

CREATE OR REPLACE FUNCTION public._pay_policy_x_resolve_pre_draft_economic_key(
  p_timesheet_id uuid DEFAULT NULL::uuid,
  p_live_source_json jsonb DEFAULT '{}'::jsonb,
  p_item_type text DEFAULT NULL::text,
  p_key_type_hint text DEFAULT NULL::text,
  p_key_value_hint text DEFAULT NULL::text,
  p_work_date date DEFAULT NULL::date
)
RETURNS TABLE(
  timesheet_id uuid,
  key_type text,
  key_value text,
  key_resolution_source text,
  key_resolution_failure_reason text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_source_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_live_source_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_live_source_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_timesheet_id uuid := p_timesheet_id;
  v_timesheet_id_text text;
  v_item_type text := UPPER(NULLIF(BTRIM(COALESCE(p_item_type, '')), ''));
  v_direct_key_type text;
  v_direct_key_value text;
  v_resolved_key_type text := NULL::text;
  v_resolved_key_value text := NULL::text;
  v_resolved_source text := NULL::text;
  v_failure_reason text := NULL::text;
  v_assert_ok boolean := false;
  v_assert_key_type text := NULL::text;
  v_assert_key_value text := NULL::text;
  v_assert_failure_reason text := NULL::text;
  v_work_date_text text := NULL::text;
  v_segment_id_text text := NULL::text;
  v_segment_key_text text := NULL::text;
  v_segment_stable_key_text text := NULL::text;
  v_ref_num_text text := NULL::text;
  v_adjustment_id_text text := NULL::text;
  v_additional_code_text text := NULL::text;
  v_expense_code_text text := NULL::text;
  v_segments_json jsonb := '[]'::jsonb;
  v_live_schedule_json jsonb := '{}'::jsonb;
  v_segment_match_found boolean := false;
  v_segment_match_date_text text := NULL::text;
  v_timesheet_start_date_text text := NULL::text;
BEGIN
  v_timesheet_id_text := NULLIF(BTRIM(COALESCE(v_source_json->>'timesheet_id', '')), '');
  IF v_timesheet_id IS NULL
     AND v_timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_timesheet_id := v_timesheet_id_text::uuid;
  END IF;

  IF v_item_type IS NULL THEN
    v_item_type := UPPER(NULLIF(BTRIM(COALESCE(
      v_source_json->>'item_type',
      v_source_json->>'line_type',
      v_source_json->>'component_type',
      v_source_json#>>'{source_basis_json,item_type}',
      ''
    )), ''));
  END IF;

  v_direct_key_type := UPPER(NULLIF(BTRIM(COALESCE(
    p_key_type_hint,
    v_source_json->>'component_key_type',
    v_source_json->>'key_type',
    v_source_json#>>'{source_basis_json,component_key_type}',
    v_source_json#>>'{source_basis_json,key_type}',
    ''
  )), ''));

  v_direct_key_value := NULLIF(BTRIM(COALESCE(
    p_key_value_hint,
    v_source_json->>'component_key_value',
    v_source_json->>'key_value',
    v_source_json#>>'{source_basis_json,component_key_value}',
    v_source_json#>>'{source_basis_json,key_value}',
    ''
  )), '');

  IF v_direct_key_type IS NOT NULL OR v_direct_key_value IS NOT NULL THEN
    SELECT
      key_check.ok,
      key_check.key_type,
      key_check.key_value,
      key_check.failure_reason
    INTO
      v_assert_ok,
      v_assert_key_type,
      v_assert_key_value,
      v_assert_failure_reason
    FROM public._pay_policy_x_assert_economic_key(
      p_timesheet_id => v_timesheet_id,
      p_key_type => v_direct_key_type,
      p_key_value => v_direct_key_value,
      p_context => 'PRE_DRAFT_RESOLVE_DIRECT_KEY',
      p_authority_scope => 'PRE_DRAFT',
      p_resolution_source => 'PRE_DRAFT_LIVE_DIRECT_KEY',
      p_required => true,
      p_source_json => v_source_json
    ) AS key_check;

    IF COALESCE(v_assert_ok, false) THEN
      v_resolved_key_type := v_assert_key_type;
      v_resolved_key_value := v_assert_key_value;
      v_resolved_source := 'PRE_DRAFT_LIVE_DIRECT_KEY';
    ELSE
      v_failure_reason := v_assert_failure_reason;
    END IF;
  END IF;

  IF v_resolved_key_type IS NULL THEN
    v_work_date_text := COALESCE(
      CASE WHEN p_work_date IS NULL THEN NULL::text ELSE p_work_date::text END,
      NULLIF(BTRIM(COALESCE(v_source_json->>'work_date', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json->>'date', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json#>>'{source_basis_json,work_date}', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json#>>'{source_basis_json,date}', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json#>>'{segment,work_date}', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json#>>'{segment,date}', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json#>>'{segment_json,work_date}', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_json#>>'{segment_json,date}', '')), '')
    );

    v_segment_id_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'segment_id',
      v_source_json#>>'{source_basis_json,segment_id}',
      v_source_json#>>'{segment,segment_id}',
      v_source_json#>>'{segment_json,segment_id}',
      ''
    )), '');

    v_segment_key_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'segment_key',
      v_source_json#>>'{source_basis_json,segment_key}',
      v_source_json#>>'{segment,segment_key}',
      v_source_json#>>'{segment_json,segment_key}',
      ''
    )), '');

    v_segment_stable_key_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'segment_stable_key',
      v_source_json#>>'{source_basis_json,segment_stable_key}',
      v_source_json#>>'{segment,segment_stable_key}',
      v_source_json#>>'{segment_json,segment_stable_key}',
      ''
    )), '');

    v_ref_num_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'ref_num',
      v_source_json#>>'{source_basis_json,ref_num}',
      v_source_json#>>'{segment,ref_num}',
      v_source_json#>>'{segment_json,ref_num}',
      ''
    )), '');

    v_adjustment_id_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'adjustment_id',
      v_source_json->>'adjustment_code',
      v_source_json#>>'{source_basis_json,adjustment_id}',
      v_source_json#>>'{source_basis_json,adjustment_code}',
      ''
    )), '');

    v_additional_code_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'additional_code',
      v_source_json#>>'{source_basis_json,additional_code}',
      ''
    )), '');

    v_expense_code_text := NULLIF(BTRIM(COALESCE(
      v_source_json->>'expense_code',
      v_source_json->>'mileage_code',
      v_source_json#>>'{source_basis_json,expense_code}',
      v_source_json#>>'{source_basis_json,mileage_code}',
      ''
    )), '');

    IF v_item_type IN ('SEGMENT_DELTA', 'SEGMENT', 'TIMESHEET_SEGMENT', 'HOURS') THEN
      IF v_work_date_text IS NOT NULL AND v_work_date_text ~ '^\d{4}-\d{2}-\d{2}$' THEN
        v_resolved_key_type := 'TS_DAY';
        v_resolved_key_value := v_work_date_text;
        v_resolved_source := 'PRE_DRAFT_LIVE_WORK_DATE';
      END IF;

      IF v_resolved_key_type IS NULL THEN
        IF jsonb_typeof(v_source_json->'segments') = 'array' THEN
          v_segments_json := v_source_json->'segments';
        ELSIF jsonb_typeof(v_source_json#>'{actual_schedule_json,segments}') = 'array' THEN
          v_segments_json := v_source_json#>'{actual_schedule_json,segments}';
        ELSIF jsonb_typeof(v_source_json#>'{schedule_json,segments}') = 'array' THEN
          v_segments_json := v_source_json#>'{schedule_json,segments}';
        ELSE
          v_segments_json := '[]'::jsonb;
        END IF;

        IF jsonb_array_length(v_segments_json) > 0 THEN
          SELECT
            NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'date', segment_choice.segment_json->>'work_date', '')), ''),
            true
          INTO
            v_segment_match_date_text,
            v_segment_match_found
          FROM jsonb_array_elements(v_segments_json) AS segment_choice(segment_json)
          WHERE segment_choice.segment_json IS NOT NULL
            AND jsonb_typeof(segment_choice.segment_json) = 'object'
            AND (
              (v_work_date_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'date', segment_choice.segment_json->>'work_date', '')), '') = v_work_date_text)
              OR (v_ref_num_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'ref_num', '')), '') = v_ref_num_text)
              OR (v_segment_id_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_id', '')), '') = v_segment_id_text)
              OR (v_segment_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_key', segment_choice.segment_json->>'segment_id', '')), '') = v_segment_key_text)
              OR (v_segment_stable_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_stable_key', segment_choice.segment_json->>'segment_id', segment_choice.segment_json->>'segment_key', '')), '') = v_segment_stable_key_text)
            )
          ORDER BY
            CASE
              WHEN v_work_date_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'date', segment_choice.segment_json->>'work_date', '')), '') = v_work_date_text THEN 0
              WHEN v_ref_num_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'ref_num', '')), '') = v_ref_num_text THEN 1
              WHEN v_segment_id_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_id', '')), '') = v_segment_id_text THEN 2
              WHEN v_segment_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_key', segment_choice.segment_json->>'segment_id', '')), '') = v_segment_key_text THEN 3
              WHEN v_segment_stable_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_stable_key', segment_choice.segment_json->>'segment_id', segment_choice.segment_json->>'segment_key', '')), '') = v_segment_stable_key_text THEN 4
              ELSE 9
            END
          LIMIT 1;

          IF COALESCE(v_segment_match_found, false)
             AND v_segment_match_date_text IS NOT NULL
             AND v_segment_match_date_text ~ '^\d{4}-\d{2}-\d{2}$' THEN
            v_resolved_key_type := 'TS_DAY';
            v_resolved_key_value := v_segment_match_date_text;
            v_resolved_source := 'PRE_DRAFT_LIVE_SEGMENT_DATE';
          ELSIF COALESCE(v_segment_match_found, false) THEN
            v_resolved_key_type := 'TS_TOTAL';
            v_resolved_key_value := 'TOTAL';
            v_resolved_source := 'PRE_DRAFT_LIVE_SEGMENT_TOTAL_FALLBACK';
          END IF;
        END IF;
      END IF;

      IF v_resolved_key_type IS NULL AND v_timesheet_id IS NOT NULL THEN
        SELECT COALESCE(latest_finance.actual_schedule_json, timesheet_row.actual_schedule_json, '{}'::jsonb)
        INTO v_live_schedule_json
        FROM public.timesheets AS timesheet_row
        LEFT JOIN LATERAL (
          SELECT finance_row.actual_schedule_json
          FROM public.timesheets_financials AS finance_row
          WHERE finance_row.timesheet_id = timesheet_row.timesheet_id
            AND finance_row.is_current = true
          ORDER BY finance_row.computed_at_utc DESC, finance_row.id DESC
          LIMIT 1
        ) AS latest_finance ON true
        WHERE timesheet_row.timesheet_id = v_timesheet_id
        LIMIT 1;

        IF jsonb_typeof(v_live_schedule_json->'segments') = 'array' THEN
          v_segments_json := v_live_schedule_json->'segments';
        ELSE
          v_segments_json := '[]'::jsonb;
        END IF;

        IF jsonb_array_length(v_segments_json) > 0 THEN
          v_segment_match_found := false;
          v_segment_match_date_text := NULL::text;

          SELECT
            NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'date', segment_choice.segment_json->>'work_date', '')), ''),
            true
          INTO
            v_segment_match_date_text,
            v_segment_match_found
          FROM jsonb_array_elements(v_segments_json) AS segment_choice(segment_json)
          WHERE segment_choice.segment_json IS NOT NULL
            AND jsonb_typeof(segment_choice.segment_json) = 'object'
            AND (
              (v_ref_num_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'ref_num', '')), '') = v_ref_num_text)
              OR (v_segment_id_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_id', '')), '') = v_segment_id_text)
              OR (v_segment_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_key', segment_choice.segment_json->>'segment_id', '')), '') = v_segment_key_text)
              OR (v_segment_stable_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_stable_key', segment_choice.segment_json->>'segment_id', segment_choice.segment_json->>'segment_key', '')), '') = v_segment_stable_key_text)
            )
          ORDER BY
            CASE
              WHEN v_ref_num_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'ref_num', '')), '') = v_ref_num_text THEN 1
              WHEN v_segment_id_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_id', '')), '') = v_segment_id_text THEN 2
              WHEN v_segment_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_key', segment_choice.segment_json->>'segment_id', '')), '') = v_segment_key_text THEN 3
              WHEN v_segment_stable_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_stable_key', segment_choice.segment_json->>'segment_id', segment_choice.segment_json->>'segment_key', '')), '') = v_segment_stable_key_text THEN 4
              ELSE 9
            END
          LIMIT 1;

          IF COALESCE(v_segment_match_found, false)
             AND v_segment_match_date_text IS NOT NULL
             AND v_segment_match_date_text ~ '^\d{4}-\d{2}-\d{2}$' THEN
            v_resolved_key_type := 'TS_DAY';
            v_resolved_key_value := v_segment_match_date_text;
            v_resolved_source := 'PRE_DRAFT_LIVE_TIMESHEET_SEGMENT_DATE';
          ELSIF COALESCE(v_segment_match_found, false) THEN
            v_resolved_key_type := 'TS_TOTAL';
            v_resolved_key_value := 'TOTAL';
            v_resolved_source := 'PRE_DRAFT_LIVE_TIMESHEET_SEGMENT_TOTAL_FALLBACK';
          END IF;
        END IF;
      END IF;

      IF v_resolved_key_type IS NULL AND v_timesheet_id IS NOT NULL THEN
        SELECT COALESCE(timesheet_row.worked_start_iso::date::text, timesheet_row.scheduled_start_iso::date::text)
        INTO v_timesheet_start_date_text
        FROM public.timesheets AS timesheet_row
        WHERE timesheet_row.timesheet_id = v_timesheet_id
        LIMIT 1;

        IF v_timesheet_start_date_text IS NOT NULL THEN
          v_resolved_key_type := 'TS_DAY';
          v_resolved_key_value := v_timesheet_start_date_text;
          v_resolved_source := 'PRE_DRAFT_LIVE_TIMESHEET_START_DATE';
        END IF;
      END IF;

      IF v_resolved_key_type IS NULL THEN
        v_resolved_key_type := 'TS_TOTAL';
        v_resolved_key_value := 'TOTAL';
        v_resolved_source := 'PRE_DRAFT_LIVE_TOTAL_FALLBACK';
      END IF;

    ELSIF v_item_type = 'ADJUSTMENT_DELTA' AND v_adjustment_id_text IS NOT NULL THEN
      v_resolved_key_type := 'ADJUSTMENT_CODE';
      v_resolved_key_value := v_adjustment_id_text;
      v_resolved_source := 'PRE_DRAFT_LIVE_ADJUSTMENT_KEY';

    ELSIF v_item_type = 'EXPENSE_DELTA' AND v_additional_code_text IS NOT NULL THEN
      v_resolved_key_type := 'ADDITIONAL_CODE';
      v_resolved_key_value := UPPER(v_additional_code_text);
      v_resolved_source := 'PRE_DRAFT_LIVE_ADDITIONAL_CODE';

    ELSIF v_item_type IN ('EXPENSE_DELTA', 'MILEAGE_DELTA') AND v_expense_code_text IS NOT NULL THEN
      v_resolved_key_type := 'EXPENSE_CODE';
      v_resolved_key_value := UPPER(v_expense_code_text);
      v_resolved_source := 'PRE_DRAFT_LIVE_EXPENSE_CODE';
    END IF;
  END IF;

  SELECT
    key_check.ok,
    key_check.key_type,
    key_check.key_value,
    key_check.failure_reason
  INTO
    v_assert_ok,
    v_assert_key_type,
    v_assert_key_value,
    v_assert_failure_reason
  FROM public._pay_policy_x_assert_economic_key(
    p_timesheet_id => v_timesheet_id,
    p_key_type => v_resolved_key_type,
    p_key_value => v_resolved_key_value,
    p_context => 'PRE_DRAFT_RESOLVE_FINAL',
    p_authority_scope => 'PRE_DRAFT',
    p_resolution_source => COALESCE(v_resolved_source, 'PRE_DRAFT_KEY_RESOLUTION_FAILED'),
    p_required => true,
    p_source_json => v_source_json
  ) AS key_check;

  IF COALESCE(v_assert_ok, false) THEN
    timesheet_id := v_timesheet_id;
    key_type := v_assert_key_type;
    key_value := v_assert_key_value;
    key_resolution_source := v_resolved_source;
    key_resolution_failure_reason := NULL::text;
  ELSE
    timesheet_id := v_timesheet_id;
    key_type := NULL::text;
    key_value := NULL::text;
    key_resolution_source := 'KEY_RESOLUTION_FAILED';
    key_resolution_failure_reason := COALESCE(v_failure_reason, v_assert_failure_reason, 'PRE_DRAFT_KEY_RESOLUTION_FAILED');
  END IF;

  RETURN NEXT;
END;
$function$;

-- =========================================================
-- Helpers (private)
-- ==========================================================


-- Normalize percent: supports 20 or 0.2 -> returns 0.2
create or replace function public._pay_pct_to_frac(p_pct numeric)
returns numeric
language plpgsql
immutable
as $$
begin
  if p_pct is null then return 0; end if;
  if p_pct > 1 then return p_pct / 100; end if;
  return p_pct;
end;
$$;

-- 1 + pct (supports 15 or 0.15 -> 1.15)
create or replace function public._pay_pct_to_mult(p_pct numeric)
returns numeric
language plpgsql
immutable
as $$
declare
  v_frac numeric;
begin
  v_frac := public._pay_pct_to_frac(p_pct);
  return 1 + coalesce(v_frac, 0);
end;
$$;

-- Monday week-start for a given date
create or replace function public._pay_week_start_monday(p_date date)
returns date
language plpgsql
immutable
as $$
declare
  v_dow int;
  v_offset int;
begin
  if p_date is null then return null; end if;
  v_dow := extract(dow from p_date)::int;      -- 0=Sun..6=Sat
  v_offset := (v_dow + 6) % 7;                 -- days since Monday
  return (p_date - v_offset);
end;
$$;

-- Umbrella VAT calc: returns {ex, vat, inc}
create or replace function public._pay_umbrella_vat_calc(
  p_ex numeric,
  p_vat_rate_pct numeric,
  p_vat_chargeable boolean
)
returns jsonb
language plpgsql
immutable
as $$
declare
  v_ex numeric := coalesce(p_ex,0);
  v_vat numeric := 0;
  v_inc numeric := 0;
  v_frac numeric := public._pay_pct_to_frac(p_vat_rate_pct);
begin
  if coalesce(p_vat_chargeable,false) then
    v_vat := round(v_ex * v_frac, 2);
    v_inc := round(v_ex + v_vat, 2);
  else
    v_vat := 0;
    v_inc := round(v_ex, 2);
  end if;

  return jsonb_build_object(
    'ex', round(v_ex,2),
    'vat', round(v_vat,2),
    'inc', round(v_inc,2)
  );
end;
$$;

-- Conversion: PAYE(ex) -> UMBRELLA (ex after ERNI, then VAT if chargeable)
create or replace function public._pay_convert_paye_to_umbrella(
  p_paye_ex numeric,
  p_erni_pct numeric,
  p_vat_rate_pct numeric,
  p_vat_chargeable boolean
)
returns jsonb
language plpgsql
immutable
as $$
declare
  v_erni_mult numeric := public._pay_pct_to_mult(p_erni_pct);
  v_ex numeric := round(coalesce(p_paye_ex,0) * v_erni_mult, 2);
begin
  return public._pay_umbrella_vat_calc(v_ex, p_vat_rate_pct, p_vat_chargeable);
end;
$$;

-- Conversion: UMBRELLA(ex) -> PAYE(ex) (reverse ERNI; VAT not applicable on PAYE)
create or replace function public._pay_convert_umbrella_to_paye_ex(
  p_umbrella_ex numeric,
  p_erni_pct numeric
)
returns numeric
language plpgsql
immutable
as $$
declare
  v_erni_mult numeric := public._pay_pct_to_mult(p_erni_pct);
  v_ex numeric := coalesce(p_umbrella_ex,0);
begin
  if v_erni_mult <= 0 then v_erni_mult := 1; end if;
  return round(v_ex / v_erni_mult, 2);
end;
$$;

-- Robust CSV line parser (handles quoted fields, commas inside quotes)
create or replace function public._pay_csv_parse_line(p_line text)
returns text[]
language plpgsql
immutable
as $$
declare
  v text := coalesce(p_line,'');
  i int := 1;
  ch text;
  in_quotes boolean := false;
  cur text := '';
  out_arr text[] := array[]::text[];
begin
  while i <= char_length(v) loop
    ch := substr(v, i, 1);

    if ch = '"' then
      -- Double quote escape inside quoted field
      if in_quotes and i < char_length(v) and substr(v, i+1, 1) = '"' then
        cur := cur || '"';
        i := i + 1;
      else
        in_quotes := not in_quotes;
      end if;

    elsif ch = ',' and not in_quotes then
      out_arr := out_arr || array[cur];
      cur := '';

    else
      cur := cur || ch;
    end if;

    i := i + 1;
  end loop;

  out_arr := out_arr || array[cur];
  return out_arr;
end;
$$;

create or replace function public._pay_csv_trim_field(p_field text)
returns text
language plpgsql
immutable
as $$
begin
  return nullif(btrim(coalesce(p_field,'')), '');
end;
$$;


DROP FUNCTION IF EXISTS public.pay_batch_cancel(uuid, uuid, text);



create or replace function public.pay_batch_cancel(
  p_pay_batch_id uuid,
  p_actor_user_id uuid,
  p_reason text,
  p_correction_request_id uuid DEFAULT NULL::uuid,
  p_work_item_id uuid DEFAULT NULL::uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now timestamptz := now();
  v_batch public.pay_batches%rowtype;
  v_evidence_json jsonb := '{}'::jsonb;
  v_result_json jsonb := '{}'::jsonb;
  v_progress_json jsonb := '{}'::jsonb;
  v_blockers jsonb := '[]'::jsonb;
  v_reason text := COALESCE(NULLIF(btrim(p_reason), ''), 'Pre-bank cancellation requested');
  v_idempotency_key text := NULL::text;
  v_correction_request_id uuid := p_correction_request_id;
  v_active_payment_item_count integer := 0;
  v_pending_work_count integer := 0;
  v_processing_work_count integer := 0;
  v_applied_work_count integer := 0;
  v_blocked_work_count integer := 0;
  v_failed_work_count integer := 0;
  v_live_signal_result jsonb := '{}'::jsonb;
begin
  if p_pay_batch_id is null then
    raise exception 'PAY_BATCH_CANCEL_PAY_BATCH_ID_REQUIRED'
      using errcode = 'P0001',
            detail = jsonb_build_object('code', 'PAY_BATCH_CANCEL_PAY_BATCH_ID_REQUIRED')::text;
  end if;

  if p_actor_user_id is null then
    raise exception 'PAY_BATCH_CANCEL_ACTOR_REQUIRED'
      using errcode = 'P0001',
            detail = jsonb_build_object('code', 'PAY_BATCH_CANCEL_ACTOR_REQUIRED')::text;
  end if;

  select public.pay_batches.*
  into v_batch
  from public.pay_batches
  where public.pay_batches.id = p_pay_batch_id
  for update;

  if not found then
    raise exception 'PAY_BATCH_CANCEL_BATCH_NOT_FOUND'
      using errcode = 'P0001',
            detail = jsonb_build_object('code', 'PAY_BATCH_CANCEL_BATCH_NOT_FOUND', 'pay_batch_id', p_pay_batch_id)::text;
  end if;

  v_evidence_json := public.pay_batch_submission_evidence(p_pay_batch_id, true);

  if COALESCE((v_evidence_json->>'has_external_provider_submission')::boolean, false)
     or COALESCE((v_evidence_json->>'has_pending_provider_outcome')::boolean, false)
     or COALESCE((v_evidence_json->>'has_unknown_provider_outcome')::boolean, false)
     or COALESCE((v_evidence_json->>'has_terminal_no_money')::boolean, false)
     or COALESCE((v_evidence_json->>'has_final_paid_or_settled')::boolean, false) then
    v_blockers := jsonb_build_array(jsonb_build_object(
      'code', 'PAY_BATCH_CANCEL_PROVIDER_EVIDENCE_PRESENT',
      'message', 'Whole-batch local cancellation is blocked because provider submission, terminal no-money, unknown outcome, pending provider state, or paid/settled evidence exists.',
      'submission_evidence', v_evidence_json
    ));

    raise exception 'PAY_BATCH_CANCEL_PROVIDER_EVIDENCE_PRESENT'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'PAY_BATCH_CANCEL_PROVIDER_EVIDENCE_PRESENT',
              'pay_batch_id', p_pay_batch_id,
              'blockers', v_blockers,
              'submission_evidence', v_evidence_json
            )::text;
  end if;

  if exists (
    select 1
    from public.banking_pay_operations as provider_operation
    where provider_operation.pay_batch_id = p_pay_batch_id
      and provider_operation.operation_type in ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
      and provider_operation.phase in ('SUBMIT_PROVIDER_TRANSFERS', 'PROVIDER_SUBMIT', 'CLAIM_PROVIDER_SUBMIT', 'EXECUTE_PROVIDER')
      and provider_operation.status in ('QUEUED', 'RUNNING', 'PROCESSING', 'CLAIMED')
    limit 1
  ) then
    raise exception 'PAY_BATCH_CANCEL_PROVIDER_SUBMISSION_IN_PROGRESS'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'PAY_BATCH_CANCEL_PROVIDER_SUBMISSION_IN_PROGRESS',
              'pay_batch_id', p_pay_batch_id
            )::text;
  end if;

  v_idempotency_key := COALESCE(
    CASE WHEN v_correction_request_id IS NULL THEN NULL ELSE 'pay-batch-cancel-existing-request:' || v_correction_request_id::text END,
    'pay-batch-cancel:' || p_pay_batch_id::text
  );

  v_result_json := public.pay_payment_cancel_not_sent_and_recalculate(
    p_pay_batch_id => p_pay_batch_id,
    p_selection_json => jsonb_build_object(
      'scope_type', 'BATCH',
      'source_context', 'pay_batch_cancel',
      'requested_action', 'PRE_PROVIDER_CANCEL_AND_RECALCULATE',
      'legacy_entry_point', true,
      'db_status_rule', 'Only existing pay_batches.status values are written; derived partial lifecycle labels remain payload-only.'
    ),
    p_actor_user_id => p_actor_user_id,
    p_reason => v_reason,
    p_idempotency_key => v_idempotency_key,
    p_confirmation_json => jsonb_build_object(
      'confirmed_pre_provider_cancel', true,
      'legacy_pay_batch_cancel_entry_point', true,
      'called_from_work_item_id', CASE WHEN p_work_item_id IS NULL THEN NULL ELSE p_work_item_id::text END
    )
  );

  v_correction_request_id := COALESCE(
    NULLIF(v_result_json->>'correction_request_id', '')::uuid,
    v_correction_request_id
  );

  if v_correction_request_id is not null then
    select jsonb_build_object(
             'total', count(*)::integer,
             'pending', count(*) filter (where work_items.status = 'PENDING')::integer,
             'processing', count(*) filter (where work_items.status = 'PROCESSING')::integer,
             'applied', count(*) filter (where work_items.status = 'APPLIED')::integer,
             'blocked', count(*) filter (where work_items.status = 'BLOCKED')::integer,
             'failed_retryable', count(*) filter (where work_items.status = 'FAILED_RETRYABLE')::integer,
             'failed_final', count(*) filter (where work_items.status = 'FAILED_FINAL')::integer
           ),
           count(*) filter (where work_items.status = 'PENDING')::integer,
           count(*) filter (where work_items.status = 'PROCESSING')::integer,
           count(*) filter (where work_items.status = 'APPLIED')::integer,
           count(*) filter (where work_items.status = 'BLOCKED')::integer,
           count(*) filter (where work_items.status in ('FAILED_RETRYABLE', 'FAILED_FINAL'))::integer
    into v_progress_json,
         v_pending_work_count,
         v_processing_work_count,
         v_applied_work_count,
         v_blocked_work_count,
         v_failed_work_count
    from public.pay_payment_correction_work_items as work_items
    where work_items.correction_request_id = v_correction_request_id;
  else
    v_progress_json := COALESCE(v_result_json->'progress', '{}'::jsonb);
  end if;

  select count(*)::integer
  into v_active_payment_item_count
  from public.pay_batch_items as active_items
  join public.pay_batch_candidates as active_candidates
    on active_candidates.id = active_items.pay_batch_candidate_id
  where active_candidates.pay_batch_id = p_pay_batch_id
    and coalesce(active_items.is_voided, false) = false
    and active_items.item_type <> 'DEBT_CREATED';

  if coalesce(v_active_payment_item_count, 0) = 0
     and coalesce(v_pending_work_count, 0) = 0
     and coalesce(v_processing_work_count, 0) = 0
     and coalesce(v_blocked_work_count, 0) = 0
     and coalesce(v_failed_work_count, 0) = 0 then
    update public.pay_batches as batch_to_cancel
    set
      status = 'CANCELLED',
      cancelled_at_utc = coalesce(batch_to_cancel.cancelled_at_utc, v_now),
      cancelled_by_user_id = coalesce(batch_to_cancel.cancelled_by_user_id, p_actor_user_id),
      cancel_reason = coalesce(batch_to_cancel.cancel_reason, v_reason),
      schedule_kind = null,
      scheduled_at_utc = null,
      scheduled_by_user_id = null,
      funding_account_ref = null,
      funds_warning_hours_json = null,
      execution_commit_state = case
        when nullif(btrim(coalesce(batch_to_cancel.execution_commit_state, '')), '') is null then 'NOT_SUBMITTED'
        else batch_to_cancel.execution_commit_state
      end
    where batch_to_cancel.id = p_pay_batch_id;
  end if;

  v_live_signal_result := public.banking_pay_batch_signal_touch(
    p_pay_batch_id := p_pay_batch_id,
    p_change_reason := 'PAY_BATCH_CANCEL',
    p_change_source := 'pay_batch_cancel',
    p_change_scope_json := jsonb_strip_nulls(jsonb_build_object(
      'correction_request_id', CASE WHEN v_correction_request_id IS NULL THEN NULL ELSE v_correction_request_id::text END,
      'legacy_entry_point', 'pay_batch_cancel',
      'progress', COALESCE(v_progress_json, '{}'::jsonb),
      'active_payment_item_count_after', COALESCE(v_active_payment_item_count, 0)
    )),
    p_touch_payment_status := true,
    p_touch_correction_progress := true,
    p_touch_alerts := false,
    p_touch_overview := true
  );

  return COALESCE(v_result_json, '{}'::jsonb) || jsonb_build_object(
    'ok', COALESCE(NULLIF(v_result_json->>'ok', '')::boolean, true),
    'pay_batch_id', p_pay_batch_id::text,
    'legacy_entry_point', 'pay_batch_cancel',
    'correction_request_id', CASE WHEN v_correction_request_id IS NULL THEN NULL ELSE v_correction_request_id::text END,
    'progress', COALESCE(v_progress_json, '{}'::jsonb),
    'active_payment_item_count_after', COALESCE(v_active_payment_item_count, 0),
    'batch_status', (select batch_status_after.status from public.pay_batches as batch_status_after where batch_status_after.id = p_pay_batch_id),
    'db_status_rule', 'CANCELLED may be written only after all payment-scope work items have applied; partial cancellation remains derived payload state only.',
    'submission_evidence', v_evidence_json,
    'live_signal', COALESCE(v_live_signal_result, '{}'::jsonb),
    'policy_x_checked', true
  );
end;
$$;





create or replace function public.pay_set_paye_net_from_sage(
  p_pay_batch_id uuid,
  p_csv_raw text,
  p_actor_user_id uuid,
  p_source_filename text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_lines text[];
  v_line text;
  v_fields text[];

  header_idx int := 0;
  i int := 0;

  works_col int := 0;
  net_col int := 0;

  works text;
  works_norm text;
  net_raw text;
  net_amt numeric;

  dup_check jsonb := '[]'::jsonb;

  v_matched jsonb := '[]'::jsonb;
  v_unknown jsonb := '[]'::jsonb;
  v_ambig jsonb := '[]'::jsonb;
  v_missing_net jsonb := '[]'::jsonb;

  v_applied_count int := 0;

  v_batch record;
  v_week_start date;
  v_batch_status_upper text := null;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := null;
  v_execution_committed_at_utc timestamptz := null;

  v_fresh jsonb := null;
  v_is_stale boolean := false;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;

  v_deleted_ded_items int := 0;
  v_deleted_ded_breakdowns int := 0;
  v_ins_overpay int := 0;
  v_ins_loan int := 0;
  v_ins_overpay_bd int := 0;
  v_ins_loan_bd int := 0;
  v_deleted_ded_reservations int := 0;
  v_ins_loan_res int := 0;
  v_upd_candidates int := 0;
  v_candidate_summaries jsonb := '[]'::jsonb;
begin
  if p_pay_batch_id is null then
    raise exception 'pay_batch_id is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  select
    pb.id,
    pb.status,
    pb.pay_date,
    pb.batch_kind_fixed,
    pb.cancelled_at_utc,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  for update;

  if v_batch.id is null then
    raise exception 'pay_batch not found';
  end if;

  if upper(btrim(coalesce(v_batch.batch_kind_fixed,''))) = 'LOANS' then
    raise exception 'PAYE_NET_NOT_APPLICABLE_FOR_LOANS_BATCH';
  end if;

  if v_batch.pay_date is null then
    raise exception 'pay_batch pay_date is required';
  end if;

  v_week_start := public._pay_week_start_monday(v_batch.pay_date);

  v_batch_status_upper := upper(btrim(coalesce(v_batch.status, '')));
  v_execution_commit_state := upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED')));
  if v_execution_commit_state not in ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') then
    v_execution_commit_state := 'NOT_SUBMITTED';
  end if;
  v_execution_commit_ref := nullif(btrim(coalesce(v_batch.execution_commit_ref, '')), '');
  v_execution_committed_at_utc := v_batch.execution_committed_at_utc;

  if v_batch.cancelled_at_utc is not null
     or v_batch_status_upper in ('CANCELLED', 'CANCELED', 'SCHEDULED', 'SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED', 'EXECUTED', 'PAID', 'SETTLED')
     or v_execution_commit_state <> 'NOT_SUBMITTED'
     or v_execution_commit_ref is not null
     or v_execution_committed_at_utc is not null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SET_PAYE_NET_SAGE',
      'code', 'PAYE_NET_MUTATION_BLOCKED_BY_LIFECYCLE',
      'message', 'pay_set_paye_net_from_sage: PAYE net cannot be changed after the payment batch has crossed the execution/cancellation lifecycle boundary',
      'pay_batch_id', p_pay_batch_id::text,
      'status', v_batch.status,
      'cancelled_at_utc', case when v_batch.cancelled_at_utc is null then null else v_batch.cancelled_at_utc::text end,
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref', v_execution_commit_ref,
      'execution_committed_at_utc', case when v_execution_committed_at_utc is null then null else v_execution_committed_at_utc::text end
    )::text;
  end if;

  v_fresh := public.pay_batch_validate_freshness(
    p_pay_batch_id => p_pay_batch_id,
    p_actor_user_id => p_actor_user_id,
    p_allow_large_full_scan => false
  );
  v_is_stale := coalesce((v_fresh->>'is_stale')::boolean, false);
  v_stale_reasons := coalesce(v_fresh->'stale_reasons', '[]'::jsonb);

  if v_is_stale = true then
    select coalesce(jsonb_agg(x.elem), '[]'::jsonb)
      into v_diff_sample
    from (
      select elem
      from jsonb_array_elements(coalesce(v_fresh->'diff','[]'::jsonb)) as elem
      limit 50
    ) x;

    raise exception '%', jsonb_build_object(
      'error', 'PAY_SET_PAYE_NET_SAGE',
      'code', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION' else 'BATCH_STALE' end,
      'message', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'pay_set_paye_net_from_sage: chunked freshness validation is required before changing PAYE net' else 'pay_set_paye_net_from_sage: batch is stale; regenerate draft before importing PAYE net' end,
      'pay_batch_id', p_pay_batch_id::text,
      'stale_reasons', v_stale_reasons,
      'diff', v_diff_sample
    )::text;
  end if;

  v_lines := regexp_split_to_array(coalesce(p_csv_raw,''), E'\\r?\\n');

  for i in 1..coalesce(array_length(v_lines,1),0) loop
    v_line := coalesce(v_lines[i],'');
    if btrim(v_line) = '' then continue; end if;

    v_fields := public._pay_csv_parse_line(v_line);

    works_col := 0;
    net_col := 0;

    for header_idx in 1..coalesce(array_length(v_fields,1),0) loop
      if lower(btrim(coalesce(v_fields[header_idx],''))) = lower('Works Number') then
        works_col := header_idx;
      end if;
      if lower(btrim(coalesce(v_fields[header_idx],''))) = lower('Net Pay') then
        net_col := header_idx;
      end if;
    end loop;

    if works_col > 0 and net_col > 0 then
      header_idx := i;
      exit;
    end if;
  end loop;

  if header_idx = 0 then
    raise exception 'SAGE_IMPORT_INVALID: header row with Works Number and Net Pay not found';
  end if;

  create temp table if not exists _tmp_sage_net (
    works_number text,
    works_norm text,
    net_amount numeric
  ) on commit drop;

  truncate table _tmp_sage_net;

  for i in (header_idx+1)..coalesce(array_length(v_lines,1),0) loop
    v_line := coalesce(v_lines[i],'');
    if btrim(v_line) = '' then continue; end if;

    v_fields := public._pay_csv_parse_line(v_line);

    works := public._pay_csv_trim_field(case when works_col <= array_length(v_fields,1) then v_fields[works_col] else null end);
    if works is null then
      continue;
    end if;

    if lower(works) = 'totals' then
      continue;
    end if;

    works_norm := upper(regexp_replace(btrim(coalesce(works,'')), '\s+', '', 'g'));
    if works_norm = '' then
      continue;
    end if;

    net_raw := public._pay_csv_trim_field(case when net_col <= array_length(v_fields,1) then v_fields[net_col] else null end);

    if net_raw is null or btrim(net_raw) = '' then
      insert into _tmp_sage_net(works_number, works_norm, net_amount)
      values (works, works_norm, null);
      continue;
    end if;

    net_raw := replace(net_raw, ',', '');
    net_raw := regexp_replace(net_raw, '[^0-9\\.-]', '', 'g');

    if net_raw is null or btrim(net_raw) = '' then
      insert into _tmp_sage_net(works_number, works_norm, net_amount)
      values (works, works_norm, null);
      continue;
    end if;

    begin
      net_amt := net_raw::numeric;
    exception when others then
      raise exception 'SAGE_IMPORT_INVALID: Net Pay not numeric for Works Number %', works;
    end;

    if net_amt < 0 then
      raise exception 'SAGE_IMPORT_INVALID: Net Pay negative for Works Number %', works;
    end if;

    insert into _tmp_sage_net(works_number, works_norm, net_amount)
    values (works, works_norm, round(net_amt,2));
  end loop;

  select coalesce(jsonb_agg(t.works_norm), '[]'::jsonb)
  into dup_check
  from (
    select sn.works_norm
    from _tmp_sage_net sn
    group by sn.works_norm
    having count(*) > 1
  ) t;

  if jsonb_array_length(dup_check) > 0 then
    raise exception 'SAGE_IMPORT_INVALID: duplicate Works Number(s) %', dup_check::text;
  end if;

  create temp table if not exists _tmp_batch_paye (
    candidate_id uuid,
    pay_batch_candidate_id uuid,
    tms_ref_norm text,
    ni_norm text
  ) on commit drop;

  truncate table _tmp_batch_paye;

  insert into _tmp_batch_paye(candidate_id, pay_batch_candidate_id, tms_ref_norm, ni_norm)
  select
    pbc.candidate_id,
    pbc.id,
    upper(regexp_replace(btrim(coalesce(pbc.candidate_tms_ref, c.tms_ref, '')), '\s+', '', 'g')) as tms_ref_norm,
    upper(regexp_replace(btrim(coalesce(c.ni_number, '')), '\s+', '', 'g')) as ni_norm
  from public.pay_batch_candidates pbc
  join public.candidates c on c.id = pbc.candidate_id
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.paye_state is not null;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'works_number', a.works_norm,
        'candidate_ids', a.candidate_ids
      )
    ),
    '[]'::jsonb
  )
  into v_ambig
  from (
    select
      sn.works_norm,
      jsonb_agg(distinct bp.candidate_id::text order by bp.candidate_id::text) as candidate_ids
    from _tmp_sage_net sn
    join _tmp_batch_paye bp
      on (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = sn.works_norm)
      or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = sn.works_norm)
    group by sn.works_norm
    having count(distinct bp.candidate_id) > 1
  ) a;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'works_number', sn.works_number,
        'works_norm', sn.works_norm
      )
    ),
    '[]'::jsonb
  )
  into v_unknown
  from _tmp_sage_net sn
  left join _tmp_batch_paye bp
    on (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = sn.works_norm)
    or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = sn.works_norm)
  where bp.candidate_id is null;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'works_number', sn.works_number,
        'works_norm', sn.works_norm,
        'candidate_id', bp.candidate_id::text,
        'pay_batch_candidate_id', bp.pay_batch_candidate_id::text
      )
    ),
    '[]'::jsonb
  )
  into v_missing_net
  from _tmp_sage_net sn
  join _tmp_batch_paye bp
    on (
      (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = sn.works_norm)
      or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = sn.works_norm)
    )
  where sn.net_amount is null
    and not exists (
      select 1
      from jsonb_array_elements(coalesce(v_ambig,'[]'::jsonb)) a
      where (a->>'works_number') = sn.works_norm
      limit 1
    );

  create temp table if not exists _tmp_sage_match (
    pay_batch_candidate_id uuid,
    net_amount numeric
  ) on commit drop;

  truncate table _tmp_sage_match;

  insert into _tmp_sage_match(pay_batch_candidate_id, net_amount)
  select
    bp.pay_batch_candidate_id,
    sn.net_amount
  from _tmp_sage_net sn
  join _tmp_batch_paye bp
    on (
      (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = sn.works_norm)
      or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = sn.works_norm)
    )
  where sn.net_amount is not null
    and not exists (
      select 1
      from jsonb_array_elements(coalesce(v_ambig,'[]'::jsonb)) a
      where (a->>'works_number') = sn.works_norm
      limit 1
    )
    and not exists (
      select 1
      from jsonb_array_elements(coalesce(v_unknown,'[]'::jsonb)) u
      where (u->>'works_norm') = sn.works_norm
      limit 1
    );

  select count(*)::int
  into v_applied_count
  from _tmp_sage_match sm;

  delete from public.pay_batch_paye_net_inputs pni
  using _tmp_sage_match sm
  where pni.pay_batch_candidate_id = sm.pay_batch_candidate_id
    and pni.source = 'SAGE_IMPORT';

  insert into public.pay_batch_paye_net_inputs(
    pay_batch_candidate_id, source, net_amount, imported_at_utc, file_name, file_hash
  )
  select
    sm.pay_batch_candidate_id,
    'SAGE_IMPORT',
    sm.net_amount,
    now(),
    p_source_filename,
    null
  from _tmp_sage_match sm;

  update public.pay_batch_candidates pbc
  set paye_state = case
    when exists (
      select 1
      from public.pay_batch_paye_net_inputs pni2
      where pni2.pay_batch_candidate_id = pbc.id
      limit 1
    ) then 'READY'
    else 'PENDING_NET'
  end
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.paye_state is not null;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'pay_batch_candidate_id', bp.pay_batch_candidate_id::text,
        'candidate_id', bp.candidate_id::text,
        'net_amount', sm.net_amount
      )
      order by bp.candidate_id::text
    ),
    '[]'::jsonb
  )
  into v_matched
  from _tmp_sage_match sm
  join _tmp_batch_paye bp
    on bp.pay_batch_candidate_id = sm.pay_batch_candidate_id;

  ---------------------------------------------------------------------------
  -- ✅ Recompute NET_DEDUCT items + net_bank_amount (PAYE candidates only)
  -- Gross-side recovery/addition items remain as created at draft time.
  ---------------------------------------------------------------------------
  create temp table if not exists _tmp_paye_scope (
    pay_batch_candidate_id uuid primary key,
    candidate_id uuid not null
  ) on commit drop;

  truncate table _tmp_paye_scope;

  insert into _tmp_paye_scope(pay_batch_candidate_id, candidate_id)
  select
    pbc3.id,
    pbc3.candidate_id
  from public.pay_batch_candidates pbc3
  where pbc3.pay_batch_id = p_pay_batch_id
    and pbc3.paye_state is not null;

  create temp table if not exists _tmp_ded_item_ids (
    id uuid primary key
  ) on commit drop;

  truncate table _tmp_ded_item_ids;

  insert into _tmp_ded_item_ids(id)
  select
    pbi_del.id
  from public.pay_batch_items pbi_del
  where pbi_del.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_del.item_type = 'LOAN_REPAYMENT';

  delete from public.pay_batch_item_breakdowns pbib_del
  using _tmp_ded_item_ids di
  where pbib_del.pay_batch_item_id = di.id;

  get diagnostics v_deleted_ded_breakdowns = row_count;

  delete from public.pay_advance_reservations par_del
  using _tmp_ded_item_ids di_res
  where par_del.pay_batch_item_id = di_res.id;

  get diagnostics v_deleted_ded_reservations = row_count;

  delete from public.pay_batch_items pbi_del2
  using _tmp_ded_item_ids di2
  where pbi_del2.id = di2.id;

  get diagnostics v_deleted_ded_items = row_count;

  update public.pay_batch_candidates pbc_aw
  set
    awaiting_net_amount = not exists (
      select 1
      from public.pay_batch_paye_net_inputs pni_aw
      where pni_aw.pay_batch_candidate_id = pbc_aw.id
      limit 1
    ),
    updated_at = now()
  where pbc_aw.id in (select s.pay_batch_candidate_id from _tmp_paye_scope s);

  with ins_loan_items as (
    insert into public.pay_batch_items (
      id,
      pay_batch_candidate_id,
      item_type,
      timesheet_id,
      segment_key,
      source_ref,
      amount_ex_vat,
      amount_vat,
      amount_inc_vat,
      repayment_week_start,
      pay_channel,
      umbrella_id,
      is_mismatch,
      is_voided,
      finance_case_id,
      reservation_id,
      paye_treatment,
      created_at,
      updated_at
    )
    with
    cand_scope as (
      select
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id,
        'PAYE'::text as pay_channel,
        null::uuid as umbrella_id,
        pbc.awaiting_net_amount,
        ni.net_amount::numeric(12,2) as paye_net_amount
      from public.pay_batch_candidates pbc
      join _tmp_paye_scope sc
        on sc.pay_batch_candidate_id = pbc.id
      left join lateral (
        select pni.net_amount
        from public.pay_batch_paye_net_inputs pni
        where pni.pay_batch_candidate_id = pbc.id
        order by pni.imported_at_utc desc
        limit 1
      ) ni on true
    ),
    cand_limits as (
      select
        cs.pay_batch_candidate_id,
        cs.candidate_id,
        cs.pay_channel,
        cs.umbrella_id,
        greatest(coalesce(cs.paye_net_amount, 0), 0)::numeric(12,2) as earnings_before_payment_advance_ex
      from cand_scope cs
      where cs.awaiting_net_amount = false
    ),
    paid_wtd as (
      select
        pbc2.candidate_id,
        round(sum(
          case
            when pbc2.net_bank_amount is not null then pbc2.net_bank_amount
            when pbc2.gross_preview is not null then pbc2.gross_preview
            else 0
          end
        ), 2)::numeric(12,2) as paid_wtd_before_ex
      from public.pay_batch_candidates pbc2
      join public.pay_batches pb2
        on pb2.id = pbc2.pay_batch_id
      where pb2.cancelled_at_utc is null
        and pb2.id <> p_pay_batch_id
        and coalesce(pb2.batch_kind_fixed, '') <> 'LOANS'
        and pb2.pay_date >= v_week_start
        and pb2.pay_date < (v_week_start + 7)
      group by pbc2.candidate_id
    ),
    cand_with_floor as (
      select
        cl.pay_batch_candidate_id,
        cl.candidate_id,
        cl.pay_channel,
        cl.umbrella_id,
        cl.earnings_before_payment_advance_ex,
        coalesce(pw.paid_wtd_before_ex, 0)::numeric(12,2) as paid_wtd_before_ex,
        coalesce(c.min_take_home_wtd, 0)::numeric(12,2) as floor_ex,
        round(
          greatest(
            least(
              cl.earnings_before_payment_advance_ex,
              (coalesce(pw.paid_wtd_before_ex, 0) + cl.earnings_before_payment_advance_ex) - coalesce(c.min_take_home_wtd, 0)
            ),
            0
          ),
          2
        )::numeric(12,2) as max_payment_advance_repayment_ex
      from cand_limits cl
      join public.candidates c
        on c.id = cl.candidate_id
      left join paid_wtd pw
        on pw.candidate_id = cl.candidate_id
      where cl.earnings_before_payment_advance_ex > 0
    ),
    payment_advances as (
      select
        pa.id as finance_case_id,
        pa.candidate_id,
        pa.outstanding_amount::numeric(12,2) as outstanding_amount,
        pa.weekly_due::numeric(12,2) as weekly_due,
        pa.start_week_start,
        pa.created_at
      from public.pay_advances pa
      where pa.case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
        and pa.payout_status = 'PAID'::public.pay_advance_payout_status_enum
        and pa.status = 'ACTIVE'::public.pay_advance_status_enum
        and pa.outstanding_amount > 0
        and pa.weekly_due is not null
        and pa.weekly_due > 0
        and (pa.start_week_start is null or pa.start_week_start <= v_week_start)
    ),
    payment_advance_repaid_wtd as (
      select
        pbc2.candidate_id,
        replace(pbi2.source_ref, 'advance:', '')::uuid as finance_case_id,
        round(coalesce(sum(-pbi2.amount_ex_vat), 0), 2)::numeric(12,2) as repaid_wtd_ex
      from public.pay_batch_items pbi2
      join public.pay_batch_candidates pbc2
        on pbc2.id = pbi2.pay_batch_candidate_id
      join public.pay_batches pb2
        on pb2.id = pbc2.pay_batch_id
      where pbi2.item_type = 'LOAN_REPAYMENT'
        and pbi2.is_voided = false
        and pbi2.source_ref ~ '^advance:[0-9a-fA-F-]{36}$'
        and pbi2.repayment_week_start = v_week_start
        and pb2.cancelled_at_utc is null
        and pb2.id <> p_pay_batch_id
        and coalesce(pb2.batch_kind_fixed, '') <> 'LOANS'
      group by
        pbc2.candidate_id,
        replace(pbi2.source_ref, 'advance:', '')::uuid
    ),
    payment_advance_due as (
      select
        cwf.pay_batch_candidate_id,
        cwf.candidate_id,
        cwf.pay_channel,
        cwf.umbrella_id,
        cwf.max_payment_advance_repayment_ex,
        pa.finance_case_id,
        pa.outstanding_amount,
        pa.weekly_due,
        pa.start_week_start,
        pa.created_at,
        least(pa.weekly_due, pa.outstanding_amount)::numeric(12,2) as due_this_week_ex,
        greatest(
          least(pa.weekly_due, pa.outstanding_amount) - coalesce(parw.repaid_wtd_ex, 0),
          0
        )::numeric(12,2) as remaining_due_ex
      from cand_with_floor cwf
      join payment_advances pa
        on pa.candidate_id = cwf.candidate_id
      left join payment_advance_repaid_wtd parw
        on parw.candidate_id = cwf.candidate_id
       and parw.finance_case_id = pa.finance_case_id
      where cwf.max_payment_advance_repayment_ex > 0
        and greatest(
          least(pa.weekly_due, pa.outstanding_amount) - coalesce(parw.repaid_wtd_ex, 0),
          0
        ) > 0
    ),
    alloc_base as (
      select
        pad.candidate_id,
        pad.finance_case_id,
        pad.remaining_due_ex,
        pad.max_payment_advance_repayment_ex,
        sum(pad.remaining_due_ex) over (
          partition by pad.candidate_id
          order by pad.start_week_start nulls first, pad.created_at, pad.finance_case_id
          rows between unbounded preceding and 1 preceding
        )::numeric(12,2) as cum_before_ex
      from payment_advance_due pad
    ),
    alloc as (
      select
        pad2.pay_batch_candidate_id,
        pad2.pay_channel,
        pad2.umbrella_id,
        pad2.finance_case_id,
        least(
          pad2.remaining_due_ex,
          greatest(pad2.max_payment_advance_repayment_ex - coalesce(ab.cum_before_ex, 0), 0)
        )::numeric(12,2) as take_ex
      from payment_advance_due pad2
      join alloc_base ab
        on ab.finance_case_id = pad2.finance_case_id
    )
    select
      gen_random_uuid() as id,
      a.pay_batch_candidate_id,
      'LOAN_REPAYMENT' as item_type,
      null::uuid as timesheet_id,
      null::text as segment_key,
      ('advance:' || a.finance_case_id::text) as source_ref,
      (-a.take_ex)::numeric(12,2) as amount_ex_vat,
      (0)::numeric(12,2) as amount_vat,
      (-a.take_ex)::numeric(12,2) as amount_inc_vat,
      v_week_start as repayment_week_start,
      a.pay_channel as pay_channel,
      a.umbrella_id as umbrella_id,
      false as is_mismatch,
      false as is_voided,
      a.finance_case_id as finance_case_id,
      null::uuid as reservation_id,
      'NET_DEDUCT'::text as paye_treatment,
      now() as created_at,
      now() as updated_at
    from alloc a
    where a.take_ex > 0
    returning
      id,
      pay_batch_candidate_id,
      finance_case_id,
      repayment_week_start,
      amount_ex_vat,
      amount_vat,
      amount_inc_vat
  ),
  ins_loan_reservations as (
    insert into public.pay_advance_reservations (
      id,
      finance_case_id,
      pay_batch_id,
      pay_batch_candidate_id,
      pay_batch_item_id,
      reserved_amount,
      repayment_week_start,
      status,
      created_at_utc,
      committed_at_utc,
      settled_at_utc,
      released_at_utc,
      released_reason,
      created_by_user_id,
      updated_by_user_id
    )
    select
      gen_random_uuid() as id,
      ili.finance_case_id,
      p_pay_batch_id,
      ili.pay_batch_candidate_id,
      ili.id as pay_batch_item_id,
      abs(ili.amount_ex_vat)::numeric(12,2) as reserved_amount,
      ili.repayment_week_start,
      'RESERVED' as status,
      now() as created_at_utc,
      null::timestamptz as committed_at_utc,
      null::timestamptz as settled_at_utc,
      null::timestamptz as released_at_utc,
      null::text as released_reason,
      p_actor_user_id as created_by_user_id,
      p_actor_user_id as updated_by_user_id
    from ins_loan_items ili
    returning id, pay_batch_item_id
  ),
  upd_loan_items as (
    update public.pay_batch_items pbi_upd
    set
      reservation_id = ilr.id,
      updated_at = now()
    from ins_loan_reservations ilr
    where pbi_upd.id = ilr.pay_batch_item_id
    returning pbi_upd.id
  )
  insert into public.pay_batch_item_breakdowns(
    pay_batch_item_id,
    line_kind,
    bucket_code,
    unit_name,
    units,
    rate,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    meta_json
  )
  select
    ili.id,
    'LOAN_REPAYMENT',
    null,
    'Payment Advance repayment',
    null::numeric,
    null::numeric,
    ili.amount_ex_vat,
    ili.amount_vat,
    ili.amount_inc_vat,
    '{}'::jsonb
  from ins_loan_items ili;

  get diagnostics v_ins_loan_bd = row_count;

  select count(*)::int
  into v_ins_loan
  from public.pay_batch_items pbi_ct2
  where pbi_ct2.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_ct2.item_type = 'LOAN_REPAYMENT'
    and pbi_ct2.is_voided = false
    and pbi_ct2.repayment_week_start = v_week_start;

  select count(*)::int
  into v_ins_loan_res
  from public.pay_advance_reservations par_ct
  join public.pay_batch_items pbi_res
    on pbi_res.id = par_ct.pay_batch_item_id
  where par_ct.pay_batch_id = p_pay_batch_id
    and pbi_res.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_res.item_type = 'LOAN_REPAYMENT'
    and pbi_res.is_voided = false
    and par_ct.status = 'RESERVED';

  update public.pay_batch_candidates pbc_sum
  set
    awaiting_net_amount = not exists (
      select 1
      from public.pay_batch_paye_net_inputs pni4
      where pni4.pay_batch_candidate_id = pbc_sum.id
      limit 1
    ),
    overpayment_recovery_taken = coalesce((
      select round(sum(-pbi_s.amount_ex_vat), 2)
      from public.pay_batch_items pbi_s
      where pbi_s.pay_batch_candidate_id = pbc_sum.id
        and pbi_s.is_voided = false
        and pbi_s.item_type = 'OVERPAYMENT_RECOVERY'
    ), 0)::numeric(12,2),
    loan_repayment_taken = coalesce((
      select round(sum(-pbi_s2.amount_ex_vat), 2)
      from public.pay_batch_items pbi_s2
      where pbi_s2.pay_batch_candidate_id = pbc_sum.id
        and pbi_s2.is_voided = false
        and pbi_s2.item_type = 'LOAN_REPAYMENT'
    ), 0)::numeric(12,2),
    net_bank_amount = case
      when not exists (
        select 1
        from public.pay_batch_paye_net_inputs pni5
        where pni5.pay_batch_candidate_id = pbc_sum.id
        limit 1
      ) then null
      else greatest(
        round(
          coalesce((
            select pni_last.net_amount
            from public.pay_batch_paye_net_inputs pni_last
            where pni_last.pay_batch_candidate_id = pbc_sum.id
            order by pni_last.imported_at_utc desc
            limit 1
          ), 0)
          +
          coalesce((
            select round(coalesce(sum(
              case
                when pbi_d.is_voided = false and coalesce(pbi_d.paye_treatment, '') = 'NET_ADD'
                  then pbi_d.amount_ex_vat
                when pbi_d.is_voided = false and coalesce(pbi_d.paye_treatment, '') = 'NET_DEDUCT'
                  then pbi_d.amount_ex_vat
                else 0
              end
            ),0),2)
            from public.pay_batch_items pbi_d
            where pbi_d.pay_batch_candidate_id = pbc_sum.id
          ), 0),
          2
        ),
        0
      )::numeric(12,2)
    end,
    updated_at = now()
  where pbc_sum.id in (select s.pay_batch_candidate_id from _tmp_paye_scope s);

  get diagnostics v_upd_candidates = row_count;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'pay_batch_candidate_id', pbc_ret.id::text,
        'candidate_id', pbc_ret.candidate_id::text,
        'paye_state', pbc_ret.paye_state,
        'awaiting_net_amount', pbc_ret.awaiting_net_amount,
        'paye_net_amount', pni_ret.net_amount,
        'overpayment_recovery', coalesce(pbc_ret.overpayment_recovery_taken, 0)::numeric(12,2),
        'manual_debt_recovery', coalesce((
          select round(sum(-pbi_md.amount_ex_vat), 2)
          from public.pay_batch_items pbi_md
          where pbi_md.pay_batch_candidate_id = pbc_ret.id
            and pbi_md.is_voided = false
            and pbi_md.item_type = 'MANUAL_DEBT_RECOVERY'
        ), 0)::numeric(12,2),
        'loan_repayment', coalesce(pbc_ret.loan_repayment_taken, 0)::numeric(12,2),
        'payment_advance_repayment', coalesce(pbc_ret.loan_repayment_taken, 0)::numeric(12,2),
        'loan_payout_net_additions', coalesce((
          select round(sum(coalesce(pbi_np.amount_ex_vat, 0)), 2)
          from public.pay_batch_items pbi_np
          where pbi_np.pay_batch_candidate_id = pbc_ret.id
            and pbi_np.is_voided = false
            and pbi_np.item_type = 'LOAN_PAYOUT'
            and coalesce(pbi_np.paye_treatment, '') = 'NET_ADD'
        ), 0)::numeric(12,2),
        'manual_credit_net_additions', coalesce((
          select round(sum(coalesce(pbi_mc.amount_ex_vat, 0)), 2)
          from public.pay_batch_items pbi_mc
          where pbi_mc.pay_batch_candidate_id = pbc_ret.id
            and pbi_mc.is_voided = false
            and pbi_mc.item_type = 'MANUAL_CREDIT_PAYOUT'
            and coalesce(pbi_mc.paye_treatment, '') = 'NET_ADD'
        ), 0)::numeric(12,2),
        'manual_debt_net_deductions', coalesce((
          select round(sum(-pbi_mdn.amount_ex_vat), 2)
          from public.pay_batch_items pbi_mdn
          where pbi_mdn.pay_batch_candidate_id = pbc_ret.id
            and pbi_mdn.is_voided = false
            and pbi_mdn.item_type = 'MANUAL_DEBT_RECOVERY'
            and coalesce(pbi_mdn.paye_treatment, '') = 'NET_DEDUCT'
        ), 0)::numeric(12,2),
        'net_additions_total', coalesce((
          select round(sum(coalesce(pbi_na.amount_ex_vat, 0)), 2)
          from public.pay_batch_items pbi_na
          where pbi_na.pay_batch_candidate_id = pbc_ret.id
            and pbi_na.is_voided = false
            and coalesce(pbi_na.paye_treatment, '') = 'NET_ADD'
        ), 0)::numeric(12,2),
        'net_deductions_total', coalesce((
          select round(sum(-pbi_nd0.amount_ex_vat), 2)
          from public.pay_batch_items pbi_nd0
          where pbi_nd0.pay_batch_candidate_id = pbc_ret.id
            and pbi_nd0.is_voided = false
            and coalesce(pbi_nd0.paye_treatment, '') = 'NET_DEDUCT'
        ), 0)::numeric(12,2),
        'net_bank_amount', pbc_ret.net_bank_amount,
        'deductions_summary', jsonb_build_object(
          'imported_paye_net', greatest(coalesce(pni_ret.net_amount, 0), 0)::numeric(12,2),
          'gross_side_overpayment_recovery', coalesce(pbc_ret.overpayment_recovery_taken, 0)::numeric(12,2),
          'gross_side_manual_debt_recovery', coalesce((
            select round(sum(-pbi_md2.amount_ex_vat), 2)
            from public.pay_batch_items pbi_md2
            where pbi_md2.pay_batch_candidate_id = pbc_ret.id
              and pbi_md2.is_voided = false
              and pbi_md2.item_type = 'MANUAL_DEBT_RECOVERY'
              and coalesce(pbi_md2.paye_treatment, '') = 'GROSS_DEDUCT'
          ), 0)::numeric(12,2),
          'payment_advance_repayment', coalesce(pbc_ret.loan_repayment_taken, 0)::numeric(12,2),
          'loan_payout_net_additions', coalesce((
            select round(sum(coalesce(pbi_np2.amount_ex_vat, 0)), 2)
            from public.pay_batch_items pbi_np2
            where pbi_np2.pay_batch_candidate_id = pbc_ret.id
              and pbi_np2.is_voided = false
              and pbi_np2.item_type = 'LOAN_PAYOUT'
              and coalesce(pbi_np2.paye_treatment, '') = 'NET_ADD'
          ), 0)::numeric(12,2),
          'manual_credit_net_additions', coalesce((
            select round(sum(coalesce(pbi_mc2.amount_ex_vat, 0)), 2)
            from public.pay_batch_items pbi_mc2
            where pbi_mc2.pay_batch_candidate_id = pbc_ret.id
              and pbi_mc2.is_voided = false
              and pbi_mc2.item_type = 'MANUAL_CREDIT_PAYOUT'
              and coalesce(pbi_mc2.paye_treatment, '') = 'NET_ADD'
          ), 0)::numeric(12,2),
          'manual_debt_net_deductions', coalesce((
            select round(sum(-pbi_mdn2.amount_ex_vat), 2)
            from public.pay_batch_items pbi_mdn2
            where pbi_mdn2.pay_batch_candidate_id = pbc_ret.id
              and pbi_mdn2.is_voided = false
              and pbi_mdn2.item_type = 'MANUAL_DEBT_RECOVERY'
              and coalesce(pbi_mdn2.paye_treatment, '') = 'NET_DEDUCT'
          ), 0)::numeric(12,2),
          'net_additions_total', coalesce((
            select round(sum(coalesce(pbi_na2.amount_ex_vat, 0)), 2)
            from public.pay_batch_items pbi_na2
            where pbi_na2.pay_batch_candidate_id = pbc_ret.id
              and pbi_na2.is_voided = false
              and coalesce(pbi_na2.paye_treatment, '') = 'NET_ADD'
          ), 0)::numeric(12,2),
          'net_deductions_total', coalesce((
            select round(sum(-pbi_nd.amount_ex_vat), 2)
            from public.pay_batch_items pbi_nd
            where pbi_nd.pay_batch_candidate_id = pbc_ret.id
              and pbi_nd.is_voided = false
              and coalesce(pbi_nd.paye_treatment, '') = 'NET_DEDUCT'
          ), 0)::numeric(12,2),
          'final_bank', pbc_ret.net_bank_amount,
          'awaiting_net_amount', pbc_ret.awaiting_net_amount,
          'paye_net_amount', pni_ret.net_amount
        )
      )
      order by pbc_ret.candidate_id::text
    ),
    '[]'::jsonb
  )
  into v_candidate_summaries
  from public.pay_batch_candidates pbc_ret
  left join lateral (
    select pni_ret_inner.net_amount
    from public.pay_batch_paye_net_inputs pni_ret_inner
    where pni_ret_inner.pay_batch_candidate_id = pbc_ret.id
    order by pni_ret_inner.imported_at_utc desc
    limit 1
  ) pni_ret on true
  where pbc_ret.id in (select s.pay_batch_candidate_id from _tmp_paye_scope s);

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'source', 'SAGE_IMPORT',
    'applied_count', v_applied_count,
    'matched', v_matched,
    'missing_net', v_missing_net,
    'unknown', v_unknown,
    'ambiguous', v_ambig,
    'candidate_summaries', v_candidate_summaries,
    'recompute', jsonb_build_object(
      'deleted_deduction_items', v_deleted_ded_items,
      'deleted_deduction_breakdowns', v_deleted_ded_breakdowns,
      'deleted_net_deduct_reservations', v_deleted_ded_reservations,
      'inserted_overpayment_items', v_ins_overpay,
      'inserted_overpayment_breakdowns', v_ins_overpay_bd,
      'inserted_loan_items', v_ins_loan,
      'inserted_loan_breakdowns', v_ins_loan_bd,
      'inserted_loan_reservations', v_ins_loan_res,
      'updated_candidates', v_upd_candidates
    )
  );
end;
$$;









create or replace function public.pay_set_paye_net_manual(
  p_pay_batch_id uuid,
  p_entries_json jsonb,
  p_actor_user_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_entries jsonb := coalesce(p_entries_json, '[]'::jsonb);

  v_dup jsonb := '[]'::jsonb;
  v_ambig jsonb := '[]'::jsonb;
  v_unmatched jsonb := '[]'::jsonb;

  v_updated_count int := 0;
  v_cleared_count int := 0;

  v_batch record;
  v_week_start date;
  v_batch_status_upper text := null;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := null;
  v_execution_committed_at_utc timestamptz := null;

  v_fresh jsonb := null;
  v_is_stale boolean := false;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;

  v_deleted_ded_items int := 0;
  v_deleted_ded_breakdowns int := 0;
  v_ins_overpay int := 0;
  v_ins_loan int := 0;
  v_ins_overpay_bd int := 0;
  v_ins_loan_bd int := 0;
  v_deleted_ded_reservations int := 0;
  v_deleted_manual_debt_breakdowns int := 0;
  v_released_manual_debt_reservations int := 0;
  v_voided_manual_debt_items int := 0;
  v_ins_manual_debt int := 0;
  v_ins_manual_debt_bd int := 0;
  v_ins_finance_reservations int := 0;
  v_upd_candidates int := 0;
  v_candidate_summaries jsonb := '[]'::jsonb;
begin
  if p_pay_batch_id is null then
    raise exception 'pay_batch_id is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if jsonb_typeof(v_entries) <> 'array' then
    raise exception 'entries must be an array';
  end if;

  select
    pb.id,
    pb.status,
    pb.pay_date,
    pb.batch_kind_fixed,
    pb.cancelled_at_utc,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  for update;

  if v_batch.id is null then
    raise exception 'pay_batch not found';
  end if;

  if upper(btrim(coalesce(v_batch.batch_kind_fixed,''))) = 'LOANS' then
    raise exception 'PAYE_NET_NOT_APPLICABLE_FOR_LOANS_BATCH';
  end if;

  if v_batch.pay_date is null then
    raise exception 'pay_batch pay_date is required';
  end if;

  v_week_start := public._pay_week_start_monday(v_batch.pay_date);

  v_batch_status_upper := upper(btrim(coalesce(v_batch.status, '')));
  v_execution_commit_state := upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED')));
  if v_execution_commit_state not in ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') then
    v_execution_commit_state := 'NOT_SUBMITTED';
  end if;
  v_execution_commit_ref := nullif(btrim(coalesce(v_batch.execution_commit_ref, '')), '');
  v_execution_committed_at_utc := v_batch.execution_committed_at_utc;

  if v_batch.cancelled_at_utc is not null
     or v_batch_status_upper in ('CANCELLED', 'CANCELED', 'SCHEDULED', 'SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED', 'EXECUTED', 'PAID', 'SETTLED')
     or v_execution_commit_state <> 'NOT_SUBMITTED'
     or v_execution_commit_ref is not null
     or v_execution_committed_at_utc is not null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SET_PAYE_NET_MANUAL',
      'code', 'PAYE_NET_MUTATION_BLOCKED_BY_LIFECYCLE',
      'message', 'pay_set_paye_net_manual: PAYE net cannot be changed after the payment batch has crossed the execution/cancellation lifecycle boundary',
      'pay_batch_id', p_pay_batch_id::text,
      'status', v_batch.status,
      'cancelled_at_utc', case when v_batch.cancelled_at_utc is null then null else v_batch.cancelled_at_utc::text end,
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref', v_execution_commit_ref,
      'execution_committed_at_utc', case when v_execution_committed_at_utc is null then null else v_execution_committed_at_utc::text end
    )::text;
  end if;

  v_fresh := public.pay_batch_validate_freshness(
    p_pay_batch_id => p_pay_batch_id,
    p_actor_user_id => p_actor_user_id,
    p_allow_large_full_scan => false
  );
  v_is_stale := coalesce((v_fresh->>'is_stale')::boolean, false);
  v_stale_reasons := coalesce(v_fresh->'stale_reasons', '[]'::jsonb);

  if v_is_stale = true then
    select coalesce(jsonb_agg(x.elem), '[]'::jsonb)
      into v_diff_sample
    from (
      select elem
      from jsonb_array_elements(coalesce(v_fresh->'diff','[]'::jsonb)) as elem
      limit 50
    ) x;

    raise exception '%', jsonb_build_object(
      'error', 'PAY_SET_PAYE_NET_MANUAL',
      'code', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION' else 'BATCH_STALE' end,
      'message', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'pay_set_paye_net_manual: chunked freshness validation is required before changing PAYE net' else 'pay_set_paye_net_manual: batch is stale; regenerate draft before setting PAYE net' end,
      'pay_batch_id', p_pay_batch_id::text,
      'stale_reasons', v_stale_reasons,
      'diff', v_diff_sample
    )::text;
  end if;

  create temp table if not exists _tmp_manual_net (
    pay_batch_candidate_id uuid,
    candidate_id uuid,
    works_raw text,
    works_norm text,
    net_amount numeric
  ) on commit drop;

  truncate table _tmp_manual_net;

  insert into _tmp_manual_net(pay_batch_candidate_id, candidate_id, works_raw, works_norm, net_amount)
  select
    nullif(e->>'pay_batch_candidate_id','')::uuid as pay_batch_candidate_id,
    nullif(e->>'candidate_id','')::uuid as candidate_id,
    nullif(btrim(e->>'tms_ref'), '') as works_raw,
    case
      when nullif(btrim(e->>'tms_ref'), '') is null then null
      else upper(regexp_replace(btrim(e->>'tms_ref'), '\s+', '', 'g'))
    end as works_norm,
    case
      when nullif(btrim(coalesce(e->>'net_amount','')), '') is null then null
      else round((nullif(btrim(coalesce(e->>'net_amount','')), '')::numeric), 2)
    end as net_amount
  from jsonb_array_elements(v_entries) e
  where e is not null and jsonb_typeof(e)='object';

  if exists (
    select 1
    from _tmp_manual_net mn
    where mn.pay_batch_candidate_id is null
      and mn.candidate_id is null
      and (mn.works_norm is null or mn.works_norm = '')
    limit 1
  ) then
    raise exception 'MANUAL_NET_INVALID: each entry must include pay_batch_candidate_id, candidate_id or tms_ref/NI (Works Number)';
  end if;

  if exists (
    select 1
    from _tmp_manual_net t
    where t.net_amount is not null
      and t.net_amount < 0
    limit 1
  ) then
    raise exception 'MANUAL_NET_INVALID: net_amount must be non-negative';
  end if;

  select coalesce(jsonb_agg(x), '[]'::jsonb)
  into v_dup
  from (
    select to_jsonb(
      case
        when mn.pay_batch_candidate_id is not null then ('PBC:' || mn.pay_batch_candidate_id::text)
        when mn.candidate_id is not null then ('CAND:' || mn.candidate_id::text)
        else ('WORKS:' || mn.works_norm)
      end
    ) as x
    from _tmp_manual_net mn
    group by
      case
        when mn.pay_batch_candidate_id is not null then ('PBC:' || mn.pay_batch_candidate_id::text)
        when mn.candidate_id is not null then ('CAND:' || mn.candidate_id::text)
        else ('WORKS:' || mn.works_norm)
      end
    having count(*) > 1
  ) d;

  if jsonb_array_length(v_dup) > 0 then
    raise exception 'MANUAL_NET_INVALID: duplicate entries %', v_dup::text;
  end if;

  create temp table if not exists _tmp_batch_paye2 (
    pay_batch_candidate_id uuid,
    candidate_id uuid,
    tms_ref_norm text,
    ni_norm text
  ) on commit drop;

  truncate table _tmp_batch_paye2;

  insert into _tmp_batch_paye2(pay_batch_candidate_id, candidate_id, tms_ref_norm, ni_norm)
  select
    pbc.id,
    pbc.candidate_id,
    upper(regexp_replace(btrim(coalesce(pbc.candidate_tms_ref, c.tms_ref, '')), '\s+', '', 'g')) as tms_ref_norm,
    upper(regexp_replace(btrim(coalesce(c.ni_number, '')), '\s+', '', 'g')) as ni_norm
  from public.pay_batch_candidates pbc
  join public.candidates c
    on c.id = pbc.candidate_id
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.paye_state is not null;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'works_number', a.works_norm,
        'candidate_ids', a.candidate_ids
      )
    ),
    '[]'::jsonb
  )
  into v_ambig
  from (
    select
      mn.works_norm,
      jsonb_agg(distinct bp.candidate_id::text order by bp.candidate_id::text) as candidate_ids
    from _tmp_manual_net mn
    join _tmp_batch_paye2 bp
      on mn.pay_batch_candidate_id is null
     and mn.candidate_id is null
     and mn.works_norm is not null
     and mn.works_norm <> ''
     and (
       (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = mn.works_norm)
       or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = mn.works_norm)
     )
    group by mn.works_norm
    having count(distinct bp.candidate_id) > 1
  ) a;

  if jsonb_array_length(v_ambig) > 0 then
    raise exception 'MANUAL_NET_INVALID: ambiguous Works Number(s) %', v_ambig::text;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'pay_batch_candidate_id', case when mn.pay_batch_candidate_id is null then null else mn.pay_batch_candidate_id::text end,
        'candidate_id', case when mn.candidate_id is null then null else mn.candidate_id::text end,
        'works_norm', mn.works_norm
      )
    ),
    '[]'::jsonb
  )
  into v_unmatched
  from _tmp_manual_net mn
  left join _tmp_batch_paye2 bp
    on (mn.pay_batch_candidate_id is not null and bp.pay_batch_candidate_id = mn.pay_batch_candidate_id)
    or (mn.pay_batch_candidate_id is null and mn.candidate_id is not null and bp.candidate_id = mn.candidate_id)
    or (
      mn.pay_batch_candidate_id is null
      and mn.candidate_id is null
      and mn.works_norm is not null
      and mn.works_norm <> ''
      and (
        (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = mn.works_norm)
        or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = mn.works_norm)
      )
    )
  where bp.pay_batch_candidate_id is null;

  if jsonb_array_length(v_unmatched) > 0 then
    raise exception 'MANUAL_NET_INVALID: entry candidate not found in pay batch PAYE candidates %', v_unmatched::text;
  end if;

  create temp table if not exists _tmp_manual_match (
    pay_batch_candidate_id uuid,
    net_amount numeric
  ) on commit drop;

  truncate table _tmp_manual_match;

  insert into _tmp_manual_match(pay_batch_candidate_id, net_amount)
  select
    bp.pay_batch_candidate_id,
    mn.net_amount
  from _tmp_manual_net mn
  join _tmp_batch_paye2 bp
    on mn.pay_batch_candidate_id is not null
   and bp.pay_batch_candidate_id = mn.pay_batch_candidate_id;

  insert into _tmp_manual_match(pay_batch_candidate_id, net_amount)
  select
    bp.pay_batch_candidate_id,
    mn.net_amount
  from _tmp_manual_net mn
  join _tmp_batch_paye2 bp
    on mn.pay_batch_candidate_id is null
   and mn.candidate_id is not null
   and bp.candidate_id = mn.candidate_id;

  insert into _tmp_manual_match(pay_batch_candidate_id, net_amount)
  select
    bp.pay_batch_candidate_id,
    mn.net_amount
  from _tmp_manual_net mn
  join _tmp_batch_paye2 bp
    on mn.pay_batch_candidate_id is null
   and mn.candidate_id is null
   and mn.works_norm is not null
   and mn.works_norm <> ''
   and (
     (bp.tms_ref_norm is not null and bp.tms_ref_norm <> '' and bp.tms_ref_norm = mn.works_norm)
     or (bp.ni_norm is not null and bp.ni_norm <> '' and bp.ni_norm = mn.works_norm)
   );

  if exists (
    select 1
    from _tmp_manual_match mm
    group by mm.pay_batch_candidate_id
    having count(*) > 1
    limit 1
  ) then
    raise exception 'MANUAL_NET_INVALID: duplicate resolved candidates in request (internal match collision)';
  end if;

  select count(*)::int
  into v_updated_count
  from _tmp_manual_match mm
  where mm.net_amount is not null;

  select count(*)::int
  into v_cleared_count
  from _tmp_manual_match mm
  where mm.net_amount is null;

  delete from public.pay_batch_paye_net_inputs pni
  using _tmp_manual_match mm
  where pni.pay_batch_candidate_id = mm.pay_batch_candidate_id
    and pni.source = 'MANUAL_ENTRY';

  insert into public.pay_batch_paye_net_inputs(
    pay_batch_candidate_id, source, net_amount, imported_at_utc, file_name, file_hash
  )
  select
    mm.pay_batch_candidate_id,
    'MANUAL_ENTRY',
    mm.net_amount,
    now(),
    null,
    null
  from _tmp_manual_match mm
  where mm.net_amount is not null;

  update public.pay_batch_candidates pbc
  set paye_state = case
    when exists (
      select 1
      from public.pay_batch_paye_net_inputs pni2
      where pni2.pay_batch_candidate_id = pbc.id
      limit 1
    ) then 'READY'
    else 'PENDING_NET'
  end
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.paye_state is not null;

  ---------------------------------------------------------------------------
  -- ✅ Recompute deductions + net_bank_amount (PAYE candidates only)
  ---------------------------------------------------------------------------
  create temp table if not exists _tmp_paye_scope (
    pay_batch_candidate_id uuid primary key,
    candidate_id uuid not null
  ) on commit drop;

  truncate table _tmp_paye_scope;

  insert into _tmp_paye_scope(pay_batch_candidate_id, candidate_id)
  select
    pbc3.id,
    pbc3.candidate_id
  from public.pay_batch_candidates pbc3
  where pbc3.pay_batch_id = p_pay_batch_id
    and pbc3.paye_state is not null;


  create temp table if not exists _tmp_recovery_templates (
    item_type text not null,
    pay_batch_candidate_id uuid not null,
    candidate_id uuid not null,
    finance_case_id uuid null,
    source_ref text null,
    pay_channel text null,
    umbrella_id uuid null,
    is_mismatch boolean null,
    paye_treatment text null,
    finance_component_id uuid null,
    frozen_component_snapshot_json jsonb null,
    frozen_component_key_type text null,
    frozen_component_key_value text null,
    frozen_component_classification public.pay_finance_component_classification_enum null,
    frozen_source_basis_json jsonb null,
    frozen_source_pay_method text null,
    frozen_target_pay_method text null,
    frozen_resolution_mode public.pay_finance_component_resolution_mode_enum null,
    frozen_resolution_payload_json jsonb null,
    frozen_resolution_result_json jsonb null,
    frozen_source_amount numeric(12,2) null,
    frozen_target_amount_ex_vat numeric(12,2) null,
    frozen_target_amount_vat numeric(12,2) null,
    frozen_target_amount_inc_vat numeric(12,2) null,
    payout_instruction_snapshot_json jsonb null,
    template_sort_at timestamptz null,
    sort_order integer not null,
    frozen_case_type text null,
    frozen_payout_status text null,
    frozen_remaining_source_amount numeric(12,2) not null,
    frozen_weekly_due_amount numeric(12,2) not null,
    frozen_next_due_week_start date null,
    minimum_earnings_threshold numeric(12,2) null,
    take_home_floor_override numeric(12,2) null,
    default_take_home_floor numeric(12,2) null
  ) on commit drop;

  truncate table _tmp_recovery_templates;

  insert into _tmp_recovery_templates (
    item_type,
    pay_batch_candidate_id,
    candidate_id,
    finance_case_id,
    source_ref,
    pay_channel,
    umbrella_id,
    is_mismatch,
    paye_treatment,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat,
    payout_instruction_snapshot_json,
    template_sort_at,
    sort_order,
    frozen_case_type,
    frozen_payout_status,
    frozen_remaining_source_amount,
    frozen_weekly_due_amount,
    frozen_next_due_week_start,
    minimum_earnings_threshold,
    take_home_floor_override,
    default_take_home_floor
  )
  select distinct on (
    pbi_rt.item_type,
    pbi_rt.pay_batch_candidate_id,
    coalesce(
      coalesce(
        pbi_rt.finance_case_id,
        case
          when pbi_rt.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi_rt.source_ref, 'advance:', '')::uuid
          else null::uuid
        end
      )::text,
      ''
    ),
    coalesce(pbi_rt.finance_component_id::text, ''),
    coalesce(pbi_rt.source_ref, '')
  )
    pbi_rt.item_type,
    pbi_rt.pay_batch_candidate_id,
    pbc_rt.candidate_id,
    coalesce(
      pbi_rt.finance_case_id,
      case
        when pbi_rt.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi_rt.source_ref, 'advance:', '')::uuid
        else null::uuid
      end
    ) as finance_case_id,
    pbi_rt.source_ref,
    pbi_rt.pay_channel,
    pbi_rt.umbrella_id,
    pbi_rt.is_mismatch,
    pbi_rt.paye_treatment,
    pbi_rt.finance_component_id,
    pbi_rt.frozen_component_snapshot_json,
    pbi_rt.frozen_component_key_type,
    pbi_rt.frozen_component_key_value,
    pbi_rt.frozen_component_classification,
    pbi_rt.frozen_source_basis_json,
    pbi_rt.frozen_source_pay_method,
    pbi_rt.frozen_target_pay_method,
    pbi_rt.frozen_resolution_mode,
    pbi_rt.frozen_resolution_payload_json,
    pbi_rt.frozen_resolution_result_json,
    round(coalesce(pbi_rt.frozen_source_amount, 0), 2)::numeric(12,2) as frozen_source_amount,
    round(coalesce(pbi_rt.frozen_target_amount_ex_vat, 0), 2)::numeric(12,2) as frozen_target_amount_ex_vat,
    round(coalesce(pbi_rt.frozen_target_amount_vat, 0), 2)::numeric(12,2) as frozen_target_amount_vat,
    round(coalesce(pbi_rt.frozen_target_amount_inc_vat, 0), 2)::numeric(12,2) as frozen_target_amount_inc_vat,
    pbi_rt.payout_instruction_snapshot_json,
    coalesce(pbi_rt.created_at, pbi_rt.updated_at, now()) as template_sort_at,
    case
      when nullif(btrim(coalesce(pbi_rt.frozen_source_basis_json->>'allocation_priority_order', pbi_rt.frozen_source_basis_json->>'sort_order', pbi_rt.frozen_resolution_payload_json->>'sort_order')), '') ~ '^-?[0-9]+$'
        then (coalesce(pbi_rt.frozen_source_basis_json->>'allocation_priority_order', pbi_rt.frozen_source_basis_json->>'sort_order', pbi_rt.frozen_resolution_payload_json->>'sort_order'))::integer
      else 2147483647
    end as sort_order,
    upper(coalesce(
      nullif(btrim(pbi_rt.frozen_source_basis_json->>'case_type'), ''),
      case pbi_rt.item_type
        when 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT'
        when 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE'
        when 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_ADJUSTMENT'
        else null
      end
    )) as frozen_case_type,
    upper(nullif(btrim(pbi_rt.frozen_source_basis_json->>'payout_status'), '')) as frozen_payout_status,
    round(greatest(
      coalesce(
        case
          when nullif(btrim(pbi_rt.frozen_component_snapshot_json->>'remaining_source_amount'), '') is not null then (pbi_rt.frozen_component_snapshot_json->>'remaining_source_amount')::numeric
          when nullif(btrim(pbi_rt.frozen_source_basis_json->>'remaining_source_amount'), '') is not null then (pbi_rt.frozen_source_basis_json->>'remaining_source_amount')::numeric
          when nullif(btrim(pbi_rt.frozen_source_basis_json->>'outstanding_amount'), '') is not null then (pbi_rt.frozen_source_basis_json->>'outstanding_amount')::numeric
          when nullif(btrim(pbi_rt.frozen_source_basis_json->>'amount'), '') is not null then abs((pbi_rt.frozen_source_basis_json->>'amount')::numeric)
          when pbi_rt.frozen_source_amount is not null then abs(pbi_rt.frozen_source_amount)
          else 0::numeric
        end,
        0::numeric
      ),
      0::numeric
    ), 2)::numeric(12,2) as frozen_remaining_source_amount,
    case
      when nullif(btrim(pbi_rt.frozen_source_basis_json->>'weekly_due'), '') is null then 0::numeric(12,2)
      else round(greatest(abs((pbi_rt.frozen_source_basis_json->>'weekly_due')::numeric), 0), 2)::numeric(12,2)
    end as frozen_weekly_due_amount,
    case
      when nullif(btrim(pbi_rt.frozen_source_basis_json->>'next_due_week_start'), '') is null then null::date
      else (pbi_rt.frozen_source_basis_json->>'next_due_week_start')::date
    end as frozen_next_due_week_start,
    case
      when nullif(btrim(pbi_rt.frozen_source_basis_json->>'minimum_earnings_threshold'), '') is null then null::numeric(12,2)
      else round(greatest((pbi_rt.frozen_source_basis_json->>'minimum_earnings_threshold')::numeric, 0), 2)::numeric(12,2)
    end as minimum_earnings_threshold,
    case
      when nullif(btrim(pbi_rt.frozen_source_basis_json->>'take_home_floor_override'), '') is null then null::numeric(12,2)
      else round(greatest((pbi_rt.frozen_source_basis_json->>'take_home_floor_override')::numeric, 0), 2)::numeric(12,2)
    end as take_home_floor_override,
    case
      when nullif(btrim(pbi_rt.frozen_source_basis_json->>'default_take_home_floor'), '') is null then null::numeric(12,2)
      else round(greatest((pbi_rt.frozen_source_basis_json->>'default_take_home_floor')::numeric, 0), 2)::numeric(12,2)
    end as default_take_home_floor
  from public.pay_batch_items pbi_rt
  join public.pay_batch_candidates pbc_rt
    on pbc_rt.id = pbi_rt.pay_batch_candidate_id
  where pbc_rt.pay_batch_id = p_pay_batch_id
    and pbi_rt.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY')
  order by
    pbi_rt.item_type,
    pbi_rt.pay_batch_candidate_id,
    coalesce(
      coalesce(
        pbi_rt.finance_case_id,
        case
          when pbi_rt.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi_rt.source_ref, 'advance:', '')::uuid
          else null::uuid
        end
      )::text,
      ''
    ),
    coalesce(pbi_rt.finance_component_id::text, ''),
    coalesce(pbi_rt.source_ref, ''),
    pbi_rt.is_voided desc,
    coalesce(pbi_rt.updated_at, pbi_rt.created_at) desc,
    pbi_rt.id desc;

  create temp table if not exists _tmp_manual_debt_item_ids (
    id uuid primary key
  ) on commit drop;

  truncate table _tmp_manual_debt_item_ids;

  insert into _tmp_manual_debt_item_ids(id)
  select
    pbi_md_del.id
  from public.pay_batch_items pbi_md_del
  where pbi_md_del.pay_batch_candidate_id in (select sc_md_del.pay_batch_candidate_id from _tmp_paye_scope sc_md_del)
    and pbi_md_del.item_type = 'MANUAL_DEBT_RECOVERY'
    and pbi_md_del.is_voided = false;

  create temp table if not exists _tmp_ded_item_ids (
    id uuid primary key
  ) on commit drop;

  truncate table _tmp_ded_item_ids;

  insert into _tmp_ded_item_ids(id)
  select
    pbi_del.id
  from public.pay_batch_items pbi_del
  where pbi_del.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_del.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT')
    and pbi_del.is_voided = false;

  delete from public.pay_batch_item_breakdowns pbib_del
  using _tmp_ded_item_ids di
  where pbib_del.pay_batch_item_id = di.id;

  get diagnostics v_deleted_ded_breakdowns = row_count;

  delete from public.pay_batch_item_breakdowns pbib_md_del
  using _tmp_manual_debt_item_ids mdi_del
  where pbib_md_del.pay_batch_item_id = mdi_del.id;

  get diagnostics v_deleted_manual_debt_breakdowns = row_count;

  update public.pay_advance_reservations par_del
  set
    status = 'RELEASED',
    released_at_utc = now(),
    released_reason = 'PAYE_NET_REPROJECTION',
    updated_by_user_id = p_actor_user_id
  where par_del.pay_batch_item_id in (select di_res.id from _tmp_ded_item_ids di_res)
    and par_del.status = 'RESERVED';

  get diagnostics v_deleted_ded_reservations = row_count;

  update public.pay_advance_reservations par_md
  set
    status = 'RELEASED',
    released_at_utc = now(),
    released_reason = 'PAYE_NET_REPROJECTION',
    updated_by_user_id = p_actor_user_id
  where par_md.pay_batch_item_id in (select mdi_res.id from _tmp_manual_debt_item_ids mdi_res)
    and par_md.status = 'RESERVED';

  get diagnostics v_released_manual_debt_reservations = row_count;

  update public.pay_batch_items pbi_d_void
  set
    is_voided = true,
    reservation_id = null,
    updated_at = now()
  where pbi_d_void.id in (select di_void.id from _tmp_ded_item_ids di_void)
    and pbi_d_void.is_voided = false;

  v_deleted_ded_items := 0;

  update public.pay_batch_items pbi_md_void
  set
    is_voided = true,
    reservation_id = null,
    updated_at = now()
  where pbi_md_void.id in (select mdi_void.id from _tmp_manual_debt_item_ids mdi_void)
    and pbi_md_void.is_voided = false;

  get diagnostics v_voided_manual_debt_items = row_count;

  update public.pay_batch_candidates pbc_aw
  set
    awaiting_net_amount = not exists (
      select 1
      from public.pay_batch_paye_net_inputs pni_aw
      where pni_aw.pay_batch_candidate_id = pbc_aw.id
      limit 1
    ),
    updated_at = now()
  where pbc_aw.id in (select s.pay_batch_candidate_id from _tmp_paye_scope s);

  with ins_overpay as (
    insert into public.pay_batch_items (
      id,
      pay_batch_candidate_id,
      item_type,
      timesheet_id,
      segment_key,
      source_ref,
      amount_ex_vat,
      amount_vat,
      amount_inc_vat,
      repayment_week_start,
      pay_channel,
      umbrella_id,
      is_mismatch,
      is_voided,
      created_at,
      updated_at,
      finance_case_id,
      reservation_id,
      paye_treatment,
      finance_component_id,
      frozen_component_snapshot_json,
      frozen_component_key_type,
      frozen_component_key_value,
      frozen_component_classification,
      frozen_source_basis_json,
      frozen_source_pay_method,
      frozen_target_pay_method,
      frozen_resolution_mode,
      frozen_resolution_payload_json,
      frozen_resolution_result_json,
      frozen_source_amount,
      frozen_target_amount_ex_vat,
      frozen_target_amount_vat,
      frozen_target_amount_inc_vat,
      payout_instruction_snapshot_json
    )
    with cand_scope as (
      select
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id,
        pbc.awaiting_net_amount,
        greatest(coalesce(ni.net_amount, 0), 0)::numeric(12,2) as paye_net_amount
      from public.pay_batch_candidates pbc
      join _tmp_paye_scope sc
        on sc.pay_batch_candidate_id = pbc.id
      left join lateral (
        select pni.net_amount
        from public.pay_batch_paye_net_inputs pni
        where pni.pay_batch_candidate_id = pbc.id
        order by pni.imported_at_utc desc
        limit 1
      ) ni on true
    ),
    case_templates as (
      select distinct on (rt.pay_batch_candidate_id, rt.finance_case_id, coalesce(rt.finance_component_id::text, ''), coalesce(rt.source_ref, ''))
        rt.*
      from _tmp_recovery_templates rt
      where rt.item_type = 'OVERPAYMENT_RECOVERY'
        and rt.finance_case_id is not null
      order by
        rt.pay_batch_candidate_id,
        rt.finance_case_id,
        coalesce(rt.finance_component_id::text, ''),
        coalesce(rt.source_ref, ''),
        rt.sort_order,
        rt.template_sort_at,
        rt.finance_component_id nulls last,
        rt.source_ref nulls last
    ),
    alloc_base as (
      select
        cs.pay_batch_candidate_id,
        ct.finance_case_id,
        ct.source_ref,
        ct.pay_channel,
        ct.umbrella_id,
        ct.is_mismatch,
        ct.paye_treatment,
        ct.finance_component_id,
        ct.frozen_component_snapshot_json,
        ct.frozen_component_key_type,
        ct.frozen_component_key_value,
        ct.frozen_component_classification,
        ct.frozen_source_basis_json,
        ct.frozen_source_pay_method,
        ct.frozen_target_pay_method,
        ct.frozen_resolution_mode,
        ct.frozen_resolution_payload_json,
        ct.frozen_resolution_result_json,
        ct.frozen_source_amount,
        ct.frozen_target_amount_ex_vat,
        ct.frozen_target_amount_vat,
        ct.frozen_target_amount_inc_vat,
        ct.payout_instruction_snapshot_json,
        ct.frozen_remaining_source_amount,
        ct.sort_order,
        ct.template_sort_at,
        cs.paye_net_amount as available_pool_ex,
        sum(ct.frozen_remaining_source_amount) over (
          partition by cs.pay_batch_candidate_id
          order by ct.sort_order, ct.template_sort_at, ct.finance_case_id, ct.finance_component_id, coalesce(ct.source_ref, '')
          rows between unbounded preceding and 1 preceding
        )::numeric(12,2) as cum_before_ex
      from cand_scope cs
      join case_templates ct
        on ct.pay_batch_candidate_id = cs.pay_batch_candidate_id
      where cs.awaiting_net_amount = false
        and ct.frozen_remaining_source_amount > 0
        and upper(coalesce(ct.frozen_case_type, 'OVERPAYMENT')) = 'OVERPAYMENT'
    ),
    alloc as (
      select
        ab.*,
        round(
          least(
            ab.frozen_remaining_source_amount,
            greatest(ab.available_pool_ex - coalesce(ab.cum_before_ex, 0), 0)
          ),
          2
        )::numeric(12,2) as take_ex
      from alloc_base ab
    )
    select
      gen_random_uuid() as id,
      a.pay_batch_candidate_id,
      'OVERPAYMENT_RECOVERY' as item_type,
      null::uuid as timesheet_id,
      null::text as segment_key,
      coalesce(a.source_ref, 'advance:' || a.finance_case_id::text) as source_ref,
      round(-a.take_ex, 2)::numeric(12,2) as amount_ex_vat,
      0::numeric(12,2) as amount_vat,
      round(-a.take_ex, 2)::numeric(12,2) as amount_inc_vat,
      v_week_start as repayment_week_start,
      coalesce(a.pay_channel, 'PAYE') as pay_channel,
      a.umbrella_id,
      coalesce(a.is_mismatch, false) as is_mismatch,
      false as is_voided,
      now() as created_at,
      now() as updated_at,
      a.finance_case_id,
      null::uuid as reservation_id,
      coalesce(a.paye_treatment, 'NET_DEDUCT') as paye_treatment,
      a.finance_component_id,
      a.frozen_component_snapshot_json,
      a.frozen_component_key_type,
      a.frozen_component_key_value,
      a.frozen_component_classification,
      a.frozen_source_basis_json,
      a.frozen_source_pay_method,
      coalesce(a.frozen_target_pay_method, coalesce(a.pay_channel, 'PAYE')) as frozen_target_pay_method,
      a.frozen_resolution_mode,
      a.frozen_resolution_payload_json,
      jsonb_strip_nulls(
        coalesce(a.frozen_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'target_amount_ex_vat', round(-a.take_ex, 2),
          'target_amount_vat', 0,
          'target_amount_inc_vat', round(-a.take_ex, 2)
        )
      ) as frozen_resolution_result_json,
      round(coalesce(a.take_ex, 0), 2)::numeric(12,2) as frozen_source_amount,
      round(-a.take_ex, 2)::numeric(12,2) as frozen_target_amount_ex_vat,
      0::numeric(12,2) as frozen_target_amount_vat,
      round(-a.take_ex, 2)::numeric(12,2) as frozen_target_amount_inc_vat,
      a.payout_instruction_snapshot_json
    from alloc a
    where a.take_ex > 0
    returning id, amount_ex_vat, amount_vat, amount_inc_vat
  )
  insert into public.pay_batch_item_breakdowns(
    pay_batch_item_id,
    line_kind,
    bucket_code,
    unit_name,
    units,
    rate,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    meta_json
  )
  select
    io.id,
    'OVERPAYMENT_RECOVERY',
    null,
    'Overpayment recovery',
    null::numeric,
    null::numeric,
    io.amount_ex_vat,
    io.amount_vat,
    io.amount_inc_vat,
    '{}'::jsonb
  from ins_overpay io;

  get diagnostics v_ins_overpay_bd = row_count;

  select count(*)::int
  into v_ins_overpay
  from public.pay_batch_items pbi_ct
  where pbi_ct.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_ct.item_type = 'OVERPAYMENT_RECOVERY'
    and pbi_ct.is_voided = false
    and pbi_ct.repayment_week_start = v_week_start;

  with ins_loan as (
    insert into public.pay_batch_items (
      id,
      pay_batch_candidate_id,
      item_type,
      timesheet_id,
      segment_key,
      source_ref,
      amount_ex_vat,
      amount_vat,
      amount_inc_vat,
      repayment_week_start,
      pay_channel,
      umbrella_id,
      is_mismatch,
      is_voided,
      created_at,
      updated_at,
      finance_case_id,
      reservation_id,
      paye_treatment,
      finance_component_id,
      frozen_component_snapshot_json,
      frozen_component_key_type,
      frozen_component_key_value,
      frozen_component_classification,
      frozen_source_basis_json,
      frozen_source_pay_method,
      frozen_target_pay_method,
      frozen_resolution_mode,
      frozen_resolution_payload_json,
      frozen_resolution_result_json,
      frozen_source_amount,
      frozen_target_amount_ex_vat,
      frozen_target_amount_vat,
      frozen_target_amount_inc_vat,
      payout_instruction_snapshot_json
    )
    with cand_scope as (
      select
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id,
        pbc.awaiting_net_amount,
        greatest(coalesce(ni.net_amount, 0), 0)::numeric(12,2) as paye_net_amount
      from public.pay_batch_candidates pbc
      join _tmp_paye_scope sc
        on sc.pay_batch_candidate_id = pbc.id
      left join lateral (
        select pni.net_amount
        from public.pay_batch_paye_net_inputs pni
        where pni.pay_batch_candidate_id = pbc.id
        order by pni.imported_at_utc desc
        limit 1
      ) ni on true
    ),
    overpay_current as (
      select
        pbi.pay_batch_candidate_id,
        round(sum(-pbi.amount_ex_vat), 2)::numeric(12,2) as overpayment_recovery_taken_ex
      from public.pay_batch_items pbi
      where pbi.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
        and pbi.is_voided = false
        and pbi.item_type = 'OVERPAYMENT_RECOVERY'
        and pbi.repayment_week_start = v_week_start
      group by pbi.pay_batch_candidate_id
    ),
    case_templates as (
      select distinct on (rt.pay_batch_candidate_id, rt.finance_case_id, coalesce(rt.finance_component_id::text, ''), coalesce(rt.source_ref, ''))
        rt.*
      from _tmp_recovery_templates rt
      where rt.item_type = 'LOAN_REPAYMENT'
        and rt.finance_case_id is not null
      order by
        rt.pay_batch_candidate_id,
        rt.finance_case_id,
        coalesce(rt.finance_component_id::text, ''),
        coalesce(rt.source_ref, ''),
        rt.sort_order,
        rt.template_sort_at,
        rt.finance_component_id nulls last,
        rt.source_ref nulls last
    ),
    loan_seed as (
      select
        cs.pay_batch_candidate_id,
        cs.candidate_id,
        ct.finance_case_id,
        ct.source_ref,
        ct.pay_channel,
        ct.umbrella_id,
        ct.is_mismatch,
        ct.paye_treatment,
        ct.finance_component_id,
        ct.frozen_component_snapshot_json,
        ct.frozen_component_key_type,
        ct.frozen_component_key_value,
        ct.frozen_component_classification,
        ct.frozen_source_basis_json,
        ct.frozen_source_pay_method,
        ct.frozen_target_pay_method,
        ct.frozen_resolution_mode,
        ct.frozen_resolution_payload_json,
        ct.frozen_resolution_result_json,
        ct.frozen_source_amount,
        ct.frozen_target_amount_ex_vat,
        ct.frozen_target_amount_vat,
        ct.frozen_target_amount_inc_vat,
        ct.payout_instruction_snapshot_json,
        ct.frozen_remaining_source_amount,
        ct.sort_order,
        ct.template_sort_at,
        round(greatest(least(coalesce(ct.frozen_weekly_due_amount, ct.frozen_remaining_source_amount, 0::numeric(12,2)), ct.frozen_remaining_source_amount), 0), 2)::numeric(12,2) as nominal_due_amount,
        ct.minimum_earnings_threshold,
        ct.take_home_floor_override,
        round(greatest(cs.paye_net_amount - coalesce(oc.overpayment_recovery_taken_ex, 0), 0), 2)::numeric(12,2) as run_earnings_headroom_ex,
        round(greatest(cs.paye_net_amount - coalesce(oc.overpayment_recovery_taken_ex, 0), 0), 2)::numeric(12,2) as run_take_home_before_ex
      from cand_scope cs
      join case_templates ct
        on ct.pay_batch_candidate_id = cs.pay_batch_candidate_id
      left join overpay_current oc
        on oc.pay_batch_candidate_id = cs.pay_batch_candidate_id
      where cs.awaiting_net_amount = false
        and ct.frozen_remaining_source_amount > 0
        and upper(coalesce(ct.frozen_case_type, 'PAYMENT_ADVANCE')) = 'PAYMENT_ADVANCE'
        and upper(coalesce(ct.frozen_payout_status, 'PAID')) = 'PAID'
        and (ct.frozen_next_due_week_start is null or ct.frozen_next_due_week_start <= v_week_start)
        and round(greatest(least(coalesce(ct.frozen_weekly_due_amount, ct.frozen_remaining_source_amount, 0::numeric(12,2)), ct.frozen_remaining_source_amount), 0), 2) > 0
    ),
    loan_inputs as (
      select
        ls.pay_batch_candidate_id,
        ls.candidate_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'sort_order', ls.sort_order,
              'finance_case_id', ls.finance_case_id::text,
              'case_type', 'PAYMENT_ADVANCE',
              'payout_status', 'PAID',
              'nominal_due_amount', ls.nominal_due_amount,
              'minimum_earnings_threshold', ls.minimum_earnings_threshold,
              'take_home_floor_override', ls.take_home_floor_override
            )
            order by ls.sort_order, ls.template_sort_at, ls.finance_case_id
          ),
          '[]'::jsonb
        ) as recovery_rows_json,
        max(ls.run_earnings_headroom_ex)::numeric(12,2) as run_earnings_headroom_ex,
        max(ls.run_take_home_before_ex)::numeric(12,2) as run_take_home_before_ex
      from loan_seed ls
      group by ls.pay_batch_candidate_id, ls.candidate_id
    ),
    loan_alloc as (
      select
        li.pay_batch_candidate_id,
        li.candidate_id,
        lra.finance_case_id,
        round(coalesce(lra.protected_recoverable_amount, 0), 2)::numeric(12,2) as take_ex
      from loan_inputs li
      cross join lateral public._pay_finance_protected_recovery_allocate(
        li.recovery_rows_json,
        li.run_earnings_headroom_ex,
        li.run_take_home_before_ex,
        null::numeric
      ) lra
    )
    select
      gen_random_uuid() as id,
      ct.pay_batch_candidate_id,
      'LOAN_REPAYMENT' as item_type,
      null::uuid as timesheet_id,
      null::text as segment_key,
      coalesce(ct.source_ref, 'advance:' || la.finance_case_id::text) as source_ref,
      round(-la.take_ex, 2)::numeric(12,2) as amount_ex_vat,
      0::numeric(12,2) as amount_vat,
      round(-la.take_ex, 2)::numeric(12,2) as amount_inc_vat,
      v_week_start as repayment_week_start,
      coalesce(ct.pay_channel, 'PAYE') as pay_channel,
      ct.umbrella_id,
      coalesce(ct.is_mismatch, false) as is_mismatch,
      false as is_voided,
      now() as created_at,
      now() as updated_at,
      la.finance_case_id,
      null::uuid as reservation_id,
      coalesce(ct.paye_treatment, 'NET_DEDUCT') as paye_treatment,
      ct.finance_component_id,
      ct.frozen_component_snapshot_json,
      ct.frozen_component_key_type,
      ct.frozen_component_key_value,
      ct.frozen_component_classification,
      ct.frozen_source_basis_json,
      ct.frozen_source_pay_method,
      coalesce(ct.frozen_target_pay_method, coalesce(ct.pay_channel, 'PAYE')) as frozen_target_pay_method,
      ct.frozen_resolution_mode,
      ct.frozen_resolution_payload_json,
      jsonb_strip_nulls(
        coalesce(ct.frozen_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'target_amount_ex_vat', round(-la.take_ex, 2),
          'target_amount_vat', 0,
          'target_amount_inc_vat', round(-la.take_ex, 2)
        )
      ) as frozen_resolution_result_json,
      round(coalesce(la.take_ex, 0), 2)::numeric(12,2) as frozen_source_amount,
      round(-la.take_ex, 2)::numeric(12,2) as frozen_target_amount_ex_vat,
      0::numeric(12,2) as frozen_target_amount_vat,
      round(-la.take_ex, 2)::numeric(12,2) as frozen_target_amount_inc_vat,
      ct.payout_instruction_snapshot_json
    from loan_alloc la
    join case_templates ct
      on ct.pay_batch_candidate_id = la.pay_batch_candidate_id
     and ct.finance_case_id = la.finance_case_id
    where round(coalesce(la.take_ex, 0), 2) > 0
    returning id, amount_ex_vat, amount_vat, amount_inc_vat
  )
  insert into public.pay_batch_item_breakdowns(
    pay_batch_item_id,
    line_kind,
    bucket_code,
    unit_name,
    units,
    rate,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    meta_json
  )
  select
    il.id,
    'LOAN_REPAYMENT',
    null,
    'Loan repayment',
    null::numeric,
    null::numeric,
    il.amount_ex_vat,
    il.amount_vat,
    il.amount_inc_vat,
    '{}'::jsonb
  from ins_loan il;

  get diagnostics v_ins_loan_bd = row_count;

  select count(*)::int
  into v_ins_loan
  from public.pay_batch_items pbi_ct2
  where pbi_ct2.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_ct2.item_type = 'LOAN_REPAYMENT'
    and pbi_ct2.is_voided = false
    and pbi_ct2.repayment_week_start = v_week_start;

  with manual_debt_scope as (
    select
      pbc_md.id as pay_batch_candidate_id,
      pbc_md.candidate_id,
      round(greatest(coalesce(pbc_md.gross_preview, 0), 0), 2)::numeric(12,2) as run_earnings_headroom_ex,
      round(
        greatest(
          coalesce(pni_md.net_amount, 0)
          - coalesce((
              select round(sum(-pbi_ov.amount_ex_vat), 2)
              from public.pay_batch_items pbi_ov
              where pbi_ov.pay_batch_candidate_id = pbc_md.id
                and pbi_ov.is_voided = false
                and pbi_ov.item_type = 'OVERPAYMENT_RECOVERY'
                and pbi_ov.repayment_week_start = v_week_start
            ), 0)
          - coalesce((
              select round(sum(-pbi_ln.amount_ex_vat), 2)
              from public.pay_batch_items pbi_ln
              where pbi_ln.pay_batch_candidate_id = pbc_md.id
                and pbi_ln.is_voided = false
                and pbi_ln.item_type = 'LOAN_REPAYMENT'
                and pbi_ln.repayment_week_start = v_week_start
            ), 0),
          0
        ),
        2
      )::numeric(12,2) as run_take_home_before_ex,
      round(greatest(coalesce((
        select max(rt.default_take_home_floor)
        from _tmp_recovery_templates rt
        where rt.pay_batch_candidate_id = pbc_md.id
          and rt.item_type = 'MANUAL_DEBT_RECOVERY'
      ), 0), 0), 2)::numeric(12,2) as default_take_home_floor
    from public.pay_batch_candidates pbc_md
    join _tmp_paye_scope sc_md
      on sc_md.pay_batch_candidate_id = pbc_md.id
    left join lateral (
      select pni_md_inner.net_amount
      from public.pay_batch_paye_net_inputs pni_md_inner
      where pni_md_inner.pay_batch_candidate_id = pbc_md.id
      order by pni_md_inner.imported_at_utc desc
      limit 1
    ) pni_md on true
    where pbc_md.awaiting_net_amount = false
  ),
  manual_debt_case_templates as (
    select distinct on (rt.pay_batch_candidate_id, rt.finance_case_id, coalesce(rt.finance_component_id::text, ''), coalesce(rt.source_ref, ''))
      rt.*
    from _tmp_recovery_templates rt
    where rt.item_type = 'MANUAL_DEBT_RECOVERY'
      and rt.finance_case_id is not null
    order by
      rt.pay_batch_candidate_id,
      rt.finance_case_id,
      coalesce(rt.finance_component_id::text, ''),
      coalesce(rt.source_ref, ''),
      rt.sort_order,
      rt.template_sort_at,
      rt.finance_component_id nulls last,
      rt.source_ref nulls last
  ),
  manual_debt_template_values as (
    select
      mds.pay_batch_candidate_id,
      mds.candidate_id,
      mdt.finance_case_id,
      mdt.template_sort_at,
      mds.run_earnings_headroom_ex,
      mds.run_take_home_before_ex,
      nullif(mds.default_take_home_floor, 0)::numeric(12,2) as default_take_home_floor,
      upper(coalesce(mdt.frozen_case_type, 'MANUAL_DEBT_ADJUSTMENT')) as frozen_case_type,
      mdt.frozen_next_due_week_start,
      mdt.minimum_earnings_threshold,
      mdt.take_home_floor_override,
      mdt.frozen_weekly_due_amount,
      mdt.frozen_remaining_source_amount,
      mdt.sort_order,
      sched_md.scheduled_due_amount,
      mdt.source_ref,
      mdt.pay_channel,
      mdt.umbrella_id,
      mdt.is_mismatch,
      mdt.paye_treatment,
      mdt.finance_component_id,
      mdt.frozen_component_snapshot_json,
      mdt.frozen_component_key_type,
      mdt.frozen_component_key_value,
      mdt.frozen_component_classification,
      mdt.frozen_source_basis_json,
      mdt.frozen_source_pay_method,
      mdt.frozen_target_pay_method,
      mdt.frozen_resolution_mode,
      mdt.frozen_resolution_payload_json,
      mdt.frozen_resolution_result_json,
      mdt.frozen_source_amount,
      mdt.frozen_target_amount_ex_vat,
      mdt.frozen_target_amount_vat,
      mdt.frozen_target_amount_inc_vat,
      mdt.payout_instruction_snapshot_json
    from manual_debt_scope mds
    join manual_debt_case_templates mdt
      on mdt.pay_batch_candidate_id = mds.pay_batch_candidate_id
    left join lateral (
      select
        round(greatest(abs((sched_item.value->>'amount')::numeric), 0), 2)::numeric(12,2) as scheduled_due_amount
      from jsonb_array_elements(
        case
          when jsonb_typeof(coalesce(mdt.frozen_source_basis_json->'schedule_json', '[]'::jsonb)) = 'array'
            then coalesce(mdt.frozen_source_basis_json->'schedule_json', '[]'::jsonb)
          else '[]'::jsonb
        end
      ) as sched_item(value)
      where nullif(btrim(sched_item.value->>'week_start'), '') is not null
        and (sched_item.value->>'week_start')::date = v_week_start
      limit 1
    ) sched_md on true
  ),
  manual_debt_seed as (
    select
      mdtv.pay_batch_candidate_id,
      mdtv.candidate_id,
      mdtv.finance_case_id,
      mdtv.template_sort_at,
      mdtv.sort_order,
      round(
        greatest(
          least(
            coalesce(mdtv.scheduled_due_amount, mdtv.frozen_weekly_due_amount, 0::numeric(12,2)),
            mdtv.frozen_remaining_source_amount
          ),
          0
        ),
        2
      )::numeric(12,2) as nominal_due_amount,
      mdtv.minimum_earnings_threshold,
      mdtv.take_home_floor_override,
      mdtv.run_earnings_headroom_ex,
      mdtv.run_take_home_before_ex,
      mdtv.default_take_home_floor
    from manual_debt_template_values mdtv
    where mdtv.frozen_case_type = 'MANUAL_DEBT_ADJUSTMENT'
      and mdtv.frozen_remaining_source_amount > 0
      and (mdtv.frozen_next_due_week_start is null or mdtv.frozen_next_due_week_start <= v_week_start)
      and round(
        greatest(
          least(
            coalesce(mdtv.scheduled_due_amount, mdtv.frozen_weekly_due_amount, 0::numeric(12,2)),
            mdtv.frozen_remaining_source_amount
          ),
          0
        ),
        2
      ) > 0
  ),
  manual_debt_inputs as (
    select
      mds.candidate_id,
      mds.pay_batch_candidate_id,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'sort_order', mds.sort_order,
            'finance_case_id', mds.finance_case_id::text,
            'case_type', 'MANUAL_DEBT_ADJUSTMENT',
            'payout_status', null,
            'nominal_due_amount', mds.nominal_due_amount,
            'minimum_earnings_threshold', mds.minimum_earnings_threshold,
            'take_home_floor_override', mds.take_home_floor_override
          )
          order by mds.sort_order, mds.template_sort_at, mds.finance_case_id
        ),
        '[]'::jsonb
      ) as recovery_rows_json,
      max(mds.run_earnings_headroom_ex)::numeric(12,2) as run_earnings_headroom_ex,
      max(mds.run_take_home_before_ex)::numeric(12,2) as run_take_home_before_ex,
      nullif(max(mds.default_take_home_floor), 0)::numeric(12,2) as default_take_home_floor
    from manual_debt_seed mds
    group by mds.candidate_id, mds.pay_batch_candidate_id
  ),
  manual_debt_alloc as (
    select
      mdi.pay_batch_candidate_id,
      mdi.candidate_id,
      mdra.finance_case_id,
      round(coalesce(mdra.protected_recoverable_amount, 0), 2)::numeric(12,2) as take_ex
    from manual_debt_inputs mdi
    cross join lateral public._pay_finance_protected_recovery_allocate(
      mdi.recovery_rows_json,
      mdi.run_earnings_headroom_ex,
      mdi.run_take_home_before_ex,
      mdi.default_take_home_floor
    ) mdra
  ),
  ins_manual_debt as (
    insert into public.pay_batch_items (
      id,
      pay_batch_candidate_id,
      item_type,
      timesheet_id,
      segment_key,
      source_ref,
      amount_ex_vat,
      amount_vat,
      amount_inc_vat,
      repayment_week_start,
      pay_channel,
      umbrella_id,
      is_mismatch,
      is_voided,
      created_at,
      updated_at,
      finance_case_id,
      reservation_id,
      paye_treatment,
      finance_component_id,
      frozen_component_snapshot_json,
      frozen_component_key_type,
      frozen_component_key_value,
      frozen_component_classification,
      frozen_source_basis_json,
      frozen_source_pay_method,
      frozen_target_pay_method,
      frozen_resolution_mode,
      frozen_resolution_payload_json,
      frozen_resolution_result_json,
      frozen_source_amount,
      frozen_target_amount_ex_vat,
      frozen_target_amount_vat,
      frozen_target_amount_inc_vat,
      payout_instruction_snapshot_json
    )
    select
      gen_random_uuid() as id,
      mdt.pay_batch_candidate_id,
      'MANUAL_DEBT_RECOVERY' as item_type,
      null::uuid as timesheet_id,
      null::text as segment_key,
      coalesce(mdt.source_ref, 'advance:' || mda.finance_case_id::text) as source_ref,
      round(-mda.take_ex, 2)::numeric(12,2) as amount_ex_vat,
      0::numeric(12,2) as amount_vat,
      round(-mda.take_ex, 2)::numeric(12,2) as amount_inc_vat,
      v_week_start as repayment_week_start,
      coalesce(mdt.pay_channel, 'PAYE') as pay_channel,
      mdt.umbrella_id,
      coalesce(mdt.is_mismatch, false) as is_mismatch,
      false as is_voided,
      now() as created_at,
      now() as updated_at,
      mda.finance_case_id,
      null::uuid as reservation_id,
      coalesce(mdt.paye_treatment, 'NET_DEDUCT') as paye_treatment,
      mdt.finance_component_id,
      mdt.frozen_component_snapshot_json,
      mdt.frozen_component_key_type,
      mdt.frozen_component_key_value,
      mdt.frozen_component_classification,
      mdt.frozen_source_basis_json,
      mdt.frozen_source_pay_method,
      coalesce(mdt.frozen_target_pay_method, coalesce(mdt.pay_channel, 'PAYE')) as frozen_target_pay_method,
      mdt.frozen_resolution_mode,
      mdt.frozen_resolution_payload_json,
      jsonb_strip_nulls(
        coalesce(mdt.frozen_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'target_amount_ex_vat', round(-mda.take_ex, 2),
          'target_amount_vat', 0,
          'target_amount_inc_vat', round(-mda.take_ex, 2)
        )
      ) as frozen_resolution_result_json,
      round(coalesce(mda.take_ex, 0), 2)::numeric(12,2) as frozen_source_amount,
      round(-mda.take_ex, 2)::numeric(12,2) as frozen_target_amount_ex_vat,
      0::numeric(12,2) as frozen_target_amount_vat,
      round(-mda.take_ex, 2)::numeric(12,2) as frozen_target_amount_inc_vat,
      mdt.payout_instruction_snapshot_json
    from manual_debt_alloc mda
    join manual_debt_case_templates mdt
      on mdt.pay_batch_candidate_id = mda.pay_batch_candidate_id
     and mdt.finance_case_id = mda.finance_case_id
    where round(coalesce(mda.take_ex, 0), 2) > 0
    returning id, amount_ex_vat, amount_vat, amount_inc_vat
  )
  insert into public.pay_batch_item_breakdowns(
    pay_batch_item_id,
    line_kind,
    bucket_code,
    unit_name,
    units,
    rate,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    meta_json
  )
  select
    imd.id,
    'MANUAL_DEBT_RECOVERY',
    null,
    'Manual debt recovery',
    null::numeric,
    null::numeric,
    imd.amount_ex_vat,
    imd.amount_vat,
    imd.amount_inc_vat,
    '{}'::jsonb
  from ins_manual_debt imd;

  get diagnostics v_ins_manual_debt_bd = row_count;

  select count(*)::int
  into v_ins_manual_debt
  from public.pay_batch_items pbi_ct3
  where pbi_ct3.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
    and pbi_ct3.item_type = 'MANUAL_DEBT_RECOVERY'
    and pbi_ct3.is_voided = false
    and pbi_ct3.repayment_week_start = v_week_start;

  with ins_finance_reservations as (
    insert into public.pay_advance_reservations (
      id,
      finance_case_id,
      pay_batch_id,
      pay_batch_candidate_id,
      pay_batch_item_id,
      reserved_amount,
      repayment_week_start,
      status,
      created_at_utc,
      committed_at_utc,
      settled_at_utc,
      released_at_utc,
      released_reason,
      created_by_user_id,
      updated_by_user_id,
      finance_component_id,
      frozen_component_snapshot_json,
      frozen_component_key_type,
      frozen_component_key_value,
      frozen_component_classification,
      frozen_source_basis_json,
      frozen_source_pay_method,
      frozen_target_pay_method,
      frozen_resolution_mode,
      frozen_resolution_payload_json,
      frozen_resolution_result_json,
      reserved_source_amount,
      frozen_rounded_target_amount
    )
    select
      gen_random_uuid() as id,
      pbi_fin.finance_case_id,
      p_pay_batch_id as pay_batch_id,
      pbi_fin.pay_batch_candidate_id,
      pbi_fin.id as pay_batch_item_id,
      round(abs(coalesce(pbi_fin.amount_ex_vat, 0)), 2)::numeric(12,2) as reserved_amount,
      pbi_fin.repayment_week_start,
      'RESERVED' as status,
      now() as created_at_utc,
      null::timestamptz as committed_at_utc,
      null::timestamptz as settled_at_utc,
      null::timestamptz as released_at_utc,
      null::text as released_reason,
      p_actor_user_id as created_by_user_id,
      p_actor_user_id as updated_by_user_id,
      pbi_fin.finance_component_id,
      pbi_fin.frozen_component_snapshot_json,
      pbi_fin.frozen_component_key_type,
      pbi_fin.frozen_component_key_value,
      pbi_fin.frozen_component_classification,
      pbi_fin.frozen_source_basis_json,
      pbi_fin.frozen_source_pay_method,
      pbi_fin.frozen_target_pay_method,
      pbi_fin.frozen_resolution_mode,
      pbi_fin.frozen_resolution_payload_json,
      pbi_fin.frozen_resolution_result_json,
      round(abs(coalesce(pbi_fin.frozen_source_amount, pbi_fin.amount_ex_vat, 0)), 2)::numeric(12,2) as reserved_source_amount,
      round(abs(coalesce(pbi_fin.frozen_target_amount_ex_vat, pbi_fin.amount_ex_vat, 0)), 2)::numeric(12,2) as frozen_rounded_target_amount
    from public.pay_batch_items pbi_fin
    where pbi_fin.pay_batch_candidate_id in (select s.pay_batch_candidate_id from _tmp_paye_scope s)
      and pbi_fin.is_voided = false
      and pbi_fin.finance_case_id is not null
      and pbi_fin.reservation_id is null
      and pbi_fin.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY')
    returning id, pay_batch_item_id
  ),
  upd_finance_items as (
    update public.pay_batch_items pbi_upd
    set
      reservation_id = ifr.id,
      updated_at = now()
    from ins_finance_reservations ifr
    where pbi_upd.id = ifr.pay_batch_item_id
    returning pbi_upd.id
  )
  select count(*)::int
  into v_ins_finance_reservations
  from upd_finance_items;
  update public.pay_batch_candidates pbc_sum
  set
    awaiting_net_amount = not exists (
      select 1
      from public.pay_batch_paye_net_inputs pni4
      where pni4.pay_batch_candidate_id = pbc_sum.id
      limit 1
    ),
    overpayment_recovery_taken = coalesce((
      select round(sum(-pbi_s.amount_ex_vat), 2)
      from public.pay_batch_items pbi_s
      where pbi_s.pay_batch_candidate_id = pbc_sum.id
        and pbi_s.is_voided = false
        and pbi_s.item_type = 'OVERPAYMENT_RECOVERY'
    ), 0)::numeric(12,2),
    loan_repayment_taken = coalesce((
      select round(sum(-pbi_s2.amount_ex_vat), 2)
      from public.pay_batch_items pbi_s2
      where pbi_s2.pay_batch_candidate_id = pbc_sum.id
        and pbi_s2.is_voided = false
        and pbi_s2.item_type = 'LOAN_REPAYMENT'
    ), 0)::numeric(12,2),
    net_bank_amount = case
      when not exists (
        select 1
        from public.pay_batch_paye_net_inputs pni5
        where pni5.pay_batch_candidate_id = pbc_sum.id
        limit 1
      ) then null
      else greatest(
        round(
          coalesce((
            select pni_last.net_amount
            from public.pay_batch_paye_net_inputs pni_last
            where pni_last.pay_batch_candidate_id = pbc_sum.id
            order by pni_last.imported_at_utc desc
            limit 1
          ), 0)
          +
          coalesce((
            select round(coalesce(sum(
              case
                when pbi_d.is_voided = false and coalesce(pbi_d.paye_treatment, '') = 'NET_ADD'
                  then pbi_d.amount_ex_vat
                when pbi_d.is_voided = false and coalesce(pbi_d.paye_treatment, '') = 'NET_DEDUCT'
                  then pbi_d.amount_ex_vat
                else 0
              end
            ),0),2)
            from public.pay_batch_items pbi_d
            where pbi_d.pay_batch_candidate_id = pbc_sum.id
          ), 0),
          2
        ),
        0
      )::numeric(12,2)
    end,
    updated_at = now()
  where pbc_sum.id in (select s.pay_batch_candidate_id from _tmp_paye_scope s);

  get diagnostics v_upd_candidates = row_count;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'pay_batch_candidate_id', pbc_ret.id::text,
        'candidate_id', pbc_ret.candidate_id::text,
        'paye_state', pbc_ret.paye_state,
        'awaiting_net_amount', pbc_ret.awaiting_net_amount,
        'paye_net_amount', pni_ret.net_amount,
        'overpayment_recovery_taken', coalesce(pbc_ret.overpayment_recovery_taken, 0)::numeric(12,2),
        'loan_repayment_taken', coalesce(pbc_ret.loan_repayment_taken, 0)::numeric(12,2),
        'loan_payout_net_additions', coalesce((
          select round(sum(coalesce(pbi_np.amount_ex_vat, 0)), 2)
          from public.pay_batch_items pbi_np
          where pbi_np.pay_batch_candidate_id = pbc_ret.id
            and pbi_np.is_voided = false
            and pbi_np.item_type = 'LOAN_PAYOUT'
            and coalesce(pbi_np.paye_treatment, '') = 'NET_ADD'
        ), 0)::numeric(12,2),
        'manual_credit_net_additions', coalesce((
          select round(sum(coalesce(pbi_mc.amount_ex_vat, 0)), 2)
          from public.pay_batch_items pbi_mc
          where pbi_mc.pay_batch_candidate_id = pbc_ret.id
            and pbi_mc.is_voided = false
            and pbi_mc.item_type = 'MANUAL_CREDIT_PAYOUT'
            and coalesce(pbi_mc.paye_treatment, '') = 'NET_ADD'
        ), 0)::numeric(12,2),
        'manual_debt_net_deductions', coalesce((
          select round(sum(-pbi_mdn.amount_ex_vat), 2)
          from public.pay_batch_items pbi_mdn
          where pbi_mdn.pay_batch_candidate_id = pbc_ret.id
            and pbi_mdn.is_voided = false
            and pbi_mdn.item_type = 'MANUAL_DEBT_RECOVERY'
            and coalesce(pbi_mdn.paye_treatment, '') = 'NET_DEDUCT'
        ), 0)::numeric(12,2),
        'net_additions_total', coalesce((
          select round(sum(coalesce(pbi_na.amount_ex_vat, 0)), 2)
          from public.pay_batch_items pbi_na
          where pbi_na.pay_batch_candidate_id = pbc_ret.id
            and pbi_na.is_voided = false
            and coalesce(pbi_na.paye_treatment, '') = 'NET_ADD'
        ), 0)::numeric(12,2),
        'net_deductions_total', coalesce((
          select round(sum(-pbi_nd0.amount_ex_vat), 2)
          from public.pay_batch_items pbi_nd0
          where pbi_nd0.pay_batch_candidate_id = pbc_ret.id
            and pbi_nd0.is_voided = false
            and coalesce(pbi_nd0.paye_treatment, '') = 'NET_DEDUCT'
        ), 0)::numeric(12,2),
        'net_bank_amount', pbc_ret.net_bank_amount,
        'deductions_summary', jsonb_build_object(
          'gross_positive', greatest(coalesce(pni_ret.net_amount, 0), 0)::numeric(12,2),
          'overpayment_recovery', coalesce(pbc_ret.overpayment_recovery_taken, 0)::numeric(12,2),
          'loan_repayment', coalesce(pbc_ret.loan_repayment_taken, 0)::numeric(12,2),
          'loan_payout_net_additions', coalesce((
            select round(sum(coalesce(pbi_np2.amount_ex_vat, 0)), 2)
            from public.pay_batch_items pbi_np2
            where pbi_np2.pay_batch_candidate_id = pbc_ret.id
              and pbi_np2.is_voided = false
              and pbi_np2.item_type = 'LOAN_PAYOUT'
              and coalesce(pbi_np2.paye_treatment, '') = 'NET_ADD'
          ), 0)::numeric(12,2),
          'manual_credit_net_additions', coalesce((
            select round(sum(coalesce(pbi_mc2.amount_ex_vat, 0)), 2)
            from public.pay_batch_items pbi_mc2
            where pbi_mc2.pay_batch_candidate_id = pbc_ret.id
              and pbi_mc2.is_voided = false
              and pbi_mc2.item_type = 'MANUAL_CREDIT_PAYOUT'
              and coalesce(pbi_mc2.paye_treatment, '') = 'NET_ADD'
          ), 0)::numeric(12,2),
          'manual_debt_net_deductions', coalesce((
            select round(sum(-pbi_mdn2.amount_ex_vat), 2)
            from public.pay_batch_items pbi_mdn2
            where pbi_mdn2.pay_batch_candidate_id = pbc_ret.id
              and pbi_mdn2.is_voided = false
              and pbi_mdn2.item_type = 'MANUAL_DEBT_RECOVERY'
              and coalesce(pbi_mdn2.paye_treatment, '') = 'NET_DEDUCT'
          ), 0)::numeric(12,2),
          'net_additions_total', coalesce((
            select round(sum(coalesce(pbi_na2.amount_ex_vat, 0)), 2)
            from public.pay_batch_items pbi_na2
            where pbi_na2.pay_batch_candidate_id = pbc_ret.id
              and pbi_na2.is_voided = false
              and coalesce(pbi_na2.paye_treatment, '') = 'NET_ADD'
          ), 0)::numeric(12,2),
          'net_deductions_total', coalesce((
            select round(sum(-pbi_nd.amount_ex_vat), 2)
            from public.pay_batch_items pbi_nd
            where pbi_nd.pay_batch_candidate_id = pbc_ret.id
              and pbi_nd.is_voided = false
              and coalesce(pbi_nd.paye_treatment, '') = 'NET_DEDUCT'
          ), 0)::numeric(12,2),
          'final_payable', pbc_ret.net_bank_amount,
          'awaiting_net_amount', pbc_ret.awaiting_net_amount,
          'paye_net_amount', pni_ret.net_amount
        )
      )
      order by pbc_ret.candidate_id::text
    ),
    '[]'::jsonb
  )
  into v_candidate_summaries
  from public.pay_batch_candidates pbc_ret
  left join lateral (
    select pni_ret_inner.net_amount
    from public.pay_batch_paye_net_inputs pni_ret_inner
    where pni_ret_inner.pay_batch_candidate_id = pbc_ret.id
    order by pni_ret_inner.imported_at_utc desc
    limit 1
  ) pni_ret on true
  where pbc_ret.id in (select s.pay_batch_candidate_id from _tmp_paye_scope s);

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'source', 'MANUAL_ENTRY',
    'updated_count', v_updated_count,
    'cleared_count', v_cleared_count,
    'unmatched', '[]'::jsonb,
    'candidate_summaries', v_candidate_summaries,
    'recompute', jsonb_build_object(
      'deleted_deduction_items', v_deleted_ded_items,
      'deleted_deduction_breakdowns', v_deleted_ded_breakdowns,
      'deleted_manual_debt_breakdowns', v_deleted_manual_debt_breakdowns,
      'deleted_net_deduct_reservations', v_deleted_ded_reservations,
      'released_manual_debt_reservations', v_released_manual_debt_reservations,
      'voided_manual_debt_items', v_voided_manual_debt_items,
      'inserted_overpayment_items', v_ins_overpay,
      'inserted_overpayment_breakdowns', v_ins_overpay_bd,
      'inserted_loan_items', v_ins_loan,
      'inserted_loan_breakdowns', v_ins_loan_bd,
      'inserted_manual_debt_items', v_ins_manual_debt,
      'inserted_manual_debt_breakdowns', v_ins_manual_debt_bd,
      'inserted_finance_reservations', v_ins_finance_reservations,
      'updated_candidates', v_upd_candidates
    )
  );
end;
$$;




-- =========================================================
-- pay_snooze_upsert
-- Creates a new active snooze, or updates the snooze_until_date/note for an existing ACTIVE snooze
-- matching the identity key (candidate_id + timesheet_id + segment_id + source_ref + snooze_kind).
--
-- Identity rules:
--   - Segment snooze: timesheet_id + segment_id required
--   - Non-segment snooze: source_ref required (timesheet_id optional but recommended)
--
-- snooze_until_date:
--   - NULL => snooze forever
--   - date => snoozed until that date (inclusive)
-- =========================================================

CREATE OR REPLACE FUNCTION public.pay_snooze_upsert(
  p_candidate_id uuid,
  p_timesheet_id uuid,
  p_segment_id text,
  p_source_ref text,
  p_snooze_kind text DEFAULT 'DO_NOT_PAY',
  p_snooze_until_date date DEFAULT NULL,
  p_actor_user_id uuid DEFAULT NULL,
  p_note text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_kind_input text := upper(btrim(coalesce(p_snooze_kind, 'DO_NOT_PAY')));
  v_kind text;
  v_segment_id_input text := nullif(btrim(coalesce(p_segment_id, '')), '');
  v_source_ref text := nullif(btrim(coalesce(p_source_ref, '')), '');
  v_note text := nullif(btrim(coalesce(p_note, '')), '');

  v_input_booking_id text := NULL;
  v_booking_id text := NULL;
  v_current_timesheet_id uuid := NULL;
  v_effective_timesheet_id uuid := NULL;

  v_input_invoice_breakdown_json jsonb := NULL;
  v_current_invoice_breakdown_json jsonb := NULL;

  v_input_segment_stable_key text := NULL;
  v_segment_stable_key text := NULL;
  v_current_segment_id text := NULL;
  v_effective_segment_id text := NULL;

  v_keeper_id uuid := NULL;
  v_action text := NULL;

  v_before jsonb := NULL;
  v_after jsonb := NULL;

  v_finance_case_id uuid := NULL;
  v_event_type text := NULL;
  v_conflict_snooze_id uuid := NULL;

  v_finance_case_record public.pay_advances%rowtype;
  v_requested_week_start_date date := NULL;
  v_target_week_start date := NULL;
  v_next_due_week_start_before_snooze_date date := NULL;
  v_next_due_week_start_after_snooze_date date := NULL;

  v_schedule_rebase_result jsonb := NULL;
  v_schedule_before_snooze_json jsonb := NULL;
  v_next_due_week_start_before_snooze text := NULL;
  v_requested_week_start text := NULL;
  v_schedule_after_snooze_json jsonb := NULL;
  v_next_due_week_start_after_snooze text := NULL;
  v_installment_count integer := NULL;
BEGIN
  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'candidate_id is required';
  END IF;

  v_kind := CASE v_kind_input
    WHEN 'BLOCKED' THEN 'BLOCKED_TIMESHEET'
    WHEN 'BLOCKED_TIMESHEET' THEN 'BLOCKED_TIMESHEET'
    WHEN 'DO_NOT_PAY' THEN 'DO_NOT_PAY'
    WHEN 'TIMESHEET_PAYMENT' THEN 'TIMESHEET_PAYMENT'
    WHEN 'OVERPAYMENT_RECOVERY' THEN 'OVERPAYMENT_RECOVERY'
    WHEN 'PAYMENT_ADVANCE_REPAYMENT' THEN 'PAYMENT_ADVANCE_REPAYMENT'
    WHEN 'LOAN_REPAYMENT' THEN 'PAYMENT_ADVANCE_REPAYMENT'
    WHEN 'MANUAL_DEBT_RECOVERY' THEN 'MANUAL_DEBT_RECOVERY'
    ELSE NULL
  END;

  IF v_kind IS NULL THEN
    RAISE EXCEPTION 'invalid snooze_kind';
  END IF;

  IF p_snooze_until_date IS NOT NULL AND p_snooze_until_date < current_date THEN
    RAISE EXCEPTION 'snooze_until_date must be today or later (or NULL for indefinite)';
  END IF;

  IF v_kind IN ('OVERPAYMENT_RECOVERY','PAYMENT_ADVANCE_REPAYMENT','MANUAL_DEBT_RECOVERY') THEN
    IF v_source_ref IS NULL THEN
      RAISE EXCEPTION 'source_ref is required for finance-case snoozes';
    END IF;
    IF p_timesheet_id IS NOT NULL OR v_segment_id_input IS NOT NULL THEN
      RAISE EXCEPTION 'timesheet_id/segment_id must not be supplied for finance-case snoozes';
    END IF;
  ELSIF v_kind = 'TIMESHEET_PAYMENT' THEN
    IF p_timesheet_id IS NULL THEN
      RAISE EXCEPTION 'timesheet_id is required for TIMESHEET_PAYMENT snoozes';
    END IF;
    IF v_segment_id_input IS NOT NULL THEN
      RAISE EXCEPTION 'segment_id must be null for TIMESHEET_PAYMENT snoozes';
    END IF;
    IF v_source_ref IS NOT NULL THEN
      RAISE EXCEPTION 'source_ref must be null for TIMESHEET_PAYMENT snoozes';
    END IF;
  ELSE
    IF p_timesheet_id IS NULL THEN
      RAISE EXCEPTION 'timesheet_id is required for timesheet-line snoozes';
    END IF;
    IF v_source_ref IS NOT NULL THEN
      RAISE EXCEPTION 'source_ref must be null for timesheet-line snoozes';
    END IF;
  END IF;

  IF v_source_ref IS NOT NULL
     AND v_source_ref LIKE 'advance:%'
     AND split_part(v_source_ref, ':', 2) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  THEN
    v_finance_case_id := split_part(v_source_ref, ':', 2)::uuid;
  END IF;

  IF v_source_ref IS NULL THEN
    SELECT
      nullif(btrim(coalesce(t.booking_id, '')), '')
    INTO v_input_booking_id
    FROM public.timesheets t
    WHERE t.timesheet_id = p_timesheet_id
    LIMIT 1;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'timesheet_id is invalid or no longer exists';
    END IF;

    v_booking_id := v_input_booking_id;

    IF v_booking_id IS NOT NULL THEN
      SELECT t.timesheet_id
      INTO v_current_timesheet_id
      FROM public.timesheets t
      WHERE t.booking_id = v_booking_id
        AND t.is_current = true
      ORDER BY coalesce(t.version, 0) DESC, t.updated_at DESC NULLS LAST, t.created_at DESC NULLS LAST, t.timesheet_id DESC
      LIMIT 1;
    END IF;

    v_effective_timesheet_id := coalesce(v_current_timesheet_id, p_timesheet_id);

    SELECT tf.invoice_breakdown_json
    INTO v_input_invoice_breakdown_json
    FROM public.timesheets_financials tf
    WHERE tf.timesheet_id = p_timesheet_id
    ORDER BY CASE WHEN tf.is_current THEN 0 ELSE 1 END, tf.updated_at DESC NULLS LAST, tf.created_at DESC NULLS LAST, tf.id DESC
    LIMIT 1;

    IF v_effective_timesheet_id IS NOT NULL THEN
      SELECT tf.invoice_breakdown_json
      INTO v_current_invoice_breakdown_json
      FROM public.timesheets_financials tf
      WHERE tf.timesheet_id = v_effective_timesheet_id
      ORDER BY CASE WHEN tf.is_current THEN 0 ELSE 1 END, tf.updated_at DESC NULLS LAST, tf.created_at DESC NULLS LAST, tf.id DESC
      LIMIT 1;
    END IF;

    IF v_segment_id_input IS NOT NULL THEN
      SELECT
        nullif(
          btrim(
            coalesce(
              nullif(btrim(coalesce(seg.value->>'segment_stable_key', '')), ''),
              nullif(btrim(coalesce(seg.value->>'work_date', '')), ''),
              nullif(btrim(coalesce(seg.value->>'ref_num', '')), ''),
              nullif(btrim(coalesce(seg.value->>'segment_key', '')), ''),
              nullif(btrim(coalesce(seg.value->>'segment_id', '')), '')
            )
          ),
          ''
        )
      INTO v_input_segment_stable_key
      FROM jsonb_array_elements(
        CASE
          WHEN v_input_invoice_breakdown_json IS NOT NULL
           AND jsonb_typeof(v_input_invoice_breakdown_json) = 'object'
           AND jsonb_typeof(v_input_invoice_breakdown_json->'segments') = 'array'
          THEN v_input_invoice_breakdown_json->'segments'
          ELSE '[]'::jsonb
        END
      ) AS seg(value)
      WHERE jsonb_typeof(seg.value) = 'object'
        AND (
          nullif(btrim(coalesce(seg.value->>'segment_id', '')), '') = v_segment_id_input
          OR nullif(btrim(coalesce(seg.value->>'segment_stable_key', '')), '') = v_segment_id_input
          OR nullif(btrim(coalesce(seg.value->>'segment_key', '')), '') = v_segment_id_input
          OR nullif(btrim(coalesce(seg.value->>'ref_num', '')), '') = v_segment_id_input
          OR nullif(btrim(coalesce(seg.value->>'work_date', '')), '') = v_segment_id_input
        )
      ORDER BY
        CASE
          WHEN nullif(btrim(coalesce(seg.value->>'segment_id', '')), '') = v_segment_id_input THEN 1
          WHEN nullif(btrim(coalesce(seg.value->>'segment_stable_key', '')), '') = v_segment_id_input THEN 2
          WHEN nullif(btrim(coalesce(seg.value->>'segment_key', '')), '') = v_segment_id_input THEN 3
          WHEN nullif(btrim(coalesce(seg.value->>'ref_num', '')), '') = v_segment_id_input THEN 4
          WHEN nullif(btrim(coalesce(seg.value->>'work_date', '')), '') = v_segment_id_input THEN 5
          ELSE 99
        END
      LIMIT 1;

      SELECT
        nullif(btrim(coalesce(seg.value->>'segment_id', '')), ''),
        nullif(
          btrim(
            coalesce(
              nullif(btrim(coalesce(seg.value->>'segment_stable_key', '')), ''),
              nullif(btrim(coalesce(seg.value->>'work_date', '')), ''),
              nullif(btrim(coalesce(seg.value->>'ref_num', '')), ''),
              nullif(btrim(coalesce(seg.value->>'segment_key', '')), ''),
              nullif(btrim(coalesce(seg.value->>'segment_id', '')), '')
            )
          ),
          ''
        )
      INTO v_current_segment_id, v_segment_stable_key
      FROM jsonb_array_elements(
        CASE
          WHEN v_current_invoice_breakdown_json IS NOT NULL
           AND jsonb_typeof(v_current_invoice_breakdown_json) = 'object'
           AND jsonb_typeof(v_current_invoice_breakdown_json->'segments') = 'array'
          THEN v_current_invoice_breakdown_json->'segments'
          ELSE '[]'::jsonb
        END
      ) AS seg(value)
      WHERE jsonb_typeof(seg.value) = 'object'
        AND (
          (
            v_input_segment_stable_key IS NOT NULL
            AND nullif(
                  btrim(
                    coalesce(
                      nullif(btrim(coalesce(seg.value->>'segment_stable_key', '')), ''),
                      nullif(btrim(coalesce(seg.value->>'work_date', '')), ''),
                      nullif(btrim(coalesce(seg.value->>'ref_num', '')), ''),
                      nullif(btrim(coalesce(seg.value->>'segment_key', '')), ''),
                      nullif(btrim(coalesce(seg.value->>'segment_id', '')), '')
                    )
                  ),
                  ''
                ) = v_input_segment_stable_key
          )
          OR nullif(btrim(coalesce(seg.value->>'segment_id', '')), '') = v_segment_id_input
          OR nullif(btrim(coalesce(seg.value->>'segment_stable_key', '')), '') = v_segment_id_input
          OR nullif(btrim(coalesce(seg.value->>'segment_key', '')), '') = v_segment_id_input
          OR nullif(btrim(coalesce(seg.value->>'ref_num', '')), '') = v_segment_id_input
          OR nullif(btrim(coalesce(seg.value->>'work_date', '')), '') = v_segment_id_input
        )
      ORDER BY
        CASE
          WHEN v_input_segment_stable_key IS NOT NULL
           AND nullif(
                 btrim(
                   coalesce(
                     nullif(btrim(coalesce(seg.value->>'segment_stable_key', '')), ''),
                     nullif(btrim(coalesce(seg.value->>'work_date', '')), ''),
                     nullif(btrim(coalesce(seg.value->>'ref_num', '')), ''),
                     nullif(btrim(coalesce(seg.value->>'segment_key', '')), ''),
                     nullif(btrim(coalesce(seg.value->>'segment_id', '')), '')
                   )
                 ),
                 ''
               ) = v_input_segment_stable_key THEN 1
          WHEN nullif(btrim(coalesce(seg.value->>'segment_id', '')), '') = v_segment_id_input THEN 2
          WHEN nullif(btrim(coalesce(seg.value->>'segment_stable_key', '')), '') = v_segment_id_input THEN 3
          WHEN nullif(btrim(coalesce(seg.value->>'segment_key', '')), '') = v_segment_id_input THEN 4
          WHEN nullif(btrim(coalesce(seg.value->>'ref_num', '')), '') = v_segment_id_input THEN 5
          WHEN nullif(btrim(coalesce(seg.value->>'work_date', '')), '') = v_segment_id_input THEN 6
          ELSE 99
        END
      LIMIT 1;

      v_segment_stable_key := coalesce(v_segment_stable_key, v_input_segment_stable_key);
      v_effective_segment_id := v_current_segment_id;

      IF v_segment_stable_key IS NULL THEN
        RAISE EXCEPTION 'segment_id could not be resolved on the timesheet';
      END IF;
    ELSE
      v_segment_stable_key := NULL;
      v_effective_segment_id := NULL;
    END IF;
  END IF;

  IF v_source_ref IS NULL THEN
    IF v_kind = 'TIMESHEET_PAYMENT' THEN
      SELECT s.id
      INTO v_conflict_snooze_id
      FROM public.pay_item_snoozes s
      WHERE s.candidate_id = p_candidate_id
        AND s.source_ref IS NULL
        AND s.cleared_at_utc IS NULL
        AND upper(coalesce(s.snooze_kind, '')) IN ('DO_NOT_PAY', 'BLOCKED_TIMESHEET')
        AND coalesce(
              nullif(btrim(coalesce(s.segment_stable_key, '')), ''),
              nullif(btrim(coalesce(s.segment_id, '')), '')
            ) IS NOT NULL
        AND (
          (
            v_booking_id IS NOT NULL
            AND (
              s.booking_id IS NOT DISTINCT FROM v_booking_id
              OR (
                s.booking_id IS NULL
                AND (
                  s.timesheet_id IS NOT DISTINCT FROM p_timesheet_id
                  OR s.timesheet_id IS NOT DISTINCT FROM v_effective_timesheet_id
                )
              )
            )
          )
          OR
          (
            v_booking_id IS NULL
            AND (
              s.timesheet_id IS NOT DISTINCT FROM p_timesheet_id
              OR s.timesheet_id IS NOT DISTINCT FROM v_effective_timesheet_id
            )
          )
        )
      ORDER BY s.updated_at_utc DESC NULLS LAST, s.created_at_utc DESC, s.id DESC
      LIMIT 1;

      IF v_conflict_snooze_id IS NOT NULL THEN
        RAISE EXCEPTION '%', 'SEGMENT_SNOOZES_ALREADY_EXIST'
          USING DETAIL = jsonb_build_object(
            'error_code', 'SEGMENT_SNOOZES_ALREADY_EXIST',
            'candidate_id', p_candidate_id::text,
            'timesheet_id', coalesce(v_effective_timesheet_id, p_timesheet_id)::text,
            'booking_id', v_booking_id,
            'conflict_snooze_id', v_conflict_snooze_id::text
          )::text;
      END IF;
    ELSIF coalesce(v_effective_segment_id, v_segment_stable_key, v_segment_id_input) IS NOT NULL THEN
      SELECT s.id
      INTO v_conflict_snooze_id
      FROM public.pay_item_snoozes s
      WHERE s.candidate_id = p_candidate_id
        AND s.source_ref IS NULL
        AND s.cleared_at_utc IS NULL
        AND upper(coalesce(s.snooze_kind, '')) = 'TIMESHEET_PAYMENT'
        AND s.segment_id IS NULL
        AND s.segment_stable_key IS NULL
        AND (
          (
            v_booking_id IS NOT NULL
            AND (
              s.booking_id IS NOT DISTINCT FROM v_booking_id
              OR (
                s.booking_id IS NULL
                AND (
                  s.timesheet_id IS NOT DISTINCT FROM p_timesheet_id
                  OR s.timesheet_id IS NOT DISTINCT FROM v_effective_timesheet_id
                )
              )
            )
          )
          OR
          (
            v_booking_id IS NULL
            AND (
              s.timesheet_id IS NOT DISTINCT FROM p_timesheet_id
              OR s.timesheet_id IS NOT DISTINCT FROM v_effective_timesheet_id
            )
          )
        )
      ORDER BY s.updated_at_utc DESC NULLS LAST, s.created_at_utc DESC, s.id DESC
      LIMIT 1;

      IF v_conflict_snooze_id IS NOT NULL THEN
        RAISE EXCEPTION '%', 'WHOLE_TIMESHEET_ALREADY_SNOOZED'
          USING DETAIL = jsonb_build_object(
            'error_code', 'WHOLE_TIMESHEET_ALREADY_SNOOZED',
            'candidate_id', p_candidate_id::text,
            'timesheet_id', coalesce(v_effective_timesheet_id, p_timesheet_id)::text,
            'booking_id', v_booking_id,
            'segment_id', coalesce(v_effective_segment_id, v_segment_id_input),
            'segment_stable_key', v_segment_stable_key,
            'conflict_snooze_id', v_conflict_snooze_id::text
          )::text;
      END IF;
    END IF;
  END IF;

  SELECT jsonb_build_object(
           'id', s.id::text,
           'candidate_id', s.candidate_id::text,
           'timesheet_id', CASE WHEN s.timesheet_id IS NULL THEN NULL ELSE s.timesheet_id::text END,
           'booking_id', s.booking_id,
           'segment_id', s.segment_id,
           'segment_stable_key', s.segment_stable_key,
           'source_ref', s.source_ref,
           'snooze_kind', s.snooze_kind,
           'snooze_until_date', CASE WHEN s.snooze_until_date IS NULL THEN NULL ELSE s.snooze_until_date::text END,
           'note', s.note
         )
  INTO v_before
  FROM public.pay_item_snoozes s
  WHERE s.candidate_id = p_candidate_id
    AND s.cleared_at_utc IS NULL
    AND (
      (v_source_ref IS NOT NULL AND s.source_ref IS NOT DISTINCT FROM v_source_ref)
      OR
      (
        v_source_ref IS NULL
        AND s.source_ref IS NULL
        AND (
          (
            v_booking_id IS NOT NULL
            AND s.booking_id IS NOT DISTINCT FROM v_booking_id
            AND coalesce(s.segment_stable_key, '') IS NOT DISTINCT FROM coalesce(v_segment_stable_key, '')
          )
          OR
          (
            s.booking_id IS NULL
            AND (
              s.timesheet_id IS NOT DISTINCT FROM p_timesheet_id
              OR s.timesheet_id IS NOT DISTINCT FROM v_effective_timesheet_id
            )
            AND s.segment_id IS NOT DISTINCT FROM coalesce(v_effective_segment_id, v_segment_id_input)
          )
        )
      )
    )
  ORDER BY s.updated_at_utc DESC NULLS LAST, s.created_at_utc DESC, s.id DESC
  LIMIT 1;

  SELECT s.id
  INTO v_keeper_id
  FROM public.pay_item_snoozes s
  WHERE s.candidate_id = p_candidate_id
    AND s.cleared_at_utc IS NULL
    AND (
      (v_source_ref IS NOT NULL AND s.source_ref IS NOT DISTINCT FROM v_source_ref)
      OR
      (
        v_source_ref IS NULL
        AND s.source_ref IS NULL
        AND (
          (
            v_booking_id IS NOT NULL
            AND s.booking_id IS NOT DISTINCT FROM v_booking_id
            AND coalesce(s.segment_stable_key, '') IS NOT DISTINCT FROM coalesce(v_segment_stable_key, '')
          )
          OR
          (
            s.booking_id IS NULL
            AND (
              s.timesheet_id IS NOT DISTINCT FROM p_timesheet_id
              OR s.timesheet_id IS NOT DISTINCT FROM v_effective_timesheet_id
            )
            AND s.segment_id IS NOT DISTINCT FROM coalesce(v_effective_segment_id, v_segment_id_input)
          )
        )
      )
    )
  ORDER BY s.updated_at_utc DESC NULLS LAST, s.created_at_utc DESC, s.id DESC
  LIMIT 1;

  IF v_source_ref IS NULL AND v_segment_id_input IS NOT NULL AND v_effective_segment_id IS NULL THEN
    IF v_keeper_id IS NOT NULL THEN
      UPDATE public.pay_item_snoozes s
      SET
        cleared_at_utc = now(),
        cleared_by_user_id = p_actor_user_id,
        updated_at_utc = now(),
        updated_by_user_id = p_actor_user_id
      WHERE s.id = v_keeper_id;

      SELECT jsonb_build_object(
               'id', s.id::text,
               'candidate_id', s.candidate_id::text,
               'timesheet_id', CASE WHEN s.timesheet_id IS NULL THEN NULL ELSE s.timesheet_id::text END,
               'booking_id', s.booking_id,
               'segment_id', s.segment_id,
               'segment_stable_key', s.segment_stable_key,
               'source_ref', s.source_ref,
               'snooze_kind', s.snooze_kind,
               'snooze_until_date', CASE WHEN s.snooze_until_date IS NULL THEN NULL ELSE s.snooze_until_date::text END,
               'note', s.note,
               'cleared_at_utc', CASE WHEN s.cleared_at_utc IS NULL THEN NULL ELSE s.cleared_at_utc::text END
             )
      INTO v_after
      FROM public.pay_item_snoozes s
      WHERE s.id = v_keeper_id;

      PERFORM public._audit_insert(
        'timesheets',
        coalesce(v_effective_timesheet_id, p_timesheet_id)::text,
        'SNOOZE_CLEARED',
        v_before,
        v_after,
        'SEGMENT_NO_LONGER_MATCHED',
        p_actor_user_id
      );

      RETURN jsonb_build_object(
        'ok', true,
        'action', 'CLEARED_ORPHANED',
        'id', v_keeper_id::text,
        'candidate_id', p_candidate_id::text,
        'timesheet_id', CASE WHEN v_effective_timesheet_id IS NULL THEN NULL ELSE v_effective_timesheet_id::text END,
        'booking_id', v_booking_id,
        'segment_id', NULL,
        'segment_stable_key', v_segment_stable_key,
        'source_ref', NULL,
        'snooze_kind', v_kind,
        'snooze_until_date', NULL,
        'snooze_is_indefinite', NULL,
        'note', v_note,
        'preview_visibility_hint', 'RELOAD_PREVIEW'
      );
    END IF;

    RAISE EXCEPTION 'segment_id could not be matched on the current timesheet';
  END IF;

  UPDATE public.pay_item_snoozes s
  SET
    cleared_at_utc = now(),
    cleared_by_user_id = p_actor_user_id,
    updated_at_utc = now(),
    updated_by_user_id = p_actor_user_id
  WHERE s.candidate_id = p_candidate_id
    AND s.cleared_at_utc IS NULL
    AND s.id <> v_keeper_id
    AND (
      (v_source_ref IS NOT NULL AND s.source_ref IS NOT DISTINCT FROM v_source_ref)
      OR
      (
        v_source_ref IS NULL
        AND s.source_ref IS NULL
        AND (
          (
            v_booking_id IS NOT NULL
            AND s.booking_id IS NOT DISTINCT FROM v_booking_id
            AND coalesce(s.segment_stable_key, '') IS NOT DISTINCT FROM coalesce(v_segment_stable_key, '')
          )
          OR
          (
            s.booking_id IS NULL
            AND (
              s.timesheet_id IS NOT DISTINCT FROM p_timesheet_id
              OR s.timesheet_id IS NOT DISTINCT FROM v_effective_timesheet_id
            )
            AND s.segment_id IS NOT DISTINCT FROM coalesce(v_effective_segment_id, v_segment_id_input)
          )
        )
      )
    );

  IF v_keeper_id IS NOT NULL THEN
    UPDATE public.pay_item_snoozes s
    SET
      timesheet_id = CASE WHEN v_source_ref IS NULL THEN v_effective_timesheet_id ELSE NULL END,
      booking_id = CASE WHEN v_source_ref IS NULL THEN v_booking_id ELSE NULL END,
      segment_id = CASE WHEN v_source_ref IS NULL THEN v_effective_segment_id ELSE NULL END,
      segment_stable_key = CASE WHEN v_source_ref IS NULL THEN v_segment_stable_key ELSE NULL END,
      snooze_kind = v_kind,
      snooze_until_date = p_snooze_until_date,
      note = v_note,
      updated_at_utc = now(),
      updated_by_user_id = p_actor_user_id
    WHERE s.id = v_keeper_id;

    v_action := 'UPDATED';
  ELSE
    INSERT INTO public.pay_item_snoozes (
      candidate_id,
      timesheet_id,
      booking_id,
      segment_id,
      segment_stable_key,
      source_ref,
      snooze_kind,
      snooze_until_date,
      created_at_utc,
      created_by_user_id,
      note,
      cleared_at_utc,
      cleared_by_user_id,
      updated_at_utc,
      updated_by_user_id
    )
    VALUES (
      p_candidate_id,
      CASE WHEN v_source_ref IS NULL THEN v_effective_timesheet_id ELSE NULL END,
      CASE WHEN v_source_ref IS NULL THEN v_booking_id ELSE NULL END,
      CASE WHEN v_source_ref IS NULL THEN v_effective_segment_id ELSE NULL END,
      CASE WHEN v_source_ref IS NULL THEN v_segment_stable_key ELSE NULL END,
      v_source_ref,
      v_kind,
      p_snooze_until_date,
      now(),
      p_actor_user_id,
      v_note,
      NULL,
      NULL,
      now(),
      p_actor_user_id
    )
    RETURNING id INTO v_keeper_id;

    v_action := 'CREATED';
  END IF;

  IF v_finance_case_id IS NOT NULL
     AND v_kind IN ('OVERPAYMENT_RECOVERY', 'PAYMENT_ADVANCE_REPAYMENT', 'MANUAL_DEBT_RECOVERY')
     AND p_snooze_until_date IS NOT NULL
  THEN
    SELECT pa.*
    INTO v_finance_case_record
    FROM public.pay_advances AS pa
    WHERE pa.id = v_finance_case_id
    LIMIT 1
    FOR UPDATE;

    IF v_finance_case_record.id IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_REPAYMENT_SCHEDULE_REBASE_FOR_SNOOZE',
        'code', 'FINANCE_CASE_NOT_FOUND',
        'message', '_pay_repayment_schedule_rebase_for_snooze: finance case not found',
        'finance_case_id', v_finance_case_id::text
      )::text;
    END IF;

    IF v_finance_case_record.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum THEN
      v_schedule_before_snooze_json := coalesce(v_finance_case_record.schedule_json, '[]'::jsonb);
      v_next_due_week_start_before_snooze_date := v_finance_case_record.next_due_week_start;
      v_requested_week_start_date := public._pay_week_start_monday(p_snooze_until_date);

      IF v_next_due_week_start_before_snooze_date IS NULL THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_REPAYMENT_SCHEDULE_REBASE_FOR_SNOOZE',
          'code', 'NEXT_DUE_MISSING',
          'message', '_pay_repayment_schedule_rebase_for_snooze: next_due_week_start is required on the finance case'
        )::text;
      END IF;

      IF v_requested_week_start_date < v_next_due_week_start_before_snooze_date THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_REPAYMENT_SCHEDULE_REBASE_FOR_SNOOZE',
          'code', 'SNOOZE_DATE_BEFORE_NEXT_DUE',
          'message', '_pay_repayment_schedule_rebase_for_snooze: snooze_until_date cannot move the repayment schedule earlier than the current next due week',
          'finance_case_id', v_finance_case_id::text,
          'current_next_due_week_start', v_next_due_week_start_before_snooze_date::text,
          'requested_week_start', v_requested_week_start_date::text
        )::text;
      END IF;

      v_target_week_start := CASE
        WHEN v_requested_week_start_date = v_next_due_week_start_before_snooze_date THEN (v_next_due_week_start_before_snooze_date + 7)
        ELSE v_requested_week_start_date
      END;

      WITH schedule_rows AS (
        SELECT
          row_number() OVER (ORDER BY (elem.value ->> 'week_start')::date ASC, elem.ordinality ASC) AS seq_no,
          round(coalesce((elem.value ->> 'amount')::numeric, 0), 2) AS amount_value
        FROM jsonb_array_elements(v_schedule_before_snooze_json) WITH ORDINALITY AS elem(value, ordinality)
        WHERE coalesce((elem.value ->> 'amount')::numeric, 0) < 0
      )
      SELECT
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'week_start', (v_target_week_start + (((sr.seq_no - 1)::integer) * 7))::date,
              'amount', sr.amount_value
            )
            ORDER BY (v_target_week_start + (((sr.seq_no - 1)::integer) * 7))::date ASC
          ),
          '[]'::jsonb
        ),
        count(*)::integer
      INTO v_schedule_after_snooze_json, v_installment_count
      FROM schedule_rows AS sr;

      v_next_due_week_start_after_snooze_date := CASE
        WHEN v_installment_count > 0 THEN v_target_week_start
        ELSE NULL
      END;

      UPDATE public.pay_advances AS pa
      SET schedule_json = v_schedule_after_snooze_json,
          next_due_week_start = v_next_due_week_start_after_snooze_date,
          updated_at = now()
      WHERE pa.id = v_finance_case_id;

      v_schedule_rebase_result := jsonb_build_object(
        'ok', true,
        'finance_case_id', v_finance_case_id::text,
        'schedule_before_snooze_json', v_schedule_before_snooze_json,
        'next_due_week_start_before_snooze', CASE WHEN v_next_due_week_start_before_snooze_date IS NULL THEN NULL ELSE v_next_due_week_start_before_snooze_date::text END,
        'requested_week_start', CASE WHEN v_requested_week_start_date IS NULL THEN NULL ELSE v_requested_week_start_date::text END,
        'schedule_after_snooze_json', v_schedule_after_snooze_json,
        'next_due_week_start_after_snooze', CASE WHEN v_next_due_week_start_after_snooze_date IS NULL THEN NULL ELSE v_next_due_week_start_after_snooze_date::text END,
        'installment_count', v_installment_count
      );
    ELSE
      v_schedule_rebase_result := public._pay_repayment_schedule_rebase_for_snooze(
        v_finance_case_id,
        p_snooze_until_date
      );
    END IF;

    v_schedule_before_snooze_json := v_schedule_rebase_result -> 'schedule_before_snooze_json';
    v_next_due_week_start_before_snooze_date := CASE
      WHEN nullif(btrim(coalesce(v_schedule_rebase_result ->> 'next_due_week_start_before_snooze', '')), '') IS NULL THEN NULL
      ELSE (v_schedule_rebase_result ->> 'next_due_week_start_before_snooze')::date
    END;
    v_next_due_week_start_before_snooze := CASE
      WHEN v_next_due_week_start_before_snooze_date IS NULL THEN NULL
      ELSE v_next_due_week_start_before_snooze_date::text
    END;
    v_requested_week_start_date := CASE
      WHEN nullif(btrim(coalesce(v_schedule_rebase_result ->> 'requested_week_start', '')), '') IS NULL THEN NULL
      ELSE (v_schedule_rebase_result ->> 'requested_week_start')::date
    END;
    v_requested_week_start := CASE
      WHEN v_requested_week_start_date IS NULL THEN NULL
      ELSE v_requested_week_start_date::text
    END;
    v_schedule_after_snooze_json := v_schedule_rebase_result -> 'schedule_after_snooze_json';
    v_next_due_week_start_after_snooze_date := CASE
      WHEN nullif(btrim(coalesce(v_schedule_rebase_result ->> 'next_due_week_start_after_snooze', '')), '') IS NULL THEN NULL
      ELSE (v_schedule_rebase_result ->> 'next_due_week_start_after_snooze')::date
    END;
    v_next_due_week_start_after_snooze := CASE
      WHEN v_next_due_week_start_after_snooze_date IS NULL THEN NULL
      ELSE v_next_due_week_start_after_snooze_date::text
    END;
    v_installment_count := CASE
      WHEN nullif(btrim(coalesce(v_schedule_rebase_result ->> 'installment_count', '')), '') ~ '^-?[0-9]+$'
      THEN (v_schedule_rebase_result ->> 'installment_count')::integer
      ELSE NULL
    END;

    UPDATE public.pay_item_snoozes AS s
    SET schedule_before_snooze_json = v_schedule_before_snooze_json,
        next_due_week_start_before_snooze = v_next_due_week_start_before_snooze_date,
        schedule_after_snooze_json = v_schedule_after_snooze_json,
        next_due_week_start_after_snooze = v_next_due_week_start_after_snooze_date,
        updated_at_utc = now(),
        updated_by_user_id = p_actor_user_id
    WHERE s.id = v_keeper_id;
  END IF;

  SELECT
    jsonb_build_object(
      'id', s.id::text,
      'candidate_id', s.candidate_id::text,
      'timesheet_id', CASE WHEN s.timesheet_id IS NULL THEN NULL ELSE s.timesheet_id::text END,
      'booking_id', s.booking_id,
      'segment_id', s.segment_id,
      'segment_stable_key', s.segment_stable_key,
      'source_ref', s.source_ref,
      'snooze_kind', s.snooze_kind,
      'snooze_until_date', CASE WHEN s.snooze_until_date IS NULL THEN NULL ELSE s.snooze_until_date::text END,
      'note', s.note
    )
    ||
    CASE
      WHEN v_schedule_rebase_result IS NULL THEN '{}'::jsonb
      ELSE jsonb_build_object('schedule_rebase_result', v_schedule_rebase_result)
    END
  INTO v_after
  FROM public.pay_item_snoozes s
  WHERE s.id = v_keeper_id;

  v_event_type := CASE v_action
    WHEN 'CREATED' THEN 'SNOOZE_APPLIED'
    ELSE 'SNOOZE_UPDATED'
  END;

  IF v_finance_case_id IS NOT NULL THEN
    INSERT INTO public.pay_finance_case_events (
      finance_case_id,
      event_type,
      event_at_utc,
      actor_user_id,
      before_json,
      after_json,
      reason,
      note
    )
    VALUES (
      v_finance_case_id,
      v_event_type,
      now(),
      p_actor_user_id,
      v_before,
      v_after,
      v_kind,
      v_note
    );

    PERFORM public._audit_insert(
      'finance_case',
      v_finance_case_id::text,
      v_event_type,
      v_before,
      v_after,
      v_kind,
      p_actor_user_id
    );
  ELSIF coalesce(v_effective_timesheet_id, p_timesheet_id) IS NOT NULL THEN
    PERFORM public._audit_insert(
      'timesheets',
      coalesce(v_effective_timesheet_id, p_timesheet_id)::text,
      v_event_type,
      v_before,
      v_after,
      v_kind,
      p_actor_user_id
    );
  ELSE
    PERFORM public._audit_insert(
      'pay_item_snoozes',
      v_keeper_id::text,
      v_event_type,
      v_before,
      v_after,
      v_kind,
      p_actor_user_id
    );
  END IF;

  RETURN
    jsonb_build_object(
      'ok', true,
      'action', v_action,
      'id', v_keeper_id::text,
      'candidate_id', p_candidate_id::text,
      'timesheet_id', CASE WHEN v_effective_timesheet_id IS NULL THEN NULL ELSE v_effective_timesheet_id::text END,
      'booking_id', v_booking_id,
      'segment_id', v_effective_segment_id,
      'segment_stable_key', v_segment_stable_key,
      'source_ref', v_source_ref,
      'finance_case_id', CASE WHEN v_finance_case_id IS NULL THEN NULL ELSE v_finance_case_id::text END,
      'snooze_kind', v_kind,
      'snooze_until_date', CASE WHEN p_snooze_until_date IS NULL THEN NULL ELSE p_snooze_until_date::text END,
      'snooze_is_indefinite', (p_snooze_until_date IS NULL),
      'note', v_note
    )
    ||
    jsonb_build_object(
      'schedule_before_snooze_json', v_schedule_before_snooze_json,
      'next_due_week_start_before_snooze', v_next_due_week_start_before_snooze,
      'requested_week_start', v_requested_week_start,
      'schedule_after_snooze_json', v_schedule_after_snooze_json,
      'next_due_week_start_after_snooze', v_next_due_week_start_after_snooze,
      'installment_count', v_installment_count
    );
END;
$$;




CREATE OR REPLACE FUNCTION public.pay_snooze_clear(
  p_snooze_id uuid,
  p_actor_user_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_row record;
  v_before jsonb := NULL;
  v_after jsonb := NULL;
  v_finance_case_id uuid := NULL;

  v_finance_case_record public.pay_advances%rowtype;
  v_effective_from_date date := NULL;
  v_requested_week_start_date date := NULL;
  v_current_operating_week_start_date date := NULL;
  v_target_week_start date := NULL;
  v_next_due_week_start_before_restore_date date := NULL;
  v_next_due_week_start_after_restore_date date := NULL;

  v_schedule_restore_result jsonb := NULL;
  v_schedule_before_restore_json jsonb := NULL;
  v_next_due_week_start_before_restore text := NULL;
  v_requested_week_start text := NULL;
  v_current_operating_week_start text := NULL;
  v_schedule_after_restore_json jsonb := NULL;
  v_next_due_week_start_after_restore text := NULL;
  v_installment_count integer := NULL;
BEGIN
  IF p_snooze_id IS NULL THEN
    RAISE EXCEPTION 'snooze_id is required';
  END IF;

  SELECT
    s.id,
    s.candidate_id,
    s.timesheet_id,
    s.segment_id,
    s.source_ref,
    s.snooze_kind,
    s.snooze_until_date,
    s.note,
    s.created_at_utc,
    s.cleared_at_utc
  INTO v_row
  FROM public.pay_item_snoozes s
  WHERE s.id = p_snooze_id
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SNOOZE_NOT_FOUND';
  END IF;

  v_before := jsonb_build_object(
    'id', v_row.id::text,
    'candidate_id', v_row.candidate_id::text,
    'timesheet_id', CASE WHEN v_row.timesheet_id IS NULL THEN NULL ELSE v_row.timesheet_id::text END,
    'segment_id', v_row.segment_id,
    'source_ref', v_row.source_ref,
    'snooze_kind', v_row.snooze_kind,
    'snooze_until_date', CASE WHEN v_row.snooze_until_date IS NULL THEN NULL ELSE v_row.snooze_until_date::text END,
    'note', v_row.note,
    'cleared_at_utc', v_row.cleared_at_utc
  );

  IF v_row.cleared_at_utc IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'action', 'NOOP_ALREADY_CLEARED',
      'id', v_row.id::text
    );
  END IF;

  IF v_row.source_ref IS NOT NULL
     AND v_row.source_ref LIKE 'advance:%'
     AND split_part(v_row.source_ref, ':', 2) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  THEN
    v_finance_case_id := split_part(v_row.source_ref, ':', 2)::uuid;
  END IF;

  UPDATE public.pay_item_snoozes s
  SET
    cleared_at_utc = now(),
    cleared_by_user_id = p_actor_user_id,
    updated_at_utc = now(),
    updated_by_user_id = p_actor_user_id
  WHERE s.id = p_snooze_id;

  IF v_finance_case_id IS NOT NULL
     AND upper(coalesce(v_row.snooze_kind, '')) IN ('OVERPAYMENT_RECOVERY', 'PAYMENT_ADVANCE_REPAYMENT', 'MANUAL_DEBT_RECOVERY')
     AND v_row.snooze_until_date IS NOT NULL
  THEN
    v_effective_from_date := (now() AT TIME ZONE 'Europe/London')::date;

    SELECT pa.*
    INTO v_finance_case_record
    FROM public.pay_advances AS pa
    WHERE pa.id = v_finance_case_id
    LIMIT 1
    FOR UPDATE;

    IF v_finance_case_record.id IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_REPAYMENT_SCHEDULE_RESTORE_AFTER_SNOOZE_CLEAR',
        'code', 'FINANCE_CASE_NOT_FOUND',
        'message', '_pay_repayment_schedule_restore_after_snooze_clear: finance case not found',
        'finance_case_id', v_finance_case_id::text
      )::text;
    END IF;

    IF v_finance_case_record.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum THEN
      v_schedule_before_restore_json := coalesce(v_finance_case_record.schedule_json, '[]'::jsonb);
      v_next_due_week_start_before_restore_date := v_finance_case_record.next_due_week_start;
      v_requested_week_start_date := public._pay_week_start_monday(v_effective_from_date);
      v_current_operating_week_start_date := public._pay_week_start_monday((now() AT TIME ZONE 'Europe/London')::date);

      IF v_requested_week_start_date < v_current_operating_week_start_date THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_REPAYMENT_SCHEDULE_RESTORE_AFTER_SNOOZE_CLEAR',
          'code', 'EFFECTIVE_FROM_DATE_BEFORE_NOW',
          'message', '_pay_repayment_schedule_restore_after_snooze_clear: effective_from_date cannot restore the repayment schedule earlier than the current operating week',
          'finance_case_id', v_finance_case_id::text,
          'requested_week_start', v_requested_week_start_date::text,
          'current_operating_week_start', v_current_operating_week_start_date::text
        )::text;
      END IF;

      v_target_week_start := v_requested_week_start_date;

      WITH schedule_rows AS (
        SELECT
          row_number() OVER (ORDER BY (elem.value ->> 'week_start')::date ASC, elem.ordinality ASC) AS seq_no,
          round(coalesce((elem.value ->> 'amount')::numeric, 0), 2) AS amount_value
        FROM jsonb_array_elements(v_schedule_before_restore_json) WITH ORDINALITY AS elem(value, ordinality)
        WHERE coalesce((elem.value ->> 'amount')::numeric, 0) < 0
      )
      SELECT
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'week_start', (v_target_week_start + (((sr.seq_no - 1)::integer) * 7))::date,
              'amount', sr.amount_value
            )
            ORDER BY (v_target_week_start + (((sr.seq_no - 1)::integer) * 7))::date ASC
          ),
          '[]'::jsonb
        ),
        count(*)::integer
      INTO v_schedule_after_restore_json, v_installment_count
      FROM schedule_rows AS sr;

      v_next_due_week_start_after_restore_date := CASE
        WHEN v_installment_count > 0 THEN v_target_week_start
        ELSE NULL
      END;

      UPDATE public.pay_advances AS pa
      SET schedule_json = v_schedule_after_restore_json,
          next_due_week_start = v_next_due_week_start_after_restore_date,
          updated_at = now()
      WHERE pa.id = v_finance_case_id;

      v_schedule_restore_result := jsonb_build_object(
        'ok', true,
        'finance_case_id', v_finance_case_id::text,
        'schedule_before_restore_json', v_schedule_before_restore_json,
        'next_due_week_start_before_restore', CASE WHEN v_next_due_week_start_before_restore_date IS NULL THEN NULL ELSE v_next_due_week_start_before_restore_date::text END,
        'requested_week_start', CASE WHEN v_requested_week_start_date IS NULL THEN NULL ELSE v_requested_week_start_date::text END,
        'current_operating_week_start', CASE WHEN v_current_operating_week_start_date IS NULL THEN NULL ELSE v_current_operating_week_start_date::text END,
        'schedule_after_restore_json', v_schedule_after_restore_json,
        'next_due_week_start_after_restore', CASE WHEN v_next_due_week_start_after_restore_date IS NULL THEN NULL ELSE v_next_due_week_start_after_restore_date::text END,
        'installment_count', v_installment_count
      );
    ELSE
      v_schedule_restore_result := public._pay_repayment_schedule_restore_after_snooze_clear(
        v_finance_case_id,
        v_effective_from_date
      );
    END IF;

    v_schedule_before_restore_json := v_schedule_restore_result -> 'schedule_before_restore_json';
    v_next_due_week_start_before_restore_date := CASE
      WHEN nullif(btrim(coalesce(v_schedule_restore_result ->> 'next_due_week_start_before_restore', '')), '') IS NULL THEN NULL
      ELSE (v_schedule_restore_result ->> 'next_due_week_start_before_restore')::date
    END;
    v_next_due_week_start_before_restore := CASE
      WHEN v_next_due_week_start_before_restore_date IS NULL THEN NULL
      ELSE v_next_due_week_start_before_restore_date::text
    END;
    v_requested_week_start_date := CASE
      WHEN nullif(btrim(coalesce(v_schedule_restore_result ->> 'requested_week_start', '')), '') IS NULL THEN NULL
      ELSE (v_schedule_restore_result ->> 'requested_week_start')::date
    END;
    v_requested_week_start := CASE
      WHEN v_requested_week_start_date IS NULL THEN NULL
      ELSE v_requested_week_start_date::text
    END;
    v_current_operating_week_start_date := CASE
      WHEN nullif(btrim(coalesce(v_schedule_restore_result ->> 'current_operating_week_start', '')), '') IS NULL THEN NULL
      ELSE (v_schedule_restore_result ->> 'current_operating_week_start')::date
    END;
    v_current_operating_week_start := CASE
      WHEN v_current_operating_week_start_date IS NULL THEN NULL
      ELSE v_current_operating_week_start_date::text
    END;
    v_schedule_after_restore_json := v_schedule_restore_result -> 'schedule_after_restore_json';
    v_next_due_week_start_after_restore_date := CASE
      WHEN nullif(btrim(coalesce(v_schedule_restore_result ->> 'next_due_week_start_after_restore', '')), '') IS NULL THEN NULL
      ELSE (v_schedule_restore_result ->> 'next_due_week_start_after_restore')::date
    END;
    v_next_due_week_start_after_restore := CASE
      WHEN v_next_due_week_start_after_restore_date IS NULL THEN NULL
      ELSE v_next_due_week_start_after_restore_date::text
    END;
    v_installment_count := CASE
      WHEN nullif(btrim(coalesce(v_schedule_restore_result ->> 'installment_count', '')), '') ~ '^-?[0-9]+$'
      THEN (v_schedule_restore_result ->> 'installment_count')::integer
      ELSE NULL
    END;
  END IF;

  SELECT
    jsonb_build_object(
      'id', s.id::text,
      'candidate_id', s.candidate_id::text,
      'timesheet_id', CASE WHEN s.timesheet_id IS NULL THEN NULL ELSE s.timesheet_id::text END,
      'segment_id', s.segment_id,
      'source_ref', s.source_ref,
      'snooze_kind', s.snooze_kind,
      'snooze_until_date', CASE WHEN s.snooze_until_date IS NULL THEN NULL ELSE s.snooze_until_date::text END,
      'note', s.note,
      'cleared_at_utc', s.cleared_at_utc
    )
    ||
    CASE
      WHEN v_schedule_restore_result IS NULL THEN '{}'::jsonb
      ELSE jsonb_build_object('schedule_restore_result', v_schedule_restore_result)
    END
  INTO v_after
  FROM public.pay_item_snoozes s
  WHERE s.id = p_snooze_id;

  IF v_finance_case_id IS NOT NULL THEN
    INSERT INTO public.pay_finance_case_events (
      finance_case_id,
      event_type,
      event_at_utc,
      actor_user_id,
      before_json,
      after_json,
      reason,
      note
    )
    VALUES (
      v_finance_case_id,
      'SNOOZE_CLEARED',
      now(),
      p_actor_user_id,
      v_before,
      v_after,
      COALESCE(v_row.snooze_kind, 'SNOOZE_CLEARED'),
      v_row.note
    );

    PERFORM public._audit_insert(
      'finance_case',
      v_finance_case_id::text,
      'SNOOZE_CLEARED',
      v_before,
      v_after,
      COALESCE(v_row.snooze_kind, 'SNOOZE_CLEARED'),
      p_actor_user_id
    );
  ELSIF v_row.timesheet_id IS NOT NULL THEN
    PERFORM public._audit_insert(
      'timesheets',
      v_row.timesheet_id::text,
      'SNOOZE_CLEARED',
      v_before,
      v_after,
      COALESCE(v_row.snooze_kind, 'SNOOZE_CLEARED'),
      p_actor_user_id
    );
  ELSE
    PERFORM public._audit_insert(
      'pay_item_snoozes',
      v_row.id::text,
      'SNOOZE_CLEARED',
      v_before,
      v_after,
      COALESCE(v_row.snooze_kind, 'SNOOZE_CLEARED'),
      p_actor_user_id
    );
  END IF;

  RETURN
    jsonb_build_object(
      'ok', true,
      'action', 'CLEARED',
      'id', v_row.id::text,
      'candidate_id', v_row.candidate_id::text,
      'timesheet_id', CASE WHEN v_row.timesheet_id IS NULL THEN NULL ELSE v_row.timesheet_id::text END,
      'segment_id', v_row.segment_id,
      'source_ref', v_row.source_ref,
      'finance_case_id', CASE WHEN v_finance_case_id IS NULL THEN NULL ELSE v_finance_case_id::text END,
      'snooze_kind', v_row.snooze_kind,
      'preview_visibility_hint', 'RELOAD_PREVIEW'
    )
    ||
    jsonb_build_object(
      'schedule_before_restore_json', v_schedule_before_restore_json,
      'next_due_week_start_before_restore', v_next_due_week_start_before_restore,
      'requested_week_start', v_requested_week_start,
      'current_operating_week_start', v_current_operating_week_start,
      'schedule_after_restore_json', v_schedule_after_restore_json,
      'next_due_week_start_after_restore', v_next_due_week_start_after_restore,
      'installment_count', v_installment_count
    );
END;
$$;



CREATE OR REPLACE FUNCTION public.pay_snoozes_list(
  p_candidate_id uuid DEFAULT NULL,
  p_active_only boolean DEFAULT true,
  p_limit int DEFAULT 200,
  p_offset int DEFAULT 0,
  p_client_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_limit int := greatest(1, least(coalesce(p_limit,200), 500));
  v_offset int := greatest(coalesce(p_offset,0), 0);
  v_total int := 0;
  v_rows jsonb := '[]'::jsonb;
BEGIN
  WITH base AS (
    SELECT
      s.id,
      s.candidate_id,
      s.timesheet_id,
      s.segment_id,
      s.source_ref,
      upper(COALESCE(s.snooze_kind,'')) AS snooze_kind,
      s.snooze_until_date,
      s.note,
      s.created_at_utc,
      s.created_by_user_id,
      s.updated_at_utc,
      s.updated_by_user_id,
      s.cleared_at_utc,
      s.cleared_by_user_id,
      CASE
        WHEN s.source_ref IS NOT NULL
         AND s.source_ref LIKE 'advance:%'
         AND split_part(s.source_ref, ':', 2) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        THEN split_part(s.source_ref, ':', 2)::uuid
        ELSE NULL
      END AS finance_case_id
    FROM public.pay_item_snoozes s
    WHERE (p_candidate_id IS NULL OR s.candidate_id = p_candidate_id)
      AND (coalesce(p_active_only,true) = false OR s.cleared_at_utc IS NULL)
  ),
  enriched AS (
    SELECT
      b.id,
      b.candidate_id,
      c.tms_ref AS candidate_tms_ref,
      c.display_name AS candidate_display_name,
      b.timesheet_id,
      ts.week_ending_date,
      tf.client_id AS timesheet_client_id,
      cli_tf.name AS timesheet_client_name,
      b.segment_id,
      b.source_ref,
      b.finance_case_id,
      vfc.case_type,
      vfc.client_id AS finance_client_id,
      vfc.client_name AS finance_client_name,
      vfc.linked_shift_date,
      vfc.adjustment_comment,
      vfc.status AS finance_case_status,
      vfc.payout_status AS finance_case_payout_status,
      vfc.outstanding_amount,
      vfc.active_snooze_until_date,
      b.snooze_kind,
      b.snooze_until_date,
      b.note,
      b.created_at_utc,
      b.created_by_user_id,
      b.updated_at_utc,
      b.updated_by_user_id,
      b.cleared_at_utc,
      b.cleared_by_user_id,
      CASE
        WHEN b.finance_case_id IS NOT NULL THEN
          CASE vfc.case_type
            WHEN 'PAYMENT_ADVANCE' THEN 'PAYMENT_ADVANCE_REPAYMENT'
            WHEN 'OVERPAYMENT' THEN 'OVERPAYMENT_RECOVERY'
            WHEN 'MANUAL_DEBT_ADJUSTMENT' THEN 'MANUAL_DEBT_RECOVERY'
            WHEN 'MANUAL_CREDIT_ADJUSTMENT' THEN 'MANUAL_CREDIT_ADJUSTMENT'
            ELSE 'FINANCE_CASE'
          END
        WHEN b.snooze_kind = 'TIMESHEET_PAYMENT' THEN 'TIMESHEET_PAYMENT'
        WHEN b.snooze_kind = 'BLOCKED_TIMESHEET' THEN 'BLOCKED_TIMESHEET'
        WHEN b.snooze_kind = 'DO_NOT_PAY' THEN 'DO_NOT_PAY'
        ELSE 'SNOOZE'
      END AS line_type,
      CASE
        WHEN b.finance_case_id IS NOT NULL THEN
          CASE vfc.case_type
            WHEN 'PAYMENT_ADVANCE' THEN 'Payment Advance Repayment'
            WHEN 'OVERPAYMENT' THEN 'Overpayment Recovery'
            WHEN 'MANUAL_DEBT_ADJUSTMENT' THEN 'Manual Debt Adjustment Recovery'
            WHEN 'MANUAL_CREDIT_ADJUSTMENT' THEN 'Manual Credit Adjustment'
            ELSE 'Finance item'
          END
        WHEN b.snooze_kind = 'TIMESHEET_PAYMENT' THEN 'Timesheet payment'
        WHEN b.snooze_kind = 'BLOCKED_TIMESHEET' THEN 'Blocked timesheet line'
        WHEN b.snooze_kind = 'DO_NOT_PAY' THEN 'Do not pay line'
        ELSE 'Snoozed item'
      END AS line_label,
      CASE
        WHEN b.finance_case_id IS NOT NULL THEN
          trim(
            both ' '
            from concat(
              CASE vfc.case_type
                WHEN 'PAYMENT_ADVANCE' THEN 'Payment Advance Repayment'
                WHEN 'OVERPAYMENT' THEN 'Overpayment Recovery'
                WHEN 'MANUAL_DEBT_ADJUSTMENT' THEN 'Manual Debt Adjustment Recovery'
                WHEN 'MANUAL_CREDIT_ADJUSTMENT' THEN 'Manual Credit Adjustment'
                ELSE 'Finance item'
              END,
              CASE
                WHEN nullif(btrim(coalesce(vfc.adjustment_comment,'')), '') IS NOT NULL
                  THEN ' - ' || nullif(btrim(coalesce(vfc.adjustment_comment,'')), '')
                ELSE ''
              END
            )
          )
        WHEN b.snooze_kind = 'TIMESHEET_PAYMENT' THEN 'Timesheet payment'
        WHEN b.snooze_kind = 'BLOCKED_TIMESHEET' THEN
          CASE
            WHEN nullif(btrim(coalesce(b.segment_id,'')), '') IS NOT NULL THEN 'Blocked timesheet line - ' || b.segment_id
            ELSE 'Blocked timesheet line'
          END
        WHEN b.snooze_kind = 'DO_NOT_PAY' THEN
          CASE
            WHEN nullif(btrim(coalesce(b.segment_id,'')), '') IS NOT NULL THEN 'Do not pay line - ' || b.segment_id
            ELSE 'Do not pay line'
          END
        ELSE 'Snoozed item'
      END AS line_description,
      (b.snooze_until_date IS NULL) AS snooze_is_indefinite,
      (
        b.cleared_at_utc IS NULL
        AND (b.snooze_until_date IS NULL OR b.snooze_until_date >= current_date)
      ) AS is_currently_effective,
      CASE
        WHEN b.cleared_at_utc IS NOT NULL THEN 'CLEARED_HISTORY'
        WHEN b.snooze_until_date IS NULL THEN 'LOANS_SNOOZES_ONLY'
        WHEN b.snooze_until_date >= current_date THEN 'PREVIEW_VISIBLE_EXCLUDED'
        ELSE 'PREVIEW_ELIGIBLE'
      END AS visibility_hint
    FROM base b
    JOIN public.candidates c
      ON c.id = b.candidate_id
    LEFT JOIN public.timesheets ts
      ON ts.timesheet_id = b.timesheet_id
    LEFT JOIN public.timesheets_financials tf
      ON tf.timesheet_id = b.timesheet_id
     AND tf.is_current = true
    LEFT JOIN public.clients cli_tf
      ON cli_tf.id = tf.client_id
    LEFT JOIN public.v_finance_cases_register vfc
      ON vfc.finance_case_id = b.finance_case_id
  )
  SELECT count(*)::int
  INTO v_total
  FROM enriched e
  WHERE (p_client_id IS NULL OR COALESCE(e.finance_client_id, e.timesheet_client_id) = p_client_id);

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', e.id::text,
        'candidate_id', e.candidate_id::text,
        'candidate_tms_ref', e.candidate_tms_ref,
        'candidate_display_name', e.candidate_display_name,
        'client_id', CASE WHEN COALESCE(e.finance_client_id, e.timesheet_client_id) IS NULL THEN NULL ELSE COALESCE(e.finance_client_id, e.timesheet_client_id)::text END,
        'client_name', COALESCE(e.finance_client_name, e.timesheet_client_name),
        'timesheet_id', CASE WHEN e.timesheet_id IS NULL THEN NULL ELSE e.timesheet_id::text END,
        'week_ending_date', CASE WHEN e.week_ending_date IS NULL THEN NULL ELSE e.week_ending_date::text END,
        'linked_shift_date', CASE WHEN e.linked_shift_date IS NULL THEN NULL ELSE e.linked_shift_date::text END,
        'segment_id', e.segment_id,
        'source_ref', e.source_ref,
        'finance_case_id', CASE WHEN e.finance_case_id IS NULL THEN NULL ELSE e.finance_case_id::text END,
        'case_type', e.case_type,
        'finance_case_status', e.finance_case_status,
        'finance_case_payout_status', e.finance_case_payout_status,
        'finance_case_outstanding_amount', e.outstanding_amount,
        'adjustment_comment', e.adjustment_comment,
        'line_type', e.line_type,
        'line_label', e.line_label,
        'line_description', e.line_description,
        'snooze_kind', e.snooze_kind,
        'snooze_until_date', CASE WHEN e.snooze_until_date IS NULL THEN NULL ELSE e.snooze_until_date::text END,
        'snooze_is_indefinite', e.snooze_is_indefinite,
        'is_currently_effective', e.is_currently_effective,
        'visibility_hint', e.visibility_hint,
        'note', e.note,
        'created_at_utc', e.created_at_utc,
        'created_by_user_id', CASE WHEN e.created_by_user_id IS NULL THEN NULL ELSE e.created_by_user_id::text END,
        'updated_at_utc', e.updated_at_utc,
        'updated_by_user_id', CASE WHEN e.updated_by_user_id IS NULL THEN NULL ELSE e.updated_by_user_id::text END,
        'cleared_at_utc', e.cleared_at_utc,
        'cleared_by_user_id', CASE WHEN e.cleared_by_user_id IS NULL THEN NULL ELSE e.cleared_by_user_id::text END,
        'action_flags', jsonb_build_object(
          'can_clear', e.cleared_at_utc IS NULL,
          'can_amend_date', e.cleared_at_utc IS NULL,
          'can_set_indefinite', e.cleared_at_utc IS NULL AND e.snooze_until_date IS NOT NULL,
          'can_set_dated', e.cleared_at_utc IS NULL AND e.snooze_until_date IS NULL
        )
      )
      ORDER BY e.created_at_utc DESC, e.id DESC
    ),
    '[]'::jsonb
  )
  INTO v_rows
  FROM (
    SELECT e.*
    FROM enriched e
    WHERE (p_client_id IS NULL OR COALESCE(e.finance_client_id, e.timesheet_client_id) = p_client_id)
    ORDER BY e.created_at_utc DESC, e.id DESC
    LIMIT v_limit OFFSET v_offset
  ) e;

  RETURN jsonb_build_object(
    'ok', true,
    'total_count', v_total,
    'limit', v_limit,
    'offset', v_offset,
    'rows', v_rows
  );
END;
$$;








-- =========================================================
-- A4.1 pay_preview(p_pay_date date, p_actor_user_id uuid)
-- UPDATED LOGIC FULLY APPLIED:
--  - Uses effective require_reference_to_pay = COALESCE(CASE WHEN ct.overrideclientsettings THEN ct.require_reference_to_pay END, cs.pay_reference_required, false)
--  - Segment-level reference gating using invoice_breakdown_json.segments[].ref_num (fallback uses timesheets.reference_number for non-SEGMENTS mode)
--  - Returns BLOCKED items (missing ref_num where required AND delta > 0) instead of filtering them out
--  - Returns DO_NOT_PAY items (exclude_from_pay=true), including those with no delta (informational)
--  - Applies snoozing via public.pay_item_snoozes:
--      * snooze_kind='BLOCKED' for blocked items
--      * snooze_kind='DO_NOT_PAY' for do-not-pay items
--    Active snooze: cleared_at_utc IS NULL AND (snooze_until_date IS NULL OR snooze_until_date >= p_pay_date)
--    Suppression rule:
--      * BLOCKED: suppressed if snoozed (always)
--      * DO_NOT_PAY: suppressed if snoozed AND raw_delta = 0 (informational-only)
--  - Payable deltas exclude blocked-positive segments (delta forced to 0) but still show them in blocked_items list
-- =========================================================




-- =========================================================
-- A4.2 pay_create_draft_batch(p_pay_date, p_actor_user_id, p_preview_decisions_json)
-- UPDATED LOGIC FULLY APPLIED:
--  - Candidate selection uses pay_preview but only includes candidates with has_any_delta=true
--  - Segment-level ref gating identical to pay_preview:
--      * Missing ref_num where required blocks ONLY positive delta for that segment (excluded from payable items)
--  - Uses effective require_reference_to_pay (overrideclientsettings-aware, client_settings fallback)
--  - Does not filter out missing refs at timesheet level
-- =========================================================






CREATE OR REPLACE FUNCTION public.pay_preview(
  p_pay_date date,
  p_week_ending_cutoff date,
  p_actor_user_id uuid,
  p_candidate_id uuid DEFAULT NULL::uuid,
  p_client_id uuid DEFAULT NULL::uuid,
  p_preview_decisions_json jsonb DEFAULT NULL::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_preview_decisions_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_preview_decisions_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_preview_decisions_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_requested_mode text := UPPER(NULLIF(BTRIM(COALESCE(
    v_preview_decisions_json->>'preview_mode',
    v_preview_decisions_json->>'detail_mode',
    v_preview_decisions_json->>'mode',
    'SUMMARY'
  )), ''));
  v_context_json jsonb := '{}'::jsonb;
  v_full_context_json jsonb := '{}'::jsonb;
  v_scope_candidate_ids jsonb := '[]'::jsonb;
  v_candidate_rollups_json jsonb := '[]'::jsonb;
  v_scope_candidate_id_text text := '';
  v_candidate_baseline_json jsonb := '{}'::jsonb;
  v_candidate_effective_json jsonb := '{}'::jsonb;
  v_candidate_rollup_json jsonb := '{}'::jsonb;
  v_scope_candidate_count integer := 0;
  v_scope_page_count integer := 0;
  v_tiny_compat_threshold integer := 5;
  v_full_compat_requested boolean := false;
  v_scope_limit integer := 100;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('PREVIEW_PROGRESS');

  IF p_pay_date IS NULL THEN
    RAISE EXCEPTION 'PAY_PREVIEW_PAY_DATE_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_PREVIEW_PAY_DATE_REQUIRED')::text;
  END IF;

  IF v_requested_mode NOT IN ('SUMMARY', 'PAGE', 'FULL_COMPAT') THEN
    v_requested_mode := 'SUMMARY';
  END IF;

  v_full_compat_requested := (v_requested_mode = 'FULL_COMPAT');

  IF COALESCE(v_preview_decisions_json->>'scope_limit', '') ~ '^[0-9]+$' THEN
    v_scope_limit := LEAST(GREATEST((v_preview_decisions_json->>'scope_limit')::integer, 1), 100);
  ELSE
    v_scope_limit := 100;
  END IF;

  /*
    5.1: pay_preview is now strictly a pre-draft entry point.

    Normal Banking modal usage gets compact bootstrap/progress metadata and must
    page through the row-backed workbench/session APIs.  Full legacy preview
    payloads are only produced for tiny compatibility scopes.
  */
  v_context_json := public.pay_preview_build_context(
    p_pay_date => p_pay_date,
    p_week_ending_cutoff => p_week_ending_cutoff,
    p_actor_user_id => p_actor_user_id,
    p_candidate_id => p_candidate_id,
    p_client_id => p_client_id,
    p_preview_decisions_json => v_preview_decisions_json
      || jsonb_build_object(
        'preview_context_mode', CASE WHEN v_requested_mode = 'PAGE' THEN 'PAGE' ELSE 'SUMMARY' END,
        'scope_limit', v_scope_limit
      )
  );

  IF jsonb_typeof(v_context_json) <> 'object' THEN
    RAISE EXCEPTION 'pay_preview_build_context must return a JSON object';
  END IF;

  v_scope_candidate_count := COALESCE(NULLIF(BTRIM(COALESCE(v_context_json->>'scope_candidate_count', '')), '')::integer, 0);
  v_scope_page_count := COALESCE(NULLIF(BTRIM(COALESCE(v_context_json->>'scope_page_count', '')), '')::integer, 0);

  IF v_full_compat_requested IS NOT TRUE
     OR COALESCE(v_scope_candidate_count, 0) > v_tiny_compat_threshold THEN
    RETURN jsonb_build_object(
      'ok', true,
      'preview_mode', CASE WHEN v_full_compat_requested THEN 'SUMMARY_FULL_COMPAT_SUPPRESSED' ELSE v_requested_mode END,
      'pre_draft', true,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
      'bootstrap_only', true,
      'full_preview_payload_returned', false,
      'full_preview_payload_suppressed', true,
      'tiny_compat_threshold', v_tiny_compat_threshold,
      'scope_candidate_count', COALESCE(v_scope_candidate_count, 0),
      'scope_page_count', COALESCE(v_scope_page_count, 0),
      'scope_has_more', COALESCE(NULLIF(v_context_json->>'scope_has_more', '')::boolean, false),
      'scope_next_cursor', COALESCE(v_context_json->'scope_next_cursor', NULL::jsonb),
      'workbench_session_paging_required', true,
      'recommended_next_api', 'pay_workbench_session_open',
      'recommended_page_api', 'pay_workbench_session_seed_scope_chunk',
      'context', v_context_json,
      'generated_at_utc', v_now::text
    );
  END IF;

  /*
    Tiny legacy compatibility path only.  This remains pre-draft and uses the
    existing live preview functions.  Larger Banking modal requests must use
    row-backed workbench paging.
  */
  v_full_context_json := public.pay_preview_build_context(
    p_pay_date => p_pay_date,
    p_week_ending_cutoff => p_week_ending_cutoff,
    p_actor_user_id => p_actor_user_id,
    p_candidate_id => p_candidate_id,
    p_client_id => p_client_id,
    p_preview_decisions_json => v_preview_decisions_json || jsonb_build_object('preview_context_mode', 'FULL_COMPAT')
  );

  v_scope_candidate_ids := CASE
    WHEN jsonb_typeof(v_full_context_json->'scope_candidate_ids') = 'array' THEN COALESCE(v_full_context_json->'scope_candidate_ids', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  FOR v_scope_candidate_id_text IN
    SELECT BTRIM(scope_candidate.value)
    FROM jsonb_array_elements_text(v_scope_candidate_ids) AS scope_candidate(value)
    WHERE BTRIM(scope_candidate.value) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ORDER BY BTRIM(scope_candidate.value)
  LOOP
    v_candidate_baseline_json := public.pay_preview_build_candidate_baseline(
      p_context_json => v_full_context_json,
      p_candidate_id => v_scope_candidate_id_text::uuid
    );

    v_candidate_effective_json := public.pay_preview_apply_candidate_overlay(
      p_candidate_baseline_json => v_candidate_baseline_json,
      p_case_resolutions_json => COALESCE(v_full_context_json->'preview_case_resolutions', '{}'::jsonb),
      p_overrides_json => COALESCE(v_full_context_json->'preview_decisions_json', '{}'::jsonb)
    );

    v_candidate_rollup_json := public.pay_preview_build_candidate_rollup(
      p_context_json => v_full_context_json,
      p_candidate_effective_json => v_candidate_effective_json
    );

    v_candidate_rollups_json := v_candidate_rollups_json || jsonb_build_array(v_candidate_rollup_json);
  END LOOP;

  RETURN public.pay_preview_assemble_payload(
    p_context_json => v_full_context_json || jsonb_build_object(
      'preview_mode', 'FULL_COMPAT',
      'pre_draft', true,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
      'full_preview_payload_returned', true,
      'tiny_compat_threshold', v_tiny_compat_threshold
    ),
    p_candidate_rollups_json => v_candidate_rollups_json
  );
END;
$function$;
















CREATE OR REPLACE FUNCTION public.pay_create_draft_batch(
  p_pay_date date,
  p_week_ending_cutoff date,
  p_pay_channel_scope text,
  p_actor_user_id uuid,
  p_preview_decisions_json jsonb,
  p_candidate_id uuid default null,
  p_client_id uuid default null,
  p_force_include_timesheet_ids uuid[] default null,
  p_override_reason text default null,
  p_override_mode public.pay_override_mode_enum default 'NONE'
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_scope text := upper(btrim(coalesce(p_pay_channel_scope,'')));

  v_week_start date := public._pay_week_start_monday(p_pay_date);

  -- ✅ UK “today” anchor for eligibility window (Option A)
  v_today_uk date := (now() at time zone 'Europe/London')::date;

  -- ✅ UTC now anchor (timestamptz)
  v_now_utc timestamptz := now();

  -- ✅ Eligibility window knobs (from settings_defaults; fallback to defaults if column absent)
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;

  -- ✅ Computed eligibility window
  v_eligibility_from_date date;
  v_eligibility_to_date date;

  -- ✅ Optional filters (single candidate/client)
  v_candidate_filter_single uuid := p_candidate_id;
  v_client_filter_single uuid := p_client_id;
  v_filter_text text;

  v_vat_rate_pct numeric;
  v_erni_pct numeric;

  v_settings record;

  v_need_name_check boolean := false;

  v_requires_payee_map boolean := false;

  v_blocked_candidates jsonb := '[]'::jsonb;

  v_batch_id uuid;

  v_candidate_ids uuid[] := array[]::uuid[];
  v_candidate_filter uuid[] := null;

  v_component_resolutions jsonb := coalesce(p_preview_decisions_json->'component_resolutions','null'::jsonb);
  v_reserved jsonb := '[]'::jsonb;
  v_blocked_case_states jsonb := '[]'::jsonb;

  -- loan/debt loop vars (kept at function scope; NO nested DO blocks)
  v_rec record;
  v_min_take numeric;
  v_max_ded numeric;
  v_gross_main numeric;
  v_remaining numeric;
  v_adv record;
  v_sched_amt numeric;
  v_take_amt numeric;
  v_pbci uuid;
  v_cand_pm text;
  v_cand_umb uuid;

  v_sum_scope numeric;
  v_debt_scope numeric;

  -- breakdown integrity vars
  v_breakdown_missing_ct int := 0;
  v_breakdown_bad_ct int := 0;
  v_breakdown_bad jsonb := '[]'::jsonb;

  ----------------------------------------------------------------
  -- DEBUG / AUDIT vars (non-functional)
  ----------------------------------------------------------------
  v_stage text := 'INIT';
  v_rows int := 0;
  v_rows_ins_items int := 0;
  v_rows_ins_candidates int := 0;
  v_rows_del_candidates int := 0;
  v_rows_upd_candidates_loan int := 0;
  v_rows_ins_loan_items int := 0;
  v_rows_upd_candidates_paye_awaiting int := 0;
  v_rows_ins_overpayment_recovery_items int := 0;
  v_rows_upd_candidates_overpayment_recovery_taken int := 0;
  v_rows_ins_underpayment_items int := 0;
  v_rows_ins_debt_items int := 0;
  v_rows_ins_loan_payout_items int := 0;
  v_rows_ins_manual_credit_payout_items int := 0;
  v_rows_upd_candidates_debt int := 0;
  v_rows_upd_candidates_summaries int := 0;
  v_rows_ins_snapshots int := 0;
  v_rows_ins_breakdowns int := 0;
  v_sample_candidate_ids jsonb := '[]'::jsonb;
  v_preview_candidate_filter_ct int := 0;
  v_preview_decisions_keys jsonb := '{}'::jsonb;
  v_selected_preview_row_ids text[] := array[]::text[];
  v_selected_preview_row_count int := 0;
  v_selected_preview_row_ids_present boolean := coalesce((p_preview_decisions_json ? 'selected_preview_row_ids'), false);
  v_selected_preview_rows_supplied boolean := false;
  v_selected_preview_rows_mode text := 'IMPLICIT_ALL';
  v_selected_preview_rows_pre_selection_ct int := 0;
  v_selected_preview_rows_post_selection_ct int := 0;
  v_candidate_rows_before_empty_delete int := 0;
  v_candidate_rows_after_empty_delete int := 0;
-- ✅ Optional: timesheet_ids to exclude from drafting (non-blocking TSFIN path)
v_exclude_timesheet_ids uuid[] := array[]::uuid[];
v_exclude_ts_raw text;
v_exclude_ts_uuid uuid;
v_overpayment_sync jsonb := '{}'::jsonb;
v_component_resolution_apply_result jsonb := '{}'::jsonb;
v_component_resolutions_supplied boolean := coalesce((p_preview_decisions_json ? 'component_resolutions'), false);
v_component_resolutions_input_type text := coalesce(jsonb_typeof(p_preview_decisions_json->'component_resolutions'), 'null');
v_component_resolution_input_entry_count int := 0;
v_component_resolution_candidate_count int := 0;
v_component_resolution_rows_parsed int := 0;
v_component_resolution_apply_candidate_count int := 0;
v_component_resolution_rows_applied int := 0;
v_component_resolution_rows_skipped int := 0;
v_component_resolution_invalid_sample jsonb := '[]'::jsonb;
v_negative_preview_timesheets_count int := 0;
v_rows_upd_timesheet_overrides_consumed int := 0;
v_consumed_timesheet_payment_overrides jsonb := '[]'::jsonb;
v_stage_15_reserved_key_count int := 0;
v_stage_15_outstanding_key_count int := 0;
v_stage_15_current_batch_key_count int := 0;
v_stage_15_reserved_keys_sample jsonb := '[]'::jsonb;
v_stage_15_outstanding_keys_sample jsonb := '[]'::jsonb;
v_stage_15_current_batch_keys_sample jsonb := '[]'::jsonb;
v_stage_15_ts_ids_sample jsonb := '[]'::jsonb;
v_stage_15_current_batch_items_sample jsonb := '[]'::jsonb;
v_stage_15_current_batch_keyed_sample jsonb := '[]'::jsonb;
v_stage_15_checks_sample jsonb := '[]'::jsonb;
v_override_consume_rec record;
v_component_resolution_candidate record;
  v_payout_instruction_freeze_rec record;
begin
  v_stage := 'STAGE_00_INPUTS';

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_00_INPUTS',
      jsonb_build_object(
        'pay_date', coalesce(p_pay_date::text, null),
        'week_ending_cutoff', coalesce(p_week_ending_cutoff::text, null),
        'pay_channel_scope_raw', coalesce(p_pay_channel_scope, null),
        'scope_norm', coalesce(v_scope, null),
        'actor_user_id', coalesce(p_actor_user_id::text, null),
        'candidate_id_param', coalesce(p_candidate_id::text, null),
        'client_id_param', coalesce(p_client_id::text, null),
        'preview_decisions_json_type', jsonb_typeof(p_preview_decisions_json),
        'preview_decisions_json_keys_sample', (
          select coalesce(jsonb_agg(k.key order by k.key), '[]'::jsonb)
          from (
            select e.key
            from jsonb_each(coalesce(p_preview_decisions_json,'{}'::jsonb)) e
            order by e.key
            limit 50
          ) k
        )
      ),
      'pay_create_draft_batch',
      coalesce('pay_date:'||p_pay_date::text, 'pay_date:null'),
      null,
      null,
      null,
      null,
      null
    );

-- ✅ Parse exclude_timesheet_ids from preview decisions (silent on invalid UUID strings)
begin
  if p_preview_decisions_json is not null
     and jsonb_typeof(p_preview_decisions_json) = 'object'
     and (p_preview_decisions_json ? 'exclude_timesheet_ids')
     and jsonb_typeof(p_preview_decisions_json->'exclude_timesheet_ids') = 'array'
  then
    for v_exclude_ts_raw in
      select jsonb_array_elements_text(p_preview_decisions_json->'exclude_timesheet_ids')
    loop
      begin
        v_exclude_ts_uuid := nullif(btrim(coalesce(v_exclude_ts_raw,'')),'')::uuid;
        if v_exclude_ts_uuid is not null then
          v_exclude_timesheet_ids := array_append(v_exclude_timesheet_ids, v_exclude_ts_uuid);
        end if;
      exception when others then
        null;
      end;
    end loop;
  end if;

  v_exclude_timesheet_ids := coalesce(
    (
      select array_agg(distinct t.x)
      from unnest(coalesce(v_exclude_timesheet_ids, array[]::uuid[])) as t(x)
    ),
    array[]::uuid[]
  );
exception when others then
  v_exclude_timesheet_ids := array[]::uuid[];
end;

  exception when others then
    null;
  end;

  if p_pay_date is null then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_PAY_DATE_REQUIRED',
        jsonb_build_object(
          'stage', v_stage,
          'error', 'pay_date is required'
        ),
        'pay_create_draft_batch',
        'pay_date:null',
        null, null, null, null, null
      );
    exception when others then null; end;

    raise exception 'pay_date is required';
  end if;

  if p_week_ending_cutoff is null then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_WEEK_ENDING_CUTOFF_REQUIRED',
        jsonb_build_object(
          'stage', v_stage,
          'pay_date', p_pay_date::text,
          'error', 'week_ending_cutoff is required'
        ),
        'pay_create_draft_batch',
        'pay_date:'||p_pay_date::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    raise exception 'week_ending_cutoff is required';
  end if;

  if v_scope not in ('PAYE','UMBRELLA') then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_INVALID_SCOPE',
        jsonb_build_object(
          'stage', v_stage,
          'pay_date', p_pay_date::text,
          'scope_norm', v_scope,
          'error', 'Invalid pay_channel_scope (expected PAYE or UMBRELLA)'
        ),
        'pay_create_draft_batch',
        'pay_date:'||p_pay_date::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    raise exception 'Invalid pay_channel_scope (expected PAYE or UMBRELLA)';
  end if;

  if to_regclass('public.settings_defaults') is null then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_SETTINGS_DEFAULTS_MISSING',
        jsonb_build_object(
          'stage', v_stage,
          'pay_date', p_pay_date::text,
          'error', 'settings_defaults missing'
        ),
        'pay_create_draft_batch',
        'pay_date:'||p_pay_date::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    raise exception 'settings_defaults missing';
  end if;
  if to_regclass('public.settings_finance_windows') is null then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_SETTINGS_FINANCE_WINDOWS_MISSING',
        jsonb_build_object(
          'stage', v_stage,
          'pay_date', p_pay_date::text,
          'error', 'settings_finance_windows missing'
        ),
        'pay_create_draft_batch',
        'pay_date:'||p_pay_date::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    raise exception 'settings_finance_windows missing';
  end if;

  v_stage := 'STAGE_01_FILTERS_BACKCOMPAT';

  -- Optional filters can be supplied via preview_decisions_json for backward-compatible callers
  begin
    if v_candidate_filter_single is null then
      v_filter_text := nullif(btrim(coalesce(p_preview_decisions_json->>'candidate_filter_id','')), '');
      if v_filter_text is not null then
        v_candidate_filter_single := v_filter_text::uuid;
      end if;
    end if;

    if v_client_filter_single is null then
      v_filter_text := nullif(btrim(coalesce(p_preview_decisions_json->>'client_filter_id','')), '');
      if v_filter_text is not null then
        v_client_filter_single := v_filter_text::uuid;
      end if;
    end if;

    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:STAGE_01_FILTERS_BACKCOMPAT',
        jsonb_build_object(
          'stage', v_stage,
          'candidate_filter_single', coalesce(v_candidate_filter_single::text, null),
          'client_filter_single', coalesce(v_client_filter_single::text, null),
          'candidate_filter_id_raw', nullif(btrim(coalesce(p_preview_decisions_json->>'candidate_filter_id','')), ''),
          'client_filter_id_raw', nullif(btrim(coalesce(p_preview_decisions_json->>'client_filter_id','')), '')
        ),
        'pay_create_draft_batch',
        'pay_date:'||p_pay_date::text,
        null, null, null, null, null
      );
    exception when others then null; end;

  exception when invalid_text_representation then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_INVALID_FILTER_UUID',
        jsonb_build_object(
          'stage', v_stage,
          'candidate_filter_id_raw', nullif(btrim(coalesce(p_preview_decisions_json->>'candidate_filter_id','')), ''),
          'client_filter_id_raw', nullif(btrim(coalesce(p_preview_decisions_json->>'client_filter_id','')), ''),
          'error', 'Invalid candidate_filter_id/client_filter_id (must be UUID)'
        ),
        'pay_create_draft_batch',
        'pay_date:'||p_pay_date::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    raise exception 'Invalid candidate_filter_id/client_filter_id (must be UUID)';
  end;

  v_stage := 'STAGE_02_FINANCE_WINDOW';

  select
    sfw.vat_rate_pct,
    sfw.erni_pct
  into
    v_vat_rate_pct,
    v_erni_pct
  from public.settings_finance_windows sfw
  where p_pay_date >= sfw.date_from
    and p_pay_date <= coalesce(sfw.date_to, 'infinity'::date)
  order by sfw.date_from desc
  limit 1;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_02_FINANCE_WINDOW',
      jsonb_build_object(
        'stage', v_stage,
        'pay_date', p_pay_date::text,
        'vat_rate_pct', v_vat_rate_pct,
        'erni_pct', v_erni_pct
      ),
      'pay_create_draft_batch',
      'pay_date:'||p_pay_date::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  if v_vat_rate_pct is null or v_erni_pct is null then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_NO_FINANCE_WINDOW',
        jsonb_build_object(
          'stage', v_stage,
          'pay_date', p_pay_date::text,
          'vat_rate_pct', v_vat_rate_pct,
          'erni_pct', v_erni_pct,
          'error', 'No finance window found'
        ),
        'pay_create_draft_batch',
        'pay_date:'||p_pay_date::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    raise exception 'No finance window found for pay_date %', p_pay_date;
  end if;

  v_stage := 'STAGE_03_SETTINGS_DEFAULTS';

  select
    sd.banking_system,
    sd.external_paye_system,
    sd.rail_provider_default,
    sd.rail_env_default,
    sd.rail_supports_name_check
  into v_settings
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_03_SETTINGS_DEFAULTS',
      jsonb_build_object(
        'stage', v_stage,
        'banking_system', coalesce(v_settings.banking_system, null),
        'external_paye_system', coalesce(v_settings.external_paye_system, null),
        'rail_provider_default', coalesce(v_settings.rail_provider_default, null),
        'rail_env_default', coalesce(v_settings.rail_env_default, null),
        'rail_supports_name_check', coalesce(v_settings.rail_supports_name_check, null)
      ),
      'settings_defaults',
      '1',
      null, null, null, null, null
    );
  exception when others then null; end;

  if v_settings.banking_system is null or v_settings.external_paye_system is null then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_SETTINGS_DEFAULTS_MISSING_BANKING_EXTERNAL_PAYE',
        jsonb_build_object(
          'stage', v_stage,
          'banking_system', coalesce(v_settings.banking_system, null),
          'external_paye_system', coalesce(v_settings.external_paye_system, null),
          'error', 'settings_defaults missing banking_system/external_paye_system'
        ),
        'settings_defaults',
        '1',
        null, null, null, null, null
      );
    exception when others then null; end;

    raise exception 'settings_defaults missing banking_system/external_paye_system';
  end if;

  if v_settings.rail_provider_default is null or v_settings.rail_env_default is null then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_SETTINGS_DEFAULTS_MISSING_RAIL_DEFAULTS',
        jsonb_build_object(
          'stage', v_stage,
          'rail_provider_default', coalesce(v_settings.rail_provider_default, null),
          'rail_env_default', coalesce(v_settings.rail_env_default, null),
          'error', 'settings_defaults missing rail_provider_default/rail_env_default'
        ),
        'settings_defaults',
        '1',
        null, null, null, null, null
      );
    exception when others then null; end;

    raise exception 'settings_defaults missing rail_provider_default/rail_env_default';
  end if;

  v_need_name_check := (coalesce(v_settings.rail_supports_name_check,false) = true)
                       and (upper(btrim(coalesce(v_settings.rail_provider_default,''))) <> 'CSV');

  v_requires_payee_map := (upper(btrim(coalesce(v_settings.rail_provider_default,''))) <> 'CSV');

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_03B_DERIVED_RAIL_FLAGS',
      jsonb_build_object(
        'stage', 'STAGE_03B_DERIVED_RAIL_FLAGS',
        'scope', v_scope,
        'rail_provider_default_norm', upper(btrim(coalesce(v_settings.rail_provider_default,''))),
        'rail_env_default_norm', upper(btrim(coalesce(v_settings.rail_env_default,''))),
        'need_name_check', v_need_name_check,
        'requires_payee_map', v_requires_payee_map
      ),
      'pay_create_draft_batch',
      'pay_date:'||p_pay_date::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  -- ✅ Load eligibility window knobs from settings_defaults (Option A)
  -- NOTE: use exception guard so function is robust even if column is absent at runtime.
  v_stage := 'STAGE_04_ELIGIBILITY_KNOBS';
  begin
    select
      sd.pay_eligibility_months_back,
      sd.pay_eligibility_weeks_ahead
    into
      v_pay_eligibility_months_back,
      v_pay_eligibility_weeks_ahead
    from public.settings_defaults sd
    where sd.id = 1
    limit 1;
  exception when undefined_column then
    v_pay_eligibility_months_back := 6;
    v_pay_eligibility_weeks_ahead := 2;
  end;

  v_pay_eligibility_months_back := greatest(0, least(120, coalesce(v_pay_eligibility_months_back, 6)));
  v_pay_eligibility_weeks_ahead := greatest(0, least(52,  coalesce(v_pay_eligibility_weeks_ahead, 2)));

  v_eligibility_from_date := (v_today_uk - (v_pay_eligibility_months_back::text || ' months')::interval)::date;
  v_eligibility_to_date   := (v_today_uk + (v_pay_eligibility_weeks_ahead::text || ' weeks')::interval)::date;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_04_ELIGIBILITY_WINDOW',
      jsonb_build_object(
        'stage', v_stage,
        'today_uk', v_today_uk::text,
        'pay_eligibility_months_back', v_pay_eligibility_months_back,
        'pay_eligibility_weeks_ahead', v_pay_eligibility_weeks_ahead,
        'eligibility_from_date', v_eligibility_from_date::text,
        'eligibility_to_date', v_eligibility_to_date::text,
        'week_ending_cutoff', p_week_ending_cutoff::text
      ),
      'pay_create_draft_batch',
      'pay_date:'||p_pay_date::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  v_stage := 'STAGE_05_CANDIDATE_FILTER_ARRAY';

  if jsonb_typeof(p_preview_decisions_json->'candidate_ids') = 'array' then
    select coalesce(array_agg((x::text)::uuid), array[]::uuid[])
    into v_candidate_filter
    from jsonb_array_elements_text(p_preview_decisions_json->'candidate_ids') x;
  end if;

  -- Treat empty array as "ALL" (null filter)
  if v_candidate_filter is not null and array_length(v_candidate_filter, 1) is null then
    v_candidate_filter := null;
  end if;

  if v_selected_preview_row_ids_present then
    if p_preview_decisions_json->'selected_preview_row_ids' is null
       or jsonb_typeof(p_preview_decisions_json->'selected_preview_row_ids') = 'null' then
      v_selected_preview_row_ids := array[]::text[];
      v_selected_preview_row_count := 0;
      v_selected_preview_rows_supplied := false;
      v_selected_preview_rows_mode := 'IMPLICIT_ALL';
    elsif jsonb_typeof(p_preview_decisions_json->'selected_preview_row_ids') = 'array' then
      select coalesce(
        array_agg(distinct row_id order by row_id),
        array[]::text[]
      )
      into v_selected_preview_row_ids
      from (
        select nullif(btrim(x), '') as row_id
        from jsonb_array_elements_text(p_preview_decisions_json->'selected_preview_row_ids') as q(x)
        where nullif(btrim(x), '') is not null
      ) as s;

      v_selected_preview_row_count := coalesce(array_length(v_selected_preview_row_ids, 1), 0);

      if v_selected_preview_row_count = 0 then
        raise exception 'preview_decisions_json.selected_preview_row_ids must not be an empty array when explicitly supplied';
      end if;

      v_selected_preview_rows_supplied := true;
      v_selected_preview_rows_mode := 'EXPLICIT_SUBSET';
    else
      raise exception 'preview_decisions_json.selected_preview_row_ids must be an array when supplied';
    end if;
  else
    v_selected_preview_row_ids := array[]::text[];
    v_selected_preview_row_count := 0;
    v_selected_preview_rows_supplied := false;
    v_selected_preview_rows_mode := 'IMPLICIT_ALL';
  end if;

  begin
    select coalesce(jsonb_agg(x.id order by x.id), '[]'::jsonb), count(*)::int
    into v_sample_candidate_ids, v_preview_candidate_filter_ct
    from (
      select u::text as id
      from unnest(coalesce(v_candidate_filter, array[]::uuid[])) u
      limit 50
    ) x;

    v_preview_decisions_keys := jsonb_build_object(
      'component_resolutions_type', jsonb_typeof(v_component_resolutions),
      'component_resolution_input_type', v_component_resolutions_input_type,
      'component_resolution_input_entry_count', case
        when jsonb_typeof(v_component_resolutions) = 'object' then (
          select count(*)::int
          from jsonb_each(v_component_resolutions)
        )
        when jsonb_typeof(v_component_resolutions) = 'array' then coalesce(jsonb_array_length(v_component_resolutions), 0)
        else 0
      end,
      'component_resolution_candidate_keys_sample', (
        case
          when jsonb_typeof(v_component_resolutions) = 'object' then (
            select coalesce(jsonb_agg(k.key_text order by k.key_text), '[]'::jsonb)
            from (
              select e.key as key_text
              from jsonb_each(v_component_resolutions) e
              where e.key is not null
              order by e.key
              limit 50
            ) k
          )
          when jsonb_typeof(v_component_resolutions) = 'array' then (
            select coalesce(jsonb_agg(k.key_text order by k.key_text), '[]'::jsonb)
            from (
              select nullif(btrim(coalesce(a.value->>'candidate_id','')), '') as key_text
              from jsonb_array_elements(v_component_resolutions) a(value)
              where jsonb_typeof(a.value) = 'object'
                and nullif(btrim(coalesce(a.value->>'candidate_id','')), '') is not null
              order by nullif(btrim(coalesce(a.value->>'candidate_id','')), '')
              limit 50
            ) k
          )
          else '[]'::jsonb
        end
      )
    );

    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_05_CANDIDATE_FILTER_ARRAY',
      jsonb_build_object(
        'stage', v_stage,
        'candidate_filter_array_ct', v_preview_candidate_filter_ct,
        'candidate_filter_array_sample', v_sample_candidate_ids,
        'candidate_filter_single', coalesce(v_candidate_filter_single::text, null),
        'client_filter_single', coalesce(v_client_filter_single::text, null),
        'selected_preview_row_ids_present', v_selected_preview_row_ids_present,
        'selected_preview_rows_supplied', v_selected_preview_rows_supplied,
        'selected_preview_rows_mode', v_selected_preview_rows_mode,
        'selected_preview_row_count', v_selected_preview_row_count,
        'preview_decisions_key_samples', v_preview_decisions_keys
      ),
      'pay_create_draft_batch',
      'pay_date:'||p_pay_date::text,
      null, null, null, null, null
    );
  exception when others then
    null;
  end;


  v_stage := 'STAGE_05B_BUILD_SELECTED_PREVIEW_ROWS';

  create temporary table if not exists pg_temp.tmp_pay_selected_preview_rows (
    preview_row_id text primary key,
    candidate_id uuid not null,
    finance_case_id uuid null,
    timesheet_id uuid null,
    client_id uuid null,
    line_type text null,
    case_type text null,
    pay_channel text null,
    paye_treatment text null,
    routing_kind text null,
    destination_label text null,
    taxability text null,
    beneficiary_name text null,
    masked_bank_account text null,
    bank_details_hash text null,
    item_direction text null,
    item_type_label text null,
    source_ref text null,
    preview_amount_ex_vat numeric(12,2) null,
    draftable boolean not null,
    snooze_allowed boolean not null,
    is_candidate_directed_oneoff_payout boolean not null,
    appears_on_umbrella_remittance boolean not null,
    generates_candidate_payment_advice boolean not null,
    case_components_json jsonb null
  ) on commit drop;

  truncate table pg_temp.tmp_pay_selected_preview_rows;

  with preview as (
    select public.pay_preview(p_pay_date, p_week_ending_cutoff, p_actor_user_id, p_candidate_id, p_client_id, p_preview_decisions_json) as j
  ),
  item_rows as (
    select
      nullif(btrim(coalesce(line_json->>'candidate_id','')), '')::uuid as candidate_id,
      line_json as item_json,
      coalesce(
        nullif(btrim(coalesce(line_json->>'preview_row_id','')), ''),
        nullif(btrim(coalesce(line_json->>'line_id','')), '')
      ) as preview_row_id,
      nullif(btrim(coalesce(line_json->>'client_id','')), '')::uuid as client_id,
      nullif(btrim(coalesce(line_json->>'finance_case_id','')), '')::uuid as finance_case_id,
      nullif(btrim(coalesce(line_json->>'timesheet_id','')), '')::uuid as timesheet_id
    from preview
    cross join lateral jsonb_array_elements(coalesce(preview.j->'canonical_preview_lines', '[]'::jsonb)) as line_json
    where nullif(btrim(coalesce(line_json->>'candidate_id','')), '') is not null
  )
  select count(distinct ir.preview_row_id)::int
  into v_selected_preview_rows_pre_selection_ct
  from item_rows ir
  where ir.preview_row_id is not null
    and (v_candidate_filter is null or ir.candidate_id = any(v_candidate_filter))
    and (v_candidate_filter_single is null or ir.candidate_id = v_candidate_filter_single)
    and (v_client_filter_single is null or ir.client_id = v_client_filter_single)
    and coalesce(nullif(ir.item_json->>'draftable','')::boolean, false) = true;

  insert into pg_temp.tmp_pay_selected_preview_rows (
    preview_row_id,
    candidate_id,
    finance_case_id,
    timesheet_id,
    client_id,
    line_type,
    case_type,
    pay_channel,
    paye_treatment,
    routing_kind,
    destination_label,
    taxability,
    beneficiary_name,
    masked_bank_account,
    bank_details_hash,
    item_direction,
    item_type_label,
    source_ref,
    preview_amount_ex_vat,
    draftable,
    snooze_allowed,
    is_candidate_directed_oneoff_payout,
    appears_on_umbrella_remittance,
    generates_candidate_payment_advice,
    case_components_json
  )
  with preview as (
    select public.pay_preview(p_pay_date, p_week_ending_cutoff, p_actor_user_id, p_candidate_id, p_client_id, p_preview_decisions_json) as j
  ),
  item_rows as (
    select
      nullif(btrim(coalesce(line_json->>'candidate_id','')), '')::uuid as candidate_id,
      line_json as item_json,
      coalesce(
        nullif(btrim(coalesce(line_json->>'preview_row_id','')), ''),
        nullif(btrim(coalesce(line_json->>'line_id','')), '')
      ) as preview_row_id,
      nullif(btrim(coalesce(line_json->>'client_id','')), '')::uuid as client_id,
      nullif(btrim(coalesce(line_json->>'finance_case_id','')), '')::uuid as finance_case_id,
      nullif(btrim(coalesce(line_json->>'timesheet_id','')), '')::uuid as timesheet_id
    from preview
    cross join lateral jsonb_array_elements(coalesce(preview.j->'canonical_preview_lines', '[]'::jsonb)) as line_json
    where nullif(btrim(coalesce(line_json->>'candidate_id','')), '') is not null
  )
  select distinct on (ir.preview_row_id)
    ir.preview_row_id,
    ir.candidate_id,
    ir.finance_case_id,
    ir.timesheet_id,
    ir.client_id,
    nullif(btrim(coalesce(ir.item_json->>'line_type','')), '') as line_type,
    nullif(btrim(coalesce(ir.item_json->>'case_type','')), '') as case_type,
    upper(btrim(coalesce(ir.item_json->>'pay_channel',''))) as pay_channel,
    upper(btrim(coalesce(ir.item_json->>'paye_treatment',''))) as paye_treatment,
    nullif(btrim(coalesce(ir.item_json->>'routing_kind','')), '') as routing_kind,
    nullif(btrim(coalesce(ir.item_json->>'destination_label','')), '') as destination_label,
    nullif(btrim(coalesce(ir.item_json->>'taxability','')), '') as taxability,
    nullif(btrim(coalesce(ir.item_json->>'beneficiary_name','')), '') as beneficiary_name,
    nullif(btrim(coalesce(ir.item_json->>'masked_bank_account','')), '') as masked_bank_account,
    nullif(btrim(coalesce(ir.item_json->>'bank_details_hash','')), '') as bank_details_hash,
    nullif(btrim(coalesce(ir.item_json->>'item_direction','')), '') as item_direction,
    nullif(btrim(coalesce(ir.item_json->>'item_type_label','')), '') as item_type_label,
    nullif(btrim(coalesce(ir.item_json->>'source_ref','')), '') as source_ref,
    round(coalesce(nullif(ir.item_json->>'amount_ex_vat','')::numeric, 0), 2)::numeric(12,2) as preview_amount_ex_vat,
    coalesce(nullif(ir.item_json->>'draftable','')::boolean, false) as draftable,
    coalesce(nullif(ir.item_json->>'snooze_allowed','')::boolean, false) as snooze_allowed,
    coalesce(nullif(ir.item_json->>'is_candidate_directed_oneoff_payout','')::boolean, false) as is_candidate_directed_oneoff_payout,
    coalesce(nullif(ir.item_json->>'appears_on_umbrella_remittance','')::boolean, false) as appears_on_umbrella_remittance,
    coalesce(nullif(ir.item_json->>'generates_candidate_payment_advice','')::boolean, false) as generates_candidate_payment_advice,
    coalesce(ir.item_json->'case_components', ir.item_json->'components', '[]'::jsonb) as case_components_json
  from item_rows ir
  where ir.preview_row_id is not null
    and (v_candidate_filter is null or ir.candidate_id = any(v_candidate_filter))
    and (v_candidate_filter_single is null or ir.candidate_id = v_candidate_filter_single)
    and (v_client_filter_single is null or ir.client_id = v_client_filter_single)
    and coalesce(nullif(ir.item_json->>'draftable','')::boolean, false) = true
    and (
      v_selected_preview_rows_supplied = false
      or ir.preview_row_id = any(v_selected_preview_row_ids)
    )
  order by ir.preview_row_id;

  select count(*)::int
  into v_selected_preview_rows_post_selection_ct
  from pg_temp.tmp_pay_selected_preview_rows;

  v_selected_preview_row_count := v_selected_preview_rows_post_selection_ct;

  if v_selected_preview_rows_supplied = true and v_selected_preview_rows_post_selection_ct = 0 then
    raise exception 'Selected preview rows are not valid for the current preview';
  end if;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_05B_BUILD_SELECTED_PREVIEW_ROWS',
      jsonb_build_object(
        'stage', v_stage,
        'selected_preview_row_ids_present', v_selected_preview_row_ids_present,
        'selected_preview_rows_supplied', v_selected_preview_rows_supplied,
        'selected_preview_rows_mode', v_selected_preview_rows_mode,
        'selected_preview_rows_pre_selection_ct', v_selected_preview_rows_pre_selection_ct,
        'selected_preview_rows_post_selection_ct', v_selected_preview_rows_post_selection_ct,
        'selected_preview_row_count', v_selected_preview_row_count,
        'selected_preview_rows_sample', (
          select coalesce(jsonb_agg(jsonb_build_object(
            'preview_row_id', spr.preview_row_id,
            'candidate_id', spr.candidate_id::text,
            'finance_case_id', case when spr.finance_case_id is null then null else spr.finance_case_id::text end,
            'timesheet_id', case when spr.timesheet_id is null then null else spr.timesheet_id::text end,
            'line_type', spr.line_type,
            'draftable', spr.draftable
          ) order by spr.preview_row_id), '[]'::jsonb)
          from (
            select *
            from pg_temp.tmp_pay_selected_preview_rows
            order by preview_row_id
            limit 50
          ) spr
        )
      ),
      'pay_create_draft_batch',
      'pay_date:'||p_pay_date::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  v_stage := 'STAGE_06_BUILD_CANDIDATE_SET_FROM_SELECTED_ROWS';

  select coalesce(array_agg(distinct spr.candidate_id), array[]::uuid[])
  into v_candidate_ids
  from pg_temp.tmp_pay_selected_preview_rows spr;

  begin
    select coalesce(jsonb_agg(x.candidate_id::text order by x.candidate_id::text), '[]'::jsonb)
    into v_sample_candidate_ids
    from (
      select unnest(coalesce(v_candidate_ids, array[]::uuid[])) as candidate_id
      limit 50
    ) x;

    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_06_CANDIDATE_SET_RESULT',
      jsonb_build_object(
        'stage', v_stage,
        'candidate_ids_count', coalesce(array_length(v_candidate_ids,1),0),
        'candidate_ids_sample', v_sample_candidate_ids
      ),
      'pay_create_draft_batch',
      'pay_date:'||p_pay_date::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  v_stage := 'STAGE_07_CLIENT_FILTER_ALREADY_APPLIED';

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_07_CLIENT_FILTER_ALREADY_APPLIED',
      jsonb_build_object(
        'stage', v_stage,
        'client_filter_single', coalesce(v_client_filter_single::text, null),
        'note', 'Candidate/client row narrowing already applied when building tmp_pay_selected_preview_rows'
      ),
      'pay_create_draft_batch',
      'pay_date:'||p_pay_date::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  v_stage := 'STAGE_08_ASSERT_NON_EMPTY_CANDIDATES';

  if array_length(v_candidate_ids,1) is null or array_length(v_candidate_ids,1) = 0 then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_NOTHING_TO_PAY_AFTER_BLOCKERS',
        jsonb_build_object(
          'stage', v_stage,
          'candidate_ids_count', coalesce(array_length(v_candidate_ids,1),0),
          'error', 'Nothing to pay (no payable deltas after blockers)'
        ),
        'pay_create_draft_batch',
        'pay_date:'||p_pay_date::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    raise exception 'Nothing to pay (no payable deltas after blockers)';
  end if;

  v_stage := 'STAGE_08A_SKIP_LEGACY_OVERPAYMENT_SYNC';

  v_overpayment_sync := '{}'::jsonb;
  v_negative_preview_timesheets_count := 0;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_08A_SKIP_LEGACY_OVERPAYMENT_SYNC',
      jsonb_build_object(
        'stage', v_stage,
        'scope', v_scope,
        'candidate_ids_count', coalesce(array_length(v_candidate_ids,1),0),
        'note', 'Legacy overpayment preview sync skipped for locked draft scope'
      ),
      'pay_create_draft_batch',
      'pay_date:'||p_pay_date::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  v_stage := 'STAGE_08B_IGNORE_LEGACY_COMPONENT_RESOLUTIONS';

  v_component_resolution_input_entry_count := case
    when v_component_resolutions_input_type = 'array' then coalesce(jsonb_array_length(v_component_resolutions), 0)
    when v_component_resolutions_input_type = 'object' then (
      select count(*)::int
      from jsonb_each(v_component_resolutions)
    )
    else 0
  end;
  v_component_resolution_candidate_count := 0;
  v_component_resolution_rows_parsed := 0;
  v_component_resolution_apply_candidate_count := 0;
  v_component_resolution_rows_applied := 0;
  v_component_resolution_rows_skipped := v_component_resolution_input_entry_count;
  v_component_resolution_invalid_sample := '[]'::jsonb;
  v_component_resolution_apply_result := '{}'::jsonb;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_08B_IGNORE_LEGACY_COMPONENT_RESOLUTIONS',
      jsonb_build_object(
        'stage', v_stage,
        'component_resolutions_supplied', v_component_resolutions_supplied,
        'component_resolutions_type', v_component_resolutions_input_type,
        'component_resolution_input_entry_count', v_component_resolution_input_entry_count,
        'component_resolution_candidate_count', v_component_resolution_candidate_count,
        'component_resolution_rows_parsed', v_component_resolution_rows_parsed,
        'component_resolution_apply_candidate_count', v_component_resolution_apply_candidate_count,
        'component_resolution_rows_applied', v_component_resolution_rows_applied,
        'component_resolution_rows_skipped', v_component_resolution_rows_skipped,
        'note', 'Legacy component_resolutions input ignored. Draft creation now freezes overlayed pay_preview truth only.'
      ),
      'pay_create_draft_batch',
      'pay_date:'||p_pay_date::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  v_stage := 'STAGE_08C_SKIP_LEGACY_OVERPAYMENT_RESYNC';

  v_overpayment_sync := '{}'::jsonb;
  v_negative_preview_timesheets_count := 0;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_08C_SKIP_LEGACY_OVERPAYMENT_RESYNC',
      jsonb_build_object(
        'stage', v_stage,
        'scope', v_scope,
        'candidate_ids_count', coalesce(array_length(v_candidate_ids,1),0),
        'note', 'Legacy overpayment preview resync skipped after component resolution for locked draft scope'
      ),
      'pay_create_draft_batch',
      'pay_date:'||p_pay_date::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  v_stage := 'STAGE_08D_REFRESH_SELECTED_PREVIEW_ROWS_POST_RESOLUTION';

  truncate table pg_temp.tmp_pay_selected_preview_rows;

  insert into pg_temp.tmp_pay_selected_preview_rows (
    preview_row_id,
    candidate_id,
    finance_case_id,
    timesheet_id,
    client_id,
    line_type,
    case_type,
    pay_channel,
    paye_treatment,
    routing_kind,
    destination_label,
    taxability,
    beneficiary_name,
    masked_bank_account,
    bank_details_hash,
    item_direction,
    item_type_label,
    source_ref,
    preview_amount_ex_vat,
    draftable,
    snooze_allowed,
    is_candidate_directed_oneoff_payout,
    appears_on_umbrella_remittance,
    generates_candidate_payment_advice,
    case_components_json
  )
  with preview as (
    select public.pay_preview(p_pay_date, p_week_ending_cutoff, p_actor_user_id, p_candidate_id, p_client_id, p_preview_decisions_json) as j
  ),
  item_rows as (
    select
      nullif(btrim(coalesce(line_json->>'candidate_id','')), '')::uuid as candidate_id,
      line_json as item_json,
      coalesce(
        nullif(btrim(coalesce(line_json->>'preview_row_id','')), ''),
        nullif(btrim(coalesce(line_json->>'line_id','')), '')
      ) as preview_row_id,
      nullif(btrim(coalesce(line_json->>'client_id','')), '')::uuid as client_id,
      nullif(btrim(coalesce(line_json->>'finance_case_id','')), '')::uuid as finance_case_id,
      nullif(btrim(coalesce(line_json->>'timesheet_id','')), '')::uuid as timesheet_id
    from preview
    cross join lateral jsonb_array_elements(coalesce(preview.j->'canonical_preview_lines', '[]'::jsonb)) as line_json
    where nullif(btrim(coalesce(line_json->>'candidate_id','')), '') is not null
  )
  select distinct on (ir.preview_row_id)
    ir.preview_row_id,
    ir.candidate_id,
    ir.finance_case_id,
    ir.timesheet_id,
    ir.client_id,
    nullif(btrim(coalesce(ir.item_json->>'line_type','')), '') as line_type,
    nullif(btrim(coalesce(ir.item_json->>'case_type','')), '') as case_type,
    upper(btrim(coalesce(ir.item_json->>'pay_channel',''))) as pay_channel,
    upper(btrim(coalesce(ir.item_json->>'paye_treatment',''))) as paye_treatment,
    nullif(btrim(coalesce(ir.item_json->>'routing_kind','')), '') as routing_kind,
    nullif(btrim(coalesce(ir.item_json->>'destination_label','')), '') as destination_label,
    nullif(btrim(coalesce(ir.item_json->>'taxability','')), '') as taxability,
    nullif(btrim(coalesce(ir.item_json->>'beneficiary_name','')), '') as beneficiary_name,
    nullif(btrim(coalesce(ir.item_json->>'masked_bank_account','')), '') as masked_bank_account,
    nullif(btrim(coalesce(ir.item_json->>'bank_details_hash','')), '') as bank_details_hash,
    nullif(btrim(coalesce(ir.item_json->>'item_direction','')), '') as item_direction,
    nullif(btrim(coalesce(ir.item_json->>'item_type_label','')), '') as item_type_label,
    nullif(btrim(coalesce(ir.item_json->>'source_ref','')), '') as source_ref,
    round(coalesce(nullif(ir.item_json->>'amount_ex_vat','')::numeric, 0), 2)::numeric(12,2) as preview_amount_ex_vat,
    coalesce(nullif(ir.item_json->>'draftable','')::boolean, false) as draftable,
    coalesce(nullif(ir.item_json->>'snooze_allowed','')::boolean, false) as snooze_allowed,
    coalesce(nullif(ir.item_json->>'is_candidate_directed_oneoff_payout','')::boolean, false) as is_candidate_directed_oneoff_payout,
    coalesce(nullif(ir.item_json->>'appears_on_umbrella_remittance','')::boolean, false) as appears_on_umbrella_remittance,
    coalesce(nullif(ir.item_json->>'generates_candidate_payment_advice','')::boolean, false) as generates_candidate_payment_advice,
    coalesce(ir.item_json->'case_components', ir.item_json->'components', '[]'::jsonb) as case_components_json
  from item_rows ir
  where ir.preview_row_id is not null
    and (v_candidate_filter is null or ir.candidate_id = any(v_candidate_filter))
    and (v_candidate_filter_single is null or ir.candidate_id = v_candidate_filter_single)
    and (v_client_filter_single is null or ir.client_id = v_client_filter_single)
    and coalesce(nullif(ir.item_json->>'draftable','')::boolean, false) = true
    and (
      v_selected_preview_rows_supplied = false
      or ir.preview_row_id = any(v_selected_preview_row_ids)
    )
  order by ir.preview_row_id;

  select count(*)::int
  into v_selected_preview_rows_post_selection_ct
  from pg_temp.tmp_pay_selected_preview_rows;

  v_selected_preview_row_count := v_selected_preview_rows_post_selection_ct;

  if v_selected_preview_rows_supplied = true and v_selected_preview_rows_post_selection_ct = 0 then
    raise exception 'Selected preview rows are not valid for the current preview';
  end if;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_08D_REFRESH_SELECTED_PREVIEW_ROWS_POST_RESOLUTION',
      jsonb_build_object(
        'stage', v_stage,
        'selected_preview_row_ids_present', v_selected_preview_row_ids_present,
        'selected_preview_rows_supplied', v_selected_preview_rows_supplied,
        'selected_preview_rows_mode', v_selected_preview_rows_mode,
        'selected_preview_rows_pre_selection_ct', v_selected_preview_rows_pre_selection_ct,
        'selected_preview_rows_post_selection_ct', v_selected_preview_rows_post_selection_ct,
        'selected_preview_row_count', v_selected_preview_row_count,
        'selected_preview_rows_sample', (
          select coalesce(jsonb_agg(jsonb_build_object(
            'preview_row_id', spr.preview_row_id,
            'candidate_id', spr.candidate_id::text,
            'finance_case_id', case when spr.finance_case_id is null then null else spr.finance_case_id::text end,
            'timesheet_id', case when spr.timesheet_id is null then null else spr.timesheet_id::text end,
            'line_type', spr.line_type,
            'draftable', spr.draftable
          ) order by spr.preview_row_id), '[]'::jsonb)
          from (
            select *
            from pg_temp.tmp_pay_selected_preview_rows
            order by preview_row_id
            limit 50
          ) spr
        )
      ),
      'pay_create_draft_batch',
      'pay_date:'||p_pay_date::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  v_stage := 'STAGE_09_VALIDATE_COMPONENT_CASE_STATES';

  with preview as (
    select public.pay_preview(p_pay_date, p_week_ending_cutoff, p_actor_user_id, p_candidate_id, p_client_id, p_preview_decisions_json) as j
  ),
  all_cands as (
    select c as cand
    from preview, lateral jsonb_array_elements(preview.j->'paye_candidates') c
    union all
    select c as cand
    from preview, lateral jsonb_array_elements(preview.j->'non_paye_payees') c
  ),
  selected_candidates as (
    select
      nullif(btrim(coalesce(cand->>'candidate_id','')), '')::uuid as candidate_id,
      coalesce(nullif(cand->>'is_ready_for_draft','')::boolean,false) as candidate_is_ready_for_draft,
      coalesce(cand->'blockers', '[]'::jsonb) as candidate_blockers,
      coalesce(cand->'case_resolution_states', '[]'::jsonb) as case_resolution_states
    from all_cands
    where nullif(btrim(coalesce(cand->>'candidate_id','')), '') is not null
      and (cand->>'candidate_id')::uuid = any(v_candidate_ids)
  ),
  blocked_cases as (
    select
      sc.candidate_id,
      cs.case_json
    from selected_candidates sc
    cross join lateral jsonb_array_elements(sc.case_resolution_states) as cs(case_json)
    where sc.candidate_is_ready_for_draft = true
      and jsonb_array_length(sc.candidate_blockers) = 0
      and coalesce(nullif(cs.case_json->>'is_blocked','')::boolean, false) = true
  )
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'candidate_id', bc.candidate_id::text,
          'case', bc.case_json
        )
        order by bc.candidate_id::text, coalesce(bc.case_json->>'case_key','')
      ),
      '[]'::jsonb
    )
  into v_blocked_case_states
  from blocked_cases bc;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_09_COMPONENT_CASE_STATES_RESULT',
      jsonb_build_object(
        'stage', v_stage,
        'blocked_case_states', v_blocked_case_states,
        'blocked_case_count', jsonb_array_length(v_blocked_case_states)
      ),
      'pay_create_draft_batch',
      'pay_date:'||p_pay_date::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  v_stage := 'STAGE_10_CREATE_BATCH';

  insert into public.pay_batches(
    pay_date,
    created_at_utc,
    created_by_user_id,
    status,
    banking_system_snapshot,
    external_paye_system_snapshot,
    rail_provider_snapshot,
    rail_env_snapshot
  )
  values (
    p_pay_date,
    now(),
    p_actor_user_id,
    'DRAFT',
    v_settings.banking_system,
    v_settings.external_paye_system,
    v_settings.rail_provider_default,
    v_settings.rail_env_default
  )
  returning id into v_batch_id;

  GET DIAGNOSTICS v_rows = ROW_COUNT;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_10_BATCH_CREATED',
      jsonb_build_object(
        'stage', v_stage,
        'row_count', v_rows,
        'pay_batch_id', v_batch_id::text,
        'status', 'DRAFT',
        'pay_date', p_pay_date::text,
        'scope', v_scope,
        'rail_provider_snapshot', coalesce(v_settings.rail_provider_default, null),
        'rail_env_snapshot', coalesce(v_settings.rail_env_default, null)
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  v_stage := 'STAGE_11_INSERT_PAY_BATCH_CANDIDATES';

  insert into public.pay_batch_candidates(
    pay_batch_id,
    candidate_id,
    candidate_tms_ref,
    candidate_display_name,
    paye_state,
    mismatch_settlement_choice,
    gross_preview,
    net_bank_amount,
    debt_created,
    loan_repayment_taken
  )
  select
    v_batch_id,
    c.id,
    c.tms_ref,
    c.display_name,
    case when v_scope = 'PAYE' then 'PENDING_NET' else null end,
    null::text,
    null, null, 0, 0
  from public.candidates c
  where c.id = any(v_candidate_ids);

  GET DIAGNOSTICS v_rows_ins_candidates = ROW_COUNT;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_11_CANDIDATES_INSERTED',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'scope', v_scope,
        'inserted_candidate_rows', v_rows_ins_candidates,
        'candidate_ids_count', coalesce(array_length(v_candidate_ids,1),0),
        'candidate_ids_sample', (
          select coalesce(jsonb_agg(x.candidate_id::text order by x.candidate_id::text), '[]'::jsonb)
          from (
            select unnest(coalesce(v_candidate_ids, array[]::uuid[])) as candidate_id
            limit 50
          ) x
        )
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  v_stage := 'STAGE_12_SYNC_OVERPAYMENTS_FROM_PREVIEW';

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_12_SYNC_OVERPAYMENTS_FROM_PREVIEW',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'scope', v_scope,
        'sync_result', v_overpayment_sync,
        'sync_result_reused_from_stage', 'STAGE_08C_RESYNC_OVERPAYMENTS_POST_RESOLUTION'
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  v_stage := 'STAGE_12_INSERT_PAY_BATCH_ITEMS';

  -- Build pay_batch_items from pay_preview itemisation using case-level safe rows only.
  insert into public.pay_batch_items(
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    description,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    pay_channel,
    umbrella_id,
    is_mismatch,
    finance_case_id,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat
  )
  with preview as (
    select public.pay_preview(p_pay_date, p_week_ending_cutoff, p_actor_user_id, p_candidate_id, p_client_id, p_preview_decisions_json) as j
  ),
  all_candidates as (
    select c as cand
    from preview
    cross join lateral jsonb_array_elements(coalesce(preview.j->'paye_candidates', '[]'::jsonb)) as c
    union all
    select c as cand
    from preview
    cross join lateral jsonb_array_elements(coalesce(preview.j->'non_paye_payees', '[]'::jsonb)) as c
  ),
  candidate_rows as (
    select
      nullif(btrim(coalesce(cand->>'candidate_id','')), '')::uuid as candidate_id,
      upper(btrim(coalesce(cand->>'current_pay_method',''))) as cand_pay_method,
      nullif(btrim(coalesce(cand->>'umbrella_id','')), '')::uuid as umbrella_id,
      coalesce(nullif(cand->>'umbrella_vat_chargeable','')::boolean, false) as umb_vat_chargeable,
      coalesce(nullif(cand->>'is_ready_for_draft','')::boolean, false) as is_ready_for_draft,
      coalesce(cand->'blockers', '[]'::jsonb) as blockers,
      coalesce(cand->'itemisation', '[]'::jsonb) as itemisation
    from all_candidates
    where nullif(btrim(coalesce(cand->>'candidate_id','')), '') is not null
      and (cand->>'candidate_id')::uuid = any(v_candidate_ids)
  ),
  item_rows as (
    select
      cr.candidate_id,
      cr.cand_pay_method,
      cr.umbrella_id,
      cr.umb_vat_chargeable,
      itm as item_json,
      nullif(btrim(coalesce(itm->>'finance_case_id','')), '')::uuid as finance_case_id,
      nullif(btrim(coalesce(itm->>'case_key','')), '') as case_key,
      nullif(btrim(coalesce(itm->>'timesheet_id','')), '')::uuid as timesheet_id,
      nullif(btrim(coalesce(itm->>'client_id','')), '')::uuid as client_id,
      upper(btrim(coalesce(itm->>'source_pay_method',''))) as source_pay_method,
      round(coalesce(nullif(itm->>'payment_amount_ex_vat','')::numeric, 0), 2)::numeric(12,2) as payment_amount_ex_vat,
      coalesce(nullif(itm#>>'{case_resolution_summary,is_blocked}','')::boolean, false) as case_is_blocked,
      coalesce(itm->'components', '[]'::jsonb) as case_components_json
    from candidate_rows cr
    cross join lateral jsonb_array_elements(coalesce(cr.itemisation, '[]'::jsonb)) as itm
    where cr.is_ready_for_draft = true
      and jsonb_array_length(cr.blockers) = 0
  ),
  positive_rows as (
    select
      ir.*
    from item_rows ir
    join pg_temp.tmp_pay_selected_preview_rows spr
      on spr.candidate_id = ir.candidate_id
     and spr.draftable = true
     and spr.finance_case_id is null
     and spr.timesheet_id = ir.timesheet_id
     and spr.preview_row_id = coalesce(
       nullif(btrim(coalesce(ir.item_json->>'preview_row_id','')), ''),
       nullif(btrim(coalesce(ir.item_json->>'line_id','')), ''),
       case
         when nullif(btrim(coalesce(ir.item_json->>'timesheet_id','')), '') is not null then
           case
             when coalesce(nullif(ir.item_json->>'is_partially_ready','')::boolean, false) = true
               then nullif(btrim(coalesce(ir.item_json->>'timesheet_id','')), '') || ':01:ready'
             else nullif(btrim(coalesce(ir.item_json->>'timesheet_id','')), '')
           end
         when nullif(btrim(coalesce(ir.item_json->>'finance_case_id','')), '') is not null
          and nullif(btrim(coalesce(ir.item_json->>'line_type','')), '') is not null
           then 'finance:' || nullif(btrim(coalesce(ir.item_json->>'finance_case_id','')), '') || ':' || lower(nullif(btrim(coalesce(ir.item_json->>'line_type','')), ''))
         else null
       end
     )
    where ir.timesheet_id is not null
      and not (ir.timesheet_id = any(v_exclude_timesheet_ids))
      and (v_client_filter_single is null or ir.client_id = v_client_filter_single)
      and ir.case_is_blocked = false
      and ir.payment_amount_ex_vat > 0
  ),
  positive_component_rows as (
    select
      pr.candidate_id,
      pr.timesheet_id,
      pr.finance_case_id,
      pr.case_key,
      pr.cand_pay_method,
      pr.umbrella_id,
      pr.umb_vat_chargeable,
      nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), '')::uuid as finance_component_id,
      nullif(btrim(coalesce(comp.comp_json->>'source_family_key','')), '') as source_family_key,
      nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), '') as component_key_type,
      nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), '') as component_key_value,
      case
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'TAXABLE_CHANNEL_SENSITIVE' then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'REIMBURSEMENT_GROSS_FIXED' then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
        else null::public.pay_finance_component_classification_enum
      end as classification,
      upper(btrim(coalesce(comp.comp_json->>'source_pay_method',''))) as source_pay_method,
      coalesce(comp.comp_json->'source_basis_json', '{}'::jsonb) as source_basis_json,
      nullif(btrim(coalesce(comp.comp_json->>'source_basis_fingerprint','')), '') as source_basis_fingerprint,
      nullif(upper(btrim(coalesce(comp.comp_json->>'bucket_code',''))), '') as preview_bucket_code,
      nullif(btrim(coalesce(comp.comp_json->>'label','')), '') as preview_label,
      upper(btrim(coalesce(comp.comp_json->>'component_semantics',''))) as preview_component_semantics,
      coalesce(nullif(comp.comp_json->>'is_rate_bearing','')::boolean, false) as preview_is_rate_bearing,
      coalesce(nullif(comp.comp_json->>'is_amount_led','')::boolean, false) as preview_is_amount_led,
      coalesce(nullif(comp.comp_json->>'is_actionable_resolution_row','')::boolean, false) as preview_is_actionable_resolution_row,
      coalesce(nullif(comp.comp_json->>'is_fixed_no_action_taxable_row','')::boolean, false) as preview_is_fixed_no_action_taxable_row,
      upper(btrim(coalesce(comp.comp_json->>'resolution_state',''))) as preview_resolution_state,
      upper(btrim(coalesce(comp.comp_json->>'saved_target_pay_method',''))) as saved_target_pay_method,
      case
        when nullif(btrim(coalesce(comp.comp_json->>'saved_resolution_mode','')), '') is null then null::public.pay_finance_component_resolution_mode_enum
        else nullif(btrim(coalesce(comp.comp_json->>'saved_resolution_mode','')), '')::public.pay_finance_component_resolution_mode_enum
      end as saved_resolution_mode,
      comp.comp_json->'saved_resolution_payload_json' as saved_resolution_payload_json,
      comp.comp_json->'saved_resolution_result_json' as saved_resolution_result_json,
      comp.comp_json->'suggested_resolution_payload_json' as suggested_resolution_payload_json,
      comp.comp_json->'suggested_resolution_result_json' as suggested_resolution_result_json,
      case
        when coalesce(comp.comp_json->>'preview_component_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'preview_component_amount_ex_vat')::numeric, 2)::numeric(12,2)
        when coalesce(comp.comp_json->>'component_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'component_amount_ex_vat')::numeric, 2)::numeric(12,2)
        else null::numeric(12,2)
      end as preview_component_amount_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_pay_ex_vat')::numeric, 2)::numeric(12,2)
        else null::numeric(12,2)
      end as preview_target_amount_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_rate')::numeric, 2)
        else null::numeric
      end as preview_target_rate,
      case
        when coalesce(comp.comp_json->>'source_units','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_units')::numeric, 6)
        else null::numeric
      end as preview_source_units,
      case
        when coalesce(comp.comp_json->>'target_units','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_units')::numeric, 6)
        else null::numeric
      end as preview_target_units,
      case
        when coalesce(comp.comp_json->>'source_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_rate')::numeric, 2)
        else null::numeric
      end as preview_source_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_rate')::numeric, 2)
        else null::numeric
      end as preview_source_charge_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as preview_source_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as preview_target_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_margin_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_margin_ex_vat')::numeric, 2)
        else null::numeric
      end as preview_target_margin_ex_vat,
      case
        when coalesce(comp.comp_json->>'margin_delta_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'margin_delta_ex_vat')::numeric, 2)
        else null::numeric
      end as preview_margin_delta_ex_vat
    from positive_rows pr
    cross join lateral jsonb_array_elements(coalesce(pr.case_components_json, '[]'::jsonb)) as comp(comp_json)
    where comp.comp_json is not null
      and jsonb_typeof(comp.comp_json) = 'object'
  ),
  raw_lines as (
    select
      pcr.candidate_id,
      pcr.finance_case_id,
      pcr.case_key,
      coalesce(nullif(btrim(coalesce(pcr.source_family_key,'')), ''), ('timesheet:' || pcr.timesheet_id::text)) as source_family_key,
      pcr.timesheet_id,
      upper(coalesce(pcr.source_pay_method,'')) as source_pay_method,
      upper(coalesce(pcr.cand_pay_method,'')) as cand_pay_method,
      pcr.umbrella_id,
      coalesce(pcr.umb_vat_chargeable, false) as umb_vat_chargeable,
      upper(coalesce(pcr.cand_pay_method,'')) as pay_channel,
      case
        when pcr.component_key_type in ('TS_DAY','TS_TOTAL') then 'SEGMENT_DELTA'::text
        when pcr.component_key_type = 'ADJUSTMENT_CODE' then 'ADJUSTMENT_DELTA'::text
        when pcr.component_key_type = 'EXPENSE_CODE' and upper(coalesce(pcr.component_key_value,'')) = 'MILEAGE' then 'MILEAGE_DELTA'::text
        else 'EXPENSE_DELTA'::text
      end as item_type,
      case
        when pcr.component_key_type in ('TS_DAY','TS_TOTAL')
          then coalesce(
            nullif(btrim(coalesce(pcr.source_basis_json->>'segment_key','')), ''),
            nullif(btrim(coalesce(pcr.source_basis_json->>'segment_id','')), '')
          )
        else null::text
      end as segment_key,
      case
        when pcr.component_key_type in ('TS_DAY','TS_TOTAL')
          then (
            'seg:' ||
            coalesce(
              nullif(btrim(coalesce(pcr.source_basis_json->>'segment_key','')), ''),
              nullif(btrim(coalesce(pcr.source_basis_json->>'segment_id','')), ''),
              ('ts:' || pcr.timesheet_id::text)
            ) ||
            ':' ||
            coalesce(nullif(upper(btrim(coalesce(pcr.preview_bucket_code, pcr.source_basis_json->>'bucket_code',''))), ''), 'TOTAL')
          )::text
        when pcr.component_key_type = 'ADDITIONAL_CODE'
          then case
            when upper(coalesce(pcr.component_key_value,'')) = 'TOTAL' then 'additional'::text
            else ('additional:' || upper(coalesce(pcr.component_key_value,'')))::text
          end
        when pcr.component_key_type = 'ADJUSTMENT_CODE'
          then ('adj:' || coalesce(nullif(btrim(coalesce(pcr.source_basis_json->>'adjustment_id','')), ''), coalesce(pcr.component_key_value, 'TOTAL')))::text
        when pcr.component_key_type = 'EXPENSE_CODE'
          then lower(coalesce(pcr.component_key_value, 'expense'))::text
        else coalesce(nullif(btrim(coalesce(pcr.source_basis_json->>'source_ref','')), ''), 'component')::text
      end as source_ref,
      round(coalesce(pcr.preview_component_amount_ex_vat, pcr.preview_target_amount_ex_vat, 0), 2) as delta_ex,
      pcr.classification,
      pcr.component_key_type,
      pcr.component_key_value,
      pcr.finance_component_id,
      coalesce(pcr.source_basis_json, '{}'::jsonb) as source_basis_json,
      pcr.source_basis_fingerprint,
      pcr.saved_target_pay_method,
      pcr.saved_resolution_mode,
      pcr.saved_resolution_payload_json,
      pcr.saved_resolution_result_json,
      pcr.suggested_resolution_payload_json,
      pcr.suggested_resolution_result_json,
      pcr.preview_component_amount_ex_vat,
      pcr.preview_target_amount_ex_vat,
      pcr.preview_target_rate,
      pcr.preview_source_units,
      pcr.preview_target_units,
      pcr.preview_source_rate,
      pcr.preview_source_charge_rate,
      pcr.preview_source_charge_ex_vat,
      pcr.preview_target_charge_ex_vat,
      pcr.preview_target_margin_ex_vat,
      pcr.preview_margin_delta_ex_vat,
      pcr.preview_label,
      pcr.preview_bucket_code,
      pcr.preview_component_semantics,
      pcr.preview_is_rate_bearing,
      pcr.preview_is_amount_led,
      pcr.preview_is_actionable_resolution_row,
      pcr.preview_is_fixed_no_action_taxable_row,
      pcr.preview_resolution_state
    from positive_component_rows pcr
    where round(coalesce(pcr.preview_component_amount_ex_vat, pcr.preview_target_amount_ex_vat, 0), 2) <> 0
  ),
  final_items as (
    select
      rl.candidate_id,
      rl.finance_case_id,
      rl.source_family_key,
      rl.timesheet_id,
      rl.segment_key,
      rl.source_ref,
      rl.item_type,
      coalesce(nullif(upper(coalesce(rl.saved_target_pay_method,'')), ''), rl.pay_channel) as pay_channel,
      (
        rl.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        and upper(coalesce(rl.source_pay_method,'')) is distinct from upper(coalesce(nullif(upper(coalesce(rl.saved_target_pay_method,'')), ''), rl.pay_channel))
      ) as is_mismatch,
      rl.classification,
      rl.component_key_type,
      rl.component_key_value,
      rl.finance_component_id,
      rl.source_basis_json,
      rl.source_basis_fingerprint,
      rl.source_pay_method,
      rl.saved_target_pay_method,
      rl.saved_resolution_mode,
      case
        when jsonb_typeof(rl.saved_resolution_payload_json) = 'object' then rl.saved_resolution_payload_json
        else rl.suggested_resolution_payload_json
      end as saved_resolution_payload_json,
      case
        when jsonb_typeof(rl.saved_resolution_result_json) = 'object' then rl.saved_resolution_result_json
        else rl.suggested_resolution_result_json
      end as saved_resolution_result_json,
      rl.preview_target_rate,
      rl.preview_source_units,
      rl.preview_target_units,
      rl.preview_source_rate,
      rl.preview_source_charge_rate,
      rl.preview_source_charge_ex_vat,
      rl.preview_target_charge_ex_vat,
      rl.preview_target_margin_ex_vat,
      rl.preview_margin_delta_ex_vat,
      rl.preview_label,
      rl.preview_bucket_code,
      rl.preview_component_semantics,
      rl.preview_is_rate_bearing,
      rl.preview_is_amount_led,
      rl.preview_is_actionable_resolution_row,
      rl.preview_is_fixed_no_action_taxable_row,
      rl.preview_resolution_state,
      round(coalesce(rl.delta_ex, 0), 2)::numeric(12,2) as frozen_source_amount,
      case
        when rl.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and upper(coalesce(rl.source_pay_method,'')) is distinct from upper(coalesce(nullif(upper(coalesce(rl.saved_target_pay_method,'')), ''), rl.pay_channel))
         and coalesce(coalesce(rl.saved_resolution_result_json, rl.suggested_resolution_result_json)->>'target_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$'
          then round((coalesce(rl.saved_resolution_result_json, rl.suggested_resolution_result_json)->>'target_amount_ex_vat')::numeric, 2)::numeric(12,2)
        when upper(coalesce(nullif(upper(coalesce(rl.saved_target_pay_method,'')), ''), rl.pay_channel)) = 'UMBRELLA'
         and rl.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then round((public._pay_umbrella_vat_calc(round(coalesce(rl.delta_ex,0),2), v_vat_rate_pct, rl.umb_vat_chargeable)->>'ex')::numeric, 2)::numeric(12,2)
        else round(coalesce(rl.delta_ex, 0), 2)::numeric(12,2)
      end as amount_ex_vat,
      case
        when rl.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and upper(coalesce(rl.source_pay_method,'')) is distinct from upper(coalesce(nullif(upper(coalesce(rl.saved_target_pay_method,'')), ''), rl.pay_channel))
         and coalesce(coalesce(rl.saved_resolution_result_json, rl.suggested_resolution_result_json)->>'target_amount_vat','') ~ '^-?\d+(\.\d+)?$'
          then round((coalesce(rl.saved_resolution_result_json, rl.suggested_resolution_result_json)->>'target_amount_vat')::numeric, 2)::numeric(12,2)
        when upper(coalesce(nullif(upper(coalesce(rl.saved_target_pay_method,'')), ''), rl.pay_channel)) = 'UMBRELLA'
         and rl.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then round((public._pay_umbrella_vat_calc(round(coalesce(rl.delta_ex,0),2), v_vat_rate_pct, rl.umb_vat_chargeable)->>'vat')::numeric, 2)::numeric(12,2)
        else 0::numeric(12,2)
      end as amount_vat,
      case
        when rl.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and upper(coalesce(rl.source_pay_method,'')) is distinct from upper(coalesce(nullif(upper(coalesce(rl.saved_target_pay_method,'')), ''), rl.pay_channel))
         and coalesce(coalesce(rl.saved_resolution_result_json, rl.suggested_resolution_result_json)->>'target_amount_inc_vat','') ~ '^-?\d+(\.\d+)?$'
          then round((coalesce(rl.saved_resolution_result_json, rl.suggested_resolution_result_json)->>'target_amount_inc_vat')::numeric, 2)::numeric(12,2)
        when upper(coalesce(nullif(upper(coalesce(rl.saved_target_pay_method,'')), ''), rl.pay_channel)) = 'UMBRELLA'
         and rl.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then round((public._pay_umbrella_vat_calc(round(coalesce(rl.delta_ex,0),2), v_vat_rate_pct, rl.umb_vat_chargeable)->>'inc')::numeric, 2)::numeric(12,2)
        else round(coalesce(rl.delta_ex, 0), 2)::numeric(12,2)
      end as amount_inc_vat
    from raw_lines rl
  )
  select
    pbc.id,
    fi.item_type,
    fi.timesheet_id,
    fi.segment_key,
    fi.source_ref,
    case
      when fi.item_type = 'SEGMENT_DELTA' then 'Segment delta'
      when fi.item_type = 'MILEAGE_DELTA' then 'Mileage delta'
      when fi.item_type = 'ADJUSTMENT_DELTA' then 'Pay adjustment delta'
      when fi.source_ref = 'additional' or fi.source_ref like 'additional:%' then 'Additional pay delta'
      else 'Expense delta'
    end,
    round(fi.amount_ex_vat, 2),
    round(fi.amount_vat, 2),
    round(fi.amount_inc_vat, 2),
    fi.pay_channel,
    case when fi.pay_channel = 'UMBRELLA' then c.umbrella_id else null end,
    fi.is_mismatch,
    fi.finance_case_id,
    fi.finance_component_id,
    jsonb_build_object(
      'finance_case_id', case when fi.finance_case_id is null then null else fi.finance_case_id::text end,
      'source_family_key', fi.source_family_key,
      'component_key_type', fi.component_key_type,
      'component_key_value', fi.component_key_value,
      'classification', fi.classification::text,
      'source_pay_method', fi.source_pay_method,
      'target_pay_method', fi.pay_channel,
      'source_basis_json', fi.source_basis_json,
      'source_basis_fingerprint', fi.source_basis_fingerprint,
      'label', fi.preview_label,
      'bucket_code', fi.preview_bucket_code,
      'component_semantics', fi.preview_component_semantics,
      'is_rate_bearing', fi.preview_is_rate_bearing,
      'is_amount_led', fi.preview_is_amount_led,
      'is_actionable_resolution_row', fi.preview_is_actionable_resolution_row,
      'is_fixed_no_action_taxable_row', fi.preview_is_fixed_no_action_taxable_row,
      'resolution_state', fi.preview_resolution_state,
      'saved_target_pay_method', fi.saved_target_pay_method,
      'saved_resolution_mode', case when fi.saved_resolution_mode is null then null else fi.saved_resolution_mode::text end,
      'saved_resolution_payload_json', fi.saved_resolution_payload_json,
      'saved_resolution_result_json', fi.saved_resolution_result_json,
      'source_units', fi.preview_source_units,
      'target_units', fi.preview_target_units,
      'source_rate', fi.preview_source_rate,
      'source_charge_rate', fi.preview_source_charge_rate,
      'target_rate', fi.preview_target_rate,
      'source_charge_ex_vat', fi.preview_source_charge_ex_vat,
      'target_charge_ex_vat', fi.preview_target_charge_ex_vat,
      'target_margin_ex_vat', fi.preview_target_margin_ex_vat,
      'margin_delta_ex_vat', fi.preview_margin_delta_ex_vat,
      'frozen_source_amount', round(fi.frozen_source_amount, 2),
      'frozen_target_amount_ex_vat', round(fi.amount_ex_vat, 2),
      'frozen_target_amount_vat', round(fi.amount_vat, 2),
      'frozen_target_amount_inc_vat', round(fi.amount_inc_vat, 2)
    ),
    fi.component_key_type,
    fi.component_key_value,
    fi.classification,
    fi.source_basis_json,
    fi.source_pay_method,
    coalesce(fi.saved_target_pay_method, fi.pay_channel),
    coalesce(
      fi.saved_resolution_mode,
      case
        when fi.is_mismatch then 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
        else null::public.pay_finance_component_resolution_mode_enum
      end
    ),
    case
      when jsonb_typeof(fi.saved_resolution_payload_json) = 'object' then jsonb_strip_nulls(
        fi.saved_resolution_payload_json
        || jsonb_build_object(
          'target_pay_method', fi.pay_channel,
          'target_units', coalesce(fi.preview_target_units, fi.preview_source_units),
          'bucket_code', fi.preview_bucket_code,
          'source_basis_fingerprint', fi.source_basis_fingerprint,
          'source_units', fi.preview_source_units,
          'source_rate', fi.preview_source_rate,
          'source_charge_rate', fi.preview_source_charge_rate,
          'component_semantics', fi.preview_component_semantics,
          'is_rate_bearing_row', fi.preview_is_rate_bearing,
          'is_amount_led_row', fi.preview_is_amount_led,
          'suggested_target_rate', fi.preview_target_rate
        )
      )
      when fi.is_mismatch then jsonb_strip_nulls(jsonb_build_object(
        'target_pay_method', fi.pay_channel,
        'target_units', coalesce(fi.preview_target_units, fi.preview_source_units),
        'bucket_code', fi.preview_bucket_code,
        'source_basis_fingerprint', fi.source_basis_fingerprint,
        'source_units', fi.preview_source_units,
        'source_rate', fi.preview_source_rate,
        'source_charge_rate', fi.preview_source_charge_rate,
        'component_semantics', fi.preview_component_semantics,
        'is_rate_bearing_row', fi.preview_is_rate_bearing,
        'is_amount_led_row', fi.preview_is_amount_led,
        'suggested_target_rate', fi.preview_target_rate
      ))
      else fi.saved_resolution_payload_json
    end,
    case
      when jsonb_typeof(fi.saved_resolution_result_json) = 'object' then jsonb_strip_nulls(
        fi.saved_resolution_result_json
        || jsonb_build_object(
          'target_pay_method', fi.pay_channel,
          'target_amount_ex_vat', round(fi.amount_ex_vat, 2),
          'target_amount_vat', round(fi.amount_vat, 2),
          'target_amount_inc_vat', round(fi.amount_inc_vat, 2),
          'target_units', coalesce(fi.preview_target_units, fi.preview_source_units),
          'bucket_code', fi.preview_bucket_code,
          'source_basis_fingerprint', fi.source_basis_fingerprint,
          'component_semantics', fi.preview_component_semantics,
          'is_rate_bearing_row', fi.preview_is_rate_bearing,
          'is_amount_led_row', fi.preview_is_amount_led,
          'replacement_rate', fi.preview_target_rate,
          'source_rate', fi.preview_source_rate,
          'source_charge_rate', fi.preview_source_charge_rate,
          'source_charge_ex_vat', fi.preview_source_charge_ex_vat,
          'target_charge_ex_vat', fi.preview_target_charge_ex_vat,
          'target_margin_ex_vat', fi.preview_target_margin_ex_vat,
          'margin_delta_ex_vat', fi.preview_margin_delta_ex_vat
        )
      )
      when fi.is_mismatch then jsonb_strip_nulls(jsonb_build_object(
        'target_pay_method', fi.pay_channel,
        'target_amount_ex_vat', round(fi.amount_ex_vat, 2),
        'target_amount_vat', round(fi.amount_vat, 2),
        'target_amount_inc_vat', round(fi.amount_inc_vat, 2),
        'target_units', coalesce(fi.preview_target_units, fi.preview_source_units),
        'bucket_code', fi.preview_bucket_code,
        'source_basis_fingerprint', fi.source_basis_fingerprint,
        'component_semantics', fi.preview_component_semantics,
        'is_rate_bearing_row', fi.preview_is_rate_bearing,
        'is_amount_led_row', fi.preview_is_amount_led,
        'replacement_rate', fi.preview_target_rate,
        'source_rate', fi.preview_source_rate,
        'source_charge_rate', fi.preview_source_charge_rate,
        'source_charge_ex_vat', fi.preview_source_charge_ex_vat,
        'target_charge_ex_vat', fi.preview_target_charge_ex_vat,
        'target_margin_ex_vat', fi.preview_target_margin_ex_vat,
        'margin_delta_ex_vat', fi.preview_margin_delta_ex_vat
      ))
      else fi.saved_resolution_result_json
    end,
    round(fi.frozen_source_amount, 2),
    round(fi.amount_ex_vat, 2),
    round(fi.amount_vat, 2),
    round(fi.amount_inc_vat, 2)
  from final_items fi
  join public.pay_batch_candidates pbc
    on pbc.pay_batch_id = v_batch_id
   and pbc.candidate_id = fi.candidate_id
  join public.candidates c
    on c.id = fi.candidate_id;
  GET DIAGNOSTICS v_rows_ins_items = ROW_COUNT;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_12_ITEMS_INSERTED',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'scope', v_scope,
        'inserted_item_rows', v_rows_ins_items
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  update public.pay_batch_items as pbi_set
  set payout_instruction_snapshot_json = pbi_src.payout_instruction_snapshot_json
  from (
    select
      pbi.id as pay_batch_item_id,
      jsonb_strip_nulls(
        jsonb_build_object(
          'taxability',
            case
              when pbi.frozen_component_classification = 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
                then 'NON_TAXABLE'
              else 'TAXABLE'
            end,
          'routing_kind',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' then 'NORMAL_PAY_ROUTE'
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then 'UMBRELLA_COMPANY'
              else null
            end,
          'destination_label',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' then 'normal PAYE route'
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then 'umbrella company'
              else null
            end,
          'pay_channel', upper(coalesce(pbi.pay_channel::text, '')),
          'payee_entity_kind',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' then 'CANDIDATE'
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then 'UMBRELLA'
              else null
            end,
          'payee_entity_id',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' then pbc.candidate_id::text
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and pbi.umbrella_id is not null then pbi.umbrella_id::text
              else null
            end,
          'beneficiary_name',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' then nullif(btrim(coalesce(c.account_holder, c.display_name, concat_ws(' ', c.first_name, c.last_name))), '')
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then nullif(btrim(coalesce(u.name, '')), '')
              else null
            end,
          'sort_code',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE'
               and length(regexp_replace(coalesce(c.sort_code, ''), '[^0-9]', '', 'g')) = 6
                then substr(regexp_replace(coalesce(c.sort_code, ''), '[^0-9]', '', 'g'), 1, 2) || '-' ||
                     substr(regexp_replace(coalesce(c.sort_code, ''), '[^0-9]', '', 'g'), 3, 2) || '-' ||
                     substr(regexp_replace(coalesce(c.sort_code, ''), '[^0-9]', '', 'g'), 5, 2)
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA'
               and length(regexp_replace(coalesce(u.sort_code, ''), '[^0-9]', '', 'g')) = 6
                then substr(regexp_replace(coalesce(u.sort_code, ''), '[^0-9]', '', 'g'), 1, 2) || '-' ||
                     substr(regexp_replace(coalesce(u.sort_code, ''), '[^0-9]', '', 'g'), 3, 2) || '-' ||
                     substr(regexp_replace(coalesce(u.sort_code, ''), '[^0-9]', '', 'g'), 5, 2)
              else null
            end,
          'account_number',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE'
                then nullif(regexp_replace(coalesce(c.account_number, ''), '[^0-9]', '', 'g'), '')
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA'
                then nullif(regexp_replace(coalesce(u.account_number, ''), '[^0-9]', '', 'g'), '')
              else null
            end,
          'account_type',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' then 'Personal'
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then 'Business'
              else null
            end,
          'masked_bank_account',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE'
               and nullif(coalesce(c.account_number, ''), '') is not null
                then lpad(right(c.account_number, 4), length(c.account_number), '*')
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA'
               and nullif(coalesce(u.account_number, ''), '') is not null
                then lpad(right(u.account_number, 4), length(u.account_number), '*')
              else null
            end,
          'bank_details_hash',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' then c.bank_details_hash
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then u.bank_details_hash
              else null
            end,
          'week_ending_bucket',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA'
                then case
                       when ts_pi.week_ending_date is null then (v_week_start + 6)::text
                       else ts_pi.week_ending_date::text
                     end
              else null
            end,
          'rail_provider', upper(btrim(coalesce(v_settings.rail_provider_default, ''))),
          'rail_env', upper(btrim(coalesce(v_settings.rail_env_default, ''))),
          'payee_id', case when bpm.payee_id is null then null else bpm.payee_id::text end,
          'payee_account_id', case when bpm.payee_account_id is null then null else bpm.payee_account_id::text end,
          'appears_on_umbrella_remittance',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then true
              else false
            end,
          'generates_candidate_payment_advice', false,
          'is_candidate_directed_oneoff_payout', false
        )
      ) as payout_instruction_snapshot_json
    from public.pay_batch_items as pbi
    join public.pay_batch_candidates as pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.candidates as c
      on c.id = pbc.candidate_id
    left join public.timesheets as ts_pi
      on ts_pi.timesheet_id = pbi.timesheet_id
     and ts_pi.is_current = true
    left join public.umbrellas as u
      on u.id = pbi.umbrella_id
    left join public.bank_payee_map as bpm
      on upper(coalesce(bpm.rail_provider, '')) = upper(btrim(coalesce(v_settings.rail_provider_default, '')))
     and upper(coalesce(bpm.rail_env, '')) = upper(btrim(coalesce(v_settings.rail_env_default, '')))
     and upper(coalesce(bpm.entity_kind, '')) =
          case
            when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' then 'CANDIDATE'
            when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then 'UMBRELLA'
            else ''
          end
     and bpm.entity_id =
          case
            when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' then pbc.candidate_id
            when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then pbi.umbrella_id
            else null::uuid
          end
     and bpm.bank_details_hash =
          case
            when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' then c.bank_details_hash
            when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then u.bank_details_hash
            else null
          end
    where pbc.pay_batch_id = v_batch_id
      and coalesce(pbi.is_voided, false) = false
      and pbi.finance_case_id is null
      and pbi.payout_instruction_snapshot_json is null
      and pbi.item_type in ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
  ) as pbi_src
  where pbi_set.id = pbi_src.pay_batch_item_id;

  v_stage := 'STAGE_12A_SKIP_UNAPPROVED_UNDERPAYMENT_ITEMS';
  v_rows_ins_underpayment_items := 0;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_12A_SKIP_UNAPPROVED_UNDERPAYMENT_ITEMS',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'scope', v_scope,
        'note', 'UNDERPAYMENT payment drafting skipped because it is outside the locked draft scope'
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  v_stage := 'STAGE_12B_SKIP_LEGACY_OVERPAYMENT_UPSERT';

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_12B_SKIP_LEGACY_OVERPAYMENT_UPSERT',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'scope', v_scope,
        'note', 'Legacy overpayment upsert skipped for locked draft scope'
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then
    null;
  end;

  v_stage := 'STAGE_12C_APPLY_LOAN_PAYOUTS';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  insert into public.pay_batch_items (
    id,
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    description,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    pay_channel,
    umbrella_id,
    is_mismatch,
    finance_case_id,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat,
    payout_instruction_snapshot_json,
    paye_treatment
  )
  with safe_case_rows as (
    select
      spr.preview_row_id,
      spr.candidate_id,
      spr.finance_case_id,
      spr.client_id,
      spr.timesheet_id as linked_timesheet_id,
      upper(coalesce(spr.pay_channel,'')) as pay_channel,
      upper(coalesce(spr.paye_treatment,'')) as paye_treatment,
      nullif(btrim(coalesce(spr.routing_kind,'')), '') as routing_kind,
      nullif(btrim(coalesce(spr.destination_label,'')), '') as destination_label,
      nullif(btrim(coalesce(spr.taxability,'')), '') as taxability,
      nullif(btrim(coalesce(spr.beneficiary_name,'')), '') as beneficiary_name,
      nullif(btrim(coalesce(spr.masked_bank_account,'')), '') as masked_bank_account,
      nullif(btrim(coalesce(spr.bank_details_hash,'')), '') as bank_details_hash,
      coalesce(spr.is_candidate_directed_oneoff_payout, false) as is_candidate_directed_oneoff_payout,
      coalesce(spr.appears_on_umbrella_remittance, false) as appears_on_umbrella_remittance,
      coalesce(spr.generates_candidate_payment_advice, false) as generates_candidate_payment_advice,
      abs(round(coalesce(spr.preview_amount_ex_vat, 0), 2))::numeric(12,2) as payout_total_target_ex
    from pg_temp.tmp_pay_selected_preview_rows spr
    where spr.draftable = true
      and spr.line_type = 'LOAN_PAYOUT'
      and spr.finance_case_id is not null
      and spr.candidate_id = any(v_candidate_ids)
      and (v_client_filter_single is null or spr.client_id = v_client_filter_single)
  ),
  candidate_due as (
    select
      pbc.id as pay_batch_candidate_id,
      scr.preview_row_id,
      scr.candidate_id,
      scr.pay_channel,
      case when scr.pay_channel = 'UMBRELLA' then c.umbrella_id else null end as umbrella_id,
      scr.finance_case_id,
      scr.linked_timesheet_id,
      scr.paye_treatment,
      scr.routing_kind,
      scr.destination_label,
      scr.taxability,
      scr.beneficiary_name,
      scr.masked_bank_account,
      scr.bank_details_hash,
      scr.is_candidate_directed_oneoff_payout,
      scr.appears_on_umbrella_remittance,
      scr.generates_candidate_payment_advice,
      scr.payout_total_target_ex
    from safe_case_rows scr
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = v_batch_id
     and pbc.candidate_id = scr.candidate_id
    join public.candidates c
      on c.id = scr.candidate_id
  ),
  case_component_base as (
    select
      cd.pay_batch_candidate_id,
      cd.preview_row_id,
      cd.candidate_id,
      cd.pay_channel,
      cd.umbrella_id,
      cd.finance_case_id,
      cd.linked_timesheet_id,
      cd.paye_treatment,
      cd.routing_kind,
      cd.destination_label,
      cd.taxability,
      cd.beneficiary_name,
      cd.masked_bank_account,
      cd.bank_details_hash,
      cd.is_candidate_directed_oneoff_payout,
      cd.appears_on_umbrella_remittance,
      cd.generates_candidate_payment_advice,
      pfc.id as finance_component_id,
      pfc.component_key_type,
      pfc.component_key_value,
      pfc.classification,
      upper(coalesce(pfc.source_pay_method,'')) as source_pay_method,
      pfc.source_basis_json,
      upper(coalesce(pfc.saved_target_pay_method,'')) as saved_target_pay_method,
      pfc.saved_resolution_mode,
      pfc.saved_resolution_payload_json,
      pfc.saved_resolution_result_json,
      round(greatest(coalesce(pfc.source_amount, pfc.remaining_source_amount, 0), 0), 2)::numeric(12,2) as source_amount,
      round(greatest(coalesce(pfc.remaining_source_amount, 0), 0), 2)::numeric(12,2) as remaining_source_amount,
      pfc.allocation_priority_group,
      pfc.allocation_priority_order,
      pfc.created_at_utc as finance_component_created_at,
      cd.payout_total_target_ex,
      case
        when cd.pay_channel = 'UMBRELLA'
         and pfc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then round((public._pay_umbrella_vat_calc(round(greatest(coalesce(pfc.remaining_source_amount,0),0),2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'ex')::numeric, 2)::numeric(12,2)
        else round(greatest(coalesce(pfc.remaining_source_amount,0),0), 2)::numeric(12,2)
      end as remaining_target_amount_ex_vat,
      case
        when cd.pay_channel = 'UMBRELLA'
         and pfc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then round((public._pay_umbrella_vat_calc(round(greatest(coalesce(pfc.remaining_source_amount,0),0),2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric, 2)::numeric(12,2)
        else 0::numeric(12,2)
      end as remaining_target_amount_vat,
      case
        when cd.pay_channel = 'UMBRELLA'
         and pfc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then round((public._pay_umbrella_vat_calc(round(greatest(coalesce(pfc.remaining_source_amount,0),0),2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric, 2)::numeric(12,2)
        else round(greatest(coalesce(pfc.remaining_source_amount,0),0), 2)::numeric(12,2)
      end as remaining_target_amount_inc_vat,
      obd.created_by_user_id as bank_details_created_by_user_id,
      obd.updated_by_user_id as bank_details_updated_by_user_id,
      obd.note as bank_details_note
    from candidate_due cd
    join public.pay_finance_case_components pfc
      on pfc.finance_case_id = cd.finance_case_id
     and pfc.closed_at_utc is null
     and pfc.remaining_source_amount > 0
    left join public.candidates c
      on c.id = cd.candidate_id
    left join public.umbrellas u
      on u.id = cd.umbrella_id
    left join public.pay_finance_case_oneoff_payout_bank_details obd
      on obd.finance_case_id = cd.finance_case_id
  ),
  case_component_due as (
    select
      ccb.*,
      sum(ccb.remaining_target_amount_ex_vat) over (
        partition by ccb.finance_case_id
        order by ccb.allocation_priority_group, ccb.allocation_priority_order, ccb.finance_component_created_at, ccb.finance_component_id
        rows between unbounded preceding and 1 preceding
      )::numeric(12,2) as cum_before_case_target,
      least(
        ccb.remaining_target_amount_ex_vat,
        greatest(ccb.payout_total_target_ex - coalesce(sum(ccb.remaining_target_amount_ex_vat) over (
          partition by ccb.finance_case_id
          order by ccb.allocation_priority_group, ccb.allocation_priority_order, ccb.finance_component_created_at, ccb.finance_component_id
          rows between unbounded preceding and 1 preceding
        ), 0), 0)
      )::numeric(12,2) as take_target_ex
    from case_component_base ccb
  ),
  alloc as (
    select
      ccd.pay_batch_candidate_id,
      ccd.pay_channel,
      ccd.umbrella_id,
      ccd.finance_case_id,
      ccd.linked_timesheet_id,
      ccd.paye_treatment,
      ccd.routing_kind,
      ccd.destination_label,
      ccd.taxability,
      ccd.beneficiary_name,
      ccd.masked_bank_account,
      ccd.bank_details_hash,
      ccd.is_candidate_directed_oneoff_payout,
      ccd.appears_on_umbrella_remittance,
      ccd.generates_candidate_payment_advice,
      ccd.bank_details_created_by_user_id,
      ccd.bank_details_updated_by_user_id,
      ccd.bank_details_note,
      ccd.finance_component_id,
      ccd.component_key_type,
      ccd.component_key_value,
      ccd.classification,
      ccd.source_pay_method,
      ccd.source_basis_json,
      ccd.saved_target_pay_method,
      ccd.saved_resolution_mode,
      ccd.saved_resolution_payload_json,
      ccd.saved_resolution_result_json,
      ccd.source_amount,
      ccd.remaining_source_amount,
      ccd.remaining_target_amount_ex_vat,
      ccd.remaining_target_amount_vat,
      ccd.remaining_target_amount_inc_vat,
      round(ccd.take_target_ex, 2)::numeric(12,2) as take_target_ex,
      case
        when round(coalesce(ccd.remaining_target_amount_ex_vat,0),2) > 0 then least(
          ccd.remaining_source_amount,
          round(ccd.remaining_source_amount * ccd.take_target_ex / ccd.remaining_target_amount_ex_vat, 2)
        )::numeric(12,2)
        else 0::numeric(12,2)
      end as take_source_amount,
      case
        when round(coalesce(ccd.remaining_target_amount_ex_vat,0),2) > 0 then round(coalesce(ccd.remaining_target_amount_vat,0) * ccd.take_target_ex / ccd.remaining_target_amount_ex_vat, 2)::numeric(12,2)
        else 0::numeric(12,2)
      end as take_target_vat,
      case
        when round(coalesce(ccd.remaining_target_amount_ex_vat,0),2) > 0 then round(coalesce(ccd.remaining_target_amount_inc_vat,0) * ccd.take_target_ex / ccd.remaining_target_amount_ex_vat, 2)::numeric(12,2)
        else 0::numeric(12,2)
      end as take_target_inc
    from case_component_due ccd
    where ccd.take_target_ex > 0
  )
  select
    gen_random_uuid() as id,
    a.pay_batch_candidate_id,
    'LOAN_PAYOUT'::text as item_type,
    a.linked_timesheet_id as timesheet_id,
    null::text as segment_key,
    ('advance:' || a.finance_case_id::text) as source_ref,
    'Payment Advance'::text as description,
    round(a.take_target_ex, 2) as amount_ex_vat,
    round(a.take_target_vat, 2) as amount_vat,
    round(a.take_target_inc, 2) as amount_inc_vat,
    a.pay_channel,
    a.umbrella_id,
    false as is_mismatch,
    a.finance_case_id,
    a.finance_component_id,
    jsonb_build_object(
      'finance_case_id', a.finance_case_id::text,
      'finance_component_id', a.finance_component_id::text,
      'classification', a.classification::text,
      'source_pay_method', a.source_pay_method,
      'target_pay_method', a.pay_channel,
      'source_basis_json', a.source_basis_json,
      'saved_target_pay_method', a.saved_target_pay_method,
      'saved_resolution_mode', case when a.saved_resolution_mode is null then null else a.saved_resolution_mode::text end,
      'saved_resolution_payload_json', a.saved_resolution_payload_json,
      'saved_resolution_result_json', a.saved_resolution_result_json,
      'reserved_source_amount', round(a.take_source_amount, 2),
      'frozen_target_amount_ex_vat', round(a.take_target_ex, 2),
      'frozen_target_amount_vat', round(a.take_target_vat, 2),
      'frozen_target_amount_inc_vat', round(a.take_target_inc, 2)
    ) as frozen_component_snapshot_json,
    a.component_key_type,
    a.component_key_value,
    a.classification,
    a.source_basis_json,
    a.source_pay_method,
    a.pay_channel,
    a.saved_resolution_mode,
    a.saved_resolution_payload_json,
    a.saved_resolution_result_json,
    round(a.take_source_amount, 2),
    round(a.take_target_ex, 2),
    round(a.take_target_vat, 2),
    round(a.take_target_inc, 2),
    jsonb_strip_nulls(
      jsonb_build_object(
        'taxability', a.taxability,
        'routing_kind', a.routing_kind,
        'destination_label', a.destination_label,
        'pay_channel', a.pay_channel,
        'payee_entity_kind', case when a.is_candidate_directed_oneoff_payout then 'CANDIDATE' when a.routing_kind = 'UMBRELLA_COMPANY' then 'UMBRELLA' else 'CANDIDATE' end,
        'beneficiary_name', a.beneficiary_name,
        'masked_bank_account', a.masked_bank_account,
        'bank_details_hash', a.bank_details_hash,
        'bank_details_note', a.bank_details_note,
        'bank_details_created_by_user_id', case when a.bank_details_created_by_user_id is null then null else a.bank_details_created_by_user_id::text end,
        'bank_details_updated_by_user_id', case when a.bank_details_updated_by_user_id is null then null else a.bank_details_updated_by_user_id::text end,
        'appears_on_umbrella_remittance', a.appears_on_umbrella_remittance,
        'generates_candidate_payment_advice', a.generates_candidate_payment_advice,
        'payee_entity_id', case
          when a.is_candidate_directed_oneoff_payout then (
            select pbc2.candidate_id::text
            from public.pay_batch_candidates pbc2
            where pbc2.id = a.pay_batch_candidate_id
            limit 1
          )
          when a.routing_kind = 'UMBRELLA_COMPANY' then case when a.umbrella_id is null then null else a.umbrella_id::text end
          else (
            select pbc2.candidate_id::text
            from public.pay_batch_candidates pbc2
            where pbc2.id = a.pay_batch_candidate_id
            limit 1
          )
        end
      )
    ) as payout_instruction_snapshot_json,
    case when a.pay_channel = 'PAYE' then coalesce(nullif(a.paye_treatment,''),'NET_ADD') else 'NONE' end as paye_treatment
  from alloc a
  where a.take_target_ex > 0;

  get diagnostics v_rows_ins_loan_payout_items = row_count;

  v_stage := 'STAGE_12D_APPLY_MANUAL_CREDIT_PAYOUTS';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  insert into public.pay_batch_items (
    id,
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    description,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    pay_channel,
    umbrella_id,
    is_mismatch,
    finance_case_id,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat,
    payout_instruction_snapshot_json,
    paye_treatment
  )
  with selected_case_rows as (
    select distinct on (spr.finance_case_id)
      pbc.id as pay_batch_candidate_id,
      spr.candidate_id,
      spr.finance_case_id,
      spr.client_id,
      spr.timesheet_id as linked_timesheet_id,
      upper(coalesce(nullif(spr.pay_channel,''), v_scope)) as pay_channel,
      upper(coalesce(nullif(spr.paye_treatment,''), 'NONE')) as paye_treatment,
      case when upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = 'UMBRELLA' then c.umbrella_id else null::uuid end as umbrella_id,
      nullif(btrim(coalesce(spr.routing_kind,'')), '') as routing_kind,
      nullif(btrim(coalesce(spr.destination_label,'')), '') as destination_label,
      nullif(btrim(coalesce(spr.taxability,'')), '') as taxability,
      nullif(btrim(coalesce(spr.beneficiary_name,'')), '') as beneficiary_name,
      nullif(btrim(coalesce(spr.masked_bank_account,'')), '') as masked_bank_account,
      nullif(btrim(coalesce(spr.bank_details_hash,'')), '') as bank_details_hash,
      coalesce(spr.is_candidate_directed_oneoff_payout, false) as is_candidate_directed_oneoff_payout,
      coalesce(spr.appears_on_umbrella_remittance, false) as appears_on_umbrella_remittance,
      coalesce(spr.generates_candidate_payment_advice, false) as generates_candidate_payment_advice,
      round(abs(coalesce(spr.preview_amount_ex_vat, 0)), 2)::numeric(12,2) as due_amount_ex_vat,
      coalesce(spr.case_components_json, '[]'::jsonb) as case_components_json
    from pg_temp.tmp_pay_selected_preview_rows spr
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = v_batch_id
     and pbc.candidate_id = spr.candidate_id
    join public.candidates c
      on c.id = spr.candidate_id
    where spr.draftable = true
      and spr.line_type = 'MANUAL_CREDIT_ADJUSTMENT_PAYMENT'
      and spr.finance_case_id is not null
      and spr.candidate_id = any(v_candidate_ids)
      and (v_client_filter_single is null or spr.client_id = v_client_filter_single)
      and abs(coalesce(spr.preview_amount_ex_vat, 0)) > 0
    order by spr.finance_case_id, spr.preview_row_id
  ),
  component_rows as (
    select
      scr.pay_batch_candidate_id,
      scr.candidate_id,
      scr.finance_case_id,
      scr.pay_channel,
      scr.paye_treatment,
      scr.umbrella_id,
      scr.routing_kind,
      scr.destination_label,
      scr.taxability,
      scr.beneficiary_name,
      scr.masked_bank_account,
      scr.bank_details_hash,
      scr.is_candidate_directed_oneoff_payout,
      scr.appears_on_umbrella_remittance,
      scr.generates_candidate_payment_advice,
      scr.due_amount_ex_vat,
      comp.comp_json,
      case
        when nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), '') is null then null::uuid
        else (comp.comp_json->>'finance_component_id')::uuid
      end as finance_component_id,
      nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), '') as component_key_type,
      coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), 'TOTAL') as component_key_value,
      case
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'TAXABLE_CHANNEL_SENSITIVE' then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'REIMBURSEMENT_GROSS_FIXED' then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'NET_PAY_FIXED_RECOVERY' then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
        else null::public.pay_finance_component_classification_enum
      end as classification,
      upper(btrim(coalesce(comp.comp_json->>'source_pay_method',''))) as source_pay_method,
      coalesce(comp.comp_json->'source_basis_json', '{}'::jsonb) as source_basis_json,
      upper(nullif(btrim(coalesce(comp.comp_json->>'saved_target_pay_method','')), '')) as saved_target_pay_method,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_payload_json') = 'object' then comp.comp_json->'saved_resolution_payload_json'
        else null::jsonb
      end as saved_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_result_json') = 'object' then comp.comp_json->'saved_resolution_result_json'
        else null::jsonb
      end as saved_resolution_result_json,
      case
        when jsonb_typeof(comp.comp_json->'suggested_resolution_payload_json') = 'object' then comp.comp_json->'suggested_resolution_payload_json'
        else null::jsonb
      end as preview_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'suggested_resolution_result_json') = 'object' then comp.comp_json->'suggested_resolution_result_json'
        else null::jsonb
      end as preview_resolution_result_json,
      nullif(btrim(coalesce(comp.comp_json->>'saved_resolution_mode','')), '') as saved_resolution_mode_text,
      nullif(btrim(coalesce(comp.comp_json->'suggested_resolution_payload_json'->>'resolution_mode','')), '') as preview_resolution_mode_text,
      round(
        case
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as remaining_source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'allocated_source_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'allocated_source_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as allocated_source_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as preview_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->'suggested_resolution_result_json'->>'target_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->'suggested_resolution_result_json'->>'target_amount_ex_vat')::numeric
          when coalesce(comp.comp_json->>'target_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'target_pay_ex_vat')::numeric
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as target_pay_ex_vat,
      case
        when coalesce(comp.comp_json->>'source_units','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_units')::numeric, 6)
        else null::numeric
      end as source_units,
      case
        when coalesce(comp.comp_json->>'source_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_rate')::numeric, 2)
        else null::numeric
      end as source_rate,
      case
        when coalesce(comp.comp_json->>'target_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_rate')::numeric, 2)
        else null::numeric
      end as target_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_rate')::numeric, 2)
        else null::numeric
      end as source_charge_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as source_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as target_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_margin_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_margin_ex_vat')::numeric, 2)
        else null::numeric
      end as target_margin_ex_vat,
      case
        when coalesce(comp.comp_json->>'margin_delta_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'margin_delta_ex_vat')::numeric, 2)
        else null::numeric
      end as margin_delta_ex_vat,
      row_number() over (
        partition by scr.finance_case_id
        order by
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), ''), md5(comp.comp_json::text)),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), ''), ''),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), '')
      ) as component_rn,
      count(*) over (partition by scr.finance_case_id) as component_ct,
      round(sum(
        round(
          case
            when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
            else 0
          end,
          2
        )
      ) over (partition by scr.finance_case_id), 2)::numeric(12,2) as component_preview_due_sum
    from selected_case_rows scr
    cross join lateral jsonb_array_elements(coalesce(scr.case_components_json, '[]'::jsonb)) as comp(comp_json)
    where jsonb_typeof(comp.comp_json) = 'object'
      and round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      ) > 0
  ),
  normalized as (
    select
      cr.*,
      round(
        case
          when cr.component_ct = 1 then cr.due_amount_ex_vat
          when cr.component_rn = 1 then greatest(cr.due_amount_ex_vat - (coalesce(cr.component_preview_due_sum, 0) - coalesce(cr.preview_due_amount_ex_vat, 0)), 0)
          else cr.preview_due_amount_ex_vat
        end,
        2
      )::numeric(12,2) as take_target_ex
    from component_rows cr
  ),
  final_alloc as (
    select
      n.pay_batch_candidate_id,
      n.finance_case_id,
      n.pay_channel,
      n.paye_treatment,
      n.umbrella_id,
      n.routing_kind,
      n.destination_label,
      n.taxability,
      n.beneficiary_name,
      n.masked_bank_account,
      n.bank_details_hash,
      n.is_candidate_directed_oneoff_payout,
      n.appears_on_umbrella_remittance,
      n.generates_candidate_payment_advice,
      n.finance_component_id,
      n.component_key_type,
      n.component_key_value,
      n.classification,
      n.source_pay_method,
      n.source_basis_json,
      case
        when n.preview_resolution_mode_text is not null
         and upper(coalesce(n.preview_resolution_mode_text,'')) = 'SUGGESTED_EQUIVALENT_BASIS'
        then 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
        when n.saved_resolution_mode_text is not null then n.saved_resolution_mode_text::public.pay_finance_component_resolution_mode_enum
        when n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and upper(coalesce(n.source_pay_method,'')) <> upper(coalesce(n.pay_channel,''))
        then 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
        else null::public.pay_finance_component_resolution_mode_enum
      end as frozen_resolution_mode,
      case
        when jsonb_typeof(n.preview_resolution_payload_json) = 'object' then jsonb_strip_nulls(
          n.preview_resolution_payload_json
          || jsonb_build_object(
            'target_pay_method', n.pay_channel,
            'target_units', n.source_units,
            'suggested_target_rate', n.target_rate,
            'source_rate', n.source_rate,
            'source_charge_rate', n.source_charge_rate
          )
        )
        when jsonb_typeof(n.saved_resolution_payload_json) = 'object' then jsonb_strip_nulls(
          n.saved_resolution_payload_json
          || jsonb_build_object(
            'target_pay_method', n.pay_channel,
            'target_units', n.source_units,
            'suggested_target_rate', n.target_rate,
            'source_rate', n.source_rate,
            'source_charge_rate', n.source_charge_rate
          )
        )
        else jsonb_strip_nulls(jsonb_build_object(
          'resolution_mode', coalesce(n.preview_resolution_mode_text, 'SUGGESTED_EQUIVALENT_BASIS'),
          'target_pay_method', n.pay_channel,
          'target_units', n.source_units,
          'suggested_target_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate
        ))
      end as frozen_resolution_payload_json,
      round(
        case
          when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
          when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
          else 0
        end,
        2
      )::numeric(12,2) as take_source_amount,
      round(n.take_target_ex, 2)::numeric(12,2) as take_target_ex,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as take_target_vat,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
          else round(n.take_target_ex, 2)
        end,
        2
      )::numeric(12,2) as take_target_inc,
      jsonb_strip_nulls(
        coalesce(n.comp_json, '{}'::jsonb)
        || jsonb_build_object(
          'frozen_target_pay_method', n.pay_channel,
          'frozen_resolution_mode_text', coalesce(n.preview_resolution_mode_text, n.saved_resolution_mode_text),
          'frozen_source_amount', round(
            case
              when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
              when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
              else 0
            end,
            2
          ),
          'frozen_target_amount_ex_vat', round(n.take_target_ex, 2),
          'frozen_target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'frozen_target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'selected_preview_due_amount_ex_vat', round(n.due_amount_ex_vat, 2),
          'component_preview_due_amount_ex_vat', round(n.take_target_ex, 2)
        )
      ) as frozen_component_snapshot_json,
      jsonb_strip_nulls(
        coalesce(n.preview_resolution_result_json, n.saved_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'resolution_mode', coalesce(n.preview_resolution_mode_text, coalesce(n.saved_resolution_mode_text, 'SUGGESTED_EQUIVALENT_BASIS')),
          'target_pay_method', n.pay_channel,
          'target_amount_ex_vat', round(n.take_target_ex, 2),
          'target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'replacement_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate,
          'source_charge_ex_vat', n.source_charge_ex_vat,
          'target_charge_ex_vat', n.target_charge_ex_vat,
          'target_margin_ex_vat', n.target_margin_ex_vat,
          'margin_delta_ex_vat', n.margin_delta_ex_vat
        )
      ) as frozen_resolution_result_json
    from normalized n
    left join public.umbrellas u
      on u.id = n.umbrella_id
    where n.take_target_ex > 0
  )
  select
    gen_random_uuid() as id,
    fa.pay_batch_candidate_id,
    'MANUAL_CREDIT_PAYOUT'::text as item_type,
    null::uuid as timesheet_id,
    null::text as segment_key,
    ('advance:' || fa.finance_case_id::text) as source_ref,
    'Manual credit adjustment payment'::text as description,
    round(fa.take_target_ex, 2) as amount_ex_vat,
    round(fa.take_target_vat, 2) as amount_vat,
    round(fa.take_target_inc, 2) as amount_inc_vat,
    fa.pay_channel,
    fa.umbrella_id,
    (fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(fa.source_pay_method,'')) <> upper(coalesce(fa.pay_channel,''))) as is_mismatch,
    fa.finance_case_id,
    fa.finance_component_id,
    fa.frozen_component_snapshot_json,
    fa.component_key_type,
    fa.component_key_value,
    fa.classification,
    fa.source_basis_json,
    fa.source_pay_method,
    fa.pay_channel,
    fa.frozen_resolution_mode,
    fa.frozen_resolution_payload_json,
    fa.frozen_resolution_result_json,
    round(fa.take_source_amount, 2),
    round(fa.take_target_ex, 2),
    round(fa.take_target_vat, 2),
    round(fa.take_target_inc, 2),
    jsonb_strip_nulls(
      jsonb_build_object(
        'taxability', fa.taxability,
        'routing_kind', fa.routing_kind,
        'destination_label', fa.destination_label,
        'pay_channel', fa.pay_channel,
        'payee_entity_kind', case when fa.is_candidate_directed_oneoff_payout then 'CANDIDATE' when fa.routing_kind = 'UMBRELLA_COMPANY' then 'UMBRELLA' else 'CANDIDATE' end,
        'beneficiary_name', fa.beneficiary_name,
        'masked_bank_account', fa.masked_bank_account,
        'bank_details_hash', fa.bank_details_hash,
        'appears_on_umbrella_remittance', fa.appears_on_umbrella_remittance,
        'generates_candidate_payment_advice', fa.generates_candidate_payment_advice,
        'payee_entity_id', case
          when fa.is_candidate_directed_oneoff_payout then (
            select pbc2.candidate_id::text
            from public.pay_batch_candidates pbc2
            where pbc2.id = fa.pay_batch_candidate_id
            limit 1
          )
          when fa.routing_kind = 'UMBRELLA_COMPANY' then case when fa.umbrella_id is null then null else fa.umbrella_id::text end
          else (
            select pbc2.candidate_id::text
            from public.pay_batch_candidates pbc2
            where pbc2.id = fa.pay_batch_candidate_id
            limit 1
          )
        end
      )
    ) as payout_instruction_snapshot_json,
    case when fa.pay_channel = 'PAYE' then coalesce(nullif(fa.paye_treatment,''),'GROSS_ADD') else 'NONE' end as paye_treatment
  from final_alloc fa
  where fa.take_target_ex > 0;

  get diagnostics v_rows_ins_manual_credit_payout_items = row_count;

  v_stage := 'STAGE_12E_FREEZE_FINANCE_PAYOUT_INSTRUCTIONS';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'helper_exists', (to_regprocedure('public._pay_finance_case_freeze_payout_instruction_to_batch_item(uuid,uuid)') is not null)
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  if to_regprocedure('public._pay_finance_case_freeze_payout_instruction_to_batch_item(uuid,uuid)') is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_CREATE_DRAFT_BATCH',
      'code', 'MISSING_PAYOUT_INSTRUCTION_FREEZE_HELPER',
      'message', 'pay_create_draft_batch: required helper public._pay_finance_case_freeze_payout_instruction_to_batch_item(uuid,uuid) is missing',
      'stage', v_stage,
      'pay_batch_id', v_batch_id::text
    )::text;
  end if;

  for v_payout_instruction_freeze_rec in
    select
      pbi.id as pay_batch_item_id,
      pbi.finance_case_id
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = v_batch_id
      and pbi.is_voided = false
      and pbi.finance_case_id is not null
      and pbi.item_type in ('LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT')
    order by pbi.id
  loop
    execute 'select public._pay_finance_case_freeze_payout_instruction_to_batch_item($1,$2)'
      using v_payout_instruction_freeze_rec.pay_batch_item_id, v_payout_instruction_freeze_rec.finance_case_id;
  end loop;

  v_stage := 'STAGE_13_DELETE_EMPTY_CANDIDATES';

  -- Remove any candidate rows that ended up with no items for this scoped batch
  select count(*)::int
  into v_candidate_rows_before_empty_delete
  from public.pay_batch_candidates pbc_before
  where pbc_before.pay_batch_id = v_batch_id;

  delete from public.pay_batch_candidates pbc_del
  where pbc_del.pay_batch_id = v_batch_id
    and not exists (
      select 1
      from public.pay_batch_items pbi_chk
      where pbi_chk.pay_batch_candidate_id = pbc_del.id
        and pbi_chk.item_type <> 'DEBT_CREATED'
      limit 1
    );

  GET DIAGNOSTICS v_rows_del_candidates = ROW_COUNT;

  select count(*)::int
  into v_candidate_rows_after_empty_delete
  from public.pay_batch_candidates pbc_after
  where pbc_after.pay_batch_id = v_batch_id;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_13_EMPTY_CANDIDATES_DELETED',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'candidate_rows_before_empty_delete', v_candidate_rows_before_empty_delete,
        'deleted_candidate_rows', v_rows_del_candidates,
        'candidate_rows_after_empty_delete', v_candidate_rows_after_empty_delete
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  v_stage := 'STAGE_14_ASSERT_ANY_CANDIDATES_REMAIN';

  if not exists (
    select 1
    from public.pay_batch_candidates pbc_any
    where pbc_any.pay_batch_id = v_batch_id
    limit 1
  ) then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_NOTHING_TO_PAY_FOR_SCOPE_AFTER_BLOCKERS',
        jsonb_build_object(
          'stage', v_stage,
          'pay_batch_id', v_batch_id::text,
          'scope', v_scope,
          'selected_preview_row_ids_present', v_selected_preview_row_ids_present,
          'selected_preview_rows_supplied', v_selected_preview_rows_supplied,
          'selected_preview_rows_mode', v_selected_preview_rows_mode,
          'selected_preview_rows_pre_selection_ct', v_selected_preview_rows_pre_selection_ct,
          'selected_preview_rows_post_selection_ct', v_selected_preview_rows_post_selection_ct,
          'candidate_rows_before_empty_delete', v_candidate_rows_before_empty_delete,
          'deleted_candidate_rows', v_rows_del_candidates,
          'candidate_rows_after_empty_delete', v_candidate_rows_after_empty_delete,
          'error', 'Nothing to pay (no payable items for scope after blockers)'
        ),
        'pay_batches',
        v_batch_id::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    raise exception 'Nothing to pay (no payable items for scope % after blockers)', v_scope;
  end if;

  v_stage := 'STAGE_15_DOUBLE_PAY_CONFLICT_CHECK';

  -- Policy X: numeric reservation overrun check (stable keys).
  -- Validate that THIS draft batch has not introduced or worsened an overrun on any
  -- stable key. Pre-existing stale reservations in other active batches must not block
  -- creation of a new draft; only new/worsened overrun caused by the current draft is an error.
  -- Stable keys come from _pay_outstanding_components / _pay_reserved_components:
  --   key_type: TS_DAY, TS_TOTAL, ADDITIONAL_CODE, ADJUSTMENT_CODE, EXPENSE_CODE
  --   key_value: work_date / TOTAL / adjustment_id / code
  --
  -- tolerance: 0.01 to avoid rounding noise false positives.
  with ts_ids_arr as (
    select
      array_agg(distinct pbi.timesheet_id) as timesheet_ids
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = v_batch_id
      and pbi.timesheet_id is not null
  ),
  reserved_raw as (
    select
      to_jsonb(rc) as j
    from public._pay_reserved_components((select t.timesheet_ids from ts_ids_arr t)) rc
  ),
  reserved_rows as (
    select
      nullif(btrim(coalesce(r.j->>'timesheet_id','')), '')::uuid as timesheet_id,
      upper(nullif(btrim(coalesce(r.j->>'key_type','')), '')) as key_type,
      nullif(btrim(coalesce(r.j->>'key_value','')), '') as key_value,
      round(
        coalesce(
          nullif(r.j->>'reserved_ex_vat','')::numeric,
          nullif(r.j->>'reserved_ex','')::numeric,
          nullif(r.j->>'reserved','')::numeric,
          nullif(r.j->>'amount_ex_vat','')::numeric,
          nullif(r.j->>'amount','')::numeric,
          0
        ),
        2
      ) as reserved_ex_vat
    from reserved_raw r
    where nullif(btrim(coalesce(r.j->>'timesheet_id','')), '') is not null
      and nullif(btrim(coalesce(r.j->>'key_type','')), '') is not null
      and nullif(btrim(coalesce(r.j->>'key_value','')), '') is not null
  ),
  reserved_sums as (
    select
      rr.timesheet_id,
      rr.key_type,
      rr.key_value,
      round(sum(coalesce(rr.reserved_ex_vat,0)),2) as reserved_ex_vat
    from reserved_rows rr
    where rr.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
    group by rr.timesheet_id, rr.key_type, rr.key_value
  ),
  outstanding_raw as (
    select
      to_jsonb(oc) as j
    from public._pay_outstanding_components((select t.timesheet_ids from ts_ids_arr t)) oc
  ),
  outstanding_rows_raw as (
    select
      nullif(btrim(coalesce(o.j->>'timesheet_id','')), '')::uuid as timesheet_id,
      upper(nullif(btrim(coalesce(o.j->>'key_type','')), '')) as key_type,
      nullif(btrim(coalesce(o.j->>'key_value','')), '') as key_value,
      round(
        coalesce(
          nullif(o.j->>'outstanding_ex_vat','')::numeric,
          nullif(o.j->>'outstanding_ex','')::numeric,
          nullif(o.j->>'outstanding','')::numeric,
          nullif(o.j->>'amount_ex_vat','')::numeric,
          nullif(o.j->>'amount','')::numeric,
          0
        ),
        2
      ) as outstanding_ex_vat
    from outstanding_raw o
    where nullif(btrim(coalesce(o.j->>'timesheet_id','')), '') is not null
      and nullif(btrim(coalesce(o.j->>'key_type','')), '') is not null
      and nullif(btrim(coalesce(o.j->>'key_value','')), '') is not null
  ),
  outstanding_rows as (
    select distinct on (orw_raw.timesheet_id, orw_raw.key_type, orw_raw.key_value)
      orw_raw.timesheet_id,
      orw_raw.key_type,
      orw_raw.key_value,
      round(coalesce(orw_raw.outstanding_ex_vat, 0), 2) as outstanding_ex_vat
    from outstanding_rows_raw orw_raw
    order by
      orw_raw.timesheet_id,
      orw_raw.key_type,
      orw_raw.key_value,
      coalesce(orw_raw.outstanding_ex_vat, 0) desc
  ),
  current_batch_items as (
    select
      pbi.id as pay_batch_item_id,
      pbc.pay_batch_id as pay_batch_id,
      pbi.timesheet_id as timesheet_id,
      pbi.item_type as item_type,
      pbi.segment_key as segment_key,
      pbi.source_ref as source_ref,
      pbi.finance_component_id as finance_component_id,
      pbi.frozen_component_key_type as frozen_component_key_type,
      pbi.frozen_component_key_value as frozen_component_key_value,
      pbi.frozen_component_snapshot_json as frozen_component_snapshot_json,
      pbi.frozen_source_basis_json as frozen_source_basis_json,
      pfc.component_key_type as live_component_key_type,
      pfc.component_key_value as live_component_key_value,
      round(
        coalesce(
          pbi.amount_ex_vat,
          pbi.frozen_target_amount_ex_vat,
          pbi.amount_inc_vat,
          pbi.frozen_target_amount_inc_vat,
          0
        ),
        2
      ) as amount_ex_vat
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    left join public.pay_finance_case_components pfc
      on pfc.id = pbi.finance_component_id
    where pbc.pay_batch_id = v_batch_id
      and pbi.timesheet_id is not null
      and coalesce(pbi.is_voided,false) = false
      and pbi.item_type in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
  ),
  current_batch_snapshot_choice as (
    select
      cbi.pay_batch_id,
      cbi.timesheet_id,
      (
        select pbs1.target_snapshot_json
        from public.pay_batch_timesheet_snapshots pbs1
        where pbs1.pay_batch_id = cbi.pay_batch_id
          and pbs1.timesheet_id = cbi.timesheet_id
        order by pbs1.created_at_utc desc, pbs1.id desc
        limit 1
      ) as target_snapshot_json
    from (
      select distinct
        cbi.pay_batch_id,
        cbi.timesheet_id
      from current_batch_items cbi
    ) cbi
  ),
  current_batch_seg_lookup as (
    select
      cbi.pay_batch_id,
      cbi.timesheet_id,
      coalesce(
        nullif(btrim(coalesce(cbi.segment_key,'')), ''),
        case
          when cbi.source_ref is not null and btrim(cbi.source_ref) like 'seg:%'
            then nullif(btrim(split_part(cbi.source_ref,':',2)), '')
          else null
        end
      ) as seg_id
    from current_batch_items cbi
    where cbi.item_type = 'SEGMENT_DELTA'
  ),
  current_batch_seg_date_map as (
    select
      csl.pay_batch_id,
      csl.timesheet_id,
      csl.seg_id,
      nullif(btrim(coalesce(seg.value->>'date','')), '') as seg_date_raw
    from current_batch_seg_lookup csl
    join current_batch_snapshot_choice csc
      on csc.pay_batch_id = csl.pay_batch_id
     and csc.timesheet_id = csl.timesheet_id
    join lateral jsonb_array_elements(coalesce(csc.target_snapshot_json->'segments','[]'::jsonb)) as seg(value)
      on true
    where csl.seg_id is not null
      and seg.value is not null
      and jsonb_typeof(seg.value) = 'object'
      and nullif(btrim(coalesce(seg.value->>'segment_id','')), '') = csl.seg_id
  ),
  current_batch_seg_date_final as (
    select
      csdm.pay_batch_id,
      csdm.timesheet_id,
      csdm.seg_id,
      case
        when csdm.seg_date_raw ~ '^\d{4}-\d{2}-\d{2}$' then csdm.seg_date_raw
        else null
      end as seg_date
    from current_batch_seg_date_map csdm
  ),
  current_batch_keyed as (
    select
      cbi.timesheet_id,
      coalesce(
        nullif(btrim(coalesce(cbi.frozen_component_key_type,'')), ''),
        nullif(
          btrim(
            coalesce(
              cbi.frozen_component_snapshot_json->>'component_key_type',
              cbi.frozen_component_snapshot_json->>'key_type',
              ''
            )
          ),
          ''
        ),
        case
          when cbi.item_type = 'SEGMENT_DELTA'
            then case when cbsdf.seg_date is not null then 'TS_DAY' else 'TS_TOTAL' end
          when cbi.item_type = 'MILEAGE_DELTA'
            then 'EXPENSE_CODE'
          when cbi.item_type = 'ADJUSTMENT_DELTA'
            then case
              when cbi.source_ref is not null and btrim(cbi.source_ref) like 'preview_seg:%'
                then 'TS_TOTAL'
              else 'ADJUSTMENT_CODE'
            end
          when cbi.item_type = 'EXPENSE_DELTA'
            then case
              when cbi.source_ref is not null and (
                btrim(cbi.source_ref) like 'additional:%'
                or btrim(cbi.source_ref) like 'add:%'
                or btrim(cbi.source_ref) = 'additional'
              )
                then 'ADDITIONAL_CODE'
              else 'EXPENSE_CODE'
            end
          else 'EXPENSE_CODE'
        end
      ) as key_type,
      coalesce(
        nullif(btrim(coalesce(cbi.frozen_component_key_value,'')), ''),
        nullif(
          btrim(
            coalesce(
              cbi.frozen_component_snapshot_json->>'component_key_value',
              cbi.frozen_component_snapshot_json->>'key_value',
              ''
            )
          ),
          ''
        ),
        case
          when cbi.item_type = 'SEGMENT_DELTA'
            then coalesce(cbsdf.seg_date, 'TOTAL')
          when cbi.item_type = 'MILEAGE_DELTA'
            then 'MILEAGE'
          when cbi.item_type = 'ADJUSTMENT_DELTA'
            then case
              when cbi.source_ref is not null and btrim(cbi.source_ref) like 'preview_seg:%'
                then 'TOTAL'
              when nullif(btrim(coalesce(cbi.frozen_source_basis_json->>'adjustment_id','')), '') is not null
                then nullif(btrim(coalesce(cbi.frozen_source_basis_json->>'adjustment_id','')), '')
              when cbi.source_ref is not null and btrim(cbi.source_ref) like 'adj:%'
                then case
                  when nullif(btrim(split_part(cbi.source_ref,':',2)), '') is null
                    or btrim(split_part(cbi.source_ref,':',2)) like 'preview_adj_%'
                    then 'TOTAL'
                  else nullif(btrim(split_part(cbi.source_ref,':',2)), '')
                end
              else 'TOTAL'
            end
          when cbi.item_type = 'EXPENSE_DELTA'
            then case
              when cbi.source_ref is not null and (
                btrim(cbi.source_ref) like 'additional:%'
                or btrim(cbi.source_ref) like 'add:%'
              )
                then upper(nullif(btrim(split_part(cbi.source_ref,':',2)), ''))
              when cbi.source_ref is not null and btrim(cbi.source_ref) = 'additional'
                then 'TOTAL'
              when cbi.source_ref is not null and btrim(cbi.source_ref) <> ''
                then upper(btrim(cbi.source_ref))
              else 'UNKNOWN'
            end
          else 'UNKNOWN'
        end
      ) as key_value,
      cbi.amount_ex_vat
    from current_batch_items cbi
    left join current_batch_seg_date_final cbsdf
      on cbsdf.pay_batch_id = cbi.pay_batch_id
     and cbsdf.timesheet_id = cbi.timesheet_id
     and cbsdf.seg_id = coalesce(
       nullif(btrim(coalesce(cbi.segment_key,'')), ''),
       case
         when cbi.source_ref is not null and btrim(cbi.source_ref) like 'seg:%'
           then nullif(btrim(split_part(cbi.source_ref,':',2)), '')
         else null
       end
     )
    where cbi.item_type in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
  ),
  current_batch_reserved_sums as (
    select
      c.timesheet_id,
      c.key_type,
      c.key_value,
      round(sum(coalesce(c.amount_ex_vat,0)),2) as current_batch_reserved_ex_vat
    from current_batch_keyed c
    where c.key_value is not null
      and btrim(coalesce(c.key_value,'')) <> ''
      and c.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
    group by c.timesheet_id, c.key_type, c.key_value
  ),
  key_union as (
    select rs.timesheet_id, rs.key_type, rs.key_value
    from reserved_sums rs
    union
    select orw.timesheet_id, orw.key_type, orw.key_value
    from outstanding_rows orw
    where orw.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
    union
    select cbr.timesheet_id, cbr.key_type, cbr.key_value
    from current_batch_reserved_sums cbr
  ),
  ts_total_day_fallback as (
    select
      orw.timesheet_id,
      round(
        sum(
          case
            when orw.key_type = 'TS_DAY' and coalesce(orw.outstanding_ex_vat,0) > 0
              then coalesce(orw.outstanding_ex_vat,0)
            else 0
          end
        ),
        2
      ) as ts_total_payable_fallback_ex_vat
    from outstanding_rows orw
    group by orw.timesheet_id
  ),
  checks as (
    select
      ku.timesheet_id,
      ku.key_type,
      ku.key_value,
      round(coalesce(rs.reserved_ex_vat,0),2) as reserved_total_ex_vat,
      round(coalesce(cbr.current_batch_reserved_ex_vat,0),2) as current_batch_reserved_ex_vat,
      round(greatest(coalesce(rs.reserved_ex_vat,0) - coalesce(cbr.current_batch_reserved_ex_vat,0), 0),2) as reserved_before_ex_vat,
      case
        when ku.key_type = 'TS_TOTAL'
         and orw.timesheet_id is null
        then round(greatest(coalesce(tdf.ts_total_payable_fallback_ex_vat,0), 0), 2)
        else round(
          greatest(
            coalesce(rs.reserved_ex_vat,0) + coalesce(orw.outstanding_ex_vat,0),
            0
          ),
          2
        )
      end as payable_possible_ex_vat,
      0.01::numeric as tolerance_ex_vat
    from key_union ku
    left join reserved_sums rs
      on rs.timesheet_id = ku.timesheet_id
     and rs.key_type = ku.key_type
     and rs.key_value = ku.key_value
    left join outstanding_rows orw
      on orw.timesheet_id = ku.timesheet_id
     and orw.key_type = ku.key_type
     and orw.key_value = ku.key_value
    left join current_batch_reserved_sums cbr
      on cbr.timesheet_id = ku.timesheet_id
     and cbr.key_type = ku.key_type
     and cbr.key_value = ku.key_value
    left join ts_total_day_fallback tdf
      on tdf.timesheet_id = ku.timesheet_id
  ),
  overruns as (
    select
      c.timesheet_id,
      c.key_type,
      c.key_value,
      c.reserved_total_ex_vat,
      c.current_batch_reserved_ex_vat,
      c.reserved_before_ex_vat,
      c.payable_possible_ex_vat,
      round(greatest(c.reserved_total_ex_vat - c.payable_possible_ex_vat, 0),2) as overrun_after_ex_vat,
      round(greatest(c.reserved_before_ex_vat - c.payable_possible_ex_vat, 0),2) as overrun_before_ex_vat,
      c.tolerance_ex_vat
    from checks c
    where round(greatest(c.reserved_total_ex_vat - c.payable_possible_ex_vat, 0),2)
            > round(greatest(c.reserved_before_ex_vat - c.payable_possible_ex_vat, 0),2) + c.tolerance_ex_vat
  )
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'timesheet_id', overruns.timesheet_id::text,
          'key_type', overruns.key_type,
          'key_value', overruns.key_value,
          'reserved_total_ex_vat', overruns.reserved_total_ex_vat,
          'current_batch_reserved_ex_vat', overruns.current_batch_reserved_ex_vat,
          'reserved_before_ex_vat', overruns.reserved_before_ex_vat,
          'payable_possible_ex_vat', overruns.payable_possible_ex_vat,
          'overrun_before_ex_vat', overruns.overrun_before_ex_vat,
          'overrun_after_ex_vat', overruns.overrun_after_ex_vat,
          'tolerance_ex_vat', overruns.tolerance_ex_vat
        )
        order by overruns.timesheet_id::text, overruns.key_type, overruns.key_value
      ),
      '[]'::jsonb
    ),
    (select count(*)::int from reserved_sums),
    (select count(*)::int from outstanding_rows orw where orw.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')),
    (select count(*)::int from current_batch_reserved_sums),
    (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'timesheet_id', rs.timesheet_id::text,
            'key_type', rs.key_type,
            'key_value', rs.key_value,
            'reserved_ex_vat', rs.reserved_ex_vat
          )
          order by rs.timesheet_id::text, rs.key_type, rs.key_value
        ),
        '[]'::jsonb
      )
      from (
        select
          rs.timesheet_id,
          rs.key_type,
          rs.key_value,
          rs.reserved_ex_vat
        from reserved_sums rs
        order by rs.timesheet_id::text, rs.key_type, rs.key_value
        limit 50
      ) rs
    ),
    (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'timesheet_id', orw.timesheet_id::text,
            'key_type', orw.key_type,
            'key_value', orw.key_value,
            'outstanding_ex_vat', orw.outstanding_ex_vat
          )
          order by orw.timesheet_id::text, orw.key_type, orw.key_value
        ),
        '[]'::jsonb
      )
      from (
        select
          orw.timesheet_id,
          orw.key_type,
          orw.key_value,
          orw.outstanding_ex_vat
        from outstanding_rows orw
        where orw.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
        order by orw.timesheet_id::text, orw.key_type, orw.key_value
        limit 50
      ) orw
    ),
    (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'timesheet_id', cbr.timesheet_id::text,
            'key_type', cbr.key_type,
            'key_value', cbr.key_value,
            'current_batch_reserved_ex_vat', cbr.current_batch_reserved_ex_vat
          )
          order by cbr.timesheet_id::text, cbr.key_type, cbr.key_value
        ),
        '[]'::jsonb
      )
      from (
        select
          cbr.timesheet_id,
          cbr.key_type,
          cbr.key_value,
          cbr.current_batch_reserved_ex_vat
        from current_batch_reserved_sums cbr
        order by cbr.timesheet_id::text, cbr.key_type, cbr.key_value
        limit 50
      ) cbr
    ),
    (
      select coalesce(
        jsonb_agg(x.timesheet_id_text order by x.timesheet_id_text),
        '[]'::jsonb
      )
      from (
        select distinct
          tid::text as timesheet_id_text
        from ts_ids_arr t
        cross join lateral unnest(coalesce(t.timesheet_ids, array[]::uuid[])) as u(tid)
        order by tid::text
        limit 50
      ) x
    ),
    (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'pay_batch_item_id', cbi.pay_batch_item_id::text,
            'timesheet_id', cbi.timesheet_id::text,
            'item_type', cbi.item_type,
            'segment_key', cbi.segment_key,
            'source_ref', cbi.source_ref,
            'finance_component_id', case when cbi.finance_component_id is null then null else cbi.finance_component_id::text end,
            'frozen_component_key_type', cbi.frozen_component_key_type,
            'frozen_component_key_value', cbi.frozen_component_key_value,
            'frozen_snapshot_key_type', nullif(
              btrim(
                coalesce(
                  cbi.frozen_component_snapshot_json->>'component_key_type',
                  cbi.frozen_component_snapshot_json->>'key_type',
                  ''
                )
              ),
              ''
            ),
            'frozen_snapshot_key_value', nullif(
              btrim(
                coalesce(
                  cbi.frozen_component_snapshot_json->>'component_key_value',
                  cbi.frozen_component_snapshot_json->>'key_value',
                  ''
                )
              ),
              ''
            ),
            'frozen_source_basis_work_date', nullif(btrim(coalesce(cbi.frozen_source_basis_json->>'work_date','')), ''),
            'live_component_key_type', cbi.live_component_key_type,
            'live_component_key_value', cbi.live_component_key_value,
            'amount_ex_vat', cbi.amount_ex_vat
          )
          order by cbi.timesheet_id::text, cbi.item_type, coalesce(cbi.segment_key,''), coalesce(cbi.source_ref,''), cbi.pay_batch_item_id::text
        ),
        '[]'::jsonb
      )
      from (
        select *
        from current_batch_items cbi
        order by cbi.timesheet_id::text, cbi.item_type, coalesce(cbi.segment_key,''), coalesce(cbi.source_ref,''), cbi.pay_batch_item_id::text
        limit 50
      ) cbi
    ),
    (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'timesheet_id', cbk.timesheet_id::text,
            'key_type', cbk.key_type,
            'key_value', cbk.key_value,
            'amount_ex_vat', cbk.amount_ex_vat
          )
          order by cbk.timesheet_id::text, cbk.key_type, cbk.key_value, cbk.amount_ex_vat
        ),
        '[]'::jsonb
      )
      from (
        select *
        from current_batch_keyed cbk
        order by cbk.timesheet_id::text, cbk.key_type, cbk.key_value, cbk.amount_ex_vat
        limit 50
      ) cbk
    ),
    (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'timesheet_id', chk.timesheet_id::text,
            'key_type', chk.key_type,
            'key_value', chk.key_value,
            'reserved_total_ex_vat', chk.reserved_total_ex_vat,
            'current_batch_reserved_ex_vat', chk.current_batch_reserved_ex_vat,
            'reserved_before_ex_vat', chk.reserved_before_ex_vat,
            'payable_possible_ex_vat', chk.payable_possible_ex_vat,
            'tolerance_ex_vat', chk.tolerance_ex_vat
          )
          order by chk.timesheet_id::text, chk.key_type, chk.key_value
        ),
        '[]'::jsonb
      )
      from (
        select *
        from checks chk
        order by chk.timesheet_id::text, chk.key_type, chk.key_value
        limit 50
      ) chk
    )
  into
    v_reserved,
    v_stage_15_reserved_key_count,
    v_stage_15_outstanding_key_count,
    v_stage_15_current_batch_key_count,
    v_stage_15_reserved_keys_sample,
    v_stage_15_outstanding_keys_sample,
    v_stage_15_current_batch_keys_sample,
    v_stage_15_ts_ids_sample,
    v_stage_15_current_batch_items_sample,
    v_stage_15_current_batch_keyed_sample,
    v_stage_15_checks_sample
  from overruns;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_15_RESERVATION_OVERRUN_CHECK_RESULT',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'overruns', v_reserved,
        'overrun_count', jsonb_array_length(v_reserved),
        'reserved_key_count', v_stage_15_reserved_key_count,
        'outstanding_key_count', v_stage_15_outstanding_key_count,
        'current_batch_key_count', v_stage_15_current_batch_key_count,
        'reserved_keys_sample', v_stage_15_reserved_keys_sample,
        'outstanding_keys_sample', v_stage_15_outstanding_keys_sample,
        'current_batch_keys_sample', v_stage_15_current_batch_keys_sample,
        'timesheet_ids_sample', v_stage_15_ts_ids_sample,
        'current_batch_items_sample', v_stage_15_current_batch_items_sample,
        'current_batch_keyed_sample', v_stage_15_current_batch_keyed_sample,
        'checks_sample', v_stage_15_checks_sample
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  if jsonb_array_length(v_reserved) > 0 then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_PAY_BATCH_RESERVATION_OVERRUN',
        jsonb_build_object(
          'stage', v_stage,
          'pay_batch_id', v_batch_id::text,
          'overruns', v_reserved,
          'reserved_key_count', v_stage_15_reserved_key_count,
          'outstanding_key_count', v_stage_15_outstanding_key_count,
          'current_batch_key_count', v_stage_15_current_batch_key_count,
          'reserved_keys_sample', v_stage_15_reserved_keys_sample,
          'outstanding_keys_sample', v_stage_15_outstanding_keys_sample,
          'current_batch_keys_sample', v_stage_15_current_batch_keys_sample,
          'error', 'PAY_BATCH_RESERVATION_OVERRUN'
        ),
        'pay_batches',
        v_batch_id::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_RESERVATION_OVERRUN',
      'stage', v_stage,
      'pay_batch_id', v_batch_id::text,
      'overruns', v_reserved,
      'reserved_key_count', v_stage_15_reserved_key_count,
      'outstanding_key_count', v_stage_15_outstanding_key_count,
      'current_batch_key_count', v_stage_15_current_batch_key_count,
      'reserved_keys_sample', v_stage_15_reserved_keys_sample,
      'outstanding_keys_sample', v_stage_15_outstanding_keys_sample,
      'current_batch_keys_sample', v_stage_15_current_batch_keys_sample,
      'timesheet_ids_sample', v_stage_15_ts_ids_sample,
      'current_batch_items_sample', v_stage_15_current_batch_items_sample,
      'current_batch_keyed_sample', v_stage_15_current_batch_keyed_sample,
      'checks_sample', v_stage_15_checks_sample
    )::text;
  end if;

  v_stage := 'STAGE_16A_SET_PAYE_AWAITING_NET_MARKER';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  update public.pay_batch_candidates pbc
  set
    awaiting_net_amount = (
      (v_scope = 'PAYE')
      and not exists (
        select 1
        from public.pay_batch_paye_net_inputs pni
        where pni.pay_batch_candidate_id = pbc.id
      )
    ),
    updated_at = v_now_utc
  where pbc.pay_batch_id = v_batch_id;

  get diagnostics v_rows_upd_candidates_paye_awaiting = row_count;
  v_rows_ins_overpayment_recovery_items := 0;
  v_rows_upd_candidates_overpayment_recovery_taken := 0;

  v_stage := 'STAGE_16AA_APPLY_OVERPAYMENT_RECOVERY';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  insert into public.pay_batch_items (
    id,
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    repayment_week_start,
    pay_channel,
    umbrella_id,
    is_mismatch,
    is_voided,
    created_at,
    updated_at,
    finance_case_id,
    reservation_id,
    paye_treatment,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat
  )
  with selected_case_rows as (
    select distinct on (spr.finance_case_id)
      pbc.id as pay_batch_candidate_id,
      spr.candidate_id,
      spr.finance_case_id,
      upper(coalesce(nullif(spr.pay_channel,''), v_scope)) as pay_channel,
      upper(coalesce(nullif(spr.paye_treatment,''), 'NONE')) as paye_treatment,
      case when upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = 'UMBRELLA' then c.umbrella_id else null::uuid end as umbrella_id,
      round(abs(coalesce(spr.preview_amount_ex_vat, 0)), 2)::numeric(12,2) as due_amount_ex_vat,
      coalesce(spr.case_components_json, '[]'::jsonb) as case_components_json
    from pg_temp.tmp_pay_selected_preview_rows spr
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = v_batch_id
     and pbc.candidate_id = spr.candidate_id
    join public.candidates c
      on c.id = spr.candidate_id
    where spr.draftable = true
      and spr.line_type = 'OVERPAYMENT_RECOVERY'
      and spr.finance_case_id is not null
      and upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = v_scope
      and spr.candidate_id = any(v_candidate_ids)
      and (v_client_filter_single is null or spr.client_id = v_client_filter_single)
      and abs(coalesce(spr.preview_amount_ex_vat, 0)) > 0
    order by spr.finance_case_id, spr.preview_row_id
  ),
  component_rows as (
    select
      scr.pay_batch_candidate_id,
      scr.candidate_id,
      scr.finance_case_id,
      scr.pay_channel,
      scr.paye_treatment,
      scr.umbrella_id,
      scr.due_amount_ex_vat,
      comp.comp_json,
      case
        when nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), '') is null then null::uuid
        else (comp.comp_json->>'finance_component_id')::uuid
      end as finance_component_id,
      nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), '') as component_key_type,
      coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), 'TOTAL') as component_key_value,
      case
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'TAXABLE_CHANNEL_SENSITIVE' then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'REIMBURSEMENT_GROSS_FIXED' then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'NET_PAY_FIXED_RECOVERY' then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
        else null::public.pay_finance_component_classification_enum
      end as classification,
      upper(btrim(coalesce(comp.comp_json->>'source_pay_method',''))) as source_pay_method,
      coalesce(comp.comp_json->'source_basis_json', '{}'::jsonb) as source_basis_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_payload_json') = 'object' then comp.comp_json->'saved_resolution_payload_json'
        else null::jsonb
      end as saved_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_result_json') = 'object' then comp.comp_json->'saved_resolution_result_json'
        else null::jsonb
      end as saved_resolution_result_json,
      nullif(btrim(coalesce(comp.comp_json->>'saved_resolution_mode','')), '') as saved_resolution_mode_text,
      round(
        case
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as remaining_source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'allocated_source_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'allocated_source_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as allocated_source_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as preview_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'target_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'target_pay_ex_vat')::numeric
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as target_pay_ex_vat,
      case
        when coalesce(comp.comp_json->>'source_units','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_units')::numeric, 6)
        else null::numeric
      end as source_units,
      case
        when coalesce(comp.comp_json->>'source_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_rate')::numeric, 2)
        else null::numeric
      end as source_rate,
      case
        when coalesce(comp.comp_json->>'target_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_rate')::numeric, 2)
        else null::numeric
      end as target_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_rate')::numeric, 2)
        else null::numeric
      end as source_charge_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as source_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as target_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_margin_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_margin_ex_vat')::numeric, 2)
        else null::numeric
      end as target_margin_ex_vat,
      case
        when coalesce(comp.comp_json->>'margin_delta_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'margin_delta_ex_vat')::numeric, 2)
        else null::numeric
      end as margin_delta_ex_vat,
      row_number() over (
        partition by scr.finance_case_id
        order by
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), ''), md5(comp.comp_json::text)),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), ''), ''),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), '')
      ) as component_rn,
      count(*) over (partition by scr.finance_case_id) as component_ct,
      round(sum(
        round(
          case
            when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
            else 0
          end,
          2
        )
      ) over (partition by scr.finance_case_id), 2)::numeric(12,2) as component_preview_due_sum
    from selected_case_rows scr
    cross join lateral jsonb_array_elements(coalesce(scr.case_components_json, '[]'::jsonb)) as comp(comp_json)
    where jsonb_typeof(comp.comp_json) = 'object'
      and round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      ) > 0
  ),
  normalized as (
    select
      cr.*,
      round(
        case
          when cr.component_ct = 1 then cr.due_amount_ex_vat
          when cr.component_rn = 1 then greatest(cr.due_amount_ex_vat - (coalesce(cr.component_preview_due_sum, 0) - coalesce(cr.preview_due_amount_ex_vat, 0)), 0)
          else cr.preview_due_amount_ex_vat
        end,
        2
      )::numeric(12,2) as take_target_ex
    from component_rows cr
  ),
  final_alloc as (
    select
      n.pay_batch_candidate_id,
      n.finance_case_id,
      n.pay_channel,
      n.paye_treatment,
      n.umbrella_id,
      n.finance_component_id,
      n.component_key_type,
      n.component_key_value,
      n.classification,
      n.source_pay_method,
      n.source_basis_json,
      case
        when n.saved_resolution_mode_text is not null then n.saved_resolution_mode_text::public.pay_finance_component_resolution_mode_enum
        when n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and upper(coalesce(n.source_pay_method,'')) <> upper(coalesce(n.pay_channel,''))
        then 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
        else null::public.pay_finance_component_resolution_mode_enum
      end as frozen_resolution_mode,
      case
        when jsonb_typeof(n.saved_resolution_payload_json) = 'object' then jsonb_strip_nulls(
          n.saved_resolution_payload_json
          || jsonb_build_object(
            'target_pay_method', n.pay_channel,
            'target_units', n.source_units,
            'suggested_target_rate', n.target_rate,
            'source_rate', n.source_rate,
            'source_charge_rate', n.source_charge_rate
          )
        )
        else jsonb_strip_nulls(jsonb_build_object(
          'target_pay_method', n.pay_channel,
          'target_units', n.source_units,
          'suggested_target_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate
        ))
      end as frozen_resolution_payload_json,
      round(
        case
          when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
          when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
          else 0
        end,
        2
      )::numeric(12,2) as take_source_amount,
      round(n.take_target_ex, 2)::numeric(12,2) as take_target_ex,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as take_target_vat,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
          else round(n.take_target_ex, 2)
        end,
        2
      )::numeric(12,2) as take_target_inc,
      jsonb_strip_nulls(
        coalesce(n.comp_json, '{}'::jsonb)
        || jsonb_build_object(
          'frozen_target_pay_method', n.pay_channel,
          'frozen_source_amount', round(
            case
              when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
              when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
              else 0
            end,
            2
          ),
          'frozen_target_amount_ex_vat', round(-n.take_target_ex, 2),
          'frozen_target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'frozen_target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'selected_preview_due_amount_ex_vat', round(n.due_amount_ex_vat, 2),
          'component_preview_due_amount_ex_vat', round(n.take_target_ex, 2)
        )
      ) as frozen_component_snapshot_json,
      jsonb_strip_nulls(
        coalesce(n.saved_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'target_pay_method', n.pay_channel,
          'target_amount_ex_vat', round(n.take_target_ex, 2),
          'target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'replacement_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate,
          'source_charge_ex_vat', n.source_charge_ex_vat,
          'target_charge_ex_vat', n.target_charge_ex_vat,
          'target_margin_ex_vat', n.target_margin_ex_vat,
          'margin_delta_ex_vat', n.margin_delta_ex_vat
        )
      ) as frozen_resolution_result_json
    from normalized n
    left join public.umbrellas u
      on u.id = n.umbrella_id
    where n.take_target_ex > 0
  )
  select
    gen_random_uuid() as id,
    fa.pay_batch_candidate_id,
    'OVERPAYMENT_RECOVERY' as item_type,
    null::uuid as timesheet_id,
    null::text as segment_key,
    ('advance:' || fa.finance_case_id::text) as source_ref,
    (-fa.take_target_ex)::numeric(12,2) as amount_ex_vat,
    (-fa.take_target_vat)::numeric(12,2) as amount_vat,
    (-fa.take_target_inc)::numeric(12,2) as amount_inc_vat,
    v_week_start as repayment_week_start,
    fa.pay_channel as pay_channel,
    fa.umbrella_id as umbrella_id,
    (fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(fa.source_pay_method,'')) <> upper(coalesce(fa.pay_channel,''))) as is_mismatch,
    false as is_voided,
    v_now_utc as created_at,
    v_now_utc as updated_at,
    fa.finance_case_id,
    null::uuid as reservation_id,
    fa.paye_treatment,
    fa.finance_component_id,
    fa.frozen_component_snapshot_json,
    fa.component_key_type,
    fa.component_key_value,
    fa.classification,
    fa.source_basis_json,
    fa.source_pay_method,
    fa.pay_channel,
    fa.frozen_resolution_mode,
    fa.frozen_resolution_payload_json,
    fa.frozen_resolution_result_json,
    fa.take_source_amount,
    round(-fa.take_target_ex, 2),
    round(-fa.take_target_vat, 2),
    round(-fa.take_target_inc, 2)
  from final_alloc fa
  where fa.take_target_ex > 0;

  get diagnostics v_rows_ins_overpayment_recovery_items = row_count;


  update public.pay_batch_candidates pbc
  set
    overpayment_recovery_taken = coalesce((
      select round(sum(-pbi.amount_ex_vat), 2)
      from public.pay_batch_items pbi
      where pbi.pay_batch_candidate_id = pbc.id
        and pbi.is_voided = false
        and pbi.item_type = 'OVERPAYMENT_RECOVERY'
    ), 0)::numeric(12,2),
    updated_at = v_now_utc
  where pbc.pay_batch_id = v_batch_id;

  get diagnostics v_rows_upd_candidates_overpayment_recovery_taken = row_count;

  v_rows_ins_debt_items := 0;

v_stage := 'STAGE_16B_APPLY_MANUAL_DEBT_RECOVERY';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  insert into public.pay_batch_items (
    id,
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    repayment_week_start,
    pay_channel,
    umbrella_id,
    is_mismatch,
    is_voided,
    created_at,
    updated_at,
    finance_case_id,
    reservation_id,
    paye_treatment,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat
  )
  with selected_case_rows as (
    select distinct on (spr.finance_case_id)
      pbc.id as pay_batch_candidate_id,
      spr.candidate_id,
      spr.finance_case_id,
      upper(coalesce(nullif(spr.pay_channel,''), v_scope)) as pay_channel,
      upper(coalesce(nullif(spr.paye_treatment,''), 'NONE')) as paye_treatment,
      case when upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = 'UMBRELLA' then c.umbrella_id else null::uuid end as umbrella_id,
      round(abs(coalesce(spr.preview_amount_ex_vat, 0)), 2)::numeric(12,2) as due_amount_ex_vat,
      coalesce(spr.case_components_json, '[]'::jsonb) as case_components_json
    from pg_temp.tmp_pay_selected_preview_rows spr
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = v_batch_id
     and pbc.candidate_id = spr.candidate_id
    join public.candidates c
      on c.id = spr.candidate_id
    where spr.draftable = true
      and spr.line_type = 'MANUAL_DEBT_RECOVERY'
      and spr.finance_case_id is not null
      and upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = v_scope
      and spr.candidate_id = any(v_candidate_ids)
      and (v_client_filter_single is null or spr.client_id = v_client_filter_single)
      and abs(coalesce(spr.preview_amount_ex_vat, 0)) > 0
    order by spr.finance_case_id, spr.preview_row_id
  ),
  component_rows as (
    select
      scr.pay_batch_candidate_id,
      scr.candidate_id,
      scr.finance_case_id,
      scr.pay_channel,
      scr.paye_treatment,
      scr.umbrella_id,
      scr.due_amount_ex_vat,
      comp.comp_json,
      case
        when nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), '') is null then null::uuid
        else (comp.comp_json->>'finance_component_id')::uuid
      end as finance_component_id,
      nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), '') as component_key_type,
      coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), 'TOTAL') as component_key_value,
      case
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'TAXABLE_CHANNEL_SENSITIVE' then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'REIMBURSEMENT_GROSS_FIXED' then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'NET_PAY_FIXED_RECOVERY' then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
        else null::public.pay_finance_component_classification_enum
      end as classification,
      upper(btrim(coalesce(comp.comp_json->>'source_pay_method',''))) as source_pay_method,
      coalesce(comp.comp_json->'source_basis_json', '{}'::jsonb) as source_basis_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_payload_json') = 'object' then comp.comp_json->'saved_resolution_payload_json'
        else null::jsonb
      end as saved_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_result_json') = 'object' then comp.comp_json->'saved_resolution_result_json'
        else null::jsonb
      end as saved_resolution_result_json,
      case
        when jsonb_typeof(comp.comp_json->'suggested_resolution_payload_json') = 'object' then comp.comp_json->'suggested_resolution_payload_json'
        else null::jsonb
      end as preview_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'suggested_resolution_result_json') = 'object' then comp.comp_json->'suggested_resolution_result_json'
        else null::jsonb
      end as preview_resolution_result_json,
      nullif(btrim(coalesce(comp.comp_json->>'saved_resolution_mode','')), '') as saved_resolution_mode_text,
      nullif(btrim(coalesce(comp.comp_json->'suggested_resolution_payload_json'->>'resolution_mode','')), '') as preview_resolution_mode_text,
      round(
        case
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as remaining_source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'allocated_source_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'allocated_source_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as allocated_source_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as preview_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->'suggested_resolution_result_json'->>'target_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->'suggested_resolution_result_json'->>'target_amount_ex_vat')::numeric
          when coalesce(comp.comp_json->>'target_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'target_pay_ex_vat')::numeric
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as target_pay_ex_vat,
      case
        when coalesce(comp.comp_json->>'source_units','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_units')::numeric, 6)
        else null::numeric
      end as source_units,
      case
        when coalesce(comp.comp_json->>'source_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_rate')::numeric, 2)
        else null::numeric
      end as source_rate,
      case
        when coalesce(comp.comp_json->>'target_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_rate')::numeric, 2)
        else null::numeric
      end as target_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_rate')::numeric, 2)
        else null::numeric
      end as source_charge_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as source_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as target_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_margin_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_margin_ex_vat')::numeric, 2)
        else null::numeric
      end as target_margin_ex_vat,
      case
        when coalesce(comp.comp_json->>'margin_delta_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'margin_delta_ex_vat')::numeric, 2)
        else null::numeric
      end as margin_delta_ex_vat,
      row_number() over (
        partition by scr.finance_case_id
        order by
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), ''), md5(comp.comp_json::text)),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), ''), ''),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), '')
      ) as component_rn,
      count(*) over (partition by scr.finance_case_id) as component_ct,
      round(sum(
        round(
          case
            when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
            else 0
          end,
          2
        )
      ) over (partition by scr.finance_case_id), 2)::numeric(12,2) as component_preview_due_sum
    from selected_case_rows scr
    cross join lateral jsonb_array_elements(coalesce(scr.case_components_json, '[]'::jsonb)) as comp(comp_json)
    where jsonb_typeof(comp.comp_json) = 'object'
      and round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      ) > 0
  ),
  normalized as (
    select
      cr.*,
      round(
        case
          when cr.component_ct = 1 then cr.due_amount_ex_vat
          when cr.component_rn = 1 then greatest(cr.due_amount_ex_vat - (coalesce(cr.component_preview_due_sum, 0) - coalesce(cr.preview_due_amount_ex_vat, 0)), 0)
          else cr.preview_due_amount_ex_vat
        end,
        2
      )::numeric(12,2) as take_target_ex
    from component_rows cr
  ),
  final_alloc as (
    select
      n.pay_batch_candidate_id,
      n.finance_case_id,
      n.pay_channel,
      n.paye_treatment,
      n.umbrella_id,
      n.finance_component_id,
      n.component_key_type,
      n.component_key_value,
      n.classification,
      n.source_pay_method,
      n.source_basis_json,
      case
        when n.preview_resolution_mode_text is not null
         and upper(coalesce(n.preview_resolution_mode_text,'')) = 'SUGGESTED_EQUIVALENT_BASIS'
        then 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
        when n.saved_resolution_mode_text is not null then n.saved_resolution_mode_text::public.pay_finance_component_resolution_mode_enum
        when n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and upper(coalesce(n.source_pay_method,'')) <> upper(coalesce(n.pay_channel,''))
        then 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
        else null::public.pay_finance_component_resolution_mode_enum
      end as frozen_resolution_mode,
      case
        when jsonb_typeof(n.preview_resolution_payload_json) = 'object' then jsonb_strip_nulls(
          n.preview_resolution_payload_json
          || jsonb_build_object(
            'target_pay_method', n.pay_channel,
            'target_units', n.source_units,
            'suggested_target_rate', n.target_rate,
            'source_rate', n.source_rate,
            'source_charge_rate', n.source_charge_rate
          )
        )
        when jsonb_typeof(n.saved_resolution_payload_json) = 'object' then jsonb_strip_nulls(
          n.saved_resolution_payload_json
          || jsonb_build_object(
            'target_pay_method', n.pay_channel,
            'target_units', n.source_units,
            'suggested_target_rate', n.target_rate,
            'source_rate', n.source_rate,
            'source_charge_rate', n.source_charge_rate
          )
        )
        else jsonb_strip_nulls(jsonb_build_object(
          'resolution_mode', coalesce(n.preview_resolution_mode_text, 'SUGGESTED_EQUIVALENT_BASIS'),
          'target_pay_method', n.pay_channel,
          'target_units', n.source_units,
          'suggested_target_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate
        ))
      end as frozen_resolution_payload_json,
      round(
        case
          when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
          when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
          else 0
        end,
        2
      )::numeric(12,2) as take_source_amount,
      round(n.take_target_ex, 2)::numeric(12,2) as take_target_ex,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as take_target_vat,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
          else round(n.take_target_ex, 2)
        end,
        2
      )::numeric(12,2) as take_target_inc,
      jsonb_strip_nulls(
        coalesce(n.comp_json, '{}'::jsonb)
        || jsonb_build_object(
          'frozen_target_pay_method', n.pay_channel,
          'frozen_resolution_mode_text', coalesce(n.preview_resolution_mode_text, n.saved_resolution_mode_text),
          'frozen_source_amount', round(
            case
              when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
              when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
              else 0
            end,
            2
          ),
          'frozen_target_amount_ex_vat', round(n.take_target_ex, 2),
          'frozen_target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'frozen_target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'selected_preview_due_amount_ex_vat', round(n.due_amount_ex_vat, 2),
          'component_preview_due_amount_ex_vat', round(n.take_target_ex, 2)
        )
      ) as frozen_component_snapshot_json,
      jsonb_strip_nulls(
        coalesce(n.preview_resolution_result_json, n.saved_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'resolution_mode', coalesce(n.preview_resolution_mode_text, coalesce(n.saved_resolution_mode_text, 'SUGGESTED_EQUIVALENT_BASIS')),
          'target_pay_method', n.pay_channel,
          'target_amount_ex_vat', round(n.take_target_ex, 2),
          'target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'replacement_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate,
          'source_charge_ex_vat', n.source_charge_ex_vat,
          'target_charge_ex_vat', n.target_charge_ex_vat,
          'target_margin_ex_vat', n.target_margin_ex_vat,
          'margin_delta_ex_vat', n.margin_delta_ex_vat
        )
      ) as frozen_resolution_result_json
    from normalized n
    left join public.umbrellas u
      on u.id = n.umbrella_id
    where n.take_target_ex > 0
  )
  select
    gen_random_uuid() as id,
    fa.pay_batch_candidate_id,
    'MANUAL_DEBT_RECOVERY' as item_type,
    null::uuid as timesheet_id,
    null::text as segment_key,
    ('advance:' || fa.finance_case_id::text) as source_ref,
    (-fa.take_target_ex)::numeric(12,2) as amount_ex_vat,
    (-fa.take_target_vat)::numeric(12,2) as amount_vat,
    (-fa.take_target_inc)::numeric(12,2) as amount_inc_vat,
    v_week_start as repayment_week_start,
    fa.pay_channel as pay_channel,
    fa.umbrella_id as umbrella_id,
    (fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(fa.source_pay_method,'')) <> upper(coalesce(fa.pay_channel,''))) as is_mismatch,
    false as is_voided,
    v_now_utc as created_at,
    v_now_utc as updated_at,
    fa.finance_case_id,
    null::uuid as reservation_id,
    fa.paye_treatment,
    fa.finance_component_id,
    fa.frozen_component_snapshot_json,
    fa.component_key_type,
    fa.component_key_value,
    fa.classification,
    fa.source_basis_json,
    fa.source_pay_method,
    fa.pay_channel,
    fa.frozen_resolution_mode,
    fa.frozen_resolution_payload_json,
    fa.frozen_resolution_result_json,
    fa.take_source_amount,
    round(-fa.take_target_ex, 2),
    round(-fa.take_target_vat, 2),
    round(-fa.take_target_inc, 2)
  from final_alloc fa
  where fa.take_target_ex > 0;

  get diagnostics v_rows_ins_debt_items = row_count;
v_stage := 'STAGE_16C_APPLY_PAYMENT_ADVANCE_REPAYMENTS';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  insert into public.pay_batch_items (
    id,
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    repayment_week_start,
    pay_channel,
    umbrella_id,
    is_mismatch,
    is_voided,
    created_at,
    updated_at,
    finance_case_id,
    reservation_id,
    paye_treatment,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat
  )
  with selected_case_rows as (
    select distinct on (spr.finance_case_id)
      pbc.id as pay_batch_candidate_id,
      spr.candidate_id,
      spr.finance_case_id,
      upper(coalesce(nullif(spr.pay_channel,''), v_scope)) as pay_channel,
      upper(coalesce(nullif(spr.paye_treatment,''), 'NONE')) as paye_treatment,
      case when upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = 'UMBRELLA' then c.umbrella_id else null::uuid end as umbrella_id,
      round(abs(coalesce(spr.preview_amount_ex_vat, 0)), 2)::numeric(12,2) as due_amount_ex_vat,
      coalesce(spr.case_components_json, '[]'::jsonb) as case_components_json
    from pg_temp.tmp_pay_selected_preview_rows spr
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = v_batch_id
     and pbc.candidate_id = spr.candidate_id
    join public.candidates c
      on c.id = spr.candidate_id
    where spr.draftable = true
      and spr.line_type = 'PAYMENT_ADVANCE_REPAYMENT'
      and spr.finance_case_id is not null
      and upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = v_scope
      and spr.candidate_id = any(v_candidate_ids)
      and (v_client_filter_single is null or spr.client_id = v_client_filter_single)
      and abs(coalesce(spr.preview_amount_ex_vat, 0)) > 0
    order by spr.finance_case_id, spr.preview_row_id
  ),
  component_rows as (
    select
      scr.pay_batch_candidate_id,
      scr.candidate_id,
      scr.finance_case_id,
      scr.pay_channel,
      scr.paye_treatment,
      scr.umbrella_id,
      scr.due_amount_ex_vat,
      comp.comp_json,
      case
        when nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), '') is null then null::uuid
        else (comp.comp_json->>'finance_component_id')::uuid
      end as finance_component_id,
      nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), '') as component_key_type,
      coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), 'TOTAL') as component_key_value,
      case
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'TAXABLE_CHANNEL_SENSITIVE' then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'REIMBURSEMENT_GROSS_FIXED' then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'NET_PAY_FIXED_RECOVERY' then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
        else null::public.pay_finance_component_classification_enum
      end as classification,
      upper(btrim(coalesce(comp.comp_json->>'source_pay_method',''))) as source_pay_method,
      coalesce(comp.comp_json->'source_basis_json', '{}'::jsonb) as source_basis_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_payload_json') = 'object' then comp.comp_json->'saved_resolution_payload_json'
        else null::jsonb
      end as saved_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_result_json') = 'object' then comp.comp_json->'saved_resolution_result_json'
        else null::jsonb
      end as saved_resolution_result_json,
      nullif(btrim(coalesce(comp.comp_json->>'saved_resolution_mode','')), '') as saved_resolution_mode_text,
      round(
        case
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as remaining_source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'allocated_source_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'allocated_source_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as allocated_source_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as preview_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'target_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'target_pay_ex_vat')::numeric
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as target_pay_ex_vat,
      case
        when coalesce(comp.comp_json->>'source_units','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_units')::numeric, 6)
        else null::numeric
      end as source_units,
      case
        when coalesce(comp.comp_json->>'source_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_rate')::numeric, 2)
        else null::numeric
      end as source_rate,
      case
        when coalesce(comp.comp_json->>'target_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_rate')::numeric, 2)
        else null::numeric
      end as target_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_rate')::numeric, 2)
        else null::numeric
      end as source_charge_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as source_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as target_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_margin_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_margin_ex_vat')::numeric, 2)
        else null::numeric
      end as target_margin_ex_vat,
      case
        when coalesce(comp.comp_json->>'margin_delta_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'margin_delta_ex_vat')::numeric, 2)
        else null::numeric
      end as margin_delta_ex_vat,
      row_number() over (
        partition by scr.finance_case_id
        order by
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), ''), md5(comp.comp_json::text)),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), ''), ''),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), '')
      ) as component_rn,
      count(*) over (partition by scr.finance_case_id) as component_ct,
      round(sum(
        round(
          case
            when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
            else 0
          end,
          2
        )
      ) over (partition by scr.finance_case_id), 2)::numeric(12,2) as component_preview_due_sum
    from selected_case_rows scr
    cross join lateral jsonb_array_elements(coalesce(scr.case_components_json, '[]'::jsonb)) as comp(comp_json)
    where jsonb_typeof(comp.comp_json) = 'object'
      and round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      ) > 0
  ),
  normalized as (
    select
      cr.*,
      round(
        case
          when cr.component_ct = 1 then cr.due_amount_ex_vat
          when cr.component_rn = 1 then greatest(cr.due_amount_ex_vat - (coalesce(cr.component_preview_due_sum, 0) - coalesce(cr.preview_due_amount_ex_vat, 0)), 0)
          else cr.preview_due_amount_ex_vat
        end,
        2
      )::numeric(12,2) as take_target_ex
    from component_rows cr
  ),
  final_alloc as (
    select
      n.pay_batch_candidate_id,
      n.finance_case_id,
      n.pay_channel,
      n.paye_treatment,
      n.umbrella_id,
      n.finance_component_id,
      n.component_key_type,
      n.component_key_value,
      n.classification,
      n.source_pay_method,
      n.source_basis_json,
      case
        when n.saved_resolution_mode_text is not null then n.saved_resolution_mode_text::public.pay_finance_component_resolution_mode_enum
        when n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and upper(coalesce(n.source_pay_method,'')) <> upper(coalesce(n.pay_channel,''))
        then 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
        else null::public.pay_finance_component_resolution_mode_enum
      end as frozen_resolution_mode,
      case
        when jsonb_typeof(n.saved_resolution_payload_json) = 'object' then jsonb_strip_nulls(
          n.saved_resolution_payload_json
          || jsonb_build_object(
            'target_pay_method', n.pay_channel,
            'target_units', n.source_units,
            'suggested_target_rate', n.target_rate,
            'source_rate', n.source_rate,
            'source_charge_rate', n.source_charge_rate
          )
        )
        else jsonb_strip_nulls(jsonb_build_object(
          'target_pay_method', n.pay_channel,
          'target_units', n.source_units,
          'suggested_target_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate
        ))
      end as frozen_resolution_payload_json,
      round(
        case
          when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
          when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
          else 0
        end,
        2
      )::numeric(12,2) as take_source_amount,
      round(n.take_target_ex, 2)::numeric(12,2) as take_target_ex,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as take_target_vat,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
          else round(n.take_target_ex, 2)
        end,
        2
      )::numeric(12,2) as take_target_inc,
      jsonb_strip_nulls(
        coalesce(n.comp_json, '{}'::jsonb)
        || jsonb_build_object(
          'frozen_target_pay_method', n.pay_channel,
          'frozen_source_amount', round(
            case
              when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
              when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
              else 0
            end,
            2
          ),
          'frozen_target_amount_ex_vat', round(-n.take_target_ex, 2),
          'frozen_target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'frozen_target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'selected_preview_due_amount_ex_vat', round(n.due_amount_ex_vat, 2),
          'component_preview_due_amount_ex_vat', round(n.take_target_ex, 2)
        )
      ) as frozen_component_snapshot_json,
      jsonb_strip_nulls(
        coalesce(n.saved_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'target_pay_method', n.pay_channel,
          'target_amount_ex_vat', round(n.take_target_ex, 2),
          'target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'replacement_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate,
          'source_charge_ex_vat', n.source_charge_ex_vat,
          'target_charge_ex_vat', n.target_charge_ex_vat,
          'target_margin_ex_vat', n.target_margin_ex_vat,
          'margin_delta_ex_vat', n.margin_delta_ex_vat
        )
      ) as frozen_resolution_result_json
    from normalized n
    left join public.umbrellas u
      on u.id = n.umbrella_id
    where n.take_target_ex > 0
  )
  select
    gen_random_uuid() as id,
    fa.pay_batch_candidate_id,
    'LOAN_REPAYMENT' as item_type,
    null::uuid as timesheet_id,
    null::text as segment_key,
    ('advance:' || fa.finance_case_id::text) as source_ref,
    (-fa.take_target_ex)::numeric(12,2) as amount_ex_vat,
    (-fa.take_target_vat)::numeric(12,2) as amount_vat,
    (-fa.take_target_inc)::numeric(12,2) as amount_inc_vat,
    v_week_start as repayment_week_start,
    fa.pay_channel as pay_channel,
    fa.umbrella_id as umbrella_id,
    (fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(fa.source_pay_method,'')) <> upper(coalesce(fa.pay_channel,''))) as is_mismatch,
    false as is_voided,
    v_now_utc as created_at,
    v_now_utc as updated_at,
    fa.finance_case_id,
    null::uuid as reservation_id,
    fa.paye_treatment,
    fa.finance_component_id,
    fa.frozen_component_snapshot_json,
    fa.component_key_type,
    fa.component_key_value,
    fa.classification,
    fa.source_basis_json,
    fa.source_pay_method,
    fa.pay_channel,
    fa.frozen_resolution_mode,
    fa.frozen_resolution_payload_json,
    fa.frozen_resolution_result_json,
    fa.take_source_amount,
    round(-fa.take_target_ex, 2),
    round(-fa.take_target_vat, 2),
    round(-fa.take_target_inc, 2)
  from final_alloc fa
  where fa.take_target_ex > 0;

  get diagnostics v_rows_ins_loan_items = row_count;


  update public.pay_batch_candidates pbc
  set
    loan_repayment_taken = coalesce((
      select round(sum(-pbi.amount_ex_vat), 2)
      from public.pay_batch_items pbi
      where pbi.pay_batch_candidate_id = pbc.id
        and pbi.is_voided = false
        and pbi.item_type = 'LOAN_REPAYMENT'
    ), 0)::numeric(12,2),
    updated_at = v_now_utc
  where pbc.pay_batch_id = v_batch_id;

  get diagnostics v_rows_upd_candidates_loan = row_count;
v_stage := 'STAGE_16C1_FREEZE_ALL_FINANCE_ITEM_PAYOUT_INSTRUCTIONS';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'helper_exists', (to_regprocedure('public._pay_finance_case_freeze_payout_instruction_to_batch_item(uuid,uuid)') is not null)
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  if to_regprocedure('public._pay_finance_case_freeze_payout_instruction_to_batch_item(uuid,uuid)') is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_CREATE_DRAFT_BATCH',
      'code', 'MISSING_PAYOUT_INSTRUCTION_FREEZE_HELPER',
      'message', 'pay_create_draft_batch: required helper public._pay_finance_case_freeze_payout_instruction_to_batch_item(uuid,uuid) is missing',
      'stage', v_stage,
      'pay_batch_id', v_batch_id::text
    )::text;
  end if;

  for v_payout_instruction_freeze_rec in
    select
      pbi.id as pay_batch_item_id,
      pbi.finance_case_id
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = v_batch_id
      and pbi.is_voided = false
      and pbi.finance_case_id is not null
      and pbi.item_type in ('LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','MANUAL_DEBT_RECOVERY','LOAN_REPAYMENT')
    order by pbi.id
  loop
    execute 'select public._pay_finance_case_freeze_payout_instruction_to_batch_item($1,$2)'
      using v_payout_instruction_freeze_rec.pay_batch_item_id, v_payout_instruction_freeze_rec.finance_case_id;
  end loop;

  v_stage := 'STAGE_16C2_ENRICH_FINANCE_PAYOUT_INSTRUCTION_EXEC_FIELDS';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  update public.pay_batch_items as pbi_set
  set payout_instruction_snapshot_json = pbi_src.payout_instruction_snapshot_json
  from (
    select
      pbi.id as pay_batch_item_id,
      jsonb_strip_nulls(
        coalesce(pbi.payout_instruction_snapshot_json, '{}'::jsonb)
        || jsonb_build_object(
          'beneficiary_name',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'beneficiary_name','')), ''),
              case
                when upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
                  then nullif(btrim(coalesce(obd.beneficiary_name,'')), '')
                when upper(coalesce(pbi.payout_instruction_snapshot_json->>'payee_entity_kind','')) = 'UMBRELLA'
                  then nullif(btrim(coalesce(u.name,'')), '')
                else nullif(btrim(coalesce(c.account_holder, c.display_name, concat_ws(' ', c.first_name, c.last_name))), '')
              end
            ),
          'sort_code',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'sort_code','')), ''),
              case
                when upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
                 and length(regexp_replace(coalesce(obd.sort_code,''), '[^0-9]', '', 'g')) = 6
                  then substr(regexp_replace(coalesce(obd.sort_code,''), '[^0-9]', '', 'g'), 1, 2) || '-' ||
                       substr(regexp_replace(coalesce(obd.sort_code,''), '[^0-9]', '', 'g'), 3, 2) || '-' ||
                       substr(regexp_replace(coalesce(obd.sort_code,''), '[^0-9]', '', 'g'), 5, 2)
                when upper(coalesce(pbi.payout_instruction_snapshot_json->>'payee_entity_kind','')) = 'UMBRELLA'
                 and length(regexp_replace(coalesce(u.sort_code,''), '[^0-9]', '', 'g')) = 6
                  then substr(regexp_replace(coalesce(u.sort_code,''), '[^0-9]', '', 'g'), 1, 2) || '-' ||
                       substr(regexp_replace(coalesce(u.sort_code,''), '[^0-9]', '', 'g'), 3, 2) || '-' ||
                       substr(regexp_replace(coalesce(u.sort_code,''), '[^0-9]', '', 'g'), 5, 2)
                when length(regexp_replace(coalesce(c.sort_code,''), '[^0-9]', '', 'g')) = 6
                  then substr(regexp_replace(coalesce(c.sort_code,''), '[^0-9]', '', 'g'), 1, 2) || '-' ||
                       substr(regexp_replace(coalesce(c.sort_code,''), '[^0-9]', '', 'g'), 3, 2) || '-' ||
                       substr(regexp_replace(coalesce(c.sort_code,''), '[^0-9]', '', 'g'), 5, 2)
                else null
              end
            ),
          'account_number',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'account_number','')), ''),
              case
                when upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
                  then nullif(regexp_replace(coalesce(obd.account_number,''), '[^0-9]', '', 'g'), '')
                when upper(coalesce(pbi.payout_instruction_snapshot_json->>'payee_entity_kind','')) = 'UMBRELLA'
                  then nullif(regexp_replace(coalesce(u.account_number,''), '[^0-9]', '', 'g'), '')
                else nullif(regexp_replace(coalesce(c.account_number,''), '[^0-9]', '', 'g'), '')
              end
            ),
          'account_type',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'account_type','')), ''),
              case
                when upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then 'Personal'
                when upper(coalesce(pbi.payout_instruction_snapshot_json->>'payee_entity_kind','')) = 'UMBRELLA' then 'Business'
                else 'Personal'
              end
            ),
          'masked_bank_account',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'masked_bank_account','')), ''),
              case
                when upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
                 and nullif(regexp_replace(coalesce(obd.account_number,''), '[^0-9]', '', 'g'), '') is not null
                  then lpad(right(regexp_replace(coalesce(obd.account_number,''), '[^0-9]', '', 'g'), 4), length(regexp_replace(coalesce(obd.account_number,''), '[^0-9]', '', 'g')), '*')
                when upper(coalesce(pbi.payout_instruction_snapshot_json->>'payee_entity_kind','')) = 'UMBRELLA'
                 and nullif(regexp_replace(coalesce(u.account_number,''), '[^0-9]', '', 'g'), '') is not null
                  then lpad(right(regexp_replace(coalesce(u.account_number,''), '[^0-9]', '', 'g'), 4), length(regexp_replace(coalesce(u.account_number,''), '[^0-9]', '', 'g')), '*')
                when nullif(regexp_replace(coalesce(c.account_number,''), '[^0-9]', '', 'g'), '') is not null
                  then lpad(right(regexp_replace(coalesce(c.account_number,''), '[^0-9]', '', 'g'), 4), length(regexp_replace(coalesce(c.account_number,''), '[^0-9]', '', 'g')), '*')
                else null
              end
            ),
          'bank_details_hash',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_hash','')), ''),
              case
                when upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then obd.bank_details_hash
                when upper(coalesce(pbi.payout_instruction_snapshot_json->>'payee_entity_kind','')) = 'UMBRELLA' then u.bank_details_hash
                else c.bank_details_hash
              end
            ),
          'week_ending_bucket',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA'
                then case
                       when upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then null
                       when ts_f.week_ending_date is null then (v_week_start + 6)::text
                       else ts_f.week_ending_date::text
                     end
              else null
            end
        )
      ) as payout_instruction_snapshot_json
    from public.pay_batch_items as pbi
    join public.pay_batch_candidates as pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.candidates as c
      on c.id = pbc.candidate_id
    left join public.umbrellas as u
      on u.id = case
                  when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'payee_entity_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                   and upper(coalesce(pbi.payout_instruction_snapshot_json->>'payee_entity_kind','')) = 'UMBRELLA'
                    then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'payee_entity_id','')), ''))::uuid
                  else c.umbrella_id
                end
    left join public.pay_finance_case_oneoff_payout_bank_details as obd
      on obd.finance_case_id = pbi.finance_case_id
     and upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
    left join public.timesheets as ts_f
      on ts_f.timesheet_id = pbi.timesheet_id
     and ts_f.is_current = true
    where pbc.pay_batch_id = v_batch_id
      and coalesce(pbi.is_voided, false) = false
      and pbi.finance_case_id is not null
      and pbi.item_type in ('LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','MANUAL_DEBT_RECOVERY','LOAN_REPAYMENT')
  ) as pbi_src
  where pbi_set.id = pbi_src.pay_batch_item_id;

  v_stage := 'STAGE_16D_CREATE_FINANCE_RESERVATIONS';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  with ins as (
    insert into public.pay_advance_reservations (
      id,
      finance_case_id,
      finance_component_id,
      pay_batch_id,
      pay_batch_candidate_id,
      pay_batch_item_id,
      reserved_amount,
      repayment_week_start,
      status,
      created_at_utc,
      committed_at_utc,
      settled_at_utc,
      released_at_utc,
      released_reason,
      created_by_user_id,
      updated_by_user_id,
      frozen_component_snapshot_json,
      frozen_component_key_type,
      frozen_component_key_value,
      frozen_component_classification,
      frozen_source_basis_json,
      frozen_source_pay_method,
      frozen_target_pay_method,
      frozen_resolution_mode,
      frozen_resolution_payload_json,
      frozen_resolution_result_json,
      reserved_source_amount,
      frozen_rounded_target_amount
    )
    select
      gen_random_uuid() as id,
      pbi.finance_case_id,
      pbi.finance_component_id,
      v_batch_id as pay_batch_id,
      pbi.pay_batch_candidate_id,
      pbi.id as pay_batch_item_id,
      round(abs(coalesce(pbi.amount_ex_vat, 0)), 2) as reserved_amount,
      pbi.repayment_week_start,
      'RESERVED' as status,
      v_now_utc as created_at_utc,
      null::timestamptz as committed_at_utc,
      null::timestamptz as settled_at_utc,
      null::timestamptz as released_at_utc,
      null::text as released_reason,
      p_actor_user_id as created_by_user_id,
      p_actor_user_id as updated_by_user_id,
      pbi.frozen_component_snapshot_json,
      pbi.frozen_component_key_type,
      pbi.frozen_component_key_value,
      pbi.frozen_component_classification,
      pbi.frozen_source_basis_json,
      pbi.frozen_source_pay_method,
      pbi.frozen_target_pay_method,
      pbi.frozen_resolution_mode,
      pbi.frozen_resolution_payload_json,
      pbi.frozen_resolution_result_json,
      round(abs(coalesce(pbi.frozen_source_amount, pbi.amount_ex_vat, 0)), 2) as reserved_source_amount,
      round(abs(coalesce(pbi.frozen_target_amount_ex_vat, pbi.amount_ex_vat, 0)), 2) as frozen_rounded_target_amount
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = v_batch_id
      and pbi.is_voided = false
      and pbi.finance_case_id is not null
      and pbi.reservation_id is null
    returning id, pay_batch_item_id
  )
  update public.pay_batch_items pbi
  set
    reservation_id = ins.id,
    updated_at = v_now_utc
  from ins
  where pbi.id = ins.pay_batch_item_id;

  v_stage := 'STAGE_17_CLIP_NEGATIVES_TO_DEBT_CREATED';
  -- Part 1E: legacy DEBT_CREATED / negative clipping stage disabled (NO-OP).
  -- Negative handling is represented via OVERPAYMENT balances and finance recovery deductions.
  -- Preserve v_rows_ins_debt_items because it now represents MANUAL_DEBT_RECOVERY rows inserted in Stage 16B.
  v_rows_upd_candidates_debt := 0;


  v_stage := 'STAGE_18_POPULATE_CANDIDATE_SUMMARIES';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  with
  sums as (
    select
      pbc.id as pay_batch_candidate_id,

      round(coalesce(sum(
        case
          when pbi.is_voided = false
           and pbi.item_type not in ('OVERPAYMENT_RECOVERY', 'LOAN_REPAYMENT', 'MANUAL_DEBT_RECOVERY', 'MANUAL_CREDIT_PAYOUT', 'LOAN_PAYOUT', 'DEBT_CREATED')
          then pbi.amount_ex_vat
          else 0
        end
      ), 0), 2)::numeric(12,2) as earnings_ex,

      round(coalesce(sum(
        case
          when pbi.is_voided = false
           and pbi.item_type <> 'DEBT_CREATED'
          then pbi.amount_inc_vat
          else 0
        end
      ), 0), 2)::numeric(12,2) as earnings_inc,

      round(coalesce(sum(
        case
          when pbi.is_voided = false
           and coalesce(pbi.paye_treatment,'NONE') in ('GROSS_ADD','GROSS_DEDUCT')
          then pbi.amount_ex_vat
          else 0
        end
      ), 0), 2)::numeric(12,2) as gross_adjustments_ex_sum,

      round(coalesce(sum(
        case
          when pbi.is_voided = false
           and coalesce(pbi.paye_treatment,'NONE') in ('NET_ADD','NET_DEDUCT')
          then pbi.amount_ex_vat
          else 0
        end
      ), 0), 2)::numeric(12,2) as net_adjustments_ex_sum,

      round(coalesce(sum(
        case
          when pbi.is_voided = false
           and pbi.item_type = 'OVERPAYMENT_RECOVERY'
          then -pbi.amount_ex_vat
          else 0
        end
      ), 0), 2)::numeric(12,2) as overpayment_recovery_taken_ex,

      round(coalesce(sum(
        case
          when pbi.is_voided = false
           and pbi.item_type = 'LOAN_REPAYMENT'
          then -pbi.amount_ex_vat
          else 0
        end
      ), 0), 2)::numeric(12,2) as loan_repayment_taken_ex

    from public.pay_batch_candidates pbc
    left join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
    where pbc.pay_batch_id = v_batch_id
    group by pbc.id
  ),
  paye_net as (
    select
      pni.pay_batch_candidate_id,
      pni.net_amount::numeric(12,2) as net_amount
    from public.pay_batch_paye_net_inputs pni
  )
  update public.pay_batch_candidates pbc
  set
    awaiting_net_amount = (
      (v_scope = 'PAYE')
      and not exists (
        select 1
        from public.pay_batch_paye_net_inputs pni2
        where pni2.pay_batch_candidate_id = pbc.id
      )
    ),

    gross_preview = case
      when (v_scope = 'PAYE') then round(coalesce(sums.earnings_ex, 0) + coalesce(sums.gross_adjustments_ex_sum, 0), 2)::numeric(12,2)
      else greatest(coalesce(sums.earnings_inc, 0), 0)::numeric(12,2)
    end,

    overpayment_recovery_taken = sums.overpayment_recovery_taken_ex,
    loan_repayment_taken = sums.loan_repayment_taken_ex,

    net_bank_amount = case
      when (v_scope = 'PAYE') then
        case
          when (
            (v_scope = 'PAYE')
            and not exists (
              select 1
              from public.pay_batch_paye_net_inputs pni3
              where pni3.pay_batch_candidate_id = pbc.id
            )
          ) then null
          else greatest(
            round(coalesce(pn.net_amount, 0) + coalesce(sums.net_adjustments_ex_sum, 0), 2),
            0
          )::numeric(12,2)
        end
      else greatest(coalesce(sums.earnings_inc, 0), 0)::numeric(12,2)
    end,

    mismatch_settlement_choice = null,
    updated_at = v_now_utc
  from sums
  left join paye_net pn
    on pn.pay_batch_candidate_id = sums.pay_batch_candidate_id
  where pbc.id = sums.pay_batch_candidate_id
    and pbc.pay_batch_id = v_batch_id;

  get diagnostics v_rows_upd_candidates_summaries = row_count;

  v_stage := 'STAGE_19_CREATE_TIMESHEET_SNAPSHOTS';

  -- Create frozen timesheet snapshots for settlement baselines (do NOT advance blocked segments)
  with touched_ts as (
    select distinct pbi.timesheet_id
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = v_batch_id
      and pbi.timesheet_id is not null
  ),
  ts_channel as (
    select distinct on (pbi.timesheet_id)
      pbi.timesheet_id,
      pbi.pay_channel as pay_channel_used
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = v_batch_id
      and pbi.timesheet_id is not null
      and pbi.pay_channel in ('PAYE','UMBRELLA')
    order by
      pbi.timesheet_id,
      pbi.pay_channel desc
  ),
  tf0 as (
    select
      tf.timesheet_id,
      tf.candidate_id,
      tf.client_id,
      ts.contract_id,
      ts.reference_number,
      tf.invoice_breakdown_json,
      tf.hours_day,
      tf.hours_night,
      tf.hours_sat,
      tf.hours_sun,
      tf.hours_bh,
      tf.pay_day,
      tf.pay_night,
      tf.pay_sat,
      tf.pay_sun,
      tf.pay_bh,
      tf.additional_units_json,
      tf.mileage_units,
      tf.mileage_pay_rate,
      round(coalesce(tf.total_pay_ex_vat,0),2) as total_pay_ex_vat,
      round(coalesce(tf.expenses_pay_ex_vat,0),2) as expenses_pay_ex_vat,
      round(coalesce(tf.travel_pay_ex_vat,0),2) as travel_pay_ex_vat,
      round(coalesce(tf.accommodation_pay_ex_vat,0),2) as accommodation_pay_ex_vat,
      round(coalesce(tf.other_pay_ex_vat,0),2) as other_pay_ex_vat,
      round(coalesce(tf.mileage_pay_ex_vat,0),2) as mileage_pay_ex_vat,
      coalesce(
        case when ct.overrideclientsettings then ct.require_reference_to_pay end,
        cs.pay_reference_required,
        false
      ) as require_reference_to_pay,
      coalesce(tps.last_settled_snapshot_json, '{}'::jsonb) as base_json
    from public.timesheets_financials tf
    join touched_ts t on t.timesheet_id = tf.timesheet_id
    join public.timesheets ts
      on ts.timesheet_id = tf.timesheet_id
     and ts.is_current = true
    left join public.contracts ct
      on ct.id = ts.contract_id
    left join public.client_settings cs
      on cs.client_id = tf.client_id
    left join public.timesheet_pay_state tps
      on tps.timesheet_id = tf.timesheet_id
    where tf.is_current = true
  ),
   cur0 as (
    select
      t.*,
      case
        when t.invoice_breakdown_json is not null
         and jsonb_typeof(t.invoice_breakdown_json)='object'
         and upper(coalesce(t.invoice_breakdown_json->>'mode',''))='SEGMENTS'
         and jsonb_typeof(t.invoice_breakdown_json->'segments')='array'
        then (
          select coalesce(jsonb_agg(
            jsonb_build_object(
              'segment_id', nullif(btrim(coalesce(seg->>'segment_id','')),''),
              'date', nullif(btrim(coalesce(seg->>'date','')),''),
              'start_utc', nullif(btrim(coalesce(seg->>'start_utc','')),''),
              'end_utc', nullif(btrim(coalesce(seg->>'end_utc','')),''),
              'break_mins', coalesce(nullif(seg->>'break_mins','')::numeric,0),
              'breaks', coalesce(seg->'breaks','[]'::jsonb),
              'hours_day', coalesce(nullif(seg->>'hours_day','')::numeric,0),
              'hours_night', coalesce(nullif(seg->>'hours_night','')::numeric,0),
              'hours_sat', coalesce(nullif(seg->>'hours_sat','')::numeric,0),
              'hours_sun', coalesce(nullif(seg->>'hours_sun','')::numeric,0),
              'hours_bh', coalesce(nullif(seg->>'hours_bh','')::numeric,0),
              'pay_amount', round(coalesce(nullif(seg->>'pay_amount','')::numeric,0),2),
              'exclude_from_pay', coalesce(nullif(seg->>'exclude_from_pay','')::boolean,false),
              'ref_num', nullif(btrim(coalesce(seg->>'ref_num','')),'')
            )
          ), '[]'::jsonb)
          from jsonb_array_elements(t.invoice_breakdown_json->'segments') seg
          where seg is not null and jsonb_typeof(seg)='object'
        )
        else jsonb_build_array(
          jsonb_build_object(
            'segment_id', ('ts:' || t.timesheet_id::text),
            'pay_amount', round(coalesce(t.total_pay_ex_vat,0),2),
            'exclude_from_pay', false,
            'ref_num', nullif(btrim(coalesce(t.reference_number,'')), '')
          )
        )
      end as cur_segments,
      case
        when t.invoice_breakdown_json is not null
         and jsonb_typeof(t.invoice_breakdown_json)='object'
         and upper(coalesce(t.invoice_breakdown_json->>'mode',''))='SEGMENTS'
        then round(coalesce(nullif(t.invoice_breakdown_json #>> '{additional,pay_ex_vat}','')::numeric,0),2)
        else 0::numeric
      end as cur_additional,
      coalesce(
        (
          select coalesce(
            jsonb_agg(
              jsonb_build_object(
                'id', a.id::text,
                'delta_pay_ex_vat', round(coalesce(a.delta_pay_ex_vat,0),2)
              )
              order by a.id
            ),
            '[]'::jsonb
          )
          from public.ts_pay_adjustments a
          where a.timesheet_id = t.timesheet_id
            and a.as_advance = false
        ),
        '[]'::jsonb
      ) as cur_adjs
    from tf0 t
  )
  insert into public.pay_batch_timesheet_snapshots(
    pay_batch_id,
    timesheet_id,
    candidate_id,
    pay_channel,
    base_snapshot_json,
    target_snapshot_json,
    signature,
    created_at_utc
  )
  select
    v_batch_id,
    s.timesheet_id,
    s.candidate_id,
    tc.pay_channel_used,
    s.base_snapshot_json,
    s.target_snapshot_json,
    md5(s.target_snapshot_json::text),
    now()
  from (
    select
      c.timesheet_id,
      c.candidate_id,
      coalesce(c.base_json, '{}'::jsonb) as base_snapshot_json,
      jsonb_build_object(
        'segments', coalesce(c.cur_segments, '[]'::jsonb),
        'additional_pay_ex_vat', round(coalesce(c.cur_additional,0),2),
        'additional_units_json', coalesce(c.additional_units_json, '{}'::jsonb),
        'hours_day', round(coalesce(c.hours_day,0),2),
        'hours_night', round(coalesce(c.hours_night,0),2),
        'hours_sat', round(coalesce(c.hours_sat,0),2),
        'hours_sun', round(coalesce(c.hours_sun,0),2),
        'hours_bh', round(coalesce(c.hours_bh,0),2),
        'pay_day', round(coalesce(c.pay_day,0),2),
        'pay_night', round(coalesce(c.pay_night,0),2),
        'pay_sat', round(coalesce(c.pay_sat,0),2),
        'pay_sun', round(coalesce(c.pay_sun,0),2),
        'pay_bh', round(coalesce(c.pay_bh,0),2),
        'mileage_units', round(coalesce(c.mileage_units,0),2),
        'mileage_pay_rate', c.mileage_pay_rate,
        'expenses', jsonb_build_object(
          'expenses_pay_ex_vat', round(coalesce(c.expenses_pay_ex_vat,0),2),
          'travel_pay_ex_vat', round(coalesce(c.travel_pay_ex_vat,0),2),
          'accommodation_pay_ex_vat', round(coalesce(c.accommodation_pay_ex_vat,0),2),
          'other_pay_ex_vat', round(coalesce(c.other_pay_ex_vat,0),2),
          'mileage_pay_ex_vat', round(coalesce(c.mileage_pay_ex_vat,0),2)
        ),
        'adjustments', coalesce(c.cur_adjs, '[]'::jsonb),
        'resolved_components', coalesce((
          select jsonb_agg(pbi_rc.frozen_component_snapshot_json order by pbi_rc.id)
          from public.pay_batch_items pbi_rc
          join public.pay_batch_candidates pbc_rc
            on pbc_rc.id = pbi_rc.pay_batch_candidate_id
          where pbc_rc.pay_batch_id = v_batch_id
            and pbi_rc.timesheet_id = c.timesheet_id
            and pbi_rc.is_voided = false
            and pbi_rc.frozen_component_snapshot_json is not null
        ), '[]'::jsonb)
      ) as target_snapshot_json
    from cur0 c
  ) s
  join ts_channel tc
    on tc.timesheet_id = s.timesheet_id;

  GET DIAGNOSTICS v_rows_ins_snapshots = ROW_COUNT;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_19_SNAPSHOTS_INSERTED',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'inserted_snapshot_rows', v_rows_ins_snapshots
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  v_stage := 'STAGE_20_BUILD_ITEM_BREAKDOWNS';

  -- ✅ NEW: Build canonical breakdown lines for ALL items in this batch (including LOAN_REPAYMENT + DEBT_CREATED)
  with my_items as (
    select
      pbi.id as pay_batch_item_id,
      pbi.item_type,
      pbi.timesheet_id,
      pbi.segment_key,
      pbi.source_ref,
      pbi.description,
      pbi.amount_ex_vat,
      pbi.amount_vat,
      pbi.amount_inc_vat,
      pbi.pay_channel,
      pbi.frozen_component_snapshot_json,
      pbi.frozen_source_basis_json,
      pbi.frozen_resolution_result_json,
      pbi.frozen_component_classification
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = v_batch_id
      and not exists (
        select 1
        from public.pay_batch_item_breakdowns pbib
        where pbib.pay_batch_item_id = pbi.id
        limit 1
      )
  ),
  exact_component_seed as (
    select
      mi.pay_batch_item_id,
      mi.item_type,
      mi.source_ref,
      mi.amount_ex_vat,
      mi.amount_vat,
      mi.amount_inc_vat,
      coalesce(mi.frozen_component_snapshot_json, '{}'::jsonb) as frozen_component_snapshot_json,
      coalesce(mi.frozen_source_basis_json, '{}'::jsonb) as frozen_source_basis_json,
      coalesce(mi.frozen_resolution_result_json, '{}'::jsonb) as frozen_resolution_result_json,
      nullif(
        upper(
          btrim(
            coalesce(
              mi.frozen_component_snapshot_json->>'bucket_code',
              mi.frozen_source_basis_json->>'bucket_code',
              case
                when mi.item_type = 'EXPENSE_DELTA' and mi.source_ref like 'additional:%' then split_part(mi.source_ref, ':', 2)
                when mi.item_type = 'EXPENSE_DELTA' and mi.source_ref = 'additional' then 'TOTAL'
                else null
              end,
              ''
            )
          )
        ),
        ''
      ) as bucket_code,
      nullif(btrim(coalesce(mi.frozen_component_snapshot_json->>'label', '')), '') as preview_label,
      upper(coalesce(mi.frozen_component_snapshot_json->>'component_semantics', '')) as component_semantics,
      coalesce(nullif(mi.frozen_component_snapshot_json->>'is_rate_bearing','')::boolean, false) as is_rate_bearing,
      coalesce(nullif(mi.frozen_component_snapshot_json->>'is_amount_led','')::boolean, false) as is_amount_led,
      case
        when coalesce(
          mi.frozen_resolution_result_json->>'target_units',
          mi.frozen_component_snapshot_json->>'target_units',
          mi.frozen_component_snapshot_json->>'source_units',
          mi.frozen_source_basis_json->>'source_units',
          ''
        ) ~ '^-?\d+(\.\d+)?$'
          then round(
            coalesce(
              (mi.frozen_resolution_result_json->>'target_units')::numeric,
              (mi.frozen_component_snapshot_json->>'target_units')::numeric,
              (mi.frozen_component_snapshot_json->>'source_units')::numeric,
              (mi.frozen_source_basis_json->>'source_units')::numeric
            ),
            6
          )
        else null::numeric
      end as units,
      case
        when coalesce(
          mi.frozen_resolution_result_json->>'replacement_rate',
          mi.frozen_component_snapshot_json->>'target_rate',
          mi.frozen_component_snapshot_json->>'source_rate',
          mi.frozen_source_basis_json->>'source_rate',
          ''
        ) ~ '^-?\d+(\.\d+)?$'
          then round(
            coalesce(
              (mi.frozen_resolution_result_json->>'replacement_rate')::numeric,
              (mi.frozen_component_snapshot_json->>'target_rate')::numeric,
              (mi.frozen_component_snapshot_json->>'source_rate')::numeric,
              (mi.frozen_source_basis_json->>'source_rate')::numeric
            ),
            6
          )
        else null::numeric
      end as rate
    from my_items mi
    where jsonb_typeof(mi.frozen_component_snapshot_json) = 'object'
      and (
        mi.item_type = 'SEGMENT_DELTA'
        or (mi.item_type = 'EXPENSE_DELTA' and (mi.source_ref = 'additional' or mi.source_ref like 'additional:%'))
      )
  ),
  exact_component_lines as (
    select
      ecs.pay_batch_item_id,
      case
        when ecs.item_type = 'SEGMENT_DELTA' then 'TS_BUCKET'::text
        else 'ADDITIONAL_UNIT'::text
      end as line_kind,
      ecs.bucket_code,
      case
        when ecs.item_type = 'SEGMENT_DELTA' then
          case ecs.bucket_code
            when 'DAY' then 'Day'::text
            when 'NIGHT' then 'Night'::text
            when 'SAT' then 'Sat'::text
            when 'SUN' then 'Sun'::text
            when 'BH' then 'BH'::text
            else coalesce(ecs.preview_label, 'Bucket')::text
          end
        else coalesce(
          ecs.preview_label,
          case
            when ecs.bucket_code is null or ecs.bucket_code = 'TOTAL' then 'Additional'::text
            else ecs.bucket_code::text
          end
        )
      end as unit_name,
      case when ecs.is_rate_bearing then ecs.units else null::numeric end as units,
      case when ecs.is_rate_bearing then ecs.rate else null::numeric end as rate,
      ecs.amount_ex_vat,
      ecs.amount_vat,
      ecs.amount_inc_vat,
      jsonb_strip_nulls(
        jsonb_build_object(
          'component_semantics', case when ecs.is_rate_bearing then 'RATE_BEARING' else coalesce(nullif(ecs.component_semantics,''), 'AMOUNT_LED') end,
          'source_basis_json', case when ecs.frozen_source_basis_json = '{}'::jsonb then null else ecs.frozen_source_basis_json end,
          'frozen_component_snapshot_json', case when ecs.frozen_component_snapshot_json = '{}'::jsonb then null else ecs.frozen_component_snapshot_json end
        )
      ) as meta_json
    from exact_component_seed ecs
  ),
  exact_component_item_ids as (
    select distinct ecl.pay_batch_item_id
    from exact_component_lines ecl
  ),
  simple_lines as (
    select
      mi.pay_batch_item_id,
      case
        when mi.item_type = 'MILEAGE_DELTA' then 'MILEAGE'
        when mi.item_type = 'EXPENSE_DELTA' then 'EXPENSE'
        when mi.item_type = 'ADJUSTMENT_DELTA' then 'ADJUSTMENT'
        when mi.item_type = 'CONVERSION_ADJ' then 'CONVERSION_ADJ'
        when mi.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
        when mi.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
        when mi.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
        when mi.item_type = 'DEBT_CREATED' then 'DEBT_CREATED'
        when mi.item_type = 'LOAN_PAYOUT' then 'LOAN_PAYOUT'
        when mi.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_PAYOUT'
        else 'ADJUSTMENT'
      end as line_kind,
      null::text as bucket_code,
      case
        when mi.item_type = 'MILEAGE_DELTA' then 'Mileage'
        when mi.item_type = 'EXPENSE_DELTA' then initcap(coalesce(mi.source_ref,'Expense'))
        when mi.item_type = 'ADJUSTMENT_DELTA' then 'Adjustment'
        when mi.item_type = 'CONVERSION_ADJ' then 'Conversion adjustment'
        when mi.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
        when mi.item_type = 'LOAN_REPAYMENT' then 'Loan repayment'
        when mi.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual debt recovery'
        when mi.item_type = 'DEBT_CREATED' then 'Debt created'
        when mi.item_type = 'LOAN_PAYOUT' then 'Loan payout'
        when mi.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual credit adjustment payment'
        else 'Adjustment'
      end as unit_name,
      null::numeric as units,
      null::numeric as rate,
      round(coalesce(mi.amount_ex_vat, 0), 2) as amount_ex_vat,
      round(coalesce(mi.amount_vat, 0), 2) as amount_vat,
      round(coalesce(mi.amount_inc_vat, 0), 2) as amount_inc_vat,
      '{}'::jsonb as meta_json
    from my_items mi
    where not exists (
      select 1
      from exact_component_item_ids eci
      where eci.pay_batch_item_id = mi.pay_batch_item_id
    )
  ),
  all_lines as (
    select * from exact_component_lines
    union all
    select * from simple_lines
  )
  insert into public.pay_batch_item_breakdowns(
    pay_batch_item_id,
    line_kind,
    bucket_code,
    unit_name,
    units,
    rate,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    meta_json
  )
  select
    al.pay_batch_item_id,
    al.line_kind,
    al.bucket_code,
    al.unit_name,
    al.units,
    al.rate,
    al.amount_ex_vat,
    al.amount_vat,
    al.amount_inc_vat,
    al.meta_json
  from all_lines al;

  GET DIAGNOSTICS v_rows_ins_breakdowns = ROW_COUNT;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_20_BREAKDOWNS_INSERTED',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'inserted_breakdown_rows', v_rows_ins_breakdowns
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  v_stage := 'STAGE_21_BREAKDOWN_INTEGRITY_MISSING';

  -- ✅ Integrity checks: every item must have ≥1 breakdown row; sums must match exactly
  select count(*)
  into v_breakdown_missing_ct
  from public.pay_batch_items pbi_m
  join public.pay_batch_candidates pbc_m
    on pbc_m.id = pbi_m.pay_batch_candidate_id
  where pbc_m.pay_batch_id = v_batch_id
    and not exists (
      select 1
      from public.pay_batch_item_breakdowns pbib_m
      where pbib_m.pay_batch_item_id = pbi_m.id
      limit 1
    );

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_21_BREAKDOWN_MISSING_COUNT',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'breakdown_missing_ct', coalesce(v_breakdown_missing_ct,0)
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  if coalesce(v_breakdown_missing_ct,0) > 0 then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_BREAKDOWN_MISSING',
        jsonb_build_object(
          'stage', v_stage,
          'pay_batch_id', v_batch_id::text,
          'breakdown_missing_ct', coalesce(v_breakdown_missing_ct,0),
          'error', 'PAY_BATCH_BREAKDOWN_MISSING'
        ),
        'pay_batches',
        v_batch_id::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    raise exception 'PAY_BATCH_BREAKDOWN_MISSING: % items have no breakdown rows', v_breakdown_missing_ct;
  end if;

  v_stage := 'STAGE_22_BREAKDOWN_INTEGRITY_SUM_MATCH';

  with sums as (
    select
      pbi_s.id as pay_batch_item_id,
      round(pbi_s.amount_ex_vat,2) as item_ex,
      round(pbi_s.amount_vat,2) as item_vat,
      round(pbi_s.amount_inc_vat,2) as item_inc,
      round(coalesce(sum(pbib_s.amount_ex_vat),0),2) as sum_ex,
      round(coalesce(sum(pbib_s.amount_vat),0),2) as sum_vat,
      round(coalesce(sum(pbib_s.amount_inc_vat),0),2) as sum_inc
    from public.pay_batch_items pbi_s
    join public.pay_batch_candidates pbc_s
      on pbc_s.id = pbi_s.pay_batch_candidate_id
    left join public.pay_batch_item_breakdowns pbib_s
      on pbib_s.pay_batch_item_id = pbi_s.id
    where pbc_s.pay_batch_id = v_batch_id
    group by pbi_s.id, pbi_s.amount_ex_vat, pbi_s.amount_vat, pbi_s.amount_inc_vat
  ),
  bad as (
    select
      s.pay_batch_item_id,
      s.item_ex, s.sum_ex,
      s.item_vat, s.sum_vat,
      s.item_inc, s.sum_inc
    from sums s
    where s.item_ex <> s.sum_ex
       or s.item_vat <> s.sum_vat
       or s.item_inc <> s.sum_inc
  )
  select
    count(*),
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'pay_batch_item_id', b.pay_batch_item_id::text,
          'item_ex', b.item_ex, 'sum_ex', b.sum_ex,
          'item_vat', b.item_vat, 'sum_vat', b.sum_vat,
          'item_inc', b.item_inc, 'sum_inc', b.sum_inc
        )
        order by b.pay_batch_item_id::text
      ),
      '[]'::jsonb
    )
  into v_breakdown_bad_ct, v_breakdown_bad
  from bad b;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_22_BREAKDOWN_SUMS_RESULT',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'breakdown_bad_ct', coalesce(v_breakdown_bad_ct,0),
        'breakdown_bad_sample', (
          case
            when jsonb_typeof(v_breakdown_bad) = 'array' then (
              select coalesce(jsonb_agg(x order by (x->>'pay_batch_item_id')), '[]'::jsonb)
              from (
                select e as x
                from jsonb_array_elements(v_breakdown_bad) e
                limit 50
              ) s
            )
            else v_breakdown_bad
          end
        )
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  if coalesce(v_breakdown_bad_ct,0) > 0 then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_BREAKDOWN_MISMATCH',
        jsonb_build_object(
          'stage', v_stage,
          'pay_batch_id', v_batch_id::text,
          'breakdown_bad_ct', coalesce(v_breakdown_bad_ct,0),
          'breakdown_bad', v_breakdown_bad,
          'error', 'PAY_BATCH_BREAKDOWN_MISMATCH'
        ),
        'pay_batches',
        v_batch_id::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    raise exception 'PAY_BATCH_BREAKDOWN_MISMATCH %', v_breakdown_bad::text;
  end if;

  v_stage := 'STAGE_23_FINAL_SAFETY_ASSERT_BLOCKERS';

  with destinations as (
    select distinct
      spr.candidate_id,
      case
        when upper(coalesce(spr.routing_kind,'')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then 'CANDIDATE'
        when upper(coalesce(spr.pay_channel,'')) = 'PAYE' then 'CANDIDATE'
        when upper(coalesce(spr.routing_kind,'')) = 'UMBRELLA_COMPANY' then 'UMBRELLA'
        when upper(coalesce(spr.pay_channel,'')) = 'UMBRELLA' and spr.finance_case_id is null then 'UMBRELLA'
        else 'CANDIDATE'
      end as entity_kind,
      case
        when upper(coalesce(spr.routing_kind,'')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then spr.candidate_id
        when upper(coalesce(spr.pay_channel,'')) = 'PAYE' then spr.candidate_id
        when upper(coalesce(spr.routing_kind,'')) = 'UMBRELLA_COMPANY' then c.umbrella_id
        when upper(coalesce(spr.pay_channel,'')) = 'UMBRELLA' and spr.finance_case_id is null then c.umbrella_id
        else spr.candidate_id
      end as entity_id,
      case
        when upper(coalesce(spr.routing_kind,'')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then spr.bank_details_hash
        when upper(coalesce(spr.pay_channel,'')) = 'PAYE' then c.bank_details_hash
        when upper(coalesce(spr.routing_kind,'')) = 'UMBRELLA_COMPANY' then u.bank_details_hash
        when upper(coalesce(spr.pay_channel,'')) = 'UMBRELLA' and spr.finance_case_id is null then u.bank_details_hash
        else c.bank_details_hash
      end as bank_hash
    from pg_temp.tmp_pay_selected_preview_rows spr
    join public.candidates c
      on c.id = spr.candidate_id
    left join public.umbrellas u
      on u.id = c.umbrella_id
    where spr.draftable = true
      and spr.candidate_id = any(v_candidate_ids)
  ),
  destination_blockers as (
    select
      d.candidate_id,
      d.entity_kind,
      d.entity_id,
      d.bank_hash,
      (
        (case
           when d.entity_id is null or d.bank_hash is null or btrim(d.bank_hash) = '' then jsonb_build_array('BLOCKED_BANK_DETAILS')
           else '[]'::jsonb
         end)
        ||
        (case
           when d.entity_id is not null
            and d.bank_hash is not null and btrim(d.bank_hash) <> ''
            and v_need_name_check = true
            and not exists (
              select 1
              from public.bank_name_checks bnc
              where upper(coalesce(bnc.rail_provider,'')) = upper(btrim(coalesce(v_settings.rail_provider_default,'')))
                and upper(coalesce(bnc.rail_env,'')) = upper(btrim(coalesce(v_settings.rail_env_default,'')))
                and upper(coalesce(bnc.entity_kind,'')) = d.entity_kind
                and bnc.entity_id = d.entity_id
                and bnc.bank_details_hash = d.bank_hash
                and (
                  upper(coalesce(bnc.status,'')) = 'PASS'
                  or (
                    bnc.override_reason is not null
                    and bnc.override_hash is not null
                    and bnc.override_hash = d.bank_hash
                  )
                )
              limit 1
            )
           then jsonb_build_array('BLOCKED_NAME_CHECK')
           else '[]'::jsonb
         end)
        ||
        (case
           when d.entity_id is not null
            and d.bank_hash is not null and btrim(d.bank_hash) <> ''
            and v_requires_payee_map = true
            and not exists (
              select 1
              from public.bank_payee_map bpm
              where upper(coalesce(bpm.rail_provider,'')) = upper(btrim(coalesce(v_settings.rail_provider_default,'')))
                and upper(coalesce(bpm.rail_env,'')) = upper(btrim(coalesce(v_settings.rail_env_default,'')))
                and upper(coalesce(bpm.entity_kind,'')) = d.entity_kind
                and bpm.entity_id = d.entity_id
                and bpm.bank_details_hash = d.bank_hash
              limit 1
            )
           then jsonb_build_array('BLOCKED_NO_PAYEE_MAP')
           else '[]'::jsonb
         end)
      ) as blockers
    from destinations d
  ),
  bad as (
    select
      db.candidate_id,
      db.blockers
    from destination_blockers db
    where jsonb_array_length(db.blockers) > 0
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', b.candidate_id::text,
        'blockers', b.blockers
      )
      order by b.candidate_id::text
    ),
    '[]'::jsonb
  )
  into v_blocked_candidates
  from bad b;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_23_BLOCKER_ASSERT_RESULT',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'blocked_candidates', (
          case
            when jsonb_typeof(v_blocked_candidates) = 'array' then (
              select coalesce(jsonb_agg(x order by (x->>'candidate_id')), '[]'::jsonb)
              from (
                select e as x
                from jsonb_array_elements(v_blocked_candidates) e
                limit 50
              ) s
            )
            else v_blocked_candidates
          end
        ),
        'blocked_count', jsonb_array_length(v_blocked_candidates)
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  if jsonb_array_length(v_blocked_candidates) > 0 then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_DRAFT_CONTAINS_BLOCKED_ITEMS',
        jsonb_build_object(
          'stage', v_stage,
          'pay_batch_id', v_batch_id::text,
          'blocked_candidates', v_blocked_candidates,
          'error', 'DRAFT_CONTAINS_BLOCKED_ITEMS'
        ),
        'pay_batches',
        v_batch_id::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    raise exception 'DRAFT_CONTAINS_BLOCKED_ITEMS %', v_blocked_candidates::text;
  end if;

  v_stage := 'STAGE_23B_CONSUME_TIMESHEET_PAYMENT_OVERRIDES';

  with consumed as (
    update public.timesheet_payment_overrides tpo
    set
      consumed_by_pay_batch_id = v_batch_id,
      consumed_at_utc = v_now_utc
    where tpo.cleared_at_utc is null
      and tpo.consumed_by_pay_batch_id is null
      and tpo.consumed_at_utc is null
      and upper(coalesce(tpo.override_type,'')) = 'ADVANCE_THIS_PAYMENT'
      and tpo.id in (
        select tpo_pick.id
        from (
          select distinct on (tpo2.timesheet_id)
            tpo2.id,
            tpo2.timesheet_id
          from public.timesheet_payment_overrides tpo2
          where tpo2.cleared_at_utc is null
            and tpo2.consumed_by_pay_batch_id is null
            and tpo2.consumed_at_utc is null
            and upper(coalesce(tpo2.override_type,'')) = 'ADVANCE_THIS_PAYMENT'
            and exists (
              select 1
              from public.pay_batch_items pbi
              join public.pay_batch_candidates pbc
                on pbc.id = pbi.pay_batch_candidate_id
              where pbc.pay_batch_id = v_batch_id
                and pbi.timesheet_id = tpo2.timesheet_id
                and coalesce(pbi.is_voided, false) = false
                and pbi.item_type in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
            )
          order by tpo2.timesheet_id, tpo2.created_at_utc desc, tpo2.id desc
        ) tpo_pick
      )
    returning
      tpo.id,
      tpo.timesheet_id,
      tpo.candidate_id,
      tpo.override_type,
      tpo.reason,
      tpo.created_at_utc,
      tpo.created_by_user_id,
      tpo.consumed_by_pay_batch_id,
      tpo.consumed_at_utc
  )
  select
    count(*)::int,
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'override_id', consumed.id::text,
          'timesheet_id', consumed.timesheet_id::text,
          'candidate_id', case when consumed.candidate_id is null then null else consumed.candidate_id::text end,
          'override_type', consumed.override_type,
          'reason', consumed.reason,
          'created_at_utc', consumed.created_at_utc,
          'created_by_user_id', case when consumed.created_by_user_id is null then null else consumed.created_by_user_id::text end,
          'consumed_by_pay_batch_id', case when consumed.consumed_by_pay_batch_id is null then null else consumed.consumed_by_pay_batch_id::text end,
          'consumed_at_utc', consumed.consumed_at_utc
        )
        order by consumed.timesheet_id::text, consumed.id::text
      ),
      '[]'::jsonb
    )
  into
    v_rows_upd_timesheet_overrides_consumed,
    v_consumed_timesheet_payment_overrides
  from consumed;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_23B_TIMESHEET_OVERRIDES_CONSUMED',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'consumed_timesheet_payment_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed, 0),
        'consumed_timesheet_payment_overrides', v_consumed_timesheet_payment_overrides
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  if coalesce(v_rows_upd_timesheet_overrides_consumed, 0) > 0 then
    for v_override_consume_rec in
      select
        x.override_id::uuid as override_id,
        x.timesheet_id::uuid as timesheet_id,
        case when x.candidate_id is null or btrim(x.candidate_id) = '' then null else x.candidate_id::uuid end as candidate_id,
        x.override_type,
        x.reason,
        case when x.created_by_user_id is null or btrim(x.created_by_user_id) = '' then null else x.created_by_user_id::uuid end as created_by_user_id,
        x.created_at_utc::timestamptz as created_at_utc,
        case when x.consumed_by_pay_batch_id is null or btrim(x.consumed_by_pay_batch_id) = '' then null else x.consumed_by_pay_batch_id::uuid end as consumed_by_pay_batch_id,
        x.consumed_at_utc::timestamptz as consumed_at_utc
      from jsonb_to_recordset(v_consumed_timesheet_payment_overrides) as x(
        override_id text,
        timesheet_id text,
        candidate_id text,
        override_type text,
        reason text,
        created_at_utc text,
        created_by_user_id text,
        consumed_by_pay_batch_id text,
        consumed_at_utc text
      )
    loop
      begin
        perform public._audit_insert(
          'timesheets',
          v_override_consume_rec.timesheet_id::text,
          'TIMESHEET_PAYMENT_OVERRIDE_CONSUMED',
          jsonb_build_object(
            'override_id', v_override_consume_rec.override_id::text,
            'timesheet_id', v_override_consume_rec.timesheet_id::text,
            'candidate_id', case when v_override_consume_rec.candidate_id is null then null else v_override_consume_rec.candidate_id::text end,
            'override_type', v_override_consume_rec.override_type,
            'reason', v_override_consume_rec.reason,
            'created_at_utc', v_override_consume_rec.created_at_utc,
            'created_by_user_id', case when v_override_consume_rec.created_by_user_id is null then null else v_override_consume_rec.created_by_user_id::text end
          ),
          jsonb_build_object(
            'override_id', v_override_consume_rec.override_id::text,
            'timesheet_id', v_override_consume_rec.timesheet_id::text,
            'candidate_id', case when v_override_consume_rec.candidate_id is null then null else v_override_consume_rec.candidate_id::text end,
            'consumed_by_pay_batch_id', case when v_override_consume_rec.consumed_by_pay_batch_id is null then null else v_override_consume_rec.consumed_by_pay_batch_id::text end,
            'consumed_at_utc', v_override_consume_rec.consumed_at_utc,
            'pay_batch_id', v_batch_id::text
          ),
          'ADVANCE_THIS_PAYMENT',
          p_actor_user_id
        );
      exception when others then
        null;
      end;
    end loop;
  end if;

  v_stage := 'STAGE_24_RETURN';

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_24_RETURN',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'return', jsonb_build_object(
          'ok', true,
          'pay_batch_id', v_batch_id::text,
          'pay_date', p_pay_date::text,
          'pay_week_start', v_week_start::text,
          'week_ending_cutoff_date', p_week_ending_cutoff::text,
          'pay_channel_scope', v_scope,
          'banking_system_snapshot', v_settings.banking_system,
          'external_paye_system_snapshot', v_settings.external_paye_system,
          'rail_provider_snapshot', v_settings.rail_provider_default,
          'rail_env_snapshot', v_settings.rail_env_default,
          'consumed_timesheet_payment_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed, 0),
          'consumed_timesheet_payment_overrides', v_consumed_timesheet_payment_overrides
        ),
        'dml_summary', jsonb_build_object(
          'batch_insert_rowcount', v_rows,
          'candidates_inserted', v_rows_ins_candidates,
          'items_inserted', v_rows_ins_items,
          'candidates_deleted_empty', v_rows_del_candidates,
          'loan_items_inserted', coalesce(v_rows_ins_loan_items,0),
          'overpayment_recovery_items_inserted', coalesce(v_rows_ins_overpayment_recovery_items,0),
          'underpayment_items_inserted', coalesce(v_rows_ins_underpayment_items,0),
          'debt_items_inserted', coalesce(v_rows_ins_debt_items,0),
          'loan_payout_items_inserted', coalesce(v_rows_ins_loan_payout_items,0),
          'manual_credit_payout_items_inserted', coalesce(v_rows_ins_manual_credit_payout_items,0),
          'snapshots_inserted', v_rows_ins_snapshots,
          'breakdowns_inserted', v_rows_ins_breakdowns,
          'breakdown_missing_ct', coalesce(v_breakdown_missing_ct,0),
          'breakdown_bad_ct', coalesce(v_breakdown_bad_ct,0),
          'timesheet_payment_overrides_consumed', coalesce(v_rows_upd_timesheet_overrides_consumed,0)
        )
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_batch_id::text,
    'pay_date', p_pay_date::text,
    'pay_week_start', v_week_start::text,
    'week_ending_cutoff_date', p_week_ending_cutoff::text,
    'pay_channel_scope', v_scope,
    'banking_system_snapshot', v_settings.banking_system,
    'external_paye_system_snapshot', v_settings.external_paye_system,
    'rail_provider_snapshot', v_settings.rail_provider_default,
    'rail_env_snapshot', v_settings.rail_env_default,
    'consumed_timesheet_payment_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed, 0),
    'consumed_timesheet_payment_overrides', v_consumed_timesheet_payment_overrides
  );

exception when others then
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:UNHANDLED_EXCEPTION',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', coalesce(v_batch_id::text, null),
        'pay_date', coalesce(p_pay_date::text, null),
        'week_ending_cutoff', coalesce(p_week_ending_cutoff::text, null),
        'scope', coalesce(v_scope, null),
        'candidate_filter_single', coalesce(v_candidate_filter_single::text, null),
        'client_filter_single', coalesce(v_client_filter_single::text, null),
        'candidate_ids_count', coalesce(array_length(v_candidate_ids,1),0),
        'candidate_ids_sample', (
          select coalesce(jsonb_agg(x.candidate_id::text order by x.candidate_id::text), '[]'::jsonb)
          from (
            select unnest(coalesce(v_candidate_ids, array[]::uuid[])) as candidate_id
            limit 50
          ) x
        ),
        'last_reserved_json', v_reserved,
        'blocked_candidates', v_blocked_candidates,
        'consumed_timesheet_payment_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed,0),
        'consumed_timesheet_payment_overrides', v_consumed_timesheet_payment_overrides,
        'breakdown_missing_ct', coalesce(v_breakdown_missing_ct,0),
        'breakdown_bad_ct', coalesce(v_breakdown_bad_ct,0),
        'breakdown_bad', v_breakdown_bad,
        'sqlstate', sqlstate,
        'sqlerrm', sqlerrm
      ),
      'pay_batches',
      coalesce(v_batch_id::text, 'pay_date:'||coalesce(p_pay_date::text,'null')),
      null, null, null, null, null
    );
  exception when others then
    null;
  end;

  raise;
end;
$$;


















-- =========================================================
-- A4.10 pay_timesheet_impact_preview(p_timesheet_id)
-- Returns baseline totals, current totals, and estimated deltas (raw + payable under ref-blocking rules)
-- =========================================================
create or replace function public.pay_timesheet_impact_preview(p_timesheet_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_tf record;
  v_ts record;

  v_require_ref boolean;

  v_base jsonb;
  v_base_segments jsonb;
  v_cur_segments jsonb;

  v_segment_ids text[];
  v_seg_id text;

  v_cur_pay numeric;
  v_cur_excl boolean;
  v_cur_ref text;

  v_base_pay numeric;
  v_base_excl boolean;

  v_cur_payable numeric;
  v_base_payable numeric;

  v_seg_delta_raw numeric;
  v_seg_delta_payable numeric;

  v_seg_sum_raw numeric := 0;
  v_seg_sum_payable numeric := 0;

  v_base_add numeric := 0;
  v_cur_add numeric := 0;

  v_base_exp numeric := 0;
  v_cur_exp numeric := 0;

  v_base_adj numeric := 0;
  v_cur_adj numeric := 0;

  v_delta_raw numeric := 0;
  v_delta_payable numeric := 0;
begin
  if p_timesheet_id is null then
    raise exception 'timesheet_id is required';
  end if;

  select
    tf.timesheet_id,
    tf.client_id,
    tf.invoice_breakdown_json,
    tf.total_pay_ex_vat,
    tf.additional_pay_ex_vat,
    tf.expenses_pay_ex_vat,
    tf.travel_pay_ex_vat,
    tf.accommodation_pay_ex_vat,
    tf.other_pay_ex_vat,
    tf.mileage_pay_ex_vat
  into v_tf
  from public.timesheets_financials tf
  where tf.timesheet_id = p_timesheet_id
    and tf.is_current = true
  limit 1;

  if v_tf.timesheet_id is null then
    raise exception 'timesheet_financials not found for timesheet';
  end if;

  select
    ts.timesheet_id,
    ts.contract_id,
    ts.reference_number
  into v_ts
  from public.timesheets ts
  where ts.timesheet_id = p_timesheet_id
    and ts.is_current = true
  limit 1;

  select
    coalesce(
      case when ct.overrideclientsettings then ct.require_reference_to_pay end,
      cs.pay_reference_required,
      false
    )
  into v_require_ref
  from public.contracts ct
  left join public.client_settings cs on cs.client_id = v_tf.client_id
  where ct.id = v_ts.contract_id
  limit 1;

  select coalesce(tps.last_settled_snapshot_json, '{}'::jsonb)
  into v_base
  from public.timesheet_pay_state tps
  where tps.timesheet_id = p_timesheet_id
  limit 1;

  v_base_segments := coalesce(v_base->'segments','[]'::jsonb);

  -- current segments
  if v_tf.invoice_breakdown_json is not null
     and jsonb_typeof(v_tf.invoice_breakdown_json) = 'object'
     and upper(coalesce(v_tf.invoice_breakdown_json->>'mode','')) = 'SEGMENTS'
     and jsonb_typeof(v_tf.invoice_breakdown_json->'segments') = 'array' then
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'segment_id', nullif(btrim(coalesce(seg->>'segment_id','')), ''),
          'pay_amount', round(coalesce(nullif(seg->>'pay_amount','')::numeric,0),2),
          'exclude_from_pay', coalesce(nullif(seg->>'exclude_from_pay','')::boolean,false),
          'ref_num', nullif(btrim(coalesce(seg->>'ref_num','')), '')
        )
      ),
      '[]'::jsonb
    )
    into v_cur_segments
    from jsonb_array_elements(v_tf.invoice_breakdown_json->'segments') seg
    where seg is not null and jsonb_typeof(seg)='object';
  else
    v_cur_segments := jsonb_build_array(
      jsonb_build_object(
        'segment_id', ('ts:' || p_timesheet_id::text),
        'pay_amount', round(coalesce(v_tf.total_pay_ex_vat,0),2),
        'exclude_from_pay', false,
        'ref_num', nullif(btrim(coalesce(v_ts.reference_number,'')), '')
      )
    );
  end if;

  select coalesce(array_agg(distinct sid), array[]::text[])
  into v_segment_ids
  from (
    select nullif(btrim(coalesce(s->>'segment_id','')),'') as sid
    from jsonb_array_elements(v_cur_segments) s
    where s is not null and jsonb_typeof(s)='object'
    union
    select nullif(btrim(coalesce(s->>'segment_id','')),'') as sid
    from jsonb_array_elements(v_base_segments) s
    where s is not null and jsonb_typeof(s)='object'
  ) u
  where u.sid is not null;

  foreach v_seg_id in array v_segment_ids
  loop
    select
      round(coalesce(nullif(s->>'pay_amount','')::numeric,0),2) as pay_amount,
      coalesce(nullif(s->>'exclude_from_pay','')::boolean,false) as exclude_from_pay,
      nullif(btrim(coalesce(s->>'ref_num','')), '') as ref_num
    into v_cur_pay, v_cur_excl, v_cur_ref
    from jsonb_array_elements(v_cur_segments) s
    where nullif(btrim(coalesce(s->>'segment_id','')),'') = v_seg_id
    limit 1;

    if v_cur_pay is null then v_cur_pay := 0; end if;
    if v_cur_excl is null then v_cur_excl := false; end if;

    select
      round(coalesce(nullif(s->>'pay_amount','')::numeric,0),2) as pay_amount,
      coalesce(nullif(s->>'exclude_from_pay','')::boolean,false) as exclude_from_pay
    into v_base_pay, v_base_excl
    from jsonb_array_elements(v_base_segments) s
    where nullif(btrim(coalesce(s->>'segment_id','')),'') = v_seg_id
    limit 1;

    if v_base_pay is null then v_base_pay := 0; end if;
    if v_base_excl is null then v_base_excl := false; end if;

    v_cur_payable := case when v_cur_excl then 0 else v_cur_pay end;
    v_base_payable := case when v_base_excl then 0 else v_base_pay end;

    v_seg_delta_raw := round(v_cur_payable - v_base_payable, 2);

    v_seg_delta_payable := v_seg_delta_raw;
    if v_require_ref = true
       and v_cur_excl = false
       and nullif(btrim(coalesce(v_cur_ref,'')),'') is null
       and v_seg_delta_raw > 0 then
      v_seg_delta_payable := 0;
    end if;

    v_seg_sum_raw := round(v_seg_sum_raw + v_seg_delta_raw, 2);
    v_seg_sum_payable := round(v_seg_sum_payable + v_seg_delta_payable, 2);
  end loop;

  v_base_add := round(coalesce(nullif(v_base->>'additional_pay_ex_vat','')::numeric,0),2);
  v_cur_add := round(coalesce(v_tf.additional_pay_ex_vat,0),2);

  v_base_exp :=
    round(coalesce(nullif(v_base #>> '{expenses,expenses_pay_ex_vat}','')::numeric,0),2)
    + round(coalesce(nullif(v_base #>> '{expenses,travel_pay_ex_vat}','')::numeric,0),2)
    + round(coalesce(nullif(v_base #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0),2)
    + round(coalesce(nullif(v_base #>> '{expenses,other_pay_ex_vat}','')::numeric,0),2)
    + round(coalesce(nullif(v_base #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0),2);

  v_cur_exp :=
    round(coalesce(v_tf.expenses_pay_ex_vat,0),2)
    + round(coalesce(v_tf.travel_pay_ex_vat,0),2)
    + round(coalesce(v_tf.accommodation_pay_ex_vat,0),2)
    + round(coalesce(v_tf.other_pay_ex_vat,0),2)
    + round(coalesce(v_tf.mileage_pay_ex_vat,0),2);

  -- baseline adjustments sum
  select round(coalesce(sum(coalesce(nullif(a->>'delta_pay_ex_vat','')::numeric,0)),0),2)
  into v_base_adj
  from jsonb_array_elements(coalesce(v_base->'adjustments','[]'::jsonb)) a;

  -- current adjustments sum
  select round(coalesce(sum(coalesce(a.delta_pay_ex_vat,0)),0),2)
  into v_cur_adj
  from public.ts_pay_adjustments a
  where a.timesheet_id = p_timesheet_id
    and a.as_advance = false;

  v_delta_raw := round((v_seg_sum_raw + (v_cur_add - v_base_add) + (v_cur_exp - v_base_exp) + (v_cur_adj - v_base_adj)), 2);
  v_delta_payable := round((v_seg_sum_payable + (v_cur_add - v_base_add) + (v_cur_exp - v_base_exp) + (v_cur_adj - v_base_adj)), 2);

  return jsonb_build_object(
    'ok', true,
    'timesheet_id', p_timesheet_id::text,
    'require_reference_to_pay', v_require_ref,
    'baseline', jsonb_build_object(
      'segments_payable_ex_vat', round(coalesce(v_seg_sum_raw,0) - coalesce(v_seg_sum_raw - v_seg_sum_raw,0),2),
      'additional_pay_ex_vat', v_base_add,
      'expenses_total_pay_ex_vat', v_base_exp,
      'adjustments_total_ex_vat', v_base_adj
    ),
    'current', jsonb_build_object(
      'additional_pay_ex_vat', v_cur_add,
      'expenses_total_pay_ex_vat', v_cur_exp,
      'adjustments_total_ex_vat', v_cur_adj
    ),
    'delta', jsonb_build_object(
      'raw_delta_ex_vat', v_delta_raw,
      'payable_delta_ex_vat', v_delta_payable
    )
  );
end;
$$;





-- =========================================================
-- A4.6 pay_settle_monzo(p_pay_batch_id, p_actor_user_id, p_confirmed bool)
-- =========================================================
CREATE OR REPLACE FUNCTION public.pay_settle_monzo(
  p_pay_batch_id uuid,
  p_actor_user_id uuid,
  p_confirmed boolean
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_batch record;
  v_guard_json jsonb := '{}'::jsonb;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_settle_monzo: pay_batch_id is required';
  END IF;

  IF p_confirmed IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'CONFIRM_REQUIRED';
  END IF;

  SELECT
    public.pay_batches.id,
    public.pay_batches.status,
    public.pay_batches.pay_date,
    public.pay_batches.banking_system_snapshot,
    public.pay_batches.external_paye_system_snapshot,
    public.pay_batches.rail_provider_snapshot,
    public.pay_batches.rail_env_snapshot,
    public.pay_batches.execution_commit_state,
    public.pay_batches.execution_commit_ref,
    public.pay_batches.execution_committed_at_utc,
    public.pay_batches.settlement_confirmation_json
  INTO v_batch
  FROM public.pay_batches
  WHERE public.pay_batches.id = p_pay_batch_id
  FOR UPDATE;

  IF v_batch.id IS NULL THEN
    RAISE EXCEPTION 'pay_settle_monzo: pay batch % not found', p_pay_batch_id;
  END IF;

  v_guard_json := jsonb_build_object(
    'error', 'USE_PAYMENT_CORRECTION_FLOW',
    'code', 'USE_PAYMENT_CORRECTION_FLOW',
    'message', 'pay_settle_monzo is deprecated because it bypasses the generic bank event ledger, no-money unwind, settled reversal, and remittance timing flow. Use pay_bank_event_ingest plus pay_settle_rail/pay_settle_manual_confirm instead.',
    'pay_batch_id', p_pay_batch_id::text,
    'status', v_batch.status,
    'pay_date', CASE WHEN v_batch.pay_date IS NULL THEN NULL ELSE v_batch.pay_date::text END,
    'banking_system_snapshot', v_batch.banking_system_snapshot,
    'external_paye_system_snapshot', v_batch.external_paye_system_snapshot,
    'rail_provider_snapshot', v_batch.rail_provider_snapshot,
    'rail_env_snapshot', v_batch.rail_env_snapshot,
    'execution_commit_state', v_batch.execution_commit_state,
    'execution_commit_ref', v_batch.execution_commit_ref,
    'execution_committed_at_utc', CASE WHEN v_batch.execution_committed_at_utc IS NULL THEN NULL ELSE v_batch.execution_committed_at_utc::text END
  );

  BEGIN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SETTLE_MONZO_BLOCKED_USE_GENERIC_RAIL_FLOW',
      v_guard_json,
      'pay_batch',
      p_pay_batch_id::text,
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RAISE EXCEPTION '%', v_guard_json::text;
END;
$$;


