      COALESCE(array_length(v_selected_umbrella_ids, 1), 0) > 0
      AND COALESCE(array_length(v_mail_umbrella_ids, 1), 0) > 0
      AND v_mail_umbrella_ids && v_selected_umbrella_ids
    )
    OR (
      COALESCE(array_length(v_selected_umbrella_ids, 1), 0) > 0
      AND upper(btrim(COALESCE(v_mail_row.recipient_kind, ''))) = 'UMBRELLA'
      AND v_mail_row.recipient_id IS NOT NULL
      AND v_mail_row.recipient_id = ANY(v_selected_umbrella_ids)
    )
  );

  v_transfer_scope_candidate_safe := (
    v_candidate_filter_requires_payment_match = false
    OR v_mail_candidate_scope_matches
  );

  v_transfer_scope_umbrella_safe := (
    v_umbrella_filter_requires_payment_match = false
    OR v_mail_umbrella_scope_matches
  );

  v_transfer_scope_safe := (
    v_transfer_scope_candidate_safe
    AND v_transfer_scope_umbrella_safe
  );

  IF v_mail_batch_matches = false THEN
    SELECT EXISTS(
      SELECT 1
      FROM unnest(v_selected_pay_batch_ids || ARRAY[p_pay_batch_id]) AS selected_batch_ids(batch_id)
      WHERE selected_batch_ids.batch_id IS NOT NULL
        AND COALESCE(v_mail_row.reference, '') ILIKE '%' || selected_batch_ids.batch_id::text || '%'
    )
    INTO v_reference_broad_match;

    IF v_reference_broad_match THEN
      IF v_is_whole_batch_scope THEN
        RETURN jsonb_build_object(
          'matched', true,
          'match_kind', 'WHOLE_BATCH',
          'match_confidence', 'LEGACY_BROAD',
          'safe_to_cancel', true,
          'requires_review', false,
          'reason', 'WHOLE_BATCH_SCOPE_MATCH_BY_LEGACY_BATCH_REFERENCE',
          'mail_outbox_id', p_mail_outbox_id,
          'pay_batch_id', p_pay_batch_id,
          'mail_status', v_mail_row.status::text,
          'mail_type', v_mail_row.type,
          'recipient_kind', v_mail_row.recipient_kind,
          'recipient_id', CASE WHEN v_mail_row.recipient_id IS NULL THEN NULL ELSE v_mail_row.recipient_id::text END,
          'context_kind', v_mail_row.context_kind,
          'context_id', CASE WHEN v_mail_row.context_id IS NULL THEN NULL ELSE v_mail_row.context_id::text END,
          'reference', v_mail_row.reference,
          'payment_scope_json', v_mail_scope,
          'legacy_broad_match_allowed', true,
          'safe_rule', 'Whole-batch correction may cancel mail rows matched by pay_batch_id.'
        );
      END IF;

      RETURN jsonb_build_object(
        'matched', true,
        'match_kind', 'LEGACY_BROAD',
        'match_confidence', 'LEGACY_BROAD',
        'safe_to_cancel', false,
        'requires_review', true,
        'reason', 'MAIL_MATCHES_BATCH_ONLY_BY_LEGACY_REFERENCE',
        'mail_outbox_id', p_mail_outbox_id,
        'pay_batch_id', p_pay_batch_id,
        'mail_status', v_mail_row.status::text,
        'legacy_broad_match_allowed', COALESCE(p_allow_legacy_broad_match, false)
      );
    END IF;

    RETURN jsonb_build_object(
      'matched', false,
      'match_kind', 'NONE',
      'match_confidence', 'NONE',
      'safe_to_cancel', false,
      'requires_review', false,
      'reason', 'MAIL_ROW_NOT_IN_PAY_BATCH_SCOPE',
      'mail_outbox_id', p_mail_outbox_id,
      'pay_batch_id', p_pay_batch_id,
      'mail_status', v_mail_row.status::text,
      'mail_context_kind', v_mail_row.context_kind,
      'mail_context_id', CASE WHEN v_mail_row.context_id IS NULL THEN NULL ELSE v_mail_row.context_id::text END
    );
  END IF;

  IF v_is_whole_batch_scope THEN
    RETURN jsonb_build_object(
      'matched', true,
      'match_kind', 'WHOLE_BATCH',
      'match_confidence', 'EXACT',
      'safe_to_cancel', true,
      'requires_review', false,
      'reason', 'WHOLE_BATCH_SCOPE_MATCH',
      'mail_outbox_id', p_mail_outbox_id,
      'pay_batch_id', p_pay_batch_id,
      'mail_status', v_mail_row.status::text,
      'payment_scope_json', v_mail_scope
    );
  END IF;

  v_item_exact := (
    COALESCE(array_length(v_mail_pay_batch_item_ids, 1), 0) > 0
    AND COALESCE(array_length(v_selected_pay_batch_item_ids, 1), 0) > 0
    AND v_mail_pay_batch_item_ids <@ v_selected_pay_batch_item_ids
  );

  v_item_partial := (
    COALESCE(array_length(v_mail_pay_batch_item_ids, 1), 0) > 0
    AND COALESCE(array_length(v_selected_pay_batch_item_ids, 1), 0) > 0
    AND v_mail_pay_batch_item_ids && v_selected_pay_batch_item_ids
    AND v_item_exact = false
  );

  v_transfer_exact := (
    COALESCE(array_length(v_mail_pay_bank_transfer_ids, 1), 0) > 0
    AND COALESCE(array_length(v_selected_pay_bank_transfer_ids, 1), 0) > 0
    AND v_mail_pay_bank_transfer_ids <@ v_selected_pay_bank_transfer_ids
  );

  v_transfer_partial := (
    COALESCE(array_length(v_mail_pay_bank_transfer_ids, 1), 0) > 0
    AND COALESCE(array_length(v_selected_pay_bank_transfer_ids, 1), 0) > 0
    AND v_mail_pay_bank_transfer_ids && v_selected_pay_bank_transfer_ids
    AND v_transfer_exact = false
  );

  v_payout_transfer_exact := (
    COALESCE(array_length(v_mail_payout_transfer_ids, 1), 0) > 0
    AND COALESCE(array_length(v_selected_payout_transfer_ids, 1), 0) > 0
    AND v_mail_payout_transfer_ids <@ v_selected_payout_transfer_ids
  );

  v_payout_transfer_partial := (
    COALESCE(array_length(v_mail_payout_transfer_ids, 1), 0) > 0
    AND COALESCE(array_length(v_selected_payout_transfer_ids, 1), 0) > 0
    AND v_mail_payout_transfer_ids && v_selected_payout_transfer_ids
    AND v_payout_transfer_exact = false
  );

  v_transfer_group_exact := (
    COALESCE(array_length(v_mail_transfer_group_keys, 1), 0) > 0
    AND COALESCE(array_length(v_selected_transfer_group_keys, 1), 0) > 0
    AND v_mail_transfer_group_keys <@ v_selected_transfer_group_keys
  );

  v_transfer_group_partial := (
    COALESCE(array_length(v_mail_transfer_group_keys, 1), 0) > 0
    AND COALESCE(array_length(v_selected_transfer_group_keys, 1), 0) > 0
    AND v_mail_transfer_group_keys && v_selected_transfer_group_keys
    AND v_transfer_group_exact = false
  );

  v_finance_case_exact := (
    COALESCE(array_length(v_mail_finance_case_ids, 1), 0) > 0
    AND COALESCE(array_length(v_selected_finance_case_ids, 1), 0) > 0
    AND v_mail_finance_case_ids <@ v_selected_finance_case_ids
  );

  v_finance_case_partial := (
    COALESCE(array_length(v_mail_finance_case_ids, 1), 0) > 0
    AND COALESCE(array_length(v_selected_finance_case_ids, 1), 0) > 0
    AND v_mail_finance_case_ids && v_selected_finance_case_ids
    AND v_finance_case_exact = false
  );

  v_finance_component_exact := (
    COALESCE(array_length(v_mail_finance_component_ids, 1), 0) > 0
    AND COALESCE(array_length(v_selected_finance_component_ids, 1), 0) > 0
    AND v_mail_finance_component_ids <@ v_selected_finance_component_ids
  );

  v_finance_component_partial := (
    COALESCE(array_length(v_mail_finance_component_ids, 1), 0) > 0
    AND COALESCE(array_length(v_selected_finance_component_ids, 1), 0) > 0
    AND v_mail_finance_component_ids && v_selected_finance_component_ids
    AND v_finance_component_exact = false
  );

  v_reservation_exact := (
    COALESCE(array_length(v_mail_reservation_ids, 1), 0) > 0
    AND COALESCE(array_length(v_selected_reservation_ids, 1), 0) > 0
    AND v_mail_reservation_ids <@ v_selected_reservation_ids
  );

  v_reservation_partial := (
    COALESCE(array_length(v_mail_reservation_ids, 1), 0) > 0
    AND COALESCE(array_length(v_selected_reservation_ids, 1), 0) > 0
    AND v_mail_reservation_ids && v_selected_reservation_ids
    AND v_reservation_exact = false
  );

  v_pay_batch_candidate_exact := (
    v_selected_candidate_scope_complete
    AND COALESCE(array_length(v_mail_pay_batch_candidate_ids, 1), 0) > 0
    AND COALESCE(array_length(v_selected_pay_batch_candidate_ids, 1), 0) > 0
    AND v_mail_pay_batch_candidate_ids <@ v_selected_pay_batch_candidate_ids
  );

  v_pay_batch_candidate_partial := (
    COALESCE(array_length(v_mail_pay_batch_candidate_ids, 1), 0) > 0
    AND COALESCE(array_length(v_selected_pay_batch_candidate_ids, 1), 0) > 0
    AND v_mail_pay_batch_candidate_ids && v_selected_pay_batch_candidate_ids
    AND v_pay_batch_candidate_exact = false
  );

  v_umbrella_group_exact := (
    COALESCE(array_length(v_mail_umbrella_ids, 1), 0) > 0
    AND COALESCE(array_length(v_selected_umbrella_ids, 1), 0) > 0
    AND v_mail_umbrella_ids <@ v_selected_umbrella_ids
    AND (
      v_transfer_group_exact
      OR v_transfer_exact
      OR v_item_exact
      OR v_payout_transfer_exact
      OR v_finance_case_exact
      OR v_finance_component_exact
      OR v_reservation_exact
    )
  );

  v_umbrella_partial := (
    COALESCE(array_length(v_mail_umbrella_ids, 1), 0) > 0
    AND COALESCE(array_length(v_selected_umbrella_ids, 1), 0) > 0
    AND v_mail_umbrella_ids && v_selected_umbrella_ids
    AND v_umbrella_group_exact = false
  );

  v_context_exact := (
    (
      lower(btrim(COALESCE(v_mail_row.context_kind, ''))) IN ('pay_batch_items', 'pay_batch_item')
      AND v_mail_row.context_id = ANY(v_selected_pay_batch_item_ids)
    )
    OR (
      lower(btrim(COALESCE(v_mail_row.context_kind, ''))) IN ('pay_bank_transfers', 'pay_bank_transfer')
      AND v_mail_row.context_id = ANY(v_selected_pay_bank_transfer_ids)
      AND v_transfer_scope_safe
    )
    OR (
      lower(btrim(COALESCE(v_mail_row.context_kind, ''))) IN ('pay_advances', 'pay_advance', 'finance_case', 'finance_cases')
      AND v_mail_row.context_id = ANY(v_selected_finance_case_ids)
    )
    OR (
      lower(btrim(COALESCE(v_mail_row.context_kind, ''))) IN ('pay_advance_reservations', 'pay_advance_reservation', 'reservation', 'reservations')
      AND v_mail_row.context_id = ANY(v_selected_reservation_ids)
    )
    OR (
      v_selected_candidate_scope_complete
      AND lower(btrim(COALESCE(v_mail_row.context_kind, ''))) IN ('pay_batch_candidates', 'pay_batch_candidate')
      AND v_mail_row.context_id = ANY(v_selected_pay_batch_candidate_ids)
    )
  );

  IF v_item_exact THEN
    v_match_kind := 'PAY_BATCH_ITEM';
    v_reason := 'PAY_BATCH_ITEM_SCOPE_MATCH';
  ELSIF v_transfer_exact AND v_transfer_scope_safe THEN
    v_match_kind := 'TRANSFER';
    v_reason := 'TRANSFER_SCOPE_MATCH';
  ELSIF v_payout_transfer_exact AND v_transfer_scope_safe THEN
    v_match_kind := 'TRANSFER';
    v_reason := 'PAYOUT_TRANSFER_SCOPE_MATCH';
  ELSIF v_umbrella_group_exact AND v_transfer_scope_safe THEN
    v_match_kind := 'UMBRELLA_GROUP';
    v_reason := 'UMBRELLA_GROUP_SCOPE_MATCH';
  ELSIF v_finance_component_exact THEN
    v_match_kind := 'FINANCE_CASE';
    v_reason := 'FINANCE_COMPONENT_SCOPE_MATCH';
  ELSIF v_reservation_exact THEN
    v_match_kind := 'RESERVATION';
    v_reason := 'RESERVATION_SCOPE_MATCH';
  ELSIF v_finance_case_exact THEN
    v_match_kind := 'FINANCE_CASE';
    v_reason := 'FINANCE_CASE_SCOPE_MATCH';
  ELSIF v_transfer_group_exact AND v_transfer_scope_safe THEN
    v_match_kind := 'TRANSFER';
    v_reason := 'TRANSFER_GROUP_SCOPE_MATCH';
  ELSIF v_pay_batch_candidate_exact THEN
    v_match_kind := 'PAY_BATCH_CANDIDATE';
    v_reason := 'COMPLETE_PAY_BATCH_CANDIDATE_SCOPE_MATCH';
  ELSIF v_context_exact THEN
    v_match_kind := CASE
      WHEN lower(btrim(COALESCE(v_mail_row.context_kind, ''))) IN ('pay_batch_items', 'pay_batch_item') THEN 'PAY_BATCH_ITEM'
      WHEN lower(btrim(COALESCE(v_mail_row.context_kind, ''))) IN ('pay_bank_transfers', 'pay_bank_transfer') THEN 'TRANSFER'
      WHEN lower(btrim(COALESCE(v_mail_row.context_kind, ''))) IN ('pay_batch_candidates', 'pay_batch_candidate') THEN 'PAY_BATCH_CANDIDATE'
      WHEN lower(btrim(COALESCE(v_mail_row.context_kind, ''))) IN ('pay_advance_reservations', 'pay_advance_reservation', 'reservation', 'reservations') THEN 'RESERVATION'
      ELSE 'FINANCE_CASE'
    END;
    v_reason := 'CONTEXT_SCOPE_MATCH';
  END IF;

  v_partial_overlap_requires_review := (
    v_item_partial
    OR v_transfer_partial
    OR (v_transfer_exact AND v_transfer_scope_safe = false)
    OR v_payout_transfer_partial
    OR (v_payout_transfer_exact AND v_transfer_scope_safe = false)
    OR v_transfer_group_partial
    OR (v_transfer_group_exact AND v_transfer_scope_safe = false)
    OR (v_umbrella_group_exact AND v_transfer_scope_safe = false)
    OR v_finance_case_partial
    OR v_finance_component_partial
    OR v_reservation_partial
    OR (
      v_pay_batch_candidate_partial
      AND NOT (
        v_item_exact
        OR v_transfer_exact
        OR v_payout_transfer_exact
        OR v_transfer_group_exact
        OR v_finance_case_exact
        OR v_finance_component_exact
        OR v_reservation_exact
      )
    )
    OR (
      v_umbrella_partial
      AND NOT (
        v_item_exact
        OR v_transfer_exact
        OR v_payout_transfer_exact
        OR v_transfer_group_exact
        OR v_finance_case_exact
        OR v_finance_component_exact
        OR v_reservation_exact
      )
    )
  );

  IF v_match_kind <> 'NONE' AND v_partial_overlap_requires_review THEN
    RETURN jsonb_build_object(
      'matched', true,
      'match_kind', 'LEGACY_BROAD',
      'match_confidence', 'LEGACY_BROAD',
      'safe_to_cancel', false,
      'requires_review', true,
      'reason', 'MAIL_SCOPE_PARTIAL_OVERLAP_REQUIRES_REVIEW',
      'mail_outbox_id', p_mail_outbox_id,
      'pay_batch_id', p_pay_batch_id,
      'mail_status', v_mail_row.status::text,
      'mail_type', v_mail_row.type,
      'recipient_kind', v_mail_row.recipient_kind,
      'recipient_id', CASE WHEN v_mail_row.recipient_id IS NULL THEN NULL ELSE v_mail_row.recipient_id::text END,
      'context_kind', v_mail_row.context_kind,
      'context_id', CASE WHEN v_mail_row.context_id IS NULL THEN NULL ELSE v_mail_row.context_id::text END,
      'reference', v_mail_row.reference,
      'payment_scope_json', v_mail_scope,
      'legacy_broad_match_allowed', COALESCE(p_allow_legacy_broad_match, false),
      'partial_overlap', true,
      'would_otherwise_match_kind', v_match_kind,
      'would_otherwise_match_reason', v_reason,
      'safe_rule', 'Do not cancel selected-scope mail rows when a populated scope dimension only partially overlaps the selected scope.'
    );
  END IF;

  IF v_match_kind <> 'NONE' THEN
    RETURN jsonb_build_object(
      'matched', true,
      'match_kind', v_match_kind,
      'match_confidence', 'EXACT',
      'safe_to_cancel', true,
      'requires_review', false,
      'reason', v_reason,
      'mail_outbox_id', p_mail_outbox_id,
      'pay_batch_id', p_pay_batch_id,
      'mail_status', v_mail_row.status::text,
      'mail_type', v_mail_row.type,
      'recipient_kind', v_mail_row.recipient_kind,
      'recipient_id', CASE WHEN v_mail_row.recipient_id IS NULL THEN NULL ELSE v_mail_row.recipient_id::text END,
      'context_kind', v_mail_row.context_kind,
      'context_id', CASE WHEN v_mail_row.context_id IS NULL THEN NULL ELSE v_mail_row.context_id::text END,
      'reference', v_mail_row.reference,
      'payment_scope_json', v_mail_scope,
      'selected_scope_summary', jsonb_build_object(
        'scope_type', v_scope_type,
        'pay_batch_item_count', COALESCE(array_length(v_selected_pay_batch_item_ids, 1), 0),
        'pay_bank_transfer_count', COALESCE(array_length(v_selected_pay_bank_transfer_ids, 1), 0),
        'pay_batch_candidate_count', COALESCE(array_length(v_selected_pay_batch_candidate_ids, 1), 0),
        'finance_case_count', COALESCE(array_length(v_selected_finance_case_ids, 1), 0),
        'finance_component_count', COALESCE(array_length(v_selected_finance_component_ids, 1), 0),
        'reservation_count', COALESCE(array_length(v_selected_reservation_ids, 1), 0),
        'payout_transfer_count', COALESCE(array_length(v_selected_payout_transfer_ids, 1), 0),
        'transfer_group_count', COALESCE(array_length(v_selected_transfer_group_keys, 1), 0)
      )
    );
  END IF;

  v_partial_overlap_requires_review := (
    v_item_partial
    OR v_transfer_partial
    OR (v_transfer_exact AND v_transfer_scope_safe = false)
    OR v_payout_transfer_partial
    OR (v_payout_transfer_exact AND v_transfer_scope_safe = false)
    OR v_transfer_group_partial
    OR (v_transfer_group_exact AND v_transfer_scope_safe = false)
    OR (v_umbrella_group_exact AND v_transfer_scope_safe = false)
    OR v_finance_case_partial
    OR v_finance_component_partial
    OR v_reservation_partial
    OR v_pay_batch_candidate_partial
    OR v_umbrella_partial
  );

  SELECT EXISTS(
    SELECT 1
    FROM unnest(v_selected_pay_batch_item_ids) AS selected_reference_item_ids(item_id)
    WHERE selected_reference_item_ids.item_id IS NOT NULL
      AND COALESCE(v_mail_row.reference, '') ILIKE '%' || selected_reference_item_ids.item_id::text || '%'
  ) OR EXISTS(
    SELECT 1
    FROM unnest(v_selected_pay_bank_transfer_ids) AS selected_reference_transfer_ids(transfer_id)
    WHERE selected_reference_transfer_ids.transfer_id IS NOT NULL
      AND COALESCE(v_mail_row.reference, '') ILIKE '%' || selected_reference_transfer_ids.transfer_id::text || '%'
  ) OR EXISTS(
    SELECT 1
    FROM unnest(v_selected_pay_batch_candidate_ids) AS selected_reference_candidate_ids(pay_batch_candidate_id)
    WHERE selected_reference_candidate_ids.pay_batch_candidate_id IS NOT NULL
      AND COALESCE(v_mail_row.reference, '') ILIKE '%' || selected_reference_candidate_ids.pay_batch_candidate_id::text || '%'
  ) OR EXISTS(
    SELECT 1
    FROM unnest(v_selected_candidate_ids) AS selected_reference_candidates(candidate_id)
    WHERE selected_reference_candidates.candidate_id IS NOT NULL
      AND COALESCE(v_mail_row.reference, '') ILIKE '%' || selected_reference_candidates.candidate_id::text || '%'
  ) OR EXISTS(
    SELECT 1
    FROM unnest(v_selected_umbrella_ids) AS selected_reference_umbrellas(umbrella_id)
    WHERE selected_reference_umbrellas.umbrella_id IS NOT NULL
      AND COALESCE(v_mail_row.reference, '') ILIKE '%' || selected_reference_umbrellas.umbrella_id::text || '%'
  ) OR EXISTS(
    SELECT 1
    FROM unnest(v_selected_finance_case_ids) AS selected_reference_finance_cases(finance_case_id)
    WHERE selected_reference_finance_cases.finance_case_id IS NOT NULL
      AND COALESCE(v_mail_row.reference, '') ILIKE '%' || selected_reference_finance_cases.finance_case_id::text || '%'
  ) OR EXISTS(
    SELECT 1
    FROM unnest(v_selected_finance_component_ids) AS selected_reference_finance_components(finance_component_id)
    WHERE selected_reference_finance_components.finance_component_id IS NOT NULL
      AND COALESCE(v_mail_row.reference, '') ILIKE '%' || selected_reference_finance_components.finance_component_id::text || '%'
  ) OR EXISTS(
    SELECT 1
    FROM unnest(v_selected_reservation_ids) AS selected_reference_reservations(reservation_id)
    WHERE selected_reference_reservations.reservation_id IS NOT NULL
      AND COALESCE(v_mail_row.reference, '') ILIKE '%' || selected_reference_reservations.reservation_id::text || '%'
  ) OR EXISTS(
    SELECT 1
    FROM unnest(v_selected_transfer_group_keys) AS selected_reference_groups(transfer_group_key)
    WHERE NULLIF(selected_reference_groups.transfer_group_key, '') IS NOT NULL
      AND COALESCE(v_mail_row.reference, '') ILIKE '%' || selected_reference_groups.transfer_group_key || '%'
  )
  INTO v_reference_broad_match;

  v_recipient_broad_match := (
    (
      upper(btrim(COALESCE(v_mail_row.recipient_kind, ''))) = 'CANDIDATE'
      AND v_mail_row.recipient_id IS NOT NULL
      AND (
        v_mail_row.recipient_id = ANY(v_selected_candidate_ids)
      )
    )
    OR (
      upper(btrim(COALESCE(v_mail_row.recipient_kind, ''))) = 'UMBRELLA'
      AND v_mail_row.recipient_id IS NOT NULL
      AND (
        v_mail_row.recipient_id = ANY(v_selected_umbrella_ids)
      )
    )
  );

  v_payment_scope_broad_match := (
    (
      COALESCE(array_length(v_mail_candidate_ids, 1), 0) > 0
      AND COALESCE(array_length(v_selected_candidate_ids, 1), 0) > 0
      AND v_mail_candidate_ids && v_selected_candidate_ids
    )
    OR (
      COALESCE(array_length(v_mail_umbrella_ids, 1), 0) > 0
      AND COALESCE(array_length(v_selected_umbrella_ids, 1), 0) > 0
      AND v_mail_umbrella_ids && v_selected_umbrella_ids
    )
    OR (
      COALESCE(array_length(v_mail_pay_batch_candidate_ids, 1), 0) > 0
      AND COALESCE(array_length(v_selected_pay_batch_candidate_ids, 1), 0) > 0
      AND v_mail_pay_batch_candidate_ids && v_selected_pay_batch_candidate_ids
    )
  );

  v_legacy_broad_match := (
    v_partial_overlap_requires_review
    OR v_reference_broad_match
    OR v_recipient_broad_match
    OR v_payment_scope_broad_match
  );

  IF v_legacy_broad_match THEN
    RETURN jsonb_build_object(
      'matched', true,
      'match_kind', 'LEGACY_BROAD',
      'match_confidence', 'LEGACY_BROAD',
      'safe_to_cancel', false,
      'requires_review', true,
      'reason', CASE
        WHEN v_partial_overlap_requires_review THEN 'MAIL_SCOPE_PARTIAL_OVERLAP_REQUIRES_REVIEW'
        WHEN v_reference_broad_match THEN 'MAIL_SCOPE_MATCHES_LEGACY_REFERENCE_ONLY'
        WHEN v_recipient_broad_match THEN 'MAIL_SCOPE_MATCHES_RECIPIENT_ONLY'
        ELSE 'MAIL_SCOPE_MATCHES_BROAD_PAYMENT_SCOPE_ONLY'
      END,
      'mail_outbox_id', p_mail_outbox_id,
      'pay_batch_id', p_pay_batch_id,
      'mail_status', v_mail_row.status::text,
      'mail_type', v_mail_row.type,
      'recipient_kind', v_mail_row.recipient_kind,
      'recipient_id', CASE WHEN v_mail_row.recipient_id IS NULL THEN NULL ELSE v_mail_row.recipient_id::text END,
      'context_kind', v_mail_row.context_kind,
      'context_id', CASE WHEN v_mail_row.context_id IS NULL THEN NULL ELSE v_mail_row.context_id::text END,
      'reference', v_mail_row.reference,
      'payment_scope_json', v_mail_scope,
      'legacy_broad_match_allowed', COALESCE(p_allow_legacy_broad_match, false),
      'partial_overlap', v_partial_overlap_requires_review,
      'safe_rule', 'Do not cancel selected-scope mail rows unless safe_to_cancel is true.'
    );
  END IF;

  RETURN jsonb_build_object(
    'matched', false,
    'match_kind', 'NONE',
    'match_confidence', 'NONE',
    'safe_to_cancel', false,
    'requires_review', false,
    'reason', 'NO_EXACT_OR_LEGACY_SCOPE_MATCH',
    'mail_outbox_id', p_mail_outbox_id,
    'pay_batch_id', p_pay_batch_id,
    'mail_status', v_mail_row.status::text,
    'mail_type', v_mail_row.type,
    'recipient_kind', v_mail_row.recipient_kind,
    'recipient_id', CASE WHEN v_mail_row.recipient_id IS NULL THEN NULL ELSE v_mail_row.recipient_id::text END,
    'context_kind', v_mail_row.context_kind,
    'context_id', CASE WHEN v_mail_row.context_id IS NULL THEN NULL ELSE v_mail_row.context_id::text END,
    'reference', v_mail_row.reference,
    'payment_scope_json', v_mail_scope
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.timesheet_authorise_bulk_atomic(p_items jsonb DEFAULT '[]'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 VOLATILE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamp with time zone := COALESCE(p_now_utc, now());
  v_items_array jsonb := '[]'::jsonb;
  v_uuid_re text := '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
  v_success_count integer := 0;
  v_failure_count integer := 0;
  v_out jsonb;
BEGIN
  IF p_actor_user_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT(
      'ok', FALSE,
      'batch_completed', FALSE,
      'all_success', FALSE,
      'action', 'AUTHORISE',
      'error_code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'timesheet_authorise_bulk_atomic requires p_actor_user_id.',
      'requested_count', 0,
      'success_count', 0,
      'failure_count', 0,
      'results', '[]'::jsonb,
      'row_patches', '[]'::jsonb,
      'count_deltas', JSONB_BUILD_OBJECT('processed_eligible', 0, 'authorised_eligible', 0, 'total', 0),
      'cache_invalidation_hints', JSONB_BUILD_OBJECT('row_keys', '[]'::jsonb, 'timesheet_ids', '[]'::jsonb, 'storage_keys', '[]'::jsonb, 'datasets', JSONB_BUILD_ARRAY('bulk_authorise'))
    );
  END IF;

  IF p_items IS NOT NULL AND JSONB_TYPEOF(p_items) NOT IN ('array', 'object') THEN
    RETURN JSONB_BUILD_OBJECT(
      'ok', FALSE,
      'batch_completed', FALSE,
      'all_success', FALSE,
      'action', 'AUTHORISE',
      'error_code', 'ITEMS_JSON_MUST_BE_ARRAY_OR_OBJECT',
      'message', 'p_items must be a JSON array or an object containing items/rows/selected/selections.',
      'requested_count', 0,
      'success_count', 0,
      'failure_count', 0,
      'results', '[]'::jsonb,
      'row_patches', '[]'::jsonb,
      'count_deltas', JSONB_BUILD_OBJECT('processed_eligible', 0, 'authorised_eligible', 0, 'total', 0),
      'cache_invalidation_hints', JSONB_BUILD_OBJECT('row_keys', '[]'::jsonb, 'timesheet_ids', '[]'::jsonb, 'storage_keys', '[]'::jsonb, 'datasets', JSONB_BUILD_ARRAY('bulk_authorise'))
    );
  END IF;

  v_items_array := CASE
    WHEN p_items IS NULL THEN '[]'::jsonb
    WHEN JSONB_TYPEOF(p_items) = 'array' THEN p_items
    WHEN JSONB_TYPEOF(p_items) = 'object' AND JSONB_TYPEOF(p_items->'items') = 'array' THEN p_items->'items'
    WHEN JSONB_TYPEOF(p_items) = 'object' AND JSONB_TYPEOF(p_items->'rows') = 'array' THEN p_items->'rows'
    WHEN JSONB_TYPEOF(p_items) = 'object' AND JSONB_TYPEOF(p_items->'selected') = 'array' THEN p_items->'selected'
    WHEN JSONB_TYPEOF(p_items) = 'object' AND JSONB_TYPEOF(p_items->'selections') = 'array' THEN p_items->'selections'
    WHEN JSONB_TYPEOF(p_items) = 'object' THEN JSONB_BUILD_ARRAY(p_items)
    ELSE '[]'::jsonb
  END;

  DROP TABLE IF EXISTS pg_temp.timesheet_authorise_bulk_items;
  DROP TABLE IF EXISTS pg_temp.timesheet_authorise_bulk_state;
  DROP TABLE IF EXISTS pg_temp.timesheet_authorise_bulk_decisions;
  DROP TABLE IF EXISTS pg_temp.timesheet_authorise_bulk_work;
  DROP TABLE IF EXISTS pg_temp.timesheet_authorise_bulk_updated_ts;
  DROP TABLE IF EXISTS pg_temp.timesheet_authorise_bulk_updated_tf;
  DROP TABLE IF EXISTS pg_temp.timesheet_authorise_bulk_post_decisions;
  DROP TABLE IF EXISTS pg_temp.timesheet_authorise_bulk_results;

  CREATE TEMP TABLE timesheet_authorise_bulk_items ON COMMIT DROP AS
  SELECT
    input_values.ordinality::integer AS ordinal,
    CASE WHEN JSONB_TYPEOF(input_values.item_json) = 'object' THEN input_values.item_json ELSE JSONB_BUILD_OBJECT('value', input_values.item_json) END AS item_json,
    NULLIF(BTRIM(COALESCE(input_values.item_json->>'row_key', input_values.item_json->>'rowKey', '')), '') AS row_key,
    NULLIF(BTRIM(COALESCE(input_values.item_json->>'timesheet_id', input_values.item_json->>'timesheetId', input_values.item_json->>'current_timesheet_id', input_values.item_json->>'currentTimesheetId', input_values.item_json->>'requested_timesheet_id', input_values.item_json->>'requestedTimesheetId', '')), '') AS timesheet_id_text,
    NULLIF(BTRIM(COALESCE(input_values.item_json->>'expected_timesheet_id', input_values.item_json->>'expectedTimesheetId', input_values.item_json->>'expected_current_timesheet_id', input_values.item_json->>'expectedCurrentTimesheetId', '')), '') AS expected_timesheet_id_text,
    NULLIF(BTRIM(COALESCE(input_values.item_json->>'row_signature', input_values.item_json->>'rowSignature', input_values.item_json->>'expected_row_signature', input_values.item_json->>'expectedRowSignature', '')), '') AS expected_row_signature
  FROM JSONB_ARRAY_ELEMENTS(v_items_array) WITH ORDINALITY AS input_values(item_json, ordinality);

  CREATE TEMP TABLE timesheet_authorise_bulk_state ON COMMIT DROP AS
  SELECT
    item_rows.ordinal,
    item_rows.item_json,
    item_rows.row_key,
    CASE
      WHEN item_rows.timesheet_id_text ~* v_uuid_re THEN item_rows.timesheet_id_text::uuid
      WHEN item_rows.row_key LIKE 'timesheet:%' AND SUBSTRING(item_rows.row_key FROM 11) ~* v_uuid_re THEN SUBSTRING(item_rows.row_key FROM 11)::uuid
      ELSE NULL::uuid
    END AS requested_timesheet_id,
    CASE WHEN item_rows.expected_timesheet_id_text ~* v_uuid_re THEN item_rows.expected_timesheet_id_text::uuid ELSE NULL::uuid END AS expected_timesheet_id,
    item_rows.expected_row_signature AS expected_row_signature,
    requested_ts.timesheet_id AS db_requested_timesheet_id,
    requested_ts.booking_id AS requested_booking_id,
    requested_ts.version AS requested_version,
    requested_ts.is_current AS requested_is_current,
    current_ts.timesheet_id AS current_timesheet_id,
    current_ts.booking_id AS current_booking_id,
    current_ts.version AS current_version,
    current_ts.is_current AS current_is_current,
    current_ts.authorised_at_server AS current_authorised_at_server,
    current_ts.sheet_scope AS current_sheet_scope,
    current_ts.submission_mode AS current_submission_mode,
    current_tf.id AS tsfin_id,
    current_tf.processing_status AS tsfin_processing_status,
    current_tf.basis AS tsfin_basis,
    current_tf.locked_by_invoice_id AS tsfin_locked_by_invoice_id,
    current_tf.paid_at_utc AS tsfin_paid_at_utc,
    current_tf.invoice_breakdown_json AS tsfin_invoice_breakdown_json,
    COALESCE(segment_state.has_segment_invoice_lock, FALSE) AS has_segment_invoice_lock
  FROM pg_temp.timesheet_authorise_bulk_items AS item_rows
  LEFT JOIN LATERAL (
    SELECT ts_req.timesheet_id, ts_req.booking_id, ts_req.version, ts_req.is_current
    FROM public.timesheets AS ts_req
    WHERE ts_req.timesheet_id = CASE
      WHEN item_rows.timesheet_id_text ~* v_uuid_re THEN item_rows.timesheet_id_text::uuid
      WHEN item_rows.row_key LIKE 'timesheet:%' AND SUBSTRING(item_rows.row_key FROM 11) ~* v_uuid_re THEN SUBSTRING(item_rows.row_key FROM 11)::uuid
      ELSE NULL::uuid
    END
    ORDER BY ts_req.version DESC NULLS LAST, ts_req.updated_at DESC NULLS LAST, ts_req.created_at DESC NULLS LAST, ts_req.timesheet_id DESC
    LIMIT 1
    FOR UPDATE
  ) AS requested_ts ON TRUE
  LEFT JOIN LATERAL (
    SELECT ts_cur.timesheet_id, ts_cur.booking_id, ts_cur.version, ts_cur.is_current, ts_cur.authorised_at_server, ts_cur.sheet_scope, ts_cur.submission_mode
    FROM public.timesheets AS ts_cur
    WHERE requested_ts.booking_id IS NOT NULL
      AND ts_cur.booking_id = requested_ts.booking_id
    ORDER BY CASE WHEN COALESCE(ts_cur.is_current, FALSE) = TRUE THEN 0 ELSE 1 END ASC,
             ts_cur.version DESC NULLS LAST,
             ts_cur.updated_at DESC NULLS LAST,
             ts_cur.created_at DESC NULLS LAST,
             ts_cur.timesheet_id DESC
    LIMIT 1
    FOR UPDATE
  ) AS current_ts ON TRUE
  LEFT JOIN LATERAL (
    SELECT tf_sel.id, tf_sel.processing_status, tf_sel.basis, tf_sel.locked_by_invoice_id, tf_sel.paid_at_utc, tf_sel.invoice_breakdown_json
    FROM public.timesheets_financials AS tf_sel
    WHERE tf_sel.timesheet_id = current_ts.timesheet_id
      AND tf_sel.is_current = TRUE
    ORDER BY tf_sel.computed_at_utc DESC NULLS LAST, tf_sel.created_at DESC NULLS LAST, tf_sel.updated_at DESC NULLS LAST, tf_sel.id DESC
    LIMIT 1
    FOR UPDATE
  ) AS current_tf ON TRUE
  LEFT JOIN LATERAL (
    SELECT EXISTS (
      SELECT 1
      FROM JSONB_ARRAY_ELEMENTS(
        CASE
          WHEN current_tf.invoice_breakdown_json IS NULL THEN '[]'::jsonb
          WHEN JSONB_TYPEOF(current_tf.invoice_breakdown_json) = 'array' THEN current_tf.invoice_breakdown_json
          WHEN JSONB_TYPEOF(current_tf.invoice_breakdown_json) = 'object' AND JSONB_TYPEOF(current_tf.invoice_breakdown_json->'segments') = 'array' THEN current_tf.invoice_breakdown_json->'segments'
          ELSE '[]'::jsonb
        END
      ) AS invoice_segment(segment_json)
      WHERE NULLIF(BTRIM(COALESCE(invoice_segment.segment_json->>'invoice_locked_invoice_id', '')), '') IS NOT NULL
    ) AS has_segment_invoice_lock
  ) AS segment_state ON TRUE;

  CREATE TEMP TABLE timesheet_authorise_bulk_decisions ON COMMIT DROP AS
  SELECT decision_result.row_json
  FROM (
    SELECT decision_ids.timesheet_ids_json
    FROM (
      SELECT COALESCE(JSONB_AGG(DISTINCT TO_JSONB(state_rows.current_timesheet_id::text)) FILTER (WHERE state_rows.current_timesheet_id IS NOT NULL), '[]'::jsonb) AS timesheet_ids_json
      FROM pg_temp.timesheet_authorise_bulk_state AS state_rows
    ) AS decision_ids
    WHERE JSONB_ARRAY_LENGTH(decision_ids.timesheet_ids_json) > 0
  ) AS decision_filter
  CROSS JOIN LATERAL public.bulk_timesheet_row_patch_v1(JSONB_BUILD_OBJECT('timesheet_ids', decision_filter.timesheet_ids_json, 'dataset_mode', 'authorise', 'projection', 'status_patch', 'changed_domains', JSONB_BUILD_ARRAY('authorise'))) AS decision_result(row_json);

  CREATE TEMP TABLE timesheet_authorise_bulk_work ON COMMIT DROP AS
  SELECT
    state_rows.ordinal,
    state_rows.item_json,
    state_rows.row_key,
    state_rows.requested_timesheet_id,
    state_rows.expected_timesheet_id,
    state_rows.expected_row_signature,
    state_rows.db_requested_timesheet_id,
    state_rows.requested_booking_id,
    state_rows.requested_version,
    state_rows.requested_is_current,
    state_rows.current_timesheet_id,
    state_rows.current_booking_id,
    state_rows.current_version,
    state_rows.current_is_current,
    state_rows.current_authorised_at_server,
    state_rows.current_sheet_scope,
    state_rows.current_submission_mode,
    state_rows.tsfin_id,
    state_rows.tsfin_processing_status,
    state_rows.tsfin_basis,
    state_rows.tsfin_locked_by_invoice_id,
    state_rows.tsfin_paid_at_utc,
    state_rows.has_segment_invoice_lock,
    decision_rows.row_json AS pre_row_json,
    COALESCE((decision_rows.row_json->>'can_bulk_authorise')::boolean, FALSE) AS eligible_flag,
    CASE
      WHEN state_rows.requested_timesheet_id IS NULL THEN 'TIMESHEET_ID_REQUIRED'
      WHEN state_rows.expected_timesheet_id IS NULL THEN 'EXPECTED_TIMESHEET_ID_REQUIRED'
      WHEN state_rows.db_requested_timesheet_id IS NULL THEN 'TIMESHEET_NOT_FOUND'
      WHEN state_rows.current_timesheet_id IS NULL THEN 'CURRENT_TIMESHEET_NOT_FOUND'
      WHEN state_rows.current_is_current IS DISTINCT FROM TRUE THEN 'CURRENT_TIMESHEET_NOT_FOUND'
      WHEN state_rows.expected_timesheet_id IS DISTINCT FROM state_rows.current_timesheet_id THEN 'TIMESHEET_MOVED'
      WHEN state_rows.tsfin_id IS NULL THEN 'NO_TSFIN'
      WHEN decision_rows.row_json IS NULL THEN 'DECISION_ROW_NOT_FOUND'
      WHEN state_rows.expected_row_signature IS NOT NULL AND NULLIF(BTRIM(COALESCE(decision_rows.row_json->>'row_signature', '')), '') IS DISTINCT FROM state_rows.expected_row_signature THEN 'ROW_SIGNATURE_MISMATCH'
      WHEN state_rows.tsfin_locked_by_invoice_id IS NOT NULL OR state_rows.tsfin_paid_at_utc IS NOT NULL OR state_rows.has_segment_invoice_lock = TRUE OR COALESCE((decision_rows.row_json->>'locked')::boolean, FALSE) = TRUE THEN 'TIMESHEET_LOCKED_OR_PAID'
      WHEN COALESCE((decision_rows.row_json->>'qr_unsigned_blocked')::boolean, FALSE) = TRUE THEN 'QR_UNSIGNED_BLOCKED'
      WHEN COALESCE((decision_rows.row_json->>'is_authorised')::boolean, FALSE) = TRUE THEN 'ALREADY_AUTHORISED'
      WHEN COALESCE((decision_rows.row_json->>'requires_authorisation')::boolean, FALSE) = FALSE THEN 'AUTHORISATION_NOT_REQUIRED'
      WHEN COALESCE((decision_rows.row_json->>'can_bulk_authorise')::boolean, FALSE) = FALSE THEN 'AUTHORISE_NOT_ALLOWED'
      ELSE NULL::text
    END AS failure_code,
    CASE
      WHEN state_rows.tsfin_processing_status IN ('PENDING_AUTH'::public.ts_fin_processing_status_enum, 'READY_FOR_HR'::public.ts_fin_processing_status_enum) THEN
        CASE
          WHEN COALESCE((decision_rows.row_json->>'hr_validation_awaiting')::boolean, FALSE) = TRUE THEN 'READY_FOR_HR'::public.ts_fin_processing_status_enum
          WHEN state_rows.tsfin_basis IN ('NHSP'::public.timesheet_fin_basis_enum, 'NHSP_ADJUSTMENT'::public.timesheet_fin_basis_enum, 'HEALTHROSTER_SELF_BILL'::public.timesheet_fin_basis_enum, 'HEALTHROSTER_ADJUSTMENT'::public.timesheet_fin_basis_enum) THEN 'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum
          WHEN COALESCE((decision_rows.row_json->>'client_requires_hr')::boolean, FALSE) = TRUE THEN 'READY_FOR_HR'::public.ts_fin_processing_status_enum
          ELSE 'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum
        END
      ELSE state_rows.tsfin_processing_status
    END AS new_processing_status
  FROM pg_temp.timesheet_authorise_bulk_state AS state_rows
  LEFT JOIN pg_temp.timesheet_authorise_bulk_decisions AS decision_rows
    ON CASE WHEN COALESCE(decision_rows.row_json->>'timesheet_id', '') ~* v_uuid_re THEN (decision_rows.row_json->>'timesheet_id')::uuid ELSE NULL::uuid END = state_rows.current_timesheet_id;

  CREATE TEMP TABLE timesheet_authorise_bulk_updated_ts ON COMMIT DROP AS
  WITH updated_rows AS (
    UPDATE public.timesheets AS ts_upd
    SET authorised_at_server = v_now,
        updated_at = v_now
    FROM pg_temp.timesheet_authorise_bulk_work AS work_rows
    WHERE work_rows.failure_code IS NULL
      AND ts_upd.timesheet_id = work_rows.current_timesheet_id
      AND ts_upd.is_current = TRUE
    RETURNING ts_upd.timesheet_id, ts_upd.version, ts_upd.updated_at
  )
  SELECT updated_rows.timesheet_id, updated_rows.version, updated_rows.updated_at
  FROM updated_rows;

  CREATE TEMP TABLE timesheet_authorise_bulk_updated_tf ON COMMIT DROP AS
  WITH updated_rows AS (
    UPDATE public.timesheets_financials AS tf_upd
    SET processing_status = work_rows.new_processing_status,
        authorised_by_user_id = p_actor_user_id,
        authorised_at_utc = v_now,
        updated_at = v_now
    FROM pg_temp.timesheet_authorise_bulk_work AS work_rows
    JOIN pg_temp.timesheet_authorise_bulk_updated_ts AS updated_ts
      ON updated_ts.timesheet_id = work_rows.current_timesheet_id
    WHERE work_rows.failure_code IS NULL
      AND tf_upd.id = work_rows.tsfin_id
      AND tf_upd.is_current = TRUE
    RETURNING tf_upd.timesheet_id, tf_upd.processing_status, tf_upd.updated_at
  )
  SELECT updated_rows.timesheet_id, updated_rows.processing_status, updated_rows.updated_at
  FROM updated_rows;


  CREATE TEMP TABLE timesheet_authorise_bulk_post_decisions ON COMMIT DROP AS
  SELECT post_decision_result.row_json
  FROM (
    SELECT post_ids.timesheet_ids_json
    FROM (
      SELECT COALESCE(JSONB_AGG(DISTINCT TO_JSONB(updated_tf.timesheet_id::text)) FILTER (WHERE updated_tf.timesheet_id IS NOT NULL), '[]'::jsonb) AS timesheet_ids_json
      FROM pg_temp.timesheet_authorise_bulk_updated_tf AS updated_tf
    ) AS post_ids
    WHERE JSONB_ARRAY_LENGTH(post_ids.timesheet_ids_json) > 0
  ) AS post_filter
  CROSS JOIN LATERAL public.bulk_timesheet_row_patch_v1(JSONB_BUILD_OBJECT('timesheet_ids', post_filter.timesheet_ids_json, 'dataset_mode', 'authorise', 'projection', 'status_patch', 'changed_domains', JSONB_BUILD_ARRAY('authorise'))) AS post_decision_result(row_json);



  PERFORM public._audit_insert(
    'timesheet',
    audit_work.current_timesheet_id::text,
    'TIMESHEET_BULK_AUTHORISED',
    JSONB_BUILD_OBJECT(
      'row', COALESCE(audit_work.pre_row_json, JSONB_BUILD_OBJECT()),
      'processing_status', audit_work.tsfin_processing_status,
      'authorised_at_server', audit_work.current_authorised_at_server,
      'row_signature', audit_work.pre_row_json->>'row_signature'
    ),
    JSONB_BUILD_OBJECT(
      'row', COALESCE(audit_post.row_json, JSONB_BUILD_OBJECT()),
      'processing_status', audit_updated.processing_status,
      'authorised_at_server', CASE WHEN 'AUTHORISE' = 'AUTHORISE' THEN v_now ELSE NULL::timestamp with time zone END,
      'row_signature', audit_post.row_json->>'row_signature'
    ),
    'BULK_AUTHORISE',
    p_actor_user_id
  )
  FROM pg_temp.timesheet_authorise_bulk_work AS audit_work
  JOIN pg_temp.timesheet_authorise_bulk_updated_tf AS audit_updated
    ON audit_updated.timesheet_id = audit_work.current_timesheet_id
  LEFT JOIN pg_temp.timesheet_authorise_bulk_post_decisions AS audit_post
    ON CASE WHEN COALESCE(audit_post.row_json->>'timesheet_id', '') ~* v_uuid_re THEN (audit_post.row_json->>'timesheet_id')::uuid ELSE NULL::uuid END = audit_work.current_timesheet_id
  WHERE audit_work.failure_code IS NULL;

  CREATE TEMP TABLE timesheet_authorise_bulk_results ON COMMIT DROP AS
  SELECT
    work_rows.ordinal,
    CASE WHEN work_rows.failure_code IS NULL AND updated_tf.timesheet_id IS NOT NULL THEN TRUE ELSE FALSE END AS success,
    JSONB_BUILD_OBJECT(
      'item_index', work_rows.ordinal,
      'success', CASE WHEN work_rows.failure_code IS NULL AND updated_tf.timesheet_id IS NOT NULL THEN TRUE ELSE FALSE END,
      'action', 'AUTHORISE',
      'error_code', CASE WHEN work_rows.failure_code IS NULL AND updated_tf.timesheet_id IS NOT NULL THEN NULL::text ELSE COALESCE(work_rows.failure_code, 'MUTATION_UPDATE_FAILED') END,
      'message', CASE
        WHEN work_rows.failure_code IS NULL AND updated_tf.timesheet_id IS NOT NULL THEN NULL::text
        WHEN COALESCE(work_rows.failure_code, 'MUTATION_UPDATE_FAILED') = 'TIMESHEET_MOVED' THEN 'Timesheet has moved to a different current row.'
        WHEN COALESCE(work_rows.failure_code, 'MUTATION_UPDATE_FAILED') = 'TIMESHEET_LOCKED_OR_PAID' THEN 'Timesheet is locked, invoice-locked, or paid.'
        WHEN COALESCE(work_rows.failure_code, 'MUTATION_UPDATE_FAILED') = 'ROW_SIGNATURE_MISMATCH' THEN 'Timesheet changed after it was loaded. Refresh the row and try again.'
        WHEN COALESCE(work_rows.failure_code, 'MUTATION_UPDATE_FAILED') = 'QR_UNSIGNED_BLOCKED' THEN 'QR timesheet has not been signed and returned.'
        WHEN COALESCE(work_rows.failure_code, 'MUTATION_UPDATE_FAILED') = 'AUTHORISE_NOT_ALLOWED' THEN 'Timesheet is not eligible for bulk authorisation.'
        ELSE COALESCE(work_rows.failure_code, 'MUTATION_UPDATE_FAILED')
      END,
      'requested_timesheet_id', work_rows.requested_timesheet_id,
      'expected_timesheet_id', work_rows.expected_timesheet_id,
      'expected_row_signature', work_rows.expected_row_signature,
      'current_row_signature', work_rows.pre_row_json->>'row_signature',
      'current_timesheet_id', work_rows.current_timesheet_id,
      'current_version', COALESCE(updated_ts.version, work_rows.current_version),
      'was_stale', work_rows.requested_timesheet_id IS DISTINCT FROM work_rows.current_timesheet_id,
      'processing_status_before', work_rows.tsfin_processing_status,
      'processing_status_after', updated_tf.processing_status,
      'row_key_before', COALESCE(work_rows.row_key, work_rows.pre_row_json->>'row_key'),
      'row_key_after', COALESCE(post_rows.row_json->>'row_key', work_rows.pre_row_json->>'row_key'),
      'row', CASE WHEN work_rows.failure_code IS NULL AND updated_tf.timesheet_id IS NOT NULL THEN COALESCE(post_rows.row_json, JSONB_BUILD_OBJECT()) ELSE COALESCE(work_rows.pre_row_json, JSONB_BUILD_OBJECT()) END,
      'row_patch', CASE WHEN work_rows.failure_code IS NULL AND updated_tf.timesheet_id IS NOT NULL THEN COALESCE(post_rows.row_json->'row_patch', JSONB_BUILD_OBJECT()) ELSE JSONB_BUILD_OBJECT() END,
      'cache_invalidation_hints', CASE WHEN work_rows.failure_code IS NULL AND updated_tf.timesheet_id IS NOT NULL THEN JSONB_BUILD_OBJECT(
        'row_keys', JSONB_BUILD_ARRAY(COALESCE(work_rows.row_key, work_rows.pre_row_json->>'row_key'), post_rows.row_json->>'row_key'),
        'timesheet_ids', JSONB_BUILD_ARRAY(work_rows.requested_timesheet_id, work_rows.current_timesheet_id),
        'storage_keys', '[]'::jsonb,
        'row_signature', post_rows.row_json->>'row_signature',
        'status_only', TRUE,
        'invalidate_context', FALSE,
        'invalidate_row_context', FALSE,
        'invalidate_preview', FALSE,
        'invalidate_evidence', FALSE
      ) ELSE JSONB_BUILD_OBJECT() END
    ) AS result_json
  FROM pg_temp.timesheet_authorise_bulk_work AS work_rows
  LEFT JOIN pg_temp.timesheet_authorise_bulk_updated_ts AS updated_ts ON updated_ts.timesheet_id = work_rows.current_timesheet_id
  LEFT JOIN pg_temp.timesheet_authorise_bulk_updated_tf AS updated_tf ON updated_tf.timesheet_id = work_rows.current_timesheet_id
  LEFT JOIN pg_temp.timesheet_authorise_bulk_post_decisions AS post_rows ON CASE WHEN COALESCE(post_rows.row_json->>'timesheet_id', '') ~* v_uuid_re THEN (post_rows.row_json->>'timesheet_id')::uuid ELSE NULL::uuid END = work_rows.current_timesheet_id;

  SELECT
    COUNT(result_rows.result_json) FILTER (WHERE result_rows.success = TRUE)::integer,
    COUNT(result_rows.result_json) FILTER (WHERE result_rows.success = FALSE)::integer
  INTO v_success_count, v_failure_count
  FROM pg_temp.timesheet_authorise_bulk_results AS result_rows;

  SELECT JSONB_BUILD_OBJECT(
    'ok', TRUE,
    'batch_completed', TRUE,
    'all_success', v_failure_count = 0,
    'action', 'AUTHORISE',
    'requested_count', JSONB_ARRAY_LENGTH(v_items_array),
    'success_count', v_success_count,
    'failure_count', v_failure_count,
    'has_failures', v_failure_count > 0,
    'results', COALESCE((SELECT JSONB_AGG(result_rows.result_json ORDER BY result_rows.ordinal ASC) FROM pg_temp.timesheet_authorise_bulk_results AS result_rows), '[]'::jsonb),
    'row_patches', COALESCE((SELECT JSONB_AGG(result_rows.result_json->'row_patch' ORDER BY result_rows.ordinal ASC) FROM pg_temp.timesheet_authorise_bulk_results AS result_rows WHERE result_rows.success = TRUE), '[]'::jsonb),
    'count_deltas', JSONB_BUILD_OBJECT('processed_eligible', -v_success_count, 'authorised_eligible', v_success_count, 'total', 0),
    'cache_invalidation_hints', JSONB_BUILD_OBJECT(
      'row_keys', COALESCE((SELECT JSONB_AGG(TO_JSONB(distinct_row_keys.row_key)) FROM (SELECT DISTINCT cache_key_values.cache_key AS row_key FROM pg_temp.timesheet_authorise_bulk_results AS result_rows CROSS JOIN LATERAL JSONB_ARRAY_ELEMENTS_TEXT(COALESCE(result_rows.result_json->'cache_invalidation_hints'->'row_keys', '[]'::jsonb)) AS cache_key_values(cache_key) WHERE result_rows.success = TRUE AND NULLIF(BTRIM(COALESCE(cache_key_values.cache_key, '')), '') IS NOT NULL) AS distinct_row_keys), '[]'::jsonb),
      'timesheet_ids', COALESCE((SELECT JSONB_AGG(TO_JSONB(distinct_timesheet_ids.timesheet_id_text)) FROM (SELECT DISTINCT cache_timesheet_values.timesheet_id_text FROM pg_temp.timesheet_authorise_bulk_results AS result_rows CROSS JOIN LATERAL JSONB_ARRAY_ELEMENTS_TEXT(COALESCE(result_rows.result_json->'cache_invalidation_hints'->'timesheet_ids', '[]'::jsonb)) AS cache_timesheet_values(timesheet_id_text) WHERE result_rows.success = TRUE AND NULLIF(BTRIM(COALESCE(cache_timesheet_values.timesheet_id_text, '')), '') IS NOT NULL) AS distinct_timesheet_ids), '[]'::jsonb),
      'storage_keys', COALESCE((SELECT JSONB_AGG(TO_JSONB(distinct_storage_keys.storage_key)) FROM (SELECT DISTINCT cache_storage_values.storage_key FROM pg_temp.timesheet_authorise_bulk_results AS result_rows CROSS JOIN LATERAL JSONB_ARRAY_ELEMENTS_TEXT(COALESCE(result_rows.result_json->'cache_invalidation_hints'->'storage_keys', '[]'::jsonb)) AS cache_storage_values(storage_key) WHERE result_rows.success = TRUE AND NULLIF(BTRIM(COALESCE(cache_storage_values.storage_key, '')), '') IS NOT NULL) AS distinct_storage_keys), '[]'::jsonb),
      'datasets', JSONB_BUILD_ARRAY('bulk_authorise')
    )
  ) INTO v_out;

  RETURN COALESCE(v_out, JSONB_BUILD_OBJECT('ok', TRUE, 'batch_completed', TRUE, 'all_success', TRUE, 'action', 'AUTHORISE', 'requested_count', 0, 'success_count', 0, 'failure_count', 0, 'has_failures', FALSE, 'results', '[]'::jsonb, 'row_patches', '[]'::jsonb, 'count_deltas', JSONB_BUILD_OBJECT('processed_eligible', 0, 'authorised_eligible', 0, 'total', 0), 'cache_invalidation_hints', JSONB_BUILD_OBJECT('row_keys', '[]'::jsonb, 'timesheet_ids', '[]'::jsonb, 'storage_keys', '[]'::jsonb, 'datasets', JSONB_BUILD_ARRAY('bulk_authorise'))));
END;
$function$;






CREATE OR REPLACE FUNCTION public.timesheet_unauthorise_bulk_atomic(p_items jsonb DEFAULT '[]'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 VOLATILE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamp with time zone := COALESCE(p_now_utc, now());
  v_items_array jsonb := '[]'::jsonb;
  v_uuid_re text := '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
  v_success_count integer := 0;
  v_failure_count integer := 0;
  v_out jsonb;
BEGIN
  IF p_actor_user_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT(
      'ok', FALSE,
      'batch_completed', FALSE,
      'all_success', FALSE,
      'action', 'UNAUTHORISE',
      'error_code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'timesheet_unauthorise_bulk_atomic requires p_actor_user_id.',
      'requested_count', 0,
      'success_count', 0,
      'failure_count', 0,
      'results', '[]'::jsonb,
      'row_patches', '[]'::jsonb,
      'count_deltas', JSONB_BUILD_OBJECT('processed_eligible', 0, 'authorised_eligible', 0, 'total', 0),
      'cache_invalidation_hints', JSONB_BUILD_OBJECT('row_keys', '[]'::jsonb, 'timesheet_ids', '[]'::jsonb, 'storage_keys', '[]'::jsonb, 'datasets', JSONB_BUILD_ARRAY('bulk_authorise'))
    );
  END IF;

  IF p_items IS NOT NULL AND JSONB_TYPEOF(p_items) NOT IN ('array', 'object') THEN
    RETURN JSONB_BUILD_OBJECT(
      'ok', FALSE,
      'batch_completed', FALSE,
      'all_success', FALSE,
      'action', 'UNAUTHORISE',
      'error_code', 'ITEMS_JSON_MUST_BE_ARRAY_OR_OBJECT',
      'message', 'p_items must be a JSON array or an object containing items/rows/selected/selections.',
      'requested_count', 0,
      'success_count', 0,
      'failure_count', 0,
      'results', '[]'::jsonb,
      'row_patches', '[]'::jsonb,
      'count_deltas', JSONB_BUILD_OBJECT('processed_eligible', 0, 'authorised_eligible', 0, 'total', 0),
      'cache_invalidation_hints', JSONB_BUILD_OBJECT('row_keys', '[]'::jsonb, 'timesheet_ids', '[]'::jsonb, 'storage_keys', '[]'::jsonb, 'datasets', JSONB_BUILD_ARRAY('bulk_authorise'))
    );
  END IF;

  v_items_array := CASE
    WHEN p_items IS NULL THEN '[]'::jsonb
    WHEN JSONB_TYPEOF(p_items) = 'array' THEN p_items
    WHEN JSONB_TYPEOF(p_items) = 'object' AND JSONB_TYPEOF(p_items->'items') = 'array' THEN p_items->'items'
    WHEN JSONB_TYPEOF(p_items) = 'object' AND JSONB_TYPEOF(p_items->'rows') = 'array' THEN p_items->'rows'
    WHEN JSONB_TYPEOF(p_items) = 'object' AND JSONB_TYPEOF(p_items->'selected') = 'array' THEN p_items->'selected'
    WHEN JSONB_TYPEOF(p_items) = 'object' AND JSONB_TYPEOF(p_items->'selections') = 'array' THEN p_items->'selections'
    WHEN JSONB_TYPEOF(p_items) = 'object' THEN JSONB_BUILD_ARRAY(p_items)
    ELSE '[]'::jsonb
  END;

  DROP TABLE IF EXISTS pg_temp.timesheet_unauthorise_bulk_items;
  DROP TABLE IF EXISTS pg_temp.timesheet_unauthorise_bulk_state;
  DROP TABLE IF EXISTS pg_temp.timesheet_unauthorise_bulk_decisions;
  DROP TABLE IF EXISTS pg_temp.timesheet_unauthorise_bulk_work;
  DROP TABLE IF EXISTS pg_temp.timesheet_unauthorise_bulk_updated_ts;
  DROP TABLE IF EXISTS pg_temp.timesheet_unauthorise_bulk_updated_tf;
  DROP TABLE IF EXISTS pg_temp.timesheet_unauthorise_bulk_updated_cw;
  DROP TABLE IF EXISTS pg_temp.timesheet_unauthorise_bulk_post_decisions;
  DROP TABLE IF EXISTS pg_temp.timesheet_unauthorise_bulk_results;

  CREATE TEMP TABLE timesheet_unauthorise_bulk_items ON COMMIT DROP AS
  SELECT
    input_values.ordinality::integer AS ordinal,
    CASE WHEN JSONB_TYPEOF(input_values.item_json) = 'object' THEN input_values.item_json ELSE JSONB_BUILD_OBJECT('value', input_values.item_json) END AS item_json,
    NULLIF(BTRIM(COALESCE(input_values.item_json->>'row_key', input_values.item_json->>'rowKey', '')), '') AS row_key,
    NULLIF(BTRIM(COALESCE(input_values.item_json->>'timesheet_id', input_values.item_json->>'timesheetId', input_values.item_json->>'current_timesheet_id', input_values.item_json->>'currentTimesheetId', input_values.item_json->>'requested_timesheet_id', input_values.item_json->>'requestedTimesheetId', '')), '') AS timesheet_id_text,
    NULLIF(BTRIM(COALESCE(input_values.item_json->>'expected_timesheet_id', input_values.item_json->>'expectedTimesheetId', input_values.item_json->>'expected_current_timesheet_id', input_values.item_json->>'expectedCurrentTimesheetId', '')), '') AS expected_timesheet_id_text,
    NULLIF(BTRIM(COALESCE(input_values.item_json->>'row_signature', input_values.item_json->>'rowSignature', input_values.item_json->>'expected_row_signature', input_values.item_json->>'expectedRowSignature', '')), '') AS expected_row_signature
  FROM JSONB_ARRAY_ELEMENTS(v_items_array) WITH ORDINALITY AS input_values(item_json, ordinality);

  CREATE TEMP TABLE timesheet_unauthorise_bulk_state ON COMMIT DROP AS
  SELECT
    item_rows.ordinal,
    item_rows.item_json,
    item_rows.row_key,
    CASE
      WHEN item_rows.timesheet_id_text ~* v_uuid_re THEN item_rows.timesheet_id_text::uuid
      WHEN item_rows.row_key LIKE 'timesheet:%' AND SUBSTRING(item_rows.row_key FROM 11) ~* v_uuid_re THEN SUBSTRING(item_rows.row_key FROM 11)::uuid
      ELSE NULL::uuid
    END AS requested_timesheet_id,
    CASE WHEN item_rows.expected_timesheet_id_text ~* v_uuid_re THEN item_rows.expected_timesheet_id_text::uuid ELSE NULL::uuid END AS expected_timesheet_id,
    item_rows.expected_row_signature AS expected_row_signature,
    requested_ts.timesheet_id AS db_requested_timesheet_id,
    requested_ts.booking_id AS requested_booking_id,
    requested_ts.version AS requested_version,
    requested_ts.is_current AS requested_is_current,
    current_ts.timesheet_id AS current_timesheet_id,
    current_ts.booking_id AS current_booking_id,
    current_ts.version AS current_version,
    current_ts.is_current AS current_is_current,
    current_ts.authorised_at_server AS current_authorised_at_server,
    current_ts.sheet_scope AS current_sheet_scope,
    current_ts.submission_mode AS current_submission_mode,
    current_tf.id AS tsfin_id,
    current_tf.processing_status AS tsfin_processing_status,
    current_tf.basis AS tsfin_basis,
    current_tf.locked_by_invoice_id AS tsfin_locked_by_invoice_id,
    current_tf.paid_at_utc AS tsfin_paid_at_utc,
    current_tf.invoice_breakdown_json AS tsfin_invoice_breakdown_json,
    COALESCE(segment_state.has_segment_invoice_lock, FALSE) AS has_segment_invoice_lock,
    contract_week_target.contract_week_id AS contract_week_id_for_update
  FROM pg_temp.timesheet_unauthorise_bulk_items AS item_rows
  LEFT JOIN LATERAL (
    SELECT ts_req.timesheet_id, ts_req.booking_id, ts_req.version, ts_req.is_current
    FROM public.timesheets AS ts_req
    WHERE ts_req.timesheet_id = CASE
      WHEN item_rows.timesheet_id_text ~* v_uuid_re THEN item_rows.timesheet_id_text::uuid
      WHEN item_rows.row_key LIKE 'timesheet:%' AND SUBSTRING(item_rows.row_key FROM 11) ~* v_uuid_re THEN SUBSTRING(item_rows.row_key FROM 11)::uuid
      ELSE NULL::uuid
    END
    ORDER BY ts_req.version DESC NULLS LAST, ts_req.updated_at DESC NULLS LAST, ts_req.created_at DESC NULLS LAST, ts_req.timesheet_id DESC
    LIMIT 1
    FOR UPDATE
  ) AS requested_ts ON TRUE
  LEFT JOIN LATERAL (
    SELECT ts_cur.timesheet_id, ts_cur.booking_id, ts_cur.version, ts_cur.is_current, ts_cur.authorised_at_server, ts_cur.sheet_scope, ts_cur.submission_mode
    FROM public.timesheets AS ts_cur
    WHERE requested_ts.booking_id IS NOT NULL
      AND ts_cur.booking_id = requested_ts.booking_id
    ORDER BY CASE WHEN COALESCE(ts_cur.is_current, FALSE) = TRUE THEN 0 ELSE 1 END ASC,
             ts_cur.version DESC NULLS LAST,
             ts_cur.updated_at DESC NULLS LAST,
             ts_cur.created_at DESC NULLS LAST,
             ts_cur.timesheet_id DESC
    LIMIT 1
    FOR UPDATE
  ) AS current_ts ON TRUE
  LEFT JOIN LATERAL (
    SELECT tf_sel.id, tf_sel.processing_status, tf_sel.basis, tf_sel.locked_by_invoice_id, tf_sel.paid_at_utc, tf_sel.invoice_breakdown_json
    FROM public.timesheets_financials AS tf_sel
    WHERE tf_sel.timesheet_id = current_ts.timesheet_id
      AND tf_sel.is_current = TRUE
    ORDER BY tf_sel.computed_at_utc DESC NULLS LAST, tf_sel.created_at DESC NULLS LAST, tf_sel.updated_at DESC NULLS LAST, tf_sel.id DESC
    LIMIT 1
    FOR UPDATE
  ) AS current_tf ON TRUE
  LEFT JOIN LATERAL (
    SELECT EXISTS (
      SELECT 1
      FROM JSONB_ARRAY_ELEMENTS(
        CASE
          WHEN current_tf.invoice_breakdown_json IS NULL THEN '[]'::jsonb
          WHEN JSONB_TYPEOF(current_tf.invoice_breakdown_json) = 'array' THEN current_tf.invoice_breakdown_json
          WHEN JSONB_TYPEOF(current_tf.invoice_breakdown_json) = 'object' AND JSONB_TYPEOF(current_tf.invoice_breakdown_json->'segments') = 'array' THEN current_tf.invoice_breakdown_json->'segments'
          ELSE '[]'::jsonb
        END
      ) AS invoice_segment(segment_json)
      WHERE NULLIF(BTRIM(COALESCE(invoice_segment.segment_json->>'invoice_locked_invoice_id', '')), '') IS NOT NULL
    ) AS has_segment_invoice_lock
  ) AS segment_state ON TRUE
  LEFT JOIN LATERAL (
    SELECT cw_match.id AS contract_week_id
    FROM public.contract_weeks AS cw_match
    WHERE current_ts.timesheet_id IS NOT NULL
      AND current_ts.sheet_scope = 'WEEKLY'::public.timesheet_scope_enum
      AND (
        cw_match.timesheet_id = current_ts.timesheet_id
        OR EXISTS (
          SELECT 1
          FROM public.timesheets AS cw_timesheet
          WHERE cw_timesheet.timesheet_id = cw_match.timesheet_id
            AND cw_timesheet.booking_id = current_ts.booking_id
        )
      )
    ORDER BY
      CASE WHEN cw_match.timesheet_id = current_ts.timesheet_id THEN 0 ELSE 1 END ASC,
      cw_match.updated_at DESC NULLS LAST,
      cw_match.id DESC
    LIMIT 1
    FOR UPDATE OF cw_match
  ) AS contract_week_target ON TRUE;

  CREATE TEMP TABLE timesheet_unauthorise_bulk_decisions ON COMMIT DROP AS
  SELECT decision_result.row_json
  FROM (
    SELECT decision_ids.timesheet_ids_json
    FROM (
      SELECT COALESCE(JSONB_AGG(DISTINCT TO_JSONB(state_rows.current_timesheet_id::text)) FILTER (WHERE state_rows.current_timesheet_id IS NOT NULL), '[]'::jsonb) AS timesheet_ids_json
      FROM pg_temp.timesheet_unauthorise_bulk_state AS state_rows
    ) AS decision_ids
    WHERE JSONB_ARRAY_LENGTH(decision_ids.timesheet_ids_json) > 0
  ) AS decision_filter
  CROSS JOIN LATERAL public.bulk_timesheet_row_patch_v1(JSONB_BUILD_OBJECT('timesheet_ids', decision_filter.timesheet_ids_json, 'dataset_mode', 'authorise', 'projection', 'status_patch', 'changed_domains', JSONB_BUILD_ARRAY('unauthorise'))) AS decision_result(row_json);

  CREATE TEMP TABLE timesheet_unauthorise_bulk_work ON COMMIT DROP AS
  SELECT
    state_rows.ordinal,
    state_rows.item_json,
    state_rows.row_key,
    state_rows.requested_timesheet_id,
    state_rows.expected_timesheet_id,
    state_rows.expected_row_signature,
    state_rows.db_requested_timesheet_id,
    state_rows.requested_booking_id,
    state_rows.requested_version,
    state_rows.requested_is_current,
    state_rows.current_timesheet_id,
    state_rows.current_booking_id,
    state_rows.current_version,
    state_rows.current_is_current,
    state_rows.current_authorised_at_server,
    state_rows.current_sheet_scope,
    state_rows.current_submission_mode,
    state_rows.tsfin_id,
    state_rows.tsfin_processing_status,
    state_rows.tsfin_basis,
    state_rows.tsfin_locked_by_invoice_id,
    state_rows.tsfin_paid_at_utc,
    state_rows.has_segment_invoice_lock,
    state_rows.contract_week_id_for_update,
    decision_rows.row_json AS pre_row_json,
    COALESCE((decision_rows.row_json->>'can_bulk_unauthorise')::boolean, FALSE) AS eligible_flag,
    CASE
      WHEN state_rows.requested_timesheet_id IS NULL THEN 'TIMESHEET_ID_REQUIRED'
      WHEN state_rows.expected_timesheet_id IS NULL THEN 'EXPECTED_TIMESHEET_ID_REQUIRED'
      WHEN state_rows.db_requested_timesheet_id IS NULL THEN 'TIMESHEET_NOT_FOUND'
      WHEN state_rows.current_timesheet_id IS NULL THEN 'CURRENT_TIMESHEET_NOT_FOUND'
      WHEN state_rows.current_is_current IS DISTINCT FROM TRUE THEN 'CURRENT_TIMESHEET_NOT_FOUND'
      WHEN state_rows.expected_timesheet_id IS DISTINCT FROM state_rows.current_timesheet_id THEN 'TIMESHEET_MOVED'
      WHEN state_rows.tsfin_id IS NULL THEN 'NO_TSFIN'
      WHEN decision_rows.row_json IS NULL THEN 'DECISION_ROW_NOT_FOUND'
      WHEN state_rows.expected_row_signature IS NOT NULL AND NULLIF(BTRIM(COALESCE(decision_rows.row_json->>'row_signature', '')), '') IS DISTINCT FROM state_rows.expected_row_signature THEN 'ROW_SIGNATURE_MISMATCH'
      WHEN state_rows.current_sheet_scope = 'WEEKLY'::public.timesheet_scope_enum AND state_rows.contract_week_id_for_update IS NULL THEN 'CONTRACT_WEEK_NOT_FOUND_FOR_WEEKLY_TIMESHEET'
      WHEN state_rows.tsfin_locked_by_invoice_id IS NOT NULL OR state_rows.tsfin_paid_at_utc IS NOT NULL OR state_rows.has_segment_invoice_lock = TRUE OR COALESCE((decision_rows.row_json->>'locked')::boolean, FALSE) = TRUE THEN 'TIMESHEET_LOCKED_OR_PAID'
      WHEN COALESCE((decision_rows.row_json->>'is_authorised')::boolean, FALSE) = FALSE THEN 'NOT_AUTHORISED'
      WHEN COALESCE((decision_rows.row_json->>'can_bulk_unauthorise')::boolean, FALSE) = FALSE THEN 'UNAUTHORISE_NOT_ALLOWED'
      ELSE NULL::text
    END AS failure_code,
    'PENDING_AUTH'::public.ts_fin_processing_status_enum AS new_processing_status
  FROM pg_temp.timesheet_unauthorise_bulk_state AS state_rows
  LEFT JOIN pg_temp.timesheet_unauthorise_bulk_decisions AS decision_rows
    ON CASE WHEN COALESCE(decision_rows.row_json->>'timesheet_id', '') ~* v_uuid_re THEN (decision_rows.row_json->>'timesheet_id')::uuid ELSE NULL::uuid END = state_rows.current_timesheet_id;

  CREATE TEMP TABLE timesheet_unauthorise_bulk_updated_ts ON COMMIT DROP AS
  WITH updated_rows AS (
    UPDATE public.timesheets AS ts_upd
    SET authorised_at_server = NULL,
        updated_at = v_now
    FROM pg_temp.timesheet_unauthorise_bulk_work AS work_rows
    WHERE work_rows.failure_code IS NULL
      AND ts_upd.timesheet_id = work_rows.current_timesheet_id
      AND ts_upd.is_current = TRUE
    RETURNING ts_upd.timesheet_id, ts_upd.version, ts_upd.updated_at
  )
  SELECT updated_rows.timesheet_id, updated_rows.version, updated_rows.updated_at
  FROM updated_rows;

  CREATE TEMP TABLE timesheet_unauthorise_bulk_updated_tf ON COMMIT DROP AS
  WITH updated_rows AS (
    UPDATE public.timesheets_financials AS tf_upd
    SET processing_status = work_rows.new_processing_status,
        authorised_by_user_id = NULL,
        authorised_at_utc = NULL,
        updated_at = v_now
    FROM pg_temp.timesheet_unauthorise_bulk_work AS work_rows
    JOIN pg_temp.timesheet_unauthorise_bulk_updated_ts AS updated_ts
      ON updated_ts.timesheet_id = work_rows.current_timesheet_id
    WHERE work_rows.failure_code IS NULL
      AND tf_upd.id = work_rows.tsfin_id
      AND tf_upd.is_current = TRUE
    RETURNING tf_upd.timesheet_id, tf_upd.processing_status, tf_upd.updated_at
  )
  SELECT updated_rows.timesheet_id, updated_rows.processing_status, updated_rows.updated_at
  FROM updated_rows;

  CREATE TEMP TABLE timesheet_unauthorise_bulk_updated_cw ON COMMIT DROP AS
  WITH updated_rows AS (
    UPDATE public.contract_weeks AS cw_upd
    SET timesheet_id = work_rows.current_timesheet_id,
        status = 'SUBMITTED'::public.contract_week_status_enum,
        updated_at = v_now
    FROM pg_temp.timesheet_unauthorise_bulk_work AS work_rows
    JOIN pg_temp.timesheet_unauthorise_bulk_updated_tf AS updated_tf
      ON updated_tf.timesheet_id = work_rows.current_timesheet_id
    WHERE work_rows.failure_code IS NULL
      AND work_rows.current_sheet_scope = 'WEEKLY'::public.timesheet_scope_enum
      AND cw_upd.id = work_rows.contract_week_id_for_update
    RETURNING cw_upd.id, cw_upd.timesheet_id, cw_upd.status, cw_upd.updated_at
  )
  SELECT updated_rows.id, updated_rows.timesheet_id, updated_rows.status, updated_rows.updated_at
  FROM updated_rows;


  CREATE TEMP TABLE timesheet_unauthorise_bulk_post_decisions ON COMMIT DROP AS
  SELECT post_decision_result.row_json
  FROM (
    SELECT post_ids.timesheet_ids_json
    FROM (
      SELECT COALESCE(JSONB_AGG(DISTINCT TO_JSONB(updated_tf.timesheet_id::text)) FILTER (WHERE updated_tf.timesheet_id IS NOT NULL), '[]'::jsonb) AS timesheet_ids_json
      FROM pg_temp.timesheet_unauthorise_bulk_updated_tf AS updated_tf
    ) AS post_ids
    WHERE JSONB_ARRAY_LENGTH(post_ids.timesheet_ids_json) > 0
  ) AS post_filter
  CROSS JOIN LATERAL public.bulk_timesheet_row_patch_v1(JSONB_BUILD_OBJECT('timesheet_ids', post_filter.timesheet_ids_json, 'dataset_mode', 'authorise', 'projection', 'status_patch', 'changed_domains', JSONB_BUILD_ARRAY('unauthorise'))) AS post_decision_result(row_json);



  PERFORM public._audit_insert(
    'timesheet',
    audit_work.current_timesheet_id::text,
    'TIMESHEET_BULK_UNAUTHORISED',
    JSONB_BUILD_OBJECT(
      'row', COALESCE(audit_work.pre_row_json, JSONB_BUILD_OBJECT()),
      'processing_status', audit_work.tsfin_processing_status,
      'authorised_at_server', audit_work.current_authorised_at_server,
      'row_signature', audit_work.pre_row_json->>'row_signature'
    ),
    JSONB_BUILD_OBJECT(
      'row', COALESCE(audit_post.row_json, JSONB_BUILD_OBJECT()),
      'processing_status', audit_updated.processing_status,
      'authorised_at_server', CASE WHEN 'UNAUTHORISE' = 'AUTHORISE' THEN v_now ELSE NULL::timestamp with time zone END,
      'row_signature', audit_post.row_json->>'row_signature'
    ),
    'BULK_UNAUTHORISE',
    p_actor_user_id
  )
  FROM pg_temp.timesheet_unauthorise_bulk_work AS audit_work
  JOIN pg_temp.timesheet_unauthorise_bulk_updated_tf AS audit_updated
    ON audit_updated.timesheet_id = audit_work.current_timesheet_id
  LEFT JOIN pg_temp.timesheet_unauthorise_bulk_post_decisions AS audit_post
    ON CASE WHEN COALESCE(audit_post.row_json->>'timesheet_id', '') ~* v_uuid_re THEN (audit_post.row_json->>'timesheet_id')::uuid ELSE NULL::uuid END = audit_work.current_timesheet_id
  WHERE audit_work.failure_code IS NULL;

  CREATE TEMP TABLE timesheet_unauthorise_bulk_results ON COMMIT DROP AS
  SELECT
    work_rows.ordinal,
    CASE WHEN work_rows.failure_code IS NULL AND updated_tf.timesheet_id IS NOT NULL THEN TRUE ELSE FALSE END AS success,
    JSONB_BUILD_OBJECT(
      'item_index', work_rows.ordinal,
      'success', CASE WHEN work_rows.failure_code IS NULL AND updated_tf.timesheet_id IS NOT NULL THEN TRUE ELSE FALSE END,
      'action', 'UNAUTHORISE',
      'error_code', CASE WHEN work_rows.failure_code IS NULL AND updated_tf.timesheet_id IS NOT NULL THEN NULL::text ELSE COALESCE(work_rows.failure_code, 'MUTATION_UPDATE_FAILED') END,
      'message', CASE
        WHEN work_rows.failure_code IS NULL AND updated_tf.timesheet_id IS NOT NULL THEN NULL::text
        WHEN COALESCE(work_rows.failure_code, 'MUTATION_UPDATE_FAILED') = 'TIMESHEET_MOVED' THEN 'Timesheet has moved to a different current row.'
        WHEN COALESCE(work_rows.failure_code, 'MUTATION_UPDATE_FAILED') = 'TIMESHEET_LOCKED_OR_PAID' THEN 'Timesheet is locked, invoice-locked, or paid.'
        WHEN COALESCE(work_rows.failure_code, 'MUTATION_UPDATE_FAILED') = 'ROW_SIGNATURE_MISMATCH' THEN 'Timesheet changed after it was loaded. Refresh the row and try again.'
        WHEN COALESCE(work_rows.failure_code, 'MUTATION_UPDATE_FAILED') = 'NOT_AUTHORISED' THEN 'Timesheet is not currently authorised.'
        WHEN COALESCE(work_rows.failure_code, 'MUTATION_UPDATE_FAILED') = 'UNAUTHORISE_NOT_ALLOWED' THEN 'Timesheet is not eligible for bulk unauthorisation.'
        WHEN COALESCE(work_rows.failure_code, 'MUTATION_UPDATE_FAILED') = 'CONTRACT_WEEK_NOT_FOUND_FOR_WEEKLY_TIMESHEET' THEN 'Contract week was not found for this weekly timesheet.'
        ELSE COALESCE(work_rows.failure_code, 'MUTATION_UPDATE_FAILED')
      END,
      'requested_timesheet_id', work_rows.requested_timesheet_id,
      'expected_timesheet_id', work_rows.expected_timesheet_id,
      'expected_row_signature', work_rows.expected_row_signature,
      'current_row_signature', work_rows.pre_row_json->>'row_signature',
      'current_timesheet_id', work_rows.current_timesheet_id,
      'current_version', COALESCE(updated_ts.version, work_rows.current_version),
      'was_stale', work_rows.requested_timesheet_id IS DISTINCT FROM work_rows.current_timesheet_id,
      'processing_status_before', work_rows.tsfin_processing_status,
      'processing_status_after', updated_tf.processing_status,
      'row_key_before', COALESCE(work_rows.row_key, work_rows.pre_row_json->>'row_key'),
      'row_key_after', COALESCE(post_rows.row_json->>'row_key', work_rows.pre_row_json->>'row_key'),
      'row', CASE WHEN work_rows.failure_code IS NULL AND updated_tf.timesheet_id IS NOT NULL THEN COALESCE(post_rows.row_json, JSONB_BUILD_OBJECT()) ELSE COALESCE(work_rows.pre_row_json, JSONB_BUILD_OBJECT()) END,
      'row_patch', CASE WHEN work_rows.failure_code IS NULL AND updated_tf.timesheet_id IS NOT NULL THEN COALESCE(post_rows.row_json->'row_patch', JSONB_BUILD_OBJECT()) ELSE JSONB_BUILD_OBJECT() END,
      'cache_invalidation_hints', CASE WHEN work_rows.failure_code IS NULL AND updated_tf.timesheet_id IS NOT NULL THEN JSONB_BUILD_OBJECT(
        'row_keys', JSONB_BUILD_ARRAY(COALESCE(work_rows.row_key, work_rows.pre_row_json->>'row_key'), post_rows.row_json->>'row_key'),
        'timesheet_ids', JSONB_BUILD_ARRAY(work_rows.requested_timesheet_id, work_rows.current_timesheet_id),
        'storage_keys', '[]'::jsonb,
        'row_signature', post_rows.row_json->>'row_signature',
        'status_only', TRUE,
        'invalidate_context', FALSE,
        'invalidate_row_context', FALSE,
        'invalidate_preview', FALSE,
        'invalidate_evidence', FALSE
      ) ELSE JSONB_BUILD_OBJECT() END
    ) AS result_json
  FROM pg_temp.timesheet_unauthorise_bulk_work AS work_rows
  LEFT JOIN pg_temp.timesheet_unauthorise_bulk_updated_ts AS updated_ts ON updated_ts.timesheet_id = work_rows.current_timesheet_id
  LEFT JOIN pg_temp.timesheet_unauthorise_bulk_updated_tf AS updated_tf ON updated_tf.timesheet_id = work_rows.current_timesheet_id
  LEFT JOIN pg_temp.timesheet_unauthorise_bulk_post_decisions AS post_rows ON CASE WHEN COALESCE(post_rows.row_json->>'timesheet_id', '') ~* v_uuid_re THEN (post_rows.row_json->>'timesheet_id')::uuid ELSE NULL::uuid END = work_rows.current_timesheet_id;

  SELECT
    COUNT(result_rows.result_json) FILTER (WHERE result_rows.success = TRUE)::integer,
    COUNT(result_rows.result_json) FILTER (WHERE result_rows.success = FALSE)::integer
  INTO v_success_count, v_failure_count
  FROM pg_temp.timesheet_unauthorise_bulk_results AS result_rows;

  SELECT JSONB_BUILD_OBJECT(
    'ok', TRUE,
    'batch_completed', TRUE,
    'all_success', v_failure_count = 0,
    'action', 'UNAUTHORISE',
    'requested_count', JSONB_ARRAY_LENGTH(v_items_array),
    'success_count', v_success_count,
    'failure_count', v_failure_count,
    'has_failures', v_failure_count > 0,
    'results', COALESCE((SELECT JSONB_AGG(result_rows.result_json ORDER BY result_rows.ordinal ASC) FROM pg_temp.timesheet_unauthorise_bulk_results AS result_rows), '[]'::jsonb),
    'row_patches', COALESCE((SELECT JSONB_AGG(result_rows.result_json->'row_patch' ORDER BY result_rows.ordinal ASC) FROM pg_temp.timesheet_unauthorise_bulk_results AS result_rows WHERE result_rows.success = TRUE), '[]'::jsonb),
    'count_deltas', JSONB_BUILD_OBJECT('processed_eligible', v_success_count, 'authorised_eligible', -v_success_count, 'total', 0),
    'cache_invalidation_hints', JSONB_BUILD_OBJECT(
      'row_keys', COALESCE((SELECT JSONB_AGG(TO_JSONB(distinct_row_keys.row_key)) FROM (SELECT DISTINCT cache_key_values.cache_key AS row_key FROM pg_temp.timesheet_unauthorise_bulk_results AS result_rows CROSS JOIN LATERAL JSONB_ARRAY_ELEMENTS_TEXT(COALESCE(result_rows.result_json->'cache_invalidation_hints'->'row_keys', '[]'::jsonb)) AS cache_key_values(cache_key) WHERE result_rows.success = TRUE AND NULLIF(BTRIM(COALESCE(cache_key_values.cache_key, '')), '') IS NOT NULL) AS distinct_row_keys), '[]'::jsonb),
      'timesheet_ids', COALESCE((SELECT JSONB_AGG(TO_JSONB(distinct_timesheet_ids.timesheet_id_text)) FROM (SELECT DISTINCT cache_timesheet_values.timesheet_id_text FROM pg_temp.timesheet_unauthorise_bulk_results AS result_rows CROSS JOIN LATERAL JSONB_ARRAY_ELEMENTS_TEXT(COALESCE(result_rows.result_json->'cache_invalidation_hints'->'timesheet_ids', '[]'::jsonb)) AS cache_timesheet_values(timesheet_id_text) WHERE result_rows.success = TRUE AND NULLIF(BTRIM(COALESCE(cache_timesheet_values.timesheet_id_text, '')), '') IS NOT NULL) AS distinct_timesheet_ids), '[]'::jsonb),
      'storage_keys', COALESCE((SELECT JSONB_AGG(TO_JSONB(distinct_storage_keys.storage_key)) FROM (SELECT DISTINCT cache_storage_values.storage_key FROM pg_temp.timesheet_unauthorise_bulk_results AS result_rows CROSS JOIN LATERAL JSONB_ARRAY_ELEMENTS_TEXT(COALESCE(result_rows.result_json->'cache_invalidation_hints'->'storage_keys', '[]'::jsonb)) AS cache_storage_values(storage_key) WHERE result_rows.success = TRUE AND NULLIF(BTRIM(COALESCE(cache_storage_values.storage_key, '')), '') IS NOT NULL) AS distinct_storage_keys), '[]'::jsonb),
      'datasets', JSONB_BUILD_ARRAY('bulk_authorise')
    )
  ) INTO v_out;

  RETURN COALESCE(v_out, JSONB_BUILD_OBJECT('ok', TRUE, 'batch_completed', TRUE, 'all_success', TRUE, 'action', 'UNAUTHORISE', 'requested_count', 0, 'success_count', 0, 'failure_count', 0, 'has_failures', FALSE, 'results', '[]'::jsonb, 'row_patches', '[]'::jsonb, 'count_deltas', JSONB_BUILD_OBJECT('processed_eligible', 0, 'authorised_eligible', 0, 'total', 0), 'cache_invalidation_hints', JSONB_BUILD_OBJECT('row_keys', '[]'::jsonb, 'timesheet_ids', '[]'::jsonb, 'storage_keys', '[]'::jsonb, 'datasets', JSONB_BUILD_ARRAY('bulk_authorise'))));
END;
$function$;



DROP FUNCTION IF EXISTS public.timesheet_daily_manual_process_atomic(uuid, uuid, uuid, jsonb, jsonb, timestamp with time zone);
DROP FUNCTION IF EXISTS public.timesheet_daily_manual_process_atomic(uuid, uuid, uuid, jsonb, jsonb, timestamp with time zone, text);


CREATE OR REPLACE FUNCTION public.timesheet_daily_manual_process_atomic(p_timesheet_id uuid, p_expected_timesheet_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_timesheet_patch_json jsonb DEFAULT '{}'::jsonb, p_tsfin_patch_json jsonb DEFAULT '{}'::jsonb, p_now_utc timestamp with time zone DEFAULT now(), p_expected_row_signature text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 VOLATILE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamp with time zone := COALESCE(p_now_utc, now());
  v_requested_booking_id text := NULL;
  v_requested_timesheet_id uuid := NULL;
  v_current_timesheet_id uuid := NULL;
  v_current_version integer := NULL;
  v_was_stale boolean := FALSE;
  v_sheet_scope text := NULL;
  v_submission_mode text := NULL;
  v_authorised_at_server timestamp with time zone := NULL;
  v_tsfin_id uuid := NULL;
  v_previous_status public.ts_fin_processing_status_enum := NULL;
  v_new_status public.ts_fin_processing_status_enum := 'PENDING_AUTH'::public.ts_fin_processing_status_enum;
  v_locked_by_invoice_id uuid := NULL;
  v_paid_at_utc timestamp with time zone := NULL;
  v_invoice_breakdown_json jsonb := NULL;
  v_has_segment_invoice_lock boolean := FALSE;
  v_effective_candidate_id uuid := NULL;
  v_effective_client_id uuid := NULL;
  v_effective_pay_method text := NULL;
  v_effective_candidate_assignment text := NULL;
  v_effective_has_rate_issue boolean := FALSE;
  v_effective_has_pay_channel_issue boolean := FALSE;
  v_timesheet_patch jsonb := COALESCE(p_timesheet_patch_json, '{}'::jsonb);
  v_tsfin_patch jsonb := COALESCE(p_tsfin_patch_json, '{}'::jsonb);
  v_timesheet_json jsonb := NULL;
  v_tsfin_json jsonb := NULL;
  v_authoritative_tsfin_json jsonb := NULL;
  v_pre_row jsonb := NULL;
  v_post_row jsonb := NULL;
  v_expected_row_signature text := NULL;
  v_patch_key text := NULL;
  v_supplied_text text := NULL;
  v_authoritative_text text := NULL;
  v_supplied_numeric numeric := NULL;
  v_authoritative_numeric numeric := NULL;
  v_numeric_patch_keys text[] := ARRAY[
    'hours_day', 'hours_night', 'hours_sat', 'hours_sun', 'hours_bh',
    'pay_day', 'pay_night', 'pay_sat', 'pay_sun', 'pay_bh',
    'charge_day', 'charge_night', 'charge_sat', 'charge_sun', 'charge_bh',
    'total_hours', 'total_pay_ex_vat', 'total_charge_ex_vat', 'margin_ex_vat',
    'expenses_pay_ex_vat', 'expenses_charge_ex_vat',
    'mileage_units', 'mileage_pay_rate', 'mileage_charge_rate', 'mileage_pay_ex_vat', 'mileage_charge_ex_vat',
    'travel_pay_ex_vat', 'travel_charge_ex_vat',
    'accommodation_pay_ex_vat', 'accommodation_charge_ex_vat',
    'other_pay_ex_vat', 'other_charge_ex_vat',
    'additional_pay_ex_vat', 'additional_charge_ex_vat', 'additional_margin_ex_vat'
  ];
  v_forbidden_tsfin_patch_keys text[] := ARRAY[
    'candidate_id', 'client_id', 'pay_method', 'candidate_assignment', 'basis',
    'policy_snapshot_json', 'rate_source_refs_json',
    'normal_hours', 'unsocial_hours', 'saturday_hours', 'sunday_hours', 'bank_holiday_hours',
    'sleep_in_units', 'on_call_units', 'mileage_units', 'expenses_units',
    'total_hours', 'total_pay_ex_vat', 'total_charge_ex_vat', 'margin_ex_vat', 'net_delta_ex_vat',
    'normal_pay_rate', 'unsocial_pay_rate', 'saturday_pay_rate', 'sunday_pay_rate', 'bank_holiday_pay_rate',
    'normal_charge_rate', 'unsocial_charge_rate', 'saturday_charge_rate', 'sunday_charge_rate', 'bank_holiday_charge_rate',
    'mileage_pay_rate', 'mileage_charge_rate', 'expenses_pay', 'expenses_charge',
    'has_rate_issue', 'has_pay_channel_issue',
    'hours_day', 'hours_night', 'hours_sat', 'hours_sun', 'hours_bh',
    'pay_day', 'pay_night', 'pay_sat', 'pay_sun', 'pay_bh',
    'charge_day', 'charge_night', 'charge_sat', 'charge_sun', 'charge_bh',
    'expenses_pay_ex_vat', 'expenses_charge_ex_vat',
    'mileage_pay_ex_vat', 'mileage_charge_ex_vat',
    'travel_pay_ex_vat', 'travel_charge_ex_vat',
    'accommodation_pay_ex_vat', 'accommodation_charge_ex_vat',
    'other_pay_ex_vat', 'other_charge_ex_vat',
    'additional_pay_ex_vat', 'additional_charge_ex_vat', 'additional_margin_ex_vat'
  ];
  v_financial_affecting_timesheet_patch_keys text[] := ARRAY[
    'worked_start_iso', 'worked_end_iso', 'break_start_iso', 'break_end_iso',
    'break_minutes', 'worked_minutes', 'actual_schedule_json',
    'additional_units_week', 'additional_units_per_day',
    'scheduled_start_iso', 'scheduled_end_iso', 'week_ending_date', 'worked_date', 'work_date'
  ];
BEGIN
  IF p_timesheet_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_ID_REQUIRED', 'message', 'p_timesheet_id is required.');
  END IF;

  IF p_expected_timesheet_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'EXPECTED_TIMESHEET_ID_REQUIRED', 'message', 'p_expected_timesheet_id is required.');
  END IF;

  IF p_actor_user_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'ACTOR_USER_ID_REQUIRED', 'message', 'p_actor_user_id is required.');
  END IF;

  IF jsonb_typeof(v_timesheet_patch) <> 'object' THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_PATCH_MUST_BE_OBJECT', 'message', 'p_timesheet_patch_json must be a JSON object.');
  END IF;

  IF jsonb_typeof(v_tsfin_patch) <> 'object' THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'TSFIN_PATCH_MUST_BE_OBJECT', 'message', 'p_tsfin_patch_json must be a JSON object.');
  END IF;

  FOREACH v_patch_key IN ARRAY v_forbidden_tsfin_patch_keys LOOP
    IF v_tsfin_patch ? v_patch_key THEN
      RETURN JSONB_BUILD_OBJECT(
        'ok', FALSE,
        'success', FALSE,
        'operation', 'daily_manual_process',
        'error_code', 'TSFIN_PATCH_FORBIDDEN_FIELD',
        'message', 'Cannot process: TSFIN patch contains an authoritative or financial field.',
        'field', v_patch_key,
        'timesheet_id', p_timesheet_id
      );
    END IF;
  END LOOP;

  FOREACH v_patch_key IN ARRAY v_financial_affecting_timesheet_patch_keys LOOP
    IF v_timesheet_patch ? v_patch_key THEN
      RETURN JSONB_BUILD_OBJECT(
        'ok', FALSE,
        'success', FALSE,
        'operation', 'daily_manual_process',
        'error_code', 'TIMESHEET_PATCH_REQUIRES_RECALCULATION',
        'message', 'Cannot process while changing worked time, schedule, break, work date, or additional units. Save and recalculate the row before processing.',
        'field', v_patch_key,
        'timesheet_id', p_timesheet_id
      );
    END IF;
  END LOOP;

  SELECT requested_ts.booking_id,
         requested_ts.timesheet_id
    INTO v_requested_booking_id,
         v_requested_timesheet_id
  FROM public.timesheets AS requested_ts
  WHERE requested_ts.timesheet_id = p_timesheet_id
  LIMIT 1;

  IF v_requested_timesheet_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_NOT_FOUND', 'message', 'Timesheet was not found.', 'requested_timesheet_id', p_timesheet_id);
  END IF;

  SELECT current_ts.timesheet_id,
         current_ts.version
    INTO v_current_timesheet_id,
         v_current_version
  FROM public.timesheets AS current_ts
  WHERE current_ts.booking_id = v_requested_booking_id
    AND current_ts.is_current = TRUE
  ORDER BY current_ts.version DESC NULLS LAST, current_ts.updated_at DESC NULLS LAST, current_ts.created_at DESC NULLS LAST, current_ts.timesheet_id DESC
  LIMIT 1;

  IF v_current_timesheet_id IS NULL THEN
    v_current_timesheet_id := v_requested_timesheet_id;
  END IF;

  v_was_stale := v_requested_timesheet_id IS DISTINCT FROM v_current_timesheet_id;

  IF p_expected_timesheet_id IS DISTINCT FROM v_current_timesheet_id THEN
    RETURN JSONB_BUILD_OBJECT(
      'ok', FALSE,
      'operation', 'daily_manual_process',
      'error_code', 'TIMESHEET_MOVED',
      'message', 'Timesheet has moved to a newer current row.',
      'requested_timesheet_id', p_timesheet_id,
      'expected_timesheet_id', p_expected_timesheet_id,
      'current_timesheet_id', v_current_timesheet_id,
      'was_stale', v_was_stale
    );
  END IF;

  SELECT current_ts.sheet_scope::text,
         current_ts.submission_mode::text,
         current_ts.authorised_at_server,
         current_ts.version
    INTO v_sheet_scope,
         v_submission_mode,
         v_authorised_at_server,
         v_current_version
  FROM public.timesheets AS current_ts
  WHERE current_ts.timesheet_id = v_current_timesheet_id
    AND current_ts.is_current = TRUE
  LIMIT 1
  FOR UPDATE;

  IF v_sheet_scope IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'CURRENT_TIMESHEET_NOT_FOUND', 'message', 'Current timesheet was not found.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  IF UPPER(COALESCE(v_sheet_scope, '')) <> 'DAILY' THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'NOT_DAILY', 'message', 'Timesheet is not DAILY; daily manual process only applies to DAILY sheets.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  IF UPPER(COALESCE(v_submission_mode, '')) <> 'MANUAL' THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'NOT_MANUAL', 'message', 'Timesheet must be MANUAL before processing.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  IF v_authorised_at_server IS NOT NULL THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_ALREADY_AUTHORISED', 'message', 'This timesheet is already authorised.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  SELECT tsfin_current.id,
         tsfin_current.processing_status,
         tsfin_current.locked_by_invoice_id,
         tsfin_current.paid_at_utc,
         tsfin_current.invoice_breakdown_json,
         tsfin_current.candidate_id,
         tsfin_current.client_id,
         tsfin_current.pay_method,
         tsfin_current.candidate_assignment::text,
         COALESCE(tsfin_current.has_rate_issue, FALSE),
         COALESCE(tsfin_current.has_pay_channel_issue, FALSE),
         TO_JSONB(tsfin_current)
    INTO v_tsfin_id,
         v_previous_status,
         v_locked_by_invoice_id,
         v_paid_at_utc,
         v_invoice_breakdown_json,
         v_effective_candidate_id,
         v_effective_client_id,
         v_effective_pay_method,
         v_effective_candidate_assignment,
         v_effective_has_rate_issue,
         v_effective_has_pay_channel_issue,
         v_authoritative_tsfin_json
  FROM public.timesheets_financials AS tsfin_current
  WHERE tsfin_current.timesheet_id = v_current_timesheet_id
    AND tsfin_current.is_current = TRUE
  ORDER BY tsfin_current.computed_at_utc DESC NULLS LAST, tsfin_current.created_at DESC NULLS LAST, tsfin_current.updated_at DESC NULLS LAST, tsfin_current.id DESC
  LIMIT 1
  FOR UPDATE;

  IF v_tsfin_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'NO_TSFIN', 'message', 'No current financial snapshot exists for this timesheet.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(
      CASE
        WHEN v_invoice_breakdown_json IS NULL THEN '[]'::jsonb
        WHEN jsonb_typeof(v_invoice_breakdown_json) = 'array' THEN v_invoice_breakdown_json
        WHEN jsonb_typeof(v_invoice_breakdown_json) = 'object'
         AND jsonb_typeof(v_invoice_breakdown_json->'segments') = 'array' THEN v_invoice_breakdown_json->'segments'
        ELSE '[]'::jsonb
      END
    ) AS invoice_segment(segment_json)
    WHERE NULLIF(BTRIM(COALESCE(invoice_segment.segment_json->>'invoice_locked_invoice_id', '')), '') IS NOT NULL
  ) INTO v_has_segment_invoice_lock;

  IF v_locked_by_invoice_id IS NOT NULL OR v_paid_at_utc IS NOT NULL OR v_has_segment_invoice_lock = TRUE THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_LOCKED_OR_PAID', 'message', 'Timesheet already invoiced or paid; cannot process.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  IF v_previous_status <> 'UNPROCESSED'::public.ts_fin_processing_status_enum THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'NOT_UNPROCESSED', 'message', 'Timesheet is not in UNPROCESSED state.', 'current_timesheet_id', v_current_timesheet_id, 'previous_status', v_previous_status);
  END IF;

  v_expected_row_signature := NULLIF(BTRIM(COALESCE(
    p_expected_row_signature,
    v_timesheet_patch->>'row_signature',
    v_timesheet_patch->>'rowSignature',
    v_tsfin_patch->>'row_signature',
    v_tsfin_patch->>'rowSignature',
    ''
  )), '');

  SELECT decision_result.row_json
    INTO v_pre_row
  FROM public.bulk_timesheet_row_patch_v1(JSONB_BUILD_OBJECT('dataset_mode', 'process', 'timesheet_id', v_current_timesheet_id::text)) AS decision_result(row_json)
  LIMIT 1;

  IF v_expected_row_signature IS NOT NULL
     AND NULLIF(BTRIM(COALESCE(v_pre_row->>'row_signature', '')), '') IS DISTINCT FROM v_expected_row_signature THEN
    RETURN JSONB_BUILD_OBJECT(
      'ok', FALSE,
      'operation', 'daily_manual_process',
      'error_code', 'ROW_SIGNATURE_MISMATCH',
      'message', 'Timesheet changed after it was loaded. Refresh the row and try again.',
      'current_timesheet_id', v_current_timesheet_id,
      'expected_row_signature', v_expected_row_signature,
      'current_row_signature', v_pre_row->>'row_signature'
    );
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_authoritative_tsfin_json->>'total_hours', '')), '') IS NULL
     OR NULLIF(BTRIM(COALESCE(v_authoritative_tsfin_json->>'total_pay_ex_vat', '')), '') IS NULL
     OR NULLIF(BTRIM(COALESCE(v_authoritative_tsfin_json->>'total_charge_ex_vat', '')), '') IS NULL
     OR NULLIF(BTRIM(COALESCE(v_authoritative_tsfin_json->>'margin_ex_vat', '')), '') IS NULL THEN
    RETURN JSONB_BUILD_OBJECT(
      'ok', FALSE,
      'operation', 'daily_manual_process',
      'error_code', 'AUTHORITATIVE_TSFIN_TOTALS_MISSING',
      'message', 'Cannot process: authoritative TSFIN totals are missing.',
      'current_timesheet_id', v_current_timesheet_id
    );
  END IF;

  FOREACH v_patch_key IN ARRAY v_numeric_patch_keys LOOP
    IF v_tsfin_patch ? v_patch_key THEN
      v_supplied_text := NULLIF(BTRIM(COALESCE(v_tsfin_patch->>v_patch_key, '')), '');
      v_authoritative_text := NULLIF(BTRIM(COALESCE(v_authoritative_tsfin_json->>v_patch_key, '')), '');

      IF v_supplied_text IS NULL AND v_authoritative_text IS NULL THEN
        CONTINUE;
      END IF;

      IF v_supplied_text IS NULL OR v_authoritative_text IS NULL THEN
        RETURN JSONB_BUILD_OBJECT(
          'ok', FALSE,
          'operation', 'daily_manual_process',
          'error_code', 'TSFIN_PATCH_MISMATCH',
          'message', 'Cannot process: supplied TSFIN value does not match the authoritative DB snapshot.',
          'field', v_patch_key,
          'current_timesheet_id', v_current_timesheet_id
        );
      END IF;

      BEGIN
        v_supplied_numeric := v_supplied_text::numeric;
        v_authoritative_numeric := v_authoritative_text::numeric;
      EXCEPTION WHEN OTHERS THEN
        RETURN JSONB_BUILD_OBJECT(
          'ok', FALSE,
          'operation', 'daily_manual_process',
          'error_code', 'TSFIN_PATCH_NUMERIC_INVALID',
          'message', 'Cannot process: supplied TSFIN numeric value is invalid.',
          'field', v_patch_key,
          'current_timesheet_id', v_current_timesheet_id
        );
      END;

      IF ABS(COALESCE(v_supplied_numeric, 0) - COALESCE(v_authoritative_numeric, 0)) > 0.0001 THEN
        RETURN JSONB_BUILD_OBJECT(
          'ok', FALSE,
          'operation', 'daily_manual_process',
          'error_code', 'TSFIN_PATCH_MISMATCH',
          'message', 'Cannot process: supplied TSFIN totals must match the authoritative DB snapshot.',
          'field', v_patch_key,
          'supplied', v_supplied_numeric,
          'authoritative', v_authoritative_numeric,
          'current_timesheet_id', v_current_timesheet_id
        );
      END IF;
    END IF;
  END LOOP;

  IF v_effective_candidate_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'CANDIDATE_MISSING', 'message', 'Cannot process: candidate is missing from TSFIN context.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  IF v_effective_client_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'CLIENT_MISSING', 'message', 'Cannot process: client is missing from TSFIN context.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  IF v_effective_has_rate_issue = TRUE THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'RATE_ISSUE', 'message', 'Cannot process: TSFIN has a rate issue.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  IF v_effective_has_pay_channel_issue = TRUE THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'PAY_CHANNEL_ISSUE', 'message', 'Cannot process: TSFIN has a pay channel issue.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_effective_pay_method, '')), '') IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'PAY_METHOD_MISSING', 'message', 'Cannot process: pay method is missing from TSFIN context.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_effective_candidate_assignment, '')), '') IS NULL OR UPPER(COALESCE(v_effective_candidate_assignment, '')) = 'UNASSIGNED' THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'CANDIDATE_ASSIGNMENT_UNRESOLVED', 'message', 'Cannot process: candidate assignment is unresolved in TSFIN context.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  UPDATE public.timesheets AS timesheet_update
  SET worked_start_iso = CASE WHEN v_timesheet_patch ? 'worked_start_iso' THEN NULLIF(BTRIM(v_timesheet_patch->>'worked_start_iso'), '')::timestamp with time zone ELSE timesheet_update.worked_start_iso END,
      worked_end_iso = CASE WHEN v_timesheet_patch ? 'worked_end_iso' THEN NULLIF(BTRIM(v_timesheet_patch->>'worked_end_iso'), '')::timestamp with time zone ELSE timesheet_update.worked_end_iso END,
      break_start_iso = CASE WHEN v_timesheet_patch ? 'break_start_iso' THEN NULLIF(BTRIM(v_timesheet_patch->>'break_start_iso'), '')::timestamp with time zone ELSE timesheet_update.break_start_iso END,
      break_end_iso = CASE WHEN v_timesheet_patch ? 'break_end_iso' THEN NULLIF(BTRIM(v_timesheet_patch->>'break_end_iso'), '')::timestamp with time zone ELSE timesheet_update.break_end_iso END,
      break_minutes = CASE WHEN v_timesheet_patch ? 'break_minutes' THEN NULLIF(BTRIM(v_timesheet_patch->>'break_minutes'), '')::integer ELSE timesheet_update.break_minutes END,
      worked_minutes = CASE WHEN v_timesheet_patch ? 'worked_minutes' THEN NULLIF(BTRIM(v_timesheet_patch->>'worked_minutes'), '')::integer ELSE timesheet_update.worked_minutes END,
      actual_schedule_json = CASE WHEN v_timesheet_patch ? 'actual_schedule_json' THEN v_timesheet_patch->'actual_schedule_json' ELSE timesheet_update.actual_schedule_json END,
      additional_units_week = CASE WHEN v_timesheet_patch ? 'additional_units_week' THEN v_timesheet_patch->'additional_units_week' ELSE timesheet_update.additional_units_week END,
      additional_units_per_day = CASE WHEN v_timesheet_patch ? 'additional_units_per_day' THEN v_timesheet_patch->'additional_units_per_day' ELSE timesheet_update.additional_units_per_day END,
      reference_number = CASE WHEN v_timesheet_patch ? 'reference_number' THEN NULLIF(BTRIM(v_timesheet_patch->>'reference_number'), '') ELSE timesheet_update.reference_number END,
      reference_set_at = CASE WHEN v_timesheet_patch ? 'reference_number' THEN CASE WHEN NULLIF(BTRIM(v_timesheet_patch->>'reference_number'), '') IS NULL THEN NULL::timestamp with time zone WHEN NULLIF(BTRIM(v_timesheet_patch->>'reference_number'), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(timesheet_update.reference_number, '')), '') THEN v_now ELSE COALESCE(timesheet_update.reference_set_at, v_now) END ELSE timesheet_update.reference_set_at END,
      updated_at = v_now
  WHERE timesheet_update.timesheet_id = v_current_timesheet_id
    AND timesheet_update.is_current = TRUE
  RETURNING TO_JSONB(timesheet_update), timesheet_update.version
  INTO v_timesheet_json, v_current_version;

  IF v_timesheet_json IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'TIMESHEET_UPDATE_FAILED', 'message', 'Failed to update current timesheet.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  UPDATE public.timesheets_financials AS tsfin_update
  SET processing_status = v_new_status,
      processed_by_user_id = p_actor_user_id,
      processed_at_utc = v_now,
      authorised_by_user_id = NULL,
      authorised_at_utc = NULL,
      updated_at = v_now
  WHERE tsfin_update.id = v_tsfin_id
    AND tsfin_update.is_current = TRUE
  RETURNING TO_JSONB(tsfin_update)
  INTO v_tsfin_json;

  IF v_tsfin_json IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_process', 'error_code', 'TSFIN_UPDATE_FAILED', 'message', 'Failed to update current financial snapshot.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  SELECT decision_result.row_json
    INTO v_post_row
  FROM public.bulk_timesheet_row_patch_v1(JSONB_BUILD_OBJECT('dataset_mode', 'process', 'timesheet_id', v_current_timesheet_id::text)) AS decision_result(row_json)
  LIMIT 1;

  PERFORM public._audit_insert(
    'timesheet',
    v_current_timesheet_id::text,
    'TIMESHEET_DAILY_MANUAL_PROCESSED',
    JSONB_BUILD_OBJECT(
      'row', COALESCE(v_pre_row, JSONB_BUILD_OBJECT()),
      'processing_status', v_previous_status,
      'row_signature', v_pre_row->>'row_signature'
    ),
    JSONB_BUILD_OBJECT(
      'row', COALESCE(v_post_row, JSONB_BUILD_OBJECT()),
      'processing_status', v_new_status,
      'processed_at_utc', v_now,
      'processed_by_user_id', p_actor_user_id,
      'row_signature', v_post_row->>'row_signature'
    ),
    'DAILY_MANUAL_PROCESS',
    p_actor_user_id
  );

  RETURN JSONB_BUILD_OBJECT(
    'ok', TRUE,
    'operation', 'daily_manual_process',
    'processed', TRUE,
    'success', TRUE,
    'requested_timesheet_id', p_timesheet_id,
    'expected_timesheet_id', p_expected_timesheet_id,
    'current_timesheet_id', v_current_timesheet_id,
    'timesheet_id', v_current_timesheet_id,
    'current_version', v_current_version,
    'was_stale', v_was_stale,
    'previous_status', v_previous_status,
    'processing_status', v_new_status,
    'status_transition', JSONB_BUILD_OBJECT('from', v_previous_status, 'to', v_new_status, 'processed_at_utc', v_now, 'processed_by_user_id', p_actor_user_id),
    'timesheet', COALESCE(v_timesheet_json, NULL::jsonb),
    'tsfin', COALESCE(v_tsfin_json, NULL::jsonb),
    'row_patch', COALESCE(v_post_row->'row_patch', JSONB_BUILD_OBJECT()),
    'row_patches', JSONB_BUILD_ARRAY(COALESCE(v_post_row->'row_patch', JSONB_BUILD_OBJECT())),
    'row_signature', v_post_row->>'row_signature',
    'data_row', COALESCE(v_post_row, JSONB_BUILD_OBJECT()),
    'count_deltas', JSONB_BUILD_OBJECT('unprocessed', -1, 'processed', 1),
    'cache_invalidation_hints', JSONB_BUILD_OBJECT(
      'row_keys', JSONB_BUILD_ARRAY(COALESCE(v_post_row->>'row_key', 'timesheet:' || v_current_timesheet_id::text)),
      'timesheet_ids', JSONB_BUILD_ARRAY(v_current_timesheet_id),
      'storage_keys', '[]'::jsonb,
      'datasets', JSONB_BUILD_ARRAY('bulk_process', 'bulk_authorise'),
      'row_signature', v_post_row->>'row_signature',
      'manual_changed', TRUE,
      'identity_changed', FALSE,
      'status_only', FALSE,
      'invalidate_context', FALSE,
      'invalidate_row_context', FALSE,
      'invalidate_editor_context', TRUE,
      'invalidate_preview', FALSE,
      'invalidate_evidence', FALSE
    ),
    'cache_invalidation', JSONB_BUILD_OBJECT(
      'row_keys', JSONB_BUILD_ARRAY(COALESCE(v_post_row->>'row_key', 'timesheet:' || v_current_timesheet_id::text)),
      'timesheet_ids', JSONB_BUILD_ARRAY(v_current_timesheet_id),
      'storage_keys', '[]'::jsonb,
      'datasets', JSONB_BUILD_ARRAY('bulk_process', 'bulk_authorise'),
      'row_signature', v_post_row->>'row_signature',
      'manual_changed', TRUE,
      'invalidate_context', FALSE,
      'invalidate_preview', FALSE
    )
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.timesheet_daily_manual_unprocess_atomic(p_timesheet_id uuid, p_expected_timesheet_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_now_utc timestamp with time zone DEFAULT now(), p_expected_row_signature text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 VOLATILE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamp with time zone := COALESCE(p_now_utc, now());
  v_requested_booking_id text := NULL;
  v_requested_timesheet_id uuid := NULL;
  v_current_timesheet_id uuid := NULL;
  v_current_version integer := NULL;
  v_was_stale boolean := FALSE;
  v_sheet_scope text := NULL;
  v_submission_mode text := NULL;
  v_authorised_at_server timestamp with time zone := NULL;
  v_tsfin_id uuid := NULL;
  v_previous_status public.ts_fin_processing_status_enum := NULL;
  v_new_status public.ts_fin_processing_status_enum := 'UNPROCESSED'::public.ts_fin_processing_status_enum;
  v_locked_by_invoice_id uuid := NULL;
  v_paid_at_utc timestamp with time zone := NULL;
  v_invoice_breakdown_json jsonb := NULL;
  v_has_segment_invoice_lock boolean := FALSE;
  v_tsfin_json jsonb := NULL;
  v_timesheet_json jsonb := NULL;
  v_pre_row jsonb := NULL;
  v_post_row jsonb := NULL;
  v_expected_row_signature text := NULL;
BEGIN
  IF p_timesheet_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_unprocess', 'error_code', 'TIMESHEET_ID_REQUIRED', 'message', 'p_timesheet_id is required.');
  END IF;

  IF p_expected_timesheet_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_unprocess', 'error_code', 'EXPECTED_TIMESHEET_ID_REQUIRED', 'message', 'p_expected_timesheet_id is required.');
  END IF;

  SELECT requested_ts.booking_id,
         requested_ts.timesheet_id
    INTO v_requested_booking_id,
         v_requested_timesheet_id
  FROM public.timesheets AS requested_ts
  WHERE requested_ts.timesheet_id = p_timesheet_id
  LIMIT 1;

  IF v_requested_timesheet_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_unprocess', 'error_code', 'TIMESHEET_NOT_FOUND', 'message', 'Timesheet was not found.', 'requested_timesheet_id', p_timesheet_id);
  END IF;

  SELECT current_ts.timesheet_id,
         current_ts.version
    INTO v_current_timesheet_id,
         v_current_version
  FROM public.timesheets AS current_ts
  WHERE current_ts.booking_id = v_requested_booking_id
    AND current_ts.is_current = TRUE
  ORDER BY current_ts.version DESC NULLS LAST, current_ts.timesheet_id DESC
  LIMIT 1;

  IF v_current_timesheet_id IS NULL THEN
    v_current_timesheet_id := v_requested_timesheet_id;
  END IF;

  v_was_stale := v_requested_timesheet_id IS DISTINCT FROM v_current_timesheet_id;

  IF p_expected_timesheet_id IS DISTINCT FROM v_current_timesheet_id THEN
    RETURN JSONB_BUILD_OBJECT(
      'ok', FALSE,
      'operation', 'daily_manual_unprocess',
      'error_code', 'TIMESHEET_MOVED',
      'message', 'Timesheet has moved to a newer current row.',
      'requested_timesheet_id', p_timesheet_id,
      'expected_timesheet_id', p_expected_timesheet_id,
      'current_timesheet_id', v_current_timesheet_id,
      'was_stale', v_was_stale
    );
  END IF;

  SELECT current_ts.sheet_scope::text,
         current_ts.submission_mode::text,
         current_ts.authorised_at_server,
         current_ts.version,
         TO_JSONB(current_ts)
    INTO v_sheet_scope,
         v_submission_mode,
         v_authorised_at_server,
         v_current_version,
         v_timesheet_json
  FROM public.timesheets AS current_ts
  WHERE current_ts.timesheet_id = v_current_timesheet_id
    AND current_ts.is_current = TRUE
  LIMIT 1
  FOR UPDATE;

  IF v_sheet_scope IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_unprocess', 'error_code', 'CURRENT_TIMESHEET_NOT_FOUND', 'message', 'Current timesheet was not found.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  IF UPPER(COALESCE(v_sheet_scope, '')) <> 'DAILY' THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_unprocess', 'error_code', 'NOT_DAILY', 'message', 'Timesheet is not DAILY; daily manual unprocess only applies to DAILY sheets.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  IF UPPER(COALESCE(v_submission_mode, '')) <> 'MANUAL' THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_unprocess', 'error_code', 'NOT_MANUAL', 'message', 'Timesheet must be MANUAL before unprocessing.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  IF v_authorised_at_server IS NOT NULL THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_unprocess', 'error_code', 'TIMESHEET_AUTHORISED_EDIT_BLOCKED', 'message', 'This timesheet is authorised. Unauthorise it before unprocessing.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  SELECT tsfin_current.id,
         tsfin_current.processing_status,
         tsfin_current.locked_by_invoice_id,
         tsfin_current.paid_at_utc,
         tsfin_current.invoice_breakdown_json
    INTO v_tsfin_id,
         v_previous_status,
         v_locked_by_invoice_id,
         v_paid_at_utc,
         v_invoice_breakdown_json
  FROM public.timesheets_financials AS tsfin_current
  WHERE tsfin_current.timesheet_id = v_current_timesheet_id
    AND tsfin_current.is_current = TRUE
  ORDER BY tsfin_current.computed_at_utc DESC NULLS LAST, tsfin_current.id DESC
  LIMIT 1
  FOR UPDATE;

  IF v_tsfin_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_unprocess', 'error_code', 'NO_TSFIN', 'message', 'No current financial snapshot exists for this timesheet.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(
      CASE
        WHEN v_invoice_breakdown_json IS NULL THEN '[]'::jsonb
        WHEN jsonb_typeof(v_invoice_breakdown_json) = 'array' THEN v_invoice_breakdown_json
        WHEN jsonb_typeof(v_invoice_breakdown_json) = 'object'
         AND jsonb_typeof(v_invoice_breakdown_json->'segments') = 'array' THEN v_invoice_breakdown_json->'segments'
        ELSE '[]'::jsonb
      END
    ) AS invoice_segment(segment_json)
    WHERE NULLIF(BTRIM(COALESCE(invoice_segment.segment_json->>'invoice_locked_invoice_id', '')), '') IS NOT NULL
  ) INTO v_has_segment_invoice_lock;

  IF v_locked_by_invoice_id IS NOT NULL OR v_paid_at_utc IS NOT NULL OR v_has_segment_invoice_lock = TRUE THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_unprocess', 'error_code', 'TIMESHEET_LOCKED_OR_PAID', 'message', 'Cannot unprocess: timesheet is locked or paid.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  IF v_previous_status = 'UNPROCESSED'::public.ts_fin_processing_status_enum THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_unprocess', 'error_code', 'ALREADY_UNPROCESSED', 'message', 'Timesheet is already UNPROCESSED.', 'current_timesheet_id', v_current_timesheet_id, 'previous_status', v_previous_status);
  END IF;

  IF v_previous_status NOT IN ('PENDING_AUTH'::public.ts_fin_processing_status_enum, 'READY_FOR_HR'::public.ts_fin_processing_status_enum) THEN
    RETURN JSONB_BUILD_OBJECT(
      'ok', FALSE,
      'operation', 'daily_manual_unprocess',
      'error_code', 'PROCESSING_STATUS_NOT_UNPROCESSABLE',
      'message', 'Timesheet is not in a processing state that can be moved back to UNPROCESSED.',
      'current_timesheet_id', v_current_timesheet_id,
      'previous_status', v_previous_status
    );
  END IF;

  v_expected_row_signature := NULLIF(BTRIM(COALESCE(p_expected_row_signature, '')), '');

  SELECT decision_result.row_json
    INTO v_pre_row
  FROM public.bulk_timesheet_row_patch_v1(JSONB_BUILD_OBJECT('dataset_mode', 'process', 'timesheet_id', v_current_timesheet_id::text)) AS decision_result(row_json)
  LIMIT 1;

  IF v_expected_row_signature IS NOT NULL
     AND NULLIF(BTRIM(COALESCE(v_pre_row->>'row_signature', '')), '') IS DISTINCT FROM v_expected_row_signature THEN
    RETURN JSONB_BUILD_OBJECT(
      'ok', FALSE,
      'operation', 'daily_manual_unprocess',
      'error_code', 'ROW_SIGNATURE_MISMATCH',
      'message', 'Timesheet changed after it was loaded. Refresh the row and try again.',
      'current_timesheet_id', v_current_timesheet_id,
      'expected_row_signature', v_expected_row_signature,
      'current_row_signature', v_pre_row->>'row_signature'
    );
  END IF;

  UPDATE public.timesheets_financials AS tsfin_update
  SET processing_status = v_new_status,
      processed_by_user_id = NULL,
      processed_at_utc = NULL,
      authorised_by_user_id = NULL,
      authorised_at_utc = NULL,
      updated_at = v_now
  WHERE tsfin_update.id = v_tsfin_id
    AND tsfin_update.is_current = TRUE
  RETURNING TO_JSONB(tsfin_update)
  INTO v_tsfin_json;

  IF v_tsfin_json IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('ok', FALSE, 'operation', 'daily_manual_unprocess', 'error_code', 'TSFIN_UPDATE_FAILED', 'message', 'Failed to move daily timesheet back to UNPROCESSED.', 'current_timesheet_id', v_current_timesheet_id);
  END IF;

  SELECT TO_JSONB(current_ts)
    INTO v_timesheet_json
  FROM public.timesheets AS current_ts
  WHERE current_ts.timesheet_id = v_current_timesheet_id
    AND current_ts.is_current = TRUE
  LIMIT 1;

  SELECT decision_result.row_json
    INTO v_post_row
  FROM public.bulk_timesheet_row_patch_v1(JSONB_BUILD_OBJECT('dataset_mode', 'process', 'timesheet_id', v_current_timesheet_id::text)) AS decision_result(row_json)
  LIMIT 1;

  PERFORM public._audit_insert(
    'timesheet',
    v_current_timesheet_id::text,
    'TIMESHEET_DAILY_MANUAL_UNPROCESSED',
    JSONB_BUILD_OBJECT(
      'row', COALESCE(v_pre_row, JSONB_BUILD_OBJECT()),
      'processing_status', v_previous_status,
      'row_signature', v_pre_row->>'row_signature'
    ),
    JSONB_BUILD_OBJECT(
      'row', COALESCE(v_post_row, JSONB_BUILD_OBJECT()),
      'processing_status', v_new_status,
      'row_signature', v_post_row->>'row_signature'
    ),
    'DAILY_MANUAL_UNPROCESS',
    p_actor_user_id
  );

  RETURN JSONB_BUILD_OBJECT(
    'ok', TRUE,
    'operation', 'daily_manual_unprocess',
    'unprocessed', TRUE,
    'success', TRUE,
    'requested_timesheet_id', p_timesheet_id,
    'expected_timesheet_id', p_expected_timesheet_id,
    'current_timesheet_id', v_current_timesheet_id,
    'timesheet_id', v_current_timesheet_id,
    'current_version', v_current_version,
    'was_stale', v_was_stale,
    'previous_status', v_previous_status,
    'processing_status', v_new_status,
    'status_transition', JSONB_BUILD_OBJECT('from', v_previous_status, 'to', v_new_status, 'processed_at_utc', NULL::text, 'processed_by_user_id', NULL::text),
    'timesheet', COALESCE(v_timesheet_json, NULL::jsonb),
    'tsfin', COALESCE(v_tsfin_json, NULL::jsonb),
    'row_patch', COALESCE(v_post_row->'row_patch', JSONB_BUILD_OBJECT()),
    'row_patches', JSONB_BUILD_ARRAY(COALESCE(v_post_row->'row_patch', JSONB_BUILD_OBJECT())),
    'row_signature', v_post_row->>'row_signature',
    'data_row', COALESCE(v_post_row, JSONB_BUILD_OBJECT()),
    'count_deltas', JSONB_BUILD_OBJECT('unprocessed', 1, 'processed', -1),
    'cache_invalidation_hints', JSONB_BUILD_OBJECT(
      'row_keys', JSONB_BUILD_ARRAY(COALESCE(v_post_row->>'row_key', 'timesheet:' || v_current_timesheet_id::text)),
      'timesheet_ids', JSONB_BUILD_ARRAY(v_current_timesheet_id),
      'storage_keys', '[]'::jsonb,
      'datasets', JSONB_BUILD_ARRAY('bulk_process', 'bulk_authorise'),
      'row_signature', v_post_row->>'row_signature',
      'status_only', TRUE,
      'identity_changed', FALSE,
      'manual_changed', FALSE,
      'invalidate_context', FALSE,
      'invalidate_row_context', FALSE,
      'invalidate_preview', FALSE,
      'invalidate_evidence', FALSE
    ),
    'cache_invalidation', JSONB_BUILD_OBJECT(
      'rows', JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT('row_key', COALESCE(v_post_row->>'row_key', 'timesheet:' || v_current_timesheet_id::text), 'timesheet_id', v_current_timesheet_id, 'new_row_signature', v_post_row->>'row_signature')),
      'artifacts', '[]'::jsonb,
      'datasets', JSONB_BUILD_ARRAY('bulk_process', 'bulk_authorise'),
      'status_only', TRUE,
      'invalidate_context', FALSE,
      'invalidate_preview', FALSE
    )
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public._banking_provider_failure_reason_normalise(
  p_provider_key text,
  p_provider_state text,
  p_provider_reason_code text DEFAULT NULL::text,
  p_provider_reason_text text DEFAULT NULL::text,
  p_event_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_provider_key text := UPPER(NULLIF(BTRIM(COALESCE(p_provider_key, '')), ''));
  v_provider_state text := LOWER(NULLIF(BTRIM(COALESCE(p_provider_state, '')), ''));
  v_event_payload jsonb := '{}'::jsonb;
  v_reason_code text := NULL::text;
  v_reason_text text := NULL::text;
  v_reason_probe text := NULL::text;
  v_failure_reason_group text := NULL::text;
  v_failure_reason_label text := NULL::text;
  v_is_user_filterable boolean := false;
  v_is_success_state boolean := false;
  v_is_pending_state boolean := false;
  v_is_terminal_failure_state boolean := false;
  v_support_details jsonb := '{}'::jsonb;
BEGIN
  IF p_event_payload IS NOT NULL AND COALESCE(jsonb_typeof(p_event_payload), 'null') = 'object' THEN
    v_event_payload := p_event_payload;
  END IF;

  v_reason_code := COALESCE(
    NULLIF(BTRIM(p_provider_reason_code), ''),
    NULLIF(BTRIM(v_event_payload ->> 'provider_failure_reason_code'), ''),
    NULLIF(BTRIM(v_event_payload ->> 'failure_reason_code'), ''),
    NULLIF(BTRIM(v_event_payload ->> 'reason_code'), ''),
    NULLIF(BTRIM(v_event_payload ->> 'reasonCode'), ''),
    NULLIF(BTRIM(v_event_payload ->> 'error_code'), ''),
    NULLIF(BTRIM(v_event_payload ->> 'errorCode'), ''),
    NULLIF(BTRIM(v_event_payload #>> '{data,provider_failure_reason_code}'), ''),
    NULLIF(BTRIM(v_event_payload #>> '{data,failure_reason_code}'), ''),
    NULLIF(BTRIM(v_event_payload #>> '{data,reason_code}'), ''),
    NULLIF(BTRIM(v_event_payload #>> '{data,reasonCode}'), ''),
    NULLIF(BTRIM(v_event_payload #>> '{data,error_code}'), ''),
    NULLIF(BTRIM(v_event_payload #>> '{data,errorCode}'), '')
  );

  v_reason_text := COALESCE(
    NULLIF(BTRIM(p_provider_reason_text), ''),
    NULLIF(BTRIM(v_event_payload ->> 'provider_failure_reason_text'), ''),
    NULLIF(BTRIM(v_event_payload ->> 'failure_reason'), ''),
    NULLIF(BTRIM(v_event_payload ->> 'failureReason'), ''),
    NULLIF(BTRIM(v_event_payload ->> 'reason'), ''),
    NULLIF(BTRIM(v_event_payload ->> 'message'), ''),
    NULLIF(BTRIM(v_event_payload ->> 'error_message'), ''),
    NULLIF(BTRIM(v_event_payload ->> 'errorMessage'), ''),
    NULLIF(BTRIM(v_event_payload ->> 'decline_reason'), ''),
    NULLIF(BTRIM(v_event_payload ->> 'declineReason'), ''),
    NULLIF(BTRIM(v_event_payload #>> '{data,provider_failure_reason_text}'), ''),
    NULLIF(BTRIM(v_event_payload #>> '{data,failure_reason}'), ''),
    NULLIF(BTRIM(v_event_payload #>> '{data,failureReason}'), ''),
    NULLIF(BTRIM(v_event_payload #>> '{data,reason}'), ''),
    NULLIF(BTRIM(v_event_payload #>> '{data,message}'), ''),
    NULLIF(BTRIM(v_event_payload #>> '{data,error_message}'), ''),
    NULLIF(BTRIM(v_event_payload #>> '{data,errorMessage}'), ''),
    NULLIF(BTRIM(v_event_payload #>> '{data,decline_reason}'), ''),
    NULLIF(BTRIM(v_event_payload #>> '{data,declineReason}'), '')
  );

  v_reason_probe := LOWER(CONCAT_WS(' ', v_provider_key, v_provider_state, v_reason_code, v_reason_text));

  v_is_success_state := v_provider_state IN (
    'paid',
    'settled',
    'completed',
    'complete',
    'success',
    'succeeded'
  );

  v_is_pending_state := v_provider_state IN (
    'created',
    'pending',
    'accepted',
    'scheduled',
    'submitted',
    'sent',
    'processing',
    'in_flight',
    'queued',
    'pending_settlement',
    'pending_confirmation'
  );

  v_is_terminal_failure_state := v_provider_state IN (
    'failed',
    'failure',
    'declined',
    'rejected',
    'cancelled',
    'canceled',
    'submission_failed',
    'failed_before_commit'
  );

  IF v_is_success_state THEN
    v_failure_reason_group := NULL::text;
    v_failure_reason_label := NULL::text;
    v_is_user_filterable := false;
  ELSIF v_reason_probe ~ '(insufficient|insufficient_funds|not enough|available balance|balance too low|low balance|lack of funds|funds unavailable|insufficient balance)' THEN
    v_failure_reason_group := 'INSUFFICIENT_FUNDS';
    v_failure_reason_label := 'Insufficient funds';
    v_is_user_filterable := true;
  ELSIF v_reason_probe ~ '(unknown recipient|recipient unknown|unknown beneficiary|beneficiary unknown|payee unknown|recipient not found|beneficiary not found|payee not found|name check|confirmation of payee)' THEN
    v_failure_reason_group := 'UNKNOWN_RECIPIENT';
    v_failure_reason_label := 'Unknown recipient';
    v_is_user_filterable := true;
  ELSIF v_reason_probe ~ '(invalid account|invalid iban|invalid sort|invalid routing|invalid beneficiary|invalid recipient|account number invalid|iban invalid|sort code invalid|routing number invalid|bad account)' THEN
    v_failure_reason_group := 'INVALID_ACCOUNT';
    v_failure_reason_label := 'Invalid account';
    v_is_user_filterable := true;
  ELSIF v_reason_probe ~ '(account closed|closed account|beneficiary account closed|recipient account closed)' THEN
    v_failure_reason_group := 'ACCOUNT_CLOSED';
    v_failure_reason_label := 'Account closed';
    v_is_user_filterable := true;
  ELSIF v_reason_probe ~ '(outage|unavailable|service unavailable|temporarily unavailable|timeout|timed out|gateway timeout|connection refused|connection reset|network error|provider down|bank unavailable|503|504)' THEN
    v_failure_reason_group := 'PROVIDER_OUTAGE';
    v_failure_reason_label := 'Provider outage';
    v_is_user_filterable := true;
  ELSIF v_reason_probe ~ '(webhook unmatched|webhook_unmatched|unmatched webhook|event unmatched|unmatched event)' THEN
    v_failure_reason_group := 'WEBHOOK_UNMATCHED';
    v_failure_reason_label := 'Webhook unmatched';
    v_is_user_filterable := true;
  ELSIF v_reason_probe ~ '(unknown|ambiguous|unmatched|cannot match|not matched|unable to match|outcome unknown|state unknown)' THEN
    v_failure_reason_group := 'PROVIDER_UNKNOWN';
    v_failure_reason_label := 'Provider outcome unknown';
    v_is_user_filterable := true;
  ELSIF v_reason_probe ~ '(compliance|sanction|aml|kyc|screening|review|fraud|risk review|manual review|restricted)' THEN
    v_failure_reason_group := 'COMPLIANCE_REVIEW';
    v_failure_reason_label := 'Compliance review';
    v_is_user_filterable := true;
  ELSIF v_reason_probe ~ '(duplicate|already submitted|already exists|idempotency|duplicate transaction|duplicate payment)' THEN
    v_failure_reason_group := 'DUPLICATE_RISK';
    v_failure_reason_label := 'Duplicate risk';
    v_is_user_filterable := true;
  ELSIF v_reason_probe ~ '(paid recovery|recovery required|overpayment|paid_settled|paid or settled|settled recovery)' THEN
    v_failure_reason_group := 'PAID_RECOVERY_REQUIRED';
    v_failure_reason_label := 'Paid recovery required';
    v_is_user_filterable := true;
  ELSIF v_reason_probe ~ '(manual adjustment|carry forward|carry-forward|manual_adjustment|manual adjustment blocker)' THEN
    v_failure_reason_group := 'MANUAL_ADJUSTMENT_BLOCKER';
    v_failure_reason_label := 'Manual adjustment blocker';
    v_is_user_filterable := true;
  ELSIF v_reason_probe ~ '(bank rejected|bank_rejected|rejected by bank|declined by bank|refused by bank|beneficiary bank rejected|receiving bank rejected)' THEN
    v_failure_reason_group := 'BANK_REJECTED';
    v_failure_reason_label := 'Bank rejected';
    v_is_user_filterable := true;
  ELSIF v_is_pending_state THEN
    v_failure_reason_group := NULL::text;
    v_failure_reason_label := NULL::text;
    v_is_user_filterable := false;
  ELSIF v_is_terminal_failure_state THEN
    v_failure_reason_group := 'PROVIDER_FAILED_UNSPECIFIED';
    v_failure_reason_label := 'Provider failed';
    v_is_user_filterable := true;
  ELSE
    v_failure_reason_group := NULL::text;
    v_failure_reason_label := NULL::text;
    v_is_user_filterable := false;
  END IF;

  v_support_details := jsonb_build_object(
    'provider_key', v_provider_key,
    'provider_state', v_provider_state,
    'provider_reason_code', v_reason_code,
    'provider_reason_text', v_reason_text,
    'is_success_state', v_is_success_state,
    'is_pending_state', v_is_pending_state,
    'is_terminal_failure_state', v_is_terminal_failure_state
  );

  RETURN jsonb_build_object(
    'failure_reason_group', v_failure_reason_group,
    'failure_reason_code', v_reason_code,
    'failure_reason_label', v_failure_reason_label,
    'is_user_filterable', v_is_user_filterable,
    'support_details_json', v_support_details
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.banking_pay_batch_signal_touch(
  p_pay_batch_id uuid,
  p_change_reason text,
  p_change_source text DEFAULT NULL::text,
  p_change_scope_json jsonb DEFAULT '{}'::jsonb,
  p_touch_payment_status boolean DEFAULT true,
  p_touch_correction_progress boolean DEFAULT false,
  p_touch_alerts boolean DEFAULT false,
  p_touch_overview boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_change_reason text := NULLIF(BTRIM(COALESCE(p_change_reason, '')), '');
  v_change_source text := NULLIF(BTRIM(COALESCE(p_change_source, '')), '');
  v_change_scope_json jsonb := '{}'::jsonb;
  v_touch_payment_status boolean := COALESCE(p_touch_payment_status, false);
  v_touch_correction_progress boolean := COALESCE(p_touch_correction_progress, false);
  v_touch_alerts boolean := COALESCE(p_touch_alerts, false);
  v_touch_overview boolean := COALESCE(p_touch_overview, false);
  v_last_changed_transfer_ids jsonb := '[]'::jsonb;
  v_last_changed_candidate_ids jsonb := '[]'::jsonb;
  v_last_changed_pay_batch_item_ids jsonb := '[]'::jsonb;
  v_changed_transfer_id_count integer := 0;
  v_changed_candidate_id_count integer := 0;
  v_changed_pay_batch_item_id_count integer := 0;
  v_changed_transfer_ids_hash text := 'changed_transfer_ids:v1:' || MD5('[]');
  v_changed_candidate_ids_hash text := 'changed_candidate_ids:v1:' || MD5('[]');
  v_changed_pay_batch_item_ids_hash text := 'changed_pay_batch_item_ids:v1:' || MD5('[]');
  v_signal_row public.banking_pay_batch_change_signals%ROWTYPE;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WATCH_SIGNAL');

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_PAY_BATCH_SIGNAL_TOUCH_BATCH_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_PAY_BATCH_SIGNAL_TOUCH_BATCH_REQUIRED')::text;
  END IF;

  IF v_change_reason IS NULL THEN
    RAISE EXCEPTION 'BANKING_PAY_BATCH_SIGNAL_TOUCH_REASON_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_PAY_BATCH_SIGNAL_TOUCH_REASON_REQUIRED')::text;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.pay_batches AS pay_batch_check
    WHERE pay_batch_check.id = p_pay_batch_id
  ) THEN
    RAISE EXCEPTION 'BANKING_PAY_BATCH_SIGNAL_TOUCH_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_PAY_BATCH_SIGNAL_TOUCH_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  IF p_change_scope_json IS NOT NULL AND COALESCE(jsonb_typeof(p_change_scope_json), 'null') = 'object' THEN
    v_change_scope_json := p_change_scope_json;
  END IF;

  v_last_changed_transfer_ids := COALESCE(
    CASE WHEN jsonb_typeof(v_change_scope_json -> 'last_changed_transfer_ids') = 'array' THEN v_change_scope_json -> 'last_changed_transfer_ids' END,
    CASE WHEN jsonb_typeof(v_change_scope_json -> 'changed_transfer_ids') = 'array' THEN v_change_scope_json -> 'changed_transfer_ids' END,
    CASE WHEN jsonb_typeof(v_change_scope_json -> 'pay_bank_transfer_ids') = 'array' THEN v_change_scope_json -> 'pay_bank_transfer_ids' END,
    CASE WHEN jsonb_typeof(v_change_scope_json -> 'transfer_ids') = 'array' THEN v_change_scope_json -> 'transfer_ids' END,
    '[]'::jsonb
  );

  v_last_changed_candidate_ids := COALESCE(
    CASE WHEN jsonb_typeof(v_change_scope_json -> 'last_changed_candidate_ids') = 'array' THEN v_change_scope_json -> 'last_changed_candidate_ids' END,
    CASE WHEN jsonb_typeof(v_change_scope_json -> 'changed_candidate_ids') = 'array' THEN v_change_scope_json -> 'changed_candidate_ids' END,
    CASE WHEN jsonb_typeof(v_change_scope_json -> 'candidate_ids') = 'array' THEN v_change_scope_json -> 'candidate_ids' END,
    '[]'::jsonb
  );

  v_last_changed_pay_batch_item_ids := COALESCE(
    CASE WHEN jsonb_typeof(v_change_scope_json -> 'last_changed_pay_batch_item_ids') = 'array' THEN v_change_scope_json -> 'last_changed_pay_batch_item_ids' END,
    CASE WHEN jsonb_typeof(v_change_scope_json -> 'changed_pay_batch_item_ids') = 'array' THEN v_change_scope_json -> 'changed_pay_batch_item_ids' END,
    CASE WHEN jsonb_typeof(v_change_scope_json -> 'pay_batch_item_ids') = 'array' THEN v_change_scope_json -> 'pay_batch_item_ids' END,
    CASE WHEN jsonb_typeof(v_change_scope_json -> 'item_ids') = 'array' THEN v_change_scope_json -> 'item_ids' END,
    '[]'::jsonb
  );

  v_changed_transfer_id_count := COALESCE(
    CASE
      WHEN COALESCE(v_change_scope_json->>'last_changed_transfer_id_count', v_change_scope_json->>'changed_transfer_id_count', v_change_scope_json->>'transfer_id_count', '') ~ '^[0-9]+$'
        THEN COALESCE(v_change_scope_json->>'last_changed_transfer_id_count', v_change_scope_json->>'changed_transfer_id_count', v_change_scope_json->>'transfer_id_count')::integer
      ELSE NULL::integer
    END,
    CASE WHEN jsonb_typeof(v_last_changed_transfer_ids) = 'array' THEN jsonb_array_length(v_last_changed_transfer_ids) ELSE 0 END
  );

  v_changed_candidate_id_count := COALESCE(
    CASE
      WHEN COALESCE(v_change_scope_json->>'last_changed_candidate_id_count', v_change_scope_json->>'changed_candidate_id_count', v_change_scope_json->>'candidate_id_count', '') ~ '^[0-9]+$'
        THEN COALESCE(v_change_scope_json->>'last_changed_candidate_id_count', v_change_scope_json->>'changed_candidate_id_count', v_change_scope_json->>'candidate_id_count')::integer
      ELSE NULL::integer
    END,
    CASE WHEN jsonb_typeof(v_last_changed_candidate_ids) = 'array' THEN jsonb_array_length(v_last_changed_candidate_ids) ELSE 0 END
  );

  v_changed_pay_batch_item_id_count := COALESCE(
    CASE
      WHEN COALESCE(v_change_scope_json->>'last_changed_pay_batch_item_id_count', v_change_scope_json->>'changed_pay_batch_item_id_count', v_change_scope_json->>'pay_batch_item_id_count', v_change_scope_json->>'item_id_count', '') ~ '^[0-9]+$'
        THEN COALESCE(v_change_scope_json->>'last_changed_pay_batch_item_id_count', v_change_scope_json->>'changed_pay_batch_item_id_count', v_change_scope_json->>'pay_batch_item_id_count', v_change_scope_json->>'item_id_count')::integer
      ELSE NULL::integer
    END,
    CASE WHEN jsonb_typeof(v_last_changed_pay_batch_item_ids) = 'array' THEN jsonb_array_length(v_last_changed_pay_batch_item_ids) ELSE 0 END
  );

  v_changed_transfer_ids_hash := COALESCE(
    NULLIF(BTRIM(COALESCE(v_change_scope_json->>'last_changed_transfer_ids_hash', v_change_scope_json->>'changed_transfer_ids_hash', v_change_scope_json->>'transfer_ids_hash', '')), ''),
    'changed_transfer_ids:v1:' || COALESCE(v_changed_transfer_id_count, 0)::text || ':' || MD5('[]')
  );
  v_changed_candidate_ids_hash := COALESCE(
    NULLIF(BTRIM(COALESCE(v_change_scope_json->>'last_changed_candidate_ids_hash', v_change_scope_json->>'changed_candidate_ids_hash', v_change_scope_json->>'candidate_ids_hash', '')), ''),
    'changed_candidate_ids:v1:' || COALESCE(v_changed_candidate_id_count, 0)::text || ':' || MD5('[]')
  );
  v_changed_pay_batch_item_ids_hash := COALESCE(
    NULLIF(BTRIM(COALESCE(v_change_scope_json->>'last_changed_pay_batch_item_ids_hash', v_change_scope_json->>'changed_pay_batch_item_ids_hash', v_change_scope_json->>'pay_batch_item_ids_hash', v_change_scope_json->>'item_ids_hash', '')), ''),
    'changed_pay_batch_item_ids:v1:' || COALESCE(v_changed_pay_batch_item_id_count, 0)::text || ':' || MD5('[]')
  );

  SELECT COALESCE(jsonb_agg(to_jsonb(transfer_sample.changed_id) ORDER BY transfer_sample.ordinality), '[]'::jsonb)
  INTO v_last_changed_transfer_ids
  FROM (
    SELECT changed_transfer_id_rows.changed_id, changed_transfer_id_rows.ordinality
    FROM jsonb_array_elements_text(
      CASE WHEN jsonb_typeof(v_last_changed_transfer_ids) = 'array' THEN v_last_changed_transfer_ids ELSE '[]'::jsonb END
    ) WITH ORDINALITY AS changed_transfer_id_rows(changed_id, ordinality)
    LIMIT 10
  ) AS transfer_sample;

  SELECT COALESCE(jsonb_agg(to_jsonb(candidate_sample.changed_id) ORDER BY candidate_sample.ordinality), '[]'::jsonb)
  INTO v_last_changed_candidate_ids
  FROM (
    SELECT changed_candidate_id_rows.changed_id, changed_candidate_id_rows.ordinality
    FROM jsonb_array_elements_text(
      CASE WHEN jsonb_typeof(v_last_changed_candidate_ids) = 'array' THEN v_last_changed_candidate_ids ELSE '[]'::jsonb END
    ) WITH ORDINALITY AS changed_candidate_id_rows(changed_id, ordinality)
    LIMIT 10
  ) AS candidate_sample;

  SELECT COALESCE(jsonb_agg(to_jsonb(item_sample.changed_id) ORDER BY item_sample.ordinality), '[]'::jsonb)
  INTO v_last_changed_pay_batch_item_ids
  FROM (
    SELECT changed_item_id_rows.changed_id, changed_item_id_rows.ordinality
    FROM jsonb_array_elements_text(
      CASE WHEN jsonb_typeof(v_last_changed_pay_batch_item_ids) = 'array' THEN v_last_changed_pay_batch_item_ids ELSE '[]'::jsonb END
    ) WITH ORDINALITY AS changed_item_id_rows(changed_id, ordinality)
    LIMIT 10
  ) AS item_sample;

  IF v_changed_transfer_ids_hash LIKE ('changed_transfer_ids:v1:' || COALESCE(v_changed_transfer_id_count, 0)::text || ':%') THEN
    v_changed_transfer_ids_hash := 'changed_transfer_ids:v1:' || COALESCE(v_changed_transfer_id_count, 0)::text || ':' || MD5(COALESCE(v_last_changed_transfer_ids, '[]'::jsonb)::text);
  END IF;

  IF v_changed_candidate_ids_hash LIKE ('changed_candidate_ids:v1:' || COALESCE(v_changed_candidate_id_count, 0)::text || ':%') THEN
    v_changed_candidate_ids_hash := 'changed_candidate_ids:v1:' || COALESCE(v_changed_candidate_id_count, 0)::text || ':' || MD5(COALESCE(v_last_changed_candidate_ids, '[]'::jsonb)::text);
  END IF;

  IF v_changed_pay_batch_item_ids_hash LIKE ('changed_pay_batch_item_ids:v1:' || COALESCE(v_changed_pay_batch_item_id_count, 0)::text || ':%') THEN
    v_changed_pay_batch_item_ids_hash := 'changed_pay_batch_item_ids:v1:' || COALESCE(v_changed_pay_batch_item_id_count, 0)::text || ':' || MD5(COALESCE(v_last_changed_pay_batch_item_ids, '[]'::jsonb)::text);
  END IF;

  v_change_scope_json := (
    v_change_scope_json
      - 'last_changed_transfer_ids'
      - 'changed_transfer_ids'
      - 'pay_bank_transfer_ids'
      - 'transfer_ids'
      - 'last_changed_candidate_ids'
      - 'changed_candidate_ids'
      - 'candidate_ids'
      - 'last_changed_pay_batch_item_ids'
      - 'changed_pay_batch_item_ids'
      - 'pay_batch_item_ids'
      - 'item_ids'
  ) || jsonb_build_object(
    'last_changed_transfer_ids_sample', COALESCE(v_last_changed_transfer_ids, '[]'::jsonb),
    'last_changed_transfer_id_count', COALESCE(v_changed_transfer_id_count, 0),
    'last_changed_transfer_ids_hash', v_changed_transfer_ids_hash,
    'last_changed_candidate_ids_sample', COALESCE(v_last_changed_candidate_ids, '[]'::jsonb),
    'last_changed_candidate_id_count', COALESCE(v_changed_candidate_id_count, 0),
    'last_changed_candidate_ids_hash', v_changed_candidate_ids_hash,
    'last_changed_pay_batch_item_ids_sample', COALESCE(v_last_changed_pay_batch_item_ids, '[]'::jsonb),
    'last_changed_pay_batch_item_id_count', COALESCE(v_changed_pay_batch_item_id_count, 0),
    'last_changed_pay_batch_item_ids_hash', v_changed_pay_batch_item_ids_hash,
    'changed_id_samples_are_capped', true,
    'changed_id_sample_cap', 10
  );

  IF v_touch_payment_status IS NOT TRUE
     AND v_touch_correction_progress IS NOT TRUE
     AND v_touch_alerts IS NOT TRUE
     AND v_touch_overview IS NOT TRUE THEN
    SELECT existing_signal.*
    INTO v_signal_row
    FROM public.banking_pay_batch_change_signals AS existing_signal
    WHERE existing_signal.pay_batch_id = p_pay_batch_id;

    IF NOT FOUND THEN
      RETURN jsonb_build_object(
        'ok', true,
        'changed', false,
        'pay_batch_id', p_pay_batch_id::text,
        'version', 0,
        'payment_status_version', 0,
        'correction_progress_version', 0,
        'alert_version', 0,
        'overview_version', 0
      );
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'changed', false,
      'pay_batch_id', v_signal_row.pay_batch_id::text,
      'version', v_signal_row.version,
      'payment_status_version', v_signal_row.payment_status_version,
      'correction_progress_version', v_signal_row.correction_progress_version,
      'alert_version', v_signal_row.alert_version,
      'overview_version', v_signal_row.overview_version
    );
  END IF;

  INSERT INTO public.banking_pay_batch_change_signals AS signal_target (
    pay_batch_id,
    version,
    payment_status_version,
    correction_progress_version,
    alert_version,
    overview_version,
    last_changed_at_utc,
    last_payment_status_changed_at_utc,
    last_correction_progress_changed_at_utc,
    last_alert_changed_at_utc,
    last_change_reason,
    last_change_source,
    last_change_scope_json,
    last_changed_transfer_ids,
    last_changed_candidate_ids,
    last_changed_pay_batch_item_ids,
    last_status_hash,
    last_alert_hash,
    updated_at_utc
  )
  VALUES (
    p_pay_batch_id,
    1,
    CASE WHEN v_touch_payment_status THEN 1 ELSE 0 END,
    CASE WHEN v_touch_correction_progress THEN 1 ELSE 0 END,
    CASE WHEN v_touch_alerts THEN 1 ELSE 0 END,
    CASE WHEN v_touch_overview THEN 1 ELSE 0 END,
    v_now,
    CASE WHEN v_touch_payment_status THEN v_now ELSE NULL::timestamptz END,
    CASE WHEN v_touch_correction_progress THEN v_now ELSE NULL::timestamptz END,
    CASE WHEN v_touch_alerts THEN v_now ELSE NULL::timestamptz END,
    v_change_reason,
    v_change_source,
    v_change_scope_json,
    v_last_changed_transfer_ids,
    v_last_changed_candidate_ids,
    v_last_changed_pay_batch_item_ids,
    CASE WHEN v_touch_payment_status THEN 'payment_status:' || MD5(p_pay_batch_id::text || ':1:' || v_change_reason || ':' || v_change_scope_json::text) ELSE NULL::text END,
    CASE WHEN v_touch_alerts THEN 'alert:' || MD5(p_pay_batch_id::text || ':1:' || v_change_reason || ':' || v_change_scope_json::text) ELSE NULL::text END,
    v_now
  )
  ON CONFLICT (pay_batch_id) DO UPDATE
  SET
    version = signal_target.version + 1,
    payment_status_version = signal_target.payment_status_version + CASE WHEN v_touch_payment_status THEN 1 ELSE 0 END,
    correction_progress_version = signal_target.correction_progress_version + CASE WHEN v_touch_correction_progress THEN 1 ELSE 0 END,
    alert_version = signal_target.alert_version + CASE WHEN v_touch_alerts THEN 1 ELSE 0 END,
    overview_version = signal_target.overview_version + CASE WHEN v_touch_overview THEN 1 ELSE 0 END,
    last_changed_at_utc = v_now,
    last_payment_status_changed_at_utc = CASE WHEN v_touch_payment_status THEN v_now ELSE signal_target.last_payment_status_changed_at_utc END,
    last_correction_progress_changed_at_utc = CASE WHEN v_touch_correction_progress THEN v_now ELSE signal_target.last_correction_progress_changed_at_utc END,
    last_alert_changed_at_utc = CASE WHEN v_touch_alerts THEN v_now ELSE signal_target.last_alert_changed_at_utc END,
    last_change_reason = v_change_reason,
    last_change_source = v_change_source,
    last_change_scope_json = v_change_scope_json,
    last_changed_transfer_ids = v_last_changed_transfer_ids,
    last_changed_candidate_ids = v_last_changed_candidate_ids,
    last_changed_pay_batch_item_ids = v_last_changed_pay_batch_item_ids,
    last_status_hash = CASE
      WHEN v_touch_payment_status THEN 'payment_status:' || MD5(p_pay_batch_id::text || ':' || (signal_target.payment_status_version + 1)::text || ':' || v_change_reason || ':' || v_change_scope_json::text)
      ELSE signal_target.last_status_hash
    END,
    last_alert_hash = CASE
      WHEN v_touch_alerts THEN 'alert:' || MD5(p_pay_batch_id::text || ':' || (signal_target.alert_version + 1)::text || ':' || v_change_reason || ':' || v_change_scope_json::text)
      ELSE signal_target.last_alert_hash
    END,
    updated_at_utc = v_now
  RETURNING *
  INTO v_signal_row;

  BEGIN
    PERFORM public.pay_batch_display_summary_refresh(p_pay_batch_id);
    SELECT refreshed_signal.*
    INTO v_signal_row
    FROM public.banking_pay_batch_change_signals AS refreshed_signal
    WHERE refreshed_signal.pay_batch_id = p_pay_batch_id;
  EXCEPTION WHEN OTHERS THEN
    PERFORM public.pay_batch_display_summary_touch(p_pay_batch_id);
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'changed', true,
    'pay_batch_id', v_signal_row.pay_batch_id::text,
    'version', v_signal_row.version,
    'payment_status_version', v_signal_row.payment_status_version,
    'correction_progress_version', v_signal_row.correction_progress_version,
    'alert_version', v_signal_row.alert_version,
    'overview_version', v_signal_row.overview_version,
    'last_changed_at_utc', v_signal_row.last_changed_at_utc,
    'last_change_reason', v_signal_row.last_change_reason,
    'last_change_source', v_signal_row.last_change_source,
    'last_change_scope_json', v_signal_row.last_change_scope_json,
    'last_changed_transfer_ids', COALESCE(v_signal_row.last_changed_transfer_ids, '[]'::jsonb),
    'last_changed_transfer_id_count', COALESCE(v_changed_transfer_id_count, 0),
    'last_changed_transfer_ids_hash', v_changed_transfer_ids_hash,
    'last_changed_candidate_ids', COALESCE(v_signal_row.last_changed_candidate_ids, '[]'::jsonb),
    'last_changed_candidate_id_count', COALESCE(v_changed_candidate_id_count, 0),
    'last_changed_candidate_ids_hash', v_changed_candidate_ids_hash,
    'last_changed_pay_batch_item_ids', COALESCE(v_signal_row.last_changed_pay_batch_item_ids, '[]'::jsonb),
    'last_changed_pay_batch_item_id_count', COALESCE(v_changed_pay_batch_item_id_count, 0),
    'last_changed_pay_batch_item_ids_hash', v_changed_pay_batch_item_ids_hash,
    'last_status_hash', v_signal_row.last_status_hash,
    'last_alert_hash', v_signal_row.last_alert_hash
  );
END;
$function$;





CREATE OR REPLACE FUNCTION public.banking_pay_batch_watch_signal(
  p_pay_batch_id uuid,
  p_actor_user_id uuid,
  p_known_version bigint DEFAULT NULL::bigint,
  p_known_payment_status_version bigint DEFAULT NULL::bigint,
  p_known_correction_progress_version bigint DEFAULT NULL::bigint,
  p_known_alert_version bigint DEFAULT NULL::bigint,
  p_known_overview_version bigint DEFAULT NULL::bigint,
  p_current_tab text DEFAULT NULL::text,
  p_current_section_json jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_is_valid boolean := false;
  v_current_tab text := LOWER(REPLACE(NULLIF(BTRIM(COALESCE(p_current_tab, '')), ''), '-', '_'));
  v_current_section_json jsonb := '{}'::jsonb;
  v_signal_row public.banking_pay_batch_change_signals%ROWTYPE;
  v_signal_found boolean := false;
  v_version bigint := 0;
  v_payment_status_version bigint := 0;
  v_correction_progress_version bigint := 0;
  v_alert_version bigint := 0;
  v_overview_version bigint := 0;
  v_payment_status_changed boolean := false;
  v_correction_progress_changed boolean := false;
  v_alert_changed boolean := false;
  v_overview_changed boolean := false;
  v_changed boolean := false;
  v_changed_areas text[] := ARRAY[]::text[];
  v_recommended_refresh text := 'NONE';
  v_display_summary_version bigint := 0;
  v_display_summary_updated_at_utc timestamptz := NULL::timestamptz;
  v_display_stale_summary_json jsonb := '{}'::jsonb;
  v_display_summary_refresh_required boolean := false;
  v_latest_operation_id uuid := NULL::uuid;
  v_latest_operation_status text := NULL::text;
  v_latest_operation_phase text := NULL::text;
  v_cached_alert_hash text := 'banking_alert_signal:v3:' || MD5('');
  v_cached_summary_hash text := 'banking_alert_summary:v3:' || MD5('');
  v_cached_unacknowledged_count integer := 0;
  v_cached_highest_severity text := NULL::text;
  v_cached_highest_label text := NULL::text;
  v_changed_transfer_ids_sample jsonb := '[]'::jsonb;
  v_changed_candidate_ids_sample jsonb := '[]'::jsonb;
  v_changed_pay_batch_item_ids_sample jsonb := '[]'::jsonb;
  v_changed_transfer_id_count integer := 0;
  v_changed_candidate_id_count integer := 0;
  v_changed_pay_batch_item_id_count integer := 0;
  v_changed_transfer_ids_hash text := 'changed_transfer_ids:v1:' || MD5('[]');
  v_changed_candidate_ids_hash text := 'changed_candidate_ids:v1:' || MD5('[]');
  v_changed_pay_batch_item_ids_hash text := 'changed_pay_batch_item_ids:v1:' || MD5('[]');
  v_last_change_scope_summary_json jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WATCH_SIGNAL');

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_PAY_BATCH_WATCH_SIGNAL_BATCH_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_PAY_BATCH_WATCH_SIGNAL_BATCH_REQUIRED')::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_PAY_BATCH_WATCH_SIGNAL_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_PAY_BATCH_WATCH_SIGNAL_ACTOR_REQUIRED')::text;
  END IF;

  IF v_current_tab IS NULL THEN
    RAISE EXCEPTION 'BANKING_PAY_BATCH_WATCH_SIGNAL_VISIBLE_TAB_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_PAY_BATCH_WATCH_SIGNAL_VISIBLE_TAB_REQUIRED',
              'message', 'banking_pay_batch_watch_signal requires the currently visible tab/section context.'
            )::text;
  END IF;

  IF v_current_tab NOT IN (
    'overview',
    'current_payment_status',
    'payment_status',
    'payment_issues',
    'candidates',
    'items',
    'item_breakdowns',
    'transfers',
    'finance_case_groups',
    'remittances',
    'communications',
    'auth_history',
    'events'
  ) THEN
    RAISE EXCEPTION 'BANKING_PAY_BATCH_WATCH_SIGNAL_VISIBLE_TAB_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_PAY_BATCH_WATCH_SIGNAL_VISIBLE_TAB_NOT_ALLOWED',
              'current_tab', v_current_tab
            )::text;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.tms_users AS actor_user
    WHERE actor_user.id = p_actor_user_id
      AND COALESCE(actor_user.is_active, false) = true
  )
  INTO v_actor_is_valid;

  IF COALESCE(v_actor_is_valid, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'BANKING_PAY_BATCH_WATCH_SIGNAL_ACTOR_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_PAY_BATCH_WATCH_SIGNAL_ACTOR_NOT_ALLOWED',
              'actor_user_id', p_actor_user_id::text
            )::text;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.pay_batches AS pay_batch_check
    WHERE pay_batch_check.id = p_pay_batch_id
  ) THEN
    RAISE EXCEPTION 'BANKING_PAY_BATCH_WATCH_SIGNAL_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_PAY_BATCH_WATCH_SIGNAL_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  IF p_current_section_json IS NOT NULL AND COALESCE(jsonb_typeof(p_current_section_json), 'null') = 'object' THEN
    v_current_section_json := p_current_section_json;
  END IF;

  SELECT batch_signal.*
  INTO v_signal_row
  FROM public.banking_pay_batch_change_signals AS batch_signal
  WHERE batch_signal.pay_batch_id = p_pay_batch_id;

  v_signal_found := FOUND;

  SELECT
    COALESCE(display_summary.summary_version, 0),
    display_summary.updated_at_utc,
    COALESCE(display_summary.stale_summary_json, '{}'::jsonb),
    display_summary.latest_operation_id,
    display_summary.latest_operation_status,
    display_summary.latest_operation_phase
  INTO
    v_display_summary_version,
    v_display_summary_updated_at_utc,
    v_display_stale_summary_json,
    v_latest_operation_id,
    v_latest_operation_status,
    v_latest_operation_phase
  FROM public.pay_batch_display_summary AS display_summary
  WHERE display_summary.pay_batch_id = p_pay_batch_id;

  IF NOT FOUND THEN
    v_display_summary_version := 0;
    v_display_summary_updated_at_utc := NULL::timestamptz;
    v_display_stale_summary_json := '{}'::jsonb;
    v_latest_operation_id := NULL::uuid;
    v_latest_operation_status := NULL::text;
    v_latest_operation_phase := NULL::text;
  END IF;

  SELECT
    COALESCE(alert_summary.alert_hash, v_cached_alert_hash),
    COALESCE(alert_summary.summary_hash, v_cached_summary_hash),
    COALESCE(alert_summary.unacknowledged_count, 0),
    alert_summary.highest_severity,
    alert_summary.highest_label
  INTO
    v_cached_alert_hash,
    v_cached_summary_hash,
    v_cached_unacknowledged_count,
    v_cached_highest_severity,
    v_cached_highest_label
  FROM public.banking_alert_display_summary AS alert_summary
  WHERE alert_summary.actor_user_id = p_actor_user_id;

  IF NOT FOUND THEN
    v_cached_alert_hash := 'banking_alert_signal:v3:' || MD5('');
    v_cached_summary_hash := 'banking_alert_summary:v3:' || MD5('');
    v_cached_unacknowledged_count := 0;
    v_cached_highest_severity := NULL::text;
    v_cached_highest_label := NULL::text;
  END IF;


  v_display_summary_refresh_required := LOWER(BTRIM(COALESCE(v_display_stale_summary_json->>'summary_refresh_required', 'false'))) IN ('true','1','yes','y','on');

  IF v_signal_found THEN
    v_version := COALESCE(v_signal_row.version, 0);
    v_payment_status_version := COALESCE(v_signal_row.payment_status_version, 0);
    v_correction_progress_version := COALESCE(v_signal_row.correction_progress_version, 0);
    v_alert_version := COALESCE(v_signal_row.alert_version, 0);
    v_overview_version := COALESCE(v_signal_row.overview_version, 0);

    v_changed_transfer_id_count := COALESCE(
      CASE
        WHEN COALESCE(v_signal_row.last_change_scope_json->>'last_changed_transfer_id_count', v_signal_row.last_change_scope_json->>'changed_transfer_id_count', '') ~ '^[0-9]+$'
          THEN COALESCE(v_signal_row.last_change_scope_json->>'last_changed_transfer_id_count', v_signal_row.last_change_scope_json->>'changed_transfer_id_count')::integer
        ELSE NULL::integer
      END,
      CASE
        WHEN jsonb_typeof(COALESCE(v_signal_row.last_changed_transfer_ids, '[]'::jsonb)) = 'array'
          THEN jsonb_array_length(COALESCE(v_signal_row.last_changed_transfer_ids, '[]'::jsonb))
        ELSE 0
      END
    );

    v_changed_candidate_id_count := COALESCE(
      CASE
        WHEN COALESCE(v_signal_row.last_change_scope_json->>'last_changed_candidate_id_count', v_signal_row.last_change_scope_json->>'changed_candidate_id_count', '') ~ '^[0-9]+$'
          THEN COALESCE(v_signal_row.last_change_scope_json->>'last_changed_candidate_id_count', v_signal_row.last_change_scope_json->>'changed_candidate_id_count')::integer
        ELSE NULL::integer
      END,
      CASE
        WHEN jsonb_typeof(COALESCE(v_signal_row.last_changed_candidate_ids, '[]'::jsonb)) = 'array'
          THEN jsonb_array_length(COALESCE(v_signal_row.last_changed_candidate_ids, '[]'::jsonb))
        ELSE 0
      END
    );

    v_changed_pay_batch_item_id_count := COALESCE(
      CASE
        WHEN COALESCE(v_signal_row.last_change_scope_json->>'last_changed_pay_batch_item_id_count', v_signal_row.last_change_scope_json->>'changed_pay_batch_item_id_count', '') ~ '^[0-9]+$'
          THEN COALESCE(v_signal_row.last_change_scope_json->>'last_changed_pay_batch_item_id_count', v_signal_row.last_change_scope_json->>'changed_pay_batch_item_id_count')::integer
        ELSE NULL::integer
      END,
      CASE
        WHEN jsonb_typeof(COALESCE(v_signal_row.last_changed_pay_batch_item_ids, '[]'::jsonb)) = 'array'
          THEN jsonb_array_length(COALESCE(v_signal_row.last_changed_pay_batch_item_ids, '[]'::jsonb))
        ELSE 0
      END
    );

    v_changed_transfer_ids_hash := NULLIF(BTRIM(COALESCE(v_signal_row.last_change_scope_json->>'last_changed_transfer_ids_hash', v_signal_row.last_change_scope_json->>'changed_transfer_ids_hash', '')), '');
    v_changed_candidate_ids_hash := NULLIF(BTRIM(COALESCE(v_signal_row.last_change_scope_json->>'last_changed_candidate_ids_hash', v_signal_row.last_change_scope_json->>'changed_candidate_ids_hash', '')), '');
    v_changed_pay_batch_item_ids_hash := NULLIF(BTRIM(COALESCE(v_signal_row.last_change_scope_json->>'last_changed_pay_batch_item_ids_hash', v_signal_row.last_change_scope_json->>'changed_pay_batch_item_ids_hash', '')), '');

    SELECT COALESCE(jsonb_agg(to_jsonb(transfer_sample.changed_id) ORDER BY transfer_sample.ordinality), '[]'::jsonb)
    INTO v_changed_transfer_ids_sample
    FROM (
      SELECT changed_transfer_id_rows.changed_id, changed_transfer_id_rows.ordinality
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(COALESCE(v_signal_row.last_changed_transfer_ids, '[]'::jsonb)) = 'array'
            THEN COALESCE(v_signal_row.last_changed_transfer_ids, '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) WITH ORDINALITY AS changed_transfer_id_rows(changed_id, ordinality)
      LIMIT 10
    ) AS transfer_sample;

    SELECT COALESCE(jsonb_agg(to_jsonb(candidate_sample.changed_id) ORDER BY candidate_sample.ordinality), '[]'::jsonb)
    INTO v_changed_candidate_ids_sample
    FROM (
      SELECT changed_candidate_id_rows.changed_id, changed_candidate_id_rows.ordinality
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(COALESCE(v_signal_row.last_changed_candidate_ids, '[]'::jsonb)) = 'array'
            THEN COALESCE(v_signal_row.last_changed_candidate_ids, '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) WITH ORDINALITY AS changed_candidate_id_rows(changed_id, ordinality)
      LIMIT 10
    ) AS candidate_sample;

    SELECT COALESCE(jsonb_agg(to_jsonb(item_sample.changed_id) ORDER BY item_sample.ordinality), '[]'::jsonb)
    INTO v_changed_pay_batch_item_ids_sample
    FROM (
      SELECT changed_item_id_rows.changed_id, changed_item_id_rows.ordinality
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(COALESCE(v_signal_row.last_changed_pay_batch_item_ids, '[]'::jsonb)) = 'array'
            THEN COALESCE(v_signal_row.last_changed_pay_batch_item_ids, '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) WITH ORDINALITY AS changed_item_id_rows(changed_id, ordinality)
      LIMIT 10
    ) AS item_sample;

    IF v_changed_transfer_ids_hash IS NULL THEN
      v_changed_transfer_ids_hash := 'changed_transfer_ids:v1:' || COALESCE(v_changed_transfer_id_count, 0)::text || ':' || MD5(COALESCE(v_changed_transfer_ids_sample, '[]'::jsonb)::text);
    END IF;

    IF v_changed_candidate_ids_hash IS NULL THEN
      v_changed_candidate_ids_hash := 'changed_candidate_ids:v1:' || COALESCE(v_changed_candidate_id_count, 0)::text || ':' || MD5(COALESCE(v_changed_candidate_ids_sample, '[]'::jsonb)::text);
    END IF;

    IF v_changed_pay_batch_item_ids_hash IS NULL THEN
      v_changed_pay_batch_item_ids_hash := 'changed_pay_batch_item_ids:v1:' || COALESCE(v_changed_pay_batch_item_id_count, 0)::text || ':' || MD5(COALESCE(v_changed_pay_batch_item_ids_sample, '[]'::jsonb)::text);
    END IF;

    v_last_change_scope_summary_json := (
      COALESCE(v_signal_row.last_change_scope_json, '{}'::jsonb)
        - 'last_changed_transfer_ids'
        - 'changed_transfer_ids'
        - 'pay_bank_transfer_ids'
        - 'transfer_ids'
        - 'last_changed_candidate_ids'
        - 'changed_candidate_ids'
        - 'candidate_ids'
        - 'last_changed_pay_batch_item_ids'
        - 'changed_pay_batch_item_ids'
        - 'pay_batch_item_ids'
        - 'item_ids'
    ) || jsonb_build_object(
      'last_changed_transfer_ids_sample', COALESCE(v_changed_transfer_ids_sample, '[]'::jsonb),
      'last_changed_transfer_id_count', COALESCE(v_changed_transfer_id_count, 0),
      'last_changed_transfer_ids_hash', v_changed_transfer_ids_hash,
      'last_changed_candidate_ids_sample', COALESCE(v_changed_candidate_ids_sample, '[]'::jsonb),
      'last_changed_candidate_id_count', COALESCE(v_changed_candidate_id_count, 0),
      'last_changed_candidate_ids_hash', v_changed_candidate_ids_hash,
      'last_changed_pay_batch_item_ids_sample', COALESCE(v_changed_pay_batch_item_ids_sample, '[]'::jsonb),
      'last_changed_pay_batch_item_id_count', COALESCE(v_changed_pay_batch_item_id_count, 0),
      'last_changed_pay_batch_item_ids_hash', v_changed_pay_batch_item_ids_hash,
      'changed_id_samples_are_capped', true,
      'changed_id_sample_cap', 10
    );
  END IF;

  v_payment_status_changed := p_known_payment_status_version IS NULL OR p_known_payment_status_version IS DISTINCT FROM v_payment_status_version;
  v_correction_progress_changed := p_known_correction_progress_version IS NULL OR p_known_correction_progress_version IS DISTINCT FROM v_correction_progress_version;
  v_alert_changed := p_known_alert_version IS NULL OR p_known_alert_version IS DISTINCT FROM v_alert_version;
  v_overview_changed := p_known_overview_version IS NULL OR p_known_overview_version IS DISTINCT FROM v_overview_version;
  v_changed := p_known_version IS NULL OR p_known_version IS DISTINCT FROM v_version OR v_payment_status_changed OR v_correction_progress_changed OR v_alert_changed OR v_overview_changed;

  IF v_display_summary_refresh_required THEN
    v_changed := true;
    v_overview_changed := true;
    v_payment_status_changed := true;
  END IF;

  IF v_payment_status_changed THEN
    v_changed_areas := array_append(v_changed_areas, 'payment_status');
  END IF;

  IF v_correction_progress_changed THEN
    v_changed_areas := array_append(v_changed_areas, 'correction_progress');
  END IF;

  IF v_alert_changed THEN
    v_changed_areas := array_append(v_changed_areas, 'alerts');
  END IF;

  IF v_overview_changed THEN
    v_changed_areas := array_append(v_changed_areas, 'overview');
  END IF;

  IF v_changed IS NOT TRUE THEN
    v_recommended_refresh := 'NONE';
  ELSIF v_current_tab = 'overview' AND v_overview_changed THEN
    v_recommended_refresh := 'OVERVIEW_VISIBLE_PAGE';
  ELSIF v_current_tab IN ('current_payment_status', 'payment_status', 'payment_issues') AND (v_payment_status_changed OR v_correction_progress_changed) THEN
    v_recommended_refresh := 'CURRENT_PAYMENT_STATUS_VISIBLE_PAGE';
  ELSIF v_current_tab IN ('candidates', 'items', 'item_breakdowns', 'transfers', 'finance_case_groups', 'remittances', 'communications', 'auth_history', 'events') THEN
    v_recommended_refresh := 'VISIBLE_SECTION_PAGE';
  ELSIF v_alert_changed THEN
    v_recommended_refresh := 'ALERT_SIGNAL_ONLY';
  ELSE
    v_recommended_refresh := 'VISIBLE_CONTEXT_ONLY';
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'server_time_utc', now(),
    'version', v_version,
    'display_summary_version', COALESCE(v_display_summary_version, 0),
    'display_summary_updated_at_utc', CASE WHEN v_display_summary_updated_at_utc IS NULL THEN NULL::text ELSE v_display_summary_updated_at_utc::text END,
    'display_summary_refresh_required', COALESCE(v_display_summary_refresh_required, false),
    'display_stale_summary_json', COALESCE(v_display_stale_summary_json, '{}'::jsonb),
    'latest_operation_id', CASE WHEN v_latest_operation_id IS NULL THEN NULL::text ELSE v_latest_operation_id::text END,
    'latest_operation_status', v_latest_operation_status,
    'latest_operation_phase', v_latest_operation_phase,
    'payment_status_version', v_payment_status_version,
    'correction_progress_version', v_correction_progress_version,
    'alert_version', v_alert_version,
    'overview_version', v_overview_version,
    'changed', COALESCE(v_changed, false),
    'changed_areas', to_jsonb(v_changed_areas),
    'recommended_refresh', v_recommended_refresh,
    'last_change_reason', CASE WHEN v_signal_found THEN v_signal_row.last_change_reason ELSE NULL::text END,
    'last_change_source', CASE WHEN v_signal_found THEN v_signal_row.last_change_source ELSE NULL::text END,
    'last_change_scope_json', CASE WHEN v_signal_found THEN COALESCE(v_last_change_scope_summary_json, '{}'::jsonb) ELSE '{}'::jsonb END,
    'last_changed_transfer_ids', COALESCE(v_changed_transfer_ids_sample, '[]'::jsonb),
    'last_changed_transfer_ids_sample', COALESCE(v_changed_transfer_ids_sample, '[]'::jsonb),
    'last_changed_transfer_id_count', COALESCE(v_changed_transfer_id_count, 0),
    'last_changed_transfer_ids_hash', v_changed_transfer_ids_hash,
    'last_changed_candidate_ids', COALESCE(v_changed_candidate_ids_sample, '[]'::jsonb),
    'last_changed_candidate_ids_sample', COALESCE(v_changed_candidate_ids_sample, '[]'::jsonb),
    'last_changed_candidate_id_count', COALESCE(v_changed_candidate_id_count, 0),
    'last_changed_candidate_ids_hash', v_changed_candidate_ids_hash,
    'last_changed_pay_batch_item_ids', COALESCE(v_changed_pay_batch_item_ids_sample, '[]'::jsonb),
    'last_changed_pay_batch_item_ids_sample', COALESCE(v_changed_pay_batch_item_ids_sample, '[]'::jsonb),
    'last_changed_pay_batch_item_id_count', COALESCE(v_changed_pay_batch_item_id_count, 0),
    'last_changed_pay_batch_item_ids_hash', v_changed_pay_batch_item_ids_hash,
    'last_status_hash', CASE WHEN v_signal_found THEN v_signal_row.last_status_hash ELSE NULL::text END,
    'last_alert_hash', COALESCE(CASE WHEN v_signal_found THEN v_signal_row.last_alert_hash ELSE NULL::text END, v_cached_alert_hash),
    'banking_alert_hash', v_cached_alert_hash,
    'banking_alert_summary_signature', v_cached_summary_hash,
    'banking_unacknowledged_alert_count', COALESCE(v_cached_unacknowledged_count, 0),
    'banking_highest_alert_severity', COALESCE(v_cached_highest_severity, ''),
    'banking_highest_alert_label', COALESCE(v_cached_highest_label, ''),
    'current_tab', v_current_tab,
    'current_section_json', v_current_section_json
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.banking_alert_preferences_get(p_user_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_preferences public.banking_alert_user_preferences%ROWTYPE;
  v_defaults_applied boolean := false;
  v_enabled boolean := true;
  v_alert_kind_allowlist jsonb := NULL::jsonb;
  v_alert_kind_blocklist jsonb := '[]'::jsonb;
  v_failure_reason_allowlist jsonb := NULL::jsonb;
  v_failure_reason_blocklist jsonb := '[]'::jsonb;
  v_include_action_required boolean := true;
  v_include_progress_alerts boolean := true;
  v_include_informational_alerts boolean := false;
  v_include_success_alerts boolean := false;
  v_severity_min text := 'ACTION_REQUIRED';
  v_muted_provider_keys jsonb := '[]'::jsonb;
  v_muted_pay_batch_ids jsonb := '[]'::jsonb;
  v_snoozed_until_utc_text text := NULL::text;
  v_mode text := 'ALL_ACTION_REQUIRED';
  v_failure_reason_groups jsonb := '[]'::jsonb;
  v_informational_alert_kinds jsonb := '[]'::jsonb;
  v_allowed_alert_kinds jsonb := to_jsonb(ARRAY[
    'PROVIDER_OUTAGE_RETRY_LATER',
    'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER',
    'TERMINAL_NO_MONEY_REWIND_AVAILABLE',
    'AUTO_UNWIND_PROGRESS',
    'WHOLE_BATCH_CANCELLATION_PROGRESS',
    'MANUAL_ADJUSTMENTS_CARRIED_FORWARD',
    'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS',
    'PAID_SETTLED_RECOVERY_REQUIRED',
    'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT',
    'WEBHOOK_UNMATCHED_REVIEW_REQUIRED'
  ]::text[]);
  v_allowed_failure_reason_groups jsonb := to_jsonb(ARRAY[
    'INSUFFICIENT_FUNDS',
    'UNKNOWN_RECIPIENT',
    'INVALID_ACCOUNT',
    'ACCOUNT_CLOSED',
    'BANK_REJECTED',
    'PROVIDER_OUTAGE',
    'PROVIDER_UNKNOWN',
    'COMPLIANCE_REVIEW',
    'DUPLICATE_RISK',
    'PAID_RECOVERY_REQUIRED',
    'MANUAL_ADJUSTMENT_BLOCKER',
    'WEBHOOK_UNMATCHED',
    'PROVIDER_FAILED_UNSPECIFIED'
  ]::text[]);
  v_progress_alert_kinds jsonb := to_jsonb(ARRAY[
    'AUTO_UNWIND_PROGRESS',
    'WHOLE_BATCH_CANCELLATION_PROGRESS'
  ]::text[]);
  v_default_informational_alert_kinds jsonb := to_jsonb(ARRAY[
    'MANUAL_ADJUSTMENTS_CARRIED_FORWARD'
  ]::text[]);
  v_effective_options_json jsonb := '{}'::jsonb;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_GET_USER_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_GET_USER_REQUIRED')::text;
  END IF;

  SELECT preference_row.*
  INTO v_preferences
  FROM public.banking_alert_user_preferences AS preference_row
  WHERE preference_row.user_id = p_user_id;

  IF FOUND THEN
    v_enabled := COALESCE(v_preferences.enabled, true);
    v_alert_kind_allowlist := CASE WHEN jsonb_typeof(v_preferences.alert_kind_allowlist) = 'array' THEN v_preferences.alert_kind_allowlist ELSE NULL::jsonb END;
    v_alert_kind_blocklist := COALESCE(v_preferences.alert_kind_blocklist, '[]'::jsonb);
    v_failure_reason_allowlist := CASE WHEN jsonb_typeof(v_preferences.failure_reason_allowlist) = 'array' THEN v_preferences.failure_reason_allowlist ELSE NULL::jsonb END;
    v_failure_reason_blocklist := COALESCE(v_preferences.failure_reason_blocklist, '[]'::jsonb);
    v_include_action_required := COALESCE(v_preferences.include_action_required, true);
    v_include_progress_alerts := COALESCE(v_preferences.include_progress_alerts, true);
    v_include_informational_alerts := COALESCE(v_preferences.include_informational_alerts, false);
    v_include_success_alerts := false;
    v_severity_min := COALESCE(NULLIF(BTRIM(v_preferences.severity_min), ''), 'ACTION_REQUIRED');
    v_muted_provider_keys := COALESCE(v_preferences.muted_provider_keys, '[]'::jsonb);
    v_muted_pay_batch_ids := COALESCE(v_preferences.muted_pay_batch_ids, '[]'::jsonb);
    v_snoozed_until_utc_text := CASE WHEN v_preferences.snoozed_until_utc IS NULL THEN NULL ELSE v_preferences.snoozed_until_utc::text END;
  ELSE
    v_defaults_applied := true;
  END IF;

  v_failure_reason_groups := CASE
    WHEN jsonb_typeof(v_failure_reason_allowlist) = 'array' THEN v_failure_reason_allowlist
    ELSE '[]'::jsonb
  END;

  v_mode := CASE
    WHEN COALESCE(v_enabled, true) IS NOT TRUE THEN 'NO_BANKING_PAY_ALERTS'
    WHEN jsonb_typeof(v_failure_reason_allowlist) = 'array' AND jsonb_array_length(v_failure_reason_allowlist) > 0 THEN 'SELECTED_FAILURE_REASONS'
    ELSE 'ALL_ACTION_REQUIRED'
  END;

  v_informational_alert_kinds := '[]'::jsonb;
  IF COALESCE(v_include_progress_alerts, true) THEN
    v_informational_alert_kinds := v_informational_alert_kinds || v_progress_alert_kinds;
  END IF;
  IF COALESCE(v_include_informational_alerts, false) THEN
    v_informational_alert_kinds := v_informational_alert_kinds || v_default_informational_alert_kinds;
  END IF;

  v_effective_options_json := jsonb_build_object(
    'modes', to_jsonb(ARRAY['ALL_ACTION_REQUIRED','SELECTED_FAILURE_REASONS','NO_BANKING_PAY_ALERTS']::text[]),
    'alert_kinds', v_allowed_alert_kinds,
    'failure_reason_groups', v_allowed_failure_reason_groups,
    'progress_alert_kinds', v_progress_alert_kinds,
    'informational_alert_kinds', v_default_informational_alert_kinds,
    'success_alerts_available', false,
    'default_mode', 'ALL_ACTION_REQUIRED'
  );

  RETURN jsonb_build_object(
    'ok', true,
    'user_id', p_user_id::text,
    'enabled', v_enabled,
    'mode', v_mode,
    'alert_kind_allowlist', v_alert_kind_allowlist,
    'alert_kind_blocklist', v_alert_kind_blocklist,
    'failure_reason_allowlist', v_failure_reason_allowlist,
    'failure_reason_blocklist', v_failure_reason_blocklist,
    'failure_reason_groups', v_failure_reason_groups,
    'include_action_required', v_include_action_required,
    'include_progress_alerts', v_include_progress_alerts,
    'include_informational_alerts', v_include_informational_alerts,
    'include_success_alerts', false,
    'informational_alert_kinds', v_informational_alert_kinds,
    'severity_min', v_severity_min,
    'muted_provider_keys', v_muted_provider_keys,
    'muted_pay_batch_ids', v_muted_pay_batch_ids,
    'snoozed_until_utc', v_snoozed_until_utc_text,
    'effective_defaults_applied', v_defaults_applied,
    'effective_options_json', v_effective_options_json
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public.banking_alert_preferences_update(p_user_id uuid, p_preferences_json jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_payload jsonb := '{}'::jsonb;
  v_current jsonb := '{}'::jsonb;
  v_enabled boolean := true;
  v_alert_kind_allowlist jsonb := NULL::jsonb;
  v_alert_kind_blocklist jsonb := '[]'::jsonb;
  v_failure_reason_allowlist jsonb := NULL::jsonb;
  v_failure_reason_blocklist jsonb := '[]'::jsonb;
  v_include_action_required boolean := true;
  v_include_progress_alerts boolean := true;
  v_include_informational_alerts boolean := false;
  v_include_success_alerts boolean := false;
  v_severity_min text := 'ACTION_REQUIRED';
  v_muted_provider_keys jsonb := '[]'::jsonb;
  v_muted_pay_batch_ids jsonb := '[]'::jsonb;
  v_snoozed_until_utc timestamptz := NULL::timestamptz;
  v_mode text := NULL::text;
  v_informational_alert_kinds jsonb := '[]'::jsonb;
  v_allowed_alert_kinds text[] := ARRAY[
    'PROVIDER_OUTAGE_RETRY_LATER',
    'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER',
    'TERMINAL_NO_MONEY_REWIND_AVAILABLE',
    'AUTO_UNWIND_PROGRESS',
    'WHOLE_BATCH_CANCELLATION_PROGRESS',
    'MANUAL_ADJUSTMENTS_CARRIED_FORWARD',
    'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS',
    'PAID_SETTLED_RECOVERY_REQUIRED',
    'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT',
    'WEBHOOK_UNMATCHED_REVIEW_REQUIRED'
  ];
  v_allowed_failure_reasons text[] := ARRAY[
    'INSUFFICIENT_FUNDS',
    'UNKNOWN_RECIPIENT',
    'INVALID_ACCOUNT',
    'ACCOUNT_CLOSED',
    'BANK_REJECTED',
    'PROVIDER_OUTAGE',
    'PROVIDER_UNKNOWN',
    'COMPLIANCE_REVIEW',
    'DUPLICATE_RISK',
    'PAID_RECOVERY_REQUIRED',
    'MANUAL_ADJUSTMENT_BLOCKER',
    'WEBHOOK_UNMATCHED',
    'PROVIDER_FAILED_UNSPECIFIED'
  ];
  v_value_text text;
  v_preference_id uuid;
  v_result jsonb := '{}'::jsonb;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_UPDATE_USER_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_UPDATE_USER_REQUIRED')::text;
  END IF;

  IF p_preferences_json IS NOT NULL AND COALESCE(jsonb_typeof(p_preferences_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_UPDATE_PAYLOAD_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_UPDATE_PAYLOAD_MUST_BE_OBJECT')::text;
  END IF;

  v_payload := COALESCE(p_preferences_json, '{}'::jsonb);
  v_current := public.banking_alert_preferences_get(p_user_id);

  v_enabled := COALESCE((v_current ->> 'enabled')::boolean, true);
  v_alert_kind_allowlist := CASE WHEN jsonb_typeof(v_current -> 'alert_kind_allowlist') = 'array' THEN v_current -> 'alert_kind_allowlist' ELSE NULL::jsonb END;
  v_alert_kind_blocklist := CASE WHEN jsonb_typeof(v_current -> 'alert_kind_blocklist') = 'array' THEN v_current -> 'alert_kind_blocklist' ELSE '[]'::jsonb END;
  v_failure_reason_allowlist := CASE WHEN jsonb_typeof(v_current -> 'failure_reason_allowlist') = 'array' THEN v_current -> 'failure_reason_allowlist' ELSE NULL::jsonb END;
  v_failure_reason_blocklist := CASE WHEN jsonb_typeof(v_current -> 'failure_reason_blocklist') = 'array' THEN v_current -> 'failure_reason_blocklist' ELSE '[]'::jsonb END;
  v_include_action_required := COALESCE((v_current ->> 'include_action_required')::boolean, true);
  v_include_progress_alerts := COALESCE((v_current ->> 'include_progress_alerts')::boolean, true);
  v_include_informational_alerts := COALESCE((v_current ->> 'include_informational_alerts')::boolean, false);
  v_include_success_alerts := false;
  v_severity_min := COALESCE(NULLIF(BTRIM(v_current ->> 'severity_min'), ''), 'ACTION_REQUIRED');
  v_muted_provider_keys := COALESCE(v_current -> 'muted_provider_keys', '[]'::jsonb);
  v_muted_pay_batch_ids := COALESCE(v_current -> 'muted_pay_batch_ids', '[]'::jsonb);

  IF NULLIF(BTRIM(COALESCE(v_current ->> 'snoozed_until_utc', '')), '') IS NOT NULL THEN
    BEGIN
      v_snoozed_until_utc := (v_current ->> 'snoozed_until_utc')::timestamptz;
    EXCEPTION WHEN OTHERS THEN
      v_snoozed_until_utc := NULL::timestamptz;
    END;
  END IF;

  IF v_payload ? 'mode' THEN
    IF COALESCE(jsonb_typeof(v_payload -> 'mode'), 'null') <> 'string' THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_MODE_MUST_BE_STRING'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_MODE_MUST_BE_STRING')::text;
    END IF;

    v_mode := UPPER(NULLIF(BTRIM(COALESCE(v_payload ->> 'mode', '')), ''));
    IF v_mode = 'NONE' THEN
      v_mode := 'NO_BANKING_PAY_ALERTS';
    END IF;

    IF v_mode NOT IN ('NO_BANKING_PAY_ALERTS', 'ALL_ACTION_REQUIRED', 'SELECTED_FAILURE_REASONS') THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_INVALID_MODE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_INVALID_MODE', 'mode', COALESCE(v_payload ->> 'mode', NULL))::text;
    END IF;

    IF v_mode = 'NO_BANKING_PAY_ALERTS' THEN
      v_enabled := false;
    ELSIF v_mode = 'ALL_ACTION_REQUIRED' THEN
      v_enabled := true;
      v_include_action_required := true;
      IF NOT (v_payload ? 'failure_reason_allowlist') AND NOT (v_payload ? 'failure_reason_groups') THEN
        v_failure_reason_allowlist := NULL::jsonb;
      END IF;
    ELSIF v_mode = 'SELECTED_FAILURE_REASONS' THEN
      v_enabled := true;
      v_include_action_required := true;
      IF NOT (v_payload ? 'failure_reason_allowlist') AND NOT (v_payload ? 'failure_reason_groups') THEN
        v_failure_reason_allowlist := '[]'::jsonb;
      END IF;
    END IF;
  END IF;

  IF v_payload ? 'failure_reason_groups' THEN
    IF COALESCE(jsonb_typeof(v_payload -> 'failure_reason_groups'), 'null') <> 'array' THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_REASON_GROUPS_MUST_BE_ARRAY'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_REASON_GROUPS_MUST_BE_ARRAY')::text;
    END IF;

    SELECT COALESCE(jsonb_agg(to_jsonb(normalised_reason.failure_reason_group) ORDER BY normalised_reason.failure_reason_group), '[]'::jsonb)
    INTO v_failure_reason_allowlist
    FROM (
      SELECT DISTINCT CASE UPPER(BTRIM(reason_value.value))
        WHEN 'PROVIDER_OUTCOME_UNKNOWN' THEN 'PROVIDER_UNKNOWN'
        WHEN 'UNSPECIFIED_PROVIDER_FAILURE' THEN 'PROVIDER_FAILED_UNSPECIFIED'
        ELSE UPPER(BTRIM(reason_value.value))
      END AS failure_reason_group
      FROM jsonb_array_elements_text(v_payload -> 'failure_reason_groups') AS reason_value(value)
      WHERE NULLIF(BTRIM(reason_value.value), '') IS NOT NULL
    ) AS normalised_reason;
  END IF;

  IF v_payload ? 'informational_alert_kinds' THEN
    IF COALESCE(jsonb_typeof(v_payload -> 'informational_alert_kinds'), 'null') <> 'array' THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_INFORMATIONAL_KINDS_MUST_BE_ARRAY'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_INFORMATIONAL_KINDS_MUST_BE_ARRAY')::text;
    END IF;

    SELECT COALESCE(jsonb_agg(to_jsonb(UPPER(BTRIM(informational_kind.value))) ORDER BY UPPER(BTRIM(informational_kind.value))), '[]'::jsonb)
    INTO v_informational_alert_kinds
    FROM jsonb_array_elements_text(v_payload -> 'informational_alert_kinds') AS informational_kind(value)
    WHERE NULLIF(BTRIM(informational_kind.value), '') IS NOT NULL;

    v_include_informational_alerts := EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(v_informational_alert_kinds) AS informational_kind(value)
      WHERE informational_kind.value IN ('MANUAL_ADJUSTMENTS_CARRIED_FORWARD')
    );

    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(v_informational_alert_kinds) AS progress_kind(value)
      WHERE progress_kind.value IN ('AUTO_UNWIND_PROGRESS', 'WHOLE_BATCH_CANCELLATION_PROGRESS')
    ) THEN
      v_include_progress_alerts := true;
    END IF;
  END IF;

  FOR v_value_text IN
    SELECT informational_kind_entry.value
    FROM jsonb_array_elements_text(COALESCE(v_informational_alert_kinds, '[]'::jsonb)) AS informational_kind_entry(value)
  LOOP
    IF NOT (v_value_text = ANY(v_allowed_alert_kinds)) THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_INVALID_INFORMATIONAL_ALERT_KIND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_INVALID_INFORMATIONAL_ALERT_KIND', 'alert_kind', v_value_text)::text;
    END IF;
  END LOOP;

  IF v_payload ? 'enabled' THEN
    IF COALESCE(jsonb_typeof(v_payload -> 'enabled'), 'null') <> 'boolean' THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_ENABLED_MUST_BE_BOOLEAN'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_ENABLED_MUST_BE_BOOLEAN')::text;
    END IF;
    v_enabled := (v_payload ->> 'enabled')::boolean;
  END IF;

  IF v_payload ? 'include_action_required' THEN
    IF COALESCE(jsonb_typeof(v_payload -> 'include_action_required'), 'null') <> 'boolean' THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_ACTION_REQUIRED_MUST_BE_BOOLEAN'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_ACTION_REQUIRED_MUST_BE_BOOLEAN')::text;
    END IF;
    v_include_action_required := (v_payload ->> 'include_action_required')::boolean;
  END IF;

  IF v_payload ? 'include_progress_alerts' THEN
    IF COALESCE(jsonb_typeof(v_payload -> 'include_progress_alerts'), 'null') <> 'boolean' THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_PROGRESS_MUST_BE_BOOLEAN'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_PROGRESS_MUST_BE_BOOLEAN')::text;
    END IF;
    v_include_progress_alerts := (v_payload ->> 'include_progress_alerts')::boolean;
  END IF;

  IF v_payload ? 'include_informational_alerts' THEN
    IF COALESCE(jsonb_typeof(v_payload -> 'include_informational_alerts'), 'null') <> 'boolean' THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_INFORMATIONAL_MUST_BE_BOOLEAN'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_INFORMATIONAL_MUST_BE_BOOLEAN')::text;
    END IF;
    v_include_informational_alerts := (v_payload ->> 'include_informational_alerts')::boolean;
  END IF;

  IF v_payload ? 'include_success_alerts' THEN
    IF COALESCE(jsonb_typeof(v_payload -> 'include_success_alerts'), 'null') <> 'boolean' THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_SUCCESS_MUST_BE_BOOLEAN'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_SUCCESS_MUST_BE_BOOLEAN')::text;
    END IF;
    v_include_success_alerts := false;
  END IF;

  IF v_payload ? 'severity_min' THEN
    v_severity_min := UPPER(NULLIF(BTRIM(COALESCE(v_payload ->> 'severity_min', '')), ''));
    IF v_severity_min IS NULL OR v_severity_min NOT IN ('INFO','PROGRESS','ACTION_REQUIRED','CRITICAL') THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_INVALID_SEVERITY'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'BANKING_ALERT_PREFERENCES_INVALID_SEVERITY',
                'severity_min', COALESCE(v_payload ->> 'severity_min', NULL)
              )::text;
    END IF;
  END IF;

  IF v_payload ? 'alert_kind_allowlist' THEN
    IF COALESCE(jsonb_typeof(v_payload -> 'alert_kind_allowlist'), 'null') = 'null' THEN
      v_alert_kind_allowlist := NULL::jsonb;
    ELSIF jsonb_typeof(v_payload -> 'alert_kind_allowlist') = 'array' THEN
      SELECT COALESCE(jsonb_agg(to_jsonb(normalised_alert_kind.alert_kind) ORDER BY normalised_alert_kind.alert_kind), '[]'::jsonb)
      INTO v_alert_kind_allowlist
      FROM (
        SELECT DISTINCT UPPER(BTRIM(alert_kind_value.value)) AS alert_kind
        FROM jsonb_array_elements_text(v_payload -> 'alert_kind_allowlist') AS alert_kind_value(value)
        WHERE NULLIF(BTRIM(alert_kind_value.value), '') IS NOT NULL
      ) AS normalised_alert_kind;
    ELSE
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_ALERT_ALLOWLIST_MUST_BE_ARRAY'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_ALERT_ALLOWLIST_MUST_BE_ARRAY')::text;
    END IF;
  END IF;

  IF v_payload ? 'alert_kind_blocklist' THEN
    IF COALESCE(jsonb_typeof(v_payload -> 'alert_kind_blocklist'), 'null') <> 'array' THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_ALERT_BLOCKLIST_MUST_BE_ARRAY'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_ALERT_BLOCKLIST_MUST_BE_ARRAY')::text;
    END IF;
    SELECT COALESCE(jsonb_agg(to_jsonb(normalised_alert_kind.alert_kind) ORDER BY normalised_alert_kind.alert_kind), '[]'::jsonb)
    INTO v_alert_kind_blocklist
    FROM (
      SELECT DISTINCT UPPER(BTRIM(alert_kind_value.value)) AS alert_kind
      FROM jsonb_array_elements_text(v_payload -> 'alert_kind_blocklist') AS alert_kind_value(value)
      WHERE NULLIF(BTRIM(alert_kind_value.value), '') IS NOT NULL
    ) AS normalised_alert_kind;
  END IF;

  FOR v_value_text IN
    SELECT alert_kind_entry.value
    FROM jsonb_array_elements_text(COALESCE(v_alert_kind_allowlist, '[]'::jsonb)) AS alert_kind_entry(value)
  LOOP
    IF NOT (v_value_text = ANY(v_allowed_alert_kinds)) THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_INVALID_ALERT_KIND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_INVALID_ALERT_KIND', 'alert_kind', v_value_text)::text;
    END IF;
  END LOOP;

  FOR v_value_text IN
    SELECT alert_kind_entry.value
    FROM jsonb_array_elements_text(COALESCE(v_alert_kind_blocklist, '[]'::jsonb)) AS alert_kind_entry(value)
  LOOP
    IF NOT (v_value_text = ANY(v_allowed_alert_kinds)) THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_INVALID_ALERT_KIND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_INVALID_ALERT_KIND', 'alert_kind', v_value_text)::text;
    END IF;
  END LOOP;

  IF v_payload ? 'failure_reason_allowlist' THEN
    IF COALESCE(jsonb_typeof(v_payload -> 'failure_reason_allowlist'), 'null') = 'null' THEN
      v_failure_reason_allowlist := NULL::jsonb;
    ELSIF jsonb_typeof(v_payload -> 'failure_reason_allowlist') = 'array' THEN
      SELECT COALESCE(jsonb_agg(to_jsonb(normalised_reason.failure_reason_group) ORDER BY normalised_reason.failure_reason_group), '[]'::jsonb)
      INTO v_failure_reason_allowlist
      FROM (
        SELECT DISTINCT CASE UPPER(BTRIM(reason_value.value))
        WHEN 'PROVIDER_OUTCOME_UNKNOWN' THEN 'PROVIDER_UNKNOWN'
        WHEN 'UNSPECIFIED_PROVIDER_FAILURE' THEN 'PROVIDER_FAILED_UNSPECIFIED'
        ELSE UPPER(BTRIM(reason_value.value))
      END AS failure_reason_group
        FROM jsonb_array_elements_text(v_payload -> 'failure_reason_allowlist') AS reason_value(value)
        WHERE NULLIF(BTRIM(reason_value.value), '') IS NOT NULL
      ) AS normalised_reason;
    ELSE
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_REASON_ALLOWLIST_MUST_BE_ARRAY'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_REASON_ALLOWLIST_MUST_BE_ARRAY')::text;
    END IF;
  END IF;

  IF v_payload ? 'failure_reason_blocklist' THEN
    IF COALESCE(jsonb_typeof(v_payload -> 'failure_reason_blocklist'), 'null') <> 'array' THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_REASON_BLOCKLIST_MUST_BE_ARRAY'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_REASON_BLOCKLIST_MUST_BE_ARRAY')::text;
    END IF;
    SELECT COALESCE(jsonb_agg(to_jsonb(normalised_reason.failure_reason_group) ORDER BY normalised_reason.failure_reason_group), '[]'::jsonb)
    INTO v_failure_reason_blocklist
    FROM (
      SELECT DISTINCT CASE UPPER(BTRIM(reason_value.value))
        WHEN 'PROVIDER_OUTCOME_UNKNOWN' THEN 'PROVIDER_UNKNOWN'
        WHEN 'UNSPECIFIED_PROVIDER_FAILURE' THEN 'PROVIDER_FAILED_UNSPECIFIED'
        ELSE UPPER(BTRIM(reason_value.value))
      END AS failure_reason_group
      FROM jsonb_array_elements_text(v_payload -> 'failure_reason_blocklist') AS reason_value(value)
      WHERE NULLIF(BTRIM(reason_value.value), '') IS NOT NULL
    ) AS normalised_reason;
  END IF;

  FOR v_value_text IN
    SELECT reason_entry.value
    FROM jsonb_array_elements_text(COALESCE(v_failure_reason_allowlist, '[]'::jsonb)) AS reason_entry(value)
  LOOP
    IF NOT (v_value_text = ANY(v_allowed_failure_reasons)) THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_INVALID_FAILURE_REASON'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_INVALID_FAILURE_REASON', 'failure_reason_group', v_value_text)::text;
    END IF;
  END LOOP;

  FOR v_value_text IN
    SELECT reason_entry.value
    FROM jsonb_array_elements_text(COALESCE(v_failure_reason_blocklist, '[]'::jsonb)) AS reason_entry(value)
  LOOP
    IF NOT (v_value_text = ANY(v_allowed_failure_reasons)) THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_INVALID_FAILURE_REASON'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_INVALID_FAILURE_REASON', 'failure_reason_group', v_value_text)::text;
    END IF;
  END LOOP;

  IF v_payload ? 'muted_provider_keys' THEN
    IF COALESCE(jsonb_typeof(v_payload -> 'muted_provider_keys'), 'null') <> 'array' THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_MUTED_PROVIDERS_MUST_BE_ARRAY'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_MUTED_PROVIDERS_MUST_BE_ARRAY')::text;
    END IF;
    SELECT COALESCE(jsonb_agg(to_jsonb(provider_value.provider_key) ORDER BY provider_value.provider_key), '[]'::jsonb)
    INTO v_muted_provider_keys
    FROM (
      SELECT DISTINCT UPPER(BTRIM(muted_provider.value)) AS provider_key
      FROM jsonb_array_elements_text(v_payload -> 'muted_provider_keys') AS muted_provider(value)
      WHERE NULLIF(BTRIM(muted_provider.value), '') IS NOT NULL
    ) AS provider_value;
  END IF;

  IF v_payload ? 'muted_pay_batch_ids' THEN
    IF COALESCE(jsonb_typeof(v_payload -> 'muted_pay_batch_ids'), 'null') <> 'array' THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_MUTED_BATCHES_MUST_BE_ARRAY'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_MUTED_BATCHES_MUST_BE_ARRAY')::text;
    END IF;
    SELECT COALESCE(jsonb_agg(to_jsonb(batch_value.batch_id_text) ORDER BY batch_value.batch_id_text), '[]'::jsonb)
    INTO v_muted_pay_batch_ids
    FROM (
      SELECT DISTINCT LOWER(BTRIM(muted_batch.value)) AS batch_id_text
      FROM jsonb_array_elements_text(v_payload -> 'muted_pay_batch_ids') AS muted_batch(value)
      WHERE NULLIF(BTRIM(muted_batch.value), '') IS NOT NULL
    ) AS batch_value;
  END IF;

  FOR v_value_text IN
    SELECT muted_batch_entry.value
    FROM jsonb_array_elements_text(COALESCE(v_muted_pay_batch_ids, '[]'::jsonb)) AS muted_batch_entry(value)
  LOOP
    IF v_value_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_INVALID_MUTED_BATCH_ID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_INVALID_MUTED_BATCH_ID', 'pay_batch_id', v_value_text)::text;
    END IF;
  END LOOP;

  IF v_payload ? 'snoozed_until_utc' THEN
    IF COALESCE(jsonb_typeof(v_payload -> 'snoozed_until_utc'), 'null') = 'null' THEN
      v_snoozed_until_utc := NULL::timestamptz;
    ELSIF jsonb_typeof(v_payload -> 'snoozed_until_utc') = 'string' THEN
      BEGIN
        v_snoozed_until_utc := NULLIF(BTRIM(v_payload ->> 'snoozed_until_utc'), '')::timestamptz;
      EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_INVALID_SNOOZE_TIMESTAMP'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_INVALID_SNOOZE_TIMESTAMP')::text;
      END;
    ELSE
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_SNOOZE_MUST_BE_STRING_OR_NULL'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_SNOOZE_MUST_BE_STRING_OR_NULL')::text;
    END IF;

    IF v_snoozed_until_utc IS NOT NULL AND v_snoozed_until_utc > now() + interval '366 days' THEN
      RAISE EXCEPTION 'BANKING_ALERT_PREFERENCES_SNOOZE_TOO_FAR_IN_FUTURE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PREFERENCES_SNOOZE_TOO_FAR_IN_FUTURE')::text;
    END IF;
  END IF;

  IF v_mode = 'NO_BANKING_PAY_ALERTS' THEN
    v_enabled := false;
  ELSIF v_mode = 'ALL_ACTION_REQUIRED' THEN
    v_enabled := true;
    v_include_action_required := true;
    IF NOT (v_payload ? 'failure_reason_allowlist') AND NOT (v_payload ? 'failure_reason_groups') THEN
      v_failure_reason_allowlist := NULL::jsonb;
    END IF;
  ELSIF v_mode = 'SELECTED_FAILURE_REASONS' THEN
    v_enabled := true;
    v_include_action_required := true;
    IF NOT (v_payload ? 'failure_reason_allowlist') AND NOT (v_payload ? 'failure_reason_groups') THEN
      v_failure_reason_allowlist := COALESCE(v_failure_reason_allowlist, '[]'::jsonb);
    END IF;
  END IF;

  v_include_success_alerts := false;

  INSERT INTO public.banking_alert_user_preferences AS preference_target (
    user_id,
    enabled,
    alert_kind_allowlist,
    alert_kind_blocklist,
    failure_reason_allowlist,
    failure_reason_blocklist,
    include_action_required,
    include_progress_alerts,
    include_informational_alerts,
    include_success_alerts,
    severity_min,
    muted_provider_keys,
    muted_pay_batch_ids,
    snoozed_until_utc,
    created_at_utc,
    updated_at_utc
  )
  VALUES (
    p_user_id,
    v_enabled,
    v_alert_kind_allowlist,
    v_alert_kind_blocklist,
    v_failure_reason_allowlist,
    v_failure_reason_blocklist,
    v_include_action_required,
    v_include_progress_alerts,
    v_include_informational_alerts,
    false,
    v_severity_min,
    v_muted_provider_keys,
    v_muted_pay_batch_ids,
    v_snoozed_until_utc,
    now(),
    now()
  )
  ON CONFLICT (user_id) DO UPDATE
  SET
    enabled = EXCLUDED.enabled,
    alert_kind_allowlist = EXCLUDED.alert_kind_allowlist,
    alert_kind_blocklist = EXCLUDED.alert_kind_blocklist,
    failure_reason_allowlist = EXCLUDED.failure_reason_allowlist,
    failure_reason_blocklist = EXCLUDED.failure_reason_blocklist,
    include_action_required = EXCLUDED.include_action_required,
    include_progress_alerts = EXCLUDED.include_progress_alerts,
    include_informational_alerts = EXCLUDED.include_informational_alerts,
    include_success_alerts = false,
    severity_min = EXCLUDED.severity_min,
    muted_provider_keys = EXCLUDED.muted_provider_keys,
    muted_pay_batch_ids = EXCLUDED.muted_pay_batch_ids,
    snoozed_until_utc = EXCLUDED.snoozed_until_utc,
    updated_at_utc = now()
  RETURNING id
  INTO v_preference_id;

  v_result := public.banking_alert_preferences_get(p_user_id);

  RETURN v_result || jsonb_build_object(
    'updated', true,
    'preference_id', v_preference_id::text,
    'nav_refresh_recommended', true
  );
END;
$function$;





CREATE OR REPLACE FUNCTION public._banking_alert_user_filter_allows(p_user_id uuid, p_alert_payload jsonb)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_payload jsonb := '{}'::jsonb;
  v_preferences jsonb := '{}'::jsonb;
  v_enabled boolean := true;
  v_alert_kind text := NULL::text;
  v_failure_reason_group text := NULL::text;
  v_provider_key text := NULL::text;
  v_pay_batch_id_text text := NULL::text;
  v_severity text := NULL::text;
  v_severity_min text := 'ACTION_REQUIRED';
  v_snoozed_until_utc timestamptz := NULL::timestamptz;
  v_success_only boolean := false;
  v_is_progress boolean := false;
  v_is_informational boolean := false;
  v_is_action_required boolean := false;
  v_allowlist_contains boolean := false;
  v_blocklist_contains boolean := false;
  v_reason_allowlist_contains boolean := false;
  v_reason_blocklist_contains boolean := false;
  v_provider_muted boolean := false;
  v_batch_muted boolean := false;
  v_payload_lifecycle text := NULL::text;
  v_required_user_action text := NULL::text;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN false;
  END IF;

  IF p_alert_payload IS NULL OR COALESCE(jsonb_typeof(p_alert_payload), 'null') <> 'object' THEN
    RETURN false;
  END IF;

  v_payload := p_alert_payload;
  v_preferences := public.banking_alert_preferences_get(p_user_id);

  v_enabled := COALESCE((v_preferences ->> 'enabled')::boolean, true);
  IF v_enabled IS NOT TRUE THEN
    RETURN false;
  END IF;

  v_alert_kind := UPPER(NULLIF(BTRIM(COALESCE(
    v_payload ->> 'alert_kind',
    v_payload ->> 'kind',
    v_payload ->> 'alert_type',
    ''
  )), ''));

  v_failure_reason_group := UPPER(NULLIF(BTRIM(COALESCE(
    v_payload ->> 'provider_failure_reason_group',
    v_payload ->> 'failure_reason_group',
    v_payload ->> 'reason_group',
    ''
  )), ''));

  v_provider_key := UPPER(NULLIF(BTRIM(COALESCE(
    v_payload ->> 'provider_key',
    v_payload ->> 'provider',
    v_payload ->> 'rail_provider',
    v_payload ->> 'rail',
    ''
  )), ''));

  v_pay_batch_id_text := LOWER(NULLIF(BTRIM(COALESCE(
    v_payload ->> 'pay_batch_id',
    v_payload ->> 'entity_id',
    ''
  )), ''));

  v_required_user_action := UPPER(NULLIF(BTRIM(COALESCE(
    v_payload ->> 'required_user_action',
    v_payload ->> 'recommended_action',
    ''
  )), ''));

  v_payload_lifecycle := UPPER(NULLIF(BTRIM(COALESCE(
    v_payload ->> 'payment_lifecycle_state',
    v_payload ->> 'current_status',
    v_payload ->> 'status',
    ''
  )), ''));

  v_severity := UPPER(NULLIF(BTRIM(COALESCE(
    v_payload ->> 'alert_severity',
    v_payload ->> 'severity',
    ''
  )), ''));

  IF v_alert_kind IS NULL AND v_required_user_action IS NULL AND v_failure_reason_group IS NULL THEN
    RETURN false;
  END IF;

  IF v_alert_kind IN (
    'PAYMENT_COMPLETED',
    'PAYMENT_SUCCESS',
    'PAYMENT_SUCCEEDED',
    'PROVIDER_PAYMENT_COMPLETED',
    'PROVIDER_PAYMENT_SUCCESS',
    'SETTLEMENT_COMPLETED',
    'BANK_PAYMENT_SUCCESS',
    'SUCCESS',
    'COMPLETED'
  ) THEN
    RETURN false;
  END IF;

  IF v_severity IS NULL THEN
    IF v_alert_kind IN ('AUTO_UNWIND_PROGRESS', 'WHOLE_BATCH_CANCELLATION_PROGRESS') THEN
      v_severity := 'PROGRESS';
    ELSIF v_alert_kind = 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD' THEN
      v_severity := 'INFO';
    ELSE
      v_severity := 'ACTION_REQUIRED';
    END IF;
  END IF;

  v_severity_min := UPPER(NULLIF(BTRIM(COALESCE(v_preferences ->> 'severity_min', 'ACTION_REQUIRED')), ''));
  IF v_severity_min IS NULL OR v_severity_min NOT IN ('INFO','PROGRESS','ACTION_REQUIRED','CRITICAL') THEN
    v_severity_min := 'ACTION_REQUIRED';
  END IF;

  v_success_only := lower(BTRIM(COALESCE(
    v_payload ->> 'alert_candidate_is_success_only',
    v_payload ->> 'is_success_only',
    v_payload ->> 'success_only',
    'false'
  ))) IN ('true','t','1','yes','y','on');

  IF v_success_only IS NOT TRUE
     AND v_alert_kind IS NULL
     AND v_required_user_action IS NULL
     AND v_payload_lifecycle IN ('PAID', 'PAID_OR_SETTLED', 'SETTLED', 'COMPLETED', 'SUCCESS', 'SUCCEEDED') THEN
    v_success_only := true;
  END IF;

  IF v_success_only THEN
    RETURN false;
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_preferences ->> 'snoozed_until_utc', '')), '') IS NOT NULL THEN
    BEGIN
      v_snoozed_until_utc := (v_preferences ->> 'snoozed_until_utc')::timestamptz;
    EXCEPTION WHEN OTHERS THEN
      v_snoozed_until_utc := NULL::timestamptz;
    END;
  END IF;

  IF v_snoozed_until_utc IS NOT NULL AND v_snoozed_until_utc > now() THEN
    RETURN false;
  END IF;

  IF COALESCE(jsonb_typeof(v_preferences -> 'alert_kind_blocklist'), 'null') = 'array' AND v_alert_kind IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(v_preferences -> 'alert_kind_blocklist') AS blocked_alert_kind(value)
      WHERE UPPER(BTRIM(blocked_alert_kind.value)) = v_alert_kind
    )
    INTO v_blocklist_contains;

    IF v_blocklist_contains THEN
      RETURN false;
    END IF;
  END IF;

  IF COALESCE(jsonb_typeof(v_preferences -> 'alert_kind_allowlist'), 'null') = 'array' THEN
    SELECT EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(v_preferences -> 'alert_kind_allowlist') AS allowed_alert_kind(value)
      WHERE UPPER(BTRIM(allowed_alert_kind.value)) = v_alert_kind
    )
    INTO v_allowlist_contains;

    IF v_allowlist_contains IS NOT TRUE THEN
      RETURN false;
    END IF;
  END IF;

  IF COALESCE(jsonb_typeof(v_preferences -> 'failure_reason_blocklist'), 'null') = 'array' AND v_failure_reason_group IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(v_preferences -> 'failure_reason_blocklist') AS blocked_reason(value)
      WHERE UPPER(BTRIM(blocked_reason.value)) = v_failure_reason_group
    )
    INTO v_reason_blocklist_contains;

    IF v_reason_blocklist_contains THEN
      RETURN false;
    END IF;
  END IF;

  IF COALESCE(jsonb_typeof(v_preferences -> 'failure_reason_allowlist'), 'null') = 'array' THEN
    SELECT EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(v_preferences -> 'failure_reason_allowlist') AS allowed_reason(value)
      WHERE UPPER(BTRIM(allowed_reason.value)) = v_failure_reason_group
    )
    INTO v_reason_allowlist_contains;

    IF v_reason_allowlist_contains IS NOT TRUE THEN
      RETURN false;
    END IF;
  END IF;

  IF COALESCE(jsonb_typeof(v_preferences -> 'muted_provider_keys'), 'null') = 'array' AND v_provider_key IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(v_preferences -> 'muted_provider_keys') AS muted_provider(value)
      WHERE UPPER(BTRIM(muted_provider.value)) = v_provider_key
    )
    INTO v_provider_muted;

    IF v_provider_muted THEN
      RETURN false;
    END IF;
  END IF;

  IF COALESCE(jsonb_typeof(v_preferences -> 'muted_pay_batch_ids'), 'null') = 'array' AND v_pay_batch_id_text IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(v_preferences -> 'muted_pay_batch_ids') AS muted_batch(value)
      WHERE LOWER(BTRIM(muted_batch.value)) = v_pay_batch_id_text
    )
    INTO v_batch_muted;

    IF v_batch_muted THEN
      RETURN false;
    END IF;
  END IF;

  v_is_progress := v_alert_kind IN ('AUTO_UNWIND_PROGRESS', 'WHOLE_BATCH_CANCELLATION_PROGRESS') OR v_severity = 'PROGRESS';
  v_is_informational := v_alert_kind = 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD' OR v_severity = 'INFO';
  v_is_action_required := v_severity IN ('ACTION_REQUIRED', 'CRITICAL') OR v_required_user_action IS NOT NULL;

  IF v_is_progress AND COALESCE((v_preferences ->> 'include_progress_alerts')::boolean, true) IS NOT TRUE THEN
    RETURN false;
  END IF;

  IF v_is_informational AND COALESCE((v_preferences ->> 'include_informational_alerts')::boolean, false) IS NOT TRUE THEN
    RETURN false;
  END IF;

  IF v_is_action_required AND COALESCE((v_preferences ->> 'include_action_required')::boolean, true) IS NOT TRUE THEN
    RETURN false;
  END IF;

  IF v_is_progress OR v_is_informational THEN
    RETURN true;
  END IF;

  IF v_severity_min = 'CRITICAL' AND v_severity <> 'CRITICAL' THEN
    RETURN false;
  ELSIF v_severity_min = 'ACTION_REQUIRED' AND v_severity NOT IN ('ACTION_REQUIRED', 'CRITICAL') THEN
    RETURN false;
  ELSIF v_severity_min = 'PROGRESS' AND v_severity NOT IN ('PROGRESS', 'ACTION_REQUIRED', 'CRITICAL') THEN
    RETURN false;
  END IF;

  RETURN true;
END;
$function$;




DROP FUNCTION IF EXISTS public.pay_payment_cancelability_diagnostic(uuid, jsonb, uuid);
CREATE OR REPLACE FUNCTION public.pay_payment_cancelability_diagnostic(
  p_pay_batch_id uuid,
  p_selection_json jsonb DEFAULT '{}'::jsonb,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_diagnostic_context text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_uuid_regex text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_batch public.pay_batches%ROWTYPE;
  v_selection_json jsonb := '{}'::jsonb;
  v_resolved_scope_json jsonb := '{}'::jsonb;
  v_scope_type text := NULL::text;
  v_scope_is_full boolean := true;
  v_pay_bank_transfer_ids uuid[] := ARRAY[]::uuid[];
  v_pay_batch_item_ids uuid[] := ARRAY[]::uuid[];
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_pay_batch_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_provider_evidence_class text := 'NO_PROVIDER_EVIDENCE';
  v_provider_submitted boolean := false;
  v_provider_request_sent boolean := false;
  v_provider_response_present boolean := false;
  v_provider_event_present boolean := false;
  v_provider_external_id_present boolean := false;
  v_local_prepared_only boolean := true;
  v_provider_cash_state text := NULL::text;
  v_provider_blocker_code text := NULL::text;
  v_provider_reason text := NULL::text;
  v_provider_support_details_json jsonb := '{}'::jsonb;
  v_transfer_count integer := 0;
  v_transfer_final_count integer := 0;
  v_transfer_terminal_no_money_count integer := 0;
  v_transfer_pending_count integer := 0;
  v_event_count integer := 0;
  v_event_final_count integer := 0;
  v_event_terminal_no_money_count integer := 0;
  v_event_pending_count integer := 0;
  v_event_unknown_count integer := 0;
  v_provider_webhook_evidence_count integer := 0;
  v_invalid_webhook_evidence_count integer := 0;
  v_failed_webhook_replay_evidence_count integer := 0;
  v_provider_poll_evidence_count integer := 0;
  v_provider_outage_count integer := 0;
  v_pre_bank_applied_count integer := 0;
  v_no_money_applied_count integer := 0;
  v_open_provider_submit_count integer := 0;
  v_manual_adjustment_result jsonb := '{}'::jsonb;
  v_freshness_result jsonb := '{}'::jsonb;
  v_manual_carry_forward_required boolean := false;
  v_can_carry_forward_automatically boolean := true;
  v_manual_carry_forward_blocker_count integer := 0;
  v_freshness_blocker_count integer := 0;
  v_partial_scope_blocker_count integer := 0;
  v_final_evidence_count integer := 0;
  v_terminal_no_money_count integer := 0;
  v_pending_provider_count integer := 0;
  v_unknown_provider_count integer := 0;
  v_has_paid_or_settled boolean := false;
  v_has_provider_unknown boolean := false;
  v_has_provider_pending boolean := false;
  v_has_provider_outage boolean := false;
  v_has_terminal_no_money boolean := false;
  v_is_local_not_sent boolean := false;
  v_lifecycle_state text := 'PROVIDER_OUTCOME_UNKNOWN';
  v_lifecycle_label text := 'Provider outcome unknown — check provider';
  v_recommended_action text := 'CHECK_PROVIDER_STATUS';
  v_can_pre_provider_cancel boolean := false;
  v_can_no_money_unwind boolean := false;
  v_can_recover_overpayment boolean := false;
  v_requires_provider_cancel boolean := false;
  v_requires_bank_check boolean := false;
  v_requires_retry_later boolean := false;
  v_whole_batch_cancel_available boolean := false;
  v_row_cancel_available boolean := false;
  v_retry_same_batch_safe boolean := false;
  v_blockers jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_race_or_submission_blockers jsonb := '[]'::jsonb;
  v_provider_evidence_summary_json jsonb := '{}'::jsonb;
  v_blocking_paid_evidence_json jsonb := '{}'::jsonb;
  v_terminal_no_money_evidence_json jsonb := '{}'::jsonb;
  v_pending_provider_evidence_json jsonb := '{}'::jsonb;
  v_provider_outcome_unknown_evidence_json jsonb := '{}'::jsonb;
  v_provider_webhook_evidence_json jsonb := '{}'::jsonb;
  v_finance_scope_json jsonb := '{}'::jsonb;
  v_support_details_json jsonb := '{}'::jsonb;
  v_provider_failure_reason_code text := NULL::text;
  v_provider_failure_reason_group text := NULL::text;
  v_provider_failure_reason_label text := NULL::text;
  v_provider_failure_reason_result jsonb := '{}'::jsonb;
  v_failure_event_provider_key text := NULL::text;
  v_failure_event_state text := NULL::text;
  v_failure_event_reason_code text := NULL::text;
  v_failure_event_reason_text text := NULL::text;
  v_failure_event_payload jsonb := '{}'::jsonb;
  v_alert_candidate_kind text := NULL::text;
  v_alert_candidate_severity text := NULL::text;
  v_alert_candidate_is_success_only boolean := false;
  v_paid_recovery_required boolean := false;
  v_has_actual_recovery_context boolean := false;
  v_status_update_signature text := NULL::text;
  v_result jsonb := '{}'::jsonb;
  v_actor_valid boolean := true;
  v_diagnostic_context text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_diagnostic_context, '')), ''), '-', '_'));
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_BATCH_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_BATCH_REQUIRED')::text;
  END IF;


  IF v_diagnostic_context IS NULL THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_CONTEXT_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_CONTEXT_REQUIRED',
              'message', 'pay_payment_cancelability_diagnostic requires an explicit diagnostic/action context.'
            )::text;
  END IF;

  IF v_diagnostic_context IN (
    'LIST',
    'BATCH_LIST',
    'PAY_BATCHES_LIST',
    'PAY_BATCH_GET',
    'PAY_BATCH_GET_BOOTSTRAP_ONLY',
    'BOOTSTRAP',
    'BATCH_BOOTSTRAP',
    'OVERVIEW',
    'BATCH_OVERVIEW',
    'PREVIEW_OPEN',
    'PREVIEW_PROGRESS',
    'WORKBENCH_OPEN',
    'WORKBENCH_PROGRESS',
    'OPERATION_GET',
    'OPERATION_WORKER',
    'OPERATION_WORKER_PROOF',
    'OPERATION_PROGRESS',
    'PROGRESS_POLLING',
    'LIVE_WATCH',
    'WATCH_SIGNAL',
    'RPC_CHANGES_PING'
  ) THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_CONTEXT_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_CONTEXT_NOT_ALLOWED',
              'context', v_diagnostic_context,
              'message', 'Cancelability diagnostics are blocked from list, bootstrap, Overview, preview, operation progress, operation GET, and worker proof paths.'
            )::text;
  END IF;

  IF v_diagnostic_context NOT IN (
    'CURRENT_PAYMENT_STATUS',
    'CURRENT_PAYMENT_STATUS_TAB',
    'PAYMENT_STATUS_TAB',
    'PAYMENT_ISSUES_TAB',
    'PAYMENT_ISSUE_REVIEW',
    'CANCELLATION_ACTION',
    'CANCEL_PAYMENT_ACTION',
    'CANCEL_WHOLE_BATCH_ACTION',
    'CORRECTION_REVIEW',
    'CORRECTION_ACTION',
    'PAYMENT_CORRECTION_PLAN',
    'USER_TRIGGERED_DIAGNOSTIC',
    'EXPLICIT_DIAGNOSTIC'
  ) THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_CONTEXT_NOT_EXPLICIT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_CONTEXT_NOT_EXPLICIT',
              'context', v_diagnostic_context,
              'message', 'Cancelability diagnostics are only allowed from explicit Current Payment Status, cancellation, correction, or user-triggered diagnostic flows.'
            )::text;
  END IF;

  IF p_selection_json IS NOT NULL AND COALESCE(jsonb_typeof(p_selection_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_SELECTION_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_SELECTION_MUST_BE_OBJECT')::text;
  END IF;

  v_selection_json := COALESCE(p_selection_json, '{}'::jsonb);
  v_paid_recovery_required := (
    lower(NULLIF(btrim(COALESCE(v_selection_json->>'recovery_required', '')), '')) IN ('true','t','yes','y','1','on')
    OR lower(NULLIF(btrim(COALESCE(v_selection_json->>'paid_recovery_required', '')), '')) IN ('true','t','yes','y','1','on')
    OR lower(NULLIF(btrim(COALESCE(v_selection_json->>'payment_recovery_required', '')), '')) IN ('true','t','yes','y','1','on')
    OR upper(NULLIF(btrim(COALESCE(v_selection_json->>'requested_action', '')), '')) = 'AMEND_AND_RECOVER_OVERPAYMENT'
    OR upper(NULLIF(btrim(COALESCE(v_selection_json->>'source_context', '')), '')) = 'PAID_RECOVERY_REQUIRED'
  );

  SELECT pay_batch_row.*
  INTO v_batch
  FROM public.pay_batches AS pay_batch_row
  WHERE pay_batch_row.id = p_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  IF p_actor_user_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.tms_users AS actor_user
      WHERE actor_user.id = p_actor_user_id
        AND COALESCE(actor_user.is_active, false) = true
    )
    INTO v_actor_valid;

    IF COALESCE(v_actor_valid, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_ACTOR_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PAYMENT_CANCELABILITY_DIAGNOSTIC_ACTOR_NOT_ALLOWED',
                'actor_user_id', p_actor_user_id::text
              )::text;
    END IF;
  END IF;

  v_resolved_scope_json := public._pay_resolve_payment_scope_for_cancel_rewind(
    p_pay_batch_id,
    v_selection_json,
    false,
    p_actor_user_id
  );

  v_scope_type := COALESCE(NULLIF(BTRIM(v_resolved_scope_json ->> 'scope_type'), ''), 'BATCH');
  v_scope_is_full := COALESCE((v_resolved_scope_json ->> 'is_full_scope')::boolean, true);

  SELECT COALESCE(array_agg(parsed_values.value_uuid ORDER BY parsed_values.value_uuid), ARRAY[]::uuid[])
  INTO v_pay_bank_transfer_ids
  FROM (
    SELECT DISTINCT raw_values.raw_value::uuid AS value_uuid
    FROM jsonb_array_elements_text(COALESCE(v_resolved_scope_json -> 'pay_bank_transfer_ids', '[]'::jsonb)) AS raw_values(raw_value)
    WHERE raw_values.raw_value ~ v_uuid_regex
  ) AS parsed_values;

  SELECT COALESCE(array_agg(parsed_values.value_uuid ORDER BY parsed_values.value_uuid), ARRAY[]::uuid[])
  INTO v_pay_batch_item_ids
  FROM (
    SELECT DISTINCT raw_values.raw_value::uuid AS value_uuid
    FROM jsonb_array_elements_text(COALESCE(v_resolved_scope_json -> 'pay_batch_item_ids', '[]'::jsonb)) AS raw_values(raw_value)
    WHERE raw_values.raw_value ~ v_uuid_regex
  ) AS parsed_values;

  SELECT COALESCE(array_agg(parsed_values.value_uuid ORDER BY parsed_values.value_uuid), ARRAY[]::uuid[])
  INTO v_candidate_ids
  FROM (
    SELECT DISTINCT raw_values.raw_value::uuid AS value_uuid
    FROM jsonb_array_elements_text(COALESCE(v_resolved_scope_json -> 'candidate_ids', '[]'::jsonb)) AS raw_values(raw_value)
    WHERE raw_values.raw_value ~ v_uuid_regex
  ) AS parsed_values;

  SELECT COALESCE(array_agg(parsed_values.value_uuid ORDER BY parsed_values.value_uuid), ARRAY[]::uuid[])
  INTO v_pay_batch_candidate_ids
  FROM (
    SELECT DISTINCT raw_values.raw_value::uuid AS value_uuid
    FROM jsonb_array_elements_text(COALESCE(v_resolved_scope_json -> 'pay_batch_candidate_ids', '[]'::jsonb)) AS raw_values(raw_value)
    WHERE raw_values.raw_value ~ v_uuid_regex
  ) AS parsed_values;

  SELECT provider_evidence.evidence_class,
         provider_evidence.provider_submitted,
         provider_evidence.provider_request_sent,
         provider_evidence.provider_response_present,
         provider_evidence.provider_event_present,
         provider_evidence.provider_external_id_present,
         provider_evidence.local_prepared_only,
         provider_evidence.cash_state,
         provider_evidence.blocker_code,
         provider_evidence.reason,
         provider_evidence.support_details_json
  INTO v_provider_evidence_class,
       v_provider_submitted,
       v_provider_request_sent,
       v_provider_response_present,
       v_provider_event_present,
       v_provider_external_id_present,
       v_local_prepared_only,
       v_provider_cash_state,
       v_provider_blocker_code,
       v_provider_reason,
       v_provider_support_details_json
  FROM public._pay_bank_transfer_provider_evidence_classify(
    p_pay_batch_id,
    NULL::uuid,
    v_resolved_scope_json,
    NULL::uuid
  ) AS provider_evidence
  LIMIT 1;

  v_provider_evidence_class := COALESCE(v_provider_evidence_class, 'NO_PROVIDER_EVIDENCE');
  v_provider_submitted := COALESCE(v_provider_submitted, false);
  v_provider_request_sent := COALESCE(v_provider_request_sent, false);
  v_provider_response_present := COALESCE(v_provider_response_present, false);
  v_provider_event_present := COALESCE(v_provider_event_present, false);
  v_provider_external_id_present := COALESCE(v_provider_external_id_present, false);
  v_local_prepared_only := COALESCE(v_local_prepared_only, true);
  v_provider_support_details_json := COALESCE(v_provider_support_details_json, '{}'::jsonb);

  v_manual_adjustment_result := public._pay_detect_manual_adjustments_for_carry_forward(
    p_pay_batch_id,
    v_resolved_scope_json,
    p_actor_user_id
  );

  v_freshness_result := public._pay_manual_adjustment_carry_forward_freshness_check(
    p_pay_batch_id,
    v_candidate_ids,
    v_pay_batch_item_ids,
    v_resolved_scope_json,
    p_actor_user_id
  );

  v_manual_carry_forward_required := COALESCE((v_manual_adjustment_result ->> 'manual_adjustment_carry_forward_required')::boolean, false);
  v_can_carry_forward_automatically := COALESCE((v_manual_adjustment_result ->> 'can_carry_forward_automatically')::boolean, true);
  v_manual_carry_forward_blocker_count := COALESCE(jsonb_array_length(COALESCE(v_manual_adjustment_result -> 'carry_forward_blockers', '[]'::jsonb)), 0);
  v_freshness_blocker_count := COALESCE(jsonb_array_length(COALESCE(v_freshness_result -> 'blockers', '[]'::jsonb)), 0);
  v_partial_scope_blocker_count := COALESCE(jsonb_array_length(COALESCE(v_resolved_scope_json -> 'partial_scope_blockers', '[]'::jsonb)), 0);

  WITH scoped_transfers AS (
    SELECT transfer_rows.*
    FROM public.pay_bank_transfers AS transfer_rows
    WHERE transfer_rows.pay_batch_id = p_pay_batch_id
      AND (
        COALESCE(array_length(v_pay_bank_transfer_ids, 1), 0) = 0
        OR transfer_rows.id = ANY(v_pay_bank_transfer_ids)
      )
  ), classified_transfers AS (
    SELECT
      scoped_transfers.id AS pay_bank_transfer_id,
      movement_rows.cash_state,
      movement_rows.is_final_money_moved,
      movement_rows.is_terminal_no_money,
      movement_rows.is_pending_non_final
    FROM scoped_transfers
    CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
      scoped_transfers.status,
      scoped_transfers.rail_state,
      COALESCE(scoped_transfers.rail_meta_json, '{}'::jsonb),
      jsonb_build_object(
        'provider_key', scoped_transfers.rail_provider,
        'rail_env', scoped_transfers.rail_env,
        'request_id', scoped_transfers.request_id,
        'rail_tx_id', scoped_transfers.rail_tx_id
      )
    ) AS movement_rows
  )
  SELECT
    count(*)::integer,
    count(*) FILTER (WHERE classified_transfers.is_final_money_moved)::integer,
    count(*) FILTER (WHERE classified_transfers.is_terminal_no_money)::integer,
    count(*) FILTER (WHERE classified_transfers.is_pending_non_final)::integer
  INTO v_transfer_count,
       v_transfer_final_count,
       v_transfer_terminal_no_money_count,
       v_transfer_pending_count
  FROM classified_transfers;

  WITH scoped_events AS (
    SELECT
      event_rows.*,
      receipt_rows.status AS receipt_status,
      receipt_rows.provider_key AS receipt_provider_key,
      receipt_rows.rail_env AS receipt_rail_env,
      receipt_rows.provider_event_key AS receipt_provider_event_key,
      receipt_rows.signature_valid AS receipt_signature_valid
    FROM public.pay_bank_transfer_events AS event_rows
    LEFT JOIN public.bank_provider_webhook_receipts AS receipt_rows
      ON receipt_rows.id = event_rows.provider_webhook_receipt_id
    WHERE event_rows.pay_batch_id = p_pay_batch_id
      AND (
        COALESCE(array_length(v_pay_bank_transfer_ids, 1), 0) = 0
        OR event_rows.pay_bank_transfer_id = ANY(v_pay_bank_transfer_ids)
        OR event_rows.pay_bank_transfer_id IS NULL
      )
  ), classified_events AS (
    SELECT
      scoped_events.id AS event_id,
      scoped_events.provider_event_transport,
      scoped_events.provider_signature_valid,
      scoped_events.provider_webhook_receipt_id,
      scoped_events.receipt_status,
      scoped_events.receipt_provider_key,
      scoped_events.receipt_rail_env,
      scoped_events.receipt_provider_event_key,
      scoped_events.receipt_signature_valid,
      scoped_events.provider_failure_reason_group,
      scoped_events.mapping_status,
      scoped_events.normalised_state,
      scoped_events.provider_state,
      movement_rows.cash_state,
      movement_rows.is_final_money_moved,
      movement_rows.is_terminal_no_money,
      movement_rows.is_pending_non_final
    FROM scoped_events
    CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
      scoped_events.normalised_state,
      scoped_events.provider_state,
      COALESCE(scoped_events.raw_payload, '{}'::jsonb),
      jsonb_build_object(
        'provider_key', scoped_events.provider_key,
        'provider_event_type', scoped_events.provider_event_type,
        'provider_event_transport', scoped_events.provider_event_transport,
        'provider_event_key', scoped_events.provider_event_key
      )
    ) AS movement_rows
  )
  SELECT
    count(*)::integer,
    count(*) FILTER (WHERE classified_events.is_final_money_moved)::integer,
    count(*) FILTER (WHERE classified_events.is_terminal_no_money)::integer,
    count(*) FILTER (WHERE classified_events.is_pending_non_final)::integer,
    count(*) FILTER (
      WHERE (
        upper(COALESCE(classified_events.normalised_state, '')) IN ('UNKNOWN', 'OUTCOME_UNKNOWN', 'PROVIDER_UNKNOWN')
        OR upper(COALESCE(classified_events.mapping_status, '')) IN ('UNMATCHED', 'AMBIGUOUS', 'REVIEW_REQUIRED')
        OR upper(COALESCE(classified_events.provider_failure_reason_group, '')) IN ('WEBHOOK_UNMATCHED', 'PROVIDER_UNKNOWN')
      )
      AND upper(COALESCE(classified_events.provider_failure_reason_group, '')) <> 'PROVIDER_OUTAGE'
    )::integer,
    count(*) FILTER (
      WHERE classified_events.provider_event_transport = 'PROVIDER_WEBHOOK'
        AND classified_events.provider_signature_valid IS DISTINCT FROM false
        AND classified_events.provider_webhook_receipt_id IS NOT NULL
        AND classified_events.receipt_signature_valid IS TRUE
        AND upper(COALESCE(classified_events.receipt_status, '')) IN ('VERIFIED', 'NORMALISED', 'NORMALIZED', 'INGESTED', 'FAILED_RETRYABLE', 'UNMATCHED_REVIEW_REQUIRED')
        AND classified_events.receipt_provider_key IS NOT DISTINCT FROM v_batch.rail_provider_snapshot
        AND classified_events.receipt_rail_env IS NOT DISTINCT FROM COALESCE(v_batch.rail_env_snapshot, 'PROD')
        AND NULLIF(btrim(COALESCE(classified_events.receipt_provider_event_key, '')), '') IS NOT NULL
    )::integer,
    count(*) FILTER (
      WHERE classified_events.provider_event_transport = 'PROVIDER_WEBHOOK'
        AND (
          classified_events.provider_signature_valid IS FALSE
          OR classified_events.provider_webhook_receipt_id IS NULL
          OR classified_events.receipt_signature_valid IS DISTINCT FROM true
          OR upper(COALESCE(classified_events.receipt_status, '')) IN ('SIGNATURE_INVALID', 'FAILED_FINAL')
          OR classified_events.receipt_provider_key IS DISTINCT FROM v_batch.rail_provider_snapshot
          OR classified_events.receipt_rail_env IS DISTINCT FROM COALESCE(v_batch.rail_env_snapshot, 'PROD')
          OR NULLIF(btrim(COALESCE(classified_events.receipt_provider_event_key, '')), '') IS NULL
        )
    )::integer,
    count(*) FILTER (
      WHERE classified_events.provider_event_transport = 'FAILED_WEBHOOK_REPLAY'
        AND classified_events.provider_webhook_receipt_id IS NOT NULL
        AND upper(COALESCE(classified_events.receipt_status, '')) NOT IN ('SIGNATURE_INVALID', 'FAILED_FINAL')
        AND classified_events.receipt_provider_key IS NOT DISTINCT FROM v_batch.rail_provider_snapshot
        AND classified_events.receipt_rail_env IS NOT DISTINCT FROM COALESCE(v_batch.rail_env_snapshot, 'PROD')
        AND NULLIF(btrim(COALESCE(classified_events.receipt_provider_event_key, '')), '') IS NOT NULL
    )::integer,
    count(*) FILTER (WHERE classified_events.provider_event_transport = 'PROVIDER_POLL')::integer,
    count(*) FILTER (
      WHERE upper(COALESCE(classified_events.provider_failure_reason_group, '')) = 'PROVIDER_OUTAGE'
        AND upper(COALESCE(classified_events.mapping_status, '')) = 'MATCHED'
    )::integer
  INTO v_event_count,
       v_event_final_count,
       v_event_terminal_no_money_count,
       v_event_pending_count,
       v_event_unknown_count,
       v_provider_webhook_evidence_count,
       v_invalid_webhook_evidence_count,
       v_failed_webhook_replay_evidence_count,
       v_provider_poll_evidence_count,
       v_provider_outage_count
  FROM classified_events;

  SELECT event_rows.provider_key,
         COALESCE(NULLIF(BTRIM(event_rows.provider_state), ''), NULLIF(BTRIM(event_rows.normalised_state), '')),
         event_rows.provider_failure_reason_code,
         event_rows.provider_failure_reason_group,
         COALESCE(event_rows.raw_payload, '{}'::jsonb)
  INTO v_failure_event_provider_key,
       v_failure_event_state,
       v_failure_event_reason_code,
       v_provider_failure_reason_group,
       v_failure_event_payload
  FROM public.pay_bank_transfer_events AS event_rows
  CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
    event_rows.normalised_state,
    event_rows.provider_state,
    COALESCE(event_rows.raw_payload, '{}'::jsonb),
    jsonb_build_object(
      'provider_key', event_rows.provider_key,
      'provider_event_type', event_rows.provider_event_type,
      'provider_event_transport', event_rows.provider_event_transport
    )
  ) AS movement_rows
  WHERE event_rows.pay_batch_id = p_pay_batch_id
    AND (
      COALESCE(array_length(v_pay_bank_transfer_ids, 1), 0) = 0
      OR event_rows.pay_bank_transfer_id = ANY(v_pay_bank_transfer_ids)
      OR event_rows.pay_bank_transfer_id IS NULL
    )
    AND (
      movement_rows.is_terminal_no_money
      OR event_rows.provider_failure_reason_group IS NOT NULL
      OR event_rows.provider_failure_reason_code IS NOT NULL
    )
  ORDER BY event_rows.received_at_utc DESC, event_rows.id DESC
  LIMIT 1;

  IF v_failure_event_provider_key IS NOT NULL OR v_failure_event_state IS NOT NULL OR v_failure_event_reason_code IS NOT NULL OR v_provider_failure_reason_group IS NOT NULL THEN
    v_provider_failure_reason_result := public._banking_provider_failure_reason_normalise(
      v_failure_event_provider_key,
      v_failure_event_state,
      v_failure_event_reason_code,
      v_provider_failure_reason_group,
      COALESCE(v_failure_event_payload, '{}'::jsonb)
    );
    v_provider_failure_reason_code := COALESCE(v_failure_event_reason_code, v_provider_failure_reason_result ->> 'failure_reason_code');
    v_provider_failure_reason_group := COALESCE(NULLIF(v_provider_failure_reason_group, ''), v_provider_failure_reason_result ->> 'failure_reason_group');
    v_provider_failure_reason_label := v_provider_failure_reason_result ->> 'failure_reason_label';
  END IF;

  SELECT
    count(*) FILTER (WHERE correction_work_items.work_kind = 'PRE_BANK_CANCEL' AND correction_work_items.status = 'APPLIED')::integer,
    count(*) FILTER (WHERE correction_work_items.work_kind = 'NO_MONEY_UNWIND' AND correction_work_items.status = 'APPLIED')::integer
  INTO v_pre_bank_applied_count,
       v_no_money_applied_count
  FROM public.pay_payment_correction_work_items AS correction_work_items
  WHERE correction_work_items.pay_batch_id = p_pay_batch_id
    AND (
      COALESCE(array_length(v_pay_bank_transfer_ids, 1), 0) = 0
      OR correction_work_items.pay_bank_transfer_id = ANY(v_pay_bank_transfer_ids)
      OR correction_work_items.pay_bank_transfer_id IS NULL
    );

  SELECT EXISTS (
           SELECT 1
           FROM public.pay_payment_correction_requests AS recovery_request
           WHERE recovery_request.pay_batch_id = p_pay_batch_id
             AND upper(BTRIM(COALESCE(recovery_request.status::text, ''))) IN ('REQUESTED', 'AWAITING_AUTHORISATION', 'AUTHORISED', 'EXPANDED', 'PROCESSING', 'APPLIED', 'COMPLETE', 'COMPLETED')
             AND upper(BTRIM(COALESCE(recovery_request.correction_kind::text, ''))) IN ('PAID_RECOVERY_REQUIRED', 'PAID_SETTLED_RECOVERY_REQUIRED', 'AMEND_AND_RECOVER_OVERPAYMENT', 'OVERPAYMENT_RECOVERY', 'SETTLED_REVERSAL', 'POST_PAYMENT_AMENDMENT')
         )
         OR EXISTS (
           SELECT 1
           FROM public.pay_payment_correction_items AS recovery_item
           WHERE recovery_item.pay_batch_id = p_pay_batch_id
             AND upper(BTRIM(COALESCE(recovery_item.status::text, ''))) IN ('PENDING', 'APPROVED', 'AUTHORISED', 'APPLIED', 'PROCESSING')
             AND upper(BTRIM(COALESCE(recovery_item.correction_item_kind::text, ''))) IN ('SETTLED_REVERSAL', 'OVERPAYMENT_RECOVERY', 'PAID_RECOVERY', 'POST_PAYMENT_AMENDMENT')
         )
         OR EXISTS (
           SELECT 1
           FROM public.pay_batch_items AS recovery_batch_item
           JOIN public.pay_batch_candidates AS recovery_batch_candidate
             ON recovery_batch_candidate.id = recovery_batch_item.pay_batch_candidate_id
           WHERE recovery_batch_candidate.pay_batch_id = p_pay_batch_id
             AND COALESCE(recovery_batch_item.is_voided, false) = false
             AND upper(BTRIM(COALESCE(recovery_batch_item.item_type::text, ''))) = 'OVERPAYMENT_RECOVERY'
             AND COALESCE(recovery_batch_item.amount_inc_vat, recovery_batch_item.amount_ex_vat, 0) <> 0
         )
         OR upper(NULLIF(BTRIM(COALESCE(v_selection_json->>'source_context', '')), '')) IN ('PAID_RECOVERY_REQUIRED', 'POST_PAYMENT_AMENDMENT', 'OVERPAYMENT_RECOVERY')
  INTO v_has_actual_recovery_context;

  v_has_actual_recovery_context := COALESCE(v_has_actual_recovery_context, false);

  SELECT count(*)::integer
  INTO v_open_provider_submit_count
  FROM public.banking_pay_operations AS provider_operations
  WHERE provider_operations.pay_batch_id = p_pay_batch_id
    AND provider_operations.operation_type IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
    AND provider_operations.status IN ('QUEUED', 'RUNNING', 'PROCESSING', 'CLAIMED', 'IN_PROGRESS');

  v_transfer_count := COALESCE(v_transfer_count, 0);
  v_transfer_final_count := COALESCE(v_transfer_final_count, 0);
  v_transfer_terminal_no_money_count := COALESCE(v_transfer_terminal_no_money_count, 0);
  v_transfer_pending_count := COALESCE(v_transfer_pending_count, 0);
  v_event_count := COALESCE(v_event_count, 0);
  v_event_final_count := COALESCE(v_event_final_count, 0);
  v_event_terminal_no_money_count := COALESCE(v_event_terminal_no_money_count, 0);
  v_event_pending_count := COALESCE(v_event_pending_count, 0);
  v_event_unknown_count := COALESCE(v_event_unknown_count, 0);
  v_provider_webhook_evidence_count := COALESCE(v_provider_webhook_evidence_count, 0);
  v_invalid_webhook_evidence_count := COALESCE(v_invalid_webhook_evidence_count, 0);
  v_failed_webhook_replay_evidence_count := COALESCE(v_failed_webhook_replay_evidence_count, 0);
  v_provider_poll_evidence_count := COALESCE(v_provider_poll_evidence_count, 0);
  v_provider_outage_count := COALESCE(v_provider_outage_count, 0);
  v_pre_bank_applied_count := COALESCE(v_pre_bank_applied_count, 0);
  v_no_money_applied_count := COALESCE(v_no_money_applied_count, 0);
  v_open_provider_submit_count := COALESCE(v_open_provider_submit_count, 0);

  v_final_evidence_count := v_transfer_final_count + v_event_final_count;
  v_terminal_no_money_count := v_transfer_terminal_no_money_count + v_event_terminal_no_money_count;
  v_pending_provider_count := v_transfer_pending_count + v_event_pending_count + CASE WHEN v_provider_submitted OR v_provider_request_sent THEN 1 ELSE 0 END;
  v_unknown_provider_count := v_event_unknown_count + CASE
    WHEN v_provider_outage_count > 0 OR v_provider_blocker_code = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 0
    WHEN v_provider_evidence_class = 'PROVIDER_OUTCOME_UNKNOWN' OR v_provider_blocker_code = 'PAYMENT_OUTCOME_UNKNOWN_CHECK_PROVIDER' THEN 1
    ELSE 0
  END;

  v_has_paid_or_settled := v_final_evidence_count > 0 OR upper(COALESCE(v_provider_cash_state, '')) = 'FINAL_PAID';
  v_has_provider_unknown := v_unknown_provider_count > 0;
  v_has_provider_pending := v_pending_provider_count > 0 AND v_terminal_no_money_count = 0 AND v_final_evidence_count = 0;
  v_has_provider_outage := v_provider_outage_count > 0 OR v_provider_blocker_code = 'PROVIDER_OUTAGE_RETRY_LATER';
  v_has_terminal_no_money := v_terminal_no_money_count > 0 OR upper(COALESCE(v_provider_cash_state, '')) = 'TERMINAL_NO_MONEY';
  v_is_local_not_sent := v_has_paid_or_settled IS NOT TRUE
                          AND v_has_provider_unknown IS NOT TRUE
                          AND v_has_provider_pending IS NOT TRUE
                          AND v_has_terminal_no_money IS NOT TRUE
                          AND v_provider_submitted IS NOT TRUE
                          AND v_provider_request_sent IS NOT TRUE
                          AND v_provider_response_present IS NOT TRUE
                          AND v_provider_event_present IS NOT TRUE
                          AND v_provider_external_id_present IS NOT TRUE;

  IF COALESCE(v_has_paid_or_settled, false) IS TRUE
     AND COALESCE(v_has_terminal_no_money, false) IS TRUE THEN
    v_has_actual_recovery_context := true;
  END IF;

  IF v_partial_scope_blocker_count > 0 THEN
    v_blockers := v_blockers || COALESCE(v_resolved_scope_json -> 'partial_scope_blockers', '[]'::jsonb);
  END IF;

  IF v_freshness_blocker_count > 0 THEN
    v_blockers := v_blockers || COALESCE(v_freshness_result -> 'blockers', '[]'::jsonb);
  END IF;

  IF v_manual_carry_forward_blocker_count > 0 OR v_can_carry_forward_automatically IS NOT TRUE THEN
    v_blockers := v_blockers || COALESCE(v_manual_adjustment_result -> 'carry_forward_blockers', '[]'::jsonb);
  END IF;

  IF v_open_provider_submit_count > 0 THEN
    v_race_or_submission_blockers := v_race_or_submission_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'PROVIDER_SUBMISSION_IN_PROGRESS',
      'message', 'Provider submission is in progress for this batch.'
    ));
    v_blockers := v_blockers || v_race_or_submission_blockers;
  END IF;

  IF v_has_paid_or_settled AND COALESCE(v_has_actual_recovery_context, false) THEN
    v_lifecycle_state := 'PAID_OR_SETTLED';
    v_lifecycle_label := 'Recover overpayment in next pay run';
    v_recommended_action := 'AMEND_AND_RECOVER_OVERPAYMENT';
  ELSIF v_has_provider_unknown THEN
    v_lifecycle_state := 'PROVIDER_OUTCOME_UNKNOWN';
    v_lifecycle_label := 'Provider outcome unknown — check provider';
    v_recommended_action := 'CHECK_PROVIDER_STATUS';
  ELSIF v_has_paid_or_settled THEN
    v_lifecycle_state := 'PAID_OR_SETTLED';
    v_lifecycle_label := CASE WHEN upper(COALESCE(v_batch.status, '')) = 'SETTLED' THEN 'Settled' ELSE 'Paid' END;
    v_recommended_action := 'VIEW_DETAILS';
  ELSIF v_has_provider_pending THEN
    v_lifecycle_state := 'PROVIDER_SUBMITTED_PENDING';
    v_lifecycle_label := 'Provider pending';
    v_recommended_action := 'CHECK_PROVIDER_STATUS';
  ELSIF v_has_provider_outage
        AND COALESCE(v_provider_request_sent, false) IS NOT TRUE
        AND COALESCE(v_provider_submitted, false) IS NOT TRUE
        AND COALESCE(v_provider_external_id_present, false) IS NOT TRUE
        AND COALESCE(jsonb_array_length(v_blockers), 0) = 0 THEN
    v_lifecycle_state := 'PROVIDER_OUTAGE_RETRY_LATER';
    v_lifecycle_label := 'Bank unavailable — unsent payments can be retried';
    v_recommended_action := 'RETRY_PROVIDER_LATER';
  ELSIF v_no_money_applied_count > 0 THEN
    v_lifecycle_state := 'FINANCIALS_REWOUND';
    v_lifecycle_label := 'Financials rewound — amend timesheet and recalculate';
    v_recommended_action := 'VIEW_RECALCULATE_NEXT_STEP';
  ELSIF v_has_terminal_no_money THEN
    IF upper(COALESCE(v_failure_event_state, '')) IN ('CANCELLED', 'CANCELED') THEN
      v_lifecycle_state := 'PROVIDER_CANCELLED_NO_MONEY';
    ELSE
      v_lifecycle_state := 'PROVIDER_FAILED_NO_MONEY';
    END IF;
    v_lifecycle_label := 'Failed — not paid';
    v_recommended_action := 'NO_MONEY_UNWIND_AND_RECALCULATE';
  ELSIF v_pre_bank_applied_count > 0 THEN
    IF v_scope_type = 'BATCH' THEN
      v_lifecycle_state := 'CANCELLED_BEFORE_BANK_SUBMISSION';
      v_lifecycle_label := 'Cancelled before bank submission';
    ELSE
      v_lifecycle_state := 'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION';
      v_lifecycle_label := 'Partially cancelled before bank submission';
    END IF;
    v_recommended_action := 'VIEW_RECALCULATE_NEXT_STEP';
  ELSIF v_is_local_not_sent THEN
    IF upper(COALESCE(v_batch.status, '')) = 'SCHEDULED' OR v_batch.scheduled_at_utc IS NOT NULL THEN
      v_lifecycle_state := 'SCHEDULED_LOCAL_NOT_SENT';
      v_lifecycle_label := 'Scheduled — not sent to bank yet';
    ELSE
      v_lifecycle_state := 'LOCAL_PREPARED_NOT_SENT';
      v_lifecycle_label := 'Prepared locally — not sent to bank yet';
    END IF;
    v_recommended_action := 'PRE_PROVIDER_CANCEL_AND_RECALCULATE';
  ELSE
    v_lifecycle_state := 'PROVIDER_OUTCOME_UNKNOWN';
    v_lifecycle_label := 'Provider outcome unknown — check provider';
    v_recommended_action := 'CHECK_PROVIDER_STATUS';
  END IF;

  v_can_pre_provider_cancel := v_lifecycle_state IN ('LOCAL_PREPARED_NOT_SENT', 'SCHEDULED_LOCAL_NOT_SENT')
                               AND v_scope_is_full
                               AND COALESCE(jsonb_array_length(v_blockers), 0) = 0;
  v_can_no_money_unwind := v_lifecycle_state IN ('PROVIDER_CANCELLED_NO_MONEY', 'PROVIDER_FAILED_NO_MONEY')
                           AND v_scope_is_full
                           AND COALESCE(jsonb_array_length(v_blockers), 0) = 0;
  v_can_recover_overpayment := v_lifecycle_state = 'PAID_OR_SETTLED' AND COALESCE(v_has_actual_recovery_context, false);
  v_requires_provider_cancel := v_provider_submitted OR v_provider_request_sent;
  v_requires_bank_check := v_lifecycle_state IN ('PROVIDER_OUTCOME_UNKNOWN', 'PROVIDER_SUBMITTED_PENDING');
  v_requires_retry_later := v_lifecycle_state = 'PROVIDER_OUTAGE_RETRY_LATER';
  v_whole_batch_cancel_available := v_can_pre_provider_cancel AND v_scope_type = 'BATCH';
  v_row_cancel_available := v_can_pre_provider_cancel AND v_scope_type <> 'BATCH';
  v_retry_same_batch_safe := v_lifecycle_state = 'PROVIDER_OUTAGE_RETRY_LATER'
                             AND v_provider_request_sent IS NOT TRUE
                             AND v_provider_submitted IS NOT TRUE
                             AND v_provider_external_id_present IS NOT TRUE
                             AND COALESCE(jsonb_array_length(v_blockers), 0) = 0;

  v_provider_evidence_summary_json := jsonb_build_object(
    'evidence_class', v_provider_evidence_class,
    'provider_submitted', v_provider_submitted,
    'provider_request_sent', v_provider_request_sent,
    'provider_response_present', v_provider_response_present,
    'provider_event_present', v_provider_event_present,
    'provider_external_id_present', v_provider_external_id_present,
    'local_prepared_only', v_local_prepared_only,
    'cash_state', v_provider_cash_state,
    'provider_webhook_evidence_count', v_provider_webhook_evidence_count,
    'invalid_webhook_evidence_count', v_invalid_webhook_evidence_count,
    'failed_webhook_replay_evidence_count', v_failed_webhook_replay_evidence_count,
    'provider_poll_evidence_count', v_provider_poll_evidence_count,
    'support_details_json', v_provider_support_details_json
  );

  v_blocking_paid_evidence_json := jsonb_build_object(
    'has_paid_or_settled', v_has_paid_or_settled,
    'final_evidence_count', v_final_evidence_count,
    'transfer_final_count', v_transfer_final_count,
    'event_final_count', v_event_final_count
  );

  v_terminal_no_money_evidence_json := jsonb_build_object(
    'has_terminal_no_money', v_has_terminal_no_money,
    'terminal_no_money_count', v_terminal_no_money_count,
    'transfer_terminal_no_money_count', v_transfer_terminal_no_money_count,
    'event_terminal_no_money_count', v_event_terminal_no_money_count,
    'provider_failure_reason_code', v_provider_failure_reason_code,
    'provider_failure_reason_group', v_provider_failure_reason_group,
    'provider_failure_reason_label', v_provider_failure_reason_label
  );

  v_pending_provider_evidence_json := jsonb_build_object(
    'has_provider_pending', v_has_provider_pending,
    'pending_provider_count', v_pending_provider_count,
    'transfer_pending_count', v_transfer_pending_count,
    'event_pending_count', v_event_pending_count
  );

  v_provider_outcome_unknown_evidence_json := jsonb_build_object(
    'has_provider_unknown', v_has_provider_unknown,
    'unknown_provider_count', v_unknown_provider_count,
    'event_unknown_count', v_event_unknown_count,
    'provider_blocker_code', v_provider_blocker_code,
    'provider_reason', v_provider_reason
  );

  v_provider_webhook_evidence_json := jsonb_build_object(
    'provider_webhook_evidence_count', v_provider_webhook_evidence_count,
    'invalid_webhook_evidence_count', v_invalid_webhook_evidence_count,
    'failed_webhook_replay_evidence_count', v_failed_webhook_replay_evidence_count,
    'provider_poll_evidence_count', v_provider_poll_evidence_count,
    'event_count', v_event_count
  );

  v_finance_scope_json := jsonb_build_object(
    'finance_case_ids', COALESCE(v_resolved_scope_json -> 'finance_case_ids', '[]'::jsonb),
    'finance_component_ids', COALESCE(v_resolved_scope_json -> 'finance_component_ids', '[]'::jsonb),
    'reservation_ids', COALESCE(v_resolved_scope_json -> 'reservation_ids', '[]'::jsonb)
  );

  v_alert_candidate_is_success_only := v_lifecycle_state = 'PAID_OR_SETTLED'
    AND COALESCE(v_has_actual_recovery_context, false) IS NOT TRUE;
  v_alert_candidate_kind := CASE
    WHEN v_alert_candidate_is_success_only THEN NULL::text
    WHEN v_lifecycle_state = 'PAID_OR_SETTLED' AND v_recommended_action = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN 'PAID_SETTLED_RECOVERY_REQUIRED'
    WHEN v_lifecycle_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'PROVIDER_OUTAGE_RETRY_LATER'
    WHEN v_lifecycle_state = 'PROVIDER_OUTCOME_UNKNOWN' THEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
    WHEN v_lifecycle_state IN ('PROVIDER_CANCELLED_NO_MONEY', 'PROVIDER_FAILED_NO_MONEY') THEN 'TERMINAL_NO_MONEY_REWIND_AVAILABLE'
    WHEN v_lifecycle_state = 'PROVIDER_SUBMITTED_PENDING' THEN NULL::text
    WHEN v_manual_carry_forward_blocker_count > 0 THEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
    ELSE NULL::text
  END;

  v_alert_candidate_severity := CASE
    WHEN v_alert_candidate_kind IN ('PROVIDER_OUTAGE_RETRY_LATER', 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER', 'TERMINAL_NO_MONEY_REWIND_AVAILABLE', 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS', 'PAID_SETTLED_RECOVERY_REQUIRED') THEN 'ACTION_REQUIRED'
    ELSE NULL::text
  END;

  v_status_update_signature := md5(jsonb_build_object(
    'pay_batch_id', p_pay_batch_id::text,
    'scope_type', v_scope_type,
    'lifecycle_state', v_lifecycle_state,
    'recommended_action', v_recommended_action,
    'final_evidence_count', v_final_evidence_count,
    'terminal_no_money_count', v_terminal_no_money_count,
    'pending_provider_count', v_pending_provider_count,
    'unknown_provider_count', v_unknown_provider_count,
    'pre_bank_applied_count', v_pre_bank_applied_count,
    'no_money_applied_count', v_no_money_applied_count
  )::text);

  v_support_details_json := jsonb_build_object(
    'batch_status', v_batch.status,
    'scope_type', v_scope_type,
    'scope_is_full', v_scope_is_full,
    'transfer_count', v_transfer_count,
    'event_count', v_event_count,
    'pre_bank_applied_count', v_pre_bank_applied_count,
    'no_money_applied_count', v_no_money_applied_count,
    'open_provider_submit_count', v_open_provider_submit_count,
    'actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END
  );

  v_result := jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'selection_json', v_selection_json,
    'scope_type', v_scope_type,
    'payment_lifecycle_state', v_lifecycle_state,
    'payment_lifecycle_label', v_lifecycle_label,
    'recommended_action', v_recommended_action,
    'next_step', CASE WHEN v_lifecycle_state IN ('FINANCIALS_REWOUND', 'CANCELLED_BEFORE_BANK_SUBMISSION', 'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION') THEN 'AMEND_TIMESHEET_AND_RECALCULATE' ELSE NULL::text END,
    'next_step_label', CASE WHEN v_lifecycle_state IN ('FINANCIALS_REWOUND', 'CANCELLED_BEFORE_BANK_SUBMISSION', 'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION') THEN 'Amend timesheets and recalculate' ELSE NULL::text END,
    'can_pre_provider_cancel', v_can_pre_provider_cancel,
    'can_no_money_unwind', v_can_no_money_unwind,
    'can_recover_overpayment', v_can_recover_overpayment,
    'requires_provider_cancel', v_requires_provider_cancel,
    'requires_bank_check', v_requires_bank_check,
    'requires_retry_later', v_requires_retry_later,
    'whole_batch_cancel_available', v_whole_batch_cancel_available,
    'row_cancel_available', v_row_cancel_available,
    'retry_same_batch_safe', v_retry_same_batch_safe,
    'retry_status_label', CASE WHEN v_lifecycle_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Bank unavailable — unsent payments can be retried' ELSE NULL::text END,
    'retry_row_label', CASE WHEN v_lifecycle_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Bank unavailable — retry available' ELSE NULL::text END,
    'retry_button_label', CASE WHEN v_lifecycle_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Retry unsent payments' ELSE NULL::text END,
    'retry_running_label', CASE WHEN v_lifecycle_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Retrying unsent payments' ELSE NULL::text END,
    'retry_disabled_button_label', CASE WHEN v_lifecycle_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Retry in progress' ELSE NULL::text END,
    'retry_row_action_label', CASE WHEN v_lifecycle_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Open retry summary' ELSE NULL::text END,
    'paid_recovery_label', CASE WHEN v_lifecycle_state = 'PAID_OR_SETTLED' AND COALESCE(v_has_actual_recovery_context, false) THEN 'Recover overpayment in next pay run' ELSE NULL::text END,
    'has_actual_recovery_context', COALESCE(v_has_actual_recovery_context, false)
  );

  v_result := v_result || jsonb_build_object(
    'provider_evidence_summary_json', v_provider_evidence_summary_json,
    'blocking_paid_evidence_json', v_blocking_paid_evidence_json,
    'terminal_no_money_evidence_json', v_terminal_no_money_evidence_json,
    'pending_provider_evidence_json', v_pending_provider_evidence_json,
    'provider_outcome_unknown_evidence_json', v_provider_outcome_unknown_evidence_json,
    'provider_webhook_evidence_json', v_provider_webhook_evidence_json,
    'resolved_full_payment_scope_json', v_resolved_scope_json,
    'finance_scope_json', v_finance_scope_json,
    'manual_adjustment_carry_forward_required', v_manual_carry_forward_required,
    'manual_adjustments_to_carry_forward', COALESCE(v_manual_adjustment_result -> 'manual_adjustments_to_carry_forward', '[]'::jsonb),
    'manual_adjustments_carried_forward_existing', COALESCE(v_manual_adjustment_result -> 'manual_adjustments_carried_forward_existing', '[]'::jsonb),
    'can_carry_forward_automatically', v_can_carry_forward_automatically
  );

  v_result := v_result || jsonb_build_object(
    'carry_forward_blockers', COALESCE(v_manual_adjustment_result -> 'carry_forward_blockers', '[]'::jsonb),
    'manual_adjustment_support_details_json', COALESCE(v_manual_adjustment_result -> 'manual_adjustment_support_details_json', '{}'::jsonb),
    'race_or_submission_blockers', v_race_or_submission_blockers,
    'blockers', v_blockers,
    'warnings', v_warnings,
    'support_details_json', v_support_details_json,
    'provider_failure_reason_code', v_provider_failure_reason_code,
    'provider_failure_reason_group', v_provider_failure_reason_group,
    'provider_failure_reason_label', v_provider_failure_reason_label,
    'status_update_signature', v_status_update_signature,
    'verified_webhook_evidence_count', v_provider_webhook_evidence_count,
    'invalid_webhook_evidence_count', v_invalid_webhook_evidence_count,
    'failed_webhook_replay_evidence_count', v_failed_webhook_replay_evidence_count,
    'alert_candidate_kind', v_alert_candidate_kind,
    'alert_candidate_severity', v_alert_candidate_severity,
    'alert_candidate_is_success_only', v_alert_candidate_is_success_only
  );

  RETURN v_result;
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_payment_cancel_not_sent_and_recalculate(
  p_pay_batch_id uuid,
  p_selection_json jsonb DEFAULT '{}'::jsonb,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_reason text DEFAULT NULL::text,
  p_idempotency_key text DEFAULT NULL::text,
  p_confirmation_json jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_uuid_regex text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_selection_json jsonb := '{}'::jsonb;
  v_confirmation_json jsonb := '{}'::jsonb;
  v_diagnostic_json jsonb := '{}'::jsonb;
  v_resolved_scope_json jsonb := '{}'::jsonb;
  v_lifecycle_state text := NULL::text;
  v_recommended_action text := NULL::text;
  v_blockers jsonb := '[]'::jsonb;
  v_race_blockers jsonb := '[]'::jsonb;
  v_effective_selection_json jsonb := '{}'::jsonb;
  v_selection_hash text := NULL::text;
  v_plan_json jsonb := '{}'::jsonb;
  v_plan_hash text := NULL::text;
  v_accepted_resolution_json jsonb := '{}'::jsonb;
  v_accepted_resolution_hash text := NULL::text;
  v_required_quantity integer := 1;
  v_reason text := NULL::text;
  v_existing_request public.pay_payment_correction_requests%ROWTYPE;
  v_request public.pay_payment_correction_requests%ROWTYPE;
  v_expand_result jsonb := '{}'::jsonb;
  v_process_result jsonb := '{}'::jsonb;
  v_signal_result jsonb := '{}'::jsonb;
  v_idempotency_key text := NULL::text;
  v_scope_type text := NULL::text;
  v_actor_valid boolean := false;
  v_is_complete boolean := false;
  v_grouped_alert_updates jsonb := '[]'::jsonb;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_BATCH_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CANCEL_NOT_SENT_BATCH_REQUIRED')::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CANCEL_NOT_SENT_ACTOR_REQUIRED')::text;
  END IF;

  IF p_selection_json IS NOT NULL AND COALESCE(jsonb_typeof(p_selection_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_SELECTION_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CANCEL_NOT_SENT_SELECTION_MUST_BE_OBJECT')::text;
  END IF;

  IF p_confirmation_json IS NOT NULL AND COALESCE(jsonb_typeof(p_confirmation_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_CONFIRMATION_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CANCEL_NOT_SENT_CONFIRMATION_MUST_BE_OBJECT')::text;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.tms_users AS actor_user
    WHERE actor_user.id = p_actor_user_id
      AND COALESCE(actor_user.is_active, false) = true
  )
  INTO v_actor_valid;

  IF COALESCE(v_actor_valid, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_ACTOR_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CANCEL_NOT_SENT_ACTOR_NOT_ALLOWED', 'actor_user_id', p_actor_user_id::text)::text;
  END IF;

  v_selection_json := COALESCE(p_selection_json, '{}'::jsonb);
  v_confirmation_json := COALESCE(p_confirmation_json, '{}'::jsonb);
  v_reason := NULLIF(BTRIM(COALESCE(p_reason, '')), '');

  v_diagnostic_json := public.pay_payment_cancelability_diagnostic(p_pay_batch_id, v_selection_json, p_actor_user_id);
  v_lifecycle_state := v_diagnostic_json ->> 'payment_lifecycle_state';
  v_recommended_action := v_diagnostic_json ->> 'recommended_action';
  v_blockers := COALESCE(v_diagnostic_json -> 'blockers', '[]'::jsonb);
  v_race_blockers := COALESCE(v_diagnostic_json -> 'race_or_submission_blockers', '[]'::jsonb);
  v_resolved_scope_json := COALESCE(v_diagnostic_json -> 'resolved_full_payment_scope_json', '{}'::jsonb);
  v_scope_type := COALESCE(NULLIF(BTRIM(v_resolved_scope_json ->> 'scope_type'), ''), 'BATCH');

  IF v_lifecycle_state NOT IN ('LOCAL_PREPARED_NOT_SENT', 'SCHEDULED_LOCAL_NOT_SENT')
     OR v_recommended_action IS DISTINCT FROM 'PRE_PROVIDER_CANCEL_AND_RECALCULATE' THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_NOT_AVAILABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_NOT_SENT_NOT_AVAILABLE',
              'pay_batch_id', p_pay_batch_id::text,
              'payment_lifecycle_state', v_lifecycle_state,
              'recommended_action', v_recommended_action,
              'diagnostic_json', v_diagnostic_json
            )::text;
  END IF;

  IF COALESCE(jsonb_array_length(v_blockers), 0) > 0 OR COALESCE(jsonb_array_length(v_race_blockers), 0) > 0 THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CANCEL_NOT_SENT_BLOCKED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CANCEL_NOT_SENT_BLOCKED',
              'pay_batch_id', p_pay_batch_id::text,
              'blockers', v_blockers,
              'race_or_submission_blockers', v_race_blockers
            )::text;
  END IF;

  v_effective_selection_json := v_selection_json
    || jsonb_build_object(
      'requested_action', 'PRE_PROVIDER_CANCEL_AND_RECALCULATE',
      'correction_kind', 'PRE_BANK_CANCEL',
      'scope_type', v_scope_type,
      'pay_batch_id', p_pay_batch_id::text,
      'pay_batch_item_ids', COALESCE(v_resolved_scope_json -> 'pay_batch_item_ids', '[]'::jsonb),
      'expected_pay_batch_item_ids', COALESCE(v_resolved_scope_json -> 'pay_batch_item_ids', '[]'::jsonb),
      'pay_bank_transfer_ids', COALESCE(v_resolved_scope_json -> 'pay_bank_transfer_ids', '[]'::jsonb),
      'pay_batch_candidate_ids', COALESCE(v_resolved_scope_json -> 'pay_batch_candidate_ids', '[]'::jsonb)
    )
    || jsonb_build_object(
      'candidate_ids', COALESCE(v_resolved_scope_json -> 'candidate_ids', '[]'::jsonb),
      'finance_case_ids', COALESCE(v_resolved_scope_json -> 'finance_case_ids', '[]'::jsonb),
      'finance_component_ids', COALESCE(v_resolved_scope_json -> 'finance_component_ids', '[]'::jsonb),
      'reservation_ids', COALESCE(v_resolved_scope_json -> 'reservation_ids', '[]'::jsonb),
      'manual_adjustments_to_carry_forward', COALESCE(v_diagnostic_json -> 'manual_adjustments_to_carry_forward', '[]'::jsonb),
      'manual_adjustments_carried_forward_existing', COALESCE(v_diagnostic_json -> 'manual_adjustments_carried_forward_existing', '[]'::jsonb)
    );

  v_selection_hash := md5(v_effective_selection_json::text);
  v_idempotency_key := COALESCE(NULLIF(BTRIM(COALESCE(p_idempotency_key, '')), ''), md5(jsonb_build_object(
    'pay_batch_id', p_pay_batch_id::text,
    'selection_hash', v_selection_hash,
    'action', 'PRE_PROVIDER_CANCEL_AND_RECALCULATE',
    'actor_user_id', p_actor_user_id::text
  )::text));

  SELECT GREATEST(COALESCE(settings_row.payment_authoriser_quantity, 1), 1)
  INTO v_required_quantity
  FROM public.settings_defaults AS settings_row
  ORDER BY settings_row.id
  LIMIT 1;

  v_required_quantity := GREATEST(COALESCE(v_required_quantity, 1), 1);

  v_plan_json := jsonb_build_object(
    'classification', v_lifecycle_state,
    'payment_lifecycle_state', v_lifecycle_state,
    'recommended_action', v_recommended_action,
    'resolved_full_payment_scope_json', v_resolved_scope_json,
    'finance_scope_json', COALESCE(v_diagnostic_json -> 'finance_scope_json', '{}'::jsonb),
    'provider_evidence', COALESCE(v_diagnostic_json -> 'provider_evidence_summary_json', '{}'::jsonb),
    'manual_adjustments_to_carry_forward', COALESCE(v_diagnostic_json -> 'manual_adjustments_to_carry_forward', '[]'::jsonb),
    'manual_adjustments_carried_forward_existing', COALESCE(v_diagnostic_json -> 'manual_adjustments_carried_forward_existing', '[]'::jsonb),
    'work_expansion_plan', jsonb_build_object('work_unit', CASE WHEN jsonb_array_length(COALESCE(v_resolved_scope_json -> 'pay_bank_transfer_ids', '[]'::jsonb)) > 0 THEN 'TRANSFER' ELSE 'CANDIDATE_PAYEE' END, 'chunk_size', 50),
    'idempotency_key', v_idempotency_key
  );

  v_plan_hash := md5(v_plan_json::text);

  v_accepted_resolution_json := jsonb_build_object(
    'accepted_action', 'PRE_PROVIDER_CANCEL_AND_RECALCULATE',
    'accepted_at_utc', now(),
    'accepted_by_user_id', p_actor_user_id::text,
    'reason', v_reason,
    'confirmation_json', v_confirmation_json,
    'diagnostic_json', v_diagnostic_json,
    'idempotency_key', v_idempotency_key
  );

  v_accepted_resolution_hash := md5(v_accepted_resolution_json::text);

  SELECT request_rows.*
  INTO v_existing_request
  FROM public.pay_payment_correction_requests AS request_rows
  WHERE request_rows.pay_batch_id = p_pay_batch_id
    AND request_rows.selection_hash = v_selection_hash
    AND request_rows.correction_kind = 'PRE_BANK_CANCEL'
    AND request_rows.status IN ('REQUESTED', 'AWAITING_AUTHORISATION', 'AUTHORISED', 'EXPANDED', 'PROCESSING')
  ORDER BY request_rows.created_at_utc
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    UPDATE public.pay_payment_correction_requests AS request_to_authorise
    SET status = CASE WHEN request_to_authorise.status IN ('REQUESTED', 'AWAITING_AUTHORISATION') THEN 'AUTHORISED' ELSE request_to_authorise.status END,
        approved_count = GREATEST(COALESCE(request_to_authorise.approved_count, 0), COALESCE(request_to_authorise.required_quantity, v_required_quantity, 1)),
        authorised_at_utc = COALESCE(request_to_authorise.authorised_at_utc, now()),
        accepted_resolution_json = COALESCE(request_to_authorise.accepted_resolution_json, v_accepted_resolution_json),
        accepted_resolution_hash = COALESCE(request_to_authorise.accepted_resolution_hash, v_accepted_resolution_hash),
        updated_at_utc = now()
    WHERE request_to_authorise.id = v_existing_request.id
    RETURNING request_to_authorise.*
    INTO v_request;
  ELSE
    BEGIN
      INSERT INTO public.pay_payment_correction_requests (
        pay_batch_id,
        correction_kind,
        status,
        requested_by_user_id,
        requested_at_utc,
        required_quantity,
        approved_count,
        golden_key_used,
        golden_key_user_id,
        reason,
        selection_json,
        selection_hash,
        plan_json,
        plan_hash,
        accepted_resolution_json,
        accepted_resolution_hash,
        source_bank_event_id,
        auto_requested,
        created_at_utc,
        authorised_at_utc,
        applied_at_utc,
        cancelled_at_utc,
        updated_at_utc
      )
      VALUES (
        p_pay_batch_id,
        'PRE_BANK_CANCEL',
        'AUTHORISED',
        p_actor_user_id,
        now(),
        v_required_quantity,
        v_required_quantity,
        false,
        NULL::uuid,
        v_reason,
        v_effective_selection_json,
        v_selection_hash,
        v_plan_json,
        v_plan_hash,
        v_accepted_resolution_json,
        v_accepted_resolution_hash,
        NULL::uuid,
        false,
        now(),
        now(),
        NULL::timestamptz,
        NULL::timestamptz,
        now()
      )
      RETURNING public.pay_payment_correction_requests.*
      INTO v_request;

      INSERT INTO public.pay_payment_correction_actions (
        correction_request_id,
        pay_batch_id,
        actor_kind,
        actor_user_id,
        action,
        action_at_utc,
        note,
        before_json,
        after_json,
        metadata_json
      )
      VALUES (
        v_request.id,
        p_pay_batch_id,
        'USER',
        p_actor_user_id,
        'REQUEST',
        now(),
        v_reason,
        NULL::jsonb,
        to_jsonb(v_request),
        jsonb_build_object(
          'requested_action', 'PRE_PROVIDER_CANCEL_AND_RECALCULATE',
          'correction_kind', 'PRE_BANK_CANCEL',
          'selection_hash', v_selection_hash,
          'idempotency_key', v_idempotency_key
        )
      );
    EXCEPTION WHEN unique_violation THEN
      SELECT request_rows.*
      INTO v_request
      FROM public.pay_payment_correction_requests AS request_rows
      WHERE request_rows.pay_batch_id = p_pay_batch_id
        AND request_rows.selection_hash = v_selection_hash
        AND request_rows.correction_kind = 'PRE_BANK_CANCEL'
        AND request_rows.status IN ('REQUESTED', 'AWAITING_AUTHORISATION', 'AUTHORISED', 'EXPANDED', 'PROCESSING')
      ORDER BY request_rows.created_at_utc
      LIMIT 1
      FOR UPDATE;
    END;
  END IF;

  v_expand_result := public.pay_payment_correction_expand_work(v_request.id, p_actor_user_id);
  v_process_result := public.pay_payment_correction_process_chunk(v_request.id, 50, 'cancel-not-sent-recalculate', p_actor_user_id);
  v_grouped_alert_updates := COALESCE(v_process_result -> 'grouped_alert_updates', '[]'::jsonb);
  v_is_complete := COALESCE((v_process_result ->> 'complete')::boolean, false);

  v_signal_result := public.banking_pay_batch_signal_touch(
    p_pay_batch_id,
    'PAYMENT_CANCEL_NOT_SENT_AND_RECALCULATE',
    'pay_payment_cancel_not_sent_and_recalculate',
    jsonb_build_object(
      'correction_request_id', v_request.id::text,
      'selection_hash', v_selection_hash,
      'payment_lifecycle_state', v_lifecycle_state,
      'progress', v_process_result
    ),
    true,
    true,
    COALESCE(jsonb_array_length(v_grouped_alert_updates), 0) > 0,
    true
  );

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'correction_request_id', v_request.id::text,
    'payment_lifecycle_state', v_lifecycle_state,
    'recommended_action', v_recommended_action,
    'next_step', 'AMEND_TIMESHEET_AND_RECALCULATE',
    'progress_completed', COALESCE((v_process_result -> 'totals' ->> 'applied')::integer, COALESCE((v_process_result ->> 'applied')::integer, 0)),
    'progress_total', COALESCE((v_process_result -> 'totals' ->> 'total')::integer, 0),
    'is_complete', v_is_complete,
    'voided_transfer_count', COALESCE((v_process_result ->> 'updated_transfer_count')::integer, 0),
    'voided_item_count', COALESCE((v_process_result ->> 'applied')::integer, 0),
    'released_reservation_count', COALESCE((v_process_result ->> 'released_reservations')::integer, 0),
    'restored_finance_component_count', COALESCE((v_process_result ->> 'restored_finance_components')::integer, 0),
    'carry_forward_created_count', COALESCE((v_process_result ->> 'carry_forward_created')::integer, 0),
    'carry_forward_existing_count', COALESCE((v_process_result ->> 'carry_forward_existing')::integer, 0),
    'carry_forward_released_count', COALESCE((v_process_result ->> 'carry_forward_released')::integer, 0),
    'freshness_dirty_result', COALESCE(v_process_result -> 'freshness_dirty_result', '{}'::jsonb),
    'diagnostic_json', v_diagnostic_json,
    'expand_result', v_expand_result,
    'process_result', v_process_result,
    'live_signal', v_signal_result,
    'grouped_alert_summary_impact', v_grouped_alert_updates
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_payment_confirm_no_money_and_unwind(
  p_pay_batch_id uuid,
  p_selection_json jsonb DEFAULT '{}'::jsonb,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_confirmation_json jsonb DEFAULT '{}'::jsonb,
  p_reason text DEFAULT NULL::text,
  p_idempotency_key text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_uuid_regex text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_selection_json jsonb := '{}'::jsonb;
  v_confirmation_json jsonb := '{}'::jsonb;
  v_diagnostic_json jsonb := '{}'::jsonb;
  v_resolved_scope_json jsonb := '{}'::jsonb;
  v_lifecycle_state text := NULL::text;
  v_recommended_action text := NULL::text;
  v_blockers jsonb := '[]'::jsonb;
  v_race_blockers jsonb := '[]'::jsonb;
  v_carry_forward_blockers jsonb := '[]'::jsonb;
  v_effective_selection_json jsonb := '{}'::jsonb;
  v_selection_hash text := NULL::text;
  v_plan_json jsonb := '{}'::jsonb;
  v_plan_hash text := NULL::text;
  v_accepted_resolution_json jsonb := '{}'::jsonb;
  v_accepted_resolution_hash text := NULL::text;
  v_required_quantity integer := 1;
  v_reason text := NULL::text;
  v_existing_request public.pay_payment_correction_requests%ROWTYPE;
  v_request public.pay_payment_correction_requests%ROWTYPE;
  v_expand_result jsonb := '{}'::jsonb;
  v_process_result jsonb := '{}'::jsonb;
  v_signal_result jsonb := '{}'::jsonb;
  v_idempotency_key text := NULL::text;
  v_scope_type text := NULL::text;
  v_actor_valid boolean := true;
  v_source_text text := NULL::text;
  v_source_bank_event_id uuid := NULL::uuid;
  v_source_bank_event_text text := NULL::text;
  v_source_bank_event_pay_batch_id uuid := NULL::uuid;
  v_source_bank_event_provider_key text := NULL::text;
  v_source_bank_event_transport text := NULL::text;
  v_source_bank_event_key text := NULL::text;
  v_source_bank_event_provider_event_id text := NULL::text;
  v_source_bank_event_provider_transaction_id text := NULL::text;
  v_source_bank_event_provider_request_id text := NULL::text;
  v_source_bank_event_mapping_status text := NULL::text;
  v_source_bank_event_mapping_method text := NULL::text;
  v_source_bank_event_webhook_receipt_id uuid := NULL::uuid;
  v_source_bank_event_signature_valid boolean := NULL::boolean;
  v_source_bank_event_terminal_no_money boolean := false;
  v_source_bank_event_final_paid boolean := false;
  v_source_bank_event_pending boolean := false;
  v_provider_key_text text := NULL::text;
  v_provider_event_key_text text := NULL::text;
  v_provider_event_id_text text := NULL::text;
  v_provider_transaction_id_text text := NULL::text;
  v_provider_request_id_text text := NULL::text;
  v_provider_webhook_receipt_id_text text := NULL::text;
  v_provider_webhook_receipt_id uuid := NULL::uuid;
  v_provider_signature_valid_confirmed boolean := false;
  v_source_is_provider boolean := false;
  v_webhook_receipt_status text := NULL::text;
  v_webhook_receipt_provider_key text := NULL::text;
  v_webhook_receipt_rail_env text := NULL::text;
  v_webhook_receipt_event_key text := NULL::text;
  v_webhook_receipt_signature_valid boolean := NULL::boolean;
  v_webhook_receipt_ok boolean := false;
  v_failed_webhook_replay_receipt_ok boolean := false;
  v_diagnostic_terminal_no_money_count integer := 0;
  v_scope_is_full boolean := true;
  v_strong_mapping_confirmed boolean := false;
  v_strong_provider_evidence boolean := false;
  v_manual_confirmation_ok boolean := false;
  v_manual_confirmation_reference_text text := NULL::text;
  v_is_system_request boolean := false;
  v_auto_unwind_setting boolean := false;
  v_correction_kind text := 'NO_MONEY_UNWIND';
  v_is_complete boolean := false;
  v_grouped_alert_updates jsonb := '[]'::jsonb;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_BATCH_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_BATCH_REQUIRED')::text;
  END IF;

  IF p_selection_json IS NOT NULL AND COALESCE(jsonb_typeof(p_selection_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_SELECTION_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_SELECTION_MUST_BE_OBJECT')::text;
  END IF;

  IF p_confirmation_json IS NOT NULL AND COALESCE(jsonb_typeof(p_confirmation_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_CONFIRMATION_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_CONFIRMATION_MUST_BE_OBJECT')::text;
  END IF;

  IF p_actor_user_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.tms_users AS actor_user
      WHERE actor_user.id = p_actor_user_id
        AND COALESCE(actor_user.is_active, false) = true
    )
    INTO v_actor_valid;

    IF COALESCE(v_actor_valid, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_ACTOR_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_ACTOR_NOT_ALLOWED', 'actor_user_id', p_actor_user_id::text)::text;
    END IF;
  END IF;

  v_selection_json := COALESCE(p_selection_json, '{}'::jsonb);
  v_confirmation_json := COALESCE(p_confirmation_json, '{}'::jsonb);
  v_reason := NULLIF(BTRIM(COALESCE(p_reason, '')), '');
  v_source_text := UPPER(NULLIF(BTRIM(COALESCE(v_confirmation_json ->> 'source', v_confirmation_json ->> 'evidence_source', '')), ''));
  v_provider_key_text := UPPER(NULLIF(BTRIM(COALESCE(v_confirmation_json ->> 'provider_key', v_confirmation_json ->> 'provider', v_confirmation_json ->> 'rail_provider', '')), ''));
  v_provider_event_key_text := NULLIF(BTRIM(COALESCE(v_confirmation_json ->> 'provider_event_key', v_confirmation_json ->> 'event_key', '')), '');
  v_provider_event_id_text := NULLIF(BTRIM(COALESCE(v_confirmation_json ->> 'provider_event_id', v_confirmation_json ->> 'event_id', '')), '');
  v_provider_transaction_id_text := NULLIF(BTRIM(COALESCE(v_confirmation_json ->> 'provider_transaction_id', v_confirmation_json ->> 'transaction_id', v_confirmation_json ->> 'provider_payment_id', '')), '');
  v_provider_request_id_text := NULLIF(BTRIM(COALESCE(v_confirmation_json ->> 'provider_request_id', v_confirmation_json ->> 'request_id', '')), '');
  v_provider_webhook_receipt_id_text := NULLIF(BTRIM(COALESCE(v_confirmation_json ->> 'provider_webhook_receipt_id', v_confirmation_json ->> 'webhook_receipt_id', '')), '');
  v_provider_signature_valid_confirmed := lower(BTRIM(COALESCE(v_confirmation_json ->> 'provider_signature_valid', v_confirmation_json ->> 'signature_valid', 'false'))) IN ('true','t','yes','y','1','on');
  v_source_is_provider := v_source_text IN ('PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY', 'PROVIDER_POLL', 'PROVIDER_RESPONSE');

  v_source_bank_event_text := COALESCE(
    NULLIF(BTRIM(v_confirmation_json ->> 'source_bank_event_id'), ''),
    NULLIF(BTRIM(v_confirmation_json ->> 'bank_event_id'), '')
  );

  IF v_source_bank_event_text IS NOT NULL THEN
    IF v_source_bank_event_text !~ v_uuid_regex THEN
      RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_INVALID_SOURCE_BANK_EVENT_ID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_INVALID_SOURCE_BANK_EVENT_ID',
                'source_bank_event_id', v_source_bank_event_text
              )::text;
    END IF;
    v_source_bank_event_id := v_source_bank_event_text::uuid;
  END IF;

  IF v_provider_webhook_receipt_id_text IS NOT NULL THEN
    IF v_provider_webhook_receipt_id_text !~ v_uuid_regex THEN
      RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_INVALID_WEBHOOK_RECEIPT_ID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_INVALID_WEBHOOK_RECEIPT_ID',
                'provider_webhook_receipt_id', v_provider_webhook_receipt_id_text
              )::text;
    END IF;
    v_provider_webhook_receipt_id := v_provider_webhook_receipt_id_text::uuid;
  END IF;

  v_manual_confirmation_reference_text := NULLIF(BTRIM(COALESCE(
    v_confirmation_json ->> 'provider_reference',
    v_confirmation_json ->> 'provider_ref',
    v_confirmation_json ->> 'bank_reference',
    v_confirmation_json ->> 'bank_ref',
    v_confirmation_json ->> 'rail_tx_id',
    v_confirmation_json ->> 'provider_transaction_id',
    v_confirmation_json ->> 'audit_note',
    v_confirmation_json ->> 'manual_note',
    v_confirmation_json ->> 'note',
    v_reason,
    ''
  )), '');
  v_is_system_request := p_actor_user_id IS NULL;

  SELECT COALESCE(settings_row.banking_pay_auto_unwind_terminal_no_money, false)
  INTO v_auto_unwind_setting
  FROM public.settings_defaults AS settings_row
  ORDER BY settings_row.id
  LIMIT 1;

  IF v_is_system_request AND COALESCE(v_auto_unwind_setting, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_AUTO_UNWIND_DISABLED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_AUTO_UNWIND_DISABLED')::text;
  END IF;

  v_diagnostic_json := public.pay_payment_cancelability_diagnostic(p_pay_batch_id, v_selection_json, p_actor_user_id);
  v_lifecycle_state := v_diagnostic_json ->> 'payment_lifecycle_state';
  v_recommended_action := v_diagnostic_json ->> 'recommended_action';
  v_blockers := COALESCE(v_diagnostic_json -> 'blockers', '[]'::jsonb);
  v_race_blockers := COALESCE(v_diagnostic_json -> 'race_or_submission_blockers', '[]'::jsonb);
  v_carry_forward_blockers := COALESCE(v_diagnostic_json -> 'carry_forward_blockers', '[]'::jsonb);
  v_resolved_scope_json := COALESCE(v_diagnostic_json -> 'resolved_full_payment_scope_json', '{}'::jsonb);
  v_scope_type := COALESCE(NULLIF(BTRIM(v_resolved_scope_json ->> 'scope_type'), ''), 'BATCH');
  v_scope_is_full := CASE
    WHEN LOWER(BTRIM(COALESCE(v_resolved_scope_json ->> 'is_full_scope', 'true'))) IN ('true','t','yes','y','1','on') THEN true
    WHEN LOWER(BTRIM(COALESCE(v_resolved_scope_json ->> 'is_full_scope', 'true'))) IN ('false','f','no','n','0','off') THEN false
    ELSE true
  END;

  IF v_source_bank_event_id IS NOT NULL THEN
    SELECT source_event_row.pay_batch_id,
           source_event_row.provider_key,
           source_event_row.provider_event_transport,
           source_event_row.provider_event_key,
           source_event_row.provider_event_id,
           source_event_row.provider_transaction_id,
           source_event_row.provider_request_id,
           source_event_row.mapping_status,
           source_event_row.mapping_method,
           source_event_row.provider_webhook_receipt_id,
           source_event_row.provider_signature_valid,
           COALESCE(source_event_classification.is_terminal_no_money, false),
           COALESCE(source_event_classification.is_final_money_moved, false),
           COALESCE(source_event_classification.is_pending_non_final, false)
    INTO v_source_bank_event_pay_batch_id,
         v_source_bank_event_provider_key,
         v_source_bank_event_transport,
         v_source_bank_event_key,
         v_source_bank_event_provider_event_id,
         v_source_bank_event_provider_transaction_id,
         v_source_bank_event_provider_request_id,
         v_source_bank_event_mapping_status,
         v_source_bank_event_mapping_method,
         v_source_bank_event_webhook_receipt_id,
         v_source_bank_event_signature_valid,
         v_source_bank_event_terminal_no_money,
         v_source_bank_event_final_paid,
         v_source_bank_event_pending
    FROM public.pay_bank_transfer_events AS source_event_row
    CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
      source_event_row.normalised_state,
      source_event_row.provider_state,
      COALESCE(source_event_row.raw_payload, '{}'::jsonb),
      jsonb_build_object(
        'provider_key', source_event_row.provider_key,
        'provider_event_transport', source_event_row.provider_event_transport,
        'provider_event_key', source_event_row.provider_event_key,
        'provider_transaction_id', source_event_row.provider_transaction_id,
        'provider_request_id', source_event_row.provider_request_id,
        'rail_env', source_event_row.rail_env
      )
    ) AS source_event_classification
    WHERE source_event_row.id = v_source_bank_event_id;

    IF v_source_bank_event_pay_batch_id IS NULL THEN
      RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_SOURCE_BANK_EVENT_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_SOURCE_BANK_EVENT_NOT_FOUND',
                'source_bank_event_id', v_source_bank_event_id::text
              )::text;
    END IF;

    IF v_source_bank_event_pay_batch_id IS DISTINCT FROM p_pay_batch_id THEN
      RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_SOURCE_BANK_EVENT_BATCH_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_SOURCE_BANK_EVENT_BATCH_MISMATCH',
                'pay_batch_id', p_pay_batch_id::text,
                'source_bank_event_pay_batch_id', v_source_bank_event_pay_batch_id::text,
                'source_bank_event_id', v_source_bank_event_id::text
              )::text;
    END IF;

    v_provider_key_text := COALESCE(v_provider_key_text, UPPER(NULLIF(BTRIM(v_source_bank_event_provider_key), '')));
    v_source_text := COALESCE(v_source_text, UPPER(NULLIF(BTRIM(v_source_bank_event_transport), '')));
    v_source_is_provider := v_source_text IN ('PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY', 'PROVIDER_POLL', 'PROVIDER_RESPONSE');
    v_provider_event_key_text := COALESCE(v_provider_event_key_text, NULLIF(BTRIM(v_source_bank_event_key), ''));
    v_provider_event_id_text := COALESCE(v_provider_event_id_text, NULLIF(BTRIM(v_source_bank_event_provider_event_id), ''));
    v_provider_transaction_id_text := COALESCE(v_provider_transaction_id_text, NULLIF(BTRIM(v_source_bank_event_provider_transaction_id), ''));
    v_provider_request_id_text := COALESCE(v_provider_request_id_text, NULLIF(BTRIM(v_source_bank_event_provider_request_id), ''));
    v_provider_webhook_receipt_id := COALESCE(v_provider_webhook_receipt_id, v_source_bank_event_webhook_receipt_id);
    v_provider_signature_valid_confirmed := COALESCE(v_provider_signature_valid_confirmed, false) OR COALESCE(v_source_bank_event_signature_valid, false);
  END IF;

  IF v_lifecycle_state NOT IN ('PROVIDER_CANCELLED_NO_MONEY', 'PROVIDER_FAILED_NO_MONEY')
     OR v_recommended_action IS DISTINCT FROM 'NO_MONEY_UNWIND_AND_RECALCULATE' THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_NOT_AVAILABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_NOT_AVAILABLE',
              'pay_batch_id', p_pay_batch_id::text,
              'payment_lifecycle_state', v_lifecycle_state,
              'recommended_action', v_recommended_action,
              'diagnostic_json', v_diagnostic_json
            )::text;
  END IF;

  IF COALESCE(v_scope_is_full, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_FULL_SCOPE_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_FULL_SCOPE_REQUIRED',
              'pay_batch_id', p_pay_batch_id::text,
              'scope_type', v_scope_type,
              'resolved_full_payment_scope_json', v_resolved_scope_json
            )::text;
  END IF;

  IF COALESCE(jsonb_array_length(v_blockers), 0) > 0
     OR COALESCE(jsonb_array_length(v_race_blockers), 0) > 0
     OR COALESCE(jsonb_array_length(v_carry_forward_blockers), 0) > 0 THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_BLOCKED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_BLOCKED',
              'pay_batch_id', p_pay_batch_id::text,
              'blockers', v_blockers,
              'race_or_submission_blockers', v_race_blockers,
              'carry_forward_blockers', v_carry_forward_blockers
            )::text;
  END IF;

  v_diagnostic_terminal_no_money_count := COALESCE(NULLIF(BTRIM(COALESCE(v_diagnostic_json #>> '{terminal_no_money_evidence_json,terminal_no_money_count}', '')), '')::integer, 0);

  IF v_provider_webhook_receipt_id IS NOT NULL THEN
    SELECT receipt_row.status,
           receipt_row.provider_key,
           receipt_row.rail_env,
           receipt_row.provider_event_key,
           receipt_row.signature_valid
    INTO v_webhook_receipt_status,
         v_webhook_receipt_provider_key,
         v_webhook_receipt_rail_env,
         v_webhook_receipt_event_key,
         v_webhook_receipt_signature_valid
    FROM public.bank_provider_webhook_receipts AS receipt_row
    WHERE receipt_row.id = v_provider_webhook_receipt_id;

    v_provider_event_key_text := COALESCE(v_provider_event_key_text, v_webhook_receipt_event_key);
  END IF;

  v_webhook_receipt_ok := (
    v_provider_webhook_receipt_id IS NOT NULL
    AND v_webhook_receipt_status IS NOT NULL
    AND UPPER(COALESCE(v_webhook_receipt_status, '')) NOT IN ('SIGNATURE_INVALID', 'FAILED_FINAL', 'FAILED_RETRYABLE')
    AND v_webhook_receipt_signature_valid IS TRUE
    AND (v_provider_key_text IS NULL OR v_webhook_receipt_provider_key IS NOT DISTINCT FROM v_provider_key_text)
    AND NULLIF(BTRIM(COALESCE(v_provider_event_key_text, '')), '') IS NOT NULL
    AND v_webhook_receipt_event_key IS NOT NULL
    AND v_webhook_receipt_event_key = v_provider_event_key_text
  );

  v_failed_webhook_replay_receipt_ok := (
    v_provider_webhook_receipt_id IS NOT NULL
    AND v_webhook_receipt_status IS NOT NULL
    AND UPPER(COALESCE(v_webhook_receipt_status, '')) NOT IN ('SIGNATURE_INVALID', 'FAILED_FINAL')
    AND (v_provider_key_text IS NULL OR v_webhook_receipt_provider_key IS NOT DISTINCT FROM v_provider_key_text)
    AND NULLIF(BTRIM(COALESCE(v_provider_event_key_text, '')), '') IS NOT NULL
    AND v_webhook_receipt_event_key IS NOT NULL
    AND v_webhook_receipt_event_key = v_provider_event_key_text
  );

  v_strong_mapping_confirmed := (
    lower(BTRIM(COALESCE(v_confirmation_json ->> 'strong_mapping_method', v_confirmation_json ->> 'strong_transfer_mapping', 'false'))) IN ('true','t','yes','y','1','on')
    OR (
      UPPER(BTRIM(COALESCE(v_source_bank_event_mapping_status, ''))) = 'MATCHED'
      AND UPPER(BTRIM(COALESCE(v_source_bank_event_mapping_method, ''))) IN (
        'TRANSFER_ID',
        'PROVIDER_EVENT_ID',
        'PROVIDER_TRANSACTION_ID',
        'PROVIDER_REQUEST_ID',
        'PROVIDER_REFERENCE',
        'RAIL_TX_ID',
        'MANUAL_TRANSFER_SELECTION'
      )
    )
    OR (
      v_source_bank_event_id IS NULL
      AND jsonb_array_length(COALESCE(v_resolved_scope_json -> 'pay_bank_transfer_ids', '[]'::jsonb)) > 0
      AND v_source_text IN ('PROVIDER_POLL', 'PROVIDER_RESPONSE')
    )
  );

  v_strong_provider_evidence := (
    v_source_is_provider
    AND v_provider_key_text IS NOT NULL
    AND (v_provider_event_key_text IS NOT NULL OR v_provider_event_id_text IS NOT NULL OR v_source_bank_event_id IS NOT NULL)
    AND lower(BTRIM(COALESCE(v_confirmation_json ->> 'terminal_no_money_evidence', 'false'))) IN ('true','t','yes','y','1','on')
    AND COALESCE(v_diagnostic_terminal_no_money_count, 0) > 0
    AND COALESCE(v_strong_mapping_confirmed, false) IS TRUE
    AND (v_source_bank_event_id IS NULL OR v_source_bank_event_terminal_no_money IS TRUE)
    AND v_source_bank_event_final_paid IS NOT TRUE
    AND v_source_bank_event_pending IS NOT TRUE
    AND (
      v_source_text <> 'PROVIDER_WEBHOOK'
      OR (
        v_provider_signature_valid_confirmed IS TRUE
        AND v_webhook_receipt_ok IS TRUE
      )
    )
    AND (
      v_source_text <> 'FAILED_WEBHOOK_REPLAY'
      OR v_failed_webhook_replay_receipt_ok IS TRUE
    )
  );

  v_manual_confirmation_ok := lower(BTRIM(COALESCE(v_confirmation_json ->> 'provider_checked', 'false'))) IN ('true','t','yes','y','1','on')
                              AND lower(BTRIM(COALESCE(v_confirmation_json ->> 'no_payment_made', 'false'))) IN ('true','t','yes','y','1','on')
                              AND lower(BTRIM(COALESCE(v_confirmation_json ->> 'terminal_no_money_confirmed', 'false'))) IN ('true','t','yes','y','1','on')
                              AND lower(BTRIM(COALESCE(v_confirmation_json ->> 'will_not_later_be_paid', 'false'))) IN ('true','t','yes','y','1','on')
                              AND v_manual_confirmation_reference_text IS NOT NULL;

  IF v_source_is_provider AND v_strong_provider_evidence IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_PROVIDER_SOURCE_REQUIRES_STRONG_PROVIDER_EVIDENCE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_PROVIDER_SOURCE_REQUIRES_STRONG_PROVIDER_EVIDENCE',
              'confirmation_json', v_confirmation_json,
              'source', v_source_text,
              'provider_key_present', v_provider_key_text IS NOT NULL,
              'provider_event_identity_present', (v_provider_event_key_text IS NOT NULL OR v_provider_event_id_text IS NOT NULL OR v_source_bank_event_id IS NOT NULL),
              'diagnostic_terminal_no_money_count', v_diagnostic_terminal_no_money_count,
              'provider_signature_valid', v_provider_signature_valid_confirmed,
              'webhook_receipt_ok', v_webhook_receipt_ok,
              'failed_webhook_replay_receipt_ok', v_failed_webhook_replay_receipt_ok,
              'scope_is_full', v_scope_is_full,
              'strong_mapping_confirmed', v_strong_mapping_confirmed,
              'source_bank_event_id', CASE WHEN v_source_bank_event_id IS NULL THEN NULL ELSE v_source_bank_event_id::text END,
              'source_bank_event_terminal_no_money', v_source_bank_event_terminal_no_money,
              'source_bank_event_final_paid', v_source_bank_event_final_paid,
              'source_bank_event_pending', v_source_bank_event_pending
            )::text;
  END IF;

  IF v_is_system_request AND v_strong_provider_evidence IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_SYSTEM_REQUIRES_STRONG_PROVIDER_EVIDENCE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_SYSTEM_REQUIRES_STRONG_PROVIDER_EVIDENCE',
              'confirmation_json', v_confirmation_json,
              'source', v_source_text,
              'provider_key_present', v_provider_key_text IS NOT NULL,
              'provider_event_identity_present', (v_provider_event_key_text IS NOT NULL OR v_provider_event_id_text IS NOT NULL OR v_source_bank_event_id IS NOT NULL),
              'diagnostic_terminal_no_money_count', v_diagnostic_terminal_no_money_count,
              'provider_signature_valid', v_provider_signature_valid_confirmed,
              'webhook_receipt_ok', v_webhook_receipt_ok,
              'failed_webhook_replay_receipt_ok', v_failed_webhook_replay_receipt_ok,
              'scope_is_full', v_scope_is_full,
              'strong_mapping_confirmed', v_strong_mapping_confirmed,
              'source_bank_event_id', CASE WHEN v_source_bank_event_id IS NULL THEN NULL ELSE v_source_bank_event_id::text END,
              'source_bank_event_terminal_no_money', v_source_bank_event_terminal_no_money,
              'source_bank_event_final_paid', v_source_bank_event_final_paid,
              'source_bank_event_pending', v_source_bank_event_pending
            )::text;
  END IF;

  IF v_is_system_request IS NOT TRUE AND v_source_is_provider IS NOT TRUE AND v_strong_provider_evidence IS NOT TRUE AND v_manual_confirmation_ok IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_PAYMENT_CONFIRM_NO_MONEY_MANUAL_CONFIRMATION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_PAYMENT_CONFIRM_NO_MONEY_MANUAL_CONFIRMATION_REQUIRED',
              'required_fields', jsonb_build_array('provider_checked', 'no_payment_made', 'terminal_no_money_confirmed', 'will_not_later_be_paid', 'provider_reference_or_audit_note')
            )::text;
  END IF;

  v_correction_kind := CASE
    WHEN v_strong_provider_evidence THEN 'NO_MONEY_UNWIND'
    ELSE 'MANUAL_EVIDENCE_NO_MONEY'
  END;

  v_effective_selection_json := v_selection_json
    || jsonb_build_object(
      'requested_action', 'NO_MONEY_UNWIND_AND_RECALCULATE',
      'correction_kind', v_correction_kind,
      'scope_type', v_scope_type,
      'pay_batch_id', p_pay_batch_id::text,
      'pay_batch_item_ids', COALESCE(v_resolved_scope_json -> 'pay_batch_item_ids', '[]'::jsonb),
      'expected_pay_batch_item_ids', COALESCE(v_resolved_scope_json -> 'pay_batch_item_ids', '[]'::jsonb),
      'pay_bank_transfer_ids', COALESCE(v_resolved_scope_json -> 'pay_bank_transfer_ids', '[]'::jsonb),
      'pay_batch_candidate_ids', COALESCE(v_resolved_scope_json -> 'pay_batch_candidate_ids', '[]'::jsonb)
    )
    || jsonb_build_object(
      'candidate_ids', COALESCE(v_resolved_scope_json -> 'candidate_ids', '[]'::jsonb),
      'finance_case_ids', COALESCE(v_resolved_scope_json -> 'finance_case_ids', '[]'::jsonb),
      'finance_component_ids', COALESCE(v_resolved_scope_json -> 'finance_component_ids', '[]'::jsonb),
      'reservation_ids', COALESCE(v_resolved_scope_json -> 'reservation_ids', '[]'::jsonb),
      'manual_adjustments_to_carry_forward', COALESCE(v_diagnostic_json -> 'manual_adjustments_to_carry_forward', '[]'::jsonb),
      'manual_adjustments_carried_forward_existing', COALESCE(v_diagnostic_json -> 'manual_adjustments_carried_forward_existing', '[]'::jsonb)
    );

  v_selection_hash := md5(v_effective_selection_json::text);
  v_idempotency_key := COALESCE(NULLIF(BTRIM(COALESCE(p_idempotency_key, '')), ''), md5(jsonb_build_object(
    'pay_batch_id', p_pay_batch_id::text,
    'selection_hash', v_selection_hash,
    'action', 'NO_MONEY_UNWIND_AND_RECALCULATE',
    'source_bank_event_id', CASE WHEN v_source_bank_event_id IS NULL THEN NULL ELSE v_source_bank_event_id::text END,
    'provider_event_key', v_provider_event_key_text,
    'provider_event_id', v_provider_event_id_text,
    'provider_webhook_receipt_id', CASE WHEN v_provider_webhook_receipt_id IS NULL THEN NULL ELSE v_provider_webhook_receipt_id::text END,
    'provider_transaction_id', v_provider_transaction_id_text,
    'provider_request_id', v_provider_request_id_text,
    'pay_bank_transfer_ids', COALESCE(v_resolved_scope_json -> 'pay_bank_transfer_ids', '[]'::jsonb),
    'source', v_source_text
  )::text));

  SELECT GREATEST(COALESCE(settings_row.payment_authoriser_quantity, 1), 1)
  INTO v_required_quantity
  FROM public.settings_defaults AS settings_row
  ORDER BY settings_row.id
  LIMIT 1;

  v_required_quantity := GREATEST(COALESCE(v_required_quantity, 1), 1);

  v_plan_json := jsonb_build_object(
    'classification', v_lifecycle_state,
    'payment_lifecycle_state', v_lifecycle_state,
    'recommended_action', v_recommended_action,
    'resolved_full_payment_scope_json', v_resolved_scope_json,
    'finance_scope_json', COALESCE(v_diagnostic_json -> 'finance_scope_json', '{}'::jsonb),
    'provider_evidence', COALESCE(v_diagnostic_json -> 'provider_evidence_summary_json', '{}'::jsonb),
    'terminal_no_money_evidence_json', COALESCE(v_diagnostic_json -> 'terminal_no_money_evidence_json', '{}'::jsonb),
    'carry_forward_blockers', v_carry_forward_blockers,
    'manual_adjustments_to_carry_forward', COALESCE(v_diagnostic_json -> 'manual_adjustments_to_carry_forward', '[]'::jsonb),
    'work_expansion_plan', jsonb_build_object('work_unit', CASE WHEN jsonb_array_length(COALESCE(v_resolved_scope_json -> 'pay_bank_transfer_ids', '[]'::jsonb)) > 0 THEN 'TRANSFER' ELSE 'CANDIDATE_PAYEE' END, 'chunk_size', 50),
    'idempotency_key', v_idempotency_key,
    'provider_event_key', v_provider_event_key_text,
    'provider_event_id', v_provider_event_id_text,
    'provider_webhook_receipt_id', CASE WHEN v_provider_webhook_receipt_id IS NULL THEN NULL ELSE v_provider_webhook_receipt_id::text END,
    'provider_transaction_id', v_provider_transaction_id_text,
    'provider_request_id', v_provider_request_id_text,
    'strong_provider_evidence', v_strong_provider_evidence,
    'strong_mapping_confirmed', v_strong_mapping_confirmed,
    'webhook_receipt_ok', v_webhook_receipt_ok,
    'failed_webhook_replay_receipt_ok', v_failed_webhook_replay_receipt_ok,
    'scope_is_full', v_scope_is_full,
    'source_bank_event_id', CASE WHEN v_source_bank_event_id IS NULL THEN NULL ELSE v_source_bank_event_id::text END,
    'source_bank_event_terminal_no_money', v_source_bank_event_terminal_no_money,
    'source_bank_event_final_paid', v_source_bank_event_final_paid,
    'source_bank_event_pending', v_source_bank_event_pending,
    'manual_confirmation_ok', v_manual_confirmation_ok
  );

  v_plan_hash := md5(v_plan_json::text);

  v_accepted_resolution_json := jsonb_build_object(
    'accepted_action', 'NO_MONEY_UNWIND_AND_RECALCULATE',
    'actor_kind', CASE WHEN v_is_system_request THEN 'SYSTEM' ELSE 'USER' END,
    'accepted_at_utc', now(),
    'accepted_by_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END,
    'reason', v_reason,
    'manual_confirmation_reference_text', v_manual_confirmation_reference_text,
    'confirmation_json', v_confirmation_json,
    'diagnostic_json', v_diagnostic_json,
    'carry_forward_blockers', v_carry_forward_blockers,
    'idempotency_key', v_idempotency_key
  );

  v_accepted_resolution_hash := md5(v_accepted_resolution_json::text);

  SELECT request_rows.*
  INTO v_existing_request
  FROM public.pay_payment_correction_requests AS request_rows
  WHERE request_rows.pay_batch_id = p_pay_batch_id
    AND request_rows.selection_hash = v_selection_hash
    AND request_rows.correction_kind = v_correction_kind
    AND request_rows.status IN ('REQUESTED', 'AWAITING_AUTHORISATION', 'AUTHORISED', 'EXPANDED', 'PROCESSING')
  ORDER BY request_rows.created_at_utc
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    UPDATE public.pay_payment_correction_requests AS request_to_authorise
    SET status = CASE WHEN request_to_authorise.status IN ('REQUESTED', 'AWAITING_AUTHORISATION') THEN 'AUTHORISED' ELSE request_to_authorise.status END,
        approved_count = GREATEST(COALESCE(request_to_authorise.approved_count, 0), COALESCE(request_to_authorise.required_quantity, v_required_quantity, 1)),
        authorised_at_utc = COALESCE(request_to_authorise.authorised_at_utc, now()),
        accepted_resolution_json = COALESCE(request_to_authorise.accepted_resolution_json, v_accepted_resolution_json),
        accepted_resolution_hash = COALESCE(request_to_authorise.accepted_resolution_hash, v_accepted_resolution_hash),
        updated_at_utc = now()
    WHERE request_to_authorise.id = v_existing_request.id
    RETURNING request_to_authorise.*
    INTO v_request;
  ELSE
    BEGIN
      INSERT INTO public.pay_payment_correction_requests (
        pay_batch_id,
        correction_kind,
        status,
        requested_by_user_id,
        requested_at_utc,
        required_quantity,
        approved_count,
        golden_key_used,
        golden_key_user_id,
        reason,
        selection_json,
        selection_hash,
        plan_json,
        plan_hash,
        accepted_resolution_json,
        accepted_resolution_hash,
        source_bank_event_id,
        auto_requested,
        created_at_utc,
        authorised_at_utc,
        applied_at_utc,
        cancelled_at_utc,
        updated_at_utc
      )
      VALUES (
        p_pay_batch_id,
        v_correction_kind,
        'AUTHORISED',
        CASE WHEN v_is_system_request THEN NULL::uuid ELSE p_actor_user_id END,
        now(),
        v_required_quantity,
        v_required_quantity,
        false,
        NULL::uuid,
        v_reason,
        v_effective_selection_json,
        v_selection_hash,
        v_plan_json,
        v_plan_hash,
        v_accepted_resolution_json,
        v_accepted_resolution_hash,
        v_source_bank_event_id,
        v_is_system_request,
        now(),
        now(),
        NULL::timestamptz,
        NULL::timestamptz,
        now()
      )
      RETURNING public.pay_payment_correction_requests.*
      INTO v_request;

      INSERT INTO public.pay_payment_correction_actions (
        correction_request_id,
        pay_batch_id,
        actor_kind,
        actor_user_id,
        action,
        action_at_utc,
        note,
        before_json,
        after_json,
        metadata_json
      )
      VALUES (
        v_request.id,
        p_pay_batch_id,
        CASE WHEN v_is_system_request THEN 'SYSTEM' ELSE 'USER' END,
        CASE WHEN v_is_system_request THEN NULL::uuid ELSE p_actor_user_id END,
        'REQUEST',
        now(),
        v_reason,
        NULL::jsonb,
        to_jsonb(v_request),
        jsonb_build_object(
          'requested_action', 'NO_MONEY_UNWIND_AND_RECALCULATE',
          'correction_kind', v_correction_kind,
          'selection_hash', v_selection_hash,
          'idempotency_key', v_idempotency_key,
          'source_bank_event_id', CASE WHEN v_source_bank_event_id IS NULL THEN NULL ELSE v_source_bank_event_id::text END,
          'source', v_source_text
        )
      );
    EXCEPTION WHEN unique_violation THEN
      SELECT request_rows.*
      INTO v_request
      FROM public.pay_payment_correction_requests AS request_rows
      WHERE request_rows.pay_batch_id = p_pay_batch_id
        AND request_rows.selection_hash = v_selection_hash
        AND request_rows.correction_kind = v_correction_kind
        AND request_rows.status IN ('REQUESTED', 'AWAITING_AUTHORISATION', 'AUTHORISED', 'EXPANDED', 'PROCESSING')
      ORDER BY request_rows.created_at_utc
      LIMIT 1
      FOR UPDATE;
    END;
  END IF;

  v_expand_result := public.pay_payment_correction_expand_work(v_request.id, p_actor_user_id);
  v_process_result := public.pay_payment_correction_process_chunk(v_request.id, 50, 'confirm-no-money-unwind', p_actor_user_id);
  v_grouped_alert_updates := COALESCE(v_process_result -> 'grouped_alert_updates', '[]'::jsonb);
  v_is_complete := COALESCE((v_process_result ->> 'complete')::boolean, false);

  v_signal_result := public.banking_pay_batch_signal_touch(
    p_pay_batch_id,
    'PAYMENT_CONFIRM_NO_MONEY_AND_UNWIND',
    'pay_payment_confirm_no_money_and_unwind',
    jsonb_build_object(
      'correction_request_id', v_request.id::text,
      'selection_hash', v_selection_hash,
      'payment_lifecycle_state', v_lifecycle_state,
      'provider_failure_reason_group', v_diagnostic_json ->> 'provider_failure_reason_group',
      'progress', v_process_result
    ),
    true,
    true,
    COALESCE(jsonb_array_length(v_grouped_alert_updates), 0) > 0 OR v_is_complete IS NOT TRUE,
    true
  );

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'correction_request_id', v_request.id::text,
    'payment_lifecycle_state', v_lifecycle_state,
    'recommended_action', v_recommended_action,
    'progress_completed', COALESCE((v_process_result -> 'totals' ->> 'applied')::integer, COALESCE((v_process_result ->> 'applied')::integer, 0)),
    'progress_total', COALESCE((v_process_result -> 'totals' ->> 'total')::integer, 0),
    'is_complete', v_is_complete,
    'released_reservation_count', COALESCE((v_process_result ->> 'released_reservations')::integer, 0),
    'restored_finance_component_count', COALESCE((v_process_result ->> 'restored_finance_components')::integer, 0),
    'voided_transfer_count', COALESCE((v_process_result ->> 'updated_transfer_count')::integer, 0),
    'voided_item_count', COALESCE((v_process_result ->> 'applied')::integer, 0),
    'carry_forward_created_count', COALESCE((v_process_result ->> 'carry_forward_created')::integer, 0),
    'carry_forward_existing_count', COALESCE((v_process_result ->> 'carry_forward_existing')::integer, 0),
    'carry_forward_released_count', COALESCE((v_process_result ->> 'carry_forward_released')::integer, 0),
    'freshness_dirty_result', COALESCE(v_process_result -> 'freshness_dirty_result', '{}'::jsonb),
    'blocked_work_items', COALESCE(v_process_result -> 'blocked_work_items', '[]'::jsonb),
    'diagnostic_json', v_diagnostic_json,
    'expand_result', v_expand_result,
    'process_result', v_process_result,
    'live_signal', v_signal_result,
    'grouped_alert_summary_impact', v_grouped_alert_updates
  );
END;
$function$;






CREATE OR REPLACE FUNCTION public._pay_detect_manual_adjustments_for_carry_forward(
  p_pay_batch_id uuid,
  p_scope_json jsonb,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_scope_json jsonb := COALESCE(p_scope_json, '{}'::jsonb);
  v_uuid_regex text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_pay_batch_item_ids uuid[] := ARRAY[]::uuid[];
  v_manual_adjustments_to_carry_forward jsonb := '[]'::jsonb;
  v_carry_forward_blockers jsonb := '[]'::jsonb;
  v_manual_adjustment_support_details_json jsonb := '{}'::jsonb;
  v_finance_backed_count integer := 0;
  v_source_backed_count integer := 0;
  v_source_less_safe_count integer := 0;
  v_source_less_ambiguous_count integer := 0;
  v_manual_count integer := 0;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF v_scope_json IS NULL OR jsonb_typeof(v_scope_json) <> 'object' THEN
    RAISE EXCEPTION 'PAY_SCOPE_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_SCOPE_JSON_MUST_BE_OBJECT', 'pay_batch_id', p_pay_batch_id)::text;
  END IF;

  WITH raw_values AS (
    SELECT item_values.raw_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_scope_json->'pay_batch_item_ids') = 'array' THEN v_scope_json->'pay_batch_item_ids'
        WHEN jsonb_typeof(v_scope_json #> '{resolved_full_payment_scope_json,pay_batch_item_ids}') = 'array' THEN v_scope_json #> '{resolved_full_payment_scope_json,pay_batch_item_ids}'
        ELSE '[]'::jsonb
      END
    ) AS item_values(raw_value)
  ), clean_values AS (
    SELECT NULLIF(btrim(raw_values.raw_value), '') AS clean_value
    FROM raw_values
  )
  SELECT COALESCE(array_agg(clean_values.clean_value::uuid), ARRAY[]::uuid[])
  INTO v_pay_batch_item_ids
  FROM clean_values
  WHERE clean_values.clean_value IS NOT NULL
    AND clean_values.clean_value ~ v_uuid_regex;

  IF COALESCE(array_length(v_pay_batch_item_ids, 1), 0) = 0 THEN
    RETURN jsonb_build_object(
      'manual_adjustment_carry_forward_required', false,
      'manual_adjustments_to_carry_forward', '[]'::jsonb,
      'can_carry_forward_automatically', true,
      'carry_forward_blockers', '[]'::jsonb,
      'manual_adjustment_support_details_json', jsonb_build_object('manual_item_count', 0, 'reason', 'No pay_batch_item_ids were supplied in the resolved scope.'),
      'finance_backed_count', 0,
      'source_backed_count', 0,
      'source_less_safe_count', 0,
      'source_less_ambiguous_count', 0
    );
  END IF;

  WITH scoped_items AS (
    SELECT
      item_rows.id AS pay_batch_item_id,
      item_rows.item_type,
      item_rows.timesheet_id,
      item_rows.source_ref,
      item_rows.description,
      item_rows.amount_ex_vat,
      item_rows.amount_vat,
      item_rows.amount_inc_vat,
      item_rows.pay_channel,
      item_rows.umbrella_id,
      item_rows.finance_case_id,
      item_rows.finance_component_id,
      item_rows.reservation_id,
      item_rows.paye_treatment,
      item_rows.frozen_component_snapshot_json,
      item_rows.frozen_component_key_type,
      item_rows.frozen_component_key_value,
      item_rows.frozen_component_classification::text AS frozen_component_classification,
      item_rows.frozen_source_basis_json,
      item_rows.frozen_source_pay_method,
      item_rows.frozen_target_pay_method,
      item_rows.frozen_resolution_mode::text AS frozen_resolution_mode,
      item_rows.frozen_resolution_payload_json,
      item_rows.frozen_resolution_result_json,
      item_rows.operation_source_key,
      item_rows.pay_bank_transfer_id,
      batch_candidate_rows.pay_batch_id,
      batch_candidate_rows.id AS pay_batch_candidate_id,
      batch_candidate_rows.candidate_id,
      COALESCE(
        item_rows.umbrella_id,
        transfer_rows.umbrella_id,
        CASE
          WHEN upper(btrim(COALESCE(item_rows.pay_channel, ''))) = 'UMBRELLA' THEN candidate_record_rows.umbrella_id
          ELSE NULL::uuid
        END,
        CASE
          WHEN upper(COALESCE(transfer_rows.payee_entity_kind, '')) IN ('UMBRELLA', 'UMBRELLA_COMPANY') THEN transfer_rows.payee_entity_id
          ELSE NULL::uuid
        END
      ) AS effective_umbrella_id,
      transfer_rows.transfer_group_key,
      transfer_rows.payee_entity_kind,
      transfer_rows.payee_entity_id,
      existing_target_carry_forward_rows.id AS existing_target_carry_forward_id,
      existing_source_carry_forward_rows.id AS existing_source_carry_forward_id,
      (
        upper(COALESCE(item_rows.item_type, '')) LIKE '%MANUAL%'
        OR upper(COALESCE(item_rows.item_type, '')) LIKE '%ADJUSTMENT%'
        OR upper(COALESCE(item_rows.item_type, '')) LIKE '%DEBT%'
        OR upper(COALESCE(item_rows.item_type, '')) LIKE '%CREDIT%'
        OR upper(COALESCE(item_rows.item_type, '')) IN ('ADJUSTMENT_DELTA', 'MANUAL_CREDIT_ADJUSTMENT_PAYMENT', 'MANUAL_CREDIT_PAYOUT', 'MANUAL_DEBT_RECOVERY', 'FINANCE_ADJUSTMENT')
        OR upper(COALESCE(item_rows.source_ref, '')) LIKE 'MANUAL%'
        OR upper(COALESCE(item_rows.operation_source_key, '')) LIKE 'MANUAL%'
      ) AS is_manual_like
    FROM public.pay_batch_items AS item_rows
    JOIN public.pay_batch_candidates AS batch_candidate_rows
      ON batch_candidate_rows.id = item_rows.pay_batch_candidate_id
    JOIN public.candidates AS candidate_record_rows
      ON candidate_record_rows.id = batch_candidate_rows.candidate_id
    LEFT JOIN public.pay_bank_transfers AS transfer_rows
      ON transfer_rows.id = item_rows.pay_bank_transfer_id
    LEFT JOIN public.pay_manual_adjustment_carry_forwards AS existing_target_carry_forward_rows
      ON existing_target_carry_forward_rows.target_pay_batch_item_id = item_rows.id
    LEFT JOIN public.pay_manual_adjustment_carry_forwards AS existing_source_carry_forward_rows
      ON existing_source_carry_forward_rows.source_pay_batch_item_id = item_rows.id
    WHERE batch_candidate_rows.pay_batch_id = p_pay_batch_id
      AND item_rows.id = ANY(COALESCE(v_pay_batch_item_ids, ARRAY[]::uuid[]))
  ), classified_items AS (
    SELECT
      scoped_items.*,
      CASE
        WHEN scoped_items.is_manual_like = false THEN 'NOT_MANUAL'
        WHEN scoped_items.existing_target_carry_forward_id IS NOT NULL
          OR upper(COALESCE(scoped_items.source_ref, '')) LIKE 'CARRY_FORWARD:%'
          OR upper(COALESCE(scoped_items.operation_source_key, '')) LIKE 'CARRY_FORWARD:%'
          THEN 'SOURCE_BACKED'
        WHEN scoped_items.finance_case_id IS NOT NULL
          OR scoped_items.finance_component_id IS NOT NULL
          OR scoped_items.reservation_id IS NOT NULL
          THEN 'FINANCE_BACKED'
        WHEN scoped_items.timesheet_id IS NOT NULL
          OR upper(COALESCE(scoped_items.operation_source_key, '')) LIKE 'TIMESHEET:%'
          OR upper(COALESCE(scoped_items.operation_source_key, '')) LIKE 'TS:%'
          OR upper(COALESCE(scoped_items.operation_source_key, '')) LIKE 'SEG:%'
          OR upper(COALESCE(scoped_items.operation_source_key, '')) LIKE 'ADJ:%'
          OR upper(COALESCE(scoped_items.operation_source_key, '')) LIKE 'EXPENSE:%'
          OR upper(COALESCE(scoped_items.operation_source_key, '')) LIKE 'MILEAGE:%'
          OR upper(COALESCE(scoped_items.operation_source_key, '')) LIKE 'ADDITIONAL%'
          OR upper(COALESCE(scoped_items.operation_source_key, '')) LIKE 'FINANCE:%'
          OR upper(COALESCE(scoped_items.operation_source_key, '')) LIKE 'FINANCE_CASE:%'
          OR upper(COALESCE(scoped_items.operation_source_key, '')) LIKE 'RESERVATION:%'
          OR upper(COALESCE(scoped_items.operation_source_key, '')) LIKE 'ADVANCE:%'
          OR upper(COALESCE(scoped_items.source_ref, '')) LIKE 'TS:%'
          OR upper(COALESCE(scoped_items.source_ref, '')) LIKE 'SEG:%'
          OR upper(COALESCE(scoped_items.source_ref, '')) LIKE 'ADJ:%'
          OR upper(COALESCE(scoped_items.source_ref, '')) LIKE 'EXPENSE:%'
          OR upper(COALESCE(scoped_items.source_ref, '')) LIKE 'MILEAGE:%'
          OR upper(COALESCE(scoped_items.source_ref, '')) LIKE 'ADDITIONAL%'
          THEN 'SOURCE_BACKED'
        WHEN scoped_items.amount_inc_vat IS NOT NULL
          AND round(scoped_items.amount_inc_vat, 2) <> 0
          AND scoped_items.amount_ex_vat IS NOT NULL
          AND scoped_items.amount_vat IS NOT NULL
          AND NULLIF(btrim(COALESCE(scoped_items.description, '')), '') IS NOT NULL
          AND scoped_items.candidate_id IS NOT NULL
          AND upper(btrim(COALESCE(scoped_items.pay_channel, ''))) IN ('PAYE', 'UMBRELLA')
          AND (
            upper(btrim(COALESCE(scoped_items.pay_channel, ''))) = 'PAYE'
            OR scoped_items.effective_umbrella_id IS NOT NULL
          )
          THEN 'SOURCE_LESS_CARRY_FORWARD_SAFE'
        ELSE 'SOURCE_LESS_AMBIGUOUS'
      END AS classification,
      CASE
        WHEN scoped_items.amount_inc_vat IS NULL THEN 'MISSING_AMOUNT_INC_VAT'
        WHEN round(scoped_items.amount_inc_vat, 2) = 0 THEN 'ZERO_AMOUNT'
        WHEN scoped_items.amount_ex_vat IS NULL THEN 'MISSING_AMOUNT_EX_VAT'
        WHEN scoped_items.amount_vat IS NULL THEN 'MISSING_AMOUNT_VAT'
        WHEN NULLIF(btrim(COALESCE(scoped_items.description, '')), '') IS NULL THEN 'MISSING_DESCRIPTION'
        WHEN scoped_items.candidate_id IS NULL THEN 'MISSING_CANDIDATE_CONTEXT'
        WHEN upper(btrim(COALESCE(scoped_items.pay_channel, ''))) NOT IN ('PAYE', 'UMBRELLA') THEN 'UNSUPPORTED_OR_MISSING_PAY_CHANNEL'
        WHEN upper(btrim(COALESCE(scoped_items.pay_channel, ''))) = 'UMBRELLA' AND scoped_items.effective_umbrella_id IS NULL THEN 'MISSING_UMBRELLA_PAYEE_CONTEXT'
        ELSE NULL::text
      END AS ambiguity_reason
    FROM scoped_items
  )
  SELECT
    COALESCE((count(*) FILTER (WHERE classified_items.is_manual_like))::integer, 0),
    COALESCE((count(*) FILTER (WHERE classified_items.classification = 'FINANCE_BACKED'))::integer, 0),
    COALESCE((count(*) FILTER (WHERE classified_items.classification = 'SOURCE_BACKED'))::integer, 0),
    COALESCE((count(*) FILTER (WHERE classified_items.classification = 'SOURCE_LESS_CARRY_FORWARD_SAFE'))::integer, 0),
    COALESCE((count(*) FILTER (WHERE classified_items.classification = 'SOURCE_LESS_AMBIGUOUS'))::integer, 0),
    COALESCE(jsonb_agg(jsonb_build_object(
      'pay_batch_item_id', classified_items.pay_batch_item_id::text,
      'pay_batch_id', classified_items.pay_batch_id::text,
      'pay_batch_candidate_id', classified_items.pay_batch_candidate_id::text,
      'candidate_id', classified_items.candidate_id::text,
      'umbrella_id', CASE WHEN classified_items.effective_umbrella_id IS NULL THEN NULL ELSE classified_items.effective_umbrella_id::text END,
      'pay_bank_transfer_id', CASE WHEN classified_items.pay_bank_transfer_id IS NULL THEN NULL ELSE classified_items.pay_bank_transfer_id::text END,
      'item_type', classified_items.item_type,
      'description', classified_items.description,
      'pay_channel', classified_items.pay_channel,
      'amount_ex_vat', classified_items.amount_ex_vat,
      'amount_vat', classified_items.amount_vat,
      'amount_inc_vat', classified_items.amount_inc_vat,
      'adjustment_direction', CASE WHEN classified_items.amount_inc_vat > 0 THEN 'CREDIT' ELSE 'DEBIT' END,
      'signed_amount_convention', 'SIGNED_AMOUNTS',
      'paye_treatment', classified_items.paye_treatment,
      'source_ref', classified_items.source_ref,
      'operation_source_key', classified_items.operation_source_key,
      'classification', classified_items.classification
    ) ORDER BY classified_items.pay_batch_item_id::text) FILTER (WHERE classified_items.classification = 'SOURCE_LESS_CARRY_FORWARD_SAFE'), '[]'::jsonb),
    COALESCE(jsonb_agg(jsonb_build_object(
      'code', 'SOURCE_LESS_MANUAL_ADJUSTMENT_AMBIGUOUS',
      'pay_batch_item_id', classified_items.pay_batch_item_id::text,
      'item_type', classified_items.item_type,
      'description', classified_items.description,
      'amount_inc_vat', classified_items.amount_inc_vat,
      'pay_channel', classified_items.pay_channel,
      'reason', classified_items.ambiguity_reason
    ) ORDER BY classified_items.pay_batch_item_id::text) FILTER (WHERE classified_items.classification = 'SOURCE_LESS_AMBIGUOUS'), '[]'::jsonb),
    COALESCE(jsonb_agg(jsonb_build_object(
      'pay_batch_item_id', classified_items.pay_batch_item_id::text,
      'item_type', classified_items.item_type,
      'classification', classified_items.classification,
      'is_manual_like', classified_items.is_manual_like,
      'effective_umbrella_id', CASE WHEN classified_items.effective_umbrella_id IS NULL THEN NULL ELSE classified_items.effective_umbrella_id::text END,
      'payee_entity_kind', classified_items.payee_entity_kind,
      'payee_entity_id', CASE WHEN classified_items.payee_entity_id IS NULL THEN NULL ELSE classified_items.payee_entity_id::text END,
      'finance_case_id', CASE WHEN classified_items.finance_case_id IS NULL THEN NULL ELSE classified_items.finance_case_id::text END,
      'finance_component_id', CASE WHEN classified_items.finance_component_id IS NULL THEN NULL ELSE classified_items.finance_component_id::text END,
      'reservation_id', CASE WHEN classified_items.reservation_id IS NULL THEN NULL ELSE classified_items.reservation_id::text END,
      'timesheet_id', CASE WHEN classified_items.timesheet_id IS NULL THEN NULL ELSE classified_items.timesheet_id::text END,
      'source_ref', classified_items.source_ref,
      'operation_source_key', classified_items.operation_source_key,
      'existing_target_carry_forward_id', CASE WHEN classified_items.existing_target_carry_forward_id IS NULL THEN NULL ELSE classified_items.existing_target_carry_forward_id::text END,
      'existing_source_carry_forward_id', CASE WHEN classified_items.existing_source_carry_forward_id IS NULL THEN NULL ELSE classified_items.existing_source_carry_forward_id::text END,
      'ambiguity_reason', classified_items.ambiguity_reason
    ) ORDER BY classified_items.pay_batch_item_id::text) FILTER (WHERE classified_items.is_manual_like), '[]'::jsonb)
  INTO
    v_manual_count,
    v_finance_backed_count,
    v_source_backed_count,
    v_source_less_safe_count,
    v_source_less_ambiguous_count,
    v_manual_adjustments_to_carry_forward,
    v_carry_forward_blockers,
    v_manual_adjustment_support_details_json
  FROM classified_items;

  RETURN jsonb_build_object(
    'manual_adjustment_carry_forward_required', v_source_less_safe_count > 0,
    'manual_adjustments_to_carry_forward', COALESCE(v_manual_adjustments_to_carry_forward, '[]'::jsonb),
    'can_carry_forward_automatically', v_source_less_ambiguous_count = 0,
    'carry_forward_blockers', COALESCE(v_carry_forward_blockers, '[]'::jsonb),
    'manual_adjustment_support_details_json', jsonb_build_object(
      'manual_item_count', v_manual_count,
      'classified_items', COALESCE(v_manual_adjustment_support_details_json, '[]'::jsonb),
      'signed_amount_convention', 'SIGNED_AMOUNTS',
      'adjustment_direction_is_display_only', true,
      'actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END
    ),
    'finance_backed_count', v_finance_backed_count,
    'source_backed_count', v_source_backed_count,
    'source_less_safe_count', v_source_less_safe_count,
    'source_less_ambiguous_count', v_source_less_ambiguous_count
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public._pay_manual_adjustment_carry_forward_create(
  p_source_pay_batch_item_ids uuid[] DEFAULT NULL::uuid[],
  p_resolved_scope_json jsonb DEFAULT NULL::jsonb,
  p_source_correction_request_id uuid DEFAULT NULL::uuid,
  p_source_correction_work_item_id uuid DEFAULT NULL::uuid,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_uuid_regex text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_source_pay_batch_item_ids uuid[] := COALESCE(p_source_pay_batch_item_ids, ARRAY[]::uuid[]);
  v_scope_item_ids uuid[] := ARRAY[]::uuid[];
  v_source_pay_batch_id uuid := NULL::uuid;
  v_detection_result jsonb := '{}'::jsonb;
  v_safe_source_item_ids uuid[] := ARRAY[]::uuid[];
  v_existing_source_item_ids uuid[] := ARRAY[]::uuid[];
  v_created_count integer := 0;
  v_existing_count integer := 0;
  v_skipped_count integer := 0;
  v_total_safe_count integer := 0;
  v_records_json jsonb := '[]'::jsonb;
  v_skipped_json jsonb := '[]'::jsonb;
BEGIN
  IF p_resolved_scope_json IS NOT NULL AND jsonb_typeof(p_resolved_scope_json) <> 'object' THEN
    RAISE EXCEPTION 'RESOLVED_SCOPE_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'RESOLVED_SCOPE_JSON_MUST_BE_OBJECT')::text;
  END IF;

  IF p_resolved_scope_json IS NOT NULL AND jsonb_typeof(p_resolved_scope_json) = 'object' THEN
    WITH raw_values AS (
      SELECT item_values.raw_value
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(p_resolved_scope_json->'pay_batch_item_ids') = 'array' THEN p_resolved_scope_json->'pay_batch_item_ids'
          ELSE '[]'::jsonb
        END
      ) AS item_values(raw_value)
    ), clean_values AS (
      SELECT NULLIF(btrim(raw_values.raw_value), '') AS clean_value
      FROM raw_values
    )
    SELECT COALESCE(array_agg(clean_values.clean_value::uuid), ARRAY[]::uuid[])
    INTO v_scope_item_ids
    FROM clean_values
    WHERE clean_values.clean_value IS NOT NULL
      AND clean_values.clean_value ~ v_uuid_regex;
  END IF;

  v_source_pay_batch_item_ids := COALESCE(v_source_pay_batch_item_ids, ARRAY[]::uuid[]) || COALESCE(v_scope_item_ids, ARRAY[]::uuid[]);

  SELECT COALESCE(array_agg(DISTINCT source_item_values.source_item_id) FILTER (WHERE source_item_values.source_item_id IS NOT NULL), ARRAY[]::uuid[])
  INTO v_source_pay_batch_item_ids
  FROM unnest(COALESCE(v_source_pay_batch_item_ids, ARRAY[]::uuid[])) AS source_item_values(source_item_id);

  IF COALESCE(array_length(v_source_pay_batch_item_ids, 1), 0) = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'created_count', 0,
      'existing_count', 0,
      'skipped_count', 0,
      'carry_forward_records', '[]'::jsonb,
      'skipped_items', '[]'::jsonb,
      'message', 'No source pay_batch_item_ids supplied.'
    );
  END IF;

  SELECT batch_candidate_rows.pay_batch_id
  INTO v_source_pay_batch_id
  FROM public.pay_batch_items AS source_item_rows
  JOIN public.pay_batch_candidates AS batch_candidate_rows
    ON batch_candidate_rows.id = source_item_rows.pay_batch_candidate_id
  WHERE source_item_rows.id = ANY(v_source_pay_batch_item_ids)
  ORDER BY batch_candidate_rows.pay_batch_id
  LIMIT 1;

  IF v_source_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'SOURCE_PAY_BATCH_ITEMS_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'SOURCE_PAY_BATCH_ITEMS_NOT_FOUND')::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.pay_batch_items AS source_item_rows
    JOIN public.pay_batch_candidates AS batch_candidate_rows
      ON batch_candidate_rows.id = source_item_rows.pay_batch_candidate_id
    WHERE source_item_rows.id = ANY(v_source_pay_batch_item_ids)
      AND batch_candidate_rows.pay_batch_id IS DISTINCT FROM v_source_pay_batch_id
  ) THEN
    RAISE EXCEPTION 'SOURCE_PAY_BATCH_ITEMS_MUST_BELONG_TO_ONE_BATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'SOURCE_PAY_BATCH_ITEMS_MUST_BELONG_TO_ONE_BATCH')::text;
  END IF;

  PERFORM 1
  FROM public.pay_batch_items AS lock_source_item_rows
  WHERE lock_source_item_rows.id = ANY(v_source_pay_batch_item_ids)
  ORDER BY lock_source_item_rows.id
  FOR UPDATE;

  v_detection_result := public._pay_detect_manual_adjustments_for_carry_forward(
    v_source_pay_batch_id,
    jsonb_build_object(
      'pay_batch_id', v_source_pay_batch_id::text,
      'pay_batch_item_ids', COALESCE((SELECT jsonb_agg(item_id_values.source_item_id::text ORDER BY item_id_values.source_item_id::text) FROM unnest(v_source_pay_batch_item_ids) AS item_id_values(source_item_id)), '[]'::jsonb)
    ),
    p_actor_user_id
  );

  WITH safe_items AS (
    SELECT NULLIF(btrim(safe_item_values.safe_item_json->>'pay_batch_item_id'), '')::uuid AS pay_batch_item_id
    FROM jsonb_array_elements(COALESCE(v_detection_result->'manual_adjustments_to_carry_forward', '[]'::jsonb)) AS safe_item_values(safe_item_json)
    WHERE NULLIF(btrim(safe_item_values.safe_item_json->>'pay_batch_item_id'), '') ~ v_uuid_regex
  )
  SELECT COALESCE(array_agg(safe_items.pay_batch_item_id), ARRAY[]::uuid[])
  INTO v_safe_source_item_ids
  FROM safe_items;

  v_total_safe_count := COALESCE(array_length(v_safe_source_item_ids, 1), 0);

  SELECT COALESCE(array_agg(existing_carry_forward_rows.source_pay_batch_item_id), ARRAY[]::uuid[])
  INTO v_existing_source_item_ids
  FROM public.pay_manual_adjustment_carry_forwards AS existing_carry_forward_rows
  WHERE existing_carry_forward_rows.source_pay_batch_item_id = ANY(COALESCE(v_safe_source_item_ids, ARRAY[]::uuid[]));

  WITH candidate_rows AS (
    SELECT
      source_item_rows.id AS source_pay_batch_item_id,
      batch_candidate_rows.pay_batch_id AS source_pay_batch_id,
      source_item_rows.pay_bank_transfer_id AS source_pay_bank_transfer_id,
      source_item_rows.pay_batch_candidate_id AS source_pay_batch_candidate_id,
      batch_candidate_rows.candidate_id AS candidate_id,
      COALESCE(source_item_rows.umbrella_id, transfer_rows.umbrella_id, CASE WHEN upper(COALESCE(source_item_rows.pay_channel, '')) = 'UMBRELLA' THEN candidate_record_rows.umbrella_id ELSE NULL::uuid END) AS umbrella_id,
      CASE
        WHEN NULLIF(btrim(COALESCE(source_item_rows.frozen_source_basis_json->>'client_id', '')), '') ~ v_uuid_regex
             AND client_rows.id IS NOT NULL
          THEN client_rows.id
        ELSE NULL::uuid
      END AS client_id,
      source_item_rows.timesheet_id AS timesheet_id,
      upper(btrim(COALESCE(source_item_rows.pay_channel, ''))) AS pay_channel,
      CASE WHEN source_item_rows.amount_inc_vat > 0 THEN 'CREDIT' ELSE 'DEBIT' END AS adjustment_direction,
      source_item_rows.amount_ex_vat AS amount_ex_vat,
      source_item_rows.amount_vat AS amount_vat,
      source_item_rows.amount_inc_vat AS amount_inc_vat,
      COALESCE(NULLIF(btrim(source_item_rows.frozen_component_key_type), ''), source_item_rows.item_type) AS amount_basis,
      source_item_rows.paye_treatment AS paye_treatment,
      jsonb_build_object(
        'signed_amount_convention', 'SIGNED_AMOUNTS',
        'adjustment_direction_is_display_only', true,
        'pay_channel', source_item_rows.pay_channel,
        'paye_treatment', source_item_rows.paye_treatment,
        'frozen_component_classification', CASE WHEN source_item_rows.frozen_component_classification IS NULL THEN NULL ELSE source_item_rows.frozen_component_classification::text END,
        'frozen_source_pay_method', source_item_rows.frozen_source_pay_method,
        'frozen_target_pay_method', source_item_rows.frozen_target_pay_method,
        'amount_ex_vat', source_item_rows.amount_ex_vat,
        'amount_vat', source_item_rows.amount_vat,
        'amount_inc_vat', source_item_rows.amount_inc_vat
      ) AS tax_treatment_json,
      source_item_rows.description AS description,
      COALESCE(
        NULLIF(btrim(COALESCE(source_item_rows.frozen_source_basis_json->>'reason', '')), ''),
        NULLIF(btrim(COALESCE(source_item_rows.frozen_resolution_payload_json->>'reason', '')), ''),
        NULLIF(btrim(COALESCE(source_item_rows.description, '')), '')
      ) AS reason,
      source_item_rows.source_ref AS source_ref,
      source_item_rows.operation_source_key AS source_operation_source_key,
      jsonb_build_object(
        'source_pay_batch_item', to_jsonb(source_item_rows),
        'source_pay_batch_candidate', to_jsonb(batch_candidate_rows),
        'source_pay_bank_transfer', CASE WHEN transfer_rows.id IS NULL THEN NULL ELSE to_jsonb(transfer_rows) END,
        'signed_amount_convention', 'SIGNED_AMOUNTS',
        'created_from_function', '_pay_manual_adjustment_carry_forward_create'
      ) AS source_snapshot_json
    FROM public.pay_batch_items AS source_item_rows
    JOIN public.pay_batch_candidates AS batch_candidate_rows
      ON batch_candidate_rows.id = source_item_rows.pay_batch_candidate_id
    JOIN public.candidates AS candidate_record_rows
      ON candidate_record_rows.id = batch_candidate_rows.candidate_id
    LEFT JOIN public.pay_bank_transfers AS transfer_rows
      ON transfer_rows.id = source_item_rows.pay_bank_transfer_id
    LEFT JOIN public.clients AS client_rows
      ON client_rows.id = CASE
        WHEN NULLIF(btrim(COALESCE(source_item_rows.frozen_source_basis_json->>'client_id', '')), '') ~ v_uuid_regex
          THEN (source_item_rows.frozen_source_basis_json->>'client_id')::uuid
        ELSE NULL::uuid
      END
    WHERE source_item_rows.id = ANY(COALESCE(v_safe_source_item_ids, ARRAY[]::uuid[]))
      AND source_item_rows.amount_inc_vat IS NOT NULL
      AND round(source_item_rows.amount_inc_vat, 2) <> 0
      AND NULLIF(btrim(COALESCE(source_item_rows.description, '')), '') IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_manual_adjustment_carry_forwards AS target_carry_forward_rows
        WHERE target_carry_forward_rows.target_pay_batch_item_id = source_item_rows.id
      )
      AND upper(COALESCE(source_item_rows.source_ref, '')) NOT LIKE 'CARRY_FORWARD:%'
      AND upper(COALESCE(source_item_rows.operation_source_key, '')) NOT LIKE 'CARRY_FORWARD:%'
  ), upserted_rows AS (
    INSERT INTO public.pay_manual_adjustment_carry_forwards AS carry_forward_target_rows (
      source_pay_batch_id,
      source_pay_batch_item_id,
      source_pay_bank_transfer_id,
      source_pay_batch_candidate_id,
      source_correction_request_id,
      source_correction_work_item_id,
      candidate_id,
      umbrella_id,
      client_id,
      timesheet_id,
      pay_channel,
      adjustment_direction,
      amount_ex_vat,
      amount_vat,
      amount_inc_vat,
      amount_basis,
      paye_treatment,
      tax_treatment_json,
      description,
      reason,
      source_ref,
      source_operation_source_key,
      source_snapshot_json,
      status,
      created_by_user_id
    )
    SELECT
      candidate_rows.source_pay_batch_id,
      candidate_rows.source_pay_batch_item_id,
      candidate_rows.source_pay_bank_transfer_id,
      candidate_rows.source_pay_batch_candidate_id,
      p_source_correction_request_id,
      p_source_correction_work_item_id,
      candidate_rows.candidate_id,
      candidate_rows.umbrella_id,
      candidate_rows.client_id,
      candidate_rows.timesheet_id,
      candidate_rows.pay_channel,
      candidate_rows.adjustment_direction,
      candidate_rows.amount_ex_vat,
      candidate_rows.amount_vat,
      candidate_rows.amount_inc_vat,
      candidate_rows.amount_basis,
      candidate_rows.paye_treatment,
      candidate_rows.tax_treatment_json,
      candidate_rows.description,
      candidate_rows.reason,
      candidate_rows.source_ref,
      candidate_rows.source_operation_source_key,
      candidate_rows.source_snapshot_json,
      'PENDING_CARRY_FORWARD',
      p_actor_user_id
    FROM candidate_rows
    ON CONFLICT (source_pay_batch_item_id)
    DO UPDATE
    SET
      source_correction_request_id = COALESCE(carry_forward_target_rows.source_correction_request_id, EXCLUDED.source_correction_request_id),
      source_correction_work_item_id = COALESCE(carry_forward_target_rows.source_correction_work_item_id, EXCLUDED.source_correction_work_item_id),
      source_snapshot_json = COALESCE(carry_forward_target_rows.source_snapshot_json, '{}'::jsonb) || jsonb_build_object('last_seen_source_snapshot_json', EXCLUDED.source_snapshot_json),
      updated_at_utc = now()
    RETURNING *
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', upserted_rows.id::text,
    'source_pay_batch_id', upserted_rows.source_pay_batch_id::text,
    'source_pay_batch_item_id', upserted_rows.source_pay_batch_item_id::text,
    'source_pay_bank_transfer_id', CASE WHEN upserted_rows.source_pay_bank_transfer_id IS NULL THEN NULL ELSE upserted_rows.source_pay_bank_transfer_id::text END,
    'source_pay_batch_candidate_id', CASE WHEN upserted_rows.source_pay_batch_candidate_id IS NULL THEN NULL ELSE upserted_rows.source_pay_batch_candidate_id::text END,
    'candidate_id', upserted_rows.candidate_id::text,
    'umbrella_id', CASE WHEN upserted_rows.umbrella_id IS NULL THEN NULL ELSE upserted_rows.umbrella_id::text END,
    'pay_channel', upserted_rows.pay_channel,
    'adjustment_direction', upserted_rows.adjustment_direction,
    'amount_ex_vat', upserted_rows.amount_ex_vat,
    'amount_vat', upserted_rows.amount_vat,
    'amount_inc_vat', upserted_rows.amount_inc_vat,
    'description', upserted_rows.description,
    'status', upserted_rows.status,
    'was_existing', upserted_rows.source_pay_batch_item_id = ANY(COALESCE(v_existing_source_item_ids, ARRAY[]::uuid[])),
    'signed_amount_convention', 'SIGNED_AMOUNTS'
  ) ORDER BY upserted_rows.source_pay_batch_item_id::text), '[]'::jsonb)
  INTO v_records_json
  FROM upserted_rows;

  SELECT
    COALESCE((count(*) FILTER (WHERE COALESCE((record_values.record_json->>'was_existing')::boolean, false)))::integer, 0),
    COALESCE((count(*) FILTER (WHERE NOT COALESCE((record_values.record_json->>'was_existing')::boolean, false)))::integer, 0)
  INTO v_existing_count, v_created_count
  FROM jsonb_array_elements(COALESCE(v_records_json, '[]'::jsonb)) AS record_values(record_json);

  WITH recorded_items AS (
    SELECT NULLIF(btrim(record_values.record_json->>'source_pay_batch_item_id'), '')::uuid AS source_item_id
    FROM jsonb_array_elements(COALESCE(v_records_json, '[]'::jsonb)) AS record_values(record_json)
    WHERE NULLIF(btrim(record_values.record_json->>'source_pay_batch_item_id'), '') ~ v_uuid_regex
  ), skipped_items AS (
    SELECT source_item_values.source_item_id
    FROM unnest(COALESCE(v_source_pay_batch_item_ids, ARRAY[]::uuid[])) AS source_item_values(source_item_id)
    WHERE NOT EXISTS (
      SELECT 1
      FROM recorded_items AS recorded_item_rows
      WHERE recorded_item_rows.source_item_id = source_item_values.source_item_id
    )
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'pay_batch_item_id', skipped_items.source_item_id::text,
    'reason', CASE
      WHEN skipped_items.source_item_id = ANY(COALESCE(v_safe_source_item_ids, ARRAY[]::uuid[])) THEN 'SAFE_ITEM_NOT_INSERTED_OR_REUSED_TARGET_CARRY_FORWARD_SOURCE'
      ELSE 'NOT_SOURCE_LESS_CARRY_FORWARD_SAFE'
    END
  ) ORDER BY skipped_items.source_item_id::text), '[]'::jsonb)
  INTO v_skipped_json
  FROM skipped_items;

  v_skipped_count := COALESCE(jsonb_array_length(COALESCE(v_skipped_json, '[]'::jsonb)), 0);

  RETURN jsonb_build_object(
    'ok', true,
    'source_pay_batch_id', v_source_pay_batch_id::text,
    'source_correction_request_id', CASE WHEN p_source_correction_request_id IS NULL THEN NULL ELSE p_source_correction_request_id::text END,
    'source_correction_work_item_id', CASE WHEN p_source_correction_work_item_id IS NULL THEN NULL ELSE p_source_correction_work_item_id::text END,
    'created_count', COALESCE(v_created_count, 0),
    'existing_count', COALESCE(v_existing_count, 0),
    'skipped_count', COALESCE(v_skipped_count, 0),
    'carry_forward_records', COALESCE(v_records_json, '[]'::jsonb),
    'skipped_items', COALESCE(v_skipped_json, '[]'::jsonb),
    'detection_result', COALESCE(v_detection_result, '{}'::jsonb),
    'signed_amount_convention', 'SIGNED_AMOUNTS',
    'adjustment_direction_is_display_only', true
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public._pay_rail_state_money_movement_classify(
  p_transfer_status text DEFAULT NULL::text,
  p_rail_state text DEFAULT NULL::text,
  p_event_payload_json jsonb DEFAULT '{}'::jsonb,
  p_provider_meta_json jsonb DEFAULT '{}'::jsonb
)
RETURNS TABLE(
  cash_state text,
  normalised_transfer_status text,
  is_final_money_moved boolean,
  is_terminal_no_money boolean,
  is_pending_non_final boolean,
  completed_at_allowed boolean,
  reason text,
  support_details_json jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_event_payload_json jsonb := '{}'::jsonb;
  v_provider_meta_json jsonb := '{}'::jsonb;
  v_transfer_status_upper text := NULL::text;
  v_rail_state_upper text := NULL::text;
  v_event_status_upper text := NULL::text;
  v_provider_status_upper text := NULL::text;
  v_event_outcome_upper text := NULL::text;
  v_provider_outcome_upper text := NULL::text;
  v_error_code_upper text := NULL::text;
  v_reason_code_upper text := NULL::text;
  v_provider_key_upper text := NULL::text;
  v_provider_event_type_upper text := NULL::text;
  v_provider_event_transport_upper text := NULL::text;
  v_data_new_state_upper text := NULL::text;
  v_data_state_upper text := NULL::text;
  v_old_state_upper text := NULL::text;
  v_new_state_upper text := NULL::text;
  v_normalised_state_upper text := NULL::text;
  v_primary_status_upper text := NULL::text;
  v_status_terms text[] := ARRAY[]::text[];
  v_final_status_present boolean := false;
  v_terminal_status_present boolean := false;
  v_pending_status_present boolean := false;
  v_explicit_final_paid_evidence boolean := false;
  v_explicit_terminal_no_money_evidence boolean := false;
  v_explicit_pending_evidence boolean := false;
  v_ambiguous_commit_or_execute boolean := false;
  v_ambiguous_return_or_revert boolean := false;
  v_bool_true_terms text[] := ARRAY['true','t','yes','y','1','final','settled','paid','completed','success','succeeded'];
  v_bool_false_terms text[] := ARRAY['false','f','no','n','0'];
BEGIN
  IF p_event_payload_json IS NOT NULL AND jsonb_typeof(p_event_payload_json) = 'object' THEN
    v_event_payload_json := p_event_payload_json;
  END IF;

  IF p_provider_meta_json IS NOT NULL AND jsonb_typeof(p_provider_meta_json) = 'object' THEN
    v_provider_meta_json := p_provider_meta_json;
  END IF;

  v_transfer_status_upper := upper(NULLIF(btrim(COALESCE(p_transfer_status, '')), ''));
  v_rail_state_upper := upper(NULLIF(btrim(COALESCE(p_rail_state, '')), ''));

  v_event_status_upper := upper(NULLIF(btrim(COALESCE(
    v_event_payload_json->>'status',
    v_event_payload_json->>'normalised_state',
    v_event_payload_json->>'normalized_state',
    v_event_payload_json->>'new_state',
    v_event_payload_json->>'state',
    v_event_payload_json->>'rail_state',
    v_event_payload_json->>'payment_status',
    v_event_payload_json->>'provider_status',
    v_event_payload_json #>> '{payment,status}',
    v_event_payload_json #>> '{provider,status}',
    v_event_payload_json #>> '{data,new_state}',
    v_event_payload_json #>> '{data,state}',
    v_event_payload_json #>> '{data,status}',
    ''
  )), ''));

  v_provider_status_upper := upper(NULLIF(btrim(COALESCE(
    v_provider_meta_json->>'status',
    v_provider_meta_json->>'normalised_state',
    v_provider_meta_json->>'normalized_state',
    v_provider_meta_json->>'new_state',
    v_provider_meta_json->>'state',
    v_provider_meta_json->>'rail_state',
    v_provider_meta_json->>'payment_status',
    v_provider_meta_json->>'provider_status',
    v_provider_meta_json #>> '{payment,status}',
    v_provider_meta_json #>> '{provider,status}',
    v_provider_meta_json #>> '{data,new_state}',
    v_provider_meta_json #>> '{data,state}',
    v_provider_meta_json #>> '{data,status}',
    ''
  )), ''));

  v_event_outcome_upper := upper(NULLIF(btrim(COALESCE(
    v_event_payload_json->>'outcome',
    v_event_payload_json->>'cash_state',
    v_event_payload_json->>'money_movement_state',
    v_event_payload_json->>'mapping_status',
    v_event_payload_json #>> '{payment,outcome}',
    v_event_payload_json #>> '{provider,outcome}',
    v_event_payload_json #>> '{data,outcome}',
    ''
  )), ''));

  v_provider_outcome_upper := upper(NULLIF(btrim(COALESCE(
    v_provider_meta_json->>'outcome',
    v_provider_meta_json->>'cash_state',
    v_provider_meta_json->>'money_movement_state',
    v_provider_meta_json->>'mapping_status',
    v_provider_meta_json #>> '{payment,outcome}',
    v_provider_meta_json #>> '{provider,outcome}',
    v_provider_meta_json #>> '{data,outcome}',
    ''
  )), ''));

  v_error_code_upper := upper(NULLIF(btrim(COALESCE(
    v_event_payload_json->>'error_code',
    v_event_payload_json->>'failure_code',
    v_event_payload_json->>'decline_code',
    v_event_payload_json #>> '{error,code}',
    v_event_payload_json #>> '{failure,code}',
    v_provider_meta_json->>'error_code',
    v_provider_meta_json->>'failure_code',
    v_provider_meta_json->>'decline_code',
    v_provider_meta_json #>> '{error,code}',
    v_provider_meta_json #>> '{failure,code}',
    ''
  )), ''));

  v_reason_code_upper := upper(NULLIF(btrim(COALESCE(
    v_event_payload_json->>'reason_code',
    v_event_payload_json->>'reason',
    v_event_payload_json->>'failed_reason',
    v_event_payload_json #>> '{reason,code}',
    v_provider_meta_json->>'reason_code',
    v_provider_meta_json->>'reason',
    v_provider_meta_json->>'failed_reason',
    v_provider_meta_json #>> '{reason,code}',
    ''
  )), ''));


  v_provider_key_upper := upper(NULLIF(btrim(COALESCE(
    v_event_payload_json->>'provider_key',
    v_event_payload_json->>'provider',
    v_event_payload_json->>'rail_provider',
    v_provider_meta_json->>'provider_key',
    v_provider_meta_json->>'provider',
    v_provider_meta_json->>'rail_provider',
    ''
  )), ''));

  v_provider_event_type_upper := upper(NULLIF(btrim(COALESCE(
    v_event_payload_json->>'provider_event_type',
    v_event_payload_json->>'event_type',
    v_event_payload_json->>'event',
    v_provider_meta_json->>'provider_event_type',
    v_provider_meta_json->>'event_type',
    v_provider_meta_json->>'event',
    ''
  )), ''));

  v_provider_event_transport_upper := upper(NULLIF(btrim(COALESCE(
    v_event_payload_json->>'provider_event_transport',
    v_event_payload_json->>'event_source',
    v_event_payload_json->>'source',
    v_provider_meta_json->>'provider_event_transport',
    v_provider_meta_json->>'event_source',
    v_provider_meta_json->>'source',
    ''
  )), ''));

  v_data_new_state_upper := upper(NULLIF(btrim(COALESCE(
    v_event_payload_json #>> '{data,new_state}',
    v_provider_meta_json #>> '{data,new_state}',
    v_event_payload_json->>'new_state',
    v_provider_meta_json->>'new_state',
    ''
  )), ''));

  v_data_state_upper := upper(NULLIF(btrim(COALESCE(
    v_event_payload_json #>> '{data,state}',
    v_provider_meta_json #>> '{data,state}',
    v_event_payload_json->>'state',
    v_provider_meta_json->>'state',
    ''
  )), ''));

  v_old_state_upper := upper(NULLIF(btrim(COALESCE(
    v_event_payload_json #>> '{data,old_state}',
    v_provider_meta_json #>> '{data,old_state}',
    ''
  )), ''));

  v_new_state_upper := upper(NULLIF(btrim(COALESCE(
    v_event_payload_json #>> '{data,new_state}',
    v_provider_meta_json #>> '{data,new_state}',
    v_event_payload_json->>'new_state',
    v_provider_meta_json->>'new_state',
    ''
  )), ''));

  v_normalised_state_upper := upper(NULLIF(btrim(COALESCE(
    v_event_payload_json->>'normalised_state',
    v_event_payload_json->>'normalized_state',
    v_provider_meta_json->>'normalised_state',
    v_provider_meta_json->>'normalized_state',
    ''
  )), ''));

  v_status_terms := ARRAY[
    v_transfer_status_upper,
    v_rail_state_upper,
    v_event_status_upper,
    v_provider_status_upper,
    v_event_outcome_upper,
    v_provider_outcome_upper,
    v_error_code_upper,
    v_reason_code_upper,
    v_data_new_state_upper,
    v_data_state_upper,
    v_old_state_upper,
    v_new_state_upper,
    v_normalised_state_upper
  ];

  SELECT COALESCE(status_terms.status_text, 'UNKNOWN')
  INTO v_primary_status_upper
  FROM unnest(v_status_terms) AS status_terms(status_text)
  WHERE status_terms.status_text IS NOT NULL
  LIMIT 1;

  v_final_status_present := EXISTS (
    SELECT 1
    FROM unnest(ARRAY[
      v_transfer_status_upper,
      v_rail_state_upper,
      v_event_status_upper,
      v_provider_status_upper,
      v_event_outcome_upper,
      v_provider_outcome_upper,
      v_error_code_upper,
      v_reason_code_upper,
      v_data_new_state_upper,
      v_data_state_upper,
      v_new_state_upper,
      v_normalised_state_upper
    ]) AS status_terms(status_text)
    WHERE status_terms.status_text IN (
      'PAID',
      'SETTLED',
      'COMPLETED',
      'SUCCESS',
      'SUCCEEDED',
      'PAYMENT_PAID',
      'PAYMENT_SETTLED',
      'PAYMENT_COMPLETED',
      'FINAL_PAID',
      'MONEY_MOVED',
      'CONFIRMED_PAID',
      'CONFIRMED_SETTLED'
    )
  );

  v_terminal_status_present := EXISTS (
    SELECT 1
    FROM unnest(ARRAY[
      v_transfer_status_upper,
      v_rail_state_upper,
      v_event_status_upper,
      v_provider_status_upper,
      v_event_outcome_upper,
      v_provider_outcome_upper,
      v_error_code_upper,
      v_reason_code_upper,
      v_data_new_state_upper,
      v_data_state_upper,
      v_new_state_upper,
      v_normalised_state_upper
    ]) AS status_terms(status_text)
    WHERE status_terms.status_text IN (
      'FAILED',
      'FAILURE',
      'REJECTED',
      'DECLINED',
      'CANCELLED',
      'CANCELED',
      'SUBMISSION_FAILED',
      'FAILED_BEFORE_COMMIT',
      'CANCELLED_BEFORE_RELEASE',
      'CANCELED_BEFORE_RELEASE',
      'WRONG_BANK',
      'WRONG_BANK_DETAILS',
      'NO_MONEY',
      'NO_PAYMENT_MADE',
      'NOT_PAID',
      'REVERSED_BEFORE_RELEASE',
      'INSUFFICIENT_FUNDS',
      'ACCOUNT_CLOSED',
      'INVALID_ACCOUNT',
      'INVALID_SORT_CODE',
      'BANK_REJECTED'
    )
  );

  v_pending_status_present := EXISTS (
    SELECT 1
    FROM unnest(ARRAY[
      v_transfer_status_upper,
      v_rail_state_upper,
      v_event_status_upper,
      v_provider_status_upper,
      v_event_outcome_upper,
      v_provider_outcome_upper,
      v_error_code_upper,
      v_reason_code_upper,
      v_data_new_state_upper,
      v_data_state_upper,
      v_new_state_upper,
      v_normalised_state_upper
    ]) AS status_terms(status_text)
    WHERE status_terms.status_text IN (
      'CREATED',
      'ACCEPTED',
      'SCHEDULED',
      'SUBMITTED',
      'SENT',
      'PROCESSING',
      'IN_FLIGHT',
      'IN-FLIGHT',
      'INFLIGHT',
      'QUEUED',
      'PENDING',
      'PENDING_SETTLEMENT',
      'PENDING_CONFIRMATION',
      'PENDING_SUBMISSION',
      'AUTHORISED',
      'AUTHORIZED',
      'AWAITING_CONFIRMATION',
      'AWAITING_SETTLEMENT'
    )
  );

  v_ambiguous_commit_or_execute := EXISTS (
    SELECT 1
    FROM unnest(v_status_terms) AS status_terms(status_text)
    WHERE status_terms.status_text IN ('COMMITTED', 'EXECUTED')
  );

  v_ambiguous_return_or_revert := EXISTS (
    SELECT 1
    FROM unnest(v_status_terms) AS status_terms(status_text)
    WHERE status_terms.status_text IN ('RETURNED', 'REVERTED', 'REVERSED')
  );

  v_explicit_final_paid_evidence := (
    lower(NULLIF(btrim(COALESCE(v_event_payload_json->>'final_paid', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_event_payload_json->>'is_final_money_moved', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_event_payload_json->>'money_moved', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_event_payload_json->>'payment_made', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_event_payload_json->>'settlement_confirmed', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_event_payload_json->>'settled', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_event_payload_json->>'paid', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_event_payload_json #>> '{money_movement,final_paid}', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_event_payload_json #>> '{settlement,confirmed}', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json->>'final_paid', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json->>'is_final_money_moved', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json->>'money_moved', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json->>'payment_made', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json->>'settlement_confirmed', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json->>'settled', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json->>'paid', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json #>> '{money_movement,final_paid}', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json #>> '{settlement,confirmed}', '')), '')) = ANY(v_bool_true_terms)
  );

  v_explicit_terminal_no_money_evidence := (
    lower(NULLIF(btrim(COALESCE(v_event_payload_json->>'no_payment_made', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_event_payload_json->>'no_money', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_event_payload_json->>'terminal_no_money', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_event_payload_json->>'wrong_bank', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_event_payload_json->>'cancelled_before_release', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_event_payload_json->>'canceled_before_release', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_event_payload_json->>'failed_before_commit', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_event_payload_json #>> '{money_movement,no_payment_made}', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json->>'no_payment_made', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json->>'no_money', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json->>'terminal_no_money', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json->>'wrong_bank', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json->>'cancelled_before_release', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json->>'canceled_before_release', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json->>'failed_before_commit', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json #>> '{money_movement,no_payment_made}', '')), '')) = ANY(v_bool_true_terms)
  );

  v_explicit_pending_evidence := (
    lower(NULLIF(btrim(COALESCE(v_event_payload_json->>'pending', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_event_payload_json->>'in_flight', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_event_payload_json->>'processing', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json->>'pending', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json->>'in_flight', '')), '')) = ANY(v_bool_true_terms)
    OR lower(NULLIF(btrim(COALESCE(v_provider_meta_json->>'processing', '')), '')) = ANY(v_bool_true_terms)
  );

  v_explicit_final_paid_evidence := COALESCE(v_explicit_final_paid_evidence, false);
  v_explicit_terminal_no_money_evidence := COALESCE(v_explicit_terminal_no_money_evidence, false);
  v_explicit_pending_evidence := COALESCE(v_explicit_pending_evidence, false);

  IF v_explicit_final_paid_evidence OR v_final_status_present THEN
    cash_state := 'FINAL_PAID';
    normalised_transfer_status := 'COMPLETED';
    is_final_money_moved := true;
    is_terminal_no_money := false;
    is_pending_non_final := false;
    completed_at_allowed := true;
    reason := 'Explicit final-paid/provider-settled evidence was found.';
  ELSIF v_explicit_terminal_no_money_evidence OR v_terminal_status_present THEN
    cash_state := 'TERMINAL_NO_MONEY';
    normalised_transfer_status := CASE
      WHEN v_primary_status_upper IN ('CANCELLED', 'CANCELED', 'CANCELLED_BEFORE_RELEASE', 'CANCELED_BEFORE_RELEASE') THEN 'CANCELLED'
      ELSE 'FAILED'
    END;
    is_final_money_moved := false;
    is_terminal_no_money := true;
    is_pending_non_final := false;
    completed_at_allowed := false;
    reason := 'Terminal no-money/failure/cancelled-before-release evidence was found.';
  ELSIF v_explicit_pending_evidence OR v_pending_status_present THEN
    cash_state := 'PENDING_NON_FINAL';
    normalised_transfer_status := CASE
      WHEN v_primary_status_upper IN ('CREATED', 'SCHEDULED', 'SUBMITTED', 'SENT', 'PROCESSING', 'QUEUED', 'ACCEPTED', 'PENDING') THEN CASE WHEN v_primary_status_upper = 'CREATED' THEN 'PENDING' ELSE v_primary_status_upper END
      ELSE 'PENDING'
    END;
    is_final_money_moved := false;
    is_terminal_no_money := false;
    is_pending_non_final := true;
    completed_at_allowed := false;
    reason := 'Pending/non-final provider or rail state was found.';
  ELSE
    cash_state := 'UNKNOWN';
    normalised_transfer_status := COALESCE(v_primary_status_upper, 'UNKNOWN');
    is_final_money_moved := false;
    is_terminal_no_money := false;
    is_pending_non_final := false;
    completed_at_allowed := false;
    reason := CASE
      WHEN v_ambiguous_commit_or_execute THEN 'Bare COMMITTED/EXECUTED evidence is ambiguous and is not final-paid evidence without explicit final settlement metadata.'
      WHEN v_ambiguous_return_or_revert THEN 'RETURNED/REVERTED/REVERSED evidence is ambiguous and is not terminal no-money without explicit no-payment-made evidence.'
      ELSE 'No explicit final-paid, terminal no-money, or pending non-final evidence was found.'
    END;
  END IF;

  support_details_json := jsonb_build_object(
    'transfer_status', p_transfer_status,
    'rail_state', p_rail_state,
    'transfer_status_upper', v_transfer_status_upper,
    'rail_state_upper', v_rail_state_upper,
    'event_status_upper', v_event_status_upper,
    'provider_status_upper', v_provider_status_upper,
    'event_outcome_upper', v_event_outcome_upper,
    'provider_outcome_upper', v_provider_outcome_upper,
    'error_code_upper', v_error_code_upper,
    'reason_code_upper', v_reason_code_upper,
    'primary_status_upper', v_primary_status_upper,
    'final_status_present', v_final_status_present,
    'terminal_status_present', v_terminal_status_present,
    'pending_status_present', v_pending_status_present,
    'explicit_final_paid_evidence', v_explicit_final_paid_evidence,
    'explicit_terminal_no_money_evidence', v_explicit_terminal_no_money_evidence,
    'explicit_pending_evidence', v_explicit_pending_evidence,
    'ambiguous_commit_or_execute', v_ambiguous_commit_or_execute,
    'ambiguous_return_or_revert', v_ambiguous_return_or_revert,
    'committed_or_executed_requires_explicit_final_paid_metadata', true,
    'returned_or_reverted_requires_explicit_no_money_metadata', true,
    'provider_key_upper', v_provider_key_upper,
    'provider_event_type_upper', v_provider_event_type_upper,
    'provider_event_transport_upper', v_provider_event_transport_upper,
    'data_new_state_upper', v_data_new_state_upper,
    'data_state_upper', v_data_state_upper,
    'old_state_upper', v_old_state_upper,
    'new_state_upper', v_new_state_upper,
    'normalised_state_upper', v_normalised_state_upper,
    'is_unknown_or_review', (cash_state = 'UNKNOWN'),
    'can_no_money_unwind', (cash_state = 'TERMINAL_NO_MONEY'),
    'reason_code', CASE
      WHEN cash_state = 'FINAL_PAID' THEN 'FINAL_PAID_EXPLICIT'
      WHEN cash_state = 'TERMINAL_NO_MONEY' THEN 'TERMINAL_NO_MONEY_EXPLICIT'
      WHEN cash_state = 'PENDING_NON_FINAL' THEN 'PENDING_NON_FINAL'
      WHEN v_ambiguous_commit_or_execute THEN 'AMBIGUOUS_COMMITTED_OR_EXECUTED'
      WHEN v_ambiguous_return_or_revert THEN 'AMBIGUOUS_RETURNED_OR_REVERTED'
      ELSE 'UNKNOWN_NO_EXPLICIT_PROVIDER_OUTCOME'
    END,
    'reason_label', reason,
    'success_only_status_update', (cash_state = 'FINAL_PAID'),
    'event_payload_keys', CASE
      WHEN jsonb_typeof(v_event_payload_json) = 'object' THEN COALESCE((SELECT jsonb_agg(event_keys.key_name ORDER BY event_keys.key_name) FROM jsonb_object_keys(v_event_payload_json) AS event_keys(key_name)), '[]'::jsonb)
      ELSE '[]'::jsonb
    END,
    'provider_meta_keys', CASE
      WHEN jsonb_typeof(v_provider_meta_json) = 'object' THEN COALESCE((SELECT jsonb_agg(meta_keys.key_name ORDER BY meta_keys.key_name) FROM jsonb_object_keys(v_provider_meta_json) AS meta_keys(key_name)), '[]'::jsonb)
      ELSE '[]'::jsonb
    END
  );

  RETURN NEXT;
END;
$function$;




CREATE OR REPLACE FUNCTION public._pay_resolve_payment_scope_for_cancel_rewind(
  p_pay_batch_id uuid,
  p_selection_json jsonb,
  p_lock_mode boolean DEFAULT false,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_scope_type text := NULL::text;
  v_uuid_regex text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_selected_pay_batch_item_ids uuid[] := ARRAY[]::uuid[];
  v_selected_pay_batch_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_selected_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_selected_pay_bank_transfer_ids uuid[] := ARRAY[]::uuid[];
  v_selected_umbrella_ids uuid[] := ARRAY[]::uuid[];
  v_selected_transfer_group_keys text[] := ARRAY[]::text[];
  v_selected_pay_channels text[] := ARRAY[]::text[];
  v_explicit_pay_batch_item_ids uuid[] := ARRAY[]::uuid[];
  v_expected_pay_batch_item_ids uuid[] := ARRAY[]::uuid[];
  v_authoritative_explicit_item_ids uuid[] := ARRAY[]::uuid[];
  v_pay_batch_item_ids uuid[] := ARRAY[]::uuid[];
  v_pay_batch_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_umbrella_ids uuid[] := ARRAY[]::uuid[];
  v_pay_bank_transfer_ids uuid[] := ARRAY[]::uuid[];
  v_finance_case_ids uuid[] := ARRAY[]::uuid[];
  v_finance_component_ids uuid[] := ARRAY[]::uuid[];
  v_reservation_ids uuid[] := ARRAY[]::uuid[];
  v_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_pay_channels text[] := ARRAY[]::text[];
  v_transfer_group_keys text[] := ARRAY[]::text[];
  v_candidate_payment_group_keys text[] := ARRAY[]::text[];
  v_missing_explicit_item_ids uuid[] := ARRAY[]::uuid[];
  v_selected_item_count integer := 0;
  v_expanded_item_count integer := 0;
  v_is_full_scope boolean := true;
  v_partial_scope_blockers jsonb := '[]'::jsonb;
  v_result jsonb := '{}'::jsonb;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF p_selection_json IS NULL OR jsonb_typeof(p_selection_json) <> 'object' THEN
    RAISE EXCEPTION 'PAYMENT_SCOPE_SELECTION_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAYMENT_SCOPE_SELECTION_JSON_MUST_BE_OBJECT', 'pay_batch_id', p_pay_batch_id)::text;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.pay_batches AS batch_check WHERE batch_check.id = p_pay_batch_id) THEN
    RAISE EXCEPTION 'PAY_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_NOT_FOUND', 'pay_batch_id', p_pay_batch_id)::text;
  END IF;

  v_scope_type := upper(NULLIF(btrim(COALESCE(p_selection_json->>'scope_type', '')), ''));

  IF v_scope_type IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_SCOPE_TYPE_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAYMENT_SCOPE_TYPE_REQUIRED', 'pay_batch_id', p_pay_batch_id)::text;
  END IF;

  WITH selected_items AS (
    SELECT selected_item_rows.*
    FROM public._pay_payment_correction_selected_items(p_pay_batch_id, p_selection_json, true) AS selected_item_rows
  )
  SELECT
    COALESCE(array_agg(DISTINCT selected_items.pay_batch_item_id) FILTER (WHERE selected_items.pay_batch_item_id IS NOT NULL), ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT selected_items.pay_batch_candidate_id) FILTER (WHERE selected_items.pay_batch_candidate_id IS NOT NULL), ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT selected_items.candidate_id) FILTER (WHERE selected_items.candidate_id IS NOT NULL), ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT selected_items.pay_bank_transfer_id) FILTER (WHERE selected_items.pay_bank_transfer_id IS NOT NULL), ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT selected_items.umbrella_id) FILTER (WHERE selected_items.umbrella_id IS NOT NULL), ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT selected_items.transfer_group_key) FILTER (WHERE NULLIF(btrim(COALESCE(selected_items.transfer_group_key, '')), '') IS NOT NULL), ARRAY[]::text[]),
    COALESCE(array_agg(DISTINCT upper(btrim(COALESCE(selected_items.pay_channel, '')))) FILTER (WHERE NULLIF(btrim(COALESCE(selected_items.pay_channel, '')), '') IS NOT NULL), ARRAY[]::text[]),
    count(*)::integer
  INTO
    v_selected_pay_batch_item_ids,
    v_selected_pay_batch_candidate_ids,
    v_selected_candidate_ids,
    v_selected_pay_bank_transfer_ids,
    v_selected_umbrella_ids,
    v_selected_transfer_group_keys,
    v_selected_pay_channels,
    v_selected_item_count
  FROM selected_items;

  WITH raw_values AS (
    SELECT explicit_item_values.raw_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(p_selection_json->'pay_batch_item_ids') = 'array' THEN p_selection_json->'pay_batch_item_ids'
        ELSE '[]'::jsonb
      END
    ) AS explicit_item_values(raw_value)
    UNION ALL
    SELECT p_selection_json->>'pay_batch_item_id'
    WHERE p_selection_json ? 'pay_batch_item_id'
  ), clean_values AS (
    SELECT NULLIF(btrim(raw_values.raw_value), '') AS clean_value
    FROM raw_values
  )
  SELECT COALESCE(array_agg(clean_values.clean_value::uuid), ARRAY[]::uuid[])
  INTO v_explicit_pay_batch_item_ids
  FROM clean_values
  WHERE clean_values.clean_value IS NOT NULL
    AND clean_values.clean_value ~ v_uuid_regex;

  WITH raw_values AS (
    SELECT expected_item_values.raw_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(p_selection_json->'expected_pay_batch_item_ids') = 'array' THEN p_selection_json->'expected_pay_batch_item_ids'
        ELSE '[]'::jsonb
      END
    ) AS expected_item_values(raw_value)
  ), clean_values AS (
    SELECT NULLIF(btrim(raw_values.raw_value), '') AS clean_value
    FROM raw_values
  )
  SELECT COALESCE(array_agg(clean_values.clean_value::uuid), ARRAY[]::uuid[])
  INTO v_expected_pay_batch_item_ids
  FROM clean_values
  WHERE clean_values.clean_value IS NOT NULL
    AND clean_values.clean_value ~ v_uuid_regex;

  SELECT COALESCE(array_agg(DISTINCT explicit_items.explicit_item_id) FILTER (WHERE explicit_items.explicit_item_id IS NOT NULL), ARRAY[]::uuid[])
  INTO v_authoritative_explicit_item_ids
  FROM (
    SELECT unnest(COALESCE(v_explicit_pay_batch_item_ids, ARRAY[]::uuid[])) AS explicit_item_id
    UNION ALL
    SELECT unnest(COALESCE(v_expected_pay_batch_item_ids, ARRAY[]::uuid[])) AS explicit_item_id
  ) AS explicit_items;

  WITH selected_seed AS (
    SELECT selected_item_rows.*
    FROM public._pay_payment_correction_selected_items(p_pay_batch_id, p_selection_json, true) AS selected_item_rows
  ), expanded_items AS (
    SELECT DISTINCT candidate_item_rows.id AS pay_batch_item_id
    FROM public.pay_batch_items AS candidate_item_rows
    JOIN public.pay_batch_candidates AS candidate_batch_rows
      ON candidate_batch_rows.id = candidate_item_rows.pay_batch_candidate_id
    LEFT JOIN public.pay_bank_transfers AS candidate_transfer_rows
      ON candidate_transfer_rows.id = candidate_item_rows.pay_bank_transfer_id
    WHERE candidate_batch_rows.pay_batch_id = p_pay_batch_id
      AND (
        v_scope_type = 'BATCH'
        OR candidate_item_rows.id = ANY(COALESCE(v_selected_pay_batch_item_ids, ARRAY[]::uuid[]))
        OR (
          COALESCE(array_length(v_selected_pay_bank_transfer_ids, 1), 0) > 0
          AND candidate_item_rows.pay_bank_transfer_id = ANY(v_selected_pay_bank_transfer_ids)
        )
        OR (
          v_scope_type = 'CANDIDATES'
          AND candidate_item_rows.pay_batch_candidate_id = ANY(COALESCE(v_selected_pay_batch_candidate_ids, ARRAY[]::uuid[]))
        )
        OR EXISTS (
          SELECT 1
          FROM selected_seed AS selected_seed_rows
          WHERE selected_seed_rows.pay_batch_candidate_id = candidate_item_rows.pay_batch_candidate_id
            AND (
              (
                selected_seed_rows.pay_bank_transfer_id IS NOT NULL
                AND candidate_item_rows.pay_bank_transfer_id = selected_seed_rows.pay_bank_transfer_id
              )
              OR (
                NULLIF(btrim(COALESCE(selected_seed_rows.transfer_group_key, '')), '') IS NOT NULL
                AND NULLIF(btrim(COALESCE(candidate_transfer_rows.transfer_group_key, '')), '') IS NOT NULL
                AND candidate_transfer_rows.transfer_group_key = selected_seed_rows.transfer_group_key
                AND upper(btrim(COALESCE(candidate_item_rows.pay_channel, ''))) = upper(btrim(COALESCE(selected_seed_rows.pay_channel, '')))
              )
              OR (
                selected_seed_rows.pay_bank_transfer_id IS NULL
                AND candidate_item_rows.pay_bank_transfer_id IS NULL
                AND upper(btrim(COALESCE(candidate_item_rows.pay_channel, ''))) = upper(btrim(COALESCE(selected_seed_rows.pay_channel, '')))
                AND candidate_item_rows.umbrella_id IS NOT DISTINCT FROM selected_seed_rows.umbrella_id
              )
            )
        )
      )
  )
  SELECT COALESCE(array_agg(expanded_items.pay_batch_item_id), ARRAY[]::uuid[])
  INTO v_pay_batch_item_ids
  FROM expanded_items;

  v_expanded_item_count := COALESCE(array_length(v_pay_batch_item_ids, 1), 0);

  WITH expanded_batch_items AS (
    SELECT
      item_rows.id AS pay_batch_item_id,
      item_rows.pay_batch_candidate_id,
      batch_candidate_rows.candidate_id,
      item_rows.pay_bank_transfer_id,
      COALESCE(item_rows.umbrella_id, transfer_rows.umbrella_id) AS umbrella_id,
      item_rows.finance_case_id,
      item_rows.finance_component_id,
      item_rows.reservation_id,
      item_rows.timesheet_id,
      upper(btrim(COALESCE(item_rows.pay_channel, ''))) AS pay_channel,
      transfer_rows.transfer_group_key,
      (
        batch_candidate_rows.candidate_id::text
        || ':' || upper(btrim(COALESCE(item_rows.pay_channel, '')))
        || ':' || COALESCE(item_rows.umbrella_id::text, transfer_rows.umbrella_id::text, 'NO_UMBRELLA')
        || ':' || COALESCE(transfer_rows.transfer_group_key, 'NO_TRANSFER_GROUP')
      ) AS candidate_payment_group_key
    FROM public.pay_batch_items AS item_rows
    JOIN public.pay_batch_candidates AS batch_candidate_rows
      ON batch_candidate_rows.id = item_rows.pay_batch_candidate_id
    LEFT JOIN public.pay_bank_transfers AS transfer_rows
      ON transfer_rows.id = item_rows.pay_bank_transfer_id
    WHERE item_rows.id = ANY(COALESCE(v_pay_batch_item_ids, ARRAY[]::uuid[]))
  ), reservation_rows AS (
    SELECT reservation_source_rows.*
    FROM public.pay_advance_reservations AS reservation_source_rows
    WHERE reservation_source_rows.pay_batch_id = p_pay_batch_id
      AND (
        reservation_source_rows.pay_batch_item_id = ANY(COALESCE(v_pay_batch_item_ids, ARRAY[]::uuid[]))
        OR reservation_source_rows.pay_batch_candidate_id = ANY(COALESCE(v_selected_pay_batch_candidate_ids, ARRAY[]::uuid[]))
      )
  )
  SELECT
    COALESCE(array_agg(DISTINCT expanded_batch_items.pay_batch_candidate_id) FILTER (WHERE expanded_batch_items.pay_batch_candidate_id IS NOT NULL), ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT expanded_batch_items.candidate_id) FILTER (WHERE expanded_batch_items.candidate_id IS NOT NULL), ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT expanded_batch_items.umbrella_id) FILTER (WHERE expanded_batch_items.umbrella_id IS NOT NULL), ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT expanded_batch_items.pay_bank_transfer_id) FILTER (WHERE expanded_batch_items.pay_bank_transfer_id IS NOT NULL), ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT COALESCE(expanded_batch_items.finance_case_id, reservation_rows.finance_case_id)) FILTER (WHERE COALESCE(expanded_batch_items.finance_case_id, reservation_rows.finance_case_id) IS NOT NULL), ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT COALESCE(expanded_batch_items.finance_component_id, reservation_rows.finance_component_id)) FILTER (WHERE COALESCE(expanded_batch_items.finance_component_id, reservation_rows.finance_component_id) IS NOT NULL), ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT COALESCE(expanded_batch_items.reservation_id, reservation_rows.id)) FILTER (WHERE COALESCE(expanded_batch_items.reservation_id, reservation_rows.id) IS NOT NULL), ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT expanded_batch_items.timesheet_id) FILTER (WHERE expanded_batch_items.timesheet_id IS NOT NULL), ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT expanded_batch_items.pay_channel) FILTER (WHERE NULLIF(expanded_batch_items.pay_channel, '') IS NOT NULL), ARRAY[]::text[]),
    COALESCE(array_agg(DISTINCT expanded_batch_items.transfer_group_key) FILTER (WHERE NULLIF(btrim(COALESCE(expanded_batch_items.transfer_group_key, '')), '') IS NOT NULL), ARRAY[]::text[]),
    COALESCE(array_agg(DISTINCT expanded_batch_items.candidate_payment_group_key) FILTER (WHERE NULLIF(btrim(COALESCE(expanded_batch_items.candidate_payment_group_key, '')), '') IS NOT NULL), ARRAY[]::text[])
  INTO
    v_pay_batch_candidate_ids,
    v_candidate_ids,
    v_umbrella_ids,
    v_pay_bank_transfer_ids,
    v_finance_case_ids,
    v_finance_component_ids,
    v_reservation_ids,
    v_timesheet_ids,
    v_pay_channels,
    v_transfer_group_keys,
    v_candidate_payment_group_keys
  FROM expanded_batch_items
  LEFT JOIN reservation_rows
    ON reservation_rows.pay_batch_item_id = expanded_batch_items.pay_batch_item_id
    OR reservation_rows.pay_batch_candidate_id = expanded_batch_items.pay_batch_candidate_id;

  IF COALESCE(array_length(v_authoritative_explicit_item_ids, 1), 0) > 0 THEN
    SELECT COALESCE(array_agg(missing_item_rows.pay_batch_item_id), ARRAY[]::uuid[])
    INTO v_missing_explicit_item_ids
    FROM unnest(COALESCE(v_pay_batch_item_ids, ARRAY[]::uuid[])) AS missing_item_rows(pay_batch_item_id)
    WHERE NOT (missing_item_rows.pay_batch_item_id = ANY(v_authoritative_explicit_item_ids));

    v_is_full_scope := COALESCE(array_length(v_missing_explicit_item_ids, 1), 0) = 0;
  ELSE
    v_is_full_scope := true;
  END IF;

  IF NOT v_is_full_scope THEN
    v_partial_scope_blockers := v_partial_scope_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'SELECT_FULL_UNPAID_PAYMENT_SCOPE_REQUIRED',
      'message', 'The selected rows do not include the whole unpaid payment scope. Select the full payment scope before cancellation or rewind.',
      'missing_pay_batch_item_ids', COALESCE((SELECT jsonb_agg(missing_values.pay_batch_item_id::text ORDER BY missing_values.pay_batch_item_id::text) FROM unnest(v_missing_explicit_item_ids) AS missing_values(pay_batch_item_id)), '[]'::jsonb)
    ));
  END IF;

  IF COALESCE(p_lock_mode, false) THEN
    PERFORM 1
    FROM public.pay_batches AS lock_batch_rows
    WHERE lock_batch_rows.id = p_pay_batch_id
    FOR UPDATE;

    PERFORM 1
    FROM public.pay_bank_transfers AS lock_transfer_rows
    WHERE lock_transfer_rows.id = ANY(COALESCE(v_pay_bank_transfer_ids, ARRAY[]::uuid[]))
    ORDER BY lock_transfer_rows.id
    FOR UPDATE;

    PERFORM 1
    FROM public.pay_batch_candidates AS lock_candidate_rows
    WHERE lock_candidate_rows.id = ANY(COALESCE(v_pay_batch_candidate_ids, ARRAY[]::uuid[]))
    ORDER BY lock_candidate_rows.id
    FOR UPDATE;

    PERFORM 1
    FROM public.pay_batch_items AS lock_item_rows
    WHERE lock_item_rows.id = ANY(COALESCE(v_pay_batch_item_ids, ARRAY[]::uuid[]))
    ORDER BY lock_item_rows.id
    FOR UPDATE;

    PERFORM 1
    FROM public.pay_advance_reservations AS lock_reservation_rows
    WHERE lock_reservation_rows.id = ANY(COALESCE(v_reservation_ids, ARRAY[]::uuid[]))
    ORDER BY lock_reservation_rows.id
    FOR UPDATE;

    PERFORM 1
    FROM public.pay_finance_case_components AS lock_component_rows
    WHERE lock_component_rows.id = ANY(COALESCE(v_finance_component_ids, ARRAY[]::uuid[]))
    ORDER BY lock_component_rows.id
    FOR UPDATE;

    PERFORM 1
    FROM public.pay_payment_correction_requests AS lock_request_rows
    WHERE lock_request_rows.pay_batch_id = p_pay_batch_id
      AND upper(COALESCE(lock_request_rows.status, '')) IN ('REQUESTED', 'PENDING', 'AUTHORISED', 'AUTHORIZED', 'IN_PROGRESS', 'PROCESSING', 'EXPANDED')
    ORDER BY lock_request_rows.id
    FOR UPDATE;

    PERFORM 1
    FROM public.pay_payment_correction_work_items AS lock_work_item_rows
    WHERE lock_work_item_rows.pay_batch_id = p_pay_batch_id
      AND upper(COALESCE(lock_work_item_rows.status, '')) IN ('PENDING', 'CLAIMED', 'LOCKED', 'RUNNING', 'PROCESSING')
    ORDER BY lock_work_item_rows.id
    FOR UPDATE;

    PERFORM 1
    FROM public.banking_pay_operations AS lock_operation_rows
    WHERE lock_operation_rows.pay_batch_id = p_pay_batch_id
      AND upper(COALESCE(lock_operation_rows.status, '')) IN ('QUEUED', 'RUNNING', 'PROCESSING', 'IN_PROGRESS', 'REVIEW_REQUIRED')
    ORDER BY lock_operation_rows.id
    FOR UPDATE;

    PERFORM 1
    FROM public.banking_pay_operation_chunks AS lock_chunk_rows
    JOIN public.banking_pay_operations AS lock_chunk_operation_rows
      ON lock_chunk_operation_rows.id = lock_chunk_rows.operation_id
    WHERE lock_chunk_operation_rows.pay_batch_id = p_pay_batch_id
      AND upper(COALESCE(lock_chunk_rows.status, '')) IN ('PENDING', 'CLAIMED', 'LOCKED', 'RUNNING', 'PROCESSING')
    ORDER BY lock_chunk_rows.id
    FOR UPDATE;
  END IF;

  v_result := jsonb_build_object(
    'scope_type', v_scope_type,
    'pay_batch_id', p_pay_batch_id::text,
    'pay_batch_candidate_ids', COALESCE((SELECT jsonb_agg(scope_values.value_id::text ORDER BY scope_values.value_id::text) FROM unnest(COALESCE(v_pay_batch_candidate_ids, ARRAY[]::uuid[])) AS scope_values(value_id)), '[]'::jsonb),
    'candidate_ids', COALESCE((SELECT jsonb_agg(scope_values.value_id::text ORDER BY scope_values.value_id::text) FROM unnest(COALESCE(v_candidate_ids, ARRAY[]::uuid[])) AS scope_values(value_id)), '[]'::jsonb),
    'umbrella_ids', COALESCE((SELECT jsonb_agg(scope_values.value_id::text ORDER BY scope_values.value_id::text) FROM unnest(COALESCE(v_umbrella_ids, ARRAY[]::uuid[])) AS scope_values(value_id)), '[]'::jsonb),
    'pay_bank_transfer_ids', COALESCE((SELECT jsonb_agg(scope_values.value_id::text ORDER BY scope_values.value_id::text) FROM unnest(COALESCE(v_pay_bank_transfer_ids, ARRAY[]::uuid[])) AS scope_values(value_id)), '[]'::jsonb),
    'pay_batch_item_ids', COALESCE((SELECT jsonb_agg(scope_values.value_id::text ORDER BY scope_values.value_id::text) FROM unnest(COALESCE(v_pay_batch_item_ids, ARRAY[]::uuid[])) AS scope_values(value_id)), '[]'::jsonb),
    'finance_case_ids', COALESCE((SELECT jsonb_agg(scope_values.value_id::text ORDER BY scope_values.value_id::text) FROM unnest(COALESCE(v_finance_case_ids, ARRAY[]::uuid[])) AS scope_values(value_id)), '[]'::jsonb),
    'finance_component_ids', COALESCE((SELECT jsonb_agg(scope_values.value_id::text ORDER BY scope_values.value_id::text) FROM unnest(COALESCE(v_finance_component_ids, ARRAY[]::uuid[])) AS scope_values(value_id)), '[]'::jsonb),
    'reservation_ids', COALESCE((SELECT jsonb_agg(scope_values.value_id::text ORDER BY scope_values.value_id::text) FROM unnest(COALESCE(v_reservation_ids, ARRAY[]::uuid[])) AS scope_values(value_id)), '[]'::jsonb),
    'timesheet_ids', COALESCE((SELECT jsonb_agg(scope_values.value_id::text ORDER BY scope_values.value_id::text) FROM unnest(COALESCE(v_timesheet_ids, ARRAY[]::uuid[])) AS scope_values(value_id)), '[]'::jsonb),
    'pay_channels', COALESCE((SELECT jsonb_agg(scope_values.value_text ORDER BY scope_values.value_text) FROM unnest(COALESCE(v_pay_channels, ARRAY[]::text[])) AS scope_values(value_text)), '[]'::jsonb),
    'transfer_group_keys', COALESCE((SELECT jsonb_agg(scope_values.value_text ORDER BY scope_values.value_text) FROM unnest(COALESCE(v_transfer_group_keys, ARRAY[]::text[])) AS scope_values(value_text)), '[]'::jsonb),
    'candidate_payment_group_keys', COALESCE((SELECT jsonb_agg(scope_values.value_text ORDER BY scope_values.value_text) FROM unnest(COALESCE(v_candidate_payment_group_keys, ARRAY[]::text[])) AS scope_values(value_text)), '[]'::jsonb),
    'is_full_scope', v_is_full_scope,
    'partial_scope_blockers', COALESCE(v_partial_scope_blockers, '[]'::jsonb),
    'support_details_json', jsonb_build_object(
      'selected_item_count', v_selected_item_count,
      'expanded_item_count', v_expanded_item_count,
      'explicit_pay_batch_item_ids', COALESCE((SELECT jsonb_agg(scope_values.value_id::text ORDER BY scope_values.value_id::text) FROM unnest(COALESCE(v_explicit_pay_batch_item_ids, ARRAY[]::uuid[])) AS scope_values(value_id)), '[]'::jsonb),
      'expected_pay_batch_item_ids', COALESCE((SELECT jsonb_agg(scope_values.value_id::text ORDER BY scope_values.value_id::text) FROM unnest(COALESCE(v_expected_pay_batch_item_ids, ARRAY[]::uuid[])) AS scope_values(value_id)), '[]'::jsonb),
      'lock_mode', COALESCE(p_lock_mode, false),
      'actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END
    )
  );

  RETURN v_result;
END;
$function$;


CREATE OR REPLACE FUNCTION public._pay_bank_transfer_provider_evidence_classify(
  p_pay_batch_id uuid DEFAULT NULL::uuid,
  p_pay_bank_transfer_id uuid DEFAULT NULL::uuid,
  p_selection_json jsonb DEFAULT NULL::jsonb,
  p_operation_id uuid DEFAULT NULL::uuid
)
RETURNS TABLE(
  evidence_class text,
  provider_submitted boolean,
  provider_request_sent boolean,
  provider_response_present boolean,
  provider_event_present boolean,
  provider_external_id_present boolean,
  local_prepared_only boolean,
  cash_state text,
  blocker_code text,
  reason text,
  support_details_json jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_effective_pay_batch_id uuid := p_pay_batch_id;
  v_uuid_regex text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_scope_type text := NULL::text;
  v_direct_transfer_ids uuid[] := ARRAY[]::uuid[];
  v_selected_transfer_ids uuid[] := ARRAY[]::uuid[];
  v_transfer_ids uuid[] := ARRAY[]::uuid[];
  v_transfer_count integer := 0;
  v_scope_row_count integer := 0;
  v_provider_external_id_count integer := 0;
  v_provider_response_count integer := 0;
  v_provider_event_count integer := 0;
  v_provider_request_sent_count integer := 0;
  v_provider_response_event_count integer := 0;
  v_provider_poll_event_count integer := 0;
  v_verified_webhook_event_count integer := 0;
  v_failed_webhook_replay_event_count integer := 0;
  v_invalid_or_unverified_webhook_event_count integer := 0;
  v_canonical_provider_external_id_count integer := 0;
  v_canonical_final_paid_count integer := 0;
  v_canonical_terminal_no_money_count integer := 0;
  v_canonical_pending_non_final_count integer := 0;
  v_canonical_unknown_cash_state_count integer := 0;
  v_canonical_event_cash_state_counts jsonb := '{}'::jsonb;
  v_provider_outcome_unknown_count integer := 0;
  v_local_prepare_identity_count integer := 0;
  v_final_paid_count integer := 0;
  v_terminal_no_money_count integer := 0;
  v_pending_non_final_count integer := 0;
  v_unknown_cash_state_count integer := 0;
  v_operation_submit_attempt_count integer := 0;
  v_operation_submit_unknown_count integer := 0;
  v_operation_payload_evidence_count integer := 0;
  v_chunk_submit_attempt_count integer := 0;
BEGIN
  IF p_pay_bank_transfer_id IS NOT NULL AND v_effective_pay_batch_id IS NULL THEN
    SELECT transfer_row.pay_batch_id
    INTO v_effective_pay_batch_id
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.id = p_pay_bank_transfer_id;
  END IF;

  IF p_selection_json IS NOT NULL AND jsonb_typeof(p_selection_json) = 'object' THEN
    v_scope_type := upper(NULLIF(btrim(COALESCE(p_selection_json->>'scope_type', '')), ''));
  END IF;

  IF p_pay_bank_transfer_id IS NOT NULL THEN
    v_direct_transfer_ids := ARRAY[p_pay_bank_transfer_id];
  END IF;

  IF p_selection_json IS NOT NULL AND jsonb_typeof(p_selection_json) = 'object' THEN
    WITH raw_values AS (
      SELECT direct_transfer_values.raw_value
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(p_selection_json->'pay_bank_transfer_ids') = 'array' THEN p_selection_json->'pay_bank_transfer_ids'
          ELSE '[]'::jsonb
        END
      ) AS direct_transfer_values(raw_value)
      UNION ALL
      SELECT p_selection_json->>'pay_bank_transfer_id'
      WHERE p_selection_json ? 'pay_bank_transfer_id'
    ), clean_values AS (
      SELECT NULLIF(btrim(raw_values.raw_value), '') AS clean_value
      FROM raw_values
    )
    SELECT COALESCE(array_agg(clean_values.clean_value::uuid), ARRAY[]::uuid[])
    INTO v_selected_transfer_ids
    FROM clean_values
    WHERE clean_values.clean_value IS NOT NULL
      AND clean_values.clean_value ~ v_uuid_regex;
  END IF;

  v_transfer_ids := COALESCE(v_direct_transfer_ids, ARRAY[]::uuid[]) || COALESCE(v_selected_transfer_ids, ARRAY[]::uuid[]);

  IF v_effective_pay_batch_id IS NOT NULL
     AND p_selection_json IS NOT NULL
     AND jsonb_typeof(p_selection_json) = 'object'
     AND v_scope_type IS NOT NULL THEN
    BEGIN
      SELECT COALESCE(array_agg(DISTINCT selected_items.pay_bank_transfer_id) FILTER (WHERE selected_items.pay_bank_transfer_id IS NOT NULL), ARRAY[]::uuid[])
      INTO v_selected_transfer_ids
      FROM public._pay_payment_correction_selected_items(v_effective_pay_batch_id, p_selection_json, true) AS selected_items;

      v_transfer_ids := COALESCE(v_transfer_ids, ARRAY[]::uuid[]) || COALESCE(v_selected_transfer_ids, ARRAY[]::uuid[]);
    EXCEPTION
      WHEN OTHERS THEN
        v_transfer_ids := COALESCE(v_transfer_ids, ARRAY[]::uuid[]);
    END;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT transfer_id_rows.transfer_id) FILTER (WHERE transfer_id_rows.transfer_id IS NOT NULL), ARRAY[]::uuid[])
  INTO v_transfer_ids
  FROM unnest(COALESCE(v_transfer_ids, ARRAY[]::uuid[])) AS transfer_id_rows(transfer_id);

  IF v_effective_pay_batch_id IS NOT NULL
     AND COALESCE(array_length(v_transfer_ids, 1), 0) = 0
     AND (p_selection_json IS NULL OR v_scope_type = 'BATCH') THEN
    SELECT COALESCE(array_agg(batch_transfer_rows.id), ARRAY[]::uuid[])
    INTO v_transfer_ids
    FROM public.pay_bank_transfers AS batch_transfer_rows
    WHERE batch_transfer_rows.pay_batch_id = v_effective_pay_batch_id;
  END IF;

  WITH target_transfers AS (
    SELECT transfer_row.*
    FROM public.pay_bank_transfers AS transfer_row
    WHERE (
        COALESCE(array_length(v_transfer_ids, 1), 0) > 0
        AND transfer_row.id = ANY(v_transfer_ids)
      )
      OR (
        COALESCE(array_length(v_transfer_ids, 1), 0) = 0
        AND v_effective_pay_batch_id IS NOT NULL
        AND transfer_row.pay_batch_id = v_effective_pay_batch_id
        AND (p_selection_json IS NULL OR v_scope_type = 'BATCH')
      )
  ), target_scopes AS (
    SELECT scope_row.*
    FROM public.banking_pay_operation_transfer_scope AS scope_row
    WHERE (v_effective_pay_batch_id IS NULL OR scope_row.pay_batch_id = v_effective_pay_batch_id)
      AND (p_operation_id IS NULL OR scope_row.operation_id = p_operation_id)
      AND (
        COALESCE(array_length(v_transfer_ids, 1), 0) = 0
        OR scope_row.pay_bank_transfer_id = ANY(v_transfer_ids)
        OR EXISTS (
          SELECT 1
          FROM target_transfers AS transfer_for_scope
          WHERE transfer_for_scope.pay_batch_id = scope_row.pay_batch_id
            AND transfer_for_scope.pay_channel = scope_row.pay_channel
            AND NULLIF(btrim(COALESCE(transfer_for_scope.transfer_group_key, '')), '') IS NOT NULL
            AND transfer_for_scope.transfer_group_key = scope_row.transfer_group_key
        )
      )
  ), evidence_rows AS (
    SELECT
      'TRANSFER'::text AS evidence_source,
      transfer_row.id AS pay_bank_transfer_id,
      transfer_row.pay_batch_id AS pay_batch_id,
      NULL::uuid AS operation_id,
      transfer_row.status AS transfer_status,
      transfer_row.rail_state AS rail_state,
      transfer_row.request_id AS request_id,
      transfer_row.payment_reference AS payment_reference,
      transfer_row.rail_tx_id AS rail_tx_id,
      COALESCE(transfer_row.rail_meta_json, '{}'::jsonb) AS meta_json,
      transfer_row.completed_at_utc AS completed_at_utc
    FROM target_transfers AS transfer_row
    UNION ALL
    SELECT
      'TRANSFER_SCOPE'::text AS evidence_source,
      scope_row.pay_bank_transfer_id AS pay_bank_transfer_id,
      scope_row.pay_batch_id AS pay_batch_id,
      scope_row.operation_id AS operation_id,
      scope_row.status AS transfer_status,
      NULL::text AS rail_state,
      scope_row.request_id AS request_id,
      scope_row.payment_reference AS payment_reference,
      NULL::text AS rail_tx_id,
      jsonb_build_object(
        'scope_id', scope_row.id::text,
        'operation_id', scope_row.operation_id::text,
        'scope_status', scope_row.status,
        'scope_request_id_present', NULLIF(btrim(COALESCE(scope_row.request_id, '')), '') IS NOT NULL,
        'scope_payment_reference_present', NULLIF(btrim(COALESCE(scope_row.payment_reference, '')), '') IS NOT NULL
      ) AS meta_json,
      NULL::timestamptz AS completed_at_utc
    FROM target_scopes AS scope_row
  ), classified_evidence_rows AS (
    SELECT
      evidence_rows.*,
      classification_rows.cash_state AS classified_cash_state,
      classification_rows.is_final_money_moved AS classified_is_final_money_moved,
      classification_rows.is_terminal_no_money AS classified_is_terminal_no_money,
      classification_rows.is_pending_non_final AS classified_is_pending_non_final,
      classification_rows.support_details_json AS classification_support_details_json,
      (
        NULLIF(btrim(COALESCE(evidence_rows.request_id, '')), '') IS NOT NULL
        OR NULLIF(btrim(COALESCE(evidence_rows.payment_reference, '')), '') IS NOT NULL
        OR evidence_rows.evidence_source = 'TRANSFER_SCOPE'
      ) AS has_local_prepare_identity,
      (
        (NULLIF(btrim(COALESCE(evidence_rows.rail_tx_id, '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(evidence_rows.rail_tx_id, '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'rail_tx_id', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'rail_tx_id', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'provider_transaction_id', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'provider_transaction_id', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'provider_payment_id', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'provider_payment_id', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'provider_reference', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'provider_reference', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(evidence_rows.meta_json #>> '{provider,transaction_id}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json #>> '{provider,transaction_id}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(evidence_rows.meta_json #>> '{provider,payment_id}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json #>> '{provider,payment_id}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
      ) AS has_provider_external_id,
      (
        (evidence_rows.meta_json ? 'provider_response' AND evidence_rows.meta_json->'provider_response' IS NOT NULL AND evidence_rows.meta_json->'provider_response' <> 'null'::jsonb AND ((jsonb_typeof(evidence_rows.meta_json->'provider_response') = 'object' AND evidence_rows.meta_json->'provider_response' <> '{}'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'provider_response') = 'array' AND evidence_rows.meta_json->'provider_response' <> '[]'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'provider_response') = 'string' AND NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'provider_response')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'provider_response')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(evidence_rows.meta_json->'provider_response') = 'number')))
        OR (evidence_rows.meta_json ? 'provider_response_json' AND evidence_rows.meta_json->'provider_response_json' IS NOT NULL AND evidence_rows.meta_json->'provider_response_json' <> 'null'::jsonb AND ((jsonb_typeof(evidence_rows.meta_json->'provider_response_json') = 'object' AND evidence_rows.meta_json->'provider_response_json' <> '{}'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'provider_response_json') = 'array' AND evidence_rows.meta_json->'provider_response_json' <> '[]'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'provider_response_json') = 'string' AND NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'provider_response_json')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'provider_response_json')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(evidence_rows.meta_json->'provider_response_json') = 'number')))
        OR (evidence_rows.meta_json ? 'submit_response' AND evidence_rows.meta_json->'submit_response' IS NOT NULL AND evidence_rows.meta_json->'submit_response' <> 'null'::jsonb AND ((jsonb_typeof(evidence_rows.meta_json->'submit_response') = 'object' AND evidence_rows.meta_json->'submit_response' <> '{}'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'submit_response') = 'array' AND evidence_rows.meta_json->'submit_response' <> '[]'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'submit_response') = 'string' AND NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'submit_response')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'submit_response')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(evidence_rows.meta_json->'submit_response') = 'number')))
        OR (evidence_rows.meta_json ? 'response_json' AND evidence_rows.meta_json->'response_json' IS NOT NULL AND evidence_rows.meta_json->'response_json' <> 'null'::jsonb AND ((jsonb_typeof(evidence_rows.meta_json->'response_json') = 'object' AND evidence_rows.meta_json->'response_json' <> '{}'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'response_json') = 'array' AND evidence_rows.meta_json->'response_json' <> '[]'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'response_json') = 'string' AND NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'response_json')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'response_json')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(evidence_rows.meta_json->'response_json') = 'number')))
        OR (evidence_rows.meta_json ? 'provider_result' AND evidence_rows.meta_json->'provider_result' IS NOT NULL AND evidence_rows.meta_json->'provider_result' <> 'null'::jsonb AND ((jsonb_typeof(evidence_rows.meta_json->'provider_result') = 'object' AND evidence_rows.meta_json->'provider_result' <> '{}'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'provider_result') = 'array' AND evidence_rows.meta_json->'provider_result' <> '[]'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'provider_result') = 'string' AND NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'provider_result')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'provider_result')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(evidence_rows.meta_json->'provider_result') = 'number')))
        OR (evidence_rows.meta_json ? 'provider_payload' AND evidence_rows.meta_json->'provider_payload' IS NOT NULL AND evidence_rows.meta_json->'provider_payload' <> 'null'::jsonb AND ((jsonb_typeof(evidence_rows.meta_json->'provider_payload') = 'object' AND evidence_rows.meta_json->'provider_payload' <> '{}'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'provider_payload') = 'array' AND evidence_rows.meta_json->'provider_payload' <> '[]'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'provider_payload') = 'string' AND NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'provider_payload')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'provider_payload')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(evidence_rows.meta_json->'provider_payload') = 'number')))
        OR (NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'http_status', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'http_status', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'provider_http_status', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'provider_http_status', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'response_status', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'response_status', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(evidence_rows.meta_json #>> '{provider,response}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json #>> '{provider,response}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
      ) AS has_provider_response,
      (
        (evidence_rows.meta_json ? 'provider_event' AND evidence_rows.meta_json->'provider_event' IS NOT NULL AND evidence_rows.meta_json->'provider_event' <> 'null'::jsonb AND ((jsonb_typeof(evidence_rows.meta_json->'provider_event') = 'object' AND evidence_rows.meta_json->'provider_event' <> '{}'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'provider_event') = 'array' AND evidence_rows.meta_json->'provider_event' <> '[]'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'provider_event') = 'string' AND NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'provider_event')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'provider_event')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(evidence_rows.meta_json->'provider_event') = 'number')))
        OR (evidence_rows.meta_json ? 'latest_provider_event' AND evidence_rows.meta_json->'latest_provider_event' IS NOT NULL AND evidence_rows.meta_json->'latest_provider_event' <> 'null'::jsonb AND ((jsonb_typeof(evidence_rows.meta_json->'latest_provider_event') = 'object' AND evidence_rows.meta_json->'latest_provider_event' <> '{}'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'latest_provider_event') = 'array' AND evidence_rows.meta_json->'latest_provider_event' <> '[]'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'latest_provider_event') = 'string' AND NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'latest_provider_event')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'latest_provider_event')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(evidence_rows.meta_json->'latest_provider_event') = 'number')))
        OR (evidence_rows.meta_json ? 'webhook' AND evidence_rows.meta_json->'webhook' IS NOT NULL AND evidence_rows.meta_json->'webhook' <> 'null'::jsonb AND ((jsonb_typeof(evidence_rows.meta_json->'webhook') = 'object' AND evidence_rows.meta_json->'webhook' <> '{}'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'webhook') = 'array' AND evidence_rows.meta_json->'webhook' <> '[]'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'webhook') = 'string' AND NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'webhook')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'webhook')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(evidence_rows.meta_json->'webhook') = 'number')))
        OR (evidence_rows.meta_json ? 'events' AND evidence_rows.meta_json->'events' IS NOT NULL AND evidence_rows.meta_json->'events' <> 'null'::jsonb AND ((jsonb_typeof(evidence_rows.meta_json->'events') = 'object' AND evidence_rows.meta_json->'events' <> '{}'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'events') = 'array' AND evidence_rows.meta_json->'events' <> '[]'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'events') = 'string' AND NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'events')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'events')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(evidence_rows.meta_json->'events') = 'number')))
        OR (evidence_rows.meta_json ? 'poll_result' AND evidence_rows.meta_json->'poll_result' IS NOT NULL AND evidence_rows.meta_json->'poll_result' <> 'null'::jsonb AND ((jsonb_typeof(evidence_rows.meta_json->'poll_result') = 'object' AND evidence_rows.meta_json->'poll_result' <> '{}'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'poll_result') = 'array' AND evidence_rows.meta_json->'poll_result' <> '[]'::jsonb) OR (jsonb_typeof(evidence_rows.meta_json->'poll_result') = 'string' AND NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'poll_result')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (evidence_rows.meta_json->'poll_result')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(evidence_rows.meta_json->'poll_result') = 'number')))
        OR (NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'poll_status', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'poll_status', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'event_id', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'event_id', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'provider_event_id', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'provider_event_id', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(evidence_rows.meta_json #>> '{provider,event_id}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json #>> '{provider,event_id}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
      ) AS has_provider_event,
      (
        lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'provider_request_sent', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'request_sent', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'provider_submit_attempted', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'request_dispatched', '')), '')) IN ('true','t','yes','y','1')
        OR (NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'request_sent_at_utc', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'request_sent_at_utc', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'provider_request_sent_at_utc', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'provider_request_sent_at_utc', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR upper(NULLIF(btrim(COALESCE(evidence_rows.transfer_status, '')), '')) IN ('REQUEST_SENT', 'PROVIDER_REQUEST_SENT', 'SUBMITTED', 'SENT', 'PROCESSING', 'ACCEPTED', 'PROVIDER_SUBMITTED', 'SUBMISSION_UNKNOWN', 'REQUEST_SENT_NO_RESPONSE')
      ) AS has_provider_request_sent,
      (
        lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'provider_outcome_unknown', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(evidence_rows.meta_json->>'request_sent_no_response', '')), '')) IN ('true','t','yes','y','1')
        OR upper(NULLIF(btrim(COALESCE(evidence_rows.transfer_status, '')), '')) IN ('UNKNOWN', 'SUBMISSION_UNKNOWN', 'PROVIDER_OUTCOME_UNKNOWN', 'REQUEST_SENT_NO_RESPONSE')
      ) AS has_provider_outcome_unknown
    FROM evidence_rows
    CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
      evidence_rows.transfer_status,
      evidence_rows.rail_state,
      evidence_rows.meta_json,
      evidence_rows.meta_json
    ) AS classification_rows
  )
  SELECT
    (SELECT count(*)::integer FROM target_transfers),
    (SELECT count(*)::integer FROM target_scopes),
    COALESCE((count(*) FILTER (WHERE classified_evidence_rows.has_provider_external_id))::integer, 0),
    COALESCE((count(*) FILTER (WHERE classified_evidence_rows.has_provider_response))::integer, 0),
    COALESCE((count(*) FILTER (WHERE classified_evidence_rows.has_provider_event))::integer, 0),
    COALESCE((count(*) FILTER (WHERE classified_evidence_rows.has_provider_request_sent))::integer, 0),
    COALESCE((count(*) FILTER (WHERE classified_evidence_rows.has_provider_outcome_unknown))::integer, 0),
    COALESCE((count(*) FILTER (WHERE classified_evidence_rows.has_local_prepare_identity))::integer, 0),
    COALESCE((count(*) FILTER (WHERE classified_evidence_rows.classified_is_final_money_moved))::integer, 0),
    COALESCE((count(*) FILTER (WHERE classified_evidence_rows.classified_is_terminal_no_money))::integer, 0),
    COALESCE((count(*) FILTER (WHERE classified_evidence_rows.classified_is_pending_non_final))::integer, 0),
    COALESCE((count(*) FILTER (WHERE classified_evidence_rows.classified_cash_state = 'UNKNOWN'))::integer, 0)
  INTO
    v_transfer_count,
    v_scope_row_count,
    v_provider_external_id_count,
    v_provider_response_count,
    v_provider_event_count,
    v_provider_request_sent_count,
    v_provider_outcome_unknown_count,
    v_local_prepare_identity_count,
    v_final_paid_count,
    v_terminal_no_money_count,
    v_pending_non_final_count,
    v_unknown_cash_state_count
  FROM classified_evidence_rows;


  WITH canonical_event_rows AS (
    SELECT
      event_row.id AS event_id,
      event_row.pay_bank_transfer_id,
      event_row.pay_batch_id,
      event_row.provider_key,
      event_row.provider_event_transport,
      event_row.provider_signature_valid,
      event_row.provider_webhook_receipt_id,
      event_row.provider_transaction_id,
      event_row.provider_request_id,
      event_row.provider_event_key,
      event_row.rail_env,
      event_row.normalised_state,
      event_row.provider_state,
      COALESCE(event_row.raw_payload, '{}'::jsonb) AS raw_payload_json,
      receipt_row.status AS receipt_status,
      receipt_row.provider_key AS receipt_provider_key,
      receipt_row.rail_env AS receipt_rail_env,
      receipt_row.provider_event_key AS receipt_provider_event_key,
      receipt_row.signature_valid AS receipt_signature_valid
    FROM public.pay_bank_transfer_events AS event_row
    LEFT JOIN public.bank_provider_webhook_receipts AS receipt_row
      ON receipt_row.id = event_row.provider_webhook_receipt_id
    WHERE (v_effective_pay_batch_id IS NULL OR event_row.pay_batch_id = v_effective_pay_batch_id)
      AND (
        COALESCE(array_length(v_transfer_ids, 1), 0) = 0
        OR event_row.pay_bank_transfer_id = ANY(v_transfer_ids)
        OR event_row.pay_bank_transfer_id IS NULL
      )
  ), canonical_classified_events AS (
    SELECT
      canonical_event_rows.*,
      movement_rows.cash_state AS classified_cash_state,
      movement_rows.is_final_money_moved AS classified_is_final_money_moved,
      movement_rows.is_terminal_no_money AS classified_is_terminal_no_money,
      movement_rows.is_pending_non_final AS classified_is_pending_non_final,
      (
        canonical_event_rows.provider_event_transport = 'PROVIDER_WEBHOOK'
        AND canonical_event_rows.provider_signature_valid IS TRUE
        AND canonical_event_rows.provider_webhook_receipt_id IS NOT NULL
        AND canonical_event_rows.receipt_status IS NOT NULL
        AND upper(COALESCE(canonical_event_rows.receipt_status, '')) NOT IN ('SIGNATURE_INVALID', 'FAILED_FINAL', 'FAILED_RETRYABLE')
        AND canonical_event_rows.receipt_signature_valid IS TRUE
        AND canonical_event_rows.receipt_provider_key IS NOT DISTINCT FROM canonical_event_rows.provider_key
        AND canonical_event_rows.receipt_rail_env IS NOT DISTINCT FROM canonical_event_rows.rail_env
        AND NULLIF(btrim(COALESCE(canonical_event_rows.provider_event_key, '')), '') IS NOT NULL
        AND canonical_event_rows.receipt_provider_event_key IS NOT NULL
        AND canonical_event_rows.receipt_provider_event_key = canonical_event_rows.provider_event_key
      ) AS is_verified_webhook_event,
      (
        canonical_event_rows.provider_event_transport = 'FAILED_WEBHOOK_REPLAY'
        AND canonical_event_rows.provider_webhook_receipt_id IS NOT NULL
        AND canonical_event_rows.receipt_status IS NOT NULL
        AND upper(COALESCE(canonical_event_rows.receipt_status, '')) NOT IN ('SIGNATURE_INVALID', 'FAILED_FINAL')
        AND canonical_event_rows.receipt_provider_key IS NOT DISTINCT FROM canonical_event_rows.provider_key
        AND canonical_event_rows.receipt_rail_env IS NOT DISTINCT FROM canonical_event_rows.rail_env
        AND NULLIF(btrim(COALESCE(canonical_event_rows.provider_event_key, '')), '') IS NOT NULL
        AND canonical_event_rows.receipt_provider_event_key IS NOT NULL
        AND canonical_event_rows.receipt_provider_event_key = canonical_event_rows.provider_event_key
      ) AS is_valid_failed_webhook_replay_event,
      (
        canonical_event_rows.provider_event_transport = 'PROVIDER_WEBHOOK'
        AND NOT (
          canonical_event_rows.provider_signature_valid IS TRUE
          AND canonical_event_rows.provider_webhook_receipt_id IS NOT NULL
          AND canonical_event_rows.receipt_status IS NOT NULL
          AND upper(COALESCE(canonical_event_rows.receipt_status, '')) NOT IN ('SIGNATURE_INVALID', 'FAILED_FINAL', 'FAILED_RETRYABLE')
          AND canonical_event_rows.receipt_signature_valid IS TRUE
          AND canonical_event_rows.receipt_provider_key IS NOT DISTINCT FROM canonical_event_rows.provider_key
          AND canonical_event_rows.receipt_rail_env IS NOT DISTINCT FROM canonical_event_rows.rail_env
          AND NULLIF(btrim(COALESCE(canonical_event_rows.provider_event_key, '')), '') IS NOT NULL
          AND canonical_event_rows.receipt_provider_event_key IS NOT NULL
          AND canonical_event_rows.receipt_provider_event_key = canonical_event_rows.provider_event_key
        )
      ) AS is_invalid_or_unverified_webhook_event,
      (
        NULLIF(btrim(COALESCE(canonical_event_rows.provider_transaction_id, '')), '') IS NOT NULL
        OR NULLIF(btrim(COALESCE(canonical_event_rows.provider_event_key, '')), '') IS NOT NULL
      ) AS has_canonical_external_id
    FROM canonical_event_rows
    CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
      canonical_event_rows.normalised_state,
      canonical_event_rows.provider_state,
      canonical_event_rows.raw_payload_json,
      jsonb_build_object(
        'provider_key', canonical_event_rows.provider_key,
        'provider_event_transport', canonical_event_rows.provider_event_transport,
        'provider_event_key', canonical_event_rows.provider_event_key,
        'provider_transaction_id', canonical_event_rows.provider_transaction_id,
        'provider_request_id', canonical_event_rows.provider_request_id,
        'rail_env', canonical_event_rows.rail_env
      )
    ) AS movement_rows
  )
  SELECT
    COALESCE((count(*) FILTER (WHERE canonical_classified_events.provider_event_transport = 'PROVIDER_RESPONSE'))::integer, 0),
    COALESCE((count(*) FILTER (WHERE canonical_classified_events.provider_event_transport = 'PROVIDER_POLL'))::integer, 0),
    COALESCE((count(*) FILTER (WHERE canonical_classified_events.is_verified_webhook_event))::integer, 0),
    COALESCE((count(*) FILTER (WHERE canonical_classified_events.is_valid_failed_webhook_replay_event))::integer, 0),
    COALESCE((count(*) FILTER (WHERE canonical_classified_events.is_invalid_or_unverified_webhook_event))::integer, 0),
    COALESCE((count(*) FILTER (WHERE canonical_classified_events.has_canonical_external_id))::integer, 0),
    COALESCE((count(*) FILTER (WHERE canonical_classified_events.classified_is_final_money_moved))::integer, 0),
    COALESCE((count(*) FILTER (WHERE canonical_classified_events.classified_is_terminal_no_money))::integer, 0),
    COALESCE((count(*) FILTER (WHERE canonical_classified_events.classified_is_pending_non_final))::integer, 0),
    COALESCE((count(*) FILTER (WHERE canonical_classified_events.classified_cash_state = 'UNKNOWN'))::integer, 0)
  INTO
    v_provider_response_event_count,
    v_provider_poll_event_count,
    v_verified_webhook_event_count,
    v_failed_webhook_replay_event_count,
    v_invalid_or_unverified_webhook_event_count,
    v_canonical_provider_external_id_count,
    v_canonical_final_paid_count,
    v_canonical_terminal_no_money_count,
    v_canonical_pending_non_final_count,
    v_canonical_unknown_cash_state_count
  FROM canonical_classified_events;

  WITH canonical_event_rows AS (
    SELECT
      event_row.normalised_state,
      event_row.provider_state,
      COALESCE(event_row.raw_payload, '{}'::jsonb) AS raw_payload_json,
      event_row.provider_key,
      event_row.provider_event_transport,
      event_row.provider_event_key,
      event_row.provider_transaction_id,
      event_row.provider_request_id,
      event_row.rail_env
    FROM public.pay_bank_transfer_events AS event_row
    WHERE (v_effective_pay_batch_id IS NULL OR event_row.pay_batch_id = v_effective_pay_batch_id)
      AND (
        COALESCE(array_length(v_transfer_ids, 1), 0) = 0
        OR event_row.pay_bank_transfer_id = ANY(v_transfer_ids)
        OR event_row.pay_bank_transfer_id IS NULL
      )
  ), canonical_cash_counts AS (
    SELECT movement_rows.cash_state, count(*)::integer AS state_count
    FROM canonical_event_rows
    CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
      canonical_event_rows.normalised_state,
      canonical_event_rows.provider_state,
      canonical_event_rows.raw_payload_json,
      jsonb_build_object(
        'provider_key', canonical_event_rows.provider_key,
        'provider_event_transport', canonical_event_rows.provider_event_transport,
        'provider_event_key', canonical_event_rows.provider_event_key,
        'provider_transaction_id', canonical_event_rows.provider_transaction_id,
        'provider_request_id', canonical_event_rows.provider_request_id,
        'rail_env', canonical_event_rows.rail_env
      )
    ) AS movement_rows
    GROUP BY movement_rows.cash_state
  )
  SELECT COALESCE(jsonb_object_agg(canonical_cash_counts.cash_state, canonical_cash_counts.state_count), '{}'::jsonb)
  INTO v_canonical_event_cash_state_counts
  FROM canonical_cash_counts;

  WITH operation_payloads AS (
    SELECT
      'OPERATION'::text AS evidence_source,
      operation_rows.id AS operation_id,
      NULL::uuid AS chunk_id,
      payload_rows.payload_name,
      COALESCE(payload_rows.payload_json, '{}'::jsonb) AS payload_json
    FROM public.banking_pay_operations AS operation_rows
    CROSS JOIN LATERAL (VALUES
      ('progress_json'::text, operation_rows.progress_json),
      ('result_json'::text, operation_rows.result_json),
      ('error_json'::text, operation_rows.error_json)
    ) AS payload_rows(payload_name, payload_json)
    WHERE (p_operation_id IS NOT NULL AND operation_rows.id = p_operation_id)
       OR (
         p_operation_id IS NULL
         AND v_effective_pay_batch_id IS NOT NULL
         AND operation_rows.pay_batch_id = v_effective_pay_batch_id
         AND upper(COALESCE(operation_rows.operation_type, '')) LIKE '%PAY%'
       )
    UNION ALL
    SELECT
      'CHUNK'::text AS evidence_source,
      operation_rows.id AS operation_id,
      chunk_rows.id AS chunk_id,
      payload_rows.payload_name,
      COALESCE(payload_rows.payload_json, '{}'::jsonb) AS payload_json
    FROM public.banking_pay_operation_chunks AS chunk_rows
    JOIN public.banking_pay_operations AS operation_rows
      ON operation_rows.id = chunk_rows.operation_id
    CROSS JOIN LATERAL (VALUES
      ('payload_json'::text, chunk_rows.payload_json),
      ('result_json'::text, chunk_rows.result_json),
      ('error_json'::text, chunk_rows.error_json)
    ) AS payload_rows(payload_name, payload_json)
    WHERE (p_operation_id IS NOT NULL AND chunk_rows.operation_id = p_operation_id)
       OR (
         p_operation_id IS NULL
         AND v_effective_pay_batch_id IS NOT NULL
         AND operation_rows.pay_batch_id = v_effective_pay_batch_id
       )
  ), operation_payload_flags AS (
    SELECT
      operation_payloads.evidence_source,
      operation_payloads.operation_id,
      operation_payloads.chunk_id,
      operation_payloads.payload_name,
      operation_payloads.payload_json,
      (
        lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'provider_request_sent', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'providerRequestSent', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'provider_request_sent_confirmed', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'providerRequestSentConfirmed', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'request_sent', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'requestSent', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'request_dispatched', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'requestDispatched', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'provider_submit_attempted', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'providerSubmitAttempted', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{provider_submit_diagnostic,provider_request_sent}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{providerSubmitDiagnostic,providerRequestSent}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{provider_evidence,provider_request_sent}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{providerEvidence,providerRequestSent}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{diagnostic,provider_request_sent}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{diagnostic,providerRequestSent}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{outcome,provider_request_sent}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{outcome,providerRequestSent}', '')), '')) IN ('true','t','yes','y','1')
        OR (NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'request_sent_at_utc', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'request_sent_at_utc', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'provider_request_sent_at_utc', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'provider_request_sent_at_utc', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'requestSentAtUtc', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'requestSentAtUtc', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'providerRequestSentAtUtc', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'providerRequestSentAtUtc', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{provider_submit_diagnostic,request_sent_at_utc}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{provider_submit_diagnostic,request_sent_at_utc}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{providerSubmitDiagnostic,requestSentAtUtc}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{providerSubmitDiagnostic,requestSentAtUtc}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (
          NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'provider_request_sent_count', '')), '') ~ '^[0-9]+(\.[0-9]+)?$'
          AND (operation_payloads.payload_json->>'provider_request_sent_count')::numeric > 0
        )
        OR (
          NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'providerRequestSentCount', '')), '') ~ '^[0-9]+(\.[0-9]+)?$'
          AND (operation_payloads.payload_json->>'providerRequestSentCount')::numeric > 0
        )
        OR (
          NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'provider_call_sent_count', '')), '') ~ '^[0-9]+(\.[0-9]+)?$'
          AND (operation_payloads.payload_json->>'provider_call_sent_count')::numeric > 0
        )
        OR (
          NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'providerCallSentCount', '')), '') ~ '^[0-9]+(\.[0-9]+)?$'
          AND (operation_payloads.payload_json->>'providerCallSentCount')::numeric > 0
        )
        OR (
          NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{provider_submit_diagnostic,provider_request_sent_count}', '')), '') ~ '^[0-9]+(\.[0-9]+)?$'
          AND (operation_payloads.payload_json #>> '{provider_submit_diagnostic,provider_request_sent_count}')::numeric > 0
        )
        OR (
          NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{providerSubmitDiagnostic,providerRequestSentCount}', '')), '') ~ '^[0-9]+(\.[0-9]+)?$'
          AND (operation_payloads.payload_json #>> '{providerSubmitDiagnostic,providerRequestSentCount}')::numeric > 0
        )
      ) AS has_provider_request_sent,
      (
        lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'provider_outcome_unknown', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'providerOutcomeUnknown', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'request_sent_no_response', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'requestSentNoResponse', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{provider_submit_diagnostic,provider_outcome_unknown}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{providerSubmitDiagnostic,providerOutcomeUnknown}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{diagnostic,provider_outcome_unknown}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{diagnostic,providerOutcomeUnknown}', '')), '')) IN ('true','t','yes','y','1')
        OR upper(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'code', '')), '')) IN ('REQUEST_SENT_NO_RESPONSE', 'PROVIDER_OUTCOME_UNKNOWN', 'SUBMISSION_UNKNOWN')
        OR upper(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'error_code', '')), '')) IN ('REQUEST_SENT_NO_RESPONSE', 'PROVIDER_OUTCOME_UNKNOWN', 'SUBMISSION_UNKNOWN')
        OR upper(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'status', '')), '')) IN ('REQUEST_SENT_NO_RESPONSE', 'PROVIDER_OUTCOME_UNKNOWN', 'SUBMISSION_UNKNOWN')
        OR upper(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'outcome', '')), '')) IN ('REQUEST_SENT_NO_RESPONSE', 'PROVIDER_OUTCOME_UNKNOWN', 'SUBMISSION_UNKNOWN')
        OR upper(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{error,code}', '')), '')) IN ('REQUEST_SENT_NO_RESPONSE', 'PROVIDER_OUTCOME_UNKNOWN', 'SUBMISSION_UNKNOWN')
        OR upper(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{provider_submit_diagnostic,code}', '')), '')) IN ('REQUEST_SENT_NO_RESPONSE', 'PROVIDER_OUTCOME_UNKNOWN', 'SUBMISSION_UNKNOWN')
        OR upper(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{providerSubmitDiagnostic,code}', '')), '')) IN ('REQUEST_SENT_NO_RESPONSE', 'PROVIDER_OUTCOME_UNKNOWN', 'SUBMISSION_UNKNOWN')
      ) AS has_provider_outcome_unknown,
      (
        (NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'rail_tx_id', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'rail_tx_id', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'railTxId', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'railTxId', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'provider_transaction_id', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'provider_transaction_id', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'providerTransactionId', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'providerTransactionId', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'provider_payment_id', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'provider_payment_id', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'providerPaymentId', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json->>'providerPaymentId', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{provider,transaction_id}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{provider,transaction_id}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{provider,transactionId}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{provider,transactionId}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{provider,payment_id}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{provider,payment_id}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{provider,paymentId}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{provider,paymentId}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{provider_submit_diagnostic,provider_transaction_id}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{provider_submit_diagnostic,provider_transaction_id}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{provider_submit_diagnostic,provider_payment_id}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{provider_submit_diagnostic,provider_payment_id}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{providerSubmitDiagnostic,providerTransactionId}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{providerSubmitDiagnostic,providerTransactionId}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{providerSubmitDiagnostic,providerPaymentId}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(operation_payloads.payload_json #>> '{providerSubmitDiagnostic,providerPaymentId}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (operation_payloads.payload_json ? 'provider_response' AND operation_payloads.payload_json->'provider_response' IS NOT NULL AND operation_payloads.payload_json->'provider_response' <> 'null'::jsonb AND ((jsonb_typeof(operation_payloads.payload_json->'provider_response') = 'object' AND operation_payloads.payload_json->'provider_response' <> '{}'::jsonb) OR (jsonb_typeof(operation_payloads.payload_json->'provider_response') = 'array' AND operation_payloads.payload_json->'provider_response' <> '[]'::jsonb) OR (jsonb_typeof(operation_payloads.payload_json->'provider_response') = 'string' AND NULLIF(btrim(trim(both '"' from (operation_payloads.payload_json->'provider_response')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (operation_payloads.payload_json->'provider_response')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(operation_payloads.payload_json->'provider_response') = 'number')))
        OR (operation_payloads.payload_json ? 'provider_response_json' AND operation_payloads.payload_json->'provider_response_json' IS NOT NULL AND operation_payloads.payload_json->'provider_response_json' <> 'null'::jsonb AND ((jsonb_typeof(operation_payloads.payload_json->'provider_response_json') = 'object' AND operation_payloads.payload_json->'provider_response_json' <> '{}'::jsonb) OR (jsonb_typeof(operation_payloads.payload_json->'provider_response_json') = 'array' AND operation_payloads.payload_json->'provider_response_json' <> '[]'::jsonb) OR (jsonb_typeof(operation_payloads.payload_json->'provider_response_json') = 'string' AND NULLIF(btrim(trim(both '"' from (operation_payloads.payload_json->'provider_response_json')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (operation_payloads.payload_json->'provider_response_json')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(operation_payloads.payload_json->'provider_response_json') = 'number')))
        OR (operation_payloads.payload_json ? 'submit_response' AND operation_payloads.payload_json->'submit_response' IS NOT NULL AND operation_payloads.payload_json->'submit_response' <> 'null'::jsonb AND ((jsonb_typeof(operation_payloads.payload_json->'submit_response') = 'object' AND operation_payloads.payload_json->'submit_response' <> '{}'::jsonb) OR (jsonb_typeof(operation_payloads.payload_json->'submit_response') = 'array' AND operation_payloads.payload_json->'submit_response' <> '[]'::jsonb) OR (jsonb_typeof(operation_payloads.payload_json->'submit_response') = 'string' AND NULLIF(btrim(trim(both '"' from (operation_payloads.payload_json->'submit_response')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (operation_payloads.payload_json->'submit_response')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(operation_payloads.payload_json->'submit_response') = 'number')))
        OR (operation_payloads.payload_json ? 'response_json' AND operation_payloads.payload_json->'response_json' IS NOT NULL AND operation_payloads.payload_json->'response_json' <> 'null'::jsonb AND ((jsonb_typeof(operation_payloads.payload_json->'response_json') = 'object' AND operation_payloads.payload_json->'response_json' <> '{}'::jsonb) OR (jsonb_typeof(operation_payloads.payload_json->'response_json') = 'array' AND operation_payloads.payload_json->'response_json' <> '[]'::jsonb) OR (jsonb_typeof(operation_payloads.payload_json->'response_json') = 'string' AND NULLIF(btrim(trim(both '"' from (operation_payloads.payload_json->'response_json')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (operation_payloads.payload_json->'response_json')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(operation_payloads.payload_json->'response_json') = 'number')))
        OR (operation_payloads.payload_json ? 'provider_result' AND operation_payloads.payload_json->'provider_result' IS NOT NULL AND operation_payloads.payload_json->'provider_result' <> 'null'::jsonb AND ((jsonb_typeof(operation_payloads.payload_json->'provider_result') = 'object' AND operation_payloads.payload_json->'provider_result' <> '{}'::jsonb) OR (jsonb_typeof(operation_payloads.payload_json->'provider_result') = 'array' AND operation_payloads.payload_json->'provider_result' <> '[]'::jsonb) OR (jsonb_typeof(operation_payloads.payload_json->'provider_result') = 'string' AND NULLIF(btrim(trim(both '"' from (operation_payloads.payload_json->'provider_result')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (operation_payloads.payload_json->'provider_result')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(operation_payloads.payload_json->'provider_result') = 'number')))
        OR (operation_payloads.payload_json ? 'provider_payload' AND operation_payloads.payload_json->'provider_payload' IS NOT NULL AND operation_payloads.payload_json->'provider_payload' <> 'null'::jsonb AND ((jsonb_typeof(operation_payloads.payload_json->'provider_payload') = 'object' AND operation_payloads.payload_json->'provider_payload' <> '{}'::jsonb) OR (jsonb_typeof(operation_payloads.payload_json->'provider_payload') = 'array' AND operation_payloads.payload_json->'provider_payload' <> '[]'::jsonb) OR (jsonb_typeof(operation_payloads.payload_json->'provider_payload') = 'string' AND NULLIF(btrim(trim(both '"' from (operation_payloads.payload_json->'provider_payload')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (operation_payloads.payload_json->'provider_payload')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(operation_payloads.payload_json->'provider_payload') = 'number')))
      ) AS has_provider_payload_evidence
    FROM operation_payloads
  )
  SELECT
    COALESCE((count(*) FILTER (WHERE operation_payload_flags.evidence_source = 'OPERATION' AND operation_payload_flags.has_provider_request_sent))::integer, 0),
    COALESCE((count(*) FILTER (WHERE operation_payload_flags.has_provider_outcome_unknown))::integer, 0),
    COALESCE((count(*) FILTER (WHERE operation_payload_flags.has_provider_payload_evidence))::integer, 0),
    COALESCE((count(*) FILTER (WHERE operation_payload_flags.evidence_source = 'CHUNK' AND operation_payload_flags.has_provider_request_sent))::integer, 0)
  INTO
    v_operation_submit_attempt_count,
    v_operation_submit_unknown_count,
    v_operation_payload_evidence_count,
    v_chunk_submit_attempt_count
  FROM operation_payload_flags;

  v_operation_submit_attempt_count := COALESCE(v_operation_submit_attempt_count, 0) + COALESCE(v_chunk_submit_attempt_count, 0);

  provider_external_id_present := (v_provider_external_id_count + v_canonical_provider_external_id_count) > 0;
  provider_response_present := v_provider_response_count > 0
    OR v_operation_payload_evidence_count > 0
    OR v_provider_response_event_count > 0;
  provider_event_present := v_provider_poll_event_count > 0
    OR v_verified_webhook_event_count > 0
    OR v_failed_webhook_replay_event_count > 0;
  provider_request_sent := provider_external_id_present
    OR provider_response_present
    OR provider_event_present
    OR v_operation_submit_attempt_count > 0;
  provider_submitted := provider_request_sent;
  local_prepared_only := (
    provider_submitted = false
    AND (
      v_local_prepare_identity_count > 0
      OR v_transfer_count > 0
      OR v_scope_row_count > 0
    )
  );

  v_final_paid_count := v_final_paid_count + v_canonical_final_paid_count;
  v_terminal_no_money_count := v_terminal_no_money_count + v_canonical_terminal_no_money_count;
  v_pending_non_final_count := v_pending_non_final_count + v_canonical_pending_non_final_count;
  v_unknown_cash_state_count := v_unknown_cash_state_count + v_canonical_unknown_cash_state_count;

  IF v_final_paid_count > 0 THEN
    cash_state := 'FINAL_PAID';
  ELSIF v_terminal_no_money_count > 0 THEN
    cash_state := 'TERMINAL_NO_MONEY';
  ELSIF v_pending_non_final_count > 0 THEN
    cash_state := 'PENDING_NON_FINAL';
  ELSIF v_unknown_cash_state_count > 0 OR provider_request_sent THEN
    cash_state := 'UNKNOWN';
  ELSE
    cash_state := 'NO_TRANSFER_EVIDENCE';
  END IF;

  IF provider_request_sent AND (v_provider_outcome_unknown_count > 0 OR v_operation_submit_unknown_count > 0 OR cash_state = 'UNKNOWN') THEN
    evidence_class := 'PROVIDER_OUTCOME_UNKNOWN';
  ELSIF provider_event_present THEN
    evidence_class := 'PROVIDER_EVENT_PRESENT';
  ELSIF provider_response_present THEN
    evidence_class := 'PROVIDER_RESPONSE_PRESENT';
  ELSIF provider_external_id_present THEN
    evidence_class := 'PROVIDER_EXTERNAL_ID_PRESENT';
  ELSIF provider_request_sent THEN
    evidence_class := 'PROVIDER_REQUEST_SENT';
  ELSIF local_prepared_only THEN
    evidence_class := 'LOCAL_PREPARED_ONLY';
  ELSE
    evidence_class := 'NO_PROVIDER_EVIDENCE';
  END IF;

  blocker_code := CASE
    WHEN evidence_class = 'PROVIDER_OUTCOME_UNKNOWN' OR (provider_submitted AND cash_state = 'UNKNOWN') THEN 'PAYMENT_OUTCOME_UNKNOWN_CHECK_PROVIDER'
    WHEN provider_submitted AND cash_state = 'PENDING_NON_FINAL' THEN 'PROVIDER_CANCELLATION_REQUIRED_BEFORE_UNWIND'
    ELSE NULL::text
  END;

  reason := CASE evidence_class
    WHEN 'PROVIDER_EVENT_PRESENT' THEN 'Provider event/webhook/poll evidence is present.'
    WHEN 'PROVIDER_RESPONSE_PRESENT' THEN 'Provider response evidence is present.'
    WHEN 'PROVIDER_EXTERNAL_ID_PRESENT' THEN 'Provider external transaction/payment ID evidence is present.'
    WHEN 'PROVIDER_OUTCOME_UNKNOWN' THEN 'Provider request may have been sent but final outcome is unknown; check/poll provider before retry or unwind.'
    WHEN 'PROVIDER_REQUEST_SENT' THEN 'Provider request-sent evidence is present.'
    WHEN 'LOCAL_PREPARED_ONLY' THEN 'Only local CloudTMS preparation artefacts are present; no provider submission evidence was found.'
    ELSE 'No provider submission evidence was found.'
  END;

  support_details_json := jsonb_build_object(
    'pay_batch_id', CASE WHEN v_effective_pay_batch_id IS NULL THEN NULL ELSE v_effective_pay_batch_id::text END,
    'pay_bank_transfer_id', CASE WHEN p_pay_bank_transfer_id IS NULL THEN NULL ELSE p_pay_bank_transfer_id::text END,
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'scope_type', v_scope_type,
    'transfer_ids', COALESCE((SELECT jsonb_agg(transfer_id_values.transfer_id::text ORDER BY transfer_id_values.transfer_id::text) FROM unnest(COALESCE(v_transfer_ids, ARRAY[]::uuid[])) AS transfer_id_values(transfer_id)), '[]'::jsonb),
    'transfer_count', v_transfer_count,
    'scope_row_count', v_scope_row_count,
    'provider_external_id_count', v_provider_external_id_count,
    'canonical_provider_external_id_count', v_canonical_provider_external_id_count,
    'provider_response_count', v_provider_response_count,
    'provider_response_event_count', v_provider_response_event_count,
    'provider_event_count', v_provider_event_count,
    'provider_poll_event_count', v_provider_poll_event_count,
    'verified_webhook_event_count', v_verified_webhook_event_count,
    'failed_webhook_replay_event_count', v_failed_webhook_replay_event_count,
    'invalid_or_unverified_webhook_event_count', v_invalid_or_unverified_webhook_event_count,
    'canonical_event_cash_state_counts', v_canonical_event_cash_state_counts,
    'provider_request_sent_count', v_provider_request_sent_count,
    'provider_outcome_unknown_count', v_provider_outcome_unknown_count,
    'local_prepare_identity_count', v_local_prepare_identity_count,
    'local_prepared_only', local_prepared_only,
    'local_prepared_only_basis', CASE
      WHEN local_prepared_only THEN jsonb_build_array(
        CASE WHEN v_local_prepare_identity_count > 0 THEN 'local_request_or_scope_identity' ELSE NULL END,
        CASE WHEN v_transfer_count > 0 THEN 'local_transfer_row' ELSE NULL END,
        CASE WHEN v_scope_row_count > 0 THEN 'local_transfer_scope_row' ELSE NULL END
      )
      ELSE '[]'::jsonb
    END,
    'final_paid_count', v_final_paid_count,
    'terminal_no_money_count', v_terminal_no_money_count,
    'pending_non_final_count', v_pending_non_final_count,
    'unknown_cash_state_count', v_unknown_cash_state_count,
    'operation_submit_attempt_count', v_operation_submit_attempt_count,
    'operation_submit_unknown_count', v_operation_submit_unknown_count,
    'operation_payload_evidence_count', v_operation_payload_evidence_count,
    'provider_request_sent_transfer_status_count_not_authoritative', v_provider_request_sent_count,
    'local_only_reference_count', v_local_prepare_identity_count,
    'provider_external_id_count_total', v_provider_external_id_count + v_canonical_provider_external_id_count,
    'local_artifacts_do_not_count_as_provider_submission', jsonb_build_array('request_id', 'payment_reference', 'bulk_reference', 'operation_id', 'scope_id', 'auth_request_id', 'local_idempotency_key', 'local_only_rail_meta_json', 'pending_local_transfer_rows')
  );

  RETURN NEXT;
END;
$function$;




CREATE OR REPLACE FUNCTION public._pay_manual_adjustment_carry_forward_reserve_for_batch_item(
  p_carry_forward_id uuid,
  p_target_pay_batch_id uuid,
  p_target_pay_batch_item_id uuid,
  p_target_operation_source_key text DEFAULT NULL::text,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_carry_forward_row public.pay_manual_adjustment_carry_forwards%ROWTYPE;
  v_target_item_id uuid := p_target_pay_batch_item_id;
  v_target_pay_batch_id uuid := p_target_pay_batch_id;
  v_target_operation_source_key text := NULL::text;
  v_target_item_pay_batch_id uuid := NULL::uuid;
  v_target_item_candidate_id uuid := NULL::uuid;
  v_target_item_pay_channel text := NULL::text;
  v_target_item_amount_ex_vat numeric := NULL::numeric;
  v_target_item_amount_vat numeric := NULL::numeric;
  v_target_item_amount_inc_vat numeric := NULL::numeric;
  v_target_item_operation_source_key text := NULL::text;
  v_target_item_source_ref text := NULL::text;
  v_target_item_is_voided boolean := false;
  v_existing_target_carry_forward_id uuid := NULL::uuid;
  v_blockers jsonb := '[]'::jsonb;
  v_result_status text := NULL::text;
  v_was_idempotent boolean := false;
BEGIN
  IF p_carry_forward_id IS NULL THEN
    RAISE EXCEPTION 'CARRY_FORWARD_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'CARRY_FORWARD_ID_REQUIRED')::text;
  END IF;

  IF p_target_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'TARGET_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'TARGET_PAY_BATCH_ID_REQUIRED', 'carry_forward_id', p_carry_forward_id)::text;
  END IF;

  IF p_target_pay_batch_item_id IS NULL THEN
    RAISE EXCEPTION 'TARGET_PAY_BATCH_ITEM_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'TARGET_PAY_BATCH_ITEM_ID_REQUIRED', 'carry_forward_id', p_carry_forward_id)::text;
  END IF;

  SELECT carry_forward_rows.*
  INTO v_carry_forward_row
  FROM public.pay_manual_adjustment_carry_forwards AS carry_forward_rows
  WHERE carry_forward_rows.id = p_carry_forward_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CARRY_FORWARD_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'CARRY_FORWARD_NOT_FOUND', 'carry_forward_id', p_carry_forward_id)::text;
  END IF;

  SELECT
    batch_candidate_rows.pay_batch_id,
    batch_candidate_rows.candidate_id,
    upper(btrim(COALESCE(target_item_rows.pay_channel, ''))),
    target_item_rows.amount_ex_vat,
    target_item_rows.amount_vat,
    target_item_rows.amount_inc_vat,
    target_item_rows.operation_source_key,
    target_item_rows.source_ref,
    COALESCE(target_item_rows.is_voided, false)
  INTO
    v_target_item_pay_batch_id,
    v_target_item_candidate_id,
    v_target_item_pay_channel,
    v_target_item_amount_ex_vat,
    v_target_item_amount_vat,
    v_target_item_amount_inc_vat,
    v_target_item_operation_source_key,
    v_target_item_source_ref,
    v_target_item_is_voided
  FROM public.pay_batch_items AS target_item_rows
  JOIN public.pay_batch_candidates AS batch_candidate_rows
    ON batch_candidate_rows.id = target_item_rows.pay_batch_candidate_id
  WHERE target_item_rows.id = p_target_pay_batch_item_id
  FOR UPDATE OF target_item_rows, batch_candidate_rows;

  IF v_target_item_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'TARGET_PAY_BATCH_ITEM_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'TARGET_PAY_BATCH_ITEM_NOT_FOUND', 'target_pay_batch_item_id', p_target_pay_batch_item_id)::text;
  END IF;

  SELECT existing_target_rows.id
  INTO v_existing_target_carry_forward_id
  FROM public.pay_manual_adjustment_carry_forwards AS existing_target_rows
  WHERE existing_target_rows.target_pay_batch_item_id = p_target_pay_batch_item_id
    AND existing_target_rows.id <> p_carry_forward_id
  FOR UPDATE;

  IF v_existing_target_carry_forward_id IS NOT NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'TARGET_PAY_BATCH_ITEM_ALREADY_RESERVED_BY_ANOTHER_CARRY_FORWARD',
      'carry_forward_id', p_carry_forward_id::text,
      'existing_carry_forward_id', v_existing_target_carry_forward_id::text,
      'target_pay_batch_item_id', p_target_pay_batch_item_id::text
    ));
  END IF;

  v_target_operation_source_key := COALESCE(
    NULLIF(btrim(COALESCE(p_target_operation_source_key, '')), ''),
    NULLIF(btrim(COALESCE(v_target_item_operation_source_key, '')), ''),
    'carry_forward:' || p_carry_forward_id::text
  );

  IF v_target_item_pay_batch_id IS DISTINCT FROM p_target_pay_batch_id THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'TARGET_ITEM_BATCH_MISMATCH',
      'target_pay_batch_id', p_target_pay_batch_id::text,
      'actual_pay_batch_id', v_target_item_pay_batch_id::text,
      'target_pay_batch_item_id', p_target_pay_batch_item_id::text
    ));
  END IF;

  IF v_target_item_is_voided THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'TARGET_PAY_BATCH_ITEM_VOIDED',
      'target_pay_batch_item_id', p_target_pay_batch_item_id::text
    ));
  END IF;

  IF v_carry_forward_row.status NOT IN ('PENDING_CARRY_FORWARD', 'RESERVED_IN_DRAFT') THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'CARRY_FORWARD_STATUS_NOT_RESERVABLE',
      'carry_forward_id', p_carry_forward_id::text,
      'status', v_carry_forward_row.status
    ));
  END IF;

  IF v_carry_forward_row.status = 'RESERVED_IN_DRAFT'
     AND (
       v_carry_forward_row.target_pay_batch_id IS DISTINCT FROM p_target_pay_batch_id
       OR v_carry_forward_row.target_pay_batch_item_id IS DISTINCT FROM p_target_pay_batch_item_id
     ) THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'CARRY_FORWARD_ALREADY_RESERVED_FOR_ANOTHER_TARGET',
      'carry_forward_id', p_carry_forward_id::text,
      'existing_target_pay_batch_id', CASE WHEN v_carry_forward_row.target_pay_batch_id IS NULL THEN NULL ELSE v_carry_forward_row.target_pay_batch_id::text END,
      'existing_target_pay_batch_item_id', CASE WHEN v_carry_forward_row.target_pay_batch_item_id IS NULL THEN NULL ELSE v_carry_forward_row.target_pay_batch_item_id::text END,
      'requested_target_pay_batch_id', p_target_pay_batch_id::text,
      'requested_target_pay_batch_item_id', p_target_pay_batch_item_id::text
    ));
  END IF;

  IF v_carry_forward_row.status = 'RESERVED_IN_DRAFT'
     AND v_carry_forward_row.target_pay_batch_id IS NOT DISTINCT FROM p_target_pay_batch_id
     AND v_carry_forward_row.target_pay_batch_item_id IS NOT DISTINCT FROM p_target_pay_batch_item_id THEN
    v_was_idempotent := true;
  END IF;

  IF v_carry_forward_row.candidate_id IS DISTINCT FROM v_target_item_candidate_id THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'CARRY_FORWARD_TARGET_CANDIDATE_MISMATCH',
      'carry_forward_id', p_carry_forward_id::text,
      'carry_forward_candidate_id', v_carry_forward_row.candidate_id::text,
      'target_candidate_id', CASE WHEN v_target_item_candidate_id IS NULL THEN NULL ELSE v_target_item_candidate_id::text END
    ));
  END IF;

  IF upper(btrim(COALESCE(v_carry_forward_row.pay_channel, ''))) IS DISTINCT FROM v_target_item_pay_channel THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'CARRY_FORWARD_TARGET_PAY_CHANNEL_MISMATCH',
      'carry_forward_id', p_carry_forward_id::text,
      'carry_forward_pay_channel', v_carry_forward_row.pay_channel,
      'target_pay_channel', v_target_item_pay_channel
    ));
  END IF;

  IF v_target_item_amount_inc_vat IS NULL
     OR round(v_target_item_amount_inc_vat, 2) IS DISTINCT FROM round(v_carry_forward_row.amount_inc_vat, 2)
     OR (
       v_carry_forward_row.amount_ex_vat IS NULL
       AND v_target_item_amount_ex_vat IS NOT NULL
     )
     OR (
       v_carry_forward_row.amount_ex_vat IS NOT NULL
       AND (
         v_target_item_amount_ex_vat IS NULL
         OR round(v_target_item_amount_ex_vat, 2) IS DISTINCT FROM round(v_carry_forward_row.amount_ex_vat, 2)
       )
     )
     OR (
       v_carry_forward_row.amount_vat IS NULL
       AND v_target_item_amount_vat IS NOT NULL
     )
     OR (
       v_carry_forward_row.amount_vat IS NOT NULL
       AND (
         v_target_item_amount_vat IS NULL
         OR round(v_target_item_amount_vat, 2) IS DISTINCT FROM round(v_carry_forward_row.amount_vat, 2)
       )
     ) THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'CARRY_FORWARD_TARGET_AMOUNT_MISMATCH',
      'carry_forward_id', p_carry_forward_id::text,
      'target_pay_batch_item_id', p_target_pay_batch_item_id::text,
      'carry_forward_amount_ex_vat', v_carry_forward_row.amount_ex_vat,
      'carry_forward_amount_vat', v_carry_forward_row.amount_vat,
      'carry_forward_amount_inc_vat', v_carry_forward_row.amount_inc_vat,
      'target_amount_ex_vat', v_target_item_amount_ex_vat,
      'target_amount_vat', v_target_item_amount_vat,
      'target_amount_inc_vat', v_target_item_amount_inc_vat,
      'signed_amount_convention', 'SIGNED_AMOUNTS'
    ));
  END IF;

  IF COALESCE(jsonb_array_length(v_blockers), 0) > 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reserved', false,
      'idempotent', false,
      'carry_forward_id', p_carry_forward_id::text,
      'target_pay_batch_id', p_target_pay_batch_id::text,
      'target_pay_batch_item_id', p_target_pay_batch_item_id::text,
      'blockers', v_blockers,
      'signed_amount_convention', 'SIGNED_AMOUNTS',
      'adjustment_direction_is_display_only', true
    );
  END IF;

  UPDATE public.pay_manual_adjustment_carry_forwards AS carry_forward_rows
  SET
    target_pay_batch_id = p_target_pay_batch_id,
    target_pay_batch_item_id = p_target_pay_batch_item_id,
    target_operation_source_key = v_target_operation_source_key,
    status = 'RESERVED_IN_DRAFT',
    reserved_at_utc = COALESCE(carry_forward_rows.reserved_at_utc, now()),
    released_at_utc = NULL,
    cancelled_at_utc = NULL,
    status_reason = CASE
      WHEN v_was_idempotent THEN COALESCE(carry_forward_rows.status_reason, 'Already reserved for this target item.')
      ELSE 'Reserved in draft target pay_batch_item.'
    END,
    updated_at_utc = now()
  WHERE carry_forward_rows.id = p_carry_forward_id
  RETURNING carry_forward_rows.status
  INTO v_result_status;

  RETURN jsonb_build_object(
    'ok', true,
    'reserved', true,
    'idempotent', v_was_idempotent,
    'carry_forward_id', p_carry_forward_id::text,
    'target_pay_batch_id', p_target_pay_batch_id::text,
    'target_pay_batch_item_id', p_target_pay_batch_item_id::text,
    'target_operation_source_key', v_target_operation_source_key,
    'status', COALESCE(v_result_status, 'RESERVED_IN_DRAFT'),
    'signed_amount_convention', 'SIGNED_AMOUNTS',
    'adjustment_direction_is_display_only', true
  );
END;
$function$;





CREATE OR REPLACE FUNCTION public._pay_manual_adjustment_carry_forward_release_for_scope(
  p_target_pay_batch_id uuid DEFAULT NULL::uuid,
  p_resolved_scope_json jsonb DEFAULT NULL::jsonb,
  p_target_pay_batch_item_ids uuid[] DEFAULT NULL::uuid[],
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_reason text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_uuid_regex text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_target_pay_batch_id uuid := p_target_pay_batch_id;
  v_scope_json jsonb := COALESCE(p_resolved_scope_json, '{}'::jsonb);
  v_scope_item_ids uuid[] := COALESCE(p_target_pay_batch_item_ids, ARRAY[]::uuid[]);
  v_scope_transfer_ids uuid[] := ARRAY[]::uuid[];
  v_released_ids jsonb := '[]'::jsonb;
  v_blocked_items jsonb := '[]'::jsonb;
  v_candidate_count integer := 0;
  v_released_count integer := 0;
  v_blocked_count integer := 0;
BEGIN
  IF v_scope_json IS NOT NULL AND jsonb_typeof(v_scope_json) <> 'object' THEN
    RAISE EXCEPTION 'RESOLVED_SCOPE_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'RESOLVED_SCOPE_JSON_MUST_BE_OBJECT')::text;
  END IF;

  IF v_target_pay_batch_id IS NULL
     AND v_scope_json IS NOT NULL
     AND NULLIF(btrim(COALESCE(v_scope_json->>'pay_batch_id', '')), '') ~ v_uuid_regex THEN
    v_target_pay_batch_id := (v_scope_json->>'pay_batch_id')::uuid;
  END IF;

  IF v_scope_json IS NOT NULL AND jsonb_typeof(v_scope_json) = 'object' THEN
    WITH raw_values AS (
      SELECT item_values.raw_value
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_scope_json->'pay_batch_item_ids') = 'array' THEN v_scope_json->'pay_batch_item_ids'
          ELSE '[]'::jsonb
        END
      ) AS item_values(raw_value)
    ), clean_values AS (
      SELECT NULLIF(btrim(raw_values.raw_value), '') AS clean_value
      FROM raw_values
    )
    SELECT COALESCE(array_agg(clean_values.clean_value::uuid), ARRAY[]::uuid[])
    INTO v_scope_item_ids
    FROM clean_values
    WHERE clean_values.clean_value IS NOT NULL
      AND clean_values.clean_value ~ v_uuid_regex;

    v_scope_item_ids := COALESCE(v_scope_item_ids, ARRAY[]::uuid[]) || COALESCE(p_target_pay_batch_item_ids, ARRAY[]::uuid[]);

    SELECT COALESCE(array_agg(DISTINCT item_id_values.item_id) FILTER (WHERE item_id_values.item_id IS NOT NULL), ARRAY[]::uuid[])
    INTO v_scope_item_ids
    FROM unnest(COALESCE(v_scope_item_ids, ARRAY[]::uuid[])) AS item_id_values(item_id);

    WITH raw_values AS (
      SELECT transfer_values.raw_value
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_scope_json->'pay_bank_transfer_ids') = 'array' THEN v_scope_json->'pay_bank_transfer_ids'
          ELSE '[]'::jsonb
        END
      ) AS transfer_values(raw_value)
    ), clean_values AS (
      SELECT NULLIF(btrim(raw_values.raw_value), '') AS clean_value
      FROM raw_values
    )
    SELECT COALESCE(array_agg(clean_values.clean_value::uuid), ARRAY[]::uuid[])
    INTO v_scope_transfer_ids
    FROM clean_values
    WHERE clean_values.clean_value IS NOT NULL
      AND clean_values.clean_value ~ v_uuid_regex;
  END IF;

  IF v_target_pay_batch_id IS NULL AND COALESCE(array_length(v_scope_item_ids, 1), 0) = 0 THEN
    RAISE EXCEPTION 'TARGET_PAY_BATCH_OR_ITEM_SCOPE_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'TARGET_PAY_BATCH_OR_ITEM_SCOPE_REQUIRED')::text;
  END IF;

  PERFORM 1
  FROM public.pay_manual_adjustment_carry_forwards AS lock_carry_forward_rows
  WHERE lock_carry_forward_rows.status = 'RESERVED_IN_DRAFT'
    AND (
      (v_target_pay_batch_id IS NOT NULL AND lock_carry_forward_rows.target_pay_batch_id = v_target_pay_batch_id)
      OR (COALESCE(array_length(v_scope_item_ids, 1), 0) > 0 AND lock_carry_forward_rows.target_pay_batch_item_id = ANY(v_scope_item_ids))
    )
  ORDER BY lock_carry_forward_rows.id
  FOR UPDATE;

  WITH candidate_rows AS (
    SELECT
      carry_forward_rows.id AS carry_forward_id,
      carry_forward_rows.target_pay_batch_id,
      carry_forward_rows.target_pay_batch_item_id,
      carry_forward_rows.status,
      carry_forward_rows.amount_ex_vat,
      carry_forward_rows.amount_vat,
      carry_forward_rows.amount_inc_vat,
      target_item_rows.pay_bank_transfer_id,
      target_item_rows.amount_ex_vat AS target_amount_ex_vat,
      target_item_rows.amount_vat AS target_amount_vat,
      target_item_rows.amount_inc_vat AS target_amount_inc_vat,
      target_item_rows.is_voided AS target_is_voided,
      batch_candidate_rows.settlement_status,
      batch_candidate_rows.settled_at_utc,
      target_transfer_rows.status AS transfer_status,
      target_transfer_rows.rail_state,
      target_transfer_rows.completed_at_utc,
      target_transfer_rows.rail_meta_json,
      classifier_rows.cash_state,
      classifier_rows.is_final_money_moved
    FROM public.pay_manual_adjustment_carry_forwards AS carry_forward_rows
    LEFT JOIN public.pay_batch_items AS target_item_rows
      ON target_item_rows.id = carry_forward_rows.target_pay_batch_item_id
    LEFT JOIN public.pay_batch_candidates AS batch_candidate_rows
      ON batch_candidate_rows.id = target_item_rows.pay_batch_candidate_id
    LEFT JOIN public.pay_bank_transfers AS target_transfer_rows
      ON target_transfer_rows.id = target_item_rows.pay_bank_transfer_id
    CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
      target_transfer_rows.status,
      target_transfer_rows.rail_state,
      COALESCE(target_transfer_rows.rail_meta_json, '{}'::jsonb),
      COALESCE(target_transfer_rows.rail_meta_json, '{}'::jsonb)
    ) AS classifier_rows
    WHERE carry_forward_rows.status = 'RESERVED_IN_DRAFT'
      AND (
        (v_target_pay_batch_id IS NOT NULL AND carry_forward_rows.target_pay_batch_id = v_target_pay_batch_id)
        OR (COALESCE(array_length(v_scope_item_ids, 1), 0) > 0 AND carry_forward_rows.target_pay_batch_item_id = ANY(v_scope_item_ids))
        OR (COALESCE(array_length(v_scope_transfer_ids, 1), 0) > 0 AND target_item_rows.pay_bank_transfer_id = ANY(v_scope_transfer_ids))
      )
  ), classified_rows AS (
    SELECT
      candidate_rows.*,
      (
        COALESCE(candidate_rows.is_final_money_moved, false)
        OR upper(COALESCE(candidate_rows.cash_state, '')) = 'FINAL_PAID'
        OR upper(COALESCE(candidate_rows.settlement_status, '')) = 'SETTLED'
        OR candidate_rows.settled_at_utc IS NOT NULL
      ) AS has_final_paid_or_settled_evidence
    FROM candidate_rows
  ), blocked_rows AS (
    SELECT classified_rows.*
    FROM classified_rows
    WHERE classified_rows.has_final_paid_or_settled_evidence
  ), releasable_rows AS (
    SELECT classified_rows.*
    FROM classified_rows
    WHERE classified_rows.has_final_paid_or_settled_evidence = false
  ), updated_rows AS (
    UPDATE public.pay_manual_adjustment_carry_forwards AS carry_forward_update_rows
    SET
      status = 'PENDING_CARRY_FORWARD',
      target_pay_batch_id = NULL,
      target_pay_batch_item_id = NULL,
      target_operation_source_key = NULL,
      reserved_at_utc = NULL,
      released_at_utc = now(),
      status_reason = COALESCE(NULLIF(btrim(p_reason), ''), 'Released because target payment scope was cancelled or unwound before money moved.'),
      updated_at_utc = now()
    FROM releasable_rows
    WHERE carry_forward_update_rows.id = releasable_rows.carry_forward_id
    RETURNING carry_forward_update_rows.id
  )
  SELECT
    (SELECT count(*)::integer FROM candidate_rows),
    (SELECT count(*)::integer FROM updated_rows),
    (SELECT count(*)::integer FROM blocked_rows),
    COALESCE((SELECT jsonb_agg(updated_rows.id::text ORDER BY updated_rows.id::text) FROM updated_rows), '[]'::jsonb),
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'code', 'CARRY_FORWARD_TARGET_HAS_FINAL_PAID_OR_SETTLED_EVIDENCE',
        'carry_forward_id', blocked_rows.carry_forward_id::text,
        'target_pay_batch_id', CASE WHEN blocked_rows.target_pay_batch_id IS NULL THEN NULL ELSE blocked_rows.target_pay_batch_id::text END,
        'target_pay_batch_item_id', CASE WHEN blocked_rows.target_pay_batch_item_id IS NULL THEN NULL ELSE blocked_rows.target_pay_batch_item_id::text END,
        'pay_bank_transfer_id', CASE WHEN blocked_rows.pay_bank_transfer_id IS NULL THEN NULL ELSE blocked_rows.pay_bank_transfer_id::text END,
        'cash_state', blocked_rows.cash_state,
        'transfer_status', blocked_rows.transfer_status,
        'settlement_status', blocked_rows.settlement_status,
        'settled_at_utc', blocked_rows.settled_at_utc,
        'completed_at_utc', blocked_rows.completed_at_utc
      ) ORDER BY blocked_rows.carry_forward_id::text)
      FROM blocked_rows
    ), '[]'::jsonb)
  INTO
    v_candidate_count,
    v_released_count,
    v_blocked_count,
    v_released_ids,
    v_blocked_items;

  RETURN jsonb_build_object(
    'ok', COALESCE(v_blocked_count, 0) = 0,
    'target_pay_batch_id', CASE WHEN v_target_pay_batch_id IS NULL THEN NULL ELSE v_target_pay_batch_id::text END,
    'candidate_count', COALESCE(v_candidate_count, 0),
    'released_count', COALESCE(v_released_count, 0),
    'released_carry_forward_ids', COALESCE(v_released_ids, '[]'::jsonb),
    'blocked_count', COALESCE(v_blocked_count, 0),
    'blockers', COALESCE(v_blocked_items, '[]'::jsonb),
    'signed_amount_convention', 'SIGNED_AMOUNTS',
    'adjustment_direction_is_display_only', true,
    'actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public._pay_manual_adjustment_carry_forward_mark_consumed(
  p_target_pay_batch_id uuid DEFAULT NULL::uuid,
  p_target_pay_batch_item_ids uuid[] DEFAULT NULL::uuid[],
  p_resolved_scope_json jsonb DEFAULT NULL::jsonb,
  p_final_paid_evidence_json jsonb DEFAULT NULL::jsonb,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_uuid_regex text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_target_pay_batch_id uuid := p_target_pay_batch_id;
  v_scope_json jsonb := COALESCE(p_resolved_scope_json, '{}'::jsonb);
  v_scope_item_ids uuid[] := COALESCE(p_target_pay_batch_item_ids, ARRAY[]::uuid[]);
  v_scope_transfer_ids uuid[] := ARRAY[]::uuid[];
  v_explicit_final_paid boolean := false;
  v_candidate_count integer := 0;
  v_consumed_count integer := 0;
  v_existing_consumed_count integer := 0;
  v_blocked_count integer := 0;
  v_consumed_ids jsonb := '[]'::jsonb;
  v_existing_consumed_ids jsonb := '[]'::jsonb;
  v_blockers jsonb := '[]'::jsonb;
BEGIN
  IF v_scope_json IS NOT NULL AND jsonb_typeof(v_scope_json) <> 'object' THEN
    RAISE EXCEPTION 'RESOLVED_SCOPE_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'RESOLVED_SCOPE_JSON_MUST_BE_OBJECT')::text;
  END IF;

  IF v_target_pay_batch_id IS NULL
     AND v_scope_json IS NOT NULL
     AND NULLIF(btrim(COALESCE(v_scope_json->>'pay_batch_id', '')), '') ~ v_uuid_regex THEN
    v_target_pay_batch_id := (v_scope_json->>'pay_batch_id')::uuid;
  END IF;

  IF v_scope_json IS NOT NULL AND jsonb_typeof(v_scope_json) = 'object' THEN
    WITH raw_values AS (
      SELECT item_values.raw_value
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_scope_json->'pay_batch_item_ids') = 'array' THEN v_scope_json->'pay_batch_item_ids'
          ELSE '[]'::jsonb
        END
      ) AS item_values(raw_value)
    ), clean_values AS (
      SELECT NULLIF(btrim(raw_values.raw_value), '') AS clean_value
      FROM raw_values
    )
    SELECT COALESCE(array_agg(clean_values.clean_value::uuid), ARRAY[]::uuid[])
    INTO v_scope_item_ids
    FROM clean_values
    WHERE clean_values.clean_value IS NOT NULL
      AND clean_values.clean_value ~ v_uuid_regex;

    v_scope_item_ids := COALESCE(v_scope_item_ids, ARRAY[]::uuid[]) || COALESCE(p_target_pay_batch_item_ids, ARRAY[]::uuid[]);

    SELECT COALESCE(array_agg(DISTINCT item_id_values.item_id) FILTER (WHERE item_id_values.item_id IS NOT NULL), ARRAY[]::uuid[])
    INTO v_scope_item_ids
    FROM unnest(COALESCE(v_scope_item_ids, ARRAY[]::uuid[])) AS item_id_values(item_id);

    WITH raw_values AS (
      SELECT transfer_values.raw_value
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_scope_json->'pay_bank_transfer_ids') = 'array' THEN v_scope_json->'pay_bank_transfer_ids'
          ELSE '[]'::jsonb
        END
      ) AS transfer_values(raw_value)
    ), clean_values AS (
      SELECT NULLIF(btrim(raw_values.raw_value), '') AS clean_value
      FROM raw_values
    )
    SELECT COALESCE(array_agg(clean_values.clean_value::uuid), ARRAY[]::uuid[])
    INTO v_scope_transfer_ids
    FROM clean_values
    WHERE clean_values.clean_value IS NOT NULL
      AND clean_values.clean_value ~ v_uuid_regex;
  END IF;

  IF v_target_pay_batch_id IS NULL AND COALESCE(array_length(v_scope_item_ids, 1), 0) = 0 THEN
    RAISE EXCEPTION 'TARGET_PAY_BATCH_OR_ITEM_SCOPE_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'TARGET_PAY_BATCH_OR_ITEM_SCOPE_REQUIRED')::text;
  END IF;

  IF p_final_paid_evidence_json IS NOT NULL AND jsonb_typeof(p_final_paid_evidence_json) = 'object' THEN
    v_explicit_final_paid := (
      lower(NULLIF(btrim(COALESCE(p_final_paid_evidence_json->>'final_paid', '')), '')) IN ('true','t','yes','y','1','paid','settled','completed','success','succeeded')
      OR lower(NULLIF(btrim(COALESCE(p_final_paid_evidence_json->>'is_final_money_moved', '')), '')) IN ('true','t','yes','y','1','paid','settled','completed','success','succeeded')
      OR lower(NULLIF(btrim(COALESCE(p_final_paid_evidence_json->>'money_moved', '')), '')) IN ('true','t','yes','y','1','paid','settled','completed','success','succeeded')
      OR lower(NULLIF(btrim(COALESCE(p_final_paid_evidence_json->>'payment_made', '')), '')) IN ('true','t','yes','y','1','paid','settled','completed','success','succeeded')
      OR lower(NULLIF(btrim(COALESCE(p_final_paid_evidence_json->>'settled', '')), '')) IN ('true','t','yes','y','1','paid','settled','completed','success','succeeded')
      OR upper(NULLIF(btrim(COALESCE(p_final_paid_evidence_json->>'cash_state', '')), '')) = 'FINAL_PAID'
    );
  END IF;

  PERFORM 1
  FROM public.pay_manual_adjustment_carry_forwards AS lock_carry_forward_rows
  WHERE lock_carry_forward_rows.status IN ('RESERVED_IN_DRAFT', 'CONSUMED_IN_BATCH')
    AND (
      (v_target_pay_batch_id IS NOT NULL AND lock_carry_forward_rows.target_pay_batch_id = v_target_pay_batch_id)
      OR (COALESCE(array_length(v_scope_item_ids, 1), 0) > 0 AND lock_carry_forward_rows.target_pay_batch_item_id = ANY(v_scope_item_ids))
    )
  ORDER BY lock_carry_forward_rows.id
  FOR UPDATE;

  WITH candidate_rows AS (
    SELECT
      carry_forward_rows.id AS carry_forward_id,
      carry_forward_rows.status AS carry_forward_status,
      carry_forward_rows.target_pay_batch_id,
      carry_forward_rows.target_pay_batch_item_id,
      carry_forward_rows.amount_ex_vat,
      carry_forward_rows.amount_vat,
      carry_forward_rows.amount_inc_vat,
      target_item_rows.pay_bank_transfer_id,
      target_item_rows.amount_ex_vat AS target_amount_ex_vat,
      target_item_rows.amount_vat AS target_amount_vat,
      target_item_rows.amount_inc_vat AS target_amount_inc_vat,
      target_item_rows.is_voided AS target_is_voided,
      batch_candidate_rows.settlement_status,
      batch_candidate_rows.settled_at_utc,
      target_transfer_rows.status AS transfer_status,
      target_transfer_rows.rail_state,
      target_transfer_rows.completed_at_utc,
      target_transfer_rows.rail_meta_json,
      classifier_rows.cash_state,
      classifier_rows.is_final_money_moved
    FROM public.pay_manual_adjustment_carry_forwards AS carry_forward_rows
    LEFT JOIN public.pay_batch_items AS target_item_rows
      ON target_item_rows.id = carry_forward_rows.target_pay_batch_item_id
    LEFT JOIN public.pay_batch_candidates AS batch_candidate_rows
      ON batch_candidate_rows.id = target_item_rows.pay_batch_candidate_id
    LEFT JOIN public.pay_bank_transfers AS target_transfer_rows
      ON target_transfer_rows.id = target_item_rows.pay_bank_transfer_id
    CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
      target_transfer_rows.status,
      target_transfer_rows.rail_state,
      COALESCE(target_transfer_rows.rail_meta_json, '{}'::jsonb),
      COALESCE(target_transfer_rows.rail_meta_json, '{}'::jsonb)
    ) AS classifier_rows
    WHERE carry_forward_rows.status IN ('RESERVED_IN_DRAFT', 'CONSUMED_IN_BATCH')
      AND (
        (v_target_pay_batch_id IS NOT NULL AND carry_forward_rows.target_pay_batch_id = v_target_pay_batch_id)
        OR (COALESCE(array_length(v_scope_item_ids, 1), 0) > 0 AND carry_forward_rows.target_pay_batch_item_id = ANY(v_scope_item_ids))
        OR (COALESCE(array_length(v_scope_transfer_ids, 1), 0) > 0 AND target_item_rows.pay_bank_transfer_id = ANY(v_scope_transfer_ids))
      )
  ), classified_rows AS (
    SELECT
      candidate_rows.*,
      (
        COALESCE(candidate_rows.is_final_money_moved, false)
        OR upper(COALESCE(candidate_rows.cash_state, '')) = 'FINAL_PAID'
        OR upper(COALESCE(candidate_rows.settlement_status, '')) = 'SETTLED'
        OR candidate_rows.settled_at_utc IS NOT NULL
        OR COALESCE(v_explicit_final_paid, false)
      ) AS has_final_paid_or_settled_evidence,
      (
        candidate_rows.target_pay_batch_item_id IS NOT NULL
        AND candidate_rows.target_amount_inc_vat IS NOT NULL
        AND round(candidate_rows.target_amount_inc_vat, 2) IS NOT DISTINCT FROM round(candidate_rows.amount_inc_vat, 2)
        AND (
          (candidate_rows.amount_ex_vat IS NULL AND candidate_rows.target_amount_ex_vat IS NULL)
          OR (candidate_rows.amount_ex_vat IS NOT NULL AND candidate_rows.target_amount_ex_vat IS NOT NULL AND round(candidate_rows.target_amount_ex_vat, 2) IS NOT DISTINCT FROM round(candidate_rows.amount_ex_vat, 2))
        )
        AND (
          (candidate_rows.amount_vat IS NULL AND candidate_rows.target_amount_vat IS NULL)
          OR (candidate_rows.amount_vat IS NOT NULL AND candidate_rows.target_amount_vat IS NOT NULL AND round(candidate_rows.target_amount_vat, 2) IS NOT DISTINCT FROM round(candidate_rows.amount_vat, 2))
        )
      ) AS target_amount_matches
    FROM candidate_rows
  ), existing_consumed_rows AS (
    SELECT classified_rows.*
    FROM classified_rows
    WHERE classified_rows.carry_forward_status = 'CONSUMED_IN_BATCH'
  ), consumable_rows AS (
    SELECT classified_rows.*
    FROM classified_rows
    WHERE classified_rows.carry_forward_status = 'RESERVED_IN_DRAFT'
      AND classified_rows.has_final_paid_or_settled_evidence
      AND classified_rows.target_amount_matches
  ), blocked_rows AS (
    SELECT classified_rows.*,
      CASE
        WHEN classified_rows.carry_forward_status <> 'RESERVED_IN_DRAFT' THEN 'CARRY_FORWARD_STATUS_NOT_RESERVED'
        WHEN classified_rows.target_pay_batch_item_id IS NULL THEN 'CARRY_FORWARD_TARGET_ITEM_MISSING'
        WHEN classified_rows.target_amount_matches = false THEN 'CARRY_FORWARD_TARGET_AMOUNT_MISMATCH'
        WHEN classified_rows.has_final_paid_or_settled_evidence = false THEN 'FINAL_PAID_EVIDENCE_REQUIRED'
        ELSE 'CARRY_FORWARD_NOT_CONSUMABLE'
      END AS blocker_code
    FROM classified_rows
    WHERE classified_rows.carry_forward_status <> 'CONSUMED_IN_BATCH'
      AND NOT (
        classified_rows.carry_forward_status = 'RESERVED_IN_DRAFT'
        AND classified_rows.has_final_paid_or_settled_evidence
        AND classified_rows.target_amount_matches
      )
  ), updated_rows AS (
    UPDATE public.pay_manual_adjustment_carry_forwards AS carry_forward_update_rows
    SET
      status = 'CONSUMED_IN_BATCH',
      consumed_at_utc = COALESCE(carry_forward_update_rows.consumed_at_utc, now()),
      status_reason = 'Consumed after final paid/settled evidence for target payment.',
      updated_at_utc = now()
    FROM consumable_rows
    WHERE carry_forward_update_rows.id = consumable_rows.carry_forward_id
    RETURNING carry_forward_update_rows.id
  )
  SELECT
    (SELECT count(*)::integer FROM candidate_rows),
    (SELECT count(*)::integer FROM updated_rows),
    (SELECT count(*)::integer FROM existing_consumed_rows),
    (SELECT count(*)::integer FROM blocked_rows),
    COALESCE((SELECT jsonb_agg(updated_rows.id::text ORDER BY updated_rows.id::text) FROM updated_rows), '[]'::jsonb),
    COALESCE((SELECT jsonb_agg(existing_consumed_rows.carry_forward_id::text ORDER BY existing_consumed_rows.carry_forward_id::text) FROM existing_consumed_rows), '[]'::jsonb),
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'code', blocked_rows.blocker_code,
        'carry_forward_id', blocked_rows.carry_forward_id::text,
        'status', blocked_rows.carry_forward_status,
        'target_pay_batch_id', CASE WHEN blocked_rows.target_pay_batch_id IS NULL THEN NULL ELSE blocked_rows.target_pay_batch_id::text END,
        'target_pay_batch_item_id', CASE WHEN blocked_rows.target_pay_batch_item_id IS NULL THEN NULL ELSE blocked_rows.target_pay_batch_item_id::text END,
        'cash_state', blocked_rows.cash_state,
        'transfer_status', blocked_rows.transfer_status,
        'settlement_status', blocked_rows.settlement_status,
        'settled_at_utc', blocked_rows.settled_at_utc,
        'completed_at_utc', blocked_rows.completed_at_utc,
        'target_amount_matches', blocked_rows.target_amount_matches,
        'signed_amount_convention', 'SIGNED_AMOUNTS'
      ) ORDER BY blocked_rows.carry_forward_id::text)
      FROM blocked_rows
    ), '[]'::jsonb)
  INTO
    v_candidate_count,
    v_consumed_count,
    v_existing_consumed_count,
    v_blocked_count,
    v_consumed_ids,
    v_existing_consumed_ids,
    v_blockers;

  RETURN jsonb_build_object(
    'ok', COALESCE(v_blocked_count, 0) = 0,
    'target_pay_batch_id', CASE WHEN v_target_pay_batch_id IS NULL THEN NULL ELSE v_target_pay_batch_id::text END,
    'candidate_count', COALESCE(v_candidate_count, 0),
    'consumed_count', COALESCE(v_consumed_count, 0),
    'existing_consumed_count', COALESCE(v_existing_consumed_count, 0),
    'consumed_carry_forward_ids', COALESCE(v_consumed_ids, '[]'::jsonb),
    'existing_consumed_carry_forward_ids', COALESCE(v_existing_consumed_ids, '[]'::jsonb),
    'blocked_count', COALESCE(v_blocked_count, 0),
    'blockers', COALESCE(v_blockers, '[]'::jsonb),
    'explicit_final_paid_evidence', COALESCE(v_explicit_final_paid, false),
    'signed_amount_convention', 'SIGNED_AMOUNTS',
    'adjustment_direction_is_display_only', true,
    'actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public._pay_manual_adjustment_carry_forward_freshness_check(p_pay_batch_id uuid DEFAULT NULL::uuid, p_candidate_ids uuid[] DEFAULT NULL::uuid[], p_pay_batch_item_ids uuid[] DEFAULT NULL::uuid[], p_resolved_scope_json jsonb DEFAULT NULL::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uuid_regex text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_scope_json jsonb := COALESCE(p_resolved_scope_json, '{}'::jsonb);
  v_effective_pay_batch_id uuid := p_pay_batch_id;
  v_candidate_ids uuid[] := COALESCE(p_candidate_ids, ARRAY[]::uuid[]);
  v_pay_batch_item_ids uuid[] := COALESCE(p_pay_batch_item_ids, ARRAY[]::uuid[]);
  v_blockers jsonb := '[]'::jsonb;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_carry_forward_ids_json jsonb := '[]'::jsonb;
  v_blocker_count integer := 0;
BEGIN
  IF v_scope_json IS NOT NULL AND jsonb_typeof(v_scope_json) <> 'object' THEN
    RAISE EXCEPTION 'RESOLVED_SCOPE_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'RESOLVED_SCOPE_JSON_MUST_BE_OBJECT')::text;
  END IF;

  IF v_effective_pay_batch_id IS NULL
     AND NULLIF(btrim(COALESCE(v_scope_json->>'pay_batch_id', '')), '') ~ v_uuid_regex THEN
    v_effective_pay_batch_id := (v_scope_json->>'pay_batch_id')::uuid;
  END IF;

  IF v_effective_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  WITH raw_candidate_values AS (
    SELECT candidate_values.raw_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_scope_json->'candidate_ids') = 'array' THEN v_scope_json->'candidate_ids'
        WHEN jsonb_typeof(v_scope_json #> '{resolved_full_payment_scope_json,candidate_ids}') = 'array' THEN v_scope_json #> '{resolved_full_payment_scope_json,candidate_ids}'
        ELSE '[]'::jsonb
      END
    ) AS candidate_values(raw_value)
  ), raw_item_values AS (
    SELECT item_values.raw_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_scope_json->'pay_batch_item_ids') = 'array' THEN v_scope_json->'pay_batch_item_ids'
        WHEN jsonb_typeof(v_scope_json #> '{resolved_full_payment_scope_json,pay_batch_item_ids}') = 'array' THEN v_scope_json #> '{resolved_full_payment_scope_json,pay_batch_item_ids}'
        ELSE '[]'::jsonb
      END
    ) AS item_values(raw_value)
  ), all_candidates AS (
    SELECT candidate_array_values.candidate_id AS candidate_id
    FROM unnest(COALESCE(v_candidate_ids, ARRAY[]::uuid[])) AS candidate_array_values(candidate_id)
    WHERE candidate_array_values.candidate_id IS NOT NULL
    UNION ALL
    SELECT NULLIF(btrim(raw_candidate_values.raw_value), '')::uuid AS candidate_id
    FROM raw_candidate_values
    WHERE NULLIF(btrim(raw_candidate_values.raw_value), '') ~ v_uuid_regex
  ), all_items AS (
    SELECT item_array_values.item_id AS pay_batch_item_id
    FROM unnest(COALESCE(v_pay_batch_item_ids, ARRAY[]::uuid[])) AS item_array_values(item_id)
    WHERE item_array_values.item_id IS NOT NULL
    UNION ALL
    SELECT NULLIF(btrim(raw_item_values.raw_value), '')::uuid AS pay_batch_item_id
    FROM raw_item_values
    WHERE NULLIF(btrim(raw_item_values.raw_value), '') ~ v_uuid_regex
  )
  SELECT
    COALESCE((SELECT array_agg(DISTINCT all_candidates.candidate_id) FROM all_candidates WHERE all_candidates.candidate_id IS NOT NULL), ARRAY[]::uuid[]),
    COALESCE((SELECT array_agg(DISTINCT all_items.pay_batch_item_id) FROM all_items WHERE all_items.pay_batch_item_id IS NOT NULL), ARRAY[]::uuid[])
  INTO v_candidate_ids, v_pay_batch_item_ids;

  IF COALESCE(array_length(v_candidate_ids, 1), 0) = 0
     AND COALESCE(array_length(v_pay_batch_item_ids, 1), 0) = 0 THEN
    SELECT COALESCE(array_agg(DISTINCT batch_candidate_rows.candidate_id) FILTER (WHERE batch_candidate_rows.candidate_id IS NOT NULL), ARRAY[]::uuid[])
    INTO v_candidate_ids
    FROM public.pay_batch_candidates AS batch_candidate_rows
    WHERE batch_candidate_rows.pay_batch_id = v_effective_pay_batch_id;
  END IF;

  IF COALESCE(array_length(v_pay_batch_item_ids, 1), 0) = 0
     AND COALESCE(array_length(v_candidate_ids, 1), 0) = 0 THEN
    SELECT COALESCE(array_agg(DISTINCT item_rows.id), ARRAY[]::uuid[])
    INTO v_pay_batch_item_ids
    FROM public.pay_batch_items AS item_rows
    JOIN public.pay_batch_candidates AS batch_candidate_rows
      ON batch_candidate_rows.id = item_rows.pay_batch_candidate_id
    WHERE batch_candidate_rows.pay_batch_id = v_effective_pay_batch_id;
  END IF;

  WITH target_items AS (
    SELECT
      item_rows.id AS pay_batch_item_id,
      batch_candidate_rows.pay_batch_id,
      batch_candidate_rows.candidate_id,
      item_rows.pay_channel,
      item_rows.operation_source_key,
      item_rows.source_ref,
      item_rows.amount_ex_vat,
      item_rows.amount_vat,
      item_rows.amount_inc_vat,
      item_rows.is_voided
    FROM public.pay_batch_items AS item_rows
    JOIN public.pay_batch_candidates AS batch_candidate_rows
      ON batch_candidate_rows.id = item_rows.pay_batch_candidate_id
    WHERE batch_candidate_rows.pay_batch_id = v_effective_pay_batch_id
      AND (
        COALESCE(array_length(v_pay_batch_item_ids, 1), 0) = 0
        OR item_rows.id = ANY(v_pay_batch_item_ids)
      )
      AND (
        COALESCE(array_length(v_candidate_ids, 1), 0) = 0
        OR batch_candidate_rows.candidate_id = ANY(v_candidate_ids)
      )
  ), relevant_carry_forwards AS (
    SELECT DISTINCT carry_forward_rows.*
    FROM public.pay_manual_adjustment_carry_forwards AS carry_forward_rows
    LEFT JOIN target_items AS target_item_rows
      ON target_item_rows.pay_batch_item_id = carry_forward_rows.target_pay_batch_item_id
      OR lower(COALESCE(target_item_rows.operation_source_key, '')) = 'carry_forward:' || carry_forward_rows.id::text
      OR lower(COALESCE(target_item_rows.source_ref, '')) = 'carry_forward:' || carry_forward_rows.id::text
    WHERE carry_forward_rows.target_pay_batch_id = v_effective_pay_batch_id
       OR target_item_rows.pay_batch_item_id IS NOT NULL
       OR (
         COALESCE(array_length(v_candidate_ids, 1), 0) > 0
         AND carry_forward_rows.candidate_id = ANY(COALESCE(v_candidate_ids, ARRAY[]::uuid[]))
         AND carry_forward_rows.status IN ('PENDING_CARRY_FORWARD', 'RESERVED_IN_DRAFT', 'CONSUMED_IN_BATCH', 'CANCELLED', 'SUPERSEDED', 'NEEDS_REVIEW')
       )
  ), target_carry_forward_item_rows AS (
    SELECT
      relevant_carry_forwards.id AS carry_forward_id,
      target_batch_item_rows.pay_batch_item_id AS target_pay_batch_item_id,
      target_batch_item_rows.pay_batch_id AS target_pay_batch_id,
      target_batch_item_rows.candidate_id AS target_candidate_id,
      target_batch_item_rows.amount_ex_vat AS target_amount_ex_vat,
      target_batch_item_rows.amount_vat AS target_amount_vat,
      target_batch_item_rows.amount_inc_vat AS target_amount_inc_vat,
      target_batch_item_rows.is_voided AS target_is_voided,
      target_batch_item_rows.source_ref AS target_source_ref,
      target_batch_item_rows.operation_source_key AS target_operation_source_key
    FROM relevant_carry_forwards
    LEFT JOIN target_items AS target_batch_item_rows
      ON target_batch_item_rows.pay_batch_item_id = relevant_carry_forwards.target_pay_batch_item_id
      OR lower(COALESCE(target_batch_item_rows.operation_source_key, '')) = 'carry_forward:' || relevant_carry_forwards.id::text
      OR lower(COALESCE(target_batch_item_rows.source_ref, '')) = 'carry_forward:' || relevant_carry_forwards.id::text
  ), source_carry_forward_item_rows AS (
    SELECT
      relevant_carry_forwards.id AS carry_forward_id,
      source_batch_item_rows.id AS source_pay_batch_item_id,
      source_batch_item_rows.amount_ex_vat AS source_amount_ex_vat,
      source_batch_item_rows.amount_vat AS source_amount_vat,
      source_batch_item_rows.amount_inc_vat AS source_amount_inc_vat,
      source_batch_item_rows.pay_bank_transfer_id AS source_pay_bank_transfer_id,
      source_candidate_rows.settlement_status AS source_settlement_status,
      source_candidate_rows.settled_at_utc AS source_settled_at_utc,
      source_transfer_rows.status AS source_transfer_status,
      source_transfer_rows.rail_state AS source_transfer_rail_state,
      COALESCE(source_transfer_rows.rail_meta_json, '{}'::jsonb) AS source_transfer_meta_json
    FROM relevant_carry_forwards
    LEFT JOIN public.pay_batch_items AS source_batch_item_rows
      ON source_batch_item_rows.id = relevant_carry_forwards.source_pay_batch_item_id
    LEFT JOIN public.pay_batch_candidates AS source_candidate_rows
      ON source_candidate_rows.id = source_batch_item_rows.pay_batch_candidate_id
    LEFT JOIN public.pay_bank_transfers AS source_transfer_rows
      ON source_transfer_rows.id = source_batch_item_rows.pay_bank_transfer_id
  ), source_classified_rows AS (
    SELECT
      source_carry_forward_item_rows.*,
      COALESCE(source_classification_rows.is_final_money_moved, false) AS source_is_final_money_moved
    FROM source_carry_forward_item_rows
    LEFT JOIN LATERAL public._pay_rail_state_money_movement_classify(
      source_carry_forward_item_rows.source_transfer_status,
      source_carry_forward_item_rows.source_transfer_rail_state,
      source_carry_forward_item_rows.source_transfer_meta_json,
      source_carry_forward_item_rows.source_transfer_meta_json
    ) AS source_classification_rows ON source_carry_forward_item_rows.source_pay_bank_transfer_id IS NOT NULL
  ), checked_carry_forwards AS (
    SELECT
      relevant_carry_forwards.id AS carry_forward_id,
      relevant_carry_forwards.status AS carry_forward_status,
      relevant_carry_forwards.candidate_id,
      relevant_carry_forwards.pay_channel,
      relevant_carry_forwards.amount_ex_vat AS carry_forward_amount_ex_vat,
      relevant_carry_forwards.amount_vat AS carry_forward_amount_vat,
      relevant_carry_forwards.amount_inc_vat AS carry_forward_amount_inc_vat,
      relevant_carry_forwards.source_pay_batch_id,
      relevant_carry_forwards.source_pay_batch_item_id,
      relevant_carry_forwards.target_pay_batch_id,
      relevant_carry_forwards.target_pay_batch_item_id,
      target_carry_forward_item_rows.target_pay_batch_item_id AS actual_target_pay_batch_item_id,
      target_carry_forward_item_rows.target_pay_batch_id AS actual_target_pay_batch_id,
      target_carry_forward_item_rows.target_amount_ex_vat,
      target_carry_forward_item_rows.target_amount_vat,
      target_carry_forward_item_rows.target_amount_inc_vat,
      target_carry_forward_item_rows.target_is_voided,
      source_classified_rows.source_pay_batch_item_id AS actual_source_pay_batch_item_id,
      source_classified_rows.source_amount_ex_vat,
      source_classified_rows.source_amount_vat,
      source_classified_rows.source_amount_inc_vat,
      source_classified_rows.source_settlement_status,
      source_classified_rows.source_settled_at_utc,
      source_classified_rows.source_is_final_money_moved,
      EXISTS (
        SELECT 1
        FROM target_items AS represented_target_items
        WHERE represented_target_items.candidate_id = relevant_carry_forwards.candidate_id
          AND upper(btrim(COALESCE(represented_target_items.pay_channel, ''))) = upper(btrim(COALESCE(relevant_carry_forwards.pay_channel, '')))
          AND COALESCE(represented_target_items.is_voided, false) = false
          AND (
            represented_target_items.pay_batch_item_id = relevant_carry_forwards.target_pay_batch_item_id
            OR lower(COALESCE(represented_target_items.operation_source_key, '')) = 'carry_forward:' || relevant_carry_forwards.id::text
            OR lower(COALESCE(represented_target_items.source_ref, '')) = 'carry_forward:' || relevant_carry_forwards.id::text
          )
      ) AS is_represented_in_target_batch
    FROM relevant_carry_forwards
    LEFT JOIN target_carry_forward_item_rows
      ON target_carry_forward_item_rows.carry_forward_id = relevant_carry_forwards.id
    LEFT JOIN source_classified_rows
      ON source_classified_rows.carry_forward_id = relevant_carry_forwards.id
  ), blocker_rows AS (
    SELECT
      CASE
        WHEN checked_carry_forwards.carry_forward_status IN ('CANCELLED', 'SUPERSEDED', 'NEEDS_REVIEW') THEN 'MANUAL_ADJUSTMENT_CARRY_FORWARD_CHANGED'
        WHEN checked_carry_forwards.carry_forward_status = 'CONSUMED_IN_BATCH'
          AND checked_carry_forwards.target_pay_batch_id IS DISTINCT FROM v_effective_pay_batch_id THEN 'MANUAL_ADJUSTMENT_CARRY_FORWARD_CONSUMED_ELSEWHERE'
        WHEN checked_carry_forwards.carry_forward_status = 'RESERVED_IN_DRAFT'
          AND checked_carry_forwards.target_pay_batch_id IS NOT NULL
          AND checked_carry_forwards.target_pay_batch_id IS DISTINCT FROM v_effective_pay_batch_id THEN 'MANUAL_ADJUSTMENT_CARRY_FORWARD_RESERVED_ELSEWHERE'
        WHEN checked_carry_forwards.carry_forward_status = 'RESERVED_IN_DRAFT'
          AND checked_carry_forwards.target_pay_batch_id = v_effective_pay_batch_id
          AND checked_carry_forwards.actual_target_pay_batch_item_id IS NULL THEN 'RESERVED_CARRY_FORWARD_MISSING_FROM_TARGET_BATCH'
        WHEN checked_carry_forwards.carry_forward_status = 'RESERVED_IN_DRAFT'
          AND checked_carry_forwards.target_pay_batch_id = v_effective_pay_batch_id
          AND COALESCE(checked_carry_forwards.target_is_voided, false) THEN 'RESERVED_CARRY_FORWARD_TARGET_ITEM_VOIDED'
        WHEN checked_carry_forwards.carry_forward_status = 'RESERVED_IN_DRAFT'
          AND checked_carry_forwards.target_pay_batch_id = v_effective_pay_batch_id
          AND (
            round(COALESCE(checked_carry_forwards.carry_forward_amount_ex_vat, 0), 2) <> round(COALESCE(checked_carry_forwards.target_amount_ex_vat, 0), 2)
            OR round(COALESCE(checked_carry_forwards.carry_forward_amount_vat, 0), 2) <> round(COALESCE(checked_carry_forwards.target_amount_vat, 0), 2)
            OR round(COALESCE(checked_carry_forwards.carry_forward_amount_inc_vat, 0), 2) <> round(COALESCE(checked_carry_forwards.target_amount_inc_vat, 0), 2)
          ) THEN 'MANUAL_ADJUSTMENT_CARRY_FORWARD_AMOUNT_CHANGED'
        WHEN checked_carry_forwards.actual_source_pay_batch_item_id IS NOT NULL
          AND (
            round(COALESCE(checked_carry_forwards.carry_forward_amount_ex_vat, 0), 2) <> round(COALESCE(checked_carry_forwards.source_amount_ex_vat, 0), 2)
            OR round(COALESCE(checked_carry_forwards.carry_forward_amount_vat, 0), 2) <> round(COALESCE(checked_carry_forwards.source_amount_vat, 0), 2)
            OR round(COALESCE(checked_carry_forwards.carry_forward_amount_inc_vat, 0), 2) <> round(COALESCE(checked_carry_forwards.source_amount_inc_vat, 0), 2)
          ) THEN 'MANUAL_ADJUSTMENT_CARRY_FORWARD_SOURCE_AMOUNT_CHANGED'
        WHEN upper(COALESCE(checked_carry_forwards.source_settlement_status, '')) = 'SETTLED'
          OR checked_carry_forwards.source_settled_at_utc IS NOT NULL
          OR COALESCE(checked_carry_forwards.source_is_final_money_moved, false) THEN 'SOURCE_PAYMENT_SCOPE_BECAME_PAID_OR_SETTLED'
        WHEN checked_carry_forwards.carry_forward_status = 'PENDING_CARRY_FORWARD'
          AND COALESCE(array_length(v_candidate_ids, 1), 0) > 0
          AND checked_carry_forwards.candidate_id = ANY(COALESCE(v_candidate_ids, ARRAY[]::uuid[]))
          AND checked_carry_forwards.is_represented_in_target_batch = false THEN 'PENDING_CARRY_FORWARD_NOT_INCLUDED_IN_TARGET_BATCH'
        ELSE NULL::text
      END AS blocker_code,
      checked_carry_forwards.carry_forward_id,
      checked_carry_forwards.carry_forward_status,
      checked_carry_forwards.candidate_id,
      checked_carry_forwards.pay_channel,
      checked_carry_forwards.source_pay_batch_id,
      checked_carry_forwards.source_pay_batch_item_id,
      checked_carry_forwards.target_pay_batch_id,
      checked_carry_forwards.target_pay_batch_item_id,
      checked_carry_forwards.actual_target_pay_batch_item_id,
      checked_carry_forwards.carry_forward_amount_inc_vat,
      checked_carry_forwards.target_amount_inc_vat
    FROM checked_carry_forwards
  )
  SELECT
    COALESCE(jsonb_agg(jsonb_build_object(
      'code', blocker_rows.blocker_code,
      'carry_forward_id', blocker_rows.carry_forward_id::text,
      'status', blocker_rows.carry_forward_status,
      'candidate_id', CASE WHEN blocker_rows.candidate_id IS NULL THEN NULL ELSE blocker_rows.candidate_id::text END,
      'pay_channel', blocker_rows.pay_channel,
      'source_pay_batch_id', blocker_rows.source_pay_batch_id::text,
      'source_pay_batch_item_id', blocker_rows.source_pay_batch_item_id::text,
      'target_pay_batch_id', CASE WHEN blocker_rows.target_pay_batch_id IS NULL THEN NULL ELSE blocker_rows.target_pay_batch_id::text END,
      'target_pay_batch_item_id', CASE WHEN blocker_rows.target_pay_batch_item_id IS NULL THEN NULL ELSE blocker_rows.target_pay_batch_item_id::text END,
      'actual_target_pay_batch_item_id', CASE WHEN blocker_rows.actual_target_pay_batch_item_id IS NULL THEN NULL ELSE blocker_rows.actual_target_pay_batch_item_id::text END,
      'carry_forward_amount_inc_vat', blocker_rows.carry_forward_amount_inc_vat,
      'target_amount_inc_vat', blocker_rows.target_amount_inc_vat
    ) ORDER BY blocker_rows.carry_forward_id::text, blocker_rows.blocker_code) FILTER (WHERE blocker_rows.blocker_code IS NOT NULL), '[]'::jsonb),
    COALESCE(jsonb_agg(DISTINCT blocker_rows.blocker_code) FILTER (WHERE blocker_rows.blocker_code IS NOT NULL), '[]'::jsonb),
    COALESCE(jsonb_agg(DISTINCT blocker_rows.carry_forward_id::text) FILTER (WHERE blocker_rows.carry_forward_id IS NOT NULL), '[]'::jsonb)
  INTO v_blockers, v_stale_reasons, v_carry_forward_ids_json
  FROM blocker_rows;

  v_blocker_count := COALESCE(jsonb_array_length(COALESCE(v_blockers, '[]'::jsonb)), 0);

  RETURN jsonb_build_object(
    'ok', v_blocker_count = 0,
    'blockers', COALESCE(v_blockers, '[]'::jsonb),
    'carry_forward_ids', COALESCE(v_carry_forward_ids_json, '[]'::jsonb),
    'stale_reasons', COALESCE(v_stale_reasons, '[]'::jsonb),
    'support_details_json', jsonb_build_object(
      'pay_batch_id', v_effective_pay_batch_id::text,
      'candidate_ids', COALESCE((SELECT jsonb_agg(candidate_values.candidate_id::text ORDER BY candidate_values.candidate_id::text) FROM unnest(COALESCE(v_candidate_ids, ARRAY[]::uuid[])) AS candidate_values(candidate_id)), '[]'::jsonb),
      'pay_batch_item_ids', COALESCE((SELECT jsonb_agg(item_values.pay_batch_item_id::text ORDER BY item_values.pay_batch_item_id::text) FROM unnest(COALESCE(v_pay_batch_item_ids, ARRAY[]::uuid[])) AS item_values(pay_batch_item_id)), '[]'::jsonb),
      'blocker_count', v_blocker_count,
      'actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END,
      'signed_amount_convention', 'SIGNED_AMOUNTS',
      'adjustment_direction_is_display_only', true
    )
  );
END;
$function$;





CREATE OR REPLACE FUNCTION public._pay_batch_provider_submit_preflight_recheck(
  p_pay_batch_id uuid,
  p_scope_json jsonb DEFAULT '{}'::jsonb,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_uuid_regex text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_scope_json jsonb := COALESCE(p_scope_json, '{}'::jsonb);
  v_effective_scope_json jsonb := '{}'::jsonb;
  v_resolved_scope_json jsonb := '{}'::jsonb;
  v_pay_batch_item_ids uuid[] := ARRAY[]::uuid[];
  v_pay_bank_transfer_ids uuid[] := ARRAY[]::uuid[];
  v_blockers jsonb := '[]'::jsonb;
  v_provider_evidence_json jsonb := '{}'::jsonb;
  v_provider_submitted boolean := false;
  v_provider_evidence_class text := NULL::text;
  v_provider_cash_state text := NULL::text;
  v_transfer_provider_evidence_count integer := 0;
  v_operation_submit_attempt_evidence_count integer := 0;
  v_batch_status text := NULL::text;
  v_batch_cancelled_at_utc timestamptz := NULL::timestamptz;
  v_batch_execution_commit_state text := NULL::text;
  v_voided_item_count integer := 0;
  v_applied_pre_bank_cancel_count integer := 0;
  v_cancelled_transfer_count integer := 0;
  v_open_pre_bank_cancel_count integer := 0;
  v_other_operation_count integer := 0;
  v_other_chunk_count integer := 0;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF v_scope_json IS NOT NULL AND jsonb_typeof(v_scope_json) <> 'object' THEN
    RAISE EXCEPTION 'SCOPE_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'SCOPE_JSON_MUST_BE_OBJECT', 'pay_batch_id', p_pay_batch_id)::text;
  END IF;

  IF v_scope_json IS NULL OR jsonb_typeof(v_scope_json) <> 'object' OR NULLIF(btrim(COALESCE(v_scope_json->>'scope_type', '')), '') IS NULL THEN
    v_effective_scope_json := COALESCE(v_scope_json, '{}'::jsonb) || jsonb_build_object('scope_type', 'BATCH');
  ELSE
    v_effective_scope_json := v_scope_json;
  END IF;

  SELECT
    batch_rows.status,
    batch_rows.cancelled_at_utc,
    batch_rows.execution_commit_state
  INTO
    v_batch_status,
    v_batch_cancelled_at_utc,
    v_batch_execution_commit_state
  FROM public.pay_batches AS batch_rows
  WHERE batch_rows.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_NOT_FOUND', 'pay_batch_id', p_pay_batch_id)::text;
  END IF;

  v_resolved_scope_json := public._pay_resolve_payment_scope_for_cancel_rewind(
    p_pay_batch_id,
    v_effective_scope_json,
    true,
    p_actor_user_id
  );

  WITH raw_values AS (
    SELECT item_values.raw_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_resolved_scope_json->'pay_batch_item_ids') = 'array' THEN v_resolved_scope_json->'pay_batch_item_ids'
        ELSE '[]'::jsonb
      END
    ) AS item_values(raw_value)
  ), clean_values AS (
    SELECT NULLIF(btrim(raw_values.raw_value), '') AS clean_value
    FROM raw_values
  )
  SELECT COALESCE(array_agg(clean_values.clean_value::uuid), ARRAY[]::uuid[])
  INTO v_pay_batch_item_ids
  FROM clean_values
  WHERE clean_values.clean_value IS NOT NULL
    AND clean_values.clean_value ~ v_uuid_regex;

  WITH raw_values AS (
    SELECT transfer_values.raw_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_resolved_scope_json->'pay_bank_transfer_ids') = 'array' THEN v_resolved_scope_json->'pay_bank_transfer_ids'
        ELSE '[]'::jsonb
      END
    ) AS transfer_values(raw_value)
  ), clean_values AS (
    SELECT NULLIF(btrim(raw_values.raw_value), '') AS clean_value
    FROM raw_values
  )
  SELECT COALESCE(array_agg(clean_values.clean_value::uuid), ARRAY[]::uuid[])
  INTO v_pay_bank_transfer_ids
  FROM clean_values
  WHERE clean_values.clean_value IS NOT NULL
    AND clean_values.clean_value ~ v_uuid_regex;

  IF upper(btrim(COALESCE(v_batch_status, ''))) = 'CANCELLED'
     OR v_batch_cancelled_at_utc IS NOT NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'TRANSFER_CANCELLED_BEFORE_PROVIDER_SUBMIT',
      'reason', 'The pay batch is already cancelled before provider submission.',
      'pay_batch_id', p_pay_batch_id::text,
      'batch_status', v_batch_status,
      'cancelled_at_utc', v_batch_cancelled_at_utc
    ));
  END IF;

  SELECT count(*)::integer
  INTO v_voided_item_count
  FROM public.pay_batch_items AS item_rows
  WHERE item_rows.id = ANY(COALESCE(v_pay_batch_item_ids, ARRAY[]::uuid[]))
    AND COALESCE(item_rows.is_voided, false) = true;

  IF COALESCE(v_voided_item_count, 0) > 0 THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'PAYMENT_ITEMS_VOIDED_BEFORE_PROVIDER_SUBMIT',
      'reason', 'One or more payment items in the provider-submit scope have already been voided.',
      'voided_item_count', v_voided_item_count
    ));
  END IF;

  SELECT count(*)::integer
  INTO v_applied_pre_bank_cancel_count
  FROM public.pay_payment_correction_items AS correction_item_rows
  WHERE correction_item_rows.pay_batch_id = p_pay_batch_id
    AND correction_item_rows.correction_item_kind = 'PRE_BANK_CANCEL'
    AND upper(btrim(COALESCE(correction_item_rows.status, ''))) = 'APPLIED'
    AND (
      correction_item_rows.pay_batch_item_id = ANY(COALESCE(v_pay_batch_item_ids, ARRAY[]::uuid[]))
      OR correction_item_rows.pay_bank_transfer_id = ANY(COALESCE(v_pay_bank_transfer_ids, ARRAY[]::uuid[]))
    );

  IF COALESCE(v_applied_pre_bank_cancel_count, 0) > 0 THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'PAYMENT_ITEMS_VOIDED_BEFORE_PROVIDER_SUBMIT',
      'reason', 'One or more payment items in the provider-submit scope already have an applied PRE_BANK_CANCEL correction.',
      'applied_pre_bank_cancel_count', v_applied_pre_bank_cancel_count
    ));
  END IF;

  SELECT count(*)::integer
  INTO v_cancelled_transfer_count
  FROM public.pay_bank_transfers AS transfer_rows
  WHERE transfer_rows.id = ANY(COALESCE(v_pay_bank_transfer_ids, ARRAY[]::uuid[]))
    AND upper(btrim(COALESCE(transfer_rows.status, ''))) IN (
      'CANCELLED',
      'CANCELED',
      'VOIDED',
      'LOCALLY_CANCELLED',
      'LOCAL_CANCELLED',
      'CANCELLED_BEFORE_BANK_SUBMISSION',
      'CANCELED_BEFORE_BANK_SUBMISSION'
    );

  IF COALESCE(v_cancelled_transfer_count, 0) > 0 THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'TRANSFER_CANCELLED_BEFORE_PROVIDER_SUBMIT',
      'reason', 'One or more bank transfer rows in the provider-submit scope have already been locally cancelled.',
      'cancelled_transfer_count', v_cancelled_transfer_count
    ));
  END IF;

  SELECT count(*)::integer
  INTO v_open_pre_bank_cancel_count
  FROM public.pay_payment_correction_requests AS request_rows
  WHERE request_rows.pay_batch_id = p_pay_batch_id
    AND upper(btrim(COALESCE(request_rows.correction_kind, ''))) = 'PRE_BANK_CANCEL'
    AND upper(btrim(COALESCE(request_rows.status, ''))) IN (
      'REQUESTED',
      'PENDING',
      'AUTHORISED',
      'AUTHORIZED',
      'IN_PROGRESS',
      'PROCESSING',
      'EXPANDED'
    );

  IF COALESCE(v_open_pre_bank_cancel_count, 0) > 0 THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT',
      'reason', 'A pre-bank cancellation request exists for this batch/scope, so provider submission must not proceed.',
      'open_pre_bank_cancel_count', v_open_pre_bank_cancel_count
    ));
  END IF;

  SELECT jsonb_build_object(
      'evidence_class', evidence_rows.evidence_class,
      'provider_submitted', evidence_rows.provider_submitted,
      'provider_request_sent', evidence_rows.provider_request_sent,
      'provider_response_present', evidence_rows.provider_response_present,
      'provider_event_present', evidence_rows.provider_event_present,
      'provider_external_id_present', evidence_rows.provider_external_id_present,
      'local_prepared_only', evidence_rows.local_prepared_only,
      'cash_state', evidence_rows.cash_state,
      'blocker_code', evidence_rows.blocker_code,
      'reason', evidence_rows.reason,
      'support_details_json', evidence_rows.support_details_json
    ),
    evidence_rows.provider_submitted,
    evidence_rows.evidence_class,
    evidence_rows.cash_state
  INTO
    v_provider_evidence_json,
    v_provider_submitted,
    v_provider_evidence_class,
    v_provider_cash_state
  FROM public._pay_bank_transfer_provider_evidence_classify(
    p_pay_batch_id,
    NULL::uuid,
    v_effective_scope_json,
    p_operation_id
  ) AS evidence_rows
  LIMIT 1;

  v_transfer_provider_evidence_count :=
    COALESCE(NULLIF(v_provider_evidence_json #>> '{support_details_json,provider_external_id_count}', '')::integer, 0)
    + COALESCE(NULLIF(v_provider_evidence_json #>> '{support_details_json,provider_response_count}', '')::integer, 0)
    + COALESCE(NULLIF(v_provider_evidence_json #>> '{support_details_json,provider_event_count}', '')::integer, 0)
    + COALESCE(NULLIF(v_provider_evidence_json #>> '{support_details_json,provider_request_sent_count}', '')::integer, 0)
    + COALESCE(NULLIF(v_provider_evidence_json #>> '{support_details_json,provider_outcome_unknown_count}', '')::integer, 0);

  v_operation_submit_attempt_evidence_count := COALESCE(NULLIF(v_provider_evidence_json #>> '{support_details_json,operation_submit_attempt_count}', '')::integer, 0);

  IF COALESCE(v_provider_submitted, false)
     AND (
       COALESCE(v_transfer_provider_evidence_count, 0) > 0
       OR (p_operation_id IS NULL AND COALESCE(v_operation_submit_attempt_evidence_count, 0) > 0)
     ) THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'PROVIDER_SUBMISSION_ALREADY_CLAIMED',
      'reason', 'Provider submission evidence already exists for this payment scope.',
      'evidence_class', v_provider_evidence_class,
      'cash_state', v_provider_cash_state,
      'transfer_provider_evidence_count', v_transfer_provider_evidence_count,
      'operation_submit_attempt_evidence_count', v_operation_submit_attempt_evidence_count
    ));
  END IF;

  SELECT count(*)::integer
  INTO v_other_operation_count
  FROM public.banking_pay_operations AS operation_rows
  WHERE operation_rows.pay_batch_id = p_pay_batch_id
    AND (p_operation_id IS NULL OR operation_rows.id <> p_operation_id)
    AND upper(btrim(COALESCE(operation_rows.operation_type, ''))) IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS', 'PAYMENT_SETTLEMENT')
    AND upper(btrim(COALESCE(operation_rows.status, ''))) IN ('QUEUED', 'CLAIMED', 'LOCKED', 'RUNNING', 'PROCESSING', 'IN_PROGRESS', 'REVIEW_REQUIRED');

  SELECT count(*)::integer
  INTO v_other_chunk_count
  FROM public.banking_pay_operation_chunks AS chunk_rows
  JOIN public.banking_pay_operations AS operation_rows
    ON operation_rows.id = chunk_rows.operation_id
  WHERE operation_rows.pay_batch_id = p_pay_batch_id
    AND (p_operation_id IS NULL OR operation_rows.id <> p_operation_id)
    AND upper(btrim(COALESCE(operation_rows.operation_type, ''))) IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS', 'PAYMENT_SETTLEMENT')
    AND upper(btrim(COALESCE(chunk_rows.status, ''))) IN ('PENDING', 'CLAIMED', 'LOCKED', 'RUNNING', 'PROCESSING');

  IF COALESCE(v_other_operation_count, 0) + COALESCE(v_other_chunk_count, 0) > 0 THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'PROVIDER_SUBMISSION_IN_PROGRESS',
      'reason', 'Another payment provider operation/chunk is already in progress for this batch.',
      'other_operation_count', v_other_operation_count,
      'other_chunk_count', v_other_chunk_count
    ));
  END IF;

  RETURN jsonb_build_object(
    'ok', COALESCE(jsonb_array_length(v_blockers), 0) = 0,
    'pay_batch_id', p_pay_batch_id::text,
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'blockers', COALESCE(v_blockers, '[]'::jsonb),
    'resolved_scope_json', COALESCE(v_resolved_scope_json, '{}'::jsonb),
    'provider_evidence_json', COALESCE(v_provider_evidence_json, '{}'::jsonb),
    'support_details_json', jsonb_build_object(
      'batch_status', v_batch_status,
      'batch_cancelled_at_utc', v_batch_cancelled_at_utc,
      'batch_execution_commit_state', v_batch_execution_commit_state,
      'voided_item_count', COALESCE(v_voided_item_count, 0),
      'applied_pre_bank_cancel_count', COALESCE(v_applied_pre_bank_cancel_count, 0),
      'cancelled_transfer_count', COALESCE(v_cancelled_transfer_count, 0),
      'open_pre_bank_cancel_count', COALESCE(v_open_pre_bank_cancel_count, 0),
      'transfer_provider_evidence_count', COALESCE(v_transfer_provider_evidence_count, 0),
      'operation_submit_attempt_evidence_count', COALESCE(v_operation_submit_attempt_evidence_count, 0),
      'other_operation_count', COALESCE(v_other_operation_count, 0),
      'other_chunk_count', COALESCE(v_other_chunk_count, 0),
      'actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END
    )
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public._pay_batch_item_source_reservation_amount_ex_vat(p_pay_batch_item_id uuid)
RETURNS numeric
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_pay_batch_id uuid;
  v_timesheet_id uuid;
  v_item_type text;
  v_finance_case_id uuid;
  v_finance_component_id uuid;
  v_amount_ex_vat numeric;
  v_frozen_source_amount numeric;
  v_frozen_target_amount_ex_vat numeric;
  v_frozen_resolution_mode public.pay_finance_component_resolution_mode_enum;
  v_frozen_resolution_payload_json jsonb;
  v_frozen_resolution_result_json jsonb;
  v_frozen_component_key_type text;
  v_frozen_component_key_value text;
  v_frozen_component_snapshot_json jsonb;
  v_frozen_source_basis_json jsonb;
  v_single_breakdown_meta_json jsonb := '{}'::jsonb;
  v_breakdown_count integer := 0;
  v_resolved_key_type text;
  v_resolved_key_value text;
  v_key_resolution_failure_reason text;
  v_source_text text;
  v_has_source_target_split boolean;
BEGIN
  IF p_pay_batch_item_id IS NULL THEN
    RETURN NULL::numeric(12,2);
  END IF;

  SELECT
    pay_batch_candidate_row.pay_batch_id,
    pay_batch_item_row.timesheet_id,
    UPPER(NULLIF(BTRIM(COALESCE(pay_batch_item_row.item_type, '')), '')),
    pay_batch_item_row.finance_case_id,
    pay_batch_item_row.finance_component_id,
    pay_batch_item_row.amount_ex_vat,
    pay_batch_item_row.frozen_source_amount,
    pay_batch_item_row.frozen_target_amount_ex_vat,
    pay_batch_item_row.frozen_resolution_mode,
    pay_batch_item_row.frozen_resolution_payload_json,
    pay_batch_item_row.frozen_resolution_result_json,
    pay_batch_item_row.frozen_component_key_type,
    pay_batch_item_row.frozen_component_key_value,
    CASE
      WHEN jsonb_typeof(COALESCE(pay_batch_item_row.frozen_component_snapshot_json, '{}'::jsonb)) = 'object'
        THEN COALESCE(pay_batch_item_row.frozen_component_snapshot_json, '{}'::jsonb)
      ELSE '{}'::jsonb
    END,
    CASE
      WHEN jsonb_typeof(COALESCE(pay_batch_item_row.frozen_source_basis_json, '{}'::jsonb)) = 'object'
        THEN COALESCE(pay_batch_item_row.frozen_source_basis_json, '{}'::jsonb)
      ELSE '{}'::jsonb
    END
  INTO
    v_pay_batch_id,
    v_timesheet_id,
    v_item_type,
    v_finance_case_id,
    v_finance_component_id,
    v_amount_ex_vat,
    v_frozen_source_amount,
    v_frozen_target_amount_ex_vat,
    v_frozen_resolution_mode,
    v_frozen_resolution_payload_json,
    v_frozen_resolution_result_json,
    v_frozen_component_key_type,
    v_frozen_component_key_value,
    v_frozen_component_snapshot_json,
    v_frozen_source_basis_json
  FROM public.pay_batch_items AS pay_batch_item_row
  JOIN public.pay_batch_candidates AS pay_batch_candidate_row
    ON pay_batch_candidate_row.id = pay_batch_item_row.pay_batch_candidate_id
  WHERE pay_batch_item_row.id = p_pay_batch_item_id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN NULL::numeric(12,2);
  END IF;

  IF v_item_type NOT IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA') THEN
    RETURN NULL::numeric(12,2);
  END IF;

  SELECT
    COUNT(*)::integer,
    CASE
      WHEN COUNT(*) = 1 THEN (ARRAY_AGG(breakdown_row.meta_json ORDER BY breakdown_row.id))[1]
      ELSE '{}'::jsonb
    END
  INTO
    v_breakdown_count,
    v_single_breakdown_meta_json
  FROM public.pay_batch_item_breakdowns AS breakdown_row
  WHERE breakdown_row.pay_batch_item_id = p_pay_batch_item_id;

  IF jsonb_typeof(COALESCE(v_single_breakdown_meta_json, '{}'::jsonb)) <> 'object' THEN
    v_single_breakdown_meta_json := '{}'::jsonb;
  END IF;

  SELECT
    resolved_key_row.key_type,
    resolved_key_row.key_value,
    resolved_key_row.key_resolution_failure_reason
  INTO
    v_resolved_key_type,
    v_resolved_key_value,
    v_key_resolution_failure_reason
  FROM public._pay_policy_x_resolve_post_draft_economic_key(
    p_pay_batch_item_id => p_pay_batch_item_id,
    p_pay_batch_id => v_pay_batch_id,
    p_timesheet_id => v_timesheet_id,
    p_item_type => v_item_type,
    p_frozen_key_type => v_frozen_component_key_type,
    p_frozen_key_value => v_frozen_component_key_value,
    p_frozen_component_snapshot_json => v_frozen_component_snapshot_json,
    p_frozen_source_basis_json => v_frozen_source_basis_json,
    p_breakdown_meta_json => v_single_breakdown_meta_json,
    p_target_snapshot_json => NULL::jsonb
  ) AS resolved_key_row
  LIMIT 1;

  IF v_key_resolution_failure_reason IS NOT NULL
     OR v_resolved_key_type IS NULL
     OR BTRIM(COALESCE(v_resolved_key_type, '')) = ''
     OR v_resolved_key_value IS NULL
     OR BTRIM(COALESCE(v_resolved_key_value, '')) = ''
     OR (v_resolved_key_type = 'TS_DAY' AND v_resolved_key_value !~ '^\d{4}-\d{2}-\d{2}$') THEN
    RETURN NULL::numeric(12,2);
  END IF;

  IF v_frozen_source_amount IS NOT NULL THEN
    RETURN ROUND(ABS(v_frozen_source_amount), 2)::numeric(12,2);
  END IF;

  SELECT source_candidates.source_text_value
  INTO v_source_text
  FROM (
    VALUES
      (v_frozen_component_snapshot_json->>'source_reservation_amount_ex_vat'),
      (v_frozen_component_snapshot_json->>'source_entitlement_amount_ex_vat'),
      (v_frozen_component_snapshot_json->>'source_amount_ex_vat'),
      (v_frozen_component_snapshot_json->>'source_pay_ex_vat'),
      (v_frozen_component_snapshot_json->>'source_pay_amount_ex_vat'),
      (v_frozen_component_snapshot_json->>'basis_source_amount_ex_vat'),
      (v_frozen_component_snapshot_json->>'reserved_source_amount'),
      (v_frozen_component_snapshot_json->>'frozen_source_amount'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,source_reservation_amount_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,source_entitlement_amount_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,source_amount_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,source_pay_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,source_pay_amount_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,basis_source_amount_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,pay_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,pay_amount_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,amount_ex_vat}'),
      (v_frozen_source_basis_json->>'source_reservation_amount_ex_vat'),
      (v_frozen_source_basis_json->>'source_entitlement_amount_ex_vat'),
      (v_frozen_source_basis_json->>'source_amount_ex_vat'),
      (v_frozen_source_basis_json->>'source_pay_ex_vat'),
      (v_frozen_source_basis_json->>'source_pay_amount_ex_vat'),
      (v_frozen_source_basis_json->>'basis_source_amount_ex_vat'),
      (v_frozen_source_basis_json->>'reserved_source_amount'),
      (v_frozen_source_basis_json->>'frozen_source_amount'),
      (v_frozen_source_basis_json->>'pay_ex_vat'),
      (v_frozen_source_basis_json->>'pay_amount_ex_vat'),
      (v_frozen_source_basis_json->>'amount_ex_vat'),
      (v_frozen_source_basis_json->>'pay_amount'),
      (v_frozen_resolution_payload_json->>'source_reservation_amount_ex_vat'),
      (v_frozen_resolution_payload_json->>'source_entitlement_amount_ex_vat'),
      (v_frozen_resolution_payload_json->>'source_amount_ex_vat'),
      (v_frozen_resolution_payload_json->>'source_pay_ex_vat'),
      (v_frozen_resolution_result_json->>'source_reservation_amount_ex_vat'),
      (v_frozen_resolution_result_json->>'source_entitlement_amount_ex_vat'),
      (v_frozen_resolution_result_json->>'source_amount_ex_vat'),
      (v_frozen_resolution_result_json->>'source_pay_ex_vat'),
      (v_single_breakdown_meta_json->>'source_reservation_amount_ex_vat'),
      (v_single_breakdown_meta_json->>'source_entitlement_amount_ex_vat'),
      (v_single_breakdown_meta_json->>'source_amount_ex_vat'),
      (v_single_breakdown_meta_json->>'source_pay_ex_vat')
  ) AS source_candidates(source_text_value)
  WHERE source_candidates.source_text_value IS NOT NULL
    AND BTRIM(source_candidates.source_text_value) ~ '^-?[0-9]+(\.[0-9]+)?$'
  LIMIT 1;

  IF v_source_text IS NOT NULL THEN
    RETURN ROUND(ABS(v_source_text::numeric), 2)::numeric(12,2);
  END IF;

  v_has_source_target_split :=
       v_finance_case_id IS NOT NULL
    OR v_finance_component_id IS NOT NULL
    OR v_frozen_target_amount_ex_vat IS NOT NULL
    OR v_frozen_resolution_mode IS NOT NULL
    OR v_frozen_resolution_payload_json IS NOT NULL
    OR v_frozen_resolution_result_json IS NOT NULL
    OR v_frozen_component_snapshot_json ? 'target_amount_ex_vat'
    OR v_frozen_component_snapshot_json ? 'target_pay_ex_vat'
    OR v_frozen_component_snapshot_json ? 'target_pay_amount_ex_vat'
    OR v_frozen_component_snapshot_json ? 'frozen_target_amount_ex_vat'
    OR v_frozen_component_snapshot_json ? 'target_rate'
    OR v_frozen_component_snapshot_json ? 'target_units'
    OR v_frozen_component_snapshot_json ? 'resolution_mode'
    OR v_frozen_component_snapshot_json ? 'saved_resolution_mode'
    OR v_frozen_component_snapshot_json ? 'saved_resolution_payload_json'
    OR v_frozen_component_snapshot_json ? 'saved_resolution_result_json';

  IF v_has_source_target_split THEN
    RETURN NULL::numeric(12,2);
  END IF;

  IF v_amount_ex_vat IS NOT NULL THEN
    RETURN ROUND(ABS(v_amount_ex_vat), 2)::numeric(12,2);
  END IF;

  RETURN NULL::numeric(12,2);
END;
$function$;




CREATE OR REPLACE FUNCTION public._pay_policy_x_resolve_post_draft_economic_key(
  p_pay_batch_item_id uuid DEFAULT NULL::uuid,
  p_pay_batch_id uuid DEFAULT NULL::uuid,
  p_timesheet_id uuid DEFAULT NULL::uuid,
  p_item_type text DEFAULT NULL::text,
  p_frozen_key_type text DEFAULT NULL::text,
  p_frozen_key_value text DEFAULT NULL::text,
  p_frozen_component_snapshot_json jsonb DEFAULT '{}'::jsonb,
  p_frozen_source_basis_json jsonb DEFAULT '{}'::jsonb,
  p_breakdown_meta_json jsonb DEFAULT '{}'::jsonb,
  p_target_snapshot_json jsonb DEFAULT NULL::jsonb
)
RETURNS TABLE(
  timesheet_id uuid,
  key_type text,
  key_value text,
  key_resolution_source text,
  key_resolution_failure_reason text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_pay_batch_id uuid := p_pay_batch_id;
  v_pay_batch_item_id uuid := p_pay_batch_item_id;
  v_timesheet_id uuid := p_timesheet_id;
  v_item_type text := UPPER(NULLIF(BTRIM(COALESCE(p_item_type, '')), ''));
  v_segment_key text := NULL::text;
  v_source_ref text := NULL::text;
  v_frozen_key_type text := UPPER(NULLIF(BTRIM(COALESCE(p_frozen_key_type, '')), ''));
  v_frozen_key_value text := NULLIF(BTRIM(COALESCE(p_frozen_key_value, '')), '');
  v_frozen_component_snapshot_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_frozen_component_snapshot_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_frozen_component_snapshot_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_frozen_source_basis_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_frozen_source_basis_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_frozen_source_basis_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_breakdown_meta_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_breakdown_meta_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_breakdown_meta_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_target_snapshot_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_target_snapshot_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_target_snapshot_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_breakdown_count integer := 0;
  v_snapshot_key_type text := NULL::text;
  v_snapshot_key_value text := NULL::text;
  v_work_date_text text := NULL::text;
  v_segment_id_text text := NULL::text;
  v_segment_key_text text := NULL::text;
  v_segment_stable_key_text text := NULL::text;
  v_ref_num_text text := NULL::text;
  v_adjustment_id_text text := NULL::text;
  v_additional_code_text text := NULL::text;
  v_expense_code_text text := NULL::text;
  v_segments_json jsonb := '[]'::jsonb;
  v_segment_match_found boolean := false;
  v_segment_match_date_text text := NULL::text;
  v_resolved_key_type text := NULL::text;
  v_resolved_key_value text := NULL::text;
  v_resolved_source text := NULL::text;
  v_assert_ok boolean := false;
  v_assert_key_type text := NULL::text;
  v_assert_key_value text := NULL::text;
  v_assert_failure_reason text := NULL::text;
  v_failure_reason text := NULL::text;
  v_source_json jsonb := '{}'::jsonb;
BEGIN
  IF v_pay_batch_item_id IS NOT NULL THEN
    SELECT
      batch_candidate_row.pay_batch_id,
      batch_item_row.timesheet_id,
      UPPER(NULLIF(BTRIM(COALESCE(batch_item_row.item_type, '')), '')),
      batch_item_row.segment_key,
      batch_item_row.source_ref,
      UPPER(NULLIF(BTRIM(COALESCE(batch_item_row.frozen_component_key_type, '')), '')),
      NULLIF(BTRIM(COALESCE(batch_item_row.frozen_component_key_value, '')), ''),
      CASE
        WHEN jsonb_typeof(COALESCE(batch_item_row.frozen_component_snapshot_json, '{}'::jsonb)) = 'object' THEN COALESCE(batch_item_row.frozen_component_snapshot_json, '{}'::jsonb)
        ELSE '{}'::jsonb
      END,
      CASE
        WHEN jsonb_typeof(COALESCE(batch_item_row.frozen_source_basis_json, '{}'::jsonb)) = 'object' THEN COALESCE(batch_item_row.frozen_source_basis_json, '{}'::jsonb)
        ELSE '{}'::jsonb
      END
    INTO
      v_pay_batch_id,
      v_timesheet_id,
      v_item_type,
      v_segment_key,
      v_source_ref,
      v_frozen_key_type,
      v_frozen_key_value,
      v_frozen_component_snapshot_json,
      v_frozen_source_basis_json
    FROM public.pay_batch_items AS batch_item_row
    JOIN public.pay_batch_candidates AS batch_candidate_row
      ON batch_candidate_row.id = batch_item_row.pay_batch_candidate_id
    WHERE batch_item_row.id = v_pay_batch_item_id
      AND (p_pay_batch_id IS NULL OR batch_candidate_row.pay_batch_id = p_pay_batch_id)
    LIMIT 1;

    IF v_pay_batch_id IS NOT NULL THEN
      SELECT
        COUNT(*)::integer,
        CASE
          WHEN COUNT(*) = 1 THEN (ARRAY_AGG(breakdown_row.meta_json ORDER BY breakdown_row.id))[1]
          ELSE '{}'::jsonb
        END
      INTO
        v_breakdown_count,
        v_breakdown_meta_json
      FROM public.pay_batch_item_breakdowns AS breakdown_row
      WHERE breakdown_row.pay_batch_item_id = v_pay_batch_item_id;

      IF jsonb_typeof(COALESCE(v_breakdown_meta_json, '{}'::jsonb)) <> 'object' THEN
        v_breakdown_meta_json := '{}'::jsonb;
      END IF;

      IF v_timesheet_id IS NOT NULL
         AND (p_target_snapshot_json IS NULL OR jsonb_typeof(COALESCE(p_target_snapshot_json, '{}'::jsonb)) <> 'object' OR p_target_snapshot_json = '{}'::jsonb) THEN
        SELECT snapshot_row.target_snapshot_json
        INTO v_target_snapshot_json
        FROM public.pay_batch_timesheet_snapshots AS snapshot_row
        WHERE snapshot_row.pay_batch_id = v_pay_batch_id
          AND snapshot_row.timesheet_id = v_timesheet_id
        ORDER BY snapshot_row.created_at_utc DESC, snapshot_row.id DESC
        LIMIT 1;

        IF jsonb_typeof(COALESCE(v_target_snapshot_json, '{}'::jsonb)) <> 'object' THEN
          v_target_snapshot_json := '{}'::jsonb;
        END IF;
      END IF;
    END IF;
  END IF;

  v_source_json := jsonb_build_object(
    'pay_batch_item_id', CASE WHEN v_pay_batch_item_id IS NULL THEN NULL ELSE v_pay_batch_item_id::text END,
    'pay_batch_id', CASE WHEN v_pay_batch_id IS NULL THEN NULL ELSE v_pay_batch_id::text END,
    'authority_scope', 'POST_DRAFT'
  );

  IF v_frozen_key_type IS NOT NULL OR v_frozen_key_value IS NOT NULL THEN
    SELECT
      key_check.ok,
      key_check.key_type,
      key_check.key_value,
      key_check.failure_reason
    INTO
      v_assert_ok,
      v_assert_key_type,
      v_assert_key_value,
      v_assert_failure_reason
    FROM public._pay_policy_x_assert_economic_key(
      p_timesheet_id => v_timesheet_id,
      p_key_type => v_frozen_key_type,
      p_key_value => v_frozen_key_value,
      p_context => 'POST_DRAFT_RESOLVE_FROZEN_ITEM_KEY',
      p_authority_scope => 'POST_DRAFT',
      p_resolution_source => 'FROZEN_ITEM_KEY',
      p_required => true,
      p_source_json => v_source_json
    ) AS key_check;

    IF COALESCE(v_assert_ok, false) THEN
      timesheet_id := v_timesheet_id;
      key_type := v_assert_key_type;
      key_value := v_assert_key_value;
      key_resolution_source := 'FROZEN_ITEM_KEY';
      key_resolution_failure_reason := NULL::text;
      RETURN NEXT;
      RETURN;
    ELSE
      v_failure_reason := v_assert_failure_reason;
    END IF;
  END IF;

  v_snapshot_key_type := UPPER(NULLIF(BTRIM(COALESCE(
    v_frozen_component_snapshot_json->>'component_key_type',
    v_frozen_component_snapshot_json->>'key_type',
    v_frozen_component_snapshot_json#>>'{source_basis_json,component_key_type}',
    v_frozen_component_snapshot_json#>>'{source_basis_json,key_type}',
    v_frozen_source_basis_json->>'component_key_type',
    v_frozen_source_basis_json->>'key_type',
    v_breakdown_meta_json->>'component_key_type',
    v_breakdown_meta_json->>'key_type',
    ''
  )), ''));

  v_snapshot_key_value := NULLIF(BTRIM(COALESCE(
    v_frozen_component_snapshot_json->>'component_key_value',
    v_frozen_component_snapshot_json->>'key_value',
    v_frozen_component_snapshot_json#>>'{source_basis_json,component_key_value}',
    v_frozen_component_snapshot_json#>>'{source_basis_json,key_value}',
    v_frozen_source_basis_json->>'component_key_value',
    v_frozen_source_basis_json->>'key_value',
    v_breakdown_meta_json->>'component_key_value',
    v_breakdown_meta_json->>'key_value',
    ''
  )), '');

  IF v_snapshot_key_type IS NOT NULL OR v_snapshot_key_value IS NOT NULL THEN
    SELECT
      key_check.ok,
      key_check.key_type,
      key_check.key_value,
      key_check.failure_reason
    INTO
      v_assert_ok,
      v_assert_key_type,
      v_assert_key_value,
      v_assert_failure_reason
    FROM public._pay_policy_x_assert_economic_key(
      p_timesheet_id => v_timesheet_id,
      p_key_type => v_snapshot_key_type,
      p_key_value => v_snapshot_key_value,
      p_context => 'POST_DRAFT_RESOLVE_FROZEN_COMPONENT_OR_BASIS_KEY',
      p_authority_scope => 'POST_DRAFT',
      p_resolution_source => 'FROZEN_COMPONENT_OR_BASIS_KEY',
      p_required => true,
      p_source_json => v_source_json
    ) AS key_check;

    IF COALESCE(v_assert_ok, false) THEN
      timesheet_id := v_timesheet_id;
      key_type := v_assert_key_type;
      key_value := v_assert_key_value;
      key_resolution_source := 'FROZEN_COMPONENT_OR_BASIS_KEY';
      key_resolution_failure_reason := NULL::text;
      RETURN NEXT;
      RETURN;
    ELSE
      v_failure_reason := COALESCE(v_failure_reason, v_assert_failure_reason);
    END IF;
  END IF;

  v_work_date_text := NULLIF(BTRIM(COALESCE(
    v_frozen_source_basis_json->>'work_date',
    v_frozen_source_basis_json->>'date',
    v_frozen_component_snapshot_json#>>'{source_basis_json,work_date}',
    v_frozen_component_snapshot_json#>>'{source_basis_json,date}',
    v_frozen_component_snapshot_json->>'work_date',
    v_frozen_component_snapshot_json->>'date',
    v_breakdown_meta_json->>'work_date',
    v_breakdown_meta_json->>'date',
    ''
  )), '');

  v_segment_id_text := NULLIF(BTRIM(COALESCE(
    v_frozen_source_basis_json->>'segment_id',
    v_frozen_component_snapshot_json#>>'{source_basis_json,segment_id}',
    v_frozen_component_snapshot_json->>'segment_id',
    v_breakdown_meta_json->>'segment_id',
    CASE
      WHEN v_source_ref IS NOT NULL AND BTRIM(v_source_ref) LIKE 'seg:%' THEN split_part(v_source_ref, ':', 2)
      ELSE NULL::text
    END,
    ''
  )), '');

  v_segment_key_text := NULLIF(BTRIM(COALESCE(
    v_frozen_source_basis_json->>'segment_key',
    v_frozen_source_basis_json->>'segment_stable_key',
    v_frozen_component_snapshot_json#>>'{source_basis_json,segment_key}',
    v_frozen_component_snapshot_json#>>'{source_basis_json,segment_stable_key}',
    v_frozen_component_snapshot_json->>'segment_key',
    v_frozen_component_snapshot_json->>'segment_stable_key',
    v_breakdown_meta_json->>'segment_key',
    v_breakdown_meta_json->>'segment_stable_key',
    v_segment_key,
    ''
  )), '');

  v_segment_stable_key_text := NULLIF(BTRIM(COALESCE(
    v_frozen_source_basis_json->>'segment_stable_key',
    v_frozen_component_snapshot_json#>>'{source_basis_json,segment_stable_key}',
    v_frozen_component_snapshot_json->>'segment_stable_key',
    v_breakdown_meta_json->>'segment_stable_key',
    ''
  )), '');

  v_ref_num_text := NULLIF(BTRIM(COALESCE(
    v_frozen_source_basis_json->>'ref_num',
    v_frozen_component_snapshot_json#>>'{source_basis_json,ref_num}',
    v_frozen_component_snapshot_json->>'ref_num',
    v_breakdown_meta_json->>'ref_num',
    ''
  )), '');

  v_adjustment_id_text := NULLIF(BTRIM(COALESCE(
    v_frozen_source_basis_json->>'adjustment_id',
    v_frozen_source_basis_json->>'adjustment_code',
    v_frozen_component_snapshot_json#>>'{source_basis_json,adjustment_id}',
    v_frozen_component_snapshot_json#>>'{source_basis_json,adjustment_code}',
    v_frozen_component_snapshot_json->>'adjustment_id',
    v_frozen_component_snapshot_json->>'adjustment_code',
    v_breakdown_meta_json->>'adjustment_id',
    v_breakdown_meta_json->>'adjustment_code',
    ''
  )), '');

  v_additional_code_text := NULLIF(BTRIM(COALESCE(
    v_frozen_source_basis_json->>'additional_code',
    v_frozen_component_snapshot_json#>>'{source_basis_json,additional_code}',
    v_frozen_component_snapshot_json->>'additional_code',
    v_breakdown_meta_json->>'additional_code',
    ''
  )), '');

  v_expense_code_text := NULLIF(BTRIM(COALESCE(
    v_frozen_source_basis_json->>'expense_code',
    v_frozen_source_basis_json->>'mileage_code',
    v_frozen_component_snapshot_json#>>'{source_basis_json,expense_code}',
    v_frozen_component_snapshot_json#>>'{source_basis_json,mileage_code}',
    v_frozen_component_snapshot_json->>'expense_code',
    v_frozen_component_snapshot_json->>'mileage_code',
    v_breakdown_meta_json->>'expense_code',
    v_breakdown_meta_json->>'mileage_code',
    ''
  )), '');

  IF v_item_type = 'SEGMENT_DELTA' AND v_work_date_text IS NOT NULL AND v_work_date_text ~ '^\d{4}-\d{2}-\d{2}$' THEN
    v_resolved_key_type := 'TS_DAY';
    v_resolved_key_value := v_work_date_text;
    v_resolved_source := 'FROZEN_SOURCE_BASIS_DATE';

  ELSIF v_item_type = 'SEGMENT_DELTA' THEN
    IF jsonb_typeof(v_target_snapshot_json->'segments') = 'array' THEN
      v_segments_json := v_target_snapshot_json->'segments';
    ELSIF jsonb_typeof(v_target_snapshot_json#>'{actual_schedule_json,segments}') = 'array' THEN
      v_segments_json := v_target_snapshot_json#>'{actual_schedule_json,segments}';
    ELSIF jsonb_typeof(v_target_snapshot_json#>'{schedule_json,segments}') = 'array' THEN
      v_segments_json := v_target_snapshot_json#>'{schedule_json,segments}';
    ELSE
      v_segments_json := '[]'::jsonb;
    END IF;

    IF jsonb_array_length(v_segments_json) > 0 THEN
      SELECT
        NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'date', segment_choice.segment_json->>'work_date', '')), ''),
        true
      INTO
        v_segment_match_date_text,
        v_segment_match_found
      FROM jsonb_array_elements(v_segments_json) AS segment_choice(segment_json)
      WHERE segment_choice.segment_json IS NOT NULL
        AND jsonb_typeof(segment_choice.segment_json) = 'object'
        AND (
          (v_work_date_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'date', segment_choice.segment_json->>'work_date', '')), '') = v_work_date_text)
          OR (v_ref_num_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'ref_num', '')), '') = v_ref_num_text)
          OR (v_segment_id_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_id', '')), '') = v_segment_id_text)
          OR (v_segment_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_key', segment_choice.segment_json->>'segment_id', '')), '') = v_segment_key_text)
          OR (v_segment_stable_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_stable_key', segment_choice.segment_json->>'segment_id', segment_choice.segment_json->>'segment_key', '')), '') = v_segment_stable_key_text)
        )
      ORDER BY
        CASE
          WHEN v_work_date_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'date', segment_choice.segment_json->>'work_date', '')), '') = v_work_date_text THEN 0
          WHEN v_ref_num_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'ref_num', '')), '') = v_ref_num_text THEN 1
          WHEN v_segment_id_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_id', '')), '') = v_segment_id_text THEN 2
          WHEN v_segment_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_key', segment_choice.segment_json->>'segment_id', '')), '') = v_segment_key_text THEN 3
          WHEN v_segment_stable_key_text IS NOT NULL AND NULLIF(BTRIM(COALESCE(segment_choice.segment_json->>'segment_stable_key', segment_choice.segment_json->>'segment_id', segment_choice.segment_json->>'segment_key', '')), '') = v_segment_stable_key_text THEN 4
          ELSE 9
        END
      LIMIT 1;

      IF COALESCE(v_segment_match_found, false)
         AND v_segment_match_date_text IS NOT NULL
         AND v_segment_match_date_text ~ '^\d{4}-\d{2}-\d{2}$' THEN
        v_resolved_key_type := 'TS_DAY';
        v_resolved_key_value := v_segment_match_date_text;
        v_resolved_source := 'FROZEN_TIMESHEET_SNAPSHOT';
      ELSIF COALESCE(v_segment_match_found, false) THEN
        v_resolved_key_type := 'TS_TOTAL';
        v_resolved_key_value := 'TOTAL';
        v_resolved_source := 'FROZEN_TIMESHEET_SNAPSHOT_TOTAL_FALLBACK';
      END IF;
    END IF;

  ELSIF v_item_type = 'ADJUSTMENT_DELTA' AND v_adjustment_id_text IS NOT NULL THEN
    v_resolved_key_type := 'ADJUSTMENT_CODE';
    v_resolved_key_value := v_adjustment_id_text;
    v_resolved_source := 'FROZEN_SOURCE_BASIS_KEY';

  ELSIF v_item_type = 'EXPENSE_DELTA' AND v_additional_code_text IS NOT NULL THEN
    v_resolved_key_type := 'ADDITIONAL_CODE';
    v_resolved_key_value := UPPER(v_additional_code_text);
    v_resolved_source := 'FROZEN_SOURCE_BASIS_KEY';

  ELSIF v_item_type IN ('EXPENSE_DELTA', 'MILEAGE_DELTA') AND v_expense_code_text IS NOT NULL THEN
    v_resolved_key_type := 'EXPENSE_CODE';
    v_resolved_key_value := UPPER(v_expense_code_text);
    v_resolved_source := 'FROZEN_SOURCE_BASIS_KEY';
  END IF;

  IF v_resolved_key_type IS NULL AND v_item_type = 'SEGMENT_DELTA' THEN
    v_failure_reason := COALESCE(v_failure_reason, 'MISSING_DETERMINISTIC_POST_DRAFT_SNAPSHOT_EVIDENCE');
    v_source_json := v_source_json || jsonb_build_object('missing_deterministic_post_draft_snapshot', true);
  END IF;

  SELECT
    key_check.ok,
    key_check.key_type,
    key_check.key_value,
    key_check.failure_reason
  INTO
    v_assert_ok,
    v_assert_key_type,
    v_assert_key_value,
    v_assert_failure_reason
  FROM public._pay_policy_x_assert_economic_key(
    p_timesheet_id => v_timesheet_id,
    p_key_type => v_resolved_key_type,
    p_key_value => v_resolved_key_value,
    p_context => 'POST_DRAFT_RESOLVE_FINAL',
    p_authority_scope => 'POST_DRAFT',
    p_resolution_source => COALESCE(v_resolved_source, 'POST_DRAFT_KEY_RESOLUTION_FAILED'),
    p_required => true,
    p_source_json => v_source_json
  ) AS key_check;

  IF COALESCE(v_assert_ok, false) THEN
    timesheet_id := v_timesheet_id;
    key_type := v_assert_key_type;
    key_value := v_assert_key_value;
    key_resolution_source := v_resolved_source;
    key_resolution_failure_reason := NULL::text;
  ELSE
    timesheet_id := v_timesheet_id;
    key_type := NULL::text;
    key_value := NULL::text;
    key_resolution_source := 'KEY_RESOLUTION_FAILED';
    key_resolution_failure_reason := COALESCE(v_failure_reason, v_assert_failure_reason, 'POST_DRAFT_KEY_RESOLUTION_FAILED');
  END IF;

  RETURN NEXT;
END;
$function$;




CREATE OR REPLACE FUNCTION public._pay_policy_x_assert_economic_key(
  p_timesheet_id uuid,
  p_key_type text,
  p_key_value text,
  p_context text DEFAULT NULL::text,
  p_authority_scope text DEFAULT NULL::text,
  p_resolution_source text DEFAULT NULL::text,
  p_required boolean DEFAULT true,
  p_source_json jsonb DEFAULT '{}'::jsonb
)
RETURNS TABLE(
  ok boolean,
  timesheet_id uuid,
  key_type text,
  key_value text,
  failure_reason text,
  failure_detail text,
  resolution_source text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_timesheet_id uuid := p_timesheet_id;
  v_key_type text := UPPER(NULLIF(BTRIM(COALESCE(p_key_type, '')), ''));
  v_key_value text := NULLIF(BTRIM(COALESCE(p_key_value, '')), '');
  v_context text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_context, '')), ''), '-', '_'));
  v_authority_scope text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_authority_scope, '')), ''), '-', '_'));
  v_resolution_source text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_resolution_source, '')), ''), '-', '_'));
  v_required boolean := COALESCE(p_required, true);
  v_source_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_source_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_source_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_failure_reason text := NULL::text;
  v_failure_detail text := NULL::text;
  v_date_text text := NULL::text;
  v_source_live_component_flag text := NULL::text;
  v_source_live_tsfin_flag text := NULL::text;
  v_source_live_truth_flag text := NULL::text;
  v_source_live_segment_flag text := NULL::text;
  v_source_missing_snapshot_flag text := NULL::text;
BEGIN
  v_source_live_component_flag := LOWER(BTRIM(COALESCE(v_source_json->>'live_component_identity_used', '')));
  v_source_live_tsfin_flag := LOWER(BTRIM(COALESCE(v_source_json->>'live_tsfin_used', v_source_json->>'live_tsfin_identity_used', '')));
  v_source_live_truth_flag := LOWER(BTRIM(COALESCE(v_source_json->>'live_truth_used', '')));
  v_source_live_segment_flag := LOWER(BTRIM(COALESCE(v_source_json->>'live_segment_identity_used', '')));
  v_source_missing_snapshot_flag := LOWER(BTRIM(COALESCE(v_source_json->>'missing_deterministic_post_draft_snapshot', v_source_json->>'missing_frozen_snapshot', '')));

  IF v_authority_scope = 'POST_DRAFT'
     AND (
       v_resolution_source = 'LIVE'
       OR v_resolution_source LIKE 'LIVE_%'
       OR v_resolution_source LIKE '%_LIVE'
       OR v_resolution_source LIKE '%_LIVE_%'
       OR v_resolution_source LIKE '%LIVE_FINANCE%'
       OR v_resolution_source LIKE '%LIVE_COMPONENT%'
       OR v_resolution_source LIKE '%LIVE_TSFIN%'
       OR v_source_live_component_flag IN ('true', 't', 'yes', '1')
       OR v_source_live_tsfin_flag IN ('true', 't', 'yes', '1')
       OR v_source_live_truth_flag IN ('true', 't', 'yes', '1')
       OR v_source_live_segment_flag IN ('true', 't', 'yes', '1')
     ) THEN
    v_failure_reason := 'POST_DRAFT_LIVE_COMPONENT_KEY_REJECTED';
    v_failure_detail := 'Post-draft economic key resolution cannot use live truth, live TSFIN, live segment identity, or live finance-component identity.';

  ELSIF v_timesheet_id IS NULL AND v_required THEN
    v_failure_reason := CASE
      WHEN v_authority_scope = 'POST_DRAFT' THEN 'POST_DRAFT_KEY_RESOLUTION_FAILED'
      ELSE 'TIMESHEET_ID_NOT_RESOLVED'
    END;
    v_failure_detail := 'timesheet_id is required for economic entitlement keyspace resolution.';

  ELSIF v_authority_scope = 'POST_DRAFT'
     AND v_required
     AND (v_key_type IS NULL OR v_key_value IS NULL)
     AND v_source_missing_snapshot_flag IN ('true', 't', 'yes', '1') THEN
    v_failure_reason := 'MISSING_DETERMINISTIC_POST_DRAFT_SNAPSHOT_EVIDENCE';
    v_failure_detail := 'Post-draft batch artefacts did not contain deterministic frozen snapshot evidence for the economic key.';

  ELSIF v_key_type IS NULL AND v_required THEN
    v_failure_reason := CASE
      WHEN v_authority_scope = 'POST_DRAFT' THEN 'POST_DRAFT_KEY_RESOLUTION_FAILED'
      ELSE 'KEY_TYPE_NOT_RESOLVED'
    END;
    v_failure_detail := 'key_type is required and was not resolved.';

  ELSIF v_key_value IS NULL AND v_required THEN
    v_failure_reason := CASE
      WHEN v_authority_scope = 'POST_DRAFT' THEN 'POST_DRAFT_KEY_RESOLUTION_FAILED'
      ELSE 'KEY_VALUE_NOT_RESOLVED'
    END;
    v_failure_detail := 'key_value is required and was not resolved.';

  ELSIF v_key_type IN (
    'SEGMENT_ID',
    'SEGMENT_KEY',
    'SEGMENT_STABLE_KEY',
    'STABLE_SEGMENT_KEY',
    'SEGMENT_STABLE_ID',
    'SEGMENT_HANDLE',
    'UI_SELECTION_ID',
    'SELECTION_ID',
    'SELECTION_HANDLE',
    'SNOOZE_ID',
    'SNOOZE_KEY',
    'PREVIEW_ROW_ID',
    'ROW_ID',
    'LINE_ID',
    'PAY_BATCH_ITEM_ID',
    'FINANCE_COMPONENT_ID',
    'COMPONENT_ID'
  ) THEN
    v_failure_reason := 'IDENTITY_HANDLE_NOT_ECONOMIC_KEY';
    v_failure_detail := 'Identity handles may locate evidence but cannot be used as entitlement buckets.';

  ELSIF v_key_type = 'TS_DAY' THEN
    IF v_key_value IS NULL THEN
      v_failure_reason := CASE
        WHEN v_authority_scope = 'POST_DRAFT' THEN 'POST_DRAFT_KEY_RESOLUTION_FAILED'
        ELSE 'KEY_VALUE_NOT_RESOLVED'
      END;
      v_failure_detail := 'TS_DAY requires a YYYY-MM-DD work-date key_value.';
    ELSIF v_key_value !~ '^\d{4}-\d{2}-\d{2}$' THEN
      v_failure_reason := CASE
        WHEN v_key_value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          OR v_key_value ~* '^(seg|segment|stable|snooze|row|selection)[:_\-]'
        THEN 'TS_DAY_KEY_VALUE_IDENTITY_HANDLE'
        ELSE 'TS_DAY_KEY_VALUE_NOT_DATE'
      END;
      v_failure_detail := 'TS_DAY must remain date-bucketed with key_value formatted as YYYY-MM-DD.';
    ELSE
      BEGIN
        v_date_text := to_char(v_key_value::date, 'YYYY-MM-DD');
        IF v_date_text IS DISTINCT FROM v_key_value THEN
          v_failure_reason := 'TS_DAY_KEY_VALUE_NOT_DATE';
          v_failure_detail := 'TS_DAY key_value is not a valid canonical YYYY-MM-DD date.';
        END IF;
      EXCEPTION
        WHEN OTHERS THEN
          v_failure_reason := 'TS_DAY_KEY_VALUE_NOT_DATE';
          v_failure_detail := 'TS_DAY key_value could not be cast to a valid date.';
      END;
    END IF;
  END IF;

  ok := v_failure_reason IS NULL;
  timesheet_id := v_timesheet_id;
  key_type := CASE WHEN v_failure_reason IS NULL THEN v_key_type ELSE NULL::text END;
  key_value := CASE WHEN v_failure_reason IS NULL THEN v_key_value ELSE NULL::text END;
  failure_reason := v_failure_reason;
  failure_detail := v_failure_detail;
  resolution_source := v_resolution_source;
  RETURN NEXT;
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_batch_display_summary_refresh(
  p_pay_batch_id uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_DISPLAY_SUMMARY_REFRESH_BATCH_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_DISPLAY_SUMMARY_REFRESH_BATCH_REQUIRED'
            )::text;
  END IF;

  INSERT INTO public.pay_batch_display_summary (
    pay_batch_id,
    batch_status,
    batch_kind,
    candidate_count,
    item_count,
    transfer_count,
    total_payable,
    total_bank_out,
    execution_commit_state,
    rail_provider_label,
    rail_env_label,
    issue_summary_counts,
    latest_operation_id,
    latest_operation_status,
    latest_operation_phase,
    display_label,
    stale_summary_json,
    freshness_validation_status,
    freshness_checked_at_utc,
    freshness_result_hash,
    summary_version,
    updated_at_utc
  )
  SELECT
    pay_batch_row.id AS pay_batch_id,
    pay_batch_row.status AS batch_status,
    pay_batch_row.batch_kind_fixed AS batch_kind,
    COALESCE(candidate_summary.candidate_count, 0) AS candidate_count,
    COALESCE(item_summary.item_count, 0) AS item_count,
    COALESCE(transfer_summary.transfer_count, 0) AS transfer_count,
    ROUND(COALESCE(item_summary.total_payable, 0), 2)::numeric(14,2) AS total_payable,
    ROUND(
      COALESCE(
        CASE
          WHEN COALESCE(transfer_summary.transfer_count, 0) > 0 THEN transfer_summary.transfer_amount_total
          ELSE pay_batch_row.total_bank_out
        END,
        0
      ),
      2
    )::numeric(14,2) AS total_bank_out,
    pay_batch_row.execution_commit_state AS execution_commit_state,
    pay_batch_row.rail_provider_snapshot AS rail_provider_label,
    pay_batch_row.rail_env_snapshot AS rail_env_label,
    jsonb_strip_nulls(
      jsonb_build_object(
        'candidate_count', COALESCE(candidate_summary.candidate_count, 0),
        'settled_candidate_count', COALESCE(candidate_summary.settled_candidate_count, 0),
        'awaiting_net_amount_count', COALESCE(candidate_summary.awaiting_net_amount_count, 0),
        'item_count', COALESCE(item_summary.item_count, 0),
        'voided_item_count', COALESCE(item_summary.voided_item_count, 0),
        'mismatch_item_count', COALESCE(item_summary.mismatch_item_count, 0),
        'transfer_count', COALESCE(transfer_summary.transfer_count, 0),
        'transfer_amount_total', ROUND(COALESCE(transfer_summary.transfer_amount_total, 0), 2),
        'failed_transfer_count', COALESCE(transfer_summary.failed_transfer_count, 0),
        'uncertain_transfer_count', COALESCE(transfer_summary.uncertain_transfer_count, 0),
        'sent_confirmed_count', COALESCE(transfer_summary.sent_confirmed_count, 0),
        'sent_confirmed_amount', ROUND(COALESCE(transfer_summary.sent_confirmed_amount, 0), 2),
        'pending_submitted_count', COALESCE(transfer_summary.pending_submitted_count, 0),
        'pending_submitted_amount', ROUND(COALESCE(transfer_summary.pending_submitted_amount, 0), 2),
        'failed_returned_count', COALESCE(transfer_summary.failed_returned_count, 0),
        'failed_returned_amount', ROUND(COALESCE(transfer_summary.failed_returned_amount, 0), 2),
        'check_required_count', COALESCE(transfer_summary.check_required_count, 0),
        'check_required_amount', ROUND(COALESCE(transfer_summary.check_required_amount, 0), 2),
        'not_sent_count', COALESCE(transfer_summary.not_sent_count, 0),
        'not_sent_amount', ROUND(COALESCE(transfer_summary.not_sent_amount, 0), 2),
        'summary_source', 'durable_refresh',
        'summary_refresh_required', false,
        'refreshed_at_utc', now()::text,
        'latest_operation_status', latest_operation.status,
        'latest_operation_type', latest_operation.operation_type,
        'batch_status_raw', pay_batch_row.status,
        'batch_status_label', CASE
          WHEN COALESCE(draft_create_failure_summary.draft_creation_failed, false) THEN 'Draft creation failed'
          ELSE public._pay_batch_status_display_label(
            pay_batch_row.status,
            COALESCE(transfer_summary.pending_bank_outcome_count, 0),
            COALESCE(transfer_summary.unknown_bank_outcome_count, 0)
          )
        END,
        'draft_creation_failed_empty_shell', COALESCE(draft_create_failure_summary.draft_creation_failed_empty_shell, false),
        'draft_creation_failed', COALESCE(draft_create_failure_summary.draft_creation_failed, false),
        'draft_creation_failed_partial', COALESCE(draft_create_failure_summary.draft_creation_failed_partial, false),
        'draft_creation_failed_has_items', COALESCE(draft_create_failure_summary.draft_creation_failed_has_items, false),
        'batch_action_blocked', COALESCE(draft_create_failure_summary.draft_creation_failed, false),
        'normal_draft_actions_blocked', COALESCE(draft_create_failure_summary.draft_creation_failed, false),
        'draft_creation_failed_operation_id', CASE
          WHEN COALESCE(draft_create_failure_summary.draft_creation_failed, false) THEN latest_operation.id::text
          ELSE NULL::text
        END,
        'draft_creation_failed_operation_phase', CASE
          WHEN COALESCE(draft_create_failure_summary.draft_creation_failed, false) THEN latest_operation.phase
          ELSE NULL::text
        END,
        'batch_terminal_with_failed_payments', UPPER(BTRIM(COALESCE(pay_batch_row.status, ''))) = 'FAILED',
        'pending_bank_outcome_count', COALESCE(transfer_summary.pending_bank_outcome_count, 0),
        'unknown_bank_outcome_count', COALESCE(transfer_summary.unknown_bank_outcome_count, 0),
        'terminal_failed_payment_count', COALESCE(transfer_summary.terminal_failed_payment_count, 0),
        'terminal_success_payment_count', COALESCE(transfer_summary.terminal_success_payment_count, 0),
        'settlement_required', (
          UPPER(BTRIM(COALESCE(pay_batch_row.status, ''))) = 'WAITING_BANK_CONFIRM'
          AND COALESCE(transfer_summary.transfer_count, 0) > 0
          AND COALESCE(transfer_summary.pending_bank_outcome_count, 0) = 0
          AND COALESCE(transfer_summary.unknown_bank_outcome_count, 0) = 0
          AND COALESCE(transfer_summary.not_sent_count, 0) = 0
          AND (COALESCE(transfer_summary.terminal_success_payment_count, 0) + COALESCE(transfer_summary.terminal_failed_payment_count, 0)) > 0
        ),
        'settlement_nudge_recommended', (
          UPPER(BTRIM(COALESCE(pay_batch_row.status, ''))) = 'WAITING_BANK_CONFIRM'
          AND COALESCE(transfer_summary.transfer_count, 0) > 0
          AND COALESCE(transfer_summary.pending_bank_outcome_count, 0) = 0
          AND COALESCE(transfer_summary.unknown_bank_outcome_count, 0) = 0
          AND COALESCE(transfer_summary.not_sent_count, 0) = 0
          AND (COALESCE(transfer_summary.terminal_success_payment_count, 0) + COALESCE(transfer_summary.terminal_failed_payment_count, 0)) > 0
        )
      )
    ) AS issue_summary_counts,
    latest_operation.id AS latest_operation_id,
    latest_operation.status AS latest_operation_status,
    latest_operation.phase AS latest_operation_phase,
    NULLIF(
      BTRIM(
        CONCAT_WS(
          ' · ',
          NULLIF(BTRIM(COALESCE(pay_batch_row.batch_kind_fixed, '')), ''),
          NULLIF(BTRIM(COALESCE(CASE
            WHEN COALESCE(draft_create_failure_summary.draft_creation_failed, false) THEN 'Draft creation failed'
            ELSE public._pay_batch_status_display_label(
              pay_batch_row.status,
              COALESCE(transfer_summary.pending_bank_outcome_count, 0),
              COALESCE(transfer_summary.unknown_bank_outcome_count, 0)
            )
          END, '')), ''),
          CASE WHEN pay_batch_row.pay_date IS NULL THEN NULL::text ELSE pay_batch_row.pay_date::text END
        )
      ),
      ''
    ) AS display_label,
    jsonb_strip_nulls(
      jsonb_build_object(
        'freshness_validation_status', pay_batch_row.freshness_validation_status,
        'freshness_checked_at_utc', CASE WHEN pay_batch_row.freshness_checked_at_utc IS NULL THEN NULL::text ELSE pay_batch_row.freshness_checked_at_utc::text END,
        'freshness_result_hash', pay_batch_row.freshness_result_hash,
        'freshness_scope_hash', pay_batch_row.freshness_scope_hash,
        'summary_refresh_required', false
      )
    ) AS stale_summary_json,
    pay_batch_row.freshness_validation_status AS freshness_validation_status,
    pay_batch_row.freshness_checked_at_utc AS freshness_checked_at_utc,
    pay_batch_row.freshness_result_hash AS freshness_result_hash,
    1 AS summary_version,
    now() AS updated_at_utc
  FROM public.pay_batches AS pay_batch_row
  LEFT JOIN LATERAL (
    SELECT
      COUNT(*)::integer AS candidate_count,
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(candidate_row.settlement_status, ''))) = 'SETTLED'
           OR candidate_row.settled_at_utc IS NOT NULL
      )::integer AS settled_candidate_count,
      COUNT(*) FILTER (
        WHERE COALESCE(candidate_row.awaiting_net_amount, false) = true
      )::integer AS awaiting_net_amount_count
    FROM public.pay_batch_candidates AS candidate_row
    WHERE candidate_row.pay_batch_id = pay_batch_row.id
  ) AS candidate_summary ON true
  LEFT JOIN LATERAL (
    SELECT
      COUNT(*) FILTER (WHERE COALESCE(item_row.is_voided, false) = false)::integer AS item_count,
      COUNT(*) FILTER (WHERE COALESCE(item_row.is_voided, false) = true)::integer AS voided_item_count,
      COUNT(*) FILTER (WHERE COALESCE(item_row.is_mismatch, false) = true)::integer AS mismatch_item_count,
      ROUND(
        COALESCE(
          SUM(
            COALESCE(
              item_row.frozen_target_amount_inc_vat,
              item_row.amount_inc_vat,
              item_row.frozen_target_amount_ex_vat,
              item_row.amount_ex_vat,
              0
            )
          ) FILTER (WHERE COALESCE(item_row.is_voided, false) = false),
          0
        ),
        2
      )::numeric AS total_payable
    FROM public.pay_batch_candidates AS candidate_for_item
    JOIN public.pay_batch_items AS item_row
      ON item_row.pay_batch_candidate_id = candidate_for_item.id
    WHERE candidate_for_item.pay_batch_id = pay_batch_row.id
  ) AS item_summary ON true
  LEFT JOIN LATERAL (
    SELECT
      COUNT(*)::integer AS transfer_count,
      ROUND(COALESCE(SUM(transfer_class.amount), 0), 2)::numeric AS transfer_amount_total,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'FAILED_RETURNED')::integer AS failed_transfer_count,
      COUNT(*) FILTER (WHERE transfer_class.bucket IN ('PENDING_SUBMITTED','CHECK_REQUIRED'))::integer AS uncertain_transfer_count,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'SENT_CONFIRMED')::integer AS sent_confirmed_count,
      ROUND(COALESCE(SUM(transfer_class.amount) FILTER (WHERE transfer_class.bucket = 'SENT_CONFIRMED'), 0), 2)::numeric AS sent_confirmed_amount,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'PENDING_SUBMITTED')::integer AS pending_submitted_count,
      ROUND(COALESCE(SUM(transfer_class.amount) FILTER (WHERE transfer_class.bucket = 'PENDING_SUBMITTED'), 0), 2)::numeric AS pending_submitted_amount,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'FAILED_RETURNED')::integer AS failed_returned_count,
      ROUND(COALESCE(SUM(transfer_class.amount) FILTER (WHERE transfer_class.bucket = 'FAILED_RETURNED'), 0), 2)::numeric AS failed_returned_amount,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'CHECK_REQUIRED')::integer AS check_required_count,
      ROUND(COALESCE(SUM(transfer_class.amount) FILTER (WHERE transfer_class.bucket = 'CHECK_REQUIRED'), 0), 2)::numeric AS check_required_amount,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'NOT_SENT')::integer AS not_sent_count,
      ROUND(COALESCE(SUM(transfer_class.amount) FILTER (WHERE transfer_class.bucket = 'NOT_SENT'), 0), 2)::numeric AS not_sent_amount,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'PENDING_SUBMITTED')::integer AS pending_bank_outcome_count,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'CHECK_REQUIRED')::integer AS unknown_bank_outcome_count,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'FAILED_RETURNED')::integer AS terminal_failed_payment_count,
      COUNT(*) FILTER (WHERE transfer_class.bucket = 'SENT_CONFIRMED')::integer AS terminal_success_payment_count
    FROM (
      SELECT
        transfer_row.amount,
        CASE
          WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('COMPLETED','SETTLED','PAID','COMMITTED','EXECUTED')
            OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('COMPLETED','SETTLED','PAID','COMMITTED','EXECUTED','BANK_CONFIRMED','MANUAL_CONFIRM')
            OR transfer_row.completed_at_utc IS NOT NULL
            THEN 'SENT_CONFIRMED'
          WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','CANCELLED','CANCELED')
            THEN 'FAILED_RETURNED'
          WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('UNKNOWN','UNCERTAIN','REVIEW_REQUIRED')
            OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('UNKNOWN','UNCERTAIN','REVIEW_REQUIRED')
            THEN 'CHECK_REQUIRED'
          WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('PENDING','SUBMITTED','PROCESSING','IN_FLIGHT','WAITING_BANK_CONFIRM')
            OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('PENDING','SUBMITTED','PROCESSING','IN_FLIGHT','ACCEPTED','PENDING_SETTLEMENT','PENDING_CONFIRMATION')
            OR NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '') IS NOT NULL
            OR UPPER(BTRIM(COALESCE(
              transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}',
              transfer_row.rail_meta_json #>> '{providerSubmitDiagnostic,providerSubmissionStatus}',
              transfer_row.rail_meta_json->>'provider_submission_status',
              ''
            ))) IN ('PROVIDER_SUBMISSION_ACCEPTED','ACCEPTED','SUBMITTED','PROVIDER_SUBMITTED')
            THEN 'PENDING_SUBMITTED'
          ELSE 'NOT_SENT'
        END AS bucket
      FROM public.pay_bank_transfers AS transfer_row
      WHERE transfer_row.pay_batch_id = pay_batch_row.id
    ) AS transfer_class
  ) AS transfer_summary ON true
  LEFT JOIN LATERAL (
    SELECT
      operation_row.id,
      operation_row.operation_type,
      operation_row.status,
      operation_row.phase
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.pay_batch_id = pay_batch_row.id
       OR EXISTS (
         SELECT 1
         FROM public.banking_pay_operation_candidate_scope AS operation_scope
         WHERE operation_scope.operation_id = operation_row.id
           AND operation_scope.pay_batch_id = pay_batch_row.id
       )
    ORDER BY operation_row.updated_at_utc DESC NULLS LAST,
             operation_row.created_at_utc DESC NULLS LAST,
             operation_row.id DESC
    LIMIT 1
  ) AS latest_operation ON true
  LEFT JOIN LATERAL (
    SELECT
      (
        UPPER(BTRIM(COALESCE(latest_operation.operation_type, ''))) = 'DRAFT_CREATE'
        AND UPPER(BTRIM(COALESCE(latest_operation.status, ''))) IN ('FAILED', 'ERROR', 'REVIEW_REQUIRED', 'NEEDS_REVIEW', 'REVIEW')
        AND UPPER(BTRIM(COALESCE(latest_operation.phase, ''))) NOT IN ('COMPLETE', 'COMPLETED', 'SUCCESS', 'SUCCEEDED', 'DONE')
        AND pay_batch_row.source_workbench_session_id IS NOT NULL
        AND UPPER(BTRIM(COALESCE(pay_batch_row.status, ''))) IN ('DRAFT', 'CANCELLED', 'CANCELED')
        AND (
          NULLIF(BTRIM(COALESCE(pay_batch_row.execution_commit_state, '')), '') IS NULL
          OR UPPER(BTRIM(COALESCE(pay_batch_row.execution_commit_state, ''))) = 'NOT_SUBMITTED'
        )
      ) AS draft_creation_failed,
      (
        UPPER(BTRIM(COALESCE(latest_operation.operation_type, ''))) = 'DRAFT_CREATE'
        AND UPPER(BTRIM(COALESCE(latest_operation.status, ''))) IN ('FAILED', 'ERROR', 'REVIEW_REQUIRED', 'NEEDS_REVIEW', 'REVIEW')
        AND UPPER(BTRIM(COALESCE(latest_operation.phase, ''))) NOT IN ('COMPLETE', 'COMPLETED', 'SUCCESS', 'SUCCEEDED', 'DONE')
        AND pay_batch_row.source_workbench_session_id IS NOT NULL
        AND UPPER(BTRIM(COALESCE(pay_batch_row.status, ''))) IN ('DRAFT', 'CANCELLED', 'CANCELED')
        AND (
          NULLIF(BTRIM(COALESCE(pay_batch_row.execution_commit_state, '')), '') IS NULL
          OR UPPER(BTRIM(COALESCE(pay_batch_row.execution_commit_state, ''))) = 'NOT_SUBMITTED'
        )
        AND COALESCE(candidate_summary.candidate_count, 0) = 0
        AND COALESCE(item_summary.item_count, 0) = 0
        AND COALESCE(item_summary.voided_item_count, 0) = 0
      ) AS draft_creation_failed_empty_shell,
      (
        UPPER(BTRIM(COALESCE(latest_operation.operation_type, ''))) = 'DRAFT_CREATE'
        AND UPPER(BTRIM(COALESCE(latest_operation.status, ''))) IN ('FAILED', 'ERROR', 'REVIEW_REQUIRED', 'NEEDS_REVIEW', 'REVIEW')
        AND UPPER(BTRIM(COALESCE(latest_operation.phase, ''))) NOT IN ('COMPLETE', 'COMPLETED', 'SUCCESS', 'SUCCEEDED', 'DONE')
        AND pay_batch_row.source_workbench_session_id IS NOT NULL
        AND UPPER(BTRIM(COALESCE(pay_batch_row.status, ''))) IN ('DRAFT', 'CANCELLED', 'CANCELED')
        AND (
          NULLIF(BTRIM(COALESCE(pay_batch_row.execution_commit_state, '')), '') IS NULL
          OR UPPER(BTRIM(COALESCE(pay_batch_row.execution_commit_state, ''))) = 'NOT_SUBMITTED'
        )
        AND (
          COALESCE(candidate_summary.candidate_count, 0) > 0
          OR COALESCE(item_summary.item_count, 0) > 0
          OR COALESCE(item_summary.voided_item_count, 0) > 0
        )
      ) AS draft_creation_failed_partial,
      (
        COALESCE(item_summary.item_count, 0) > 0
        OR COALESCE(item_summary.voided_item_count, 0) > 0
      ) AS draft_creation_failed_has_items
  ) AS draft_create_failure_summary ON true
  WHERE pay_batch_row.id = p_pay_batch_id
  ON CONFLICT (pay_batch_id) DO UPDATE
  SET
    batch_status = EXCLUDED.batch_status,
    batch_kind = EXCLUDED.batch_kind,
    candidate_count = EXCLUDED.candidate_count,
    item_count = EXCLUDED.item_count,
    transfer_count = EXCLUDED.transfer_count,
    total_payable = EXCLUDED.total_payable,
    total_bank_out = EXCLUDED.total_bank_out,
    execution_commit_state = EXCLUDED.execution_commit_state,
    rail_provider_label = EXCLUDED.rail_provider_label,
    rail_env_label = EXCLUDED.rail_env_label,
    issue_summary_counts = EXCLUDED.issue_summary_counts,
    latest_operation_id = EXCLUDED.latest_operation_id,
    latest_operation_status = EXCLUDED.latest_operation_status,
    latest_operation_phase = EXCLUDED.latest_operation_phase,
    display_label = EXCLUDED.display_label,
    stale_summary_json = EXCLUDED.stale_summary_json,
    freshness_validation_status = EXCLUDED.freshness_validation_status,
    freshness_checked_at_utc = EXCLUDED.freshness_checked_at_utc,
    freshness_result_hash = EXCLUDED.freshness_result_hash,
    summary_version = COALESCE(pay_batch_display_summary.summary_version, 0) + 1,
    updated_at_utc = now();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_DISPLAY_SUMMARY_REFRESH_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_DISPLAY_SUMMARY_REFRESH_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  INSERT INTO public.banking_pay_batch_change_signals (
    pay_batch_id,
    version,
    payment_status_version,
    correction_progress_version,
    alert_version,
    overview_version,
    last_changed_at_utc,
    last_payment_status_changed_at_utc,
    last_correction_progress_changed_at_utc,
    last_alert_changed_at_utc,
    last_change_reason,
    last_change_source,
    last_change_scope_json,
    last_changed_transfer_ids,
    last_changed_candidate_ids,
    last_changed_pay_batch_item_ids,
    updated_at_utc
  )
  VALUES (
    p_pay_batch_id,
    1,
    1,
    0,
    0,
    1,
    now(),
    now(),
    NULL::timestamptz,
    NULL::timestamptz,
    'DISPLAY_SUMMARY_REFRESH',
    'pay_batch_display_summary_refresh',
    jsonb_build_object(
      'summary_source', 'durable_refresh',
      'summary_refresh_required', false,
      'changed_areas', jsonb_build_array('overview', 'payment_status')
    ),
    '[]'::jsonb,
    '[]'::jsonb,
    '[]'::jsonb,
    now()
  )
  ON CONFLICT (pay_batch_id) DO UPDATE
  SET
    version = COALESCE(banking_pay_batch_change_signals.version, 0) + 1,
    payment_status_version = COALESCE(banking_pay_batch_change_signals.payment_status_version, 0) + 1,
    overview_version = COALESCE(banking_pay_batch_change_signals.overview_version, 0) + 1,
    last_changed_at_utc = now(),
    last_payment_status_changed_at_utc = now(),
    last_change_reason = 'DISPLAY_SUMMARY_REFRESH',
    last_change_source = 'pay_batch_display_summary_refresh',
    last_change_scope_json = COALESCE(banking_pay_batch_change_signals.last_change_scope_json, '{}'::jsonb) || jsonb_build_object(
      'summary_source', 'durable_refresh',
      'summary_refresh_required', false,
      'changed_areas', jsonb_build_array('overview', 'payment_status')
    ),
    updated_at_utc = now();
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_batch_display_summary_touch(
  p_pay_batch_id uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_DISPLAY_SUMMARY_TOUCH_BATCH_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_DISPLAY_SUMMARY_TOUCH_BATCH_REQUIRED'
            )::text;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.pay_batches AS pay_batch_row
    WHERE pay_batch_row.id = p_pay_batch_id
  ) THEN
    RAISE EXCEPTION 'PAY_BATCH_DISPLAY_SUMMARY_TOUCH_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_DISPLAY_SUMMARY_TOUCH_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  INSERT INTO public.pay_batch_display_summary (
    pay_batch_id,
    issue_summary_counts,
    stale_summary_json,
    summary_version,
    updated_at_utc
  )
  VALUES (
    p_pay_batch_id,
    '{}'::jsonb,
    jsonb_build_object(
      'summary_refresh_required', true,
      'touched_at_utc', now()::text
    ),
    1,
    now()
  )
  ON CONFLICT (pay_batch_id) DO UPDATE
  SET
    stale_summary_json = COALESCE(pay_batch_display_summary.stale_summary_json, '{}'::jsonb) || jsonb_build_object(
      'summary_refresh_required', true,
      'touched_at_utc', now()::text
    ),
    summary_version = COALESCE(pay_batch_display_summary.summary_version, 0) + 1,
    updated_at_utc = now();
END;
$function$;


CREATE OR REPLACE FUNCTION public.banking_alert_display_summary_refresh_for_user(
  p_actor_user_id uuid,
  p_context text DEFAULT 'EXPLICIT_ALERT_REFRESH'::text
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_context text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_context, 'EXPLICIT_ALERT_REFRESH')), ''), '-', '_'));
  v_active_json jsonb := '{}'::jsonb;
  v_alert_hash text := NULL::text;
  v_summary_hash text := NULL::text;
  v_unacknowledged_count integer := 0;
  v_highest_severity text := NULL::text;
  v_highest_label text := NULL::text;
BEGIN
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_DISPLAY_SUMMARY_REFRESH_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_ALERT_DISPLAY_SUMMARY_REFRESH_ACTOR_REQUIRED'
            )::text;
  END IF;

  IF v_context IN (
    'BATCH_LIST',
    'PAY_BATCH_LIST',
    'LIST',
    'BOOTSTRAP',
    'BATCH_BOOTSTRAP',
    'PAY_BATCH_BOOTSTRAP',
    'DISPLAY',
    'BATCH_OPEN',
    'MODAL_OPEN',
    'PAY_BATCH_GET',
    'PAY_BATCH_GET_BOOTSTRAP_ONLY',
    'SECTION_PAGE',
    'OVERVIEW',
    'OVERVIEW_PAGE',
    'OPERATION_PROGRESS',
    'PREVIEW_PROGRESS',
    'WATCH_SIGNAL',
    'LIVE_WATCH',
    'RPC_CHANGES_PING',
    'CHANGES_PING'
  ) THEN
    RAISE EXCEPTION 'BANKING_ALERT_DISPLAY_SUMMARY_REFRESH_CONTEXT_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_ALERT_DISPLAY_SUMMARY_REFRESH_CONTEXT_NOT_ALLOWED',
              'context', v_context
            )::text;
  END IF;

  PERFORM public.banking_pay_hot_path_budget_apply(
    CASE WHEN v_context = 'ALERT_REFRESH_JOB' THEN 'ALERT_REFRESH_JOB' ELSE 'EXPLICIT_DIAGNOSTIC' END
  );

  v_active_json := public.banking_alerts_active_for_user(
    p_actor_user_id,
    NULL::text,
    NULL::uuid,
    false,
    100,
    v_context
  );

  v_alert_hash := COALESCE(
    NULLIF(BTRIM(COALESCE(v_active_json ->> 'banking_alert_hash', '')), ''),
    'banking_alert_signal:v3:' || MD5('')
  );

  v_summary_hash := COALESCE(
    NULLIF(BTRIM(COALESCE(v_active_json ->> 'banking_alert_summary_signature', '')), ''),
    'banking_alert_summary:v3:' || MD5('')
  );

  BEGIN
    v_unacknowledged_count := COALESCE((v_active_json ->> 'banking_unacknowledged_alert_count')::integer, 0);
  EXCEPTION
    WHEN OTHERS THEN
      v_unacknowledged_count := 0;
  END;

  v_highest_severity := NULLIF(BTRIM(COALESCE(v_active_json ->> 'banking_highest_alert_severity', v_active_json ->> 'highest_severity', '')), '');
  v_highest_label := NULLIF(BTRIM(COALESCE(v_active_json ->> 'banking_highest_alert_label', v_active_json ->> 'highest_label', '')), '');

  INSERT INTO public.banking_alert_display_summary (
    actor_user_id,
    alert_hash,
    summary_hash,
    unacknowledged_count,
    highest_severity,
    highest_label,
    summary_json,
    updated_at_utc
  )
  VALUES (
    p_actor_user_id,
    v_alert_hash,
    v_summary_hash,
    v_unacknowledged_count,
    v_highest_severity,
    v_highest_label,
    jsonb_strip_nulls(
      jsonb_build_object(
        'ok', true,
        'context', v_context,
        'generated_at_utc', now()::text,
        'banking_alert_hash', v_alert_hash,
        'banking_alert_summary_signature', v_summary_hash,
        'banking_unacknowledged_alert_count', v_unacknowledged_count,
        'banking_highest_alert_severity', v_highest_severity,
        'banking_highest_alert_label', v_highest_label
      )
    ),
    now()
  )
  ON CONFLICT (actor_user_id) DO UPDATE
  SET
    alert_hash = EXCLUDED.alert_hash,
    summary_hash = EXCLUDED.summary_hash,
    unacknowledged_count = EXCLUDED.unacknowledged_count,
    highest_severity = EXCLUDED.highest_severity,
    highest_label = EXCLUDED.highest_label,
    summary_json = EXCLUDED.summary_json,
    updated_at_utc = now();
END;
$function$;



CREATE OR REPLACE FUNCTION public.banking_pay_hot_path_budget_apply(
  p_route_class text DEFAULT 'DISPLAY'::text
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_route_class text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_route_class, 'DISPLAY')), ''), '-', '_'));
BEGIN
  IF v_route_class IN (
    'DISPLAY',
    'LIST',
    'BATCH_LIST',
    'BOOTSTRAP',
    'BATCH_BOOTSTRAP',
    'PROGRESS',
    'OPERATION_PROGRESS',
    'PREVIEW_PROGRESS',
    'WATCH',
    'WATCH_SIGNAL',
    'OVERVIEW',
    'OVERVIEW_PAGE',
    'RPC_CHANGES_PING',
    'CHANGES_PING'
  ) THEN
    PERFORM set_config('statement_timeout', '3000', true);
    PERFORM set_config('lock_timeout', '750', true);
    PERFORM set_config('idle_in_transaction_session_timeout', '10000', true);

  ELSIF v_route_class IN (
    'PREVIEW_CHUNK',
    'WORKBENCH_CHUNK',
    'EXECUTION_CHUNK',
    'WORKER_CHUNK',
    'PROVIDER_CHUNK',
    'OPERATION_WORKER',
    'OPERATION_ADVANCE',
    'TRANSFER_SCOPE_CHUNK',
    'FRESHNESS_CHUNK'
  ) THEN
    PERFORM set_config('statement_timeout', '15000', true);
    PERFORM set_config('lock_timeout', '1500', true);
    PERFORM set_config('idle_in_transaction_session_timeout', '30000', true);

  ELSIF v_route_class IN (
    'DIAGNOSTIC',
    'EXPLICIT_DIAGNOSTIC',
    'ALERT_PANEL',
    'ALERT_REFRESH_JOB',
    'EXPORT',
    'ADMIN'
  ) THEN
    PERFORM set_config('statement_timeout', '30000', true);
    PERFORM set_config('lock_timeout', '3000', true);
    PERFORM set_config('idle_in_transaction_session_timeout', '60000', true);

  ELSE
    PERFORM set_config('statement_timeout', '5000', true);
    PERFORM set_config('lock_timeout', '1000', true);
    PERFORM set_config('idle_in_transaction_session_timeout', '15000', true);
  END IF;
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_workbench_mark_contract_client_dirty()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_trigger_table text := lower(TG_TABLE_NAME);
  v_new_row jsonb := '{}'::jsonb;
  v_old_row jsonb := '{}'::jsonb;
  v_contract_id_old uuid := NULL::uuid;
  v_contract_id_new uuid := NULL::uuid;
  v_client_id_old uuid := NULL::uuid;
  v_client_id_new uuid := NULL::uuid;
  v_candidate_id_old uuid := NULL::uuid;
  v_candidate_id_new uuid := NULL::uuid;
  v_row_id_old uuid := NULL::uuid;
  v_row_id_new uuid := NULL::uuid;
  v_scope record;
  v_dedupe_key text;
  v_payload_json jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF TG_OP <> 'DELETE' THEN
    v_new_row := to_jsonb(NEW);
  END IF;

  IF TG_OP <> 'INSERT' THEN
    v_old_row := to_jsonb(OLD);
  END IF;

  IF v_trigger_table = 'contracts' THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_contract_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_contract_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'client_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_client_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'client_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'client_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_client_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'client_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_candidate_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_candidate_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '')::uuid; END IF;
    v_row_id_old := v_contract_id_old;
    v_row_id_new := v_contract_id_new;
  ELSIF v_trigger_table = 'client_settings' THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'client_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_client_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'client_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'client_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_client_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'client_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_row_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_row_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid; END IF;
  ELSE
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'contract_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_contract_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'contract_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'contract_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_contract_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'contract_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'client_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_client_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'client_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'client_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_client_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'client_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_candidate_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_candidate_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_row_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_row_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid; END IF;
  END IF;

  FOR v_scope IN
    WITH scope_rows AS (
      SELECT 'CONTRACT'::text AS scope_kind, v_contract_id_old AS scope_id, v_contract_id_old AS contract_id, v_client_id_old AS client_id, v_candidate_id_old AS candidate_id, v_row_id_old AS row_id
      UNION ALL
      SELECT 'CONTRACT'::text AS scope_kind, v_contract_id_new AS scope_id, v_contract_id_new AS contract_id, v_client_id_new AS client_id, v_candidate_id_new AS candidate_id, v_row_id_new AS row_id
      UNION ALL
      SELECT 'CLIENT'::text AS scope_kind, v_client_id_old AS scope_id, NULL::uuid AS contract_id, v_client_id_old AS client_id, v_candidate_id_old AS candidate_id, v_row_id_old AS row_id
      UNION ALL
      SELECT 'CLIENT'::text AS scope_kind, v_client_id_new AS scope_id, NULL::uuid AS contract_id, v_client_id_new AS client_id, v_candidate_id_new AS candidate_id, v_row_id_new AS row_id
    )
    SELECT DISTINCT scope_rows.scope_kind, scope_rows.scope_id, scope_rows.contract_id, scope_rows.client_id, scope_rows.candidate_id, scope_rows.row_id
    FROM scope_rows
    WHERE scope_rows.scope_id IS NOT NULL
    ORDER BY scope_rows.scope_kind, scope_rows.scope_id
  LOOP
    v_dedupe_key := 'CONTRACT_CLIENT_DIRTY_FANOUT:' || v_scope.scope_kind || ':' || v_scope.scope_id::text;
    v_payload_json := jsonb_build_object(
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'scope_kind', v_scope.scope_kind,
      'scope_id', v_scope.scope_id::text,
      'contract_id', CASE WHEN v_scope.contract_id IS NULL THEN NULL ELSE v_scope.contract_id::text END,
      'client_id', CASE WHEN v_scope.client_id IS NULL THEN NULL ELSE v_scope.client_id::text END,
      'candidate_id', CASE WHEN v_scope.candidate_id IS NULL THEN NULL ELSE v_scope.candidate_id::text END,
      'row_id', CASE WHEN v_scope.row_id IS NULL THEN NULL ELSE v_scope.row_id::text END,
      'reason', 'DIRTY_TRIGGER:' || upper(v_trigger_table) || ':' || TG_OP,
      'page_limit', 100,
      'row_backed_scope_required', true
    );

    INSERT INTO public.banking_pay_workbench_jobs (
      job_type,
      status,
      priority,
      run_at_utc,
      attempt_count,
      max_attempts,
      dedupe_key,
      snapshot_run_id,
      session_id,
      candidate_id,
      payload_json,
      created_at_utc,
      updated_at_utc,
      started_at_utc,
      completed_at_utc,
      failed_at_utc,
      last_error_json
    )
    VALUES (
      'CONTRACT_CLIENT_DIRTY_FANOUT',
      'QUEUED',
      200,
      v_now,
      0,
      8,
      v_dedupe_key,
      NULL,
      NULL,
      NULL,
      v_payload_json,
      v_now,
      v_now,
      NULL,
      NULL,
      NULL,
      NULL
    )
    ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
    DO UPDATE
    SET priority = LEAST(public.banking_pay_workbench_jobs.priority, EXCLUDED.priority),
        run_at_utc = LEAST(public.banking_pay_workbench_jobs.run_at_utc, EXCLUDED.run_at_utc),
        payload_json = COALESCE(public.banking_pay_workbench_jobs.payload_json, '{}'::jsonb) || COALESCE(EXCLUDED.payload_json, '{}'::jsonb),
        updated_at_utc = v_now;
  END LOOP;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_workbench_candidate_line_work_seed(
  p_session_id uuid,
  p_candidate_id uuid,
  p_cursor_json jsonb DEFAULT NULL::jsonb,
  p_limit integer DEFAULT 100
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_context_json jsonb := '{}'::jsonb;
  v_seed_result jsonb := '{}'::jsonb;
  v_scope_status text := NULL::text;
  v_seeded_count integer := 0;
  v_error_count integer := 0;
  v_new_pending_count integer := 0;
  v_new_error_count integer := 0;
  v_has_more boolean := false;
  v_next_cursor jsonb := NULL::jsonb;
  v_next_scope_status text := 'MATERIALISED';
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SESSION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SESSION_ID_REQUIRED')::text;
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CANDIDATE_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CANDIDATE_ID_REQUIRED')::text;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SESSION_NOT_FOUND',
              'session_id', p_session_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_SESSION_NOT_OPEN',
              'session_id', p_session_id::text,
              'status', v_session_row.status
            )::text;
  END IF;

  SELECT scope_row.status
  INTO v_scope_status
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = p_candidate_id
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CANDIDATE_NOT_IN_SCOPE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_SEED_CANDIDATE_NOT_IN_SCOPE',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text
            )::text;
  END IF;

  v_context_json := public.pay_preview_build_context(
    p_pay_date => v_session_row.pay_date,
    p_week_ending_cutoff => v_session_row.week_ending_cutoff,
    p_actor_user_id => v_session_row.actor_user_id,
    p_candidate_id => p_candidate_id,
    p_client_id => NULL::uuid,
    p_preview_decisions_json => COALESCE(v_session_row.filters_json, '{}'::jsonb)
      || jsonb_build_object(
        'preview_context_mode', 'PAGE',
        'workbench_line_source_mode', 'CLASSIFY_ONLY',
        'line_source_mode', 'CLASSIFY_ONLY'
      )
  );

  v_seed_result := public.pay_workbench_seed_candidate_preview_line_source(
    p_session_id => p_session_id,
    p_candidate_id => p_candidate_id,
    p_context_json => v_context_json,
    p_cursor_json => p_cursor_json,
    p_limit => v_limit
  );

  v_seeded_count := COALESCE(NULLIF(BTRIM(COALESCE(
    v_seed_result->>'line_work_seeded_count',
    v_seed_result->>'seeded_count',
    v_seed_result->>'page_count',
    ''
  )), '')::integer, 0);
  v_error_count := COALESCE(NULLIF(BTRIM(COALESCE(
    v_seed_result->>'line_work_error_count',
    v_seed_result->>'error_count',
    ''
  )), '')::integer, 0);
  v_new_pending_count := COALESCE(NULLIF(BTRIM(COALESCE(v_seed_result->>'new_pending_count', '')), '')::integer, 0);
  v_new_error_count := COALESCE(NULLIF(BTRIM(COALESCE(v_seed_result->>'new_error_count', '')), '')::integer, 0);
  v_has_more := COALESCE(NULLIF(BTRIM(COALESCE(v_seed_result->>'has_more', '')), '')::boolean, false);
  v_next_cursor := COALESCE(v_seed_result->'next_cursor', NULL::jsonb);

  v_next_scope_status := CASE
    WHEN COALESCE(v_error_count, 0) > 0 THEN 'ERROR'
    WHEN COALESCE(v_seeded_count, 0) > 0 OR COALESCE(v_has_more, false) THEN 'LINE_WORK_PENDING'
    ELSE 'MATERIALISED'
  END;

  UPDATE public.banking_pay_workbench_session_scope AS scope_update
  SET status = v_next_scope_status,
      dirty = v_next_scope_status NOT IN ('MATERIALISED', 'MATERIALIZED', 'READY'),
      error_json = CASE
        WHEN COALESCE(v_error_count, 0) > 0 THEN jsonb_build_object(
          'code', 'LINE_WORK_SEED_ERRORS',
          'error_count', v_error_count,
          'seed_result', COALESCE(v_seed_result, '{}'::jsonb)
        )
        ELSE NULL::jsonb
      END,
      updated_at_utc = v_now
  WHERE scope_update.session_id = p_session_id
    AND scope_update.candidate_id = p_candidate_id;

  UPDATE public.banking_pay_workbench_sessions AS session_update
  SET line_units_total = GREATEST(
        COALESCE(session_update.line_units_total, 0)
        + COALESCE(v_new_pending_count, 0)
        + COALESCE(v_new_error_count, 0),
        0
      ),
      line_units_pending = GREATEST(
        COALESCE(session_update.line_units_pending, 0)
        + COALESCE(v_new_pending_count, 0),
        0
      ),
      line_units_failed = GREATEST(
        COALESCE(session_update.line_units_failed, 0)
        + COALESCE(v_new_error_count, 0),
        0
      ),
      progress_state = CASE
        WHEN COALESCE(v_error_count, 0) > 0 THEN 'ERROR'
        WHEN COALESCE(v_seeded_count, 0) > 0 OR COALESCE(v_has_more, false) THEN 'LINE_WORK_SEEDED'
        ELSE COALESCE(NULLIF(BTRIM(session_update.progress_state), ''), 'PENDING')
      END,
      progress_json = COALESCE(session_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'phase', 'CLASSIFIED_LINE_WORK_SEEDED',
          'last_line_seeded_count', COALESCE(v_seeded_count, 0),
          'last_line_seed_error_count', COALESCE(v_error_count, 0),
          'last_line_seed_has_more', COALESCE(v_has_more, false),
          'last_line_seeded_at_utc', v_now::text
        ),
      progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
      progress_updated_at_utc = v_now,
      updated_at_utc = v_now
  WHERE session_update.id = p_session_id;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'candidate_state', COALESCE(v_scope_status, 'PENDING'),
    'limit', v_limit,
    'seeded_count', COALESCE(v_seeded_count, 0),
    'error_count', COALESCE(v_error_count, 0),
    'total_estimate', NULL::integer,
    'count_unknown', true,
    'next_cursor', v_next_cursor
  )
  || jsonb_build_object(
    'has_more', COALESCE(v_has_more, false),
    'pending', COALESCE(v_has_more, false) OR COALESCE(v_seeded_count, 0) > 0,
    'ready', COALESCE(v_has_more, false) IS NOT TRUE AND COALESCE(v_error_count, 0) = 0,
    'scope_status', v_next_scope_status,
    'line_work_state', jsonb_build_object(
      'seeded_count', COALESCE(v_seeded_count, 0),
      'error_count', COALESCE(v_error_count, 0),
      'new_pending_count', COALESCE(v_new_pending_count, 0),
      'new_error_count', COALESCE(v_new_error_count, 0),
      'source', 'CLASSIFIED_PREVIEW_LINES',
      'count_unknown', true
    ),
    'seed_result', COALESCE(v_seed_result, '{}'::jsonb)
  );
END;
$function$;





CREATE OR REPLACE FUNCTION public.pay_workbench_session_seed_scope_chunk(
  p_session_id uuid,
  p_cursor_json jsonb DEFAULT NULL::jsonb,
  p_limit integer DEFAULT 100
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_effective_cursor jsonb := '{}'::jsonb;
  v_page_context_json jsonb := '{}'::jsonb;
  v_page_candidate_ids jsonb := '[]'::jsonb;
  v_page_count integer := 0;
  v_seeded_count integer := 0;
  v_new_scope_count integer := 0;
  v_existing_count integer := 0;
  v_enqueued_count integer := 0;
  v_reused_count integer := 0;
  v_enqueue_result jsonb := '{}'::jsonb;
  v_next_cursor jsonb := NULL::jsonb;
  v_has_more boolean := false;
  v_scope_seed_complete boolean := false;
  v_filter_candidate_id uuid := NULL::uuid;
  v_filter_client_id uuid := NULL::uuid;
  v_actor_user_id uuid := NULL::uuid;
  v_base_scope_ordinal bigint := 0;
  v_scope_seeded_count integer := 0;
  v_scope_pending_count integer := 0;
  v_scope_ready_count integer := 0;
  v_scope_failed_count integer := 0;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SESSION_SEED_SCOPE_CHUNK_SESSION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_SESSION_SEED_SCOPE_CHUNK_SESSION_ID_REQUIRED')::text;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SESSION_SEED_SCOPE_CHUNK_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_SESSION_SEED_SCOPE_CHUNK_SESSION_NOT_FOUND', 'session_id', p_session_id::text)::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SESSION_SEED_SCOPE_CHUNK_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_SESSION_SEED_SCOPE_CHUNK_SESSION_NOT_OPEN',
              'session_id', p_session_id::text,
              'status', v_session_row.status,
              'discarded_at_utc', v_session_row.discarded_at_utc
            )::text;
  END IF;

  IF COALESCE(v_session_row.scope_seed_complete, false)
     AND (p_cursor_json IS NULL OR jsonb_typeof(p_cursor_json) <> 'object') THEN
    RETURN jsonb_build_object(
      'ok', true,
      'session_id', p_session_id::text,
      'limit', v_limit,
      'seeded_count', 0,
      'existing_count', 0,
      'enqueued_count', 0,
      'reused_count', 0,
      'next_cursor', NULL::jsonb,
      'has_more', false,
      'scope_seed_complete', true,
      'progress', jsonb_build_object(
        'scope_rows_seeded', COALESCE(v_session_row.scope_seeded_count, 0),
        'scope_rows_pending', COALESCE(v_session_row.scope_pending_count, 0),
        'scope_rows_ready', COALESCE(v_session_row.scope_ready_count, 0),
        'scope_rows_error', COALESCE(v_session_row.scope_failed_count, 0)
      )
    );
  END IF;

  IF BTRIM(COALESCE(v_session_row.filters_json->>'candidate_id', v_session_row.filters_json->>'candidateId', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_candidate_id := COALESCE(v_session_row.filters_json->>'candidate_id', v_session_row.filters_json->>'candidateId')::uuid;
  END IF;

  IF BTRIM(COALESCE(v_session_row.filters_json->>'client_id', v_session_row.filters_json->>'clientId', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_client_id := COALESCE(v_session_row.filters_json->>'client_id', v_session_row.filters_json->>'clientId')::uuid;
  END IF;

  v_actor_user_id := v_session_row.actor_user_id;
  v_effective_cursor := CASE
    WHEN p_cursor_json IS NOT NULL AND jsonb_typeof(p_cursor_json) = 'object' THEN p_cursor_json
    WHEN jsonb_typeof(v_session_row.scope_next_cursor_json) = 'object' THEN v_session_row.scope_next_cursor_json
    ELSE '{}'::jsonb
  END;

  IF v_effective_cursor = '{}'::jsonb THEN
    v_effective_cursor := NULL::jsonb;
  END IF;

  v_page_context_json := public.pay_preview_build_context(
    p_pay_date => v_session_row.pay_date,
    p_week_ending_cutoff => v_session_row.week_ending_cutoff,
    p_actor_user_id => v_actor_user_id,
    p_candidate_id => v_filter_candidate_id,
    p_client_id => v_filter_client_id,
    p_preview_decisions_json => COALESCE(v_session_row.filters_json, '{}'::jsonb)
      || jsonb_build_object(
        'preview_context_mode', 'PAGE',
        'scope_limit', v_limit,
        'scope_cursor', v_effective_cursor
      )
  );

  v_page_candidate_ids := CASE
    WHEN jsonb_typeof(v_page_context_json->'candidate_ids') = 'array' THEN COALESCE(v_page_context_json->'candidate_ids', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;
  v_page_count := COALESCE(jsonb_array_length(v_page_candidate_ids), 0);
  v_next_cursor := COALESCE(v_page_context_json->'next_cursor_json', v_page_context_json->'next_cursor', NULL::jsonb);
  v_next_cursor := CASE
    WHEN jsonb_typeof(v_next_cursor) = 'object' THEN v_next_cursor
    ELSE NULL::jsonb
  END;
  v_has_more := COALESCE(NULLIF(BTRIM(COALESCE(v_page_context_json->>'has_more', '')), '')::boolean, false);
  v_scope_seed_complete := NOT COALESCE(v_has_more, false);
  v_base_scope_ordinal := COALESCE(v_session_row.scope_seeded_count, 0);

  IF v_page_count > 0 THEN
    DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_seed_candidate_page;
    CREATE TEMP TABLE _tmp_pay_wb_seed_candidate_page ON COMMIT DROP AS
    SELECT DISTINCT
      NULLIF(BTRIM(candidate_ids.value), '')::uuid AS candidate_id,
      ROW_NUMBER() OVER (ORDER BY NULLIF(BTRIM(candidate_ids.value), '')::uuid) AS page_ordinal
    FROM jsonb_array_elements_text(v_page_candidate_ids) AS candidate_ids(value)
    WHERE NULLIF(BTRIM(candidate_ids.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

    WITH selected_rows AS (
      SELECT
        candidate_page.candidate_id,
        (v_base_scope_ordinal + candidate_page.page_ordinal)::bigint AS scope_ordinal,
        existing_scope.id AS existing_scope_id,
        existing_scope.status AS existing_status
      FROM pg_temp._tmp_pay_wb_seed_candidate_page AS candidate_page
      LEFT JOIN public.banking_pay_workbench_session_scope AS existing_scope
        ON existing_scope.session_id = p_session_id
       AND existing_scope.candidate_id = candidate_page.candidate_id
    ), upserted_scope AS (
      INSERT INTO public.banking_pay_workbench_session_scope (
        session_id,
        candidate_id,
        scope_ordinal,
        status,
        pending_job_id,
        seeded,
        dirty,
        error_json,
        created_at_utc,
        updated_at_utc
      )
      SELECT
        p_session_id,
        selected_rows.candidate_id,
        selected_rows.scope_ordinal,
        'PENDING',
        NULL::uuid,
        true,
        false,
        NULL::jsonb,
        v_now,
        v_now
      FROM selected_rows
      ON CONFLICT (session_id, candidate_id)
      DO UPDATE
      SET scope_ordinal = LEAST(public.banking_pay_workbench_session_scope.scope_ordinal, EXCLUDED.scope_ordinal),
          status = CASE
            WHEN UPPER(BTRIM(COALESCE(public.banking_pay_workbench_session_scope.status, ''))) IN ('READY', 'LINE_WORK_READY', 'MATERIALISED', 'MATERIALIZED')
              THEN public.banking_pay_workbench_session_scope.status
            ELSE 'PENDING'
          END,
          seeded = true,
          dirty = false,
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      RETURNING public.banking_pay_workbench_session_scope.candidate_id, (xmax = 0) AS inserted_row
    )
    SELECT
      COUNT(*)::integer,
      COUNT(*) FILTER (WHERE upserted_scope.inserted_row)::integer,
      COUNT(*) FILTER (WHERE upserted_scope.inserted_row IS NOT TRUE)::integer
    INTO
      v_seeded_count,
      v_new_scope_count,
      v_existing_count
    FROM upserted_scope;

    v_enqueue_result := public.pay_workbench_enqueue_candidate_refresh_many(
      p_session_id => p_session_id,
      p_candidate_ids => v_page_candidate_ids,
      p_reason => 'WORKBENCH_SCOPE_SEED',
      p_actor_user_id => v_actor_user_id
    );

    v_enqueued_count := COALESCE(NULLIF(BTRIM(COALESCE(v_enqueue_result->>'queued_count', '')), '')::integer, 0);
    v_reused_count := COALESCE(NULLIF(BTRIM(COALESCE(v_enqueue_result->>'reused_count', '')), '')::integer, 0);
  END IF;

  v_scope_seeded_count := COALESCE(v_session_row.scope_seeded_count, 0) + COALESCE(v_new_scope_count, 0);
  v_scope_pending_count := COALESCE(v_session_row.scope_pending_count, 0) + COALESCE(v_new_scope_count, 0);
  v_scope_ready_count := COALESCE(v_session_row.scope_ready_count, 0);
  v_scope_failed_count := COALESCE(v_session_row.scope_failed_count, 0);

  UPDATE public.banking_pay_workbench_sessions AS session_update
  SET scope_next_cursor_json = CASE
        WHEN jsonb_typeof(v_next_cursor) = 'object' THEN v_next_cursor
        ELSE '{}'::jsonb
      END,
      scope_seed_complete = v_scope_seed_complete,
      scope_total_count = GREATEST(COALESCE(session_update.scope_total_count, 0), v_scope_seeded_count),
      scope_seeded_count = v_scope_seeded_count,
      scope_pending_count = v_scope_pending_count,
      scope_ready_count = v_scope_ready_count,
      scope_failed_count = v_scope_failed_count,
      progress_state = CASE WHEN v_scope_seed_complete AND v_scope_seeded_count = 0 THEN 'READY_EMPTY' ELSE 'REFRESHING_CANDIDATES' END,
      progress_json = jsonb_build_object(
        'phase', CASE WHEN v_scope_seed_complete AND v_scope_seeded_count = 0 THEN 'READY' ELSE 'REFRESHING_CANDIDATES' END,
        'status_text', CASE WHEN v_scope_seed_complete AND v_scope_seeded_count = 0 THEN 'Payment preview is ready.' ELSE 'Preparing payment preview.' END,
        'scope_seed_complete', v_scope_seed_complete,
        'count_unknown', NOT v_scope_seed_complete
      ),
      progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
      progress_updated_at_utc = v_now,
      updated_at_utc = v_now
  WHERE session_update.id = p_session_id;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'limit', v_limit,
    'seeded_count', COALESCE(v_seeded_count, 0),
    'new_scope_count', COALESCE(v_new_scope_count, 0),
    'existing_count', COALESCE(v_existing_count, 0),
    'enqueued_count', COALESCE(v_enqueued_count, 0),
    'reused_count', COALESCE(v_reused_count, 0),
    'next_cursor', v_next_cursor,
    'has_more', COALESCE(v_has_more, false),
    'scope_seed_complete', v_scope_seed_complete,
    'enqueue_result', COALESCE(v_enqueue_result, '{}'::jsonb)
  )
  || jsonb_build_object(
    'progress', jsonb_build_object(
      'scope_rows_seeded', COALESCE(v_scope_seeded_count, 0),
      'scope_rows_pending', COALESCE(v_scope_pending_count, 0),
      'scope_rows_ready', COALESCE(v_scope_ready_count, 0),
      'scope_rows_error', COALESCE(v_scope_failed_count, 0),
      'count_unknown', NOT v_scope_seed_complete
    )
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_workbench_candidate_line_work_process_chunk(
  p_session_id uuid,
  p_candidate_id uuid DEFAULT NULL::uuid,
  p_cursor_json jsonb DEFAULT NULL::jsonb,
  p_limit integer DEFAULT 100
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_cursor_scope_ordinal bigint := -1;
  v_cursor_line_ordinal bigint := -1;
  v_cursor_line_work_id uuid := NULL::uuid;
  v_cursor_has_scope boolean := false;
  v_raw_count integer := 0;
  v_processed_count integer := 0;
  v_error_count integer := 0;
  v_ready_delta integer := 0;
  v_skipped_count integer := 0;
  v_next_cursor jsonb := NULL::jsonb;
  v_last_returned_scope_ordinal bigint := NULL::bigint;
  v_last_returned_line_ordinal bigint := NULL::bigint;
  v_last_returned_line_work_id uuid := NULL::uuid;
  v_affected_candidate_sample jsonb := '[]'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_SESSION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_SESSION_ID_REQUIRED')::text;
  END IF;

  IF p_cursor_json IS NOT NULL AND jsonb_typeof(p_cursor_json) = 'object' THEN
    BEGIN
      IF NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_scope_ordinal', p_cursor_json->>'cursor_scope_ordinal', '')), '') IS NOT NULL THEN
        v_cursor_scope_ordinal := NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_scope_ordinal', p_cursor_json->>'cursor_scope_ordinal', '')), '')::bigint;
        v_cursor_has_scope := true;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_cursor_scope_ordinal := -1;
      v_cursor_has_scope := false;
    END;

    BEGIN
      v_cursor_line_ordinal := COALESCE(
        NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_line_ordinal', '')), '')::bigint,
        NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_ordinal', '')), '')::bigint,
        NULLIF(BTRIM(COALESCE(p_cursor_json->>'cursor_ordinal', '')), '')::bigint,
        -1
      );
    EXCEPTION WHEN OTHERS THEN
      v_cursor_line_ordinal := -1;
    END;

    IF NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_line_work_id', p_cursor_json->>'last_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_cursor_line_work_id := NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_line_work_id', p_cursor_json->>'last_id', '')), '')::uuid;
    END IF;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_SESSION_NOT_FOUND',
              'session_id', p_session_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_SESSION_NOT_OPEN',
              'session_id', p_session_id::text,
              'status', v_session_row.status
            )::text;
  END IF;

  IF p_candidate_id IS NOT NULL THEN
    SELECT COALESCE(scope_check.scope_ordinal, 0)::bigint
    INTO v_cursor_scope_ordinal
    FROM public.banking_pay_workbench_session_scope AS scope_check
    WHERE scope_check.session_id = p_session_id
      AND scope_check.candidate_id = p_candidate_id
    LIMIT 1;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CANDIDATE_NOT_IN_SCOPE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CANDIDATE_NOT_IN_SCOPE',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text
              )::text;
    END IF;
  ELSIF v_cursor_has_scope IS NOT TRUE THEN
    v_cursor_scope_ordinal := -1;
    v_cursor_line_ordinal := -1;
    v_cursor_line_work_id := NULL::uuid;
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_line_process;
  CREATE TEMP TABLE _tmp_pay_wb_line_process ON COMMIT DROP AS
  WITH pending_rows AS (
    SELECT
      line_work.id,
      line_work.session_id,
      line_work.candidate_id,
      line_work.timesheet_id,
      line_work.line_key,
      line_work.line_ordinal,
      line_work.work_payload_json,
      COALESCE(scope_row.scope_ordinal, 0)::bigint AS scope_ordinal,
      ROW_NUMBER() OVER (
        ORDER BY COALESCE(scope_row.scope_ordinal, 0), line_work.line_ordinal, line_work.id
      ) AS page_ordinal
    FROM public.banking_pay_workbench_candidate_line_work AS line_work
    JOIN public.banking_pay_workbench_session_scope AS scope_row
      ON scope_row.session_id = line_work.session_id
     AND scope_row.candidate_id = line_work.candidate_id
    WHERE line_work.session_id = p_session_id
      AND (p_candidate_id IS NULL OR line_work.candidate_id = p_candidate_id)
      AND UPPER(BTRIM(COALESCE(line_work.status, ''))) = 'PENDING'
      AND (
        COALESCE(scope_row.scope_ordinal, 0)::bigint > COALESCE(v_cursor_scope_ordinal, -1)
        OR (
          COALESCE(scope_row.scope_ordinal, 0)::bigint = COALESCE(v_cursor_scope_ordinal, -1)
          AND line_work.line_ordinal > COALESCE(v_cursor_line_ordinal, -1)
        )
        OR (
          COALESCE(scope_row.scope_ordinal, 0)::bigint = COALESCE(v_cursor_scope_ordinal, -1)
          AND line_work.line_ordinal = COALESCE(v_cursor_line_ordinal, -1)
          AND v_cursor_line_work_id IS NOT NULL
          AND line_work.id > v_cursor_line_work_id
        )
      )
    ORDER BY COALESCE(scope_row.scope_ordinal, 0), line_work.line_ordinal, line_work.id
    LIMIT (v_limit + 1)
  )
  SELECT pending_rows.*
  FROM pending_rows;

  SELECT COUNT(*)::integer
  INTO v_raw_count
  FROM pg_temp._tmp_pay_wb_line_process AS process_rows;

  WITH selected_rows AS (
    SELECT process_rows.*
    FROM pg_temp._tmp_pay_wb_line_process AS process_rows
    WHERE process_rows.page_ordinal <= v_limit
  ), prepared_source_rows AS (
    SELECT
      selected_rows.id,
      selected_rows.candidate_id,
      selected_rows.timesheet_id AS line_work_timesheet_id,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(selected_rows.work_payload_json#>>'{economic_key,timesheet_id}', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(selected_rows.work_payload_json#>>'{economic_key,timesheet_id}', '')), '')::uuid
        ELSE NULL::uuid
      END AS economic_key_timesheet_id,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(
          selected_rows.work_payload_json#>>'{line_json,economic_key,timesheet_id}',
          selected_rows.work_payload_json#>>'{line_json,real_business_timesheet_id}',
          selected_rows.work_payload_json#>>'{line_json,timesheet_id}',
          ''
        )), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(
            selected_rows.work_payload_json#>>'{line_json,economic_key,timesheet_id}',
            selected_rows.work_payload_json#>>'{line_json,real_business_timesheet_id}',
            selected_rows.work_payload_json#>>'{line_json,timesheet_id}',
            ''
          )), '')::uuid
        ELSE NULL::uuid
      END AS line_json_timesheet_id,
      selected_rows.line_key,
      selected_rows.line_ordinal,
      selected_rows.scope_ordinal,
      selected_rows.work_payload_json,
      COALESCE(selected_rows.work_payload_json->'line_json', '{}'::jsonb) AS safe_line_json,
      CASE
        WHEN jsonb_typeof(selected_rows.work_payload_json->'economic_key') = 'object'
          THEN selected_rows.work_payload_json->'economic_key'
        ELSE '{}'::jsonb
      END AS economic_key_json,
      COALESCE(
        NULLIF(BTRIM(selected_rows.work_payload_json->>'target_section'), ''),
        NULLIF(BTRIM(selected_rows.work_payload_json->>'section'), ''),
        NULLIF(BTRIM(selected_rows.work_payload_json#>>'{preview_contract,target_section}'), '')
      ) AS target_section_hint,
      UPPER(NULLIF(BTRIM(COALESCE(selected_rows.work_payload_json->>'source_kind', selected_rows.work_payload_json#>>'{line_json,source_kind}', '')), '')) AS source_kind,
      UPPER(NULLIF(BTRIM(COALESCE(selected_rows.work_payload_json->>'source_function', '')), '')) AS source_function,
      CASE
        WHEN selected_rows.line_key LIKE 'timesheet_snapshot:%' THEN true
        WHEN UPPER(NULLIF(BTRIM(COALESCE(selected_rows.work_payload_json->>'source_kind', selected_rows.work_payload_json#>>'{line_json,source_kind}', '')), '')) IN (
          'TIMESHEET_SNAPSHOT',
          'TIMESHEET_SNAPSHOT_EVIDENCE',
          'RAW_TIMESHEET_SNAPSHOT',
          'INTERNAL_ONLY',
          'NO_DELTA',
          'EXCLUDED'
        ) THEN true
        WHEN UPPER(NULLIF(BTRIM(COALESCE(selected_rows.work_payload_json->>'source_function', '')), '')) = 'PAY_PREVIEW_CANDIDATE_BUILD_TIMESHEET_SNAPSHOTS' THEN true
        ELSE false
      END AS is_internal_snapshot_row
    FROM selected_rows
  ), source_timesheet_refs AS (
    SELECT prepared_source_rows.id, 'LINE_WORK'::text AS source_label, prepared_source_rows.line_work_timesheet_id AS source_timesheet_id
    FROM prepared_source_rows
    WHERE prepared_source_rows.line_work_timesheet_id IS NOT NULL
    UNION ALL
    SELECT prepared_source_rows.id, 'ECONOMIC_KEY'::text AS source_label, prepared_source_rows.economic_key_timesheet_id AS source_timesheet_id
    FROM prepared_source_rows
    WHERE prepared_source_rows.economic_key_timesheet_id IS NOT NULL
    UNION ALL
    SELECT prepared_source_rows.id, 'LINE_JSON'::text AS source_label, prepared_source_rows.line_json_timesheet_id AS source_timesheet_id
    FROM prepared_source_rows
    WHERE prepared_source_rows.line_json_timesheet_id IS NOT NULL
  ), source_timesheet_id_array AS (
    SELECT COALESCE(
      array_agg(DISTINCT source_timesheet_refs.source_timesheet_id ORDER BY source_timesheet_refs.source_timesheet_id),
      array[]::uuid[]
    ) AS timesheet_ids
    FROM source_timesheet_refs
  ), rotation_scope_rows AS (
    SELECT
      rotation_scope.requested_timesheet_id,
      rotation_scope.canonical_timesheet_id,
      rotation_scope.family_timesheet_id,
      rotation_scope.family_is_current,
      rotation_scope.family_version,
      rotation_scope.requested_is_canonical
    FROM source_timesheet_id_array
    JOIN public._pay_timesheet_rotation_scope(source_timesheet_id_array.timesheet_ids) AS rotation_scope
      ON true
  ), rotation_scope_by_requested AS (
    SELECT DISTINCT ON (rotation_scope_rows.requested_timesheet_id)
      rotation_scope_rows.requested_timesheet_id,
      COALESCE(rotation_scope_rows.canonical_timesheet_id, rotation_scope_rows.requested_timesheet_id) AS canonical_timesheet_id,
      (rotation_scope_rows.family_timesheet_id IS NOT NULL AND rotation_scope_rows.family_is_current IS NOT NULL) AS rotation_scope_resolved,
      COALESCE(rotation_scope_rows.requested_is_canonical, false) AS requested_is_canonical
    FROM rotation_scope_rows
    WHERE rotation_scope_rows.requested_timesheet_id IS NOT NULL
    ORDER BY
      rotation_scope_rows.requested_timesheet_id,
      rotation_scope_rows.family_is_current DESC NULLS LAST,
      rotation_scope_rows.family_version DESC NULLS LAST,
      rotation_scope_rows.family_timesheet_id
  ), prepared_rows AS (
    SELECT
      prepared_source_rows.id,
      prepared_source_rows.candidate_id,
      COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id) AS timesheet_id,
      prepared_source_rows.line_work_timesheet_id,
      prepared_source_rows.economic_key_timesheet_id,
      prepared_source_rows.line_json_timesheet_id,
      line_work_rotation.canonical_timesheet_id AS line_work_canonical_timesheet_id,
      economic_key_rotation.canonical_timesheet_id AS economic_key_canonical_timesheet_id,
      line_json_rotation.canonical_timesheet_id AS line_json_canonical_timesheet_id,
      prepared_source_rows.line_key,
      prepared_source_rows.line_ordinal,
      prepared_source_rows.scope_ordinal,
      jsonb_strip_nulls(
        COALESCE(prepared_source_rows.economic_key_json, '{}'::jsonb)
        || jsonb_build_object(
          'timesheet_id', CASE
            WHEN COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id) IS NULL THEN NULL
            ELSE COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id)::text
          END
        )
      ) AS economic_key_json,
      jsonb_strip_nulls(
        CASE
          WHEN COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id) IS NULL THEN prepared_source_rows.safe_line_json
          ELSE prepared_source_rows.safe_line_json
            || jsonb_build_object(
              'timesheet_id', COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id)::text,
              'real_business_timesheet_id', COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id)::text
            )
            || jsonb_build_object(
              'economic_key', COALESCE(prepared_source_rows.safe_line_json->'economic_key', '{}'::jsonb)
                || jsonb_build_object('timesheet_id', COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id)::text)
            )
            || CASE
              WHEN prepared_source_rows.line_work_timesheet_id IS DISTINCT FROM COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id)
                OR prepared_source_rows.economic_key_timesheet_id IS DISTINCT FROM COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id)
                OR prepared_source_rows.line_json_timesheet_id IS DISTINCT FROM COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id)
              THEN jsonb_build_object(
                'rotation_requested_timesheet_ids', jsonb_strip_nulls(jsonb_build_object(
                  'line_work_timesheet_id', CASE WHEN prepared_source_rows.line_work_timesheet_id IS NULL THEN NULL ELSE prepared_source_rows.line_work_timesheet_id::text END,
                  'economic_key_timesheet_id', CASE WHEN prepared_source_rows.economic_key_timesheet_id IS NULL THEN NULL ELSE prepared_source_rows.economic_key_timesheet_id::text END,
                  'line_json_timesheet_id', CASE WHEN prepared_source_rows.line_json_timesheet_id IS NULL THEN NULL ELSE prepared_source_rows.line_json_timesheet_id::text END
                ))
              )
              ELSE '{}'::jsonb
            END
        END
      ) AS safe_line_json,
      prepared_source_rows.target_section_hint,
      prepared_source_rows.source_kind,
      prepared_source_rows.source_function,
      prepared_source_rows.is_internal_snapshot_row,
      CASE
        WHEN prepared_source_rows.is_internal_snapshot_row THEN false
        WHEN prepared_source_rows.line_work_timesheet_id IS NULL
         AND prepared_source_rows.economic_key_timesheet_id IS NULL
         AND prepared_source_rows.line_json_timesheet_id IS NULL THEN false
        WHEN COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id) IS NULL THEN true
        WHEN prepared_source_rows.line_work_timesheet_id IS NOT NULL AND COALESCE(line_work_rotation.rotation_scope_resolved, false) = false THEN true
        WHEN prepared_source_rows.economic_key_timesheet_id IS NOT NULL AND COALESCE(economic_key_rotation.rotation_scope_resolved, false) = false THEN true
        WHEN prepared_source_rows.line_json_timesheet_id IS NOT NULL AND COALESCE(line_json_rotation.rotation_scope_resolved, false) = false THEN true
        WHEN line_work_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND line_work_rotation.canonical_timesheet_id IS DISTINCT FROM economic_key_rotation.canonical_timesheet_id THEN true
        WHEN line_work_rotation.canonical_timesheet_id IS NOT NULL
         AND line_json_rotation.canonical_timesheet_id IS NOT NULL
         AND line_work_rotation.canonical_timesheet_id IS DISTINCT FROM line_json_rotation.canonical_timesheet_id THEN true
        WHEN economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND line_json_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS DISTINCT FROM line_json_rotation.canonical_timesheet_id THEN true
        ELSE false
      END AS rotation_validation_failed,
      CASE
        WHEN prepared_source_rows.is_internal_snapshot_row THEN NULL::text
        WHEN prepared_source_rows.line_work_timesheet_id IS NULL
         AND prepared_source_rows.economic_key_timesheet_id IS NULL
         AND prepared_source_rows.line_json_timesheet_id IS NULL THEN NULL::text
        WHEN COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, line_json_rotation.canonical_timesheet_id) IS NULL THEN 'ROTATION_CANONICAL_TIMESHEET_NOT_RESOLVED'
        WHEN prepared_source_rows.line_work_timesheet_id IS NOT NULL AND COALESCE(line_work_rotation.rotation_scope_resolved, false) = false THEN 'LINE_WORK_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
        WHEN prepared_source_rows.economic_key_timesheet_id IS NOT NULL AND COALESCE(economic_key_rotation.rotation_scope_resolved, false) = false THEN 'ECONOMIC_KEY_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
        WHEN prepared_source_rows.line_json_timesheet_id IS NOT NULL AND COALESCE(line_json_rotation.rotation_scope_resolved, false) = false THEN 'LINE_JSON_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
        WHEN line_work_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND line_work_rotation.canonical_timesheet_id IS DISTINCT FROM economic_key_rotation.canonical_timesheet_id THEN 'LINE_WORK_AND_ECONOMIC_KEY_CANONICAL_TIMESHEET_MISMATCH'
        WHEN line_work_rotation.canonical_timesheet_id IS NOT NULL
         AND line_json_rotation.canonical_timesheet_id IS NOT NULL
         AND line_work_rotation.canonical_timesheet_id IS DISTINCT FROM line_json_rotation.canonical_timesheet_id THEN 'LINE_WORK_AND_RESULT_ROW_CANONICAL_TIMESHEET_MISMATCH'
        WHEN economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND line_json_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS DISTINCT FROM line_json_rotation.canonical_timesheet_id THEN 'ECONOMIC_KEY_AND_RESULT_ROW_CANONICAL_TIMESHEET_MISMATCH'
        ELSE NULL::text
      END AS rotation_failure_reason
    FROM prepared_source_rows
    LEFT JOIN rotation_scope_by_requested AS line_work_rotation
      ON line_work_rotation.requested_timesheet_id = prepared_source_rows.line_work_timesheet_id
    LEFT JOIN rotation_scope_by_requested AS economic_key_rotation
      ON economic_key_rotation.requested_timesheet_id = prepared_source_rows.economic_key_timesheet_id
    LEFT JOIN rotation_scope_by_requested AS line_json_rotation
      ON line_json_rotation.requested_timesheet_id = prepared_source_rows.line_json_timesheet_id
  ), contracted_rows AS (
    SELECT
      prepared_rows.*,
      CASE
        WHEN prepared_rows.is_internal_snapshot_row THEN jsonb_build_object(
          'ok', false,
          'materialisable', false,
          'target_section', 'internal_only',
          'selection_allowed', false,
          'reasons', jsonb_build_array('INTERNAL_TIMESHEET_SNAPSHOT_ROW_SKIPPED'),
          'status', 'SKIPPED'
        )
        WHEN prepared_rows.rotation_validation_failed THEN jsonb_build_object(
          'ok', false,
          'materialisable', true,
          'target_section', COALESCE(prepared_rows.target_section_hint, 'canonical_preview_lines'),
          'selection_allowed', false,
          'reasons', jsonb_build_array(prepared_rows.rotation_failure_reason),
          'status', 'ERROR'
        )
        WHEN jsonb_typeof(prepared_rows.safe_line_json) = 'object' THEN public.pay_workbench_preview_line_contract_ok(
          p_line_json => prepared_rows.safe_line_json,
          p_economic_key_json => prepared_rows.economic_key_json,
          p_target_section => prepared_rows.target_section_hint
        )
        ELSE jsonb_build_object(
          'ok', false,
          'materialisable', false,
          'target_section', 'internal_only',
          'selection_allowed', false,
          'reasons', jsonb_build_array('LINE_JSON_NOT_OBJECT'),
          'status', 'NOT_OK'
        )
      END AS contract_json
    FROM prepared_rows
  ), update_source AS (
    SELECT
      contracted_rows.*,
      COALESCE(NULLIF(BTRIM(contracted_rows.contract_json->>'target_section'), ''), 'internal_only') AS target_section,
      CASE
        WHEN contracted_rows.rotation_validation_failed THEN 'ERROR'
        WHEN LOWER(BTRIM(COALESCE(contracted_rows.contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 'READY'
        WHEN LOWER(BTRIM(COALESCE(contracted_rows.contract_json->>'materialisable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 'ERROR'
        ELSE 'SKIPPED'
      END AS next_status
    FROM contracted_rows
  ), updated_rows AS (
    UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
    SET status = update_source.next_status,
        timesheet_id = CASE
          WHEN update_source.rotation_validation_failed THEN line_work.timesheet_id
          ELSE COALESCE(update_source.timesheet_id, line_work.timesheet_id)
        END,
        result_row_json = CASE
          WHEN update_source.next_status = 'READY' THEN jsonb_strip_nulls(
            update_source.safe_line_json
            || jsonb_build_object(
              'session_id', p_session_id::text,
              'candidate_id', update_source.candidate_id::text,
              'line_work_id', update_source.id::text,
              'row_key', update_source.line_key,
              'line_key', update_source.line_key,
              'line_ordinal', update_source.line_ordinal,
              'scope_ordinal', update_source.scope_ordinal,
              'timesheet_id', CASE WHEN update_source.timesheet_id IS NULL THEN NULL ELSE update_source.timesheet_id::text END,
              'section', update_source.target_section
            )
            || jsonb_build_object(
              'economic_key', update_source.economic_key_json,
              'preview_contract', update_source.contract_json,
              'selection_allowed', COALESCE(NULLIF(BTRIM(update_source.contract_json->>'selection_allowed'), '')::boolean, false),
              'policy_x_pre_draft_key_resolved', LOWER(BTRIM(COALESCE(update_source.economic_key_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
              'row_processing_status', CASE WHEN update_source.target_section = 'canonical_preview_lines' THEN 'READY' ELSE 'DISPLAY_ONLY' END
            )
          )
          WHEN update_source.next_status = 'SKIPPED' THEN jsonb_strip_nulls(
            update_source.safe_line_json
            || jsonb_build_object(
              'session_id', p_session_id::text,
              'candidate_id', update_source.candidate_id::text,
              'line_work_id', update_source.id::text,
              'row_key', update_source.line_key,
              'line_key', update_source.line_key,
              'line_ordinal', update_source.line_ordinal,
              'scope_ordinal', update_source.scope_ordinal,
              'section', 'internal_only',
              'preview_contract', update_source.contract_json,
              'row_processing_status', 'SKIPPED'
            )
          )
          ELSE NULL::jsonb
        END,
        error_json = CASE
          WHEN update_source.next_status = 'ERROR' THEN jsonb_build_object(
            'code', CASE WHEN update_source.rotation_validation_failed THEN 'WORKBENCH_ROTATED_TIMESHEET_MISMATCH' ELSE 'PREVIEW_LINE_CONTRACT_FAILED' END,
            'message', CASE
              WHEN update_source.rotation_validation_failed THEN 'Candidate line work timesheet identities did not resolve to the same current canonical timesheet.'
              ELSE 'Candidate line work did not satisfy the Banking Pay preview-row contract.'
            END,
            'line_key', update_source.line_key,
            'line_ordinal', update_source.line_ordinal,
            'scope_ordinal', update_source.scope_ordinal,
            'target_section', update_source.target_section,
            'reasons', COALESCE(update_source.contract_json->'reasons', '[]'::jsonb)
          )
          ELSE NULL::jsonb
        END,
        updated_at_utc = v_now
    FROM update_source
    WHERE line_work.id = update_source.id
    RETURNING line_work.candidate_id, line_work.status
  )
  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(updated_rows.status, ''))) = 'ERROR')::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(updated_rows.status, ''))) = 'READY')::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(updated_rows.status, ''))) = 'SKIPPED')::integer
  INTO v_processed_count, v_error_count, v_ready_delta, v_skipped_count
  FROM updated_rows;

  IF v_raw_count > v_limit THEN
    SELECT
      process_rows.scope_ordinal,
      process_rows.line_ordinal,
      process_rows.id
    INTO
      v_last_returned_scope_ordinal,
      v_last_returned_line_ordinal,
      v_last_returned_line_work_id
    FROM pg_temp._tmp_pay_wb_line_process AS process_rows
    WHERE process_rows.page_ordinal = v_limit;

    v_next_cursor := jsonb_build_object(
      'last_scope_ordinal', v_last_returned_scope_ordinal,
      'last_line_ordinal', v_last_returned_line_ordinal,
      'last_line_work_id', v_last_returned_line_work_id::text
    );
  ELSE
    v_next_cursor := NULL::jsonb;
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_line_process_scope_delta;
  CREATE TEMP TABLE _tmp_pay_wb_line_process_scope_delta ON COMMIT DROP AS
  WITH affected_candidates AS (
    SELECT DISTINCT process_rows.candidate_id
    FROM pg_temp._tmp_pay_wb_line_process AS process_rows
    WHERE process_rows.page_ordinal <= v_limit
  ), candidate_new_status AS (
    SELECT
      affected_candidates.candidate_id,
      CASE
        WHEN EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_line_work AS line_error
          WHERE line_error.session_id = p_session_id
            AND line_error.candidate_id = affected_candidates.candidate_id
            AND UPPER(BTRIM(COALESCE(line_error.status, ''))) = 'ERROR'
        ) THEN 'ERROR'
        WHEN EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_line_work AS line_pending
          WHERE line_pending.session_id = p_session_id
            AND line_pending.candidate_id = affected_candidates.candidate_id
            AND UPPER(BTRIM(COALESCE(line_pending.status, ''))) = 'PENDING'
        ) THEN 'LINE_WORK_PENDING'
        WHEN EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_line_work AS line_ready
          WHERE line_ready.session_id = p_session_id
            AND line_ready.candidate_id = affected_candidates.candidate_id
            AND UPPER(BTRIM(COALESCE(line_ready.status, ''))) = 'READY'
        ) THEN 'LINE_WORK_READY'
        ELSE 'MATERIALISED'
      END AS new_status
    FROM affected_candidates
  )
  SELECT
    scope_row.candidate_id,
    UPPER(BTRIM(COALESCE(scope_row.status, 'PENDING'))) AS old_status,
    candidate_new_status.new_status
  FROM candidate_new_status
  JOIN public.banking_pay_workbench_session_scope AS scope_row
    ON scope_row.session_id = p_session_id
   AND scope_row.candidate_id = candidate_new_status.candidate_id;

  UPDATE public.banking_pay_workbench_session_scope AS scope_row
  SET status = scope_delta.new_status,
      dirty = scope_delta.new_status NOT IN ('LINE_WORK_READY', 'MATERIALISED', 'MATERIALIZED'),
      updated_at_utc = v_now,
      error_json = CASE
        WHEN scope_delta.new_status = 'ERROR' THEN jsonb_build_object('code', 'LINE_WORK_PROCESS_ERROR')
        ELSE NULL::jsonb
      END
  FROM pg_temp._tmp_pay_wb_line_process_scope_delta AS scope_delta
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = scope_delta.candidate_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'candidate_id', scope_delta.candidate_id::text,
           'old_status', scope_delta.old_status,
           'new_status', scope_delta.new_status
         ) ORDER BY scope_delta.candidate_id), '[]'::jsonb)
  INTO v_affected_candidate_sample
  FROM (
    SELECT scope_delta.*
    FROM pg_temp._tmp_pay_wb_line_process_scope_delta AS scope_delta
    ORDER BY scope_delta.candidate_id
    LIMIT 25
  ) AS scope_delta;

  UPDATE public.banking_pay_workbench_sessions AS session_row
  SET line_units_pending = GREATEST(COALESCE(session_row.line_units_pending, 0) - COALESCE(v_processed_count, 0), 0),
      line_units_ready = GREATEST(COALESCE(session_row.line_units_ready, 0) + COALESCE(v_ready_delta, 0), 0),
      line_units_failed = GREATEST(COALESCE(session_row.line_units_failed, 0) + COALESCE(v_error_count, 0), 0),
      candidate_sample_rows_json = COALESCE(v_affected_candidate_sample, '[]'::jsonb),
      progress_state = CASE
        WHEN COALESCE(v_error_count, 0) > 0 THEN 'ERROR'
        WHEN v_next_cursor IS NOT NULL OR COALESCE(v_processed_count, 0) > 0 THEN 'PROCESSING_LINE_WORK'
        ELSE COALESCE(NULLIF(BTRIM(session_row.progress_state), ''), 'PENDING')
      END,
      progress_json = COALESCE(session_row.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'last_line_process_at_utc', v_now::text,
          'last_line_process_count', COALESCE(v_processed_count, 0),
          'last_line_process_ready_count', COALESCE(v_ready_delta, 0),
          'last_line_process_skipped_count', COALESCE(v_skipped_count, 0),
          'last_line_process_error_count', COALESCE(v_error_count, 0),
          'last_line_process_has_more', v_next_cursor IS NOT NULL
        ),
      progress_counter_version = COALESCE(session_row.progress_counter_version, 0) + 1,
      progress_updated_at_utc = v_now,
      updated_at_utc = v_now
  WHERE session_row.id = p_session_id;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'limit', v_limit,
    'cursor_scope_ordinal', COALESCE(v_cursor_scope_ordinal, -1),
    'cursor_line_ordinal', COALESCE(v_cursor_line_ordinal, -1),
    'cursor_line_work_id', CASE WHEN v_cursor_line_work_id IS NULL THEN NULL ELSE v_cursor_line_work_id::text END,
    'processed_count', COALESCE(v_processed_count, 0),
    'ready_count_delta', COALESCE(v_ready_delta, 0),
    'skipped_count', COALESCE(v_skipped_count, 0),
    'error_count', COALESCE(v_error_count, 0)
  )
  || jsonb_build_object(
    'next_cursor', v_next_cursor,
    'has_more', v_next_cursor IS NOT NULL,
    'affected_candidates', COALESCE(v_affected_candidate_sample, '[]'::jsonb),
    'cursor_scheme', 'last_scope_ordinal_last_line_ordinal_last_line_work_id'
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_workbench_preview_rows_materialise_chunk(p_session_id uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_cursor_scope_ordinal bigint := -1;
  v_cursor_line_ordinal bigint := -1;
  v_cursor_line_work_id uuid := NULL::uuid;
  v_cursor_has_scope boolean := false;
  v_raw_count integer := 0;
  v_materialised_count integer := 0;
  v_new_preview_row_count integer := 0;
  v_new_selected_row_count integer := 0;
  v_suppressed_preview_row_count integer := 0;
  v_materialise_error_count integer := 0;
  v_next_cursor jsonb := NULL::jsonb;
  v_last_returned_scope_ordinal bigint := NULL::bigint;
  v_last_returned_line_ordinal bigint := NULL::bigint;
  v_last_returned_line_work_id uuid := NULL::uuid;
  v_section_delta_json jsonb := '{}'::jsonb;
  v_affected_candidate_sample jsonb := '[]'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_PREVIEW_ROWS_MATERIALISE_SESSION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_PREVIEW_ROWS_MATERIALISE_SESSION_ID_REQUIRED')::text;
  END IF;

  IF p_cursor_json IS NOT NULL AND jsonb_typeof(p_cursor_json) = 'object' THEN
    BEGIN
      IF NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_scope_ordinal', p_cursor_json->>'cursor_scope_ordinal', '')), '') IS NOT NULL THEN
        v_cursor_scope_ordinal := NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_scope_ordinal', p_cursor_json->>'cursor_scope_ordinal', '')), '')::bigint;
        v_cursor_has_scope := true;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_cursor_scope_ordinal := -1;
      v_cursor_has_scope := false;
    END;

    BEGIN
      v_cursor_line_ordinal := COALESCE(
        NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_line_ordinal', '')), '')::bigint,
        NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_ordinal', '')), '')::bigint,
        NULLIF(BTRIM(COALESCE(p_cursor_json->>'cursor_ordinal', '')), '')::bigint,
        -1
      );
    EXCEPTION WHEN OTHERS THEN
      v_cursor_line_ordinal := -1;
    END;

    IF NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_line_work_id', p_cursor_json->>'last_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_cursor_line_work_id := NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_line_work_id', p_cursor_json->>'last_id', '')), '')::uuid;
    END IF;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_PREVIEW_ROWS_MATERIALISE_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_PREVIEW_ROWS_MATERIALISE_SESSION_NOT_FOUND',
              'session_id', p_session_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_PREVIEW_ROWS_MATERIALISE_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_PREVIEW_ROWS_MATERIALISE_SESSION_NOT_OPEN',
              'session_id', p_session_id::text,
              'status', v_session_row.status
            )::text;
  END IF;

  IF p_candidate_id IS NOT NULL THEN
    SELECT COALESCE(scope_check.scope_ordinal, 0)::bigint
    INTO v_cursor_scope_ordinal
    FROM public.banking_pay_workbench_session_scope AS scope_check
    WHERE scope_check.session_id = p_session_id
      AND scope_check.candidate_id = p_candidate_id
    LIMIT 1;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_PREVIEW_ROWS_MATERIALISE_CANDIDATE_NOT_IN_SCOPE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_PREVIEW_ROWS_MATERIALISE_CANDIDATE_NOT_IN_SCOPE',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text
              )::text;
    END IF;
  ELSIF v_cursor_has_scope IS NOT TRUE THEN
    v_cursor_scope_ordinal := -1;
    v_cursor_line_ordinal := -1;
    v_cursor_line_work_id := NULL::uuid;
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_preview_materialise;
  CREATE TEMP TABLE _tmp_pay_wb_preview_materialise ON COMMIT DROP AS
  WITH ready_rows AS (
    SELECT
      line_work.id,
      line_work.session_id,
      line_work.candidate_id,
      line_work.timesheet_id,
      line_work.line_key,
      line_work.line_ordinal,
      line_work.result_row_json,
      COALESCE(scope_row.scope_ordinal, 0)::bigint AS scope_ordinal,
      ROW_NUMBER() OVER (
        ORDER BY COALESCE(scope_row.scope_ordinal, 0), line_work.line_ordinal, line_work.id
      ) AS page_ordinal
    FROM public.banking_pay_workbench_candidate_line_work AS line_work
    JOIN public.banking_pay_workbench_session_scope AS scope_row
      ON scope_row.session_id = line_work.session_id
     AND scope_row.candidate_id = line_work.candidate_id
    WHERE line_work.session_id = p_session_id
      AND (p_candidate_id IS NULL OR line_work.candidate_id = p_candidate_id)
      AND UPPER(BTRIM(COALESCE(line_work.status, ''))) = 'READY'
      AND line_work.result_row_json IS NOT NULL
      AND jsonb_typeof(line_work.result_row_json) = 'object'
      AND LOWER(BTRIM(COALESCE(line_work.result_row_json#>>'{preview_contract,ok}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(line_work.result_row_json#>>'{preview_contract,materialisable}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND public.pay_workbench_preview_section_from_line_json(line_work.result_row_json) IN (
        'canonical_preview_lines',
        'cases_resolutions',
        'blocked_for_pay'
      )
      AND (
        COALESCE(scope_row.scope_ordinal, 0)::bigint > COALESCE(v_cursor_scope_ordinal, -1)
        OR (
          COALESCE(scope_row.scope_ordinal, 0)::bigint = COALESCE(v_cursor_scope_ordinal, -1)
          AND line_work.line_ordinal > COALESCE(v_cursor_line_ordinal, -1)
        )
        OR (
          COALESCE(scope_row.scope_ordinal, 0)::bigint = COALESCE(v_cursor_scope_ordinal, -1)
          AND line_work.line_ordinal = COALESCE(v_cursor_line_ordinal, -1)
          AND v_cursor_line_work_id IS NOT NULL
          AND line_work.id > v_cursor_line_work_id
        )
      )
    ORDER BY COALESCE(scope_row.scope_ordinal, 0), line_work.line_ordinal, line_work.id
    LIMIT (v_limit + 1)
  ), ready_source_rows AS (
    SELECT
      ready_rows.*,
      ready_rows.timesheet_id AS line_work_timesheet_id,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(ready_rows.result_row_json#>>'{economic_key,timesheet_id}', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(ready_rows.result_row_json#>>'{economic_key,timesheet_id}', '')), '')::uuid
        ELSE NULL::uuid
      END AS economic_key_timesheet_id,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(ready_rows.result_row_json->>'timesheet_id', ready_rows.result_row_json->>'real_business_timesheet_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(ready_rows.result_row_json->>'timesheet_id', ready_rows.result_row_json->>'real_business_timesheet_id', '')), '')::uuid
        ELSE NULL::uuid
      END AS result_row_timesheet_id
    FROM ready_rows
  ), ready_timesheet_refs AS (
    SELECT ready_source_rows.id, 'LINE_WORK'::text AS source_label, ready_source_rows.line_work_timesheet_id AS source_timesheet_id
    FROM ready_source_rows
    WHERE ready_source_rows.line_work_timesheet_id IS NOT NULL
    UNION ALL
    SELECT ready_source_rows.id, 'ECONOMIC_KEY'::text AS source_label, ready_source_rows.economic_key_timesheet_id AS source_timesheet_id
    FROM ready_source_rows
    WHERE ready_source_rows.economic_key_timesheet_id IS NOT NULL
    UNION ALL
    SELECT ready_source_rows.id, 'RESULT_ROW'::text AS source_label, ready_source_rows.result_row_timesheet_id AS source_timesheet_id
    FROM ready_source_rows
    WHERE ready_source_rows.result_row_timesheet_id IS NOT NULL
  ), ready_timesheet_id_array AS (
    SELECT COALESCE(
      array_agg(DISTINCT ready_timesheet_refs.source_timesheet_id ORDER BY ready_timesheet_refs.source_timesheet_id),
      array[]::uuid[]
    ) AS timesheet_ids
    FROM ready_timesheet_refs
  ), rotation_scope_rows AS (
    SELECT
      rotation_scope.requested_timesheet_id,
      rotation_scope.canonical_timesheet_id,
      rotation_scope.family_timesheet_id,
      rotation_scope.family_is_current,
      rotation_scope.family_version,
      rotation_scope.requested_is_canonical
    FROM ready_timesheet_id_array
    JOIN public._pay_timesheet_rotation_scope(ready_timesheet_id_array.timesheet_ids) AS rotation_scope
      ON true
  ), rotation_scope_by_requested AS (
    SELECT DISTINCT ON (rotation_scope_rows.requested_timesheet_id)
      rotation_scope_rows.requested_timesheet_id,
      COALESCE(rotation_scope_rows.canonical_timesheet_id, rotation_scope_rows.requested_timesheet_id) AS canonical_timesheet_id,
      (rotation_scope_rows.family_timesheet_id IS NOT NULL AND rotation_scope_rows.family_is_current IS NOT NULL) AS rotation_scope_resolved
    FROM rotation_scope_rows
    WHERE rotation_scope_rows.requested_timesheet_id IS NOT NULL
    ORDER BY
      rotation_scope_rows.requested_timesheet_id,
      rotation_scope_rows.family_is_current DESC NULLS LAST,
      rotation_scope_rows.family_version DESC NULLS LAST,
      rotation_scope_rows.family_timesheet_id
  ), canonical_ready_rows AS (
    SELECT
      ready_source_rows.id,
      ready_source_rows.session_id,
      ready_source_rows.candidate_id,
      COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id) AS timesheet_id,
      ready_source_rows.line_work_timesheet_id,
      ready_source_rows.economic_key_timesheet_id,
      ready_source_rows.result_row_timesheet_id,
      ready_source_rows.line_key,
      ready_source_rows.line_ordinal,
      CASE
        WHEN COALESCE(ready_source_rows.scope_ordinal, 0) > 0 THEN (ready_source_rows.scope_ordinal * 1000000) + ready_source_rows.line_ordinal
        ELSE ready_source_rows.line_ordinal
      END AS stable_row_ordinal,
      jsonb_strip_nulls(
        CASE
          WHEN COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id) IS NULL THEN ready_source_rows.result_row_json
          ELSE ready_source_rows.result_row_json
            || jsonb_build_object(
              'timesheet_id', COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id)::text,
              'real_business_timesheet_id', COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id)::text,
              'economic_key', COALESCE(ready_source_rows.result_row_json->'economic_key', '{}'::jsonb)
                || jsonb_build_object('timesheet_id', COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id)::text)
            )
            || CASE
              WHEN ready_source_rows.line_work_timesheet_id IS DISTINCT FROM COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id)
                OR ready_source_rows.economic_key_timesheet_id IS DISTINCT FROM COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id)
                OR ready_source_rows.result_row_timesheet_id IS DISTINCT FROM COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id)
              THEN jsonb_build_object(
                'rotation_requested_timesheet_ids', jsonb_strip_nulls(jsonb_build_object(
                  'line_work_timesheet_id', CASE WHEN ready_source_rows.line_work_timesheet_id IS NULL THEN NULL ELSE ready_source_rows.line_work_timesheet_id::text END,
                  'economic_key_timesheet_id', CASE WHEN ready_source_rows.economic_key_timesheet_id IS NULL THEN NULL ELSE ready_source_rows.economic_key_timesheet_id::text END,
                  'result_row_timesheet_id', CASE WHEN ready_source_rows.result_row_timesheet_id IS NULL THEN NULL ELSE ready_source_rows.result_row_timesheet_id::text END
                ))
              )
              ELSE '{}'::jsonb
            END
        END
      ) AS result_row_json,
      ready_source_rows.scope_ordinal,
      ready_source_rows.page_ordinal,
      public.pay_workbench_preview_section_from_line_json(
        CASE
          WHEN COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id) IS NULL THEN ready_source_rows.result_row_json
          ELSE ready_source_rows.result_row_json
            || jsonb_build_object(
              'timesheet_id', COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id)::text,
              'economic_key', COALESCE(ready_source_rows.result_row_json->'economic_key', '{}'::jsonb)
                || jsonb_build_object('timesheet_id', COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id)::text)
            )
        END
      ) AS target_section,
      CASE
        WHEN ready_source_rows.line_work_timesheet_id IS NULL
         AND ready_source_rows.economic_key_timesheet_id IS NULL
         AND ready_source_rows.result_row_timesheet_id IS NULL THEN false
        WHEN COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id) IS NULL THEN true
        WHEN ready_source_rows.line_work_timesheet_id IS NOT NULL AND COALESCE(line_work_rotation.rotation_scope_resolved, false) = false THEN true
        WHEN ready_source_rows.economic_key_timesheet_id IS NOT NULL AND COALESCE(economic_key_rotation.rotation_scope_resolved, false) = false THEN true
        WHEN ready_source_rows.result_row_timesheet_id IS NOT NULL AND COALESCE(result_row_rotation.rotation_scope_resolved, false) = false THEN true
        WHEN line_work_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND line_work_rotation.canonical_timesheet_id IS DISTINCT FROM economic_key_rotation.canonical_timesheet_id THEN true
        WHEN line_work_rotation.canonical_timesheet_id IS NOT NULL
         AND result_row_rotation.canonical_timesheet_id IS NOT NULL
         AND line_work_rotation.canonical_timesheet_id IS DISTINCT FROM result_row_rotation.canonical_timesheet_id THEN true
        WHEN economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND result_row_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS DISTINCT FROM result_row_rotation.canonical_timesheet_id THEN true
        ELSE false
      END AS rotation_validation_failed,
      CASE
        WHEN ready_source_rows.line_work_timesheet_id IS NULL
         AND ready_source_rows.economic_key_timesheet_id IS NULL
         AND ready_source_rows.result_row_timesheet_id IS NULL THEN NULL::text
        WHEN COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id) IS NULL THEN 'ROTATION_CANONICAL_TIMESHEET_NOT_RESOLVED'
        WHEN ready_source_rows.line_work_timesheet_id IS NOT NULL AND COALESCE(line_work_rotation.rotation_scope_resolved, false) = false THEN 'LINE_WORK_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
        WHEN ready_source_rows.economic_key_timesheet_id IS NOT NULL AND COALESCE(economic_key_rotation.rotation_scope_resolved, false) = false THEN 'ECONOMIC_KEY_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
        WHEN ready_source_rows.result_row_timesheet_id IS NOT NULL AND COALESCE(result_row_rotation.rotation_scope_resolved, false) = false THEN 'RESULT_ROW_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
        WHEN line_work_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND line_work_rotation.canonical_timesheet_id IS DISTINCT FROM economic_key_rotation.canonical_timesheet_id THEN 'LINE_WORK_AND_ECONOMIC_KEY_CANONICAL_TIMESHEET_MISMATCH'
        WHEN line_work_rotation.canonical_timesheet_id IS NOT NULL
         AND result_row_rotation.canonical_timesheet_id IS NOT NULL
         AND line_work_rotation.canonical_timesheet_id IS DISTINCT FROM result_row_rotation.canonical_timesheet_id THEN 'LINE_WORK_AND_RESULT_ROW_CANONICAL_TIMESHEET_MISMATCH'
        WHEN economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND result_row_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS DISTINCT FROM result_row_rotation.canonical_timesheet_id THEN 'ECONOMIC_KEY_AND_RESULT_ROW_CANONICAL_TIMESHEET_MISMATCH'
        ELSE NULL::text
      END AS rotation_failure_reason
    FROM ready_source_rows
    LEFT JOIN rotation_scope_by_requested AS line_work_rotation
      ON line_work_rotation.requested_timesheet_id = ready_source_rows.line_work_timesheet_id
    LEFT JOIN rotation_scope_by_requested AS economic_key_rotation
      ON economic_key_rotation.requested_timesheet_id = ready_source_rows.economic_key_timesheet_id
    LEFT JOIN rotation_scope_by_requested AS result_row_rotation
      ON result_row_rotation.requested_timesheet_id = ready_source_rows.result_row_timesheet_id
  ), component_probe_rows AS (
    SELECT
      canonical_ready_rows.*,
      component_probe.selected_amount_ex_vat AS fixed_reimbursement_original_amount_ex_vat,
      component_probe.single_fixed_reimbursement_key_type,
      component_probe.single_fixed_reimbursement_key_value
    FROM canonical_ready_rows
    CROSS JOIN LATERAL (
      SELECT
        CASE WHEN NULLIF(BTRIM(COALESCE(canonical_ready_rows.result_row_json->>'amount_ex_vat', canonical_ready_rows.result_row_json->>'preview_amount_ex_vat', '')), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(NULLIF(BTRIM(COALESCE(canonical_ready_rows.result_row_json->>'amount_ex_vat', canonical_ready_rows.result_row_json->>'preview_amount_ex_vat', '')), '')::numeric, 2)
          ELSE NULL::numeric
        END AS selected_amount_ex_vat,
        CASE
          WHEN component_counts.object_component_count = 1
           AND component_counts.fixed_reimbursement_component_count = 1 THEN component_counts.fixed_reimbursement_key_type
          ELSE NULL::text
        END AS single_fixed_reimbursement_key_type,
        CASE
          WHEN component_counts.object_component_count = 1
           AND component_counts.fixed_reimbursement_component_count = 1 THEN component_counts.fixed_reimbursement_key_value
          ELSE NULL::text
        END AS single_fixed_reimbursement_key_value
      FROM (
        SELECT
          (COUNT(*) FILTER (
            WHERE component_element.value IS NOT NULL
              AND jsonb_typeof(component_element.value) = 'object'
          ))::integer AS object_component_count,
          (COUNT(*) FILTER (
            WHERE component_element.value IS NOT NULL
              AND jsonb_typeof(component_element.value) = 'object'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
              AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
          ))::integer AS fixed_reimbursement_component_count,
          MAX(UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), ''))) FILTER (
            WHERE component_element.value IS NOT NULL
              AND jsonb_typeof(component_element.value) = 'object'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
              AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
          ) AS fixed_reimbursement_key_type,
          MAX(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '')) FILTER (
            WHERE component_element.value IS NOT NULL
              AND jsonb_typeof(component_element.value) = 'object'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
              AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
          ) AS fixed_reimbursement_key_value
        FROM jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(canonical_ready_rows.result_row_json->'case_components') = 'array' THEN canonical_ready_rows.result_row_json->'case_components'
            ELSE '[]'::jsonb
          END
        ) AS component_element(value)
      ) AS component_counts
    ) AS component_probe
  ), outstanding_timesheet_ids AS (
    SELECT COALESCE(
      array_agg(DISTINCT component_probe_rows.timesheet_id ORDER BY component_probe_rows.timesheet_id),
      array[]::uuid[]
    ) AS timesheet_ids
    FROM component_probe_rows
    WHERE component_probe_rows.page_ordinal <= v_limit
      AND component_probe_rows.rotation_validation_failed IS NOT TRUE
      AND component_probe_rows.timesheet_id IS NOT NULL
      AND component_probe_rows.single_fixed_reimbursement_key_type IS NOT NULL
  ), outstanding_component_rows AS (
    SELECT
      outstanding_components.timesheet_id,
      outstanding_components.key_type,
      outstanding_components.key_value,
      outstanding_components.outstanding_ex_vat
    FROM outstanding_timesheet_ids
    JOIN public._pay_outstanding_components(outstanding_timesheet_ids.timesheet_ids, NULL::uuid) AS outstanding_components
      ON true
  ), selected_rows AS (
    SELECT
      component_probe_rows.*,
      (
        component_probe_rows.single_fixed_reimbursement_key_type IS NOT NULL
        AND (
          UPPER(NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_type}', component_probe_rows.result_row_json->>'key_type', '')), '')) IS DISTINCT FROM component_probe_rows.single_fixed_reimbursement_key_type
          OR NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_value}', component_probe_rows.result_row_json->>'key_value', '')), '') IS DISTINCT FROM component_probe_rows.single_fixed_reimbursement_key_value
        )
      ) AS fixed_reimbursement_key_mismatch,
      (
        component_probe_rows.single_fixed_reimbursement_key_type IS NOT NULL
        AND component_probe_rows.fixed_reimbursement_original_amount_ex_vat IS NOT NULL
        AND ROUND(ABS(COALESCE(component_probe_rows.fixed_reimbursement_original_amount_ex_vat, 0)), 2) > 0
        AND (
          outstanding_component_rows.outstanding_ex_vat IS NULL
          OR ROUND(COALESCE(outstanding_component_rows.outstanding_ex_vat, 0), 2) <= 0
        )
      ) AS fixed_reimbursement_not_outstanding,
      (
        component_probe_rows.single_fixed_reimbursement_key_type IS NOT NULL
        AND component_probe_rows.fixed_reimbursement_original_amount_ex_vat IS NOT NULL
        AND ROUND(ABS(COALESCE(component_probe_rows.fixed_reimbursement_original_amount_ex_vat, 0)), 2) > 0
        AND outstanding_component_rows.outstanding_ex_vat IS NOT NULL
        AND ROUND(COALESCE(outstanding_component_rows.outstanding_ex_vat, 0), 2) = 0
        AND UPPER(NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_type}', component_probe_rows.result_row_json->>'key_type', '')), '')) = component_probe_rows.single_fixed_reimbursement_key_type
        AND NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_value}', component_probe_rows.result_row_json->>'key_value', '')), '') = component_probe_rows.single_fixed_reimbursement_key_value
      ) AS suppress_zero_outstanding_fixed_reimbursement,
      (
        component_probe_rows.single_fixed_reimbursement_key_type IS NOT NULL
        AND component_probe_rows.fixed_reimbursement_original_amount_ex_vat IS NOT NULL
        AND outstanding_component_rows.outstanding_ex_vat IS NOT NULL
        AND ROUND(COALESCE(outstanding_component_rows.outstanding_ex_vat, 0), 2) > 0
        AND ROUND(ABS(COALESCE(component_probe_rows.fixed_reimbursement_original_amount_ex_vat, 0)), 2) > ROUND(ABS(COALESCE(outstanding_component_rows.outstanding_ex_vat, 0)), 2)
        AND UPPER(NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_type}', component_probe_rows.result_row_json->>'key_type', '')), '')) = component_probe_rows.single_fixed_reimbursement_key_type
        AND NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_value}', component_probe_rows.result_row_json->>'key_value', '')), '') = component_probe_rows.single_fixed_reimbursement_key_value
      ) AS clamp_fixed_reimbursement_to_outstanding,
      ROUND(COALESCE(outstanding_component_rows.outstanding_ex_vat, 0), 2) AS fixed_reimbursement_outstanding_ex_vat,
      CASE
        WHEN component_probe_rows.rotation_validation_failed IS NOT TRUE
         AND component_probe_rows.target_section = 'canonical_preview_lines'
         AND LOWER(BTRIM(COALESCE(component_probe_rows.result_row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
         AND LOWER(BTRIM(COALESCE(component_probe_rows.result_row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
         AND LOWER(BTRIM(COALESCE(component_probe_rows.result_row_json->>'is_excluded_from_allocation', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
         AND LOWER(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{preview_contract,selection_allowed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
         AND NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_type}', '')), '') IS NOT NULL
         AND NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_value}', '')), '') IS NOT NULL
         AND NOT (
           component_probe_rows.single_fixed_reimbursement_key_type IS NOT NULL
           AND (
             UPPER(NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_type}', component_probe_rows.result_row_json->>'key_type', '')), '')) IS DISTINCT FROM component_probe_rows.single_fixed_reimbursement_key_type
             OR NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_value}', component_probe_rows.result_row_json->>'key_value', '')), '') IS DISTINCT FROM component_probe_rows.single_fixed_reimbursement_key_value
           )
         )
         AND NOT (
           component_probe_rows.single_fixed_reimbursement_key_type IS NOT NULL
           AND component_probe_rows.fixed_reimbursement_original_amount_ex_vat IS NOT NULL
           AND ROUND(ABS(COALESCE(component_probe_rows.fixed_reimbursement_original_amount_ex_vat, 0)), 2) > 0
           AND (
             outstanding_component_rows.outstanding_ex_vat IS NULL
             OR ROUND(COALESCE(outstanding_component_rows.outstanding_ex_vat, 0), 2) <= 0
           )
         )
        THEN true
        ELSE false
      END AS target_selected
    FROM component_probe_rows
    LEFT JOIN outstanding_component_rows
      ON outstanding_component_rows.timesheet_id = component_probe_rows.timesheet_id
     AND outstanding_component_rows.key_type = component_probe_rows.single_fixed_reimbursement_key_type
     AND outstanding_component_rows.key_value = component_probe_rows.single_fixed_reimbursement_key_value
  )
  SELECT selected_rows.*,
         CASE
           WHEN selected_rows.target_selected THEN 'SELECTED'
           ELSE 'NOT_SELECTABLE'
         END AS target_selection_state,
         existing_preview.id AS existing_preview_row_id
  FROM selected_rows
  LEFT JOIN public.banking_pay_workbench_preview_rows AS existing_preview
    ON existing_preview.session_id = p_session_id
   AND existing_preview.section = selected_rows.target_section
   AND existing_preview.candidate_id = selected_rows.candidate_id
   AND existing_preview.row_key = selected_rows.line_key;

  SELECT COUNT(*)::integer
  INTO v_raw_count
  FROM pg_temp._tmp_pay_wb_preview_materialise AS materialise_rows;

  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE materialise_rows.target_selected)::integer
  INTO v_new_preview_row_count, v_new_selected_row_count
  FROM pg_temp._tmp_pay_wb_preview_materialise AS materialise_rows
  WHERE materialise_rows.page_ordinal <= v_limit
    AND materialise_rows.existing_preview_row_id IS NULL
    AND materialise_rows.rotation_validation_failed IS NOT TRUE
    AND materialise_rows.suppress_zero_outstanding_fixed_reimbursement IS NOT TRUE;

  SELECT COUNT(*)::integer
  INTO v_suppressed_preview_row_count
  FROM pg_temp._tmp_pay_wb_preview_materialise AS materialise_rows
  WHERE materialise_rows.page_ordinal <= v_limit
    AND materialise_rows.suppress_zero_outstanding_fixed_reimbursement IS TRUE;

  SELECT COUNT(*)::integer
  INTO v_materialise_error_count
  FROM pg_temp._tmp_pay_wb_preview_materialise AS materialise_rows
  WHERE materialise_rows.page_ordinal <= v_limit
    AND materialise_rows.rotation_validation_failed IS TRUE;

  SELECT COALESCE(jsonb_object_agg(section_delta.target_section, section_delta.section_count ORDER BY section_delta.target_section), '{}'::jsonb)
  INTO v_section_delta_json
  FROM (
    SELECT materialise_rows.target_section, COUNT(*)::integer AS section_count
    FROM pg_temp._tmp_pay_wb_preview_materialise AS materialise_rows
    WHERE materialise_rows.page_ordinal <= v_limit
      AND materialise_rows.existing_preview_row_id IS NULL
      AND materialise_rows.rotation_validation_failed IS NOT TRUE
      AND materialise_rows.suppress_zero_outstanding_fixed_reimbursement IS NOT TRUE
    GROUP BY materialise_rows.target_section
  ) AS section_delta;

  WITH selected_rows AS (
    SELECT materialise_rows.*
    FROM pg_temp._tmp_pay_wb_preview_materialise AS materialise_rows
    WHERE materialise_rows.page_ordinal <= v_limit
  ), visible_rows AS (
    SELECT selected_rows.*
    FROM selected_rows
    WHERE selected_rows.rotation_validation_failed IS NOT TRUE
      AND selected_rows.suppress_zero_outstanding_fixed_reimbursement IS NOT TRUE
  ), suppressed_existing_preview AS (
    UPDATE public.banking_pay_workbench_preview_rows AS preview_row
    SET status = 'SUPERSEDED',
        selected = false,
        selection_state = 'SUPERSEDED',
        row_json = COALESCE(preview_row.row_json, '{}'::jsonb)
          || jsonb_build_object(
            'materialisation_suppressed', true,
            'materialisation_suppressed_reason', 'ZERO_OUTSTANDING_FIXED_REIMBURSEMENT',
            'materialisation_suppressed_at_utc', v_now::text,
            'materialised_no_visible_preview_row', true,
            'pay_outstanding_blocked', true,
            'outstanding_block_reason', 'REIMBURSEMENT_OUTSTANDING_NOT_AVAILABLE'
          ),
        updated_at_utc = v_now
    FROM selected_rows
    WHERE preview_row.id = selected_rows.existing_preview_row_id
      AND selected_rows.suppress_zero_outstanding_fixed_reimbursement IS TRUE
      AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) <> 'SUPERSEDED'
    RETURNING preview_row.id
  ), upserted_preview AS (
    INSERT INTO public.banking_pay_workbench_preview_rows (
      session_id,
      candidate_id,
      section,
      row_key,
      row_ordinal,
      row_json,
      timesheet_id,
      key_type,
      key_value,
      selected,
      selection_state,
      status,
      session_version,
      created_at_utc,
      updated_at_utc
    )
    SELECT
      p_session_id,
      selected_rows.candidate_id,
      selected_rows.target_section,
      selected_rows.line_key,
      selected_rows.stable_row_ordinal,
      selected_rows.result_row_json
        || CASE
          WHEN selected_rows.fixed_reimbursement_key_mismatch THEN jsonb_build_object(
            'draftable', false,
            'is_ready_for_draft', false,
            'selection_allowed', false,
            'pay_outstanding_blocked', true,
            'outstanding_block_reason', 'REIMBURSEMENT_KEY_MISMATCH'
          )
          WHEN selected_rows.fixed_reimbursement_not_outstanding THEN jsonb_build_object(
            'draftable', false,
            'is_ready_for_draft', false,
            'selection_allowed', false,
            'pay_outstanding_blocked', true,
            'outstanding_block_reason', 'REIMBURSEMENT_OUTSTANDING_NOT_AVAILABLE'
          )
          WHEN selected_rows.clamp_fixed_reimbursement_to_outstanding THEN (
            jsonb_build_object(
              'amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'preview_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'amount_display', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'section_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'section_non_segment_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'target_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
            )
            || jsonb_build_object(
              'ready_preview_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'preview_component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'source_entitlement_amount_ex_vat', ABS(selected_rows.fixed_reimbursement_outstanding_ex_vat),
              'source_reservation_amount_ex_vat', ABS(selected_rows.fixed_reimbursement_outstanding_ex_vat),
              'source_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
            )
            || jsonb_build_object(
              'source_basis_json', COALESCE(selected_rows.result_row_json->'source_basis_json', '{}'::jsonb)
                || jsonb_build_object(
                  'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'pay_outstanding_clamped', true,
                  'original_source_pay_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
                ),
              'frozen_source_basis_json', COALESCE(selected_rows.result_row_json->'frozen_source_basis_json', selected_rows.result_row_json->'source_basis_json', '{}'::jsonb)
                || jsonb_build_object(
                  'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'pay_outstanding_clamped', true,
                  'original_source_pay_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
                ),
              'frozen_component_snapshot_json', COALESCE(selected_rows.result_row_json->'frozen_component_snapshot_json', '{}'::jsonb)
                || jsonb_build_object(
                  'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'target_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'preview_component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
                )
                || jsonb_build_object(
                  'source_basis_json', COALESCE(selected_rows.result_row_json#>'{frozen_component_snapshot_json,source_basis_json}', '{}'::jsonb)
                    || jsonb_build_object(
                      'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                      'pay_outstanding_clamped', true,
                      'original_source_pay_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
                    )
                )
            )
            || jsonb_build_object(
              'remaining_source_amount', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'frozen_source_amount', ABS(selected_rows.fixed_reimbursement_outstanding_ex_vat),
              'frozen_target_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'pay_outstanding_clamped', true,
              'pay_outstanding_original_amount_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
            )
            || jsonb_build_object(
              'pay_outstanding_clamped_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'pay_outstanding_available_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'pay_outstanding_blocked', false,
              'outstanding_block_reason', NULL,
              'case_components', (
                SELECT COALESCE(jsonb_agg(
                  CASE
                    WHEN component_element.value IS NOT NULL
                     AND jsonb_typeof(component_element.value) = 'object' THEN
                      component_element.value
                      || jsonb_build_object(
                        'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'target_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'ready_preview_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'preview_component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
                      )
                      || jsonb_build_object(
                        'remaining_source_amount', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'pay_outstanding_clamped', true,
                        'pay_outstanding_original_amount_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat,
                        'pay_outstanding_clamped_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'source_basis_json', COALESCE(component_element.value->'source_basis_json', '{}'::jsonb)
                          || jsonb_build_object(
                            'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                            'pay_outstanding_clamped', true,
                            'original_source_pay_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
                          )
                      )
                    ELSE component_element.value
                  END
                  ORDER BY component_element.ordinality
                ), '[]'::jsonb)
                FROM jsonb_array_elements(
                  CASE
                    WHEN jsonb_typeof(selected_rows.result_row_json->'case_components') = 'array' THEN selected_rows.result_row_json->'case_components'
                    ELSE '[]'::jsonb
                  END
                ) WITH ORDINALITY AS component_element(value, ordinality)
              )
            )
            || CASE
              WHEN jsonb_typeof(selected_rows.result_row_json->'case_resolution_summary') = 'object' THEN jsonb_build_object(
                'case_resolution_summary',
                selected_rows.result_row_json->'case_resolution_summary'
                || jsonb_build_object(
                  'safe_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'blocked_case_amount_ex_vat', 0,
                  'unresolved_taxable_amount_ex_vat', 0,
                  'pay_outstanding_clamped', true,
                  'pay_outstanding_original_amount_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat,
                  'pay_outstanding_clamped_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
                )
              )
              ELSE '{}'::jsonb
            END
            || CASE
              WHEN COALESCE(selected_rows.result_row_json->>'section_amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
               AND COALESCE(selected_rows.result_row_json->>'amount_ex_vat', selected_rows.result_row_json->>'preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
               AND ROUND(ABS(COALESCE(selected_rows.fixed_reimbursement_original_amount_ex_vat, 0)), 2) > 0 THEN jsonb_build_object(
                'section_amount_display', ROUND(
                  selected_rows.fixed_reimbursement_outstanding_ex_vat
                  * ((selected_rows.result_row_json->>'section_amount_display')::numeric / selected_rows.fixed_reimbursement_original_amount_ex_vat),
                  2
                )
              )
              ELSE '{}'::jsonb
            END
          )
          ELSE '{}'::jsonb
        END
        || jsonb_build_object(
          'materialised_at_utc', v_now::text,
          'materialised_from_line_work_id', selected_rows.id::text,
          'scope_ordinal', selected_rows.scope_ordinal,
          'stable_row_ordinal', selected_rows.stable_row_ordinal,
          'section', selected_rows.target_section,
          'selected', selected_rows.target_selected,
          'selection_state', selected_rows.target_selection_state
        ),
      selected_rows.timesheet_id,
      NULLIF(BTRIM(COALESCE(selected_rows.result_row_json#>>'{economic_key,key_type}', '')), ''),
      NULLIF(BTRIM(COALESCE(selected_rows.result_row_json#>>'{economic_key,key_value}', '')), ''),
      selected_rows.target_selected,
      selected_rows.target_selection_state,
      'READY',
      COALESCE(v_session_row.version, 1),
      v_now,
      v_now
    FROM visible_rows AS selected_rows
    ON CONFLICT (session_id, section, candidate_id, row_key)
    DO UPDATE
    SET row_ordinal = EXCLUDED.row_ordinal,
        row_json = EXCLUDED.row_json,
        timesheet_id = EXCLUDED.timesheet_id,
        key_type = EXCLUDED.key_type,
        key_value = EXCLUDED.key_value,
        selected = EXCLUDED.selected,
        selection_state = EXCLUDED.selection_state,
        status = EXCLUDED.status,
        session_version = EXCLUDED.session_version,
        updated_at_utc = v_now
    RETURNING public.banking_pay_workbench_preview_rows.id
  ), marked_line_work AS (
    UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
    SET status = CASE WHEN selected_rows.rotation_validation_failed IS TRUE THEN 'ERROR' ELSE 'MATERIALISED' END,
        result_row_json = CASE
          WHEN selected_rows.rotation_validation_failed IS TRUE THEN
            COALESCE(line_work.result_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'draftable', false,
              'is_ready_for_draft', false,
              'selection_allowed', false,
              'row_processing_status', 'ERROR',
              'rotation_validation_failed', true,
              'rotation_failure_reason', selected_rows.rotation_failure_reason
            )
          WHEN selected_rows.suppress_zero_outstanding_fixed_reimbursement IS TRUE THEN
            COALESCE(line_work.result_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'draftable', false,
              'is_ready_for_draft', false,
              'selection_allowed', false,
              'pay_outstanding_blocked', true,
              'outstanding_block_reason', 'REIMBURSEMENT_OUTSTANDING_NOT_AVAILABLE'
            )
            || jsonb_build_object(
              'materialisation_suppressed', true,
              'materialisation_suppressed_reason', 'ZERO_OUTSTANDING_FIXED_REIMBURSEMENT',
              'materialisation_suppressed_at_utc', v_now::text,
              'materialised_no_visible_preview_row', true,
              'presentation_role', 'HIDDEN',
              'presentation_section', 'INTERNAL_ONLY'
            )
          WHEN selected_rows.clamp_fixed_reimbursement_to_outstanding IS TRUE THEN
            COALESCE(line_work.result_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'preview_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'amount_display', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'section_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'section_non_segment_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'target_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
            )
            || jsonb_build_object(
              'ready_preview_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'preview_component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'source_entitlement_amount_ex_vat', ABS(selected_rows.fixed_reimbursement_outstanding_ex_vat),
              'source_reservation_amount_ex_vat', ABS(selected_rows.fixed_reimbursement_outstanding_ex_vat),
              'source_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
            )
            || jsonb_build_object(
              'source_basis_json', COALESCE(line_work.result_row_json->'source_basis_json', '{}'::jsonb)
                || jsonb_build_object(
                  'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'pay_outstanding_clamped', true,
                  'original_source_pay_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
                ),
              'frozen_source_basis_json', COALESCE(line_work.result_row_json->'frozen_source_basis_json', line_work.result_row_json->'source_basis_json', '{}'::jsonb)
                || jsonb_build_object(
                  'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'pay_outstanding_clamped', true,
                  'original_source_pay_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
                ),
              'frozen_component_snapshot_json', COALESCE(line_work.result_row_json->'frozen_component_snapshot_json', '{}'::jsonb)
                || jsonb_build_object(
                  'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'target_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'preview_component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
                )
                || jsonb_build_object(
                  'source_basis_json', COALESCE(line_work.result_row_json#>'{frozen_component_snapshot_json,source_basis_json}', '{}'::jsonb)
                    || jsonb_build_object(
                      'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                      'pay_outstanding_clamped', true,
                      'original_source_pay_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
                    )
                )
            )
            || jsonb_build_object(
              'remaining_source_amount', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'frozen_source_amount', ABS(selected_rows.fixed_reimbursement_outstanding_ex_vat),
              'frozen_target_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'pay_outstanding_clamped', true,
              'pay_outstanding_original_amount_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
            )
            || jsonb_build_object(
              'pay_outstanding_clamped_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'pay_outstanding_available_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'pay_outstanding_blocked', false,
              'outstanding_block_reason', NULL,
              'case_components', (
                SELECT COALESCE(jsonb_agg(
                  CASE
                    WHEN component_element.value IS NOT NULL
                     AND jsonb_typeof(component_element.value) = 'object' THEN
                      component_element.value
                      || jsonb_build_object(
                        'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'target_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'ready_preview_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'preview_component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
                      )
                      || jsonb_build_object(
                        'remaining_source_amount', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'pay_outstanding_clamped', true,
                        'pay_outstanding_original_amount_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat,
                        'pay_outstanding_clamped_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'source_basis_json', COALESCE(component_element.value->'source_basis_json', '{}'::jsonb)
                          || jsonb_build_object(
                            'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                            'pay_outstanding_clamped', true,
                            'original_source_pay_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
                          )
                      )
                    ELSE component_element.value
                  END
                  ORDER BY component_element.ordinality
                ), '[]'::jsonb)
                FROM jsonb_array_elements(
                  CASE
                    WHEN jsonb_typeof(line_work.result_row_json->'case_components') = 'array' THEN line_work.result_row_json->'case_components'
                    ELSE '[]'::jsonb
                  END
                ) WITH ORDINALITY AS component_element(value, ordinality)
              )
            )
            || CASE
              WHEN jsonb_typeof(line_work.result_row_json->'case_resolution_summary') = 'object' THEN jsonb_build_object(
                'case_resolution_summary',
                line_work.result_row_json->'case_resolution_summary'
                || jsonb_build_object(
                  'safe_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'blocked_case_amount_ex_vat', 0,
                  'unresolved_taxable_amount_ex_vat', 0,
                  'pay_outstanding_clamped', true,
                  'pay_outstanding_original_amount_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat,
                  'pay_outstanding_clamped_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
                )
              )
              ELSE '{}'::jsonb
            END
            || CASE
              WHEN COALESCE(line_work.result_row_json->>'section_amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
               AND ROUND(ABS(COALESCE(selected_rows.fixed_reimbursement_original_amount_ex_vat, 0)), 2) > 0 THEN jsonb_build_object(
                'section_amount_display', ROUND(
                  selected_rows.fixed_reimbursement_outstanding_ex_vat
                  * ((line_work.result_row_json->>'section_amount_display')::numeric / selected_rows.fixed_reimbursement_original_amount_ex_vat),
                  2
                )
              )
              ELSE '{}'::jsonb
            END
          ELSE line_work.result_row_json
        END,
        error_json = CASE
          WHEN selected_rows.rotation_validation_failed IS TRUE THEN jsonb_build_object(
            'code', 'WORKBENCH_MATERIALISE_ROTATED_TIMESHEET_MISMATCH',
            'message', 'Ready line work timesheet identities did not resolve to one current canonical timesheet at preview materialisation.',
            'line_key', selected_rows.line_key,
            'line_ordinal', selected_rows.line_ordinal,
            'scope_ordinal', selected_rows.scope_ordinal,
            'reason', selected_rows.rotation_failure_reason
          )
          ELSE line_work.error_json
        END,
        updated_at_utc = v_now
    FROM selected_rows
    WHERE line_work.id = selected_rows.id
    RETURNING line_work.id
  )
  SELECT COUNT(*)::integer
  INTO v_materialised_count
  FROM marked_line_work;

  UPDATE public.banking_pay_workbench_preview_rows AS superseded_preview_row
  SET status = 'SUPERSEDED',
      selected = false,
      selection_state = 'SUPERSEDED',
      updated_at_utc = v_now
  WHERE superseded_preview_row.session_id = p_session_id
    AND (superseded_preview_row.session_version IS DISTINCT FROM COALESCE(v_session_row.version, 1))
    AND UPPER(BTRIM(COALESCE(superseded_preview_row.status, ''))) <> 'SUPERSEDED'
    AND EXISTS (
      SELECT 1
      FROM pg_temp._tmp_pay_wb_preview_materialise AS materialise_rows
      WHERE materialise_rows.page_ordinal <= v_limit
        AND materialise_rows.candidate_id = superseded_preview_row.candidate_id
    );

  IF v_raw_count > v_limit THEN
    SELECT
      materialise_rows.scope_ordinal,
      materialise_rows.line_ordinal,
      materialise_rows.id
    INTO
      v_last_returned_scope_ordinal,
      v_last_returned_line_ordinal,
      v_last_returned_line_work_id
    FROM pg_temp._tmp_pay_wb_preview_materialise AS materialise_rows
    WHERE materialise_rows.page_ordinal = v_limit;

    v_next_cursor := jsonb_build_object(
      'last_scope_ordinal', v_last_returned_scope_ordinal,
      'last_line_ordinal', v_last_returned_line_ordinal,
      'last_line_work_id', v_last_returned_line_work_id::text
    );
  ELSE
    v_next_cursor := NULL::jsonb;
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_materialise_scope_delta;
  CREATE TEMP TABLE _tmp_pay_wb_materialise_scope_delta ON COMMIT DROP AS
  WITH affected_candidates AS (
    SELECT DISTINCT materialise_rows.candidate_id
    FROM pg_temp._tmp_pay_wb_preview_materialise AS materialise_rows
    WHERE materialise_rows.page_ordinal <= v_limit
  ), candidate_new_status AS (
    SELECT affected_candidates.candidate_id,
           CASE
             WHEN EXISTS (
               SELECT 1
               FROM public.banking_pay_workbench_candidate_line_work AS line_error
               WHERE line_error.session_id = p_session_id
                 AND line_error.candidate_id = affected_candidates.candidate_id
                 AND UPPER(BTRIM(COALESCE(line_error.status, ''))) = 'ERROR'
             ) THEN 'ERROR'
             WHEN EXISTS (
               SELECT 1
               FROM public.banking_pay_workbench_candidate_line_work AS line_remaining
               WHERE line_remaining.session_id = p_session_id
                 AND line_remaining.candidate_id = affected_candidates.candidate_id
                 AND UPPER(BTRIM(COALESCE(line_remaining.status, ''))) IN ('PENDING', 'READY')
             ) THEN 'LINE_WORK_READY'
             ELSE 'MATERIALISED'
           END AS new_status
    FROM affected_candidates
  )
  SELECT
    scope_row.candidate_id,
    UPPER(BTRIM(COALESCE(scope_row.status, 'PENDING'))) AS old_status,
    candidate_new_status.new_status
  FROM candidate_new_status
  JOIN public.banking_pay_workbench_session_scope AS scope_row
    ON scope_row.session_id = p_session_id
   AND scope_row.candidate_id = candidate_new_status.candidate_id;

  UPDATE public.banking_pay_workbench_preview_rows AS obsolete_current_preview_row
  SET status = 'SUPERSEDED',
      selected = false,
      selection_state = 'SUPERSEDED',
      updated_at_utc = v_now
  WHERE obsolete_current_preview_row.session_id = p_session_id
    AND obsolete_current_preview_row.session_version = COALESCE(v_session_row.version, 1)
    AND UPPER(BTRIM(COALESCE(obsolete_current_preview_row.status, ''))) = 'READY'
    AND EXISTS (
      SELECT 1
      FROM pg_temp._tmp_pay_wb_materialise_scope_delta AS scope_delta
      WHERE scope_delta.candidate_id = obsolete_current_preview_row.candidate_id
        AND scope_delta.new_status = 'MATERIALISED'
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_candidate_line_work AS line_work
      WHERE line_work.session_id = p_session_id
        AND line_work.candidate_id = obsolete_current_preview_row.candidate_id
        AND line_work.line_key = obsolete_current_preview_row.row_key
        AND public.pay_workbench_preview_section_from_line_json(line_work.result_row_json) = obsolete_current_preview_row.section
        AND UPPER(BTRIM(COALESCE(line_work.status, ''))) IN ('READY', 'MATERIALISED')
    );

  UPDATE public.banking_pay_workbench_session_scope AS scope_row
  SET status = scope_delta.new_status,
      dirty = scope_delta.new_status <> 'MATERIALISED',
      updated_at_utc = v_now
  FROM pg_temp._tmp_pay_wb_materialise_scope_delta AS scope_delta
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = scope_delta.candidate_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'candidate_id', scope_delta.candidate_id::text,
           'old_status', scope_delta.old_status,
           'new_status', scope_delta.new_status
         ) ORDER BY scope_delta.candidate_id), '[]'::jsonb)
  INTO v_affected_candidate_sample
  FROM (
    SELECT scope_delta.*
    FROM pg_temp._tmp_pay_wb_materialise_scope_delta AS scope_delta
    ORDER BY scope_delta.candidate_id
    LIMIT 25
  ) AS scope_delta;

  UPDATE public.banking_pay_workbench_sessions AS session_row
  SET line_units_ready = GREATEST(COALESCE(session_row.line_units_ready, 0) - COALESCE(v_materialised_count, 0), 0),
      line_units_failed = GREATEST(COALESCE(session_row.line_units_failed, 0) + COALESCE(v_materialise_error_count, 0), 0),
      preview_row_count = GREATEST(COALESCE(session_row.preview_row_count, 0) + COALESCE(v_new_preview_row_count, 0), 0),
      selected_row_count = GREATEST(COALESCE(session_row.selected_row_count, 0) + COALESCE(v_new_selected_row_count, 0), 0),
      scope_ready_count = GREATEST(COALESCE(session_row.scope_ready_count, 0)
        + COALESCE((
          SELECT COUNT(*) FILTER (WHERE scope_delta.old_status NOT IN ('READY', 'MATERIALISED', 'MATERIALIZED') AND scope_delta.new_status = 'MATERIALISED')::integer
          FROM pg_temp._tmp_pay_wb_materialise_scope_delta AS scope_delta
        ), 0), 0),
      scope_pending_count = GREATEST(COALESCE(session_row.scope_pending_count, 0)
        - COALESCE((
          SELECT COUNT(*) FILTER (WHERE scope_delta.old_status IN ('PENDING', 'QUEUED', 'RUNNING', 'LINE_WORK_PENDING', 'LINE_WORK_READY') AND scope_delta.new_status = 'MATERIALISED')::integer
          FROM pg_temp._tmp_pay_wb_materialise_scope_delta AS scope_delta
        ), 0), 0),
      section_counts_json = COALESCE((
        SELECT COALESCE(jsonb_object_agg(merged_counts.section_key, to_jsonb(merged_counts.section_count) ORDER BY merged_counts.section_key), '{}'::jsonb)
        FROM (
          SELECT all_keys.section_key,
                 GREATEST(
                   COALESCE(NULLIF(BTRIM(session_row.section_counts_json->>all_keys.section_key), '')::integer, 0)
                   + COALESCE(NULLIF(BTRIM(v_section_delta_json->>all_keys.section_key), '')::integer, 0),
                   0
                 ) AS section_count
          FROM (
            SELECT existing_sections.key AS section_key
            FROM jsonb_each(COALESCE(session_row.section_counts_json, '{}'::jsonb)) AS existing_sections(key, value)
            UNION
            SELECT delta_sections.key AS section_key
            FROM jsonb_each(COALESCE(v_section_delta_json, '{}'::jsonb)) AS delta_sections(key, value)
          ) AS all_keys
        ) AS merged_counts
      ), '{}'::jsonb),
      candidate_sample_rows_json = COALESCE(v_affected_candidate_sample, '[]'::jsonb),
      progress_state = CASE
        WHEN v_next_cursor IS NOT NULL THEN 'MATERIALISING_PREVIEW_ROWS'
        WHEN COALESCE(session_row.line_units_pending, 0) = 0
          AND GREATEST(COALESCE(session_row.line_units_ready, 0) - COALESCE(v_materialised_count, 0), 0) = 0
          AND COALESCE(session_row.line_units_failed, 0) = 0 THEN 'READY'
        ELSE COALESCE(NULLIF(BTRIM(session_row.progress_state), ''), 'PENDING')
      END,
      progress_json = COALESCE(session_row.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'last_preview_materialise_at_utc', v_now::text,
          'last_preview_materialise_count', COALESCE(v_materialised_count, 0),
          'last_preview_materialise_selected_count', COALESCE(v_new_selected_row_count, 0),
          'last_preview_materialise_suppressed_count', COALESCE(v_suppressed_preview_row_count, 0),
          'last_preview_materialise_error_count', COALESCE(v_materialise_error_count, 0),
          'last_preview_materialise_has_more', v_next_cursor IS NOT NULL
        ),
      progress_counter_version = COALESCE(session_row.progress_counter_version, 0) + 1,
      progress_updated_at_utc = v_now,
      updated_at_utc = v_now
  WHERE session_row.id = p_session_id;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'limit', v_limit,
    'cursor_scope_ordinal', COALESCE(v_cursor_scope_ordinal, -1),
    'cursor_line_ordinal', COALESCE(v_cursor_line_ordinal, -1),
    'cursor_line_work_id', CASE WHEN v_cursor_line_work_id IS NULL THEN NULL ELSE v_cursor_line_work_id::text END,
    'materialised_count', COALESCE(v_materialised_count, 0),
    'new_preview_row_count', COALESCE(v_new_preview_row_count, 0),
    'new_selected_row_count', COALESCE(v_new_selected_row_count, 0),
    'suppressed_preview_row_count', COALESCE(v_suppressed_preview_row_count, 0),
    'materialisation_error_count', COALESCE(v_materialise_error_count, 0)
  )
  || jsonb_build_object(
    'next_cursor', v_next_cursor,
    'has_more', v_next_cursor IS NOT NULL,
    'section_delta_counts', COALESCE(v_section_delta_json, '{}'::jsonb),
    'affected_candidates', COALESCE(v_affected_candidate_sample, '[]'::jsonb),
    'stable_row_ordinal_scheme', 'scope_ordinal_times_1000000_plus_line_ordinal',
    'cursor_scheme', 'last_scope_ordinal_last_line_ordinal_last_line_work_id'
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_workbench_mark_finance_case_dirty()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_trigger_table text := lower(TG_TABLE_NAME);
  v_new_row jsonb := '{}'::jsonb;
  v_old_row jsonb := '{}'::jsonb;
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_candidate_id uuid;
  v_old_finance_case_id uuid := NULL::uuid;
  v_new_finance_case_id uuid := NULL::uuid;
  v_live_change_seq bigint := 0;
  v_reason text;
  v_payload_json jsonb;
  v_dedupe_key text;
  v_scope_row record;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF TG_OP <> 'DELETE' THEN
    v_new_row := to_jsonb(NEW);
  END IF;

  IF TG_OP <> 'INSERT' THEN
    v_old_row := to_jsonb(OLD);
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_old_row->>'finance_case_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_old_finance_case_id := NULLIF(BTRIM(COALESCE(v_old_row->>'finance_case_id', '')), '')::uuid;
  END IF;
  IF NULLIF(BTRIM(COALESCE(v_new_row->>'finance_case_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_new_finance_case_id := NULLIF(BTRIM(COALESCE(v_new_row->>'finance_case_id', '')), '')::uuid;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT candidate_candidates.candidate_id ORDER BY candidate_candidates.candidate_id), ARRAY[]::uuid[])
  INTO v_candidate_ids
  FROM (
    SELECT CASE WHEN NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '')::uuid ELSE NULL::uuid END AS candidate_id
    UNION ALL
    SELECT CASE WHEN NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '')::uuid ELSE NULL::uuid END AS candidate_id
    UNION ALL
    SELECT pay_advance_old.candidate_id FROM public.pay_advances AS pay_advance_old WHERE pay_advance_old.id = v_old_finance_case_id
    UNION ALL
    SELECT pay_advance_new.candidate_id FROM public.pay_advances AS pay_advance_new WHERE pay_advance_new.id = v_new_finance_case_id
  ) AS candidate_candidates
  WHERE candidate_candidates.candidate_id IS NOT NULL;

  IF COALESCE(array_length(v_candidate_ids, 1), 0) = 0 THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    ELSE
      RETURN NEW;
    END IF;
  END IF;

  FOREACH v_candidate_id IN ARRAY v_candidate_ids
  LOOP
    PERFORM public._change_bump('pay_candidate:' || v_candidate_id::text);

    SELECT COALESCE(change_counter.seq, 0)
    INTO v_live_change_seq
    FROM public.app_change_counters AS change_counter
    WHERE change_counter.entity_key = 'pay_candidate:' || v_candidate_id::text;

    v_reason := 'DIRTY_TRIGGER:' || upper(v_trigger_table) || ':' || TG_OP;
    v_payload_json := jsonb_build_object(
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'scope_kind', 'CANDIDATE',
      'scope_id', v_candidate_id::text,
      'candidate_id', v_candidate_id::text,
      'reason', v_reason,
      'source_change_seq', v_live_change_seq,
      'old_finance_case_id', CASE WHEN v_old_finance_case_id IS NULL THEN NULL ELSE v_old_finance_case_id::text END,
      'new_finance_case_id', CASE WHEN v_new_finance_case_id IS NULL THEN NULL ELSE v_new_finance_case_id::text END,
      'row_backed_scope_required', true
    );

    FOR v_scope_row IN
      WITH affected_scope AS (
        UPDATE public.banking_pay_workbench_session_scope AS scope_row
        SET status = 'PENDING',
            dirty = true,
            error_json = NULL::jsonb,
            updated_at_utc = v_now
        FROM public.banking_pay_workbench_sessions AS session_row
        WHERE session_row.id = scope_row.session_id
          AND UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
          AND session_row.discarded_at_utc IS NULL
          AND scope_row.candidate_id = v_candidate_id
        RETURNING scope_row.session_id, scope_row.candidate_id
      )
      SELECT affected_scope.session_id, affected_scope.candidate_id
      FROM affected_scope
    LOOP
      UPDATE public.banking_pay_workbench_preview_rows AS preview_row
      SET status = 'DIRTY',
          selected = false,
          selection_state = 'DIRTY',
          row_json = jsonb_strip_nulls(COALESCE(preview_row.row_json, '{}'::jsonb) || jsonb_build_object('dirty_reason', v_reason, 'source_change_seq', v_live_change_seq)),
          updated_at_utc = v_now
      WHERE preview_row.session_id = v_scope_row.session_id
        AND preview_row.candidate_id = v_candidate_id
        AND (
          (v_old_finance_case_id IS NOT NULL AND preview_row.row_json->>'finance_case_id' = v_old_finance_case_id::text)
          OR (v_new_finance_case_id IS NOT NULL AND preview_row.row_json->>'finance_case_id' = v_new_finance_case_id::text)
        );

      UPDATE public.banking_pay_workbench_sessions AS session_update
      SET progress_state = 'DIRTY',
          scope_pending_count = GREATEST(COALESCE(session_update.scope_pending_count, 0), 1),
          candidate_sample_rows_json = jsonb_build_array(jsonb_build_object('candidate_id', v_candidate_id::text, 'status', 'PENDING', 'reason', v_reason)),
          progress_json = jsonb_strip_nulls(COALESCE(session_update.progress_json, '{}'::jsonb) || jsonb_build_object('last_dirty_candidate_id', v_candidate_id::text, 'last_dirty_reason', v_reason, 'last_dirty_at_utc', v_now::text)),
          progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE session_update.id = v_scope_row.session_id;

      v_dedupe_key := 'WORKBENCH_CANDIDATE_LINE_WORK_SEED:' || v_scope_row.session_id::text || ':' || v_candidate_id::text;
      INSERT INTO public.banking_pay_workbench_jobs (
        job_type,
        status,
        priority,
        run_at_utc,
        attempt_count,
        max_attempts,
        dedupe_key,
        snapshot_run_id,
        session_id,
        candidate_id,
        payload_json,
        created_at_utc,
        updated_at_utc,
        started_at_utc,
        completed_at_utc,
        failed_at_utc,
        last_error_json
      )
      SELECT
        'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
        'QUEUED',
        100,
        v_now,
        0,
        8,
        v_dedupe_key,
        session_job.source_snapshot_run_id,
        session_job.id,
        v_candidate_id,
        v_payload_json || jsonb_build_object('session_id', session_job.id::text),
        v_now,
        v_now,
        NULL,
        NULL,
        NULL,
        NULL
      FROM public.banking_pay_workbench_sessions AS session_job
      WHERE session_job.id = v_scope_row.session_id
      ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
      DO UPDATE
      SET priority = LEAST(public.banking_pay_workbench_jobs.priority, EXCLUDED.priority),
          run_at_utc = LEAST(public.banking_pay_workbench_jobs.run_at_utc, EXCLUDED.run_at_utc),
          payload_json = COALESCE(public.banking_pay_workbench_jobs.payload_json, '{}'::jsonb) || COALESCE(EXCLUDED.payload_json, '{}'::jsonb),
          updated_at_utc = v_now;
    END LOOP;
  END LOOP;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_workbench_prepare_draft_allocation_rows_seed(p_operation_id uuid, p_candidate_scope_ids jsonb DEFAULT NULL::jsonb)
 RETURNS TABLE(candidate_scopes_processed integer, allocation_rows_inserted integer, allocation_rows_reused integer, failures integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation public.banking_pay_operations%ROWTYPE;
  v_scope_ids jsonb := COALESCE(p_candidate_scope_ids, '[]'::jsonb);
  v_scope_id_count integer := 0;
  v_candidate_scopes_processed integer := 0;
  v_expected_count integer := 0;
  v_inserted integer := 0;
  v_reused integer := 0;
  v_malformed_allocation_preview_rows jsonb := '[]'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_allocation_rows_seed: p_operation_id is required';
  END IF;

  IF p_candidate_scope_ids IS NOT NULL AND jsonb_typeof(p_candidate_scope_ids) <> 'array' THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_allocation_rows_seed requires p_candidate_scope_ids to be null or a JSON array';
  END IF;

  IF p_candidate_scope_ids IS NOT NULL THEN
    v_scope_id_count := jsonb_array_length(v_scope_ids);
    IF v_scope_id_count = 0 THEN
      RAISE EXCEPTION 'DRAFT_ALLOCATION_SCOPE_EMPTY'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'DRAFT_ALLOCATION_SCOPE_EMPTY', 'operation_id', p_operation_id::text, 'message', 'DRAFT_CREATE allocation seeding requires at least one candidate scope id.')::text;
    END IF;
    IF v_scope_id_count > 100 THEN
      RAISE EXCEPTION 'pay_workbench_prepare_draft_allocation_rows_seed candidate scope id array exceeds the 100 row cap: %', v_scope_id_count;
    END IF;
    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_scope_ids) AS supplied_scope(scope_value)
      WHERE NOT ((supplied_scope.scope_value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
    ) THEN
      RAISE EXCEPTION 'pay_workbench_prepare_draft_allocation_rows_seed requires candidate scope ids to be UUID strings';
    END IF;
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_allocation_rows_seed operation not found: %', p_operation_id;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_operation.operation_type, ''))) <> 'DRAFT_CREATE' THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_allocation_rows_seed expected DRAFT_CREATE operation %, got %', p_operation_id, v_operation.operation_type;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_operation.status, ''))) IN ('COMPLETE', 'FAILED', 'CANCELLED', 'CANCELED', 'REVIEW_REQUIRED') THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_allocation_rows_seed cannot seed allocation rows for terminal operation % with status %', p_operation_id, v_operation.status;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_allocation_scope_rows;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_allocation_scope_rows ON COMMIT DROP AS
  SELECT scope_row.*
  FROM public.banking_pay_operation_candidate_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
    AND (
      (
        p_candidate_scope_ids IS NULL
        AND UPPER(BTRIM(COALESCE(scope_row.status, ''))) IN ('PENDING', 'SCOPED')
      )
      OR (
        p_candidate_scope_ids IS NOT NULL
        AND scope_row.id IN (
          SELECT (supplied_scope.scope_value #>> '{}')::uuid
          FROM jsonb_array_elements(v_scope_ids) AS supplied_scope(scope_value)
        )
      )
    )
  ORDER BY scope_row.chunk_sequence NULLS LAST, scope_row.pay_channel, scope_row.candidate_id, scope_row.id
  LIMIT 100;

  SELECT COUNT(*)::integer
  INTO v_candidate_scopes_processed
  FROM pg_temp.tmp_pay_workbench_allocation_scope_rows AS selected_scope;

  IF p_candidate_scope_ids IS NOT NULL AND COALESCE(v_candidate_scopes_processed, 0) <> COALESCE(v_scope_id_count, 0) THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_allocation_rows_seed one or more candidate scope ids do not belong to operation %', p_operation_id;
  END IF;

  IF COALESCE(v_candidate_scopes_processed, 0) = 0 THEN
    RETURN QUERY SELECT 0::integer, 0::integer, 0::integer, 0::integer;
    RETURN;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_allocation_preview_candidates;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_allocation_preview_candidates ON COMMIT DROP AS
  WITH scope_selected_lines AS (
    SELECT
      selected_scope.operation_id,
      selected_scope.id AS candidate_scope_id,
      selected_scope.pay_batch_id,
      selected_scope.candidate_id,
      selected_scope.pay_channel,
      selected_scope.candidate_totals_json,
      selected_scope.allocation_basis_json AS scope_allocation_basis_json,
      line_values.value AS line_json,
      line_values.ordinality::bigint AS line_ordinal
    FROM pg_temp.tmp_pay_workbench_allocation_scope_rows AS selected_scope
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE
        WHEN jsonb_typeof(selected_scope.selected_canonical_preview_lines_json) = 'array'
          AND jsonb_array_length(selected_scope.selected_canonical_preview_lines_json) > 0
          THEN selected_scope.selected_canonical_preview_lines_json
        WHEN jsonb_typeof(selected_scope.effective_canonical_preview_lines_json) = 'array'
          AND jsonb_array_length(selected_scope.effective_canonical_preview_lines_json) > 0
          THEN selected_scope.effective_canonical_preview_lines_json
        ELSE '[]'::jsonb
      END
    ) WITH ORDINALITY AS line_values(value, ordinality)
  ), normalised_scope_lines_raw AS (
    SELECT
      scope_selected_lines.operation_id,
      scope_selected_lines.candidate_scope_id,
      scope_selected_lines.pay_batch_id,
      scope_selected_lines.candidate_id,
      scope_selected_lines.pay_channel,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'preview_row_id', scope_selected_lines.line_json->>'preview_row_pk', scope_selected_lines.line_json->>'row_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'preview_row_id', scope_selected_lines.line_json->>'preview_row_pk', scope_selected_lines.line_json->>'row_id', '')), '')::uuid
        ELSE NULL::uuid
      END AS preview_row_id,
      NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'row_key', scope_selected_lines.line_json->>'source_ref', '')), '') AS row_key,
      CASE WHEN COALESCE(scope_selected_lines.line_json->>'row_ordinal', '') ~ '^[0-9]+$' THEN (scope_selected_lines.line_json->>'row_ordinal')::bigint ELSE scope_selected_lines.line_ordinal END AS row_ordinal,
      scope_selected_lines.line_json AS row_json,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json#>>'{economic_key,timesheet_id}', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json#>>'{economic_key,timesheet_id}', '')), '')::uuid
        ELSE NULL::uuid
      END AS economic_key_timesheet_id,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'timesheet_id', scope_selected_lines.line_json->>'real_business_timesheet_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'timesheet_id', scope_selected_lines.line_json->>'real_business_timesheet_id', '')), '')::uuid
        ELSE NULL::uuid
      END AS top_level_timesheet_id,
      COALESCE(NULLIF(BTRIM(scope_selected_lines.line_json->>'section'), ''), 'canonical_preview_lines') AS section,
      UPPER(NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json#>>'{economic_key,key_type}', scope_selected_lines.line_json->>'key_type', scope_selected_lines.line_json->>'component_key_type', '')), '')) AS key_type,
      NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json#>>'{economic_key,key_value}', scope_selected_lines.line_json->>'key_value', scope_selected_lines.line_json->>'component_key_value', '')), '') AS key_value,
      UPPER(NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'selection_state', 'SELECTED')), '')) AS selection_state,
      UPPER(NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'status', 'READY')), '')) AS line_status,
      CASE WHEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'finance_case_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'finance_case_id', '')), '')::uuid ELSE NULL::uuid END AS finance_case_id,
      CASE WHEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'finance_component_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'finance_component_id', '')), '')::uuid ELSE NULL::uuid END AS finance_component_id,
      UPPER(COALESCE(NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'line_type', '')), ''), NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'case_type', '')), ''), 'PREVIEW_ROW')) AS allocation_type,
      component_probe.single_fixed_reimbursement_key_type,
      component_probe.single_fixed_reimbursement_key_value,
      NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'source_ref', scope_selected_lines.line_json->>'row_key', '')), '') AS source_ref,
      CASE
        WHEN COALESCE(scope_selected_lines.line_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND((scope_selected_lines.line_json->>'amount_ex_vat')::numeric, 2)
        WHEN COALESCE(scope_selected_lines.line_json->>'preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND((scope_selected_lines.line_json->>'preview_amount_ex_vat')::numeric, 2)
        WHEN COALESCE(scope_selected_lines.line_json->>'allocated_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND((scope_selected_lines.line_json->>'allocated_amount')::numeric, 2)
        ELSE NULL::numeric
      END AS allocated_amount
    FROM scope_selected_lines
    CROSS JOIN LATERAL (
      SELECT
        CASE
          WHEN component_counts.object_component_count = 1
           AND component_counts.fixed_reimbursement_component_count = 1 THEN component_counts.fixed_reimbursement_key_type
          ELSE NULL::text
        END AS single_fixed_reimbursement_key_type,
        CASE
          WHEN component_counts.object_component_count = 1
           AND component_counts.fixed_reimbursement_component_count = 1 THEN component_counts.fixed_reimbursement_key_value
          ELSE NULL::text
        END AS single_fixed_reimbursement_key_value
      FROM (
        SELECT
          (COUNT(*) FILTER (
            WHERE component_element.value IS NOT NULL
              AND jsonb_typeof(component_element.value) = 'object'
          ))::integer AS object_component_count,
          (COUNT(*) FILTER (
            WHERE component_element.value IS NOT NULL
              AND jsonb_typeof(component_element.value) = 'object'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
              AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
          ))::integer AS fixed_reimbursement_component_count,
          MAX(UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), ''))) FILTER (
            WHERE component_element.value IS NOT NULL
              AND jsonb_typeof(component_element.value) = 'object'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
              AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
          ) AS fixed_reimbursement_key_type,
          MAX(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '')) FILTER (
            WHERE component_element.value IS NOT NULL
              AND jsonb_typeof(component_element.value) = 'object'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
              AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
          ) AS fixed_reimbursement_key_value
        FROM jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(scope_selected_lines.line_json->'case_components') = 'array' THEN scope_selected_lines.line_json->'case_components'
            ELSE '[]'::jsonb
          END
        ) AS component_element(value)
      ) AS component_counts
    ) AS component_probe
  ), allocation_timesheet_refs AS (
    SELECT normalised_scope_lines_raw.economic_key_timesheet_id AS timesheet_id
    FROM normalised_scope_lines_raw
    WHERE normalised_scope_lines_raw.economic_key_timesheet_id IS NOT NULL
    UNION
    SELECT normalised_scope_lines_raw.top_level_timesheet_id AS timesheet_id
    FROM normalised_scope_lines_raw
    WHERE normalised_scope_lines_raw.top_level_timesheet_id IS NOT NULL
  ), allocation_timesheet_id_array AS (
    SELECT COALESCE(
      array_agg(DISTINCT allocation_timesheet_refs.timesheet_id ORDER BY allocation_timesheet_refs.timesheet_id),
      array[]::uuid[]
    ) AS timesheet_ids
    FROM allocation_timesheet_refs
  ), allocation_rotation_scope AS (
    SELECT DISTINCT ON (rotation_scope.requested_timesheet_id)
      rotation_scope.requested_timesheet_id,
      COALESCE(rotation_scope.canonical_timesheet_id, rotation_scope.requested_timesheet_id) AS canonical_timesheet_id,
      (rotation_scope.family_timesheet_id IS NOT NULL AND rotation_scope.family_is_current IS NOT NULL) AS rotation_scope_resolved
    FROM allocation_timesheet_id_array
    JOIN public._pay_timesheet_rotation_scope(allocation_timesheet_id_array.timesheet_ids) AS rotation_scope
      ON true
    ORDER BY
      rotation_scope.requested_timesheet_id,
      rotation_scope.family_is_current DESC NULLS LAST,
      rotation_scope.family_version DESC NULLS LAST,
      rotation_scope.family_timesheet_id
  ), normalised_scope_lines AS (
    SELECT
      normalised_scope_lines_raw.operation_id,
      normalised_scope_lines_raw.candidate_scope_id,
      normalised_scope_lines_raw.pay_batch_id,
      normalised_scope_lines_raw.candidate_id,
      normalised_scope_lines_raw.pay_channel,
      normalised_scope_lines_raw.preview_row_id,
      normalised_scope_lines_raw.row_key,
      normalised_scope_lines_raw.row_ordinal,
      jsonb_strip_nulls(
        normalised_scope_lines_raw.row_json
        || CASE
          WHEN COALESCE(economic_key_rotation.canonical_timesheet_id, top_level_rotation.canonical_timesheet_id) IS NULL THEN '{}'::jsonb
          ELSE jsonb_build_object(
            'timesheet_id', COALESCE(economic_key_rotation.canonical_timesheet_id, top_level_rotation.canonical_timesheet_id)::text,
            'real_business_timesheet_id', COALESCE(economic_key_rotation.canonical_timesheet_id, top_level_rotation.canonical_timesheet_id)::text,
            'economic_key', COALESCE(normalised_scope_lines_raw.row_json->'economic_key', '{}'::jsonb)
              || jsonb_build_object('timesheet_id', COALESCE(economic_key_rotation.canonical_timesheet_id, top_level_rotation.canonical_timesheet_id)::text)
          )
        END
        || CASE
          WHEN normalised_scope_lines_raw.top_level_timesheet_id IS NOT NULL
           AND normalised_scope_lines_raw.top_level_timesheet_id IS DISTINCT FROM COALESCE(economic_key_rotation.canonical_timesheet_id, top_level_rotation.canonical_timesheet_id)
          THEN jsonb_build_object('rotation_requested_timesheet_id', normalised_scope_lines_raw.top_level_timesheet_id::text)
          ELSE '{}'::jsonb
        END
      ) AS row_json,
      COALESCE(economic_key_rotation.canonical_timesheet_id, top_level_rotation.canonical_timesheet_id, normalised_scope_lines_raw.economic_key_timesheet_id, normalised_scope_lines_raw.top_level_timesheet_id) AS timesheet_id,
      normalised_scope_lines_raw.section,
      normalised_scope_lines_raw.key_type,
      normalised_scope_lines_raw.key_value,
      normalised_scope_lines_raw.selection_state,
      normalised_scope_lines_raw.line_status,
      normalised_scope_lines_raw.finance_case_id,
      normalised_scope_lines_raw.finance_component_id,
      normalised_scope_lines_raw.allocation_type,
      normalised_scope_lines_raw.single_fixed_reimbursement_key_type,
      normalised_scope_lines_raw.single_fixed_reimbursement_key_value,
      normalised_scope_lines_raw.source_ref,
      normalised_scope_lines_raw.allocated_amount,
      CASE
        WHEN normalised_scope_lines_raw.economic_key_timesheet_id IS NULL AND normalised_scope_lines_raw.top_level_timesheet_id IS NULL THEN false
        WHEN normalised_scope_lines_raw.economic_key_timesheet_id IS NOT NULL AND COALESCE(economic_key_rotation.rotation_scope_resolved, false) = false THEN true
        WHEN normalised_scope_lines_raw.top_level_timesheet_id IS NOT NULL AND COALESCE(top_level_rotation.rotation_scope_resolved, false) = false THEN true
        WHEN economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND top_level_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS DISTINCT FROM top_level_rotation.canonical_timesheet_id THEN true
        ELSE false
      END AS rotation_validation_failed,
      CASE
        WHEN normalised_scope_lines_raw.economic_key_timesheet_id IS NULL AND normalised_scope_lines_raw.top_level_timesheet_id IS NULL THEN NULL::text
        WHEN normalised_scope_lines_raw.economic_key_timesheet_id IS NOT NULL AND COALESCE(economic_key_rotation.rotation_scope_resolved, false) = false THEN 'ALLOCATION_ECONOMIC_KEY_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
        WHEN normalised_scope_lines_raw.top_level_timesheet_id IS NOT NULL AND COALESCE(top_level_rotation.rotation_scope_resolved, false) = false THEN 'ALLOCATION_LINE_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
        WHEN economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND top_level_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS DISTINCT FROM top_level_rotation.canonical_timesheet_id THEN 'ALLOCATION_LINE_AND_ECONOMIC_KEY_CANONICAL_TIMESHEET_MISMATCH'
        ELSE NULL::text
      END AS rotation_failure_reason
    FROM normalised_scope_lines_raw
    LEFT JOIN allocation_rotation_scope AS economic_key_rotation
      ON economic_key_rotation.requested_timesheet_id = normalised_scope_lines_raw.economic_key_timesheet_id
    LEFT JOIN allocation_rotation_scope AS top_level_rotation
      ON top_level_rotation.requested_timesheet_id = normalised_scope_lines_raw.top_level_timesheet_id
  )
  SELECT
    normalised_scope_lines.*,
    jsonb_strip_nulls(jsonb_build_object(
      'timesheet_id', CASE WHEN normalised_scope_lines.timesheet_id IS NULL THEN NULL ELSE normalised_scope_lines.timesheet_id::text END,
      'key_type', normalised_scope_lines.key_type,
      'key_value', normalised_scope_lines.key_value
    )) AS economic_key_json,
    public.pay_workbench_preview_line_contract_ok(
      p_line_json => jsonb_strip_nulls(
        normalised_scope_lines.row_json
        || jsonb_build_object(
          'row_key', normalised_scope_lines.row_key,
          'preview_row_pk', CASE WHEN normalised_scope_lines.preview_row_id IS NULL THEN NULL ELSE normalised_scope_lines.preview_row_id::text END,
          'selection_state', normalised_scope_lines.selection_state
        )
      ),
      p_economic_key_json => jsonb_strip_nulls(jsonb_build_object(
        'timesheet_id', CASE WHEN normalised_scope_lines.timesheet_id IS NULL THEN NULL ELSE normalised_scope_lines.timesheet_id::text END,
        'key_type', normalised_scope_lines.key_type,
        'key_value', normalised_scope_lines.key_value
      )),
      p_target_section => normalised_scope_lines.section
    ) AS preview_contract_json
  FROM normalised_scope_lines
  ORDER BY normalised_scope_lines.pay_channel, normalised_scope_lines.candidate_id, normalised_scope_lines.row_ordinal, normalised_scope_lines.preview_row_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'preview_row_id', invalid_rows.preview_row_id::text,
           'row_key', invalid_rows.row_key,
           'candidate_id', invalid_rows.candidate_id::text,
           'candidate_scope_id', invalid_rows.candidate_scope_id::text,
           'reasons', COALESCE(invalid_rows.preview_contract_json->'reasons', '[]'::jsonb)
             || CASE WHEN invalid_rows.rotation_validation_failed IS TRUE THEN jsonb_build_array(invalid_rows.rotation_failure_reason) ELSE '[]'::jsonb END
             || CASE
               WHEN invalid_rows.single_fixed_reimbursement_key_type IS NOT NULL
                AND (
                  invalid_rows.key_type IS DISTINCT FROM invalid_rows.single_fixed_reimbursement_key_type
                  OR invalid_rows.key_value IS DISTINCT FROM invalid_rows.single_fixed_reimbursement_key_value
                ) THEN jsonb_build_array('POLICY_X_REIMBURSEMENT_KEY_MISMATCH')
               ELSE '[]'::jsonb
             END
         ) ORDER BY invalid_rows.row_ordinal, invalid_rows.preview_row_id), '[]'::jsonb)
  INTO v_malformed_allocation_preview_rows
  FROM (
    SELECT candidate_row.*
    FROM pg_temp.tmp_pay_workbench_allocation_preview_candidates AS candidate_row
    WHERE candidate_row.rotation_validation_failed IS TRUE
       OR LOWER(BTRIM(COALESCE(candidate_row.preview_contract_json->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
       OR LOWER(BTRIM(COALESCE(candidate_row.preview_contract_json->>'selection_allowed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
       OR candidate_row.preview_row_id IS NULL
       OR lower(COALESCE(candidate_row.section, '')) <> 'canonical_preview_lines'
       OR UPPER(BTRIM(COALESCE(candidate_row.selection_state, ''))) <> 'SELECTED'
       OR UPPER(BTRIM(COALESCE(candidate_row.line_status, ''))) <> 'READY'
       OR candidate_row.pay_channel NOT IN ('PAYE', 'UMBRELLA')
       OR candidate_row.key_type NOT IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE','MANUAL_CARRY_FORWARD')
       OR candidate_row.key_value IS NULL
       OR (
         candidate_row.single_fixed_reimbursement_key_type IS NOT NULL
         AND (
           candidate_row.key_type IS DISTINCT FROM candidate_row.single_fixed_reimbursement_key_type
           OR candidate_row.key_value IS DISTINCT FROM candidate_row.single_fixed_reimbursement_key_value
         )
       )
       OR (candidate_row.key_type = 'TS_DAY' AND candidate_row.key_value !~ '^\d{4}-\d{2}-\d{2}$')
       OR candidate_row.allocated_amount IS NULL
       OR ROUND(COALESCE(candidate_row.allocated_amount, 0), 2) = 0
    ORDER BY candidate_row.row_ordinal, candidate_row.preview_row_id
    LIMIT 25
  ) AS invalid_rows;

  IF jsonb_array_length(COALESCE(v_malformed_allocation_preview_rows, '[]'::jsonb)) > 0 THEN
    RAISE EXCEPTION 'MALFORMED_PREVIEW_ROW_NOT_DRAFTABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'MALFORMED_PREVIEW_ROW_NOT_DRAFTABLE',
              'operation_id', p_operation_id::text,
              'malformed_selected_preview_rows', COALESCE(v_malformed_allocation_preview_rows, '[]'::jsonb),
              'message', 'Selected preview rows cannot be converted into allocation rows because they are not valid draftable Ready to Pay rows.'
            )::text;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_allocation_expected_rows;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_allocation_expected_rows ON COMMIT DROP AS
  WITH selected_preview_rows AS (
    SELECT candidate_row.*
    FROM pg_temp.tmp_pay_workbench_allocation_preview_candidates AS candidate_row
    WHERE candidate_row.rotation_validation_failed IS NOT TRUE
      AND LOWER(BTRIM(COALESCE(candidate_row.preview_contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(candidate_row.preview_contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND candidate_row.preview_row_id IS NOT NULL
      AND lower(COALESCE(candidate_row.section, '')) = 'canonical_preview_lines'
      AND UPPER(BTRIM(COALESCE(candidate_row.selection_state, ''))) = 'SELECTED'
      AND UPPER(BTRIM(COALESCE(candidate_row.line_status, ''))) = 'READY'
      AND candidate_row.pay_channel IN ('PAYE', 'UMBRELLA')
      AND candidate_row.key_type IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE','MANUAL_CARRY_FORWARD')
      AND candidate_row.key_value IS NOT NULL
      AND NOT (
        candidate_row.single_fixed_reimbursement_key_type IS NOT NULL
        AND (
          candidate_row.key_type IS DISTINCT FROM candidate_row.single_fixed_reimbursement_key_type
          OR candidate_row.key_value IS DISTINCT FROM candidate_row.single_fixed_reimbursement_key_value
        )
      )
      AND NOT (candidate_row.key_type = 'TS_DAY' AND candidate_row.key_value !~ '^\d{4}-\d{2}-\d{2}$')
      AND candidate_row.allocated_amount IS NOT NULL
      AND ROUND(COALESCE(candidate_row.allocated_amount, 0), 2) <> 0
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_candidate_allocation_rows AS existing_row
        WHERE existing_row.operation_id = candidate_row.operation_id
          AND existing_row.operation_source_key = candidate_row.operation_id::text || ':allocation:' || candidate_row.candidate_scope_id::text || ':' || candidate_row.preview_row_id::text
      )
  )
  SELECT
    selected_preview_rows.operation_id,
    selected_preview_rows.candidate_scope_id,
    selected_preview_rows.pay_batch_id,
    selected_preview_rows.candidate_id,
    selected_preview_rows.pay_channel,
    selected_preview_rows.finance_case_id,
    selected_preview_rows.finance_component_id,
    selected_preview_rows.allocation_type,
    selected_preview_rows.source_ref,
    selected_preview_rows.operation_id::text || ':allocation:' || selected_preview_rows.candidate_scope_id::text || ':' || selected_preview_rows.preview_row_id::text AS operation_source_key,
    selected_preview_rows.allocated_amount,
    jsonb_build_object(
      'source', 'banking_pay_workbench_preview_rows',
      'preview_row_id', selected_preview_rows.preview_row_id::text,
      'row_key', selected_preview_rows.row_key,
      'row_ordinal', selected_preview_rows.row_ordinal,
      'timesheet_id', CASE WHEN selected_preview_rows.timesheet_id IS NULL THEN NULL ELSE selected_preview_rows.timesheet_id::text END,
      'key_type', selected_preview_rows.key_type,
      'key_value', selected_preview_rows.key_value,
      'economic_key', jsonb_strip_nulls(jsonb_build_object(
        'timesheet_id', CASE WHEN selected_preview_rows.timesheet_id IS NULL THEN NULL ELSE selected_preview_rows.timesheet_id::text END,
        'key_type', selected_preview_rows.key_type,
        'key_value', selected_preview_rows.key_value
      )),
      'preview_contract', selected_preview_rows.preview_contract_json,
      'line', jsonb_strip_nulls(
        selected_preview_rows.row_json
        || jsonb_build_object(
          'row_key', selected_preview_rows.row_key,
          'preview_row_pk', selected_preview_rows.preview_row_id::text,
          'selection_state', 'SELECTED'
        )
      )
    ) AS allocation_basis_json,
    selected_preview_rows.row_ordinal AS sort_order
  FROM selected_preview_rows;

  SELECT COUNT(*)::integer
  INTO v_expected_count
  FROM pg_temp.tmp_pay_workbench_allocation_expected_rows AS expected_row_count;

  IF COALESCE(v_expected_count, 0) = 0 AND EXISTS (
    SELECT 1
    FROM pg_temp.tmp_pay_workbench_allocation_scope_rows AS selected_scope
    WHERE COALESCE(selected_scope.candidate_totals_json->>'selected_row_count_seeded_in_page', '0') ~ '^[0-9]+$'
      AND (selected_scope.candidate_totals_json->>'selected_row_count_seeded_in_page')::integer > 0
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_candidate_allocation_rows AS existing_row
        WHERE existing_row.operation_id = p_operation_id
          AND existing_row.candidate_scope_id = selected_scope.id
      )
  ) THEN
    RAISE EXCEPTION 'DRAFT_ALLOCATION_ROWS_EMPTY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ALLOCATION_ROWS_EMPTY',
              'operation_id', p_operation_id::text,
              'candidate_scopes_processed', COALESCE(v_candidate_scopes_processed, 0),
              'message', 'Row-backed candidate scope did not contain draftable selected preview lines for allocation.'
            )::text;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_reused
  FROM public.banking_pay_operation_candidate_allocation_rows AS existing_row
  WHERE existing_row.operation_id = p_operation_id
    AND existing_row.candidate_scope_id IN (SELECT selected_scope.id FROM pg_temp.tmp_pay_workbench_allocation_scope_rows AS selected_scope);

  IF COALESCE(v_expected_count, 0) > 0 THEN
    WITH inserted_rows AS (
      INSERT INTO public.banking_pay_operation_candidate_allocation_rows (
        operation_id,
        candidate_scope_id,
        pay_batch_id,
        candidate_id,
        pay_channel,
        finance_case_id,
        finance_component_id,
        allocation_type,
        source_ref,
        operation_source_key,
        allocated_amount,
        allocation_basis_json,
        sort_order,
        status,
        created_at_utc,
        updated_at_utc
      )
      SELECT
        expected_row.operation_id,
        expected_row.candidate_scope_id,
        expected_row.pay_batch_id,
        expected_row.candidate_id,
        expected_row.pay_channel,
        expected_row.finance_case_id,
        expected_row.finance_component_id,
        expected_row.allocation_type,
        expected_row.source_ref,
        expected_row.operation_source_key,
        expected_row.allocated_amount,
        expected_row.allocation_basis_json,
        expected_row.sort_order,
        'PENDING',
        v_now,
        v_now
      FROM pg_temp.tmp_pay_workbench_allocation_expected_rows AS expected_row
      ON CONFLICT (operation_id, operation_source_key) DO NOTHING
      RETURNING public.banking_pay_operation_candidate_allocation_rows.id
    )
    SELECT COUNT(*)::integer
    INTO v_inserted
    FROM inserted_rows;
  ELSE
    v_inserted := 0;
  END IF;

  UPDATE public.banking_pay_operation_candidate_scope AS scope_update
  SET status = CASE
        WHEN EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_candidate_allocation_rows AS existing_row
          WHERE existing_row.operation_id = scope_update.operation_id
            AND existing_row.candidate_scope_id = scope_update.id
        ) THEN 'ALLOCATED'
        ELSE scope_update.status
      END,
      updated_at_utc = v_now
  WHERE scope_update.operation_id = p_operation_id
    AND EXISTS (
      SELECT 1
      FROM pg_temp.tmp_pay_workbench_allocation_scope_rows AS selected_scope
      WHERE selected_scope.id = scope_update.id
    );

  UPDATE public.banking_pay_operations AS operation_update
  SET updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN QUERY
  SELECT
    COALESCE(v_candidate_scopes_processed, 0),
    COALESCE(v_inserted, 0),
    COALESCE(v_reused, 0),
    0::integer;
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_workbench_prepare_draft_scope_seed(
  p_operation_id uuid,
  p_workbench_session_id uuid,
  p_actor_user_id uuid,
  p_selected_preview_row_ids jsonb DEFAULT NULL::jsonb,
  p_pay_channel_scope text DEFAULT NULL::text,
  p_same_week_paye_override_json jsonb DEFAULT '{}'::jsonb
)
RETURNS TABLE(
  candidate_scope_count integer,
  selected_row_count integer,
  timesheet_count integer,
  finance_case_count integer,
  pay_channel_count integer
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation public.banking_pay_operations%ROWTYPE;
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope_filter text := UPPER(COALESCE(NULLIF(BTRIM(p_pay_channel_scope), ''), 'ALL'));
  v_selected_input_count integer := 0;
  v_candidate_scope_count integer := 0;
  v_selected_count integer := 0;
  v_timesheet_count integer := 0;
  v_finance_case_count integer := 0;
  v_pay_channel_count integer := 0;
  v_stale_selection_ids jsonb := '[]'::jsonb;
  v_missing_selection_ids jsonb := '[]'::jsonb;
  v_malformed_selected_preview_rows jsonb := '[]'::jsonb;
  v_selection_resolved_to_current boolean := false;
  v_resolved_current_selection_ids jsonb := '[]'::jsonb;
  v_resolved_selection_match_count integer := 0;
  v_resolved_selection_distinct_count integer := 0;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed: p_operation_id is required';
  END IF;

  IF p_workbench_session_id IS NULL THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed: p_workbench_session_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed: p_actor_user_id is required';
  END IF;

  IF v_scope_filter NOT IN ('ALL', 'PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed unsupported pay channel scope: %', v_scope_filter;
  END IF;

  IF jsonb_typeof(COALESCE(p_same_week_paye_override_json, '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed requires p_same_week_paye_override_json to be a JSON object';
  END IF;

  IF p_selected_preview_row_ids IS NOT NULL THEN
    IF jsonb_typeof(p_selected_preview_row_ids) <> 'array' THEN
      RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed requires p_selected_preview_row_ids to be null or a JSON array';
    END IF;

    v_selected_input_count := jsonb_array_length(p_selected_preview_row_ids);

    IF v_selected_input_count > 100 THEN
      RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed selected preview row input exceeds the 100 row cap: %', v_selected_input_count;
    END IF;
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed operation not found: %', p_operation_id;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_operation.operation_type, ''))) <> 'DRAFT_CREATE' THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed expected DRAFT_CREATE operation %, got %', p_operation_id, v_operation.operation_type;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_operation.status, ''))) IN ('COMPLETE', 'FAILED', 'CANCELLED', 'CANCELED', 'REVIEW_REQUIRED') THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed cannot seed terminal operation % with status %', p_operation_id, v_operation.status;
  END IF;

  IF v_operation.workbench_session_id IS NOT NULL AND v_operation.workbench_session_id <> p_workbench_session_id THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed operation % belongs to a different workbench session', p_operation_id;
  END IF;

  IF v_operation.actor_user_id IS NOT NULL AND v_operation.actor_user_id <> p_actor_user_id THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed operation % belongs to a different actor', p_operation_id;
  END IF;

  SELECT session_row.*
  INTO v_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_workbench_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed workbench session not found: %', p_workbench_session_id;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session.status, ''))) <> 'OPEN' OR v_session.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed workbench session % is not OPEN', p_workbench_session_id;
  END IF;

  IF v_session.actor_user_id <> p_actor_user_id THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed workbench session % belongs to a different actor', p_workbench_session_id;
  END IF;

  UPDATE public.banking_pay_operations AS operation_update
  SET workbench_session_id = COALESCE(operation_update.workbench_session_id, p_workbench_session_id),
      actor_user_id = COALESCE(operation_update.actor_user_id, p_actor_user_id),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_draft_scope_supplied_ids;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_draft_scope_supplied_ids ON COMMIT DROP AS
  SELECT DISTINCT BTRIM(supplied_id.value) AS supplied_id
  FROM jsonb_array_elements_text(COALESCE(p_selected_preview_row_ids, '[]'::jsonb)) AS supplied_id(value)
  WHERE p_selected_preview_row_ids IS NOT NULL
    AND BTRIM(supplied_id.value) <> '';

  IF p_selected_preview_row_ids IS NOT NULL AND COALESCE(v_selected_input_count, 0) > 0 THEN
    DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_draft_scope_resolved_ids;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_draft_scope_resolved_ids ON COMMIT DROP AS
    WITH supplied_ids AS (
      SELECT supplied_id.supplied_id
      FROM pg_temp.tmp_pay_workbench_draft_scope_supplied_ids AS supplied_id
    ),
    direct_current_matches AS (
      SELECT DISTINCT
        supplied_ids.supplied_id,
        current_preview_row.id::text AS resolved_id
      FROM supplied_ids
      JOIN public.banking_pay_workbench_preview_rows AS current_preview_row
        ON current_preview_row.session_id = p_workbench_session_id
       AND current_preview_row.session_version = v_session.version
       AND UPPER(BTRIM(COALESCE(current_preview_row.status, ''))) = 'READY'
       AND COALESCE(current_preview_row.selected, false) = true
       AND UPPER(BTRIM(COALESCE(current_preview_row.selection_state, ''))) = 'SELECTED'
       AND UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'presentation_section', ''))) = 'READY_TO_PAY'
       AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND (v_scope_filter = 'ALL' OR UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'pay_channel', current_preview_row.row_json->>'current_pay_method', current_preview_row.row_json->>'candidate_pay_method', ''))) = v_scope_filter)
       AND (
         current_preview_row.id::text = supplied_ids.supplied_id
         OR current_preview_row.row_key = supplied_ids.supplied_id
         OR current_preview_row.row_json->>'preview_row_id' = supplied_ids.supplied_id
         OR current_preview_row.row_json->>'row_id' = supplied_ids.supplied_id
         OR current_preview_row.row_json->>'line_id' = supplied_ids.supplied_id
       )
    ),
    operation_contracts AS (
      SELECT
        contract_entry.ordinality::integer AS contract_index,
        NULLIF(BTRIM(COALESCE(
          contract_entry.value->>'preview_row_id',
          contract_entry.value->>'materialised_preview_row_id',
          contract_entry.value->>'row_id',
          contract_entry.value->>'id',
          contract_entry.value->>'selected_preview_row_id'
        )), '') AS supplied_id,
        NULLIF(BTRIM(COALESCE(contract_entry.value->>'presentation_preview_row_id', contract_entry.value->>'line_id', '')), '') AS presentation_preview_row_id,
        NULLIF(BTRIM(COALESCE(contract_entry.value->>'row_key', '')), '') AS row_key,
        COALESCE(NULLIF(BTRIM(contract_entry.value->>'section'), ''), 'canonical_preview_lines') AS section,
        CASE
          WHEN NULLIF(BTRIM(COALESCE(contract_entry.value->>'candidate_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN NULLIF(BTRIM(COALESCE(contract_entry.value->>'candidate_id', '')), '')::uuid
          ELSE NULL::uuid
        END AS candidate_id,
        CASE
          WHEN NULLIF(BTRIM(COALESCE(contract_entry.value#>>'{economic_key,timesheet_id}', contract_entry.value->>'timesheet_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN NULLIF(BTRIM(COALESCE(contract_entry.value#>>'{economic_key,timesheet_id}', contract_entry.value->>'timesheet_id', '')), '')::uuid
          ELSE NULL::uuid
        END AS timesheet_id,
        NULLIF(BTRIM(COALESCE(contract_entry.value#>>'{economic_key,key_type}', contract_entry.value->>'key_type', '')), '') AS key_type,
        NULLIF(BTRIM(COALESCE(contract_entry.value#>>'{economic_key,key_value}', contract_entry.value->>'key_value', '')), '') AS key_value,
        UPPER(NULLIF(BTRIM(COALESCE(contract_entry.value->>'pay_channel', '')), '')) AS pay_channel
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(COALESCE(v_operation.input_json->'draft_selected_preview_row_contracts', '[]'::jsonb)) = 'array'
            THEN COALESCE(v_operation.input_json->'draft_selected_preview_row_contracts', '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) WITH ORDINALITY AS contract_entry(value, ordinality)
      WHERE jsonb_typeof(contract_entry.value) = 'object'
    ),
    operation_contract_timesheet_ids AS (
      SELECT COALESCE(
        array_agg(DISTINCT operation_contracts.timesheet_id ORDER BY operation_contracts.timesheet_id),
        array[]::uuid[]
      ) AS timesheet_ids
      FROM operation_contracts
      WHERE operation_contracts.timesheet_id IS NOT NULL
    ),
    operation_contract_rotation AS (
      SELECT DISTINCT ON (rotation_scope.requested_timesheet_id)
        rotation_scope.requested_timesheet_id,
        COALESCE(rotation_scope.canonical_timesheet_id, rotation_scope.requested_timesheet_id) AS canonical_timesheet_id
      FROM operation_contract_timesheet_ids
      JOIN public._pay_timesheet_rotation_scope(operation_contract_timesheet_ids.timesheet_ids) AS rotation_scope
        ON true
      ORDER BY
        rotation_scope.requested_timesheet_id,
        rotation_scope.family_is_current DESC NULLS LAST,
        rotation_scope.family_version DESC NULLS LAST,
        rotation_scope.family_timesheet_id
    ),
    operation_contract_current_matches AS (
      SELECT DISTINCT
        supplied_ids.supplied_id,
        current_preview_row.id::text AS resolved_id
      FROM supplied_ids
      JOIN operation_contracts AS operation_contract
        ON (
          operation_contract.supplied_id = supplied_ids.supplied_id
          OR operation_contract.presentation_preview_row_id = supplied_ids.supplied_id
          OR operation_contract.row_key = supplied_ids.supplied_id
        )
      LEFT JOIN operation_contract_rotation
        ON operation_contract_rotation.requested_timesheet_id = operation_contract.timesheet_id
      JOIN public.banking_pay_workbench_preview_rows AS current_preview_row
        ON current_preview_row.session_id = p_workbench_session_id
       AND current_preview_row.session_version = v_session.version
       AND UPPER(BTRIM(COALESCE(current_preview_row.status, ''))) = 'READY'
       AND COALESCE(current_preview_row.selected, false) = true
       AND UPPER(BTRIM(COALESCE(current_preview_row.selection_state, ''))) = 'SELECTED'
       AND UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'presentation_section', ''))) = 'READY_TO_PAY'
       AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND operation_contract.candidate_id IS NOT NULL
       AND operation_contract.timesheet_id IS NOT NULL
       AND operation_contract.row_key IS NOT NULL
       AND operation_contract.key_type IS NOT NULL
       AND operation_contract.key_value IS NOT NULL
       AND current_preview_row.candidate_id IS NOT DISTINCT FROM operation_contract.candidate_id
       AND current_preview_row.timesheet_id IS NOT DISTINCT FROM COALESCE(operation_contract_rotation.canonical_timesheet_id, operation_contract.timesheet_id)
       AND COALESCE(NULLIF(BTRIM(current_preview_row.section), ''), 'canonical_preview_lines') = COALESCE(NULLIF(BTRIM(operation_contract.section), ''), 'canonical_preview_lines')
       AND NULLIF(BTRIM(COALESCE(current_preview_row.key_type, current_preview_row.row_json#>>'{economic_key,key_type}', current_preview_row.row_json->>'component_key_type', '')), '') IS NOT DISTINCT FROM operation_contract.key_type
       AND NULLIF(BTRIM(COALESCE(current_preview_row.key_value, current_preview_row.row_json#>>'{economic_key,key_value}', current_preview_row.row_json->>'component_key_value', '')), '') IS NOT DISTINCT FROM operation_contract.key_value
       AND NULLIF(BTRIM(current_preview_row.row_key), '') IS NOT DISTINCT FROM NULLIF(BTRIM(operation_contract.row_key), '')
       AND (v_scope_filter = 'ALL' OR UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'pay_channel', current_preview_row.row_json->>'current_pay_method', current_preview_row.row_json->>'candidate_pay_method', ''))) = v_scope_filter)
       AND (
         operation_contract.pay_channel IS NULL
         OR operation_contract.pay_channel = ''
         OR UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'pay_channel', current_preview_row.row_json->>'current_pay_method', current_preview_row.row_json->>'candidate_pay_method', ''))) = operation_contract.pay_channel
       )
    ),
    historical_preview_inputs AS (
      SELECT DISTINCT
        supplied_ids.supplied_id,
        any_preview_row.candidate_id,
        COALESCE(NULLIF(BTRIM(any_preview_row.section), ''), 'canonical_preview_lines') AS section,
        any_preview_row.row_key,
        any_preview_row.timesheet_id,
        NULLIF(BTRIM(COALESCE(any_preview_row.key_type, any_preview_row.row_json#>>'{economic_key,key_type}', any_preview_row.row_json->>'component_key_type', '')), '') AS key_type,
        NULLIF(BTRIM(COALESCE(any_preview_row.key_value, any_preview_row.row_json#>>'{economic_key,key_value}', any_preview_row.row_json->>'component_key_value', '')), '') AS key_value,
        UPPER(NULLIF(BTRIM(COALESCE(any_preview_row.row_json->>'pay_channel', any_preview_row.row_json->>'current_pay_method', any_preview_row.row_json->>'candidate_pay_method', '')), '')) AS pay_channel
      FROM supplied_ids
      JOIN public.banking_pay_workbench_preview_rows AS any_preview_row
        ON any_preview_row.session_id = p_workbench_session_id
       AND (
         any_preview_row.id::text = supplied_ids.supplied_id
         OR any_preview_row.row_key = supplied_ids.supplied_id
         OR any_preview_row.row_json->>'preview_row_id' = supplied_ids.supplied_id
         OR any_preview_row.row_json->>'row_id' = supplied_ids.supplied_id
         OR any_preview_row.row_json->>'line_id' = supplied_ids.supplied_id
       )
      WHERE any_preview_row.timesheet_id IS NOT NULL
        AND any_preview_row.row_key IS NOT NULL
    ),
    historical_timesheet_ids AS (
      SELECT COALESCE(
        array_agg(DISTINCT historical_preview_inputs.timesheet_id ORDER BY historical_preview_inputs.timesheet_id),
        array[]::uuid[]
      ) AS timesheet_ids
      FROM historical_preview_inputs
    ),
    historical_rotation AS (
      SELECT DISTINCT ON (rotation_scope.requested_timesheet_id)
        rotation_scope.requested_timesheet_id,
        COALESCE(rotation_scope.canonical_timesheet_id, rotation_scope.requested_timesheet_id) AS canonical_timesheet_id
      FROM historical_timesheet_ids
      JOIN public._pay_timesheet_rotation_scope(historical_timesheet_ids.timesheet_ids) AS rotation_scope
        ON true
      ORDER BY
        rotation_scope.requested_timesheet_id,
        rotation_scope.family_is_current DESC NULLS LAST,
        rotation_scope.family_version DESC NULLS LAST,
        rotation_scope.family_timesheet_id
    ),
    historical_preview_current_matches AS (
      SELECT DISTINCT
        historical_preview_inputs.supplied_id,
        current_preview_row.id::text AS resolved_id
      FROM historical_preview_inputs
      JOIN historical_rotation
        ON historical_rotation.requested_timesheet_id = historical_preview_inputs.timesheet_id
      JOIN public.banking_pay_workbench_preview_rows AS current_preview_row
        ON current_preview_row.session_id = p_workbench_session_id
       AND current_preview_row.session_version = v_session.version
       AND UPPER(BTRIM(COALESCE(current_preview_row.status, ''))) = 'READY'
       AND COALESCE(current_preview_row.selected, false) = true
       AND UPPER(BTRIM(COALESCE(current_preview_row.selection_state, ''))) = 'SELECTED'
       AND UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'presentation_section', ''))) = 'READY_TO_PAY'
       AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND current_preview_row.candidate_id IS NOT DISTINCT FROM historical_preview_inputs.candidate_id
       AND current_preview_row.timesheet_id IS NOT DISTINCT FROM historical_rotation.canonical_timesheet_id
       AND COALESCE(NULLIF(BTRIM(current_preview_row.section), ''), 'canonical_preview_lines') = historical_preview_inputs.section
       AND NULLIF(BTRIM(current_preview_row.row_key), '') IS NOT DISTINCT FROM NULLIF(BTRIM(historical_preview_inputs.row_key), '')
       AND NULLIF(BTRIM(COALESCE(current_preview_row.key_type, current_preview_row.row_json#>>'{economic_key,key_type}', current_preview_row.row_json->>'component_key_type', '')), '') IS NOT DISTINCT FROM historical_preview_inputs.key_type
       AND NULLIF(BTRIM(COALESCE(current_preview_row.key_value, current_preview_row.row_json#>>'{economic_key,key_value}', current_preview_row.row_json->>'component_key_value', '')), '') IS NOT DISTINCT FROM historical_preview_inputs.key_value
       AND (v_scope_filter = 'ALL' OR UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'pay_channel', current_preview_row.row_json->>'current_pay_method', current_preview_row.row_json->>'candidate_pay_method', ''))) = v_scope_filter)
       AND (
         historical_preview_inputs.pay_channel IS NULL
         OR historical_preview_inputs.pay_channel = ''
         OR UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'pay_channel', current_preview_row.row_json->>'current_pay_method', current_preview_row.row_json->>'candidate_pay_method', ''))) = historical_preview_inputs.pay_channel
       )
    )
    SELECT
      supplied_ids.supplied_id,
      COALESCE(direct_current_matches.resolved_id, operation_contract_current_matches.resolved_id, historical_preview_current_matches.resolved_id) AS resolved_id
    FROM supplied_ids
    LEFT JOIN direct_current_matches
      ON direct_current_matches.supplied_id = supplied_ids.supplied_id
    LEFT JOIN operation_contract_current_matches
      ON operation_contract_current_matches.supplied_id = supplied_ids.supplied_id
    LEFT JOIN historical_preview_current_matches
      ON historical_preview_current_matches.supplied_id = supplied_ids.supplied_id;

    SELECT COUNT(*)::integer,
           COUNT(DISTINCT resolved_selection.resolved_id)::integer,
           COALESCE(jsonb_agg(to_jsonb(resolved_selection.resolved_id) ORDER BY resolved_selection.resolved_id), '[]'::jsonb)
    INTO v_resolved_selection_match_count, v_resolved_selection_distinct_count, v_resolved_current_selection_ids
    FROM pg_temp.tmp_pay_workbench_draft_scope_resolved_ids AS resolved_selection
    WHERE NULLIF(BTRIM(COALESCE(resolved_selection.resolved_id, '')), '') IS NOT NULL;

    IF COALESCE(v_resolved_selection_match_count, 0) = COALESCE(v_selected_input_count, 0)
       AND COALESCE(v_resolved_selection_distinct_count, 0) = COALESCE(v_selected_input_count, 0) THEN
      SELECT EXISTS (
        SELECT 1
        FROM pg_temp.tmp_pay_workbench_draft_scope_resolved_ids AS resolved_selection
        WHERE resolved_selection.resolved_id IS DISTINCT FROM resolved_selection.supplied_id
      )
      INTO v_selection_resolved_to_current;

      TRUNCATE TABLE pg_temp.tmp_pay_workbench_draft_scope_supplied_ids;

      INSERT INTO pg_temp.tmp_pay_workbench_draft_scope_supplied_ids (supplied_id)
      SELECT resolved_selection.resolved_id
      FROM pg_temp.tmp_pay_workbench_draft_scope_resolved_ids AS resolved_selection
      WHERE NULLIF(BTRIM(COALESCE(resolved_selection.resolved_id, '')), '') IS NOT NULL
      ORDER BY resolved_selection.resolved_id;
    END IF;
  END IF;

  IF p_selected_preview_row_ids IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(supplied_ids.supplied_id) ORDER BY supplied_ids.supplied_id), '[]'::jsonb)
    INTO v_stale_selection_ids
    FROM pg_temp.tmp_pay_workbench_draft_scope_supplied_ids AS supplied_ids
    WHERE EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_preview_rows AS any_preview_row
      WHERE any_preview_row.session_id = p_workbench_session_id
        AND (
          any_preview_row.id::text = supplied_ids.supplied_id
          OR any_preview_row.row_key = supplied_ids.supplied_id
          OR any_preview_row.row_json->>'preview_row_id' = supplied_ids.supplied_id
          OR any_preview_row.row_json->>'row_id' = supplied_ids.supplied_id
          OR any_preview_row.row_json->>'line_id' = supplied_ids.supplied_id
        )
    )
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_preview_rows AS current_preview_row
        WHERE current_preview_row.session_id = p_workbench_session_id
          AND current_preview_row.session_version = v_session.version
          AND UPPER(BTRIM(COALESCE(current_preview_row.status, ''))) = 'READY'
          AND (
            current_preview_row.id::text = supplied_ids.supplied_id
            OR current_preview_row.row_key = supplied_ids.supplied_id
            OR current_preview_row.row_json->>'preview_row_id' = supplied_ids.supplied_id
            OR current_preview_row.row_json->>'row_id' = supplied_ids.supplied_id
            OR current_preview_row.row_json->>'line_id' = supplied_ids.supplied_id
          )
      );

    SELECT COALESCE(jsonb_agg(to_jsonb(supplied_ids.supplied_id) ORDER BY supplied_ids.supplied_id), '[]'::jsonb)
    INTO v_missing_selection_ids
    FROM pg_temp.tmp_pay_workbench_draft_scope_supplied_ids AS supplied_ids
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_preview_rows AS any_preview_row
      WHERE any_preview_row.session_id = p_workbench_session_id
        AND (
          any_preview_row.id::text = supplied_ids.supplied_id
          OR any_preview_row.row_key = supplied_ids.supplied_id
          OR any_preview_row.row_json->>'preview_row_id' = supplied_ids.supplied_id
          OR any_preview_row.row_json->>'row_id' = supplied_ids.supplied_id
          OR any_preview_row.row_json->>'line_id' = supplied_ids.supplied_id
        )
    );

    IF jsonb_array_length(COALESCE(v_stale_selection_ids, '[]'::jsonb)) > 0
       OR jsonb_array_length(COALESCE(v_missing_selection_ids, '[]'::jsonb)) > 0 THEN
      RAISE EXCEPTION 'WORKBENCH_STALE_SELECTION'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'WORKBENCH_STALE_SELECTION',
                'session_id', p_workbench_session_id::text,
                'session_version', v_session.version,
                'operation_id', p_operation_id::text,
                'rejected_preview_row_ids', COALESCE(v_stale_selection_ids, '[]'::jsonb) || COALESCE(v_missing_selection_ids, '[]'::jsonb),
                'stale_preview_row_ids', COALESCE(v_stale_selection_ids, '[]'::jsonb),
                'missing_preview_row_ids', COALESCE(v_missing_selection_ids, '[]'::jsonb),
                'message', 'Selected preview rows are not part of the current ready workbench session version. Refresh the preview page and try again.'
              )::text;
    END IF;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_draft_scope_selected_candidates;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_draft_scope_selected_candidates ON COMMIT DROP AS
  WITH selected_base_raw AS (
    SELECT
      preview_row.id AS preview_row_id,
      preview_row.row_key,
      preview_row.session_id,
      preview_row.candidate_id,
      COALESCE(NULLIF(BTRIM(preview_row.section), ''), 'canonical_preview_lines') AS section,
      preview_row.selection_state,
      preview_row.row_ordinal,
      preview_row.row_json,
      preview_row.timesheet_id,
      UPPER(NULLIF(BTRIM(COALESCE(preview_row.key_type, preview_row.row_json#>>'{economic_key,key_type}', preview_row.row_json->>'component_key_type', '')), '')) AS key_type,
      NULLIF(BTRIM(COALESCE(preview_row.key_value, preview_row.row_json#>>'{economic_key,key_value}', preview_row.row_json->>'component_key_value', '')), '') AS key_value,
      UPPER(NULLIF(BTRIM(COALESCE(preview_row.row_json->>'pay_channel', preview_row.row_json->>'current_pay_method', preview_row.row_json->>'candidate_pay_method', '')), '')) AS pay_channel,
      CASE WHEN NULLIF(BTRIM(COALESCE(preview_row.row_json->>'finance_case_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN NULLIF(BTRIM(COALESCE(preview_row.row_json->>'finance_case_id', '')), '')::uuid ELSE NULL::uuid END AS finance_case_id,
      CASE WHEN COALESCE(preview_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ROUND((preview_row.row_json->>'amount_ex_vat')::numeric, 2) ELSE NULL::numeric END AS amount_ex_vat
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = p_workbench_session_id
      AND preview_row.session_version = v_session.version
      AND COALESCE(preview_row.selected, false) = true
      AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
      AND (v_scope_filter = 'ALL' OR UPPER(BTRIM(COALESCE(preview_row.row_json->>'pay_channel', preview_row.row_json->>'current_pay_method', preview_row.row_json->>'candidate_pay_method', ''))) = v_scope_filter)
      AND (
        p_selected_preview_row_ids IS NULL
        OR EXISTS (
          SELECT 1
          FROM pg_temp.tmp_pay_workbench_draft_scope_supplied_ids AS supplied_id
          WHERE supplied_id.supplied_id IN (preview_row.id::text, preview_row.row_key, preview_row.row_json->>'preview_row_id', preview_row.row_json->>'row_id', preview_row.row_json->>'line_id')
        )
      )
      AND (
        p_selected_preview_row_ids IS NOT NULL
        OR NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_candidate_scope AS existing_scope
          WHERE existing_scope.operation_id = p_operation_id
            AND existing_scope.workbench_session_id = p_workbench_session_id
            AND existing_scope.candidate_id = preview_row.candidate_id
            AND existing_scope.pay_channel = UPPER(BTRIM(COALESCE(preview_row.row_json->>'pay_channel', preview_row.row_json->>'current_pay_method', preview_row.row_json->>'candidate_pay_method', '')))
        )
      )
    ORDER BY preview_row.row_ordinal, preview_row.id
    LIMIT 100
  ), selected_timesheet_ids AS (
    SELECT COALESCE(
      array_agg(DISTINCT selected_base_raw.timesheet_id ORDER BY selected_base_raw.timesheet_id),
      array[]::uuid[]
    ) AS timesheet_ids
    FROM selected_base_raw
    WHERE selected_base_raw.timesheet_id IS NOT NULL
  ), selected_rotation_scope AS (
    SELECT DISTINCT ON (rotation_scope.requested_timesheet_id)
      rotation_scope.requested_timesheet_id,
      COALESCE(rotation_scope.canonical_timesheet_id, rotation_scope.requested_timesheet_id) AS canonical_timesheet_id,
      (rotation_scope.family_timesheet_id IS NOT NULL AND rotation_scope.family_is_current IS NOT NULL) AS rotation_scope_resolved,
      COALESCE(rotation_scope.requested_is_canonical, false) AS requested_is_canonical
    FROM selected_timesheet_ids
    JOIN public._pay_timesheet_rotation_scope(selected_timesheet_ids.timesheet_ids) AS rotation_scope
      ON true
    ORDER BY
      rotation_scope.requested_timesheet_id,
      rotation_scope.family_is_current DESC NULLS LAST,
      rotation_scope.family_version DESC NULLS LAST,
      rotation_scope.family_timesheet_id
  ), selected_base AS (
    SELECT
      selected_base_raw.preview_row_id,
      selected_base_raw.row_key,
      selected_base_raw.session_id,
      selected_base_raw.candidate_id,
      selected_base_raw.section,
      selected_base_raw.selection_state,
      selected_base_raw.row_ordinal,
      jsonb_strip_nulls(
        CASE
          WHEN selected_base_raw.timesheet_id IS NULL OR selected_rotation_scope.canonical_timesheet_id IS NULL THEN selected_base_raw.row_json
          ELSE selected_base_raw.row_json
            || jsonb_build_object(
              'timesheet_id', selected_rotation_scope.canonical_timesheet_id::text,
              'real_business_timesheet_id', selected_rotation_scope.canonical_timesheet_id::text,
              'economic_key', COALESCE(selected_base_raw.row_json->'economic_key', '{}'::jsonb)
                || jsonb_build_object('timesheet_id', selected_rotation_scope.canonical_timesheet_id::text)
            )
            || CASE
              WHEN selected_base_raw.timesheet_id IS DISTINCT FROM selected_rotation_scope.canonical_timesheet_id THEN jsonb_build_object(
                'rotation_requested_timesheet_id', selected_base_raw.timesheet_id::text
              )
              ELSE '{}'::jsonb
            END
        END
      ) AS row_json,
      COALESCE(selected_rotation_scope.canonical_timesheet_id, selected_base_raw.timesheet_id) AS timesheet_id,
      selected_base_raw.key_type,
      selected_base_raw.key_value,
      selected_base_raw.pay_channel,
      selected_base_raw.finance_case_id,
      selected_base_raw.amount_ex_vat,
      CASE
        WHEN selected_base_raw.timesheet_id IS NULL THEN false
        WHEN COALESCE(selected_rotation_scope.rotation_scope_resolved, false) = false THEN true
        WHEN selected_rotation_scope.canonical_timesheet_id IS NULL THEN true
        WHEN COALESCE(selected_rotation_scope.requested_is_canonical, false) = false THEN true
        ELSE false
      END AS rotation_validation_failed,
      CASE
        WHEN selected_base_raw.timesheet_id IS NULL THEN NULL::text
        WHEN COALESCE(selected_rotation_scope.rotation_scope_resolved, false) = false THEN 'SELECTED_PREVIEW_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
        WHEN selected_rotation_scope.canonical_timesheet_id IS NULL THEN 'SELECTED_PREVIEW_CANONICAL_TIMESHEET_NOT_RESOLVED'
        WHEN COALESCE(selected_rotation_scope.requested_is_canonical, false) = false THEN 'SELECTED_PREVIEW_TIMESHEET_NOT_CANONICAL_REFRESH_REQUIRED'
        ELSE NULL::text
      END AS rotation_failure_reason
    FROM selected_base_raw
    LEFT JOIN selected_rotation_scope
      ON selected_rotation_scope.requested_timesheet_id = selected_base_raw.timesheet_id
  )
  SELECT
    selected_base.*,
    jsonb_strip_nulls(jsonb_build_object(
      'timesheet_id', CASE WHEN selected_base.timesheet_id IS NULL THEN NULL ELSE selected_base.timesheet_id::text END,
      'key_type', selected_base.key_type,
      'key_value', selected_base.key_value
    )) AS economic_key_json,
    public.pay_workbench_preview_line_contract_ok(
      p_line_json => jsonb_strip_nulls(
        selected_base.row_json
        || jsonb_build_object(
          'row_key', selected_base.row_key,
          'preview_row_pk', selected_base.preview_row_id::text,
          'selection_state', selected_base.selection_state
        )
      ),
      p_economic_key_json => jsonb_strip_nulls(jsonb_build_object(
        'timesheet_id', CASE WHEN selected_base.timesheet_id IS NULL THEN NULL ELSE selected_base.timesheet_id::text END,
        'key_type', selected_base.key_type,
        'key_value', selected_base.key_value
      )),
      p_target_section => selected_base.section
    ) AS preview_contract_json
  FROM selected_base;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'preview_row_id', invalid_rows.preview_row_id::text,
           'row_key', invalid_rows.row_key,
           'candidate_id', invalid_rows.candidate_id::text,
           'reasons', COALESCE(invalid_rows.preview_contract_json->'reasons', '[]'::jsonb)
             || CASE WHEN invalid_rows.rotation_validation_failed IS TRUE THEN jsonb_build_array(invalid_rows.rotation_failure_reason) ELSE '[]'::jsonb END
         ) ORDER BY invalid_rows.row_ordinal, invalid_rows.preview_row_id), '[]'::jsonb)
  INTO v_malformed_selected_preview_rows
  FROM (
    SELECT selected_candidate.*
    FROM pg_temp.tmp_pay_workbench_draft_scope_selected_candidates AS selected_candidate
    WHERE selected_candidate.rotation_validation_failed IS TRUE
       OR LOWER(BTRIM(COALESCE(selected_candidate.preview_contract_json->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
       OR LOWER(BTRIM(COALESCE(selected_candidate.preview_contract_json->>'selection_allowed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
       OR UPPER(BTRIM(COALESCE(selected_candidate.section, ''))) <> 'CANONICAL_PREVIEW_LINES'
       OR UPPER(BTRIM(COALESCE(selected_candidate.selection_state, ''))) <> 'SELECTED'
       OR UPPER(BTRIM(COALESCE(selected_candidate.key_type, ''))) NOT IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE','MANUAL_CARRY_FORWARD')
       OR selected_candidate.key_value IS NULL
       OR (selected_candidate.key_type = 'TS_DAY' AND selected_candidate.key_value !~ '^\d{4}-\d{2}-\d{2}$')
       OR selected_candidate.amount_ex_vat IS NULL
       OR ROUND(COALESCE(selected_candidate.amount_ex_vat, 0), 2) = 0
    ORDER BY selected_candidate.row_ordinal, selected_candidate.preview_row_id
    LIMIT 25
  ) AS invalid_rows;

  IF jsonb_array_length(COALESCE(v_malformed_selected_preview_rows, '[]'::jsonb)) > 0 THEN
    RAISE EXCEPTION 'MALFORMED_PREVIEW_ROW_NOT_DRAFTABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'MALFORMED_PREVIEW_ROW_NOT_DRAFTABLE',
              'operation_id', p_operation_id::text,
              'workbench_session_id', p_workbench_session_id::text,
              'malformed_selected_preview_rows', COALESCE(v_malformed_selected_preview_rows, '[]'::jsonb),
              'message', 'Selected preview rows are not valid draftable Ready to Pay rows. Refresh the preview and try again.'
            )::text;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_draft_scope_selected_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_draft_scope_selected_page ON COMMIT DROP AS
  SELECT selected_candidate.*
  FROM pg_temp.tmp_pay_workbench_draft_scope_selected_candidates AS selected_candidate
  WHERE selected_candidate.rotation_validation_failed IS NOT TRUE
    AND LOWER(BTRIM(COALESCE(selected_candidate.preview_contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND LOWER(BTRIM(COALESCE(selected_candidate.preview_contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND lower(COALESCE(selected_candidate.section, '')) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(selected_candidate.selection_state, ''))) = 'SELECTED'
    AND selected_candidate.pay_channel IN ('PAYE', 'UMBRELLA')
    AND selected_candidate.key_type IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE','MANUAL_CARRY_FORWARD')
    AND selected_candidate.key_value IS NOT NULL
    AND NOT (selected_candidate.key_type = 'TS_DAY' AND selected_candidate.key_value !~ '^\d{4}-\d{2}-\d{2}$')
    AND selected_candidate.amount_ex_vat IS NOT NULL
    AND ROUND(COALESCE(selected_candidate.amount_ex_vat, 0), 2) <> 0
  ORDER BY selected_candidate.row_ordinal, selected_candidate.preview_row_id
  LIMIT 100;

  IF NOT EXISTS (SELECT 1 FROM pg_temp.tmp_pay_workbench_draft_scope_selected_page) THEN
    IF COALESCE(v_selected_input_count, 0) > 0 THEN
      RAISE EXCEPTION 'DRAFT_CANDIDATE_SCOPE_EMPTY'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'DRAFT_CANDIDATE_SCOPE_EMPTY',
                'operation_id', p_operation_id::text,
                'workbench_session_id', p_workbench_session_id::text,
                'selected_input_count', v_selected_input_count,
                'message', 'Selected preview rows did not produce any valid row-backed candidate scope rows.'
              )::text;
    END IF;
    RETURN QUERY SELECT 0::integer, 0::integer, 0::integer, 0::integer, 0::integer;
    RETURN;
  END IF;

  INSERT INTO public.banking_pay_operation_candidate_scope (
    operation_id,
    workbench_session_id,
    source_snapshot_run_id,
    source_session_version,
    candidate_id,
    pay_channel,
    pay_batch_id,
    selected_preview_row_ids_json,
    selected_timesheet_ids_json,
    selected_finance_case_ids_json,
    effective_payees_json,
    effective_case_resolution_states_json,
    effective_canonical_preview_lines_json,
    selected_canonical_preview_lines_json,
    baseline_component_rows_json,
    candidate_totals_json,
    allocation_basis_json,
    scope_hash,
    chunk_sequence,
    status,
    created_at_utc,
    updated_at_utc
  )
  SELECT
    p_operation_id,
    p_workbench_session_id,
    v_session.source_snapshot_run_id,
    v_session.version,
    selected_page.candidate_id,
    selected_page.pay_channel,
    v_operation.pay_batch_id,
    COALESCE(jsonb_agg(to_jsonb(selected_page.preview_row_id::text) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id), '[]'::jsonb),
    COALESCE(jsonb_agg(to_jsonb(selected_page.timesheet_id::text) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id) FILTER (WHERE selected_page.timesheet_id IS NOT NULL), '[]'::jsonb),
    COALESCE(jsonb_agg(to_jsonb(selected_page.finance_case_id::text) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id) FILTER (WHERE selected_page.finance_case_id IS NOT NULL), '[]'::jsonb),
    COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'source', 'banking_pay_workbench_preview_rows',
      'preview_row_id', selected_page.preview_row_id::text,
      'row_key', selected_page.row_key,
      'pay_channel', selected_page.pay_channel,
      'payee', COALESCE(selected_page.row_json->'effective_payee', selected_page.row_json->'payee', selected_page.row_json->'payee_map')
    )) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id) FILTER (WHERE selected_page.row_json ? 'effective_payee' OR selected_page.row_json ? 'payee' OR selected_page.row_json ? 'payee_map'), '[]'::jsonb),
    jsonb_strip_nulls(jsonb_build_object(
      'source', 'banking_pay_workbench_preview_rows',
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
      'same_week_paye_override', COALESCE(p_same_week_paye_override_json, '{}'::jsonb),
      'rows', COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'preview_row_id', selected_page.preview_row_id::text,
        'row_key', selected_page.row_key,
        'finance_case_id', CASE WHEN selected_page.finance_case_id IS NULL THEN NULL ELSE selected_page.finance_case_id::text END,
        'case_resolution_summary', selected_page.row_json->'case_resolution_summary'
      )) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id) FILTER (WHERE selected_page.row_json ? 'case_resolution_summary' OR selected_page.finance_case_id IS NOT NULL), '[]'::jsonb)
    )),
    COALESCE(jsonb_agg(jsonb_strip_nulls(
      selected_page.row_json
      || jsonb_build_object(
        'source', 'banking_pay_workbench_preview_rows',
        'preview_row_id', selected_page.preview_row_id::text,
        'preview_row_pk', selected_page.preview_row_id::text,
        'row_key', selected_page.row_key,
        'row_ordinal', selected_page.row_ordinal,
        'candidate_id', selected_page.candidate_id::text,
        'timesheet_id', CASE WHEN selected_page.timesheet_id IS NULL THEN NULL ELSE selected_page.timesheet_id::text END,
        'finance_case_id', CASE WHEN selected_page.finance_case_id IS NULL THEN NULL ELSE selected_page.finance_case_id::text END,
        'pay_channel', selected_page.pay_channel,
        'section', selected_page.section,
        'selection_state', 'SELECTED',
        'status', 'READY',
        'amount_ex_vat', selected_page.amount_ex_vat,
        'key_type', selected_page.key_type,
        'key_value', selected_page.key_value,
        'economic_key', selected_page.economic_key_json,
        'preview_contract', selected_page.preview_contract_json,
        'draftable', true,
        'row_backed_draft_scope', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
        'effective', true
      )
    ) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id), '[]'::jsonb),
    COALESCE(jsonb_agg(jsonb_strip_nulls(
      selected_page.row_json
      || jsonb_build_object(
        'source', 'banking_pay_workbench_preview_rows',
        'preview_row_id', selected_page.preview_row_id::text,
        'preview_row_pk', selected_page.preview_row_id::text,
        'row_key', selected_page.row_key,
        'row_ordinal', selected_page.row_ordinal,
        'candidate_id', selected_page.candidate_id::text,
        'timesheet_id', CASE WHEN selected_page.timesheet_id IS NULL THEN NULL ELSE selected_page.timesheet_id::text END,
        'finance_case_id', CASE WHEN selected_page.finance_case_id IS NULL THEN NULL ELSE selected_page.finance_case_id::text END,
        'pay_channel', selected_page.pay_channel,
        'section', selected_page.section,
        'selection_state', 'SELECTED',
        'status', 'READY',
        'amount_ex_vat', selected_page.amount_ex_vat,
        'key_type', selected_page.key_type,
        'key_value', selected_page.key_value,
        'economic_key', selected_page.economic_key_json,
        'preview_contract', selected_page.preview_contract_json,
        'draftable', true,
        'row_backed_draft_scope', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      )
    ) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id), '[]'::jsonb),
    COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'source', 'banking_pay_workbench_preview_rows',
      'preview_row_id', selected_page.preview_row_id::text,
      'row_key', selected_page.row_key,
      'row_ordinal', selected_page.row_ordinal,
      'timesheet_id', CASE WHEN selected_page.timesheet_id IS NULL THEN NULL ELSE selected_page.timesheet_id::text END,
      'candidate_id', selected_page.candidate_id::text,
      'pay_channel', selected_page.pay_channel,
      'economic_key', selected_page.economic_key_json,
      'amount_ex_vat', selected_page.amount_ex_vat,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    )) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id), '[]'::jsonb),
    jsonb_build_object(
      'selected_row_count_seeded_in_page', COUNT(*)::integer,
      'selected_amount_ex_vat_seeded_in_page', ROUND(COALESCE(SUM(selected_page.amount_ex_vat), 0), 2),
      'selected_preview_row_ids', COALESCE(jsonb_agg(to_jsonb(selected_page.preview_row_id::text) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id), '[]'::jsonb),
      'row_backed_draft_scope', true,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    ),
    jsonb_build_object(
      'source', 'banking_pay_workbench_preview_rows',
      'operation_id', p_operation_id::text,
      'workbench_session_id', p_workbench_session_id::text,
      'pay_channel_scope', v_scope_filter,
      'same_week_paye_override', COALESCE(p_same_week_paye_override_json, '{}'::jsonb),
      'selected_rows_are_row_backed', true,
      'selected_preview_row_ids', COALESCE(jsonb_agg(to_jsonb(selected_page.preview_row_id::text) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id), '[]'::jsonb),
      'economic_keyspace', 'timesheet_id,key_type,key_value',
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    ),
    md5(jsonb_build_object(
      'operation_id', p_operation_id::text,
      'workbench_session_id', p_workbench_session_id::text,
      'candidate_id', selected_page.candidate_id::text,
      'pay_channel', selected_page.pay_channel,
      'selected_preview_row_ids', COALESCE(jsonb_agg(to_jsonb(selected_page.preview_row_id::text) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id), '[]'::jsonb),
      'source_session_version', v_session.version
    )::text),
    ROW_NUMBER() OVER (ORDER BY selected_page.pay_channel, selected_page.candidate_id)::integer,
    'SCOPED',
    v_now,
    v_now
  FROM pg_temp.tmp_pay_workbench_draft_scope_selected_page AS selected_page
  WHERE selected_page.pay_channel IN ('PAYE', 'UMBRELLA')
  GROUP BY selected_page.candidate_id, selected_page.pay_channel
  ON CONFLICT (operation_id, candidate_id, pay_channel)
  DO UPDATE
  SET workbench_session_id = EXCLUDED.workbench_session_id,
      source_snapshot_run_id = EXCLUDED.source_snapshot_run_id,
      source_session_version = EXCLUDED.source_session_version,
      pay_batch_id = COALESCE(public.banking_pay_operation_candidate_scope.pay_batch_id, EXCLUDED.pay_batch_id),
      selected_preview_row_ids_json = EXCLUDED.selected_preview_row_ids_json,
      selected_timesheet_ids_json = EXCLUDED.selected_timesheet_ids_json,
      selected_finance_case_ids_json = EXCLUDED.selected_finance_case_ids_json,
      effective_payees_json = EXCLUDED.effective_payees_json,
      effective_case_resolution_states_json = EXCLUDED.effective_case_resolution_states_json,
      effective_canonical_preview_lines_json = EXCLUDED.effective_canonical_preview_lines_json,
      selected_canonical_preview_lines_json = EXCLUDED.selected_canonical_preview_lines_json,
      baseline_component_rows_json = EXCLUDED.baseline_component_rows_json,
      candidate_totals_json = EXCLUDED.candidate_totals_json,
      allocation_basis_json = COALESCE(public.banking_pay_operation_candidate_scope.allocation_basis_json, '{}'::jsonb) || EXCLUDED.allocation_basis_json,
      scope_hash = EXCLUDED.scope_hash,
      chunk_sequence = EXCLUDED.chunk_sequence,
      status = CASE WHEN public.banking_pay_operation_candidate_scope.status IN ('PENDING', 'SCOPED') THEN 'SCOPED' ELSE public.banking_pay_operation_candidate_scope.status END,
      updated_at_utc = v_now;

  SELECT COUNT(DISTINCT selected_page.candidate_id::text || ':' || selected_page.pay_channel)::integer,
         COUNT(*)::integer,
         COUNT(DISTINCT selected_page.timesheet_id) FILTER (WHERE selected_page.timesheet_id IS NOT NULL)::integer,
         COUNT(DISTINCT selected_page.finance_case_id) FILTER (WHERE selected_page.finance_case_id IS NOT NULL)::integer,
         COUNT(DISTINCT selected_page.pay_channel)::integer
  INTO v_candidate_scope_count, v_selected_count, v_timesheet_count, v_finance_case_count, v_pay_channel_count
  FROM pg_temp.tmp_pay_workbench_draft_scope_selected_page AS selected_page;

  IF COALESCE(v_selected_count, 0) > 0 AND COALESCE(v_candidate_scope_count, 0) <= 0 THEN
    RAISE EXCEPTION 'DRAFT_CANDIDATE_SCOPE_EMPTY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_CANDIDATE_SCOPE_EMPTY',
              'operation_id', p_operation_id::text,
              'workbench_session_id', p_workbench_session_id::text,
              'selected_row_count', COALESCE(v_selected_count, 0),
              'message', 'Selected preview rows did not persist into candidate scope.'
            )::text;
  END IF;

  UPDATE public.banking_pay_operations AS operation_update
  SET progress_json = jsonb_strip_nulls(
        COALESCE(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'draft_scope_last_seeded_at_utc', v_now::text,
          'draft_scope_last_selected_row_count', COALESCE(v_selected_count, 0),
          'draft_scope_last_candidate_scope_count', COALESCE(v_candidate_scope_count, 0),
          'draft_scope_selection_resolved_to_current', COALESCE(v_selection_resolved_to_current, false),
          'draft_scope_resolved_current_selected_preview_row_ids', COALESCE(v_resolved_current_selection_ids, '[]'::jsonb)
        )
      ),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN QUERY
  SELECT
    COALESCE(v_candidate_scope_count, 0),
    COALESCE(v_selected_count, 0),
    COALESCE(v_timesheet_count, 0),
    COALESCE(v_finance_case_count, 0),
    COALESCE(v_pay_channel_count, 0);
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_batch_freshness_scope_seed(
  p_operation_id uuid,
  p_pay_batch_id uuid DEFAULT NULL::uuid,
  p_cursor_json jsonb DEFAULT NULL::jsonb,
  p_limit integer DEFAULT 100
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation public.banking_pay_operations%ROWTYPE;
  v_pay_batch_id uuid := p_pay_batch_id;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_cursor_candidate_id uuid := NULL::uuid;
  v_cursor_item_id uuid := NULL::uuid;
  v_seeded_count integer := 0;
  v_page_count integer := 0;
  v_has_more boolean := false;
  v_next_cursor jsonb := NULL::jsonb;
  v_last_candidate_id uuid := NULL::uuid;
  v_last_item_id uuid := NULL::uuid;
  v_existing_max_ordinal bigint := 0;
  v_new_unit_count integer := 0;
  v_touched_unit_count integer := 0;
  v_page_scope_hash text := NULL::text;
  v_prev_summary jsonb := '{}'::jsonb;
  v_new_summary jsonb := '{}'::jsonb;
  v_prev_total_units integer := 0;
  v_prev_pending_units integer := 0;
  v_prev_seeded_units integer := 0;
  v_new_total_units integer := 0;
  v_new_pending_units integer := 0;
  v_new_seeded_units integer := 0;
  v_prev_scope_hash text := NULL::text;
  v_new_scope_hash text := NULL::text;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_freshness_scope_seed: p_operation_id is required';
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_batch_freshness_scope_seed operation not found: %', p_operation_id;
  END IF;

  v_pay_batch_id := COALESCE(v_pay_batch_id, v_operation.pay_batch_id);
  IF v_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_freshness_scope_seed: pay_batch_id is required';
  END IF;

  IF v_operation.pay_batch_id IS NOT NULL AND v_operation.pay_batch_id <> v_pay_batch_id THEN
    RAISE EXCEPTION 'pay_batch_freshness_scope_seed operation % belongs to pay batch %, not %', p_operation_id, v_operation.pay_batch_id, v_pay_batch_id;
  END IF;

  PERFORM 1
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = v_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_batch_freshness_scope_seed pay batch not found: %', v_pay_batch_id;
  END IF;

  IF p_cursor_json IS NOT NULL AND jsonb_typeof(p_cursor_json) = 'object' THEN
    IF COALESCE(p_cursor_json->>'last_candidate_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_cursor_candidate_id := (p_cursor_json->>'last_candidate_id')::uuid;
    END IF;
    IF COALESCE(p_cursor_json->>'last_pay_batch_item_id', p_cursor_json->>'last_item_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_cursor_item_id := COALESCE(p_cursor_json->>'last_pay_batch_item_id', p_cursor_json->>'last_item_id')::uuid;
    END IF;
  END IF;

  SELECT COALESCE(MAX(scope_unit.unit_ordinal), 0)
  INTO v_existing_max_ordinal
  FROM public.banking_pay_operation_scope_units AS scope_unit
  WHERE scope_unit.operation_id = p_operation_id
    AND scope_unit.phase = 'FRESHNESS'
    AND scope_unit.unit_type = 'PAY_BATCH_ITEM';

  DROP TABLE IF EXISTS pg_temp.tmp_pay_batch_freshness_seed_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_batch_freshness_seed_page ON COMMIT DROP AS
  WITH ordered_items AS (
    SELECT
      batch_candidate.candidate_id,
      batch_item.id AS pay_batch_item_id,
      batch_item.pay_batch_candidate_id,
      batch_item.item_type,
      batch_item.timesheet_id,
      batch_item.source_ref,
      batch_item.description,
      batch_item.amount_ex_vat,
      batch_item.amount_vat,
      batch_item.amount_inc_vat,
      batch_item.pay_channel,
      batch_item.finance_case_id,
      batch_item.finance_component_id,
      batch_item.frozen_component_key_type,
      batch_item.frozen_component_key_value,
      batch_item.frozen_component_snapshot_json,
      batch_item.frozen_source_basis_json,
      batch_item.frozen_component_classification,
      batch_item.frozen_source_amount,
      batch_item.frozen_target_amount_ex_vat,
      batch_item.frozen_target_amount_vat,
      batch_item.frozen_target_amount_inc_vat,
      batch_item.payout_instruction_snapshot_json,
      batch_item.operation_source_key,
      COALESCE(batch_item.is_voided, false) AS is_voided
    FROM public.pay_batch_items AS batch_item
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = batch_item.pay_batch_candidate_id
    WHERE batch_candidate.pay_batch_id = v_pay_batch_id
      AND (
        v_cursor_candidate_id IS NULL
        OR batch_candidate.candidate_id > v_cursor_candidate_id
        OR (batch_candidate.candidate_id = v_cursor_candidate_id AND batch_item.id > COALESCE(v_cursor_item_id, '00000000-0000-0000-0000-000000000000'::uuid))
      )
    ORDER BY batch_candidate.candidate_id, batch_item.id
    LIMIT (v_limit + 1)
  )
  SELECT
    ordered_items.*,
    row_number() OVER (ORDER BY ordered_items.candidate_id, ordered_items.pay_batch_item_id)::integer AS page_ordinal
  FROM ordered_items;

  SELECT COUNT(*)::integer
  INTO v_page_count
  FROM pg_temp.tmp_pay_batch_freshness_seed_page AS page_row;

  v_has_more := COALESCE(v_page_count, 0) > v_limit;

  WITH seed_rows AS (
    SELECT
      page_row.*,
      (v_existing_max_ordinal + page_row.page_ordinal)::bigint AS unit_ordinal,
      policy_key.timesheet_id AS resolved_timesheet_id,
      policy_key.key_type AS resolved_key_type,
      policy_key.key_value AS resolved_key_value,
      policy_key.key_resolution_source,
      policy_key.key_resolution_failure_reason
    FROM pg_temp.tmp_pay_batch_freshness_seed_page AS page_row
    LEFT JOIN LATERAL public._pay_policy_x_resolve_post_draft_economic_key(
      p_pay_batch_item_id => page_row.pay_batch_item_id,
      p_pay_batch_id => v_pay_batch_id,
      p_timesheet_id => page_row.timesheet_id,
      p_item_type => page_row.item_type,
      p_frozen_key_type => page_row.frozen_component_key_type,
      p_frozen_key_value => page_row.frozen_component_key_value,
      p_frozen_component_snapshot_json => COALESCE(page_row.frozen_component_snapshot_json, '{}'::jsonb),
      p_frozen_source_basis_json => COALESCE(page_row.frozen_source_basis_json, '{}'::jsonb),
      p_breakdown_meta_json => '{}'::jsonb,
      p_target_snapshot_json => NULL::jsonb
    ) AS policy_key ON true
    WHERE page_row.page_ordinal <= v_limit
  ), upserted_units AS (
    INSERT INTO public.banking_pay_operation_scope_units (
      operation_id,
      pay_batch_id,
      phase,
      unit_type,
      unit_key,
      unit_payload_json,
      unit_ordinal,
      status,
      chunk_id,
      result_hash,
      error_json,
      created_at_utc,
      updated_at_utc
    )
    SELECT
      p_operation_id,
      v_pay_batch_id,
      'FRESHNESS',
      'PAY_BATCH_ITEM',
      'pay_batch_item:' || seed_rows.pay_batch_item_id::text,
      jsonb_build_object(
        'pay_batch_item_id', seed_rows.pay_batch_item_id::text,
        'pay_batch_candidate_id', seed_rows.pay_batch_candidate_id::text,
        'candidate_id', seed_rows.candidate_id::text,
        'timesheet_id', CASE WHEN seed_rows.timesheet_id IS NULL THEN NULL ELSE seed_rows.timesheet_id::text END,
        'item_type', seed_rows.item_type,
        'source_ref', seed_rows.source_ref,
        'description', seed_rows.description,
        'pay_channel', seed_rows.pay_channel,
        'finance_case_id', CASE WHEN seed_rows.finance_case_id IS NULL THEN NULL ELSE seed_rows.finance_case_id::text END,
        'finance_component_id', CASE WHEN seed_rows.finance_component_id IS NULL THEN NULL ELSE seed_rows.finance_component_id::text END,
        'amounts', jsonb_build_object(
          'amount_ex_vat', seed_rows.amount_ex_vat,
          'amount_vat', seed_rows.amount_vat,
          'amount_inc_vat', seed_rows.amount_inc_vat
        ),
        'economic_key', jsonb_strip_nulls(jsonb_build_object(
          'timesheet_id', CASE WHEN seed_rows.resolved_timesheet_id IS NULL THEN NULL ELSE seed_rows.resolved_timesheet_id::text END,
          'key_type', seed_rows.resolved_key_type,
          'key_value', seed_rows.resolved_key_value,
          'resolution_source', seed_rows.key_resolution_source,
          'failure_reason', seed_rows.key_resolution_failure_reason
        )),
        'frozen', jsonb_strip_nulls(jsonb_build_object(
          'frozen_component_key_type', seed_rows.frozen_component_key_type,
          'frozen_component_key_value', seed_rows.frozen_component_key_value,
          'frozen_component_snapshot_json', seed_rows.frozen_component_snapshot_json,
          'frozen_source_basis_json', seed_rows.frozen_source_basis_json,
          'frozen_component_classification', CASE WHEN seed_rows.frozen_component_classification IS NULL THEN NULL ELSE seed_rows.frozen_component_classification::text END,
          'frozen_source_amount', seed_rows.frozen_source_amount,
          'frozen_target_amount_ex_vat', seed_rows.frozen_target_amount_ex_vat,
          'frozen_target_amount_vat', seed_rows.frozen_target_amount_vat,
          'frozen_target_amount_inc_vat', seed_rows.frozen_target_amount_inc_vat
        )),
        'payout_instruction_snapshot_json', seed_rows.payout_instruction_snapshot_json,
        'operation_source_key', seed_rows.operation_source_key,
        'is_voided', seed_rows.is_voided
      ),
      seed_rows.unit_ordinal,
      'PENDING',
      NULL::uuid,
      NULL::text,
      NULL::jsonb,
      v_now,
      v_now
    FROM seed_rows
    ON CONFLICT (operation_id, phase, unit_type, unit_key)
    DO UPDATE
    SET unit_payload_json = EXCLUDED.unit_payload_json,
        unit_ordinal = LEAST(public.banking_pay_operation_scope_units.unit_ordinal, EXCLUDED.unit_ordinal),
        status = CASE
          WHEN public.banking_pay_operation_scope_units.status IN ('FRESH', 'STALE', 'ERROR') THEN public.banking_pay_operation_scope_units.status
          ELSE 'PENDING'
        END,
        error_json = CASE
          WHEN public.banking_pay_operation_scope_units.status IN ('FRESH', 'STALE') THEN public.banking_pay_operation_scope_units.error_json
          ELSE NULL::jsonb
        END,
        updated_at_utc = v_now
    RETURNING
      (xmax = '0'::xid) AS inserted_row,
      unit_key,
      unit_ordinal
  )
  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE upserted_units.inserted_row)::integer,
    md5(COALESCE(string_agg(upserted_units.unit_key, '|' ORDER BY upserted_units.unit_ordinal, upserted_units.unit_key) FILTER (WHERE upserted_units.inserted_row), 'NO_NEW_SCOPE_UNITS'))
  INTO
    v_touched_unit_count,
    v_new_unit_count,
    v_page_scope_hash
  FROM upserted_units;

  v_seeded_count := COALESCE(v_new_unit_count, 0);

  IF v_has_more THEN
    SELECT jsonb_build_object(
      'last_candidate_id', page_row.candidate_id::text,
      'last_pay_batch_item_id', page_row.pay_batch_item_id::text
    )
    INTO v_next_cursor
    FROM pg_temp.tmp_pay_batch_freshness_seed_page AS page_row
    WHERE page_row.page_ordinal = v_limit;
  ELSE
    v_next_cursor := NULL::jsonb;
  END IF;

  v_prev_summary := CASE
    WHEN jsonb_typeof(COALESCE(v_operation.progress_json, '{}'::jsonb)->'freshness_summary') = 'object'
      THEN COALESCE(v_operation.progress_json->'freshness_summary', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_prev_total_units := COALESCE(
    CASE WHEN COALESCE(v_prev_summary->>'total_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'total_units')::integer ELSE NULL::integer END,
    CASE WHEN COALESCE(v_operation.progress_json->>'freshness_total_units', '') ~ '^[0-9]+$' THEN (v_operation.progress_json->>'freshness_total_units')::integer ELSE NULL::integer END,
    0
  );
  v_prev_pending_units := COALESCE(
    CASE WHEN COALESCE(v_prev_summary->>'pending_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'pending_units')::integer ELSE NULL::integer END,
    CASE WHEN COALESCE(v_operation.progress_json->>'freshness_pending_units', '') ~ '^[0-9]+$' THEN (v_operation.progress_json->>'freshness_pending_units')::integer ELSE NULL::integer END,
    0
  );
  v_prev_seeded_units := COALESCE(
    CASE WHEN COALESCE(v_prev_summary->>'seeded_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'seeded_units')::integer ELSE NULL::integer END,
    v_prev_total_units,
    0
  );
  v_prev_scope_hash := COALESCE(
    NULLIF(BTRIM(COALESCE(v_prev_summary->>'scope_hash', '')), ''),
    NULLIF(BTRIM(COALESCE(v_operation.progress_json->>'freshness_scope_hash', '')), '')
  );

  v_new_seeded_units := COALESCE(v_prev_seeded_units, 0) + COALESCE(v_new_unit_count, 0);
  v_new_total_units := GREATEST(COALESCE(v_prev_total_units, 0) + COALESCE(v_new_unit_count, 0), v_new_seeded_units);
  v_new_pending_units := COALESCE(v_prev_pending_units, 0) + COALESCE(v_new_unit_count, 0);
  v_new_scope_hash := CASE
    WHEN COALESCE(v_new_unit_count, 0) <= 0 THEN v_prev_scope_hash
    WHEN v_prev_scope_hash IS NULL THEN v_page_scope_hash
    ELSE md5(v_prev_scope_hash || '|seed|' || COALESCE(v_page_scope_hash, 'NO_NEW_SCOPE_UNITS'))
  END;

  v_new_summary := jsonb_strip_nulls(jsonb_build_object(
    'status', 'PENDING',
    'operation_id', p_operation_id::text,
    'pay_batch_id', v_pay_batch_id::text,
    'phase', 'FRESHNESS',
    'unit_type', 'PAY_BATCH_ITEM',
    'seeded_units', COALESCE(v_new_seeded_units, 0),
    'total_units', COALESCE(v_new_total_units, 0),
    'fresh_units', COALESCE(CASE WHEN COALESCE(v_prev_summary->>'fresh_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'fresh_units')::integer ELSE NULL::integer END, 0),
    'stale_units', COALESCE(CASE WHEN COALESCE(v_prev_summary->>'stale_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'stale_units')::integer ELSE NULL::integer END, 0),
    'pending_units', COALESCE(v_new_pending_units, 0),
    'error_units', COALESCE(CASE WHEN COALESCE(v_prev_summary->>'error_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'error_units')::integer ELSE NULL::integer END, 0),
    'scope_hash', v_new_scope_hash,
    'result_hash', NULL::text,
    'stale_reasons', COALESCE(v_prev_summary->'stale_reasons', '[]'::jsonb),
    'diff_samples', COALESCE(v_prev_summary->'diff_samples', '[]'::jsonb),
    'last_seeded_at_utc', v_now::text,
    'last_seeded_count', COALESCE(v_seeded_count, 0),
    'last_touched_count', COALESCE(v_touched_unit_count, 0),
    'seed_has_more', COALESCE(v_has_more, false),
    'seed_next_cursor', v_next_cursor
  ));

  UPDATE public.banking_pay_operations AS operation_update
  SET progress_json = jsonb_strip_nulls(
        COALESCE(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'freshness_summary', v_new_summary,
          'freshness_status', 'PENDING',
          'freshness_total_units', COALESCE(v_new_total_units, 0),
          'freshness_pending_units', COALESCE(v_new_pending_units, 0),
          'freshness_stale_units', COALESCE(CASE WHEN COALESCE(v_prev_summary->>'stale_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'stale_units')::integer ELSE NULL::integer END, 0),
          'freshness_error_units', COALESCE(CASE WHEN COALESCE(v_prev_summary->>'error_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'error_units')::integer ELSE NULL::integer END, 0),
          'freshness_scope_hash', v_new_scope_hash,
          'freshness_result_hash', NULL::text
        )
      ),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  UPDATE public.pay_batches AS batch_update
  SET freshness_operation_id = p_operation_id,
      freshness_validation_status = 'PENDING',
      freshness_scope_hash = COALESCE(v_new_scope_hash, batch_update.freshness_scope_hash),
      freshness_result_hash = NULL::text,
      freshness_result_json = jsonb_build_object(
        'ok', true,
        'operation_id', p_operation_id::text,
        'pay_batch_id', v_pay_batch_id::text,
        'phase', 'FRESHNESS',
        'status', 'PENDING',
        'is_stale', false,
        'summary', v_new_summary
      )
  WHERE batch_update.id = v_pay_batch_id;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', v_pay_batch_id::text,
    'phase', 'FRESHNESS',
    'unit_type', 'PAY_BATCH_ITEM',
    'seeded_count', COALESCE(v_seeded_count, 0),
    'limit', v_limit,
    'has_more', COALESCE(v_has_more, false),
    'next_cursor', v_next_cursor
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_batch_validate_freshness_chunk(
  p_operation_id uuid,
  p_cursor_json jsonb DEFAULT NULL::jsonb,
  p_limit integer DEFAULT 100
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation public.banking_pay_operations%ROWTYPE;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_cursor_ordinal bigint := NULL::bigint;
  v_cursor_unit_key text := NULL::text;
  v_raw_count integer := 0;
  v_validated_count integer := 0;
  v_fresh_count integer := 0;
  v_stale_count integer := 0;
  v_error_count integer := 0;
  v_has_more boolean := false;
  v_next_cursor jsonb := NULL::jsonb;
  v_diff_samples jsonb := '[]'::jsonb;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_prev_summary jsonb := '{}'::jsonb;
  v_new_summary jsonb := '{}'::jsonb;
  v_combined_stale_reasons jsonb := '[]'::jsonb;
  v_combined_diff_samples jsonb := '[]'::jsonb;
  v_prev_total_units integer := 0;
  v_prev_seeded_units integer := 0;
  v_prev_fresh_units integer := 0;
  v_prev_stale_units integer := 0;
  v_prev_pending_units integer := 0;
  v_prev_error_units integer := 0;
  v_new_total_units integer := 0;
  v_new_seeded_units integer := 0;
  v_new_fresh_units integer := 0;
  v_new_stale_units integer := 0;
  v_new_pending_units integer := 0;
  v_new_error_units integer := 0;
  v_new_status text := 'PENDING';
  v_scope_hash text := NULL::text;
  v_prev_result_hash text := NULL::text;
  v_page_result_hash text := NULL::text;
  v_new_result_hash text := NULL::text;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_validate_freshness_chunk: p_operation_id is required';
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_batch_validate_freshness_chunk operation not found: %', p_operation_id;
  END IF;

  IF p_cursor_json IS NOT NULL AND jsonb_typeof(p_cursor_json) = 'object' THEN
    IF COALESCE(p_cursor_json->>'last_unit_ordinal', '') ~ '^[0-9]+$' THEN
      v_cursor_ordinal := (p_cursor_json->>'last_unit_ordinal')::bigint;
    END IF;
    v_cursor_unit_key := NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_unit_key', '')), '');
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_batch_freshness_validate_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_batch_freshness_validate_page ON COMMIT DROP AS
  SELECT
    scope_unit.operation_id,
    scope_unit.pay_batch_id,
    scope_unit.phase,
    scope_unit.unit_type,
    scope_unit.unit_key,
    scope_unit.unit_payload_json,
    scope_unit.unit_ordinal,
    scope_unit.status,
    row_number() OVER (ORDER BY scope_unit.unit_ordinal, scope_unit.unit_key)::integer AS page_ordinal
  FROM public.banking_pay_operation_scope_units AS scope_unit
  WHERE scope_unit.operation_id = p_operation_id
    AND scope_unit.phase = 'FRESHNESS'
    AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
    AND UPPER(BTRIM(COALESCE(scope_unit.status, ''))) IN ('PENDING', 'QUEUED', 'READY')
    AND (
      v_cursor_ordinal IS NULL
      OR scope_unit.unit_ordinal > v_cursor_ordinal
      OR (scope_unit.unit_ordinal = v_cursor_ordinal AND v_cursor_unit_key IS NOT NULL AND scope_unit.unit_key > v_cursor_unit_key)
    )
  ORDER BY scope_unit.unit_ordinal, scope_unit.unit_key
  LIMIT (v_limit + 1);

  SELECT COUNT(*)::integer
  INTO v_raw_count
  FROM pg_temp.tmp_pay_batch_freshness_validate_page AS page_row;

  v_has_more := COALESCE(v_raw_count, 0) > v_limit;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_batch_freshness_validation_result;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_batch_freshness_validation_result ON COMMIT DROP AS
  WITH page_rows AS (
    SELECT page_row.*,
           CASE
             WHEN COALESCE(page_row.unit_payload_json->>'pay_batch_item_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               THEN (page_row.unit_payload_json->>'pay_batch_item_id')::uuid
             ELSE NULL::uuid
           END AS pay_batch_item_id,
           UPPER(NULLIF(BTRIM(COALESCE(page_row.unit_payload_json#>>'{economic_key,key_type}', '')), '')) AS stored_key_type,
           NULLIF(BTRIM(COALESCE(page_row.unit_payload_json#>>'{economic_key,key_value}', '')), '') AS stored_key_value,
           CASE
             WHEN COALESCE(page_row.unit_payload_json#>>'{economic_key,timesheet_id}', page_row.unit_payload_json->>'timesheet_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               THEN COALESCE(page_row.unit_payload_json#>>'{economic_key,timesheet_id}', page_row.unit_payload_json->>'timesheet_id')::uuid
             ELSE NULL::uuid
           END AS stored_timesheet_id,
           CASE WHEN COALESCE(page_row.unit_payload_json#>>'{amounts,amount_ex_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (page_row.unit_payload_json#>>'{amounts,amount_ex_vat}')::numeric ELSE NULL::numeric END AS stored_amount_ex_vat,
           CASE WHEN COALESCE(page_row.unit_payload_json#>>'{amounts,amount_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (page_row.unit_payload_json#>>'{amounts,amount_vat}')::numeric ELSE NULL::numeric END AS stored_amount_vat,
           CASE WHEN COALESCE(page_row.unit_payload_json#>>'{amounts,amount_inc_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (page_row.unit_payload_json#>>'{amounts,amount_inc_vat}')::numeric ELSE NULL::numeric END AS stored_amount_inc_vat
    FROM pg_temp.tmp_pay_batch_freshness_validate_page AS page_row
    WHERE page_row.page_ordinal <= v_limit
  ), live_items AS (
    SELECT
      page_rows.*,
      batch_item.id AS live_pay_batch_item_id,
      batch_item.timesheet_id AS live_timesheet_id,
      batch_item.item_type AS live_item_type,
      batch_item.amount_ex_vat AS live_amount_ex_vat,
      batch_item.amount_vat AS live_amount_vat,
      batch_item.amount_inc_vat AS live_amount_inc_vat,
      COALESCE(batch_item.is_voided, false) AS live_is_voided,
      batch_item.frozen_component_key_type,
      batch_item.frozen_component_key_value,
      batch_item.frozen_component_snapshot_json,
      batch_item.frozen_source_basis_json
    FROM page_rows
    LEFT JOIN public.pay_batch_items AS batch_item
      ON batch_item.id = page_rows.pay_batch_item_id
  ), resolved AS (
    SELECT
      live_items.*,
      policy_key.timesheet_id AS resolved_timesheet_id,
      policy_key.key_type AS resolved_key_type,
      policy_key.key_value AS resolved_key_value,
      policy_key.key_resolution_source,
      policy_key.key_resolution_failure_reason
    FROM live_items
    LEFT JOIN LATERAL public._pay_policy_x_resolve_post_draft_economic_key(
      p_pay_batch_item_id => live_items.live_pay_batch_item_id,
      p_pay_batch_id => live_items.pay_batch_id,
      p_timesheet_id => live_items.live_timesheet_id,
      p_item_type => live_items.live_item_type,
      p_frozen_key_type => live_items.frozen_component_key_type,
      p_frozen_key_value => live_items.frozen_component_key_value,
      p_frozen_component_snapshot_json => COALESCE(live_items.frozen_component_snapshot_json, '{}'::jsonb),
      p_frozen_source_basis_json => COALESCE(live_items.frozen_source_basis_json, '{}'::jsonb),
      p_breakdown_meta_json => '{}'::jsonb,
      p_target_snapshot_json => NULL::jsonb
    ) AS policy_key ON true
  ), evaluated AS (
    SELECT
      resolved.*,
      (
        CASE WHEN resolved.live_pay_batch_item_id IS NULL THEN jsonb_build_array('PAY_BATCH_ITEM_MISSING') ELSE '[]'::jsonb END
        || CASE WHEN resolved.live_is_voided THEN jsonb_build_array('PAY_BATCH_ITEM_VOIDED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.resolved_key_type IS NULL OR resolved.resolved_key_value IS NULL THEN jsonb_build_array(COALESCE(resolved.key_resolution_failure_reason, 'POST_DRAFT_KEY_RESOLUTION_FAILED')) ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_key_type IS NOT NULL AND resolved.resolved_key_type IS NOT NULL AND resolved.stored_key_type IS DISTINCT FROM resolved.resolved_key_type THEN jsonb_build_array('ECONOMIC_KEY_TYPE_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_key_value IS NOT NULL AND resolved.resolved_key_value IS NOT NULL AND resolved.stored_key_value IS DISTINCT FROM resolved.resolved_key_value THEN jsonb_build_array('ECONOMIC_KEY_VALUE_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_timesheet_id IS NOT NULL AND resolved.resolved_timesheet_id IS NOT NULL AND resolved.stored_timesheet_id IS DISTINCT FROM resolved.resolved_timesheet_id THEN jsonb_build_array('ECONOMIC_TIMESHEET_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_amount_ex_vat IS NOT NULL AND resolved.live_amount_ex_vat IS NOT NULL AND ROUND(resolved.stored_amount_ex_vat, 2) IS DISTINCT FROM ROUND(resolved.live_amount_ex_vat, 2) THEN jsonb_build_array('AMOUNT_EX_VAT_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_amount_vat IS NOT NULL AND resolved.live_amount_vat IS NOT NULL AND ROUND(resolved.stored_amount_vat, 2) IS DISTINCT FROM ROUND(resolved.live_amount_vat, 2) THEN jsonb_build_array('AMOUNT_VAT_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_amount_inc_vat IS NOT NULL AND resolved.live_amount_inc_vat IS NOT NULL AND ROUND(resolved.stored_amount_inc_vat, 2) IS DISTINCT FROM ROUND(resolved.live_amount_inc_vat, 2) THEN jsonb_build_array('AMOUNT_INC_VAT_CHANGED') ELSE '[]'::jsonb END
      ) AS stale_reasons_json
    FROM resolved
  )
  SELECT
    evaluated.*,
    (jsonb_array_length(COALESCE(evaluated.stale_reasons_json, '[]'::jsonb)) > 0) AS is_stale,
    jsonb_strip_nulls(jsonb_build_object(
      'unit_key', evaluated.unit_key,
      'pay_batch_item_id', CASE WHEN evaluated.pay_batch_item_id IS NULL THEN NULL ELSE evaluated.pay_batch_item_id::text END,
      'stored_key', jsonb_strip_nulls(jsonb_build_object('timesheet_id', CASE WHEN evaluated.stored_timesheet_id IS NULL THEN NULL ELSE evaluated.stored_timesheet_id::text END, 'key_type', evaluated.stored_key_type, 'key_value', evaluated.stored_key_value)),
      'resolved_key', jsonb_strip_nulls(jsonb_build_object('timesheet_id', CASE WHEN evaluated.resolved_timesheet_id IS NULL THEN NULL ELSE evaluated.resolved_timesheet_id::text END, 'key_type', evaluated.resolved_key_type, 'key_value', evaluated.resolved_key_value)),
      'stale_reasons', evaluated.stale_reasons_json,
      'stored_amount_ex_vat', evaluated.stored_amount_ex_vat,
      'current_amount_ex_vat', evaluated.live_amount_ex_vat
    )) AS diff_json,
    md5(jsonb_strip_nulls(jsonb_build_object(
      'unit_key', evaluated.unit_key,
      'pay_batch_item_id', CASE WHEN evaluated.pay_batch_item_id IS NULL THEN NULL ELSE evaluated.pay_batch_item_id::text END,
      'resolved_key_type', evaluated.resolved_key_type,
      'resolved_key_value', evaluated.resolved_key_value,
      'resolved_timesheet_id', CASE WHEN evaluated.resolved_timesheet_id IS NULL THEN NULL ELSE evaluated.resolved_timesheet_id::text END,
      'is_stale', (jsonb_array_length(COALESCE(evaluated.stale_reasons_json, '[]'::jsonb)) > 0),
      'stale_reasons', evaluated.stale_reasons_json
    ))::text) AS proof_hash
  FROM evaluated;

  WITH updated_units AS (
    UPDATE public.banking_pay_operation_scope_units AS scope_unit
    SET status = CASE WHEN result_row.is_stale THEN 'STALE' ELSE 'FRESH' END,
        result_hash = result_row.proof_hash,
        error_json = NULL::jsonb,
        unit_payload_json = COALESCE(scope_unit.unit_payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'validation_result', jsonb_build_object(
              'validated_at_utc', v_now::text,
              'is_stale', result_row.is_stale,
              'stale_reasons', result_row.stale_reasons_json,
              'diff', CASE WHEN result_row.is_stale THEN result_row.diff_json ELSE NULL::jsonb END,
              'proof_hash', result_row.proof_hash
            )
          ),
        updated_at_utc = v_now
    FROM pg_temp.tmp_pay_batch_freshness_validation_result AS result_row
    WHERE scope_unit.operation_id = result_row.operation_id
      AND scope_unit.phase = result_row.phase
      AND scope_unit.unit_type = result_row.unit_type
      AND scope_unit.unit_key = result_row.unit_key
    RETURNING scope_unit.status
  )
  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE updated_units.status = 'FRESH')::integer,
    COUNT(*) FILTER (WHERE updated_units.status = 'STALE')::integer,
    COUNT(*) FILTER (WHERE updated_units.status = 'ERROR')::integer
  INTO v_validated_count, v_fresh_count, v_stale_count, v_error_count
  FROM updated_units;

  SELECT COALESCE(jsonb_agg(diff_source.diff_json ORDER BY diff_source.unit_ordinal, diff_source.unit_key), '[]'::jsonb)
  INTO v_diff_samples
  FROM (
    SELECT result_row.diff_json, result_row.unit_ordinal, result_row.unit_key
    FROM pg_temp.tmp_pay_batch_freshness_validation_result AS result_row
    WHERE result_row.is_stale = true
    ORDER BY result_row.unit_ordinal, result_row.unit_key
    LIMIT 25
  ) AS diff_source;

  SELECT COALESCE(jsonb_agg(DISTINCT reason_element.value ORDER BY reason_element.value), '[]'::jsonb)
  INTO v_stale_reasons
  FROM pg_temp.tmp_pay_batch_freshness_validation_result AS result_row
  CROSS JOIN LATERAL jsonb_array_elements_text(COALESCE(result_row.stale_reasons_json, '[]'::jsonb)) AS reason_element(value)
  WHERE result_row.is_stale = true;

  SELECT md5(COALESCE(string_agg(COALESCE(result_row.proof_hash, 'NO_RESULT'), '|' ORDER BY result_row.unit_ordinal, result_row.unit_key), 'EMPTY_VALIDATION_CHUNK'))
  INTO v_page_result_hash
  FROM pg_temp.tmp_pay_batch_freshness_validation_result AS result_row;

  IF v_has_more THEN
    SELECT jsonb_build_object(
      'last_unit_ordinal', page_row.unit_ordinal,
      'last_unit_key', page_row.unit_key
    )
    INTO v_next_cursor
    FROM pg_temp.tmp_pay_batch_freshness_validate_page AS page_row
    WHERE page_row.page_ordinal = v_limit;
  ELSE
    v_next_cursor := NULL::jsonb;
  END IF;

  v_prev_summary := CASE
    WHEN jsonb_typeof(COALESCE(v_operation.progress_json, '{}'::jsonb)->'freshness_summary') = 'object'
      THEN COALESCE(v_operation.progress_json->'freshness_summary', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_prev_total_units := COALESCE(
    CASE WHEN COALESCE(v_prev_summary->>'total_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'total_units')::integer ELSE NULL::integer END,
    CASE WHEN COALESCE(v_operation.progress_json->>'freshness_total_units', '') ~ '^[0-9]+$' THEN (v_operation.progress_json->>'freshness_total_units')::integer ELSE NULL::integer END,
    0
  );
  v_prev_seeded_units := COALESCE(
    CASE WHEN COALESCE(v_prev_summary->>'seeded_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'seeded_units')::integer ELSE NULL::integer END,
    v_prev_total_units,
    0
  );
  v_prev_fresh_units := COALESCE(CASE WHEN COALESCE(v_prev_summary->>'fresh_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'fresh_units')::integer ELSE NULL::integer END, 0);
  v_prev_stale_units := COALESCE(CASE WHEN COALESCE(v_prev_summary->>'stale_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'stale_units')::integer ELSE NULL::integer END, 0);
  v_prev_pending_units := COALESCE(
    CASE WHEN COALESCE(v_prev_summary->>'pending_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'pending_units')::integer ELSE NULL::integer END,
    CASE WHEN COALESCE(v_operation.progress_json->>'freshness_pending_units', '') ~ '^[0-9]+$' THEN (v_operation.progress_json->>'freshness_pending_units')::integer ELSE NULL::integer END,
    0
  );
  v_prev_error_units := COALESCE(CASE WHEN COALESCE(v_prev_summary->>'error_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'error_units')::integer ELSE NULL::integer END, 0);
  v_scope_hash := COALESCE(
    NULLIF(BTRIM(COALESCE(v_prev_summary->>'scope_hash', '')), ''),
    NULLIF(BTRIM(COALESCE(v_operation.progress_json->>'freshness_scope_hash', '')), '')
  );
  v_prev_result_hash := COALESCE(
    NULLIF(BTRIM(COALESCE(v_prev_summary->>'result_hash', '')), ''),
    NULLIF(BTRIM(COALESCE(v_operation.progress_json->>'freshness_result_hash', '')), '')
  );

  v_new_fresh_units := COALESCE(v_prev_fresh_units, 0) + COALESCE(v_fresh_count, 0);
  v_new_stale_units := COALESCE(v_prev_stale_units, 0) + COALESCE(v_stale_count, 0);
  v_new_error_units := COALESCE(v_prev_error_units, 0) + COALESCE(v_error_count, 0);
  v_new_pending_units := GREATEST(COALESCE(v_prev_pending_units, 0) - COALESCE(v_validated_count, 0), 0);
  v_new_seeded_units := GREATEST(COALESCE(v_prev_seeded_units, 0), COALESCE(v_prev_total_units, 0), v_new_fresh_units + v_new_stale_units + v_new_error_units + v_new_pending_units);
  v_new_total_units := GREATEST(COALESCE(v_prev_total_units, 0), v_new_seeded_units);

  v_new_status := CASE
    WHEN COALESCE(v_new_pending_units, 0) > 0 OR COALESCE(v_has_more, false) THEN 'PENDING'
    WHEN COALESCE(v_new_error_units, 0) > 0 THEN 'ERROR'
    WHEN COALESCE(v_new_stale_units, 0) > 0 THEN 'STALE'
    ELSE 'PASSED'
  END;

  v_new_result_hash := CASE
    WHEN v_prev_result_hash IS NULL THEN COALESCE(v_page_result_hash, 'EMPTY_RESULT')
    ELSE md5(v_prev_result_hash || '|chunk|' || COALESCE(v_page_result_hash, 'EMPTY_VALIDATION_CHUNK'))
  END;

  SELECT COALESCE(jsonb_agg(DISTINCT reason_union.reason_text ORDER BY reason_union.reason_text), '[]'::jsonb)
  INTO v_combined_stale_reasons
  FROM (
    SELECT previous_reason.value AS reason_text
    FROM jsonb_array_elements_text(
      CASE WHEN jsonb_typeof(v_prev_summary->'stale_reasons') = 'array' THEN COALESCE(v_prev_summary->'stale_reasons', '[]'::jsonb) ELSE '[]'::jsonb END
    ) AS previous_reason(value)
    UNION ALL
    SELECT current_reason.value AS reason_text
    FROM jsonb_array_elements_text(COALESCE(v_stale_reasons, '[]'::jsonb)) AS current_reason(value)
  ) AS reason_union
  WHERE NULLIF(BTRIM(COALESCE(reason_union.reason_text, '')), '') IS NOT NULL;

  SELECT COALESCE(jsonb_agg(capped_diff.diff_json ORDER BY capped_diff.sample_rank), '[]'::jsonb)
  INTO v_combined_diff_samples
  FROM (
    SELECT diff_union.diff_json, diff_union.sample_rank
    FROM (
      SELECT previous_diff.value AS diff_json, previous_diff.ordinality::integer AS sample_rank
      FROM jsonb_array_elements(
        CASE WHEN jsonb_typeof(v_prev_summary->'diff_samples') = 'array' THEN COALESCE(v_prev_summary->'diff_samples', '[]'::jsonb) ELSE '[]'::jsonb END
      ) WITH ORDINALITY AS previous_diff(value, ordinality)
      UNION ALL
      SELECT current_diff.value AS diff_json, (1000 + current_diff.ordinality)::integer AS sample_rank
      FROM jsonb_array_elements(COALESCE(v_diff_samples, '[]'::jsonb)) WITH ORDINALITY AS current_diff(value, ordinality)
    ) AS diff_union
    WHERE jsonb_typeof(diff_union.diff_json) = 'object'
    ORDER BY diff_union.sample_rank
    LIMIT 25
  ) AS capped_diff;

  v_new_summary := jsonb_strip_nulls(jsonb_build_object(
    'status', v_new_status,
    'operation_id', p_operation_id::text,
    'pay_batch_id', CASE WHEN v_operation.pay_batch_id IS NULL THEN NULL ELSE v_operation.pay_batch_id::text END,
    'phase', 'FRESHNESS',
    'unit_type', 'PAY_BATCH_ITEM',
    'seeded_units', COALESCE(v_new_seeded_units, 0),
    'total_units', COALESCE(v_new_total_units, 0),
    'fresh_units', COALESCE(v_new_fresh_units, 0),
    'stale_units', COALESCE(v_new_stale_units, 0),
    'pending_units', COALESCE(v_new_pending_units, 0),
    'error_units', COALESCE(v_new_error_units, 0),
    'scope_hash', v_scope_hash,
    'result_hash', v_new_result_hash,
    'stale_reasons', COALESCE(v_combined_stale_reasons, '[]'::jsonb),
    'diff_samples', COALESCE(v_combined_diff_samples, '[]'::jsonb),
    'last_validated_at_utc', v_now::text,
    'last_validated_count', COALESCE(v_validated_count, 0),
    'last_fresh_count', COALESCE(v_fresh_count, 0),
    'last_stale_count', COALESCE(v_stale_count, 0),
    'last_error_count', COALESCE(v_error_count, 0),
    'has_more', COALESCE(v_has_more, false),
    'next_cursor', v_next_cursor
  ));

  UPDATE public.banking_pay_operations AS operation_update
  SET progress_json = jsonb_strip_nulls(
        COALESCE(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'freshness_summary', v_new_summary,
          'freshness_status', v_new_status,
          'freshness_total_units', COALESCE(v_new_total_units, 0),
          'freshness_stale_units', COALESCE(v_new_stale_units, 0),
          'freshness_pending_units', COALESCE(v_new_pending_units, 0),
          'freshness_error_units', COALESCE(v_new_error_units, 0),
          'freshness_scope_hash', v_scope_hash,
          'freshness_result_hash', v_new_result_hash
        )
      ),
      result_json = CASE
        WHEN v_new_status <> 'PENDING' THEN jsonb_set(
          COALESCE(operation_update.result_json, '{}'::jsonb),
          '{freshness}',
          v_new_summary,
          true
        )
        ELSE operation_update.result_json
      END,
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  IF v_operation.pay_batch_id IS NOT NULL THEN
    UPDATE public.pay_batches AS batch_update
    SET freshness_operation_id = p_operation_id,
        freshness_validation_status = v_new_status,
        freshness_checked_at_utc = CASE WHEN v_new_status <> 'PENDING' THEN v_now ELSE batch_update.freshness_checked_at_utc END,
        freshness_scope_hash = COALESCE(v_scope_hash, batch_update.freshness_scope_hash),
        freshness_result_hash = CASE WHEN v_new_status <> 'PENDING' THEN v_new_result_hash ELSE batch_update.freshness_result_hash END,
        freshness_result_json = jsonb_build_object(
          'ok', true,
          'operation_id', p_operation_id::text,
          'pay_batch_id', v_operation.pay_batch_id::text,
          'phase', 'FRESHNESS',
          'status', v_new_status,
          'is_stale', v_new_status IN ('STALE', 'ERROR'),
          'stale_reasons', COALESCE(v_combined_stale_reasons, '[]'::jsonb),
          'diff', COALESCE(v_combined_diff_samples, '[]'::jsonb),
          'diff_samples', COALESCE(v_combined_diff_samples, '[]'::jsonb),
          'scope_hash', v_scope_hash,
          'result_hash', v_new_result_hash,
          'summary', v_new_summary,
          'checked_at_utc', CASE WHEN v_new_status <> 'PENDING' THEN v_now::text ELSE NULL END
        )
    WHERE batch_update.id = v_operation.pay_batch_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', CASE WHEN v_operation.pay_batch_id IS NULL THEN NULL ELSE v_operation.pay_batch_id::text END,
    'phase', 'FRESHNESS',
    'validated_count', COALESCE(v_validated_count, 0),
    'fresh_count', COALESCE(v_fresh_count, 0),
    'stale_count', COALESCE(v_stale_count, 0),
    'error_count', COALESCE(v_error_count, 0),
    'stale_reasons', COALESCE(v_stale_reasons, '[]'::jsonb),
    'diff_samples', COALESCE(v_diff_samples, '[]'::jsonb),
    'limit', v_limit,
    'has_more', COALESCE(v_has_more, false),
    'next_cursor', v_next_cursor
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_batch_freshness_result_get(
  p_operation_id uuid,
  p_pay_batch_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation public.banking_pay_operations%ROWTYPE;
  v_pay_batch_id uuid := p_pay_batch_id;
  v_summary jsonb := '{}'::jsonb;
  v_status text := 'PENDING';
  v_total_units integer := 0;
  v_fresh_units integer := 0;
  v_stale_units integer := 0;
  v_pending_units integer := 0;
  v_error_units integer := 0;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_diff_samples jsonb := '[]'::jsonb;
  v_result_hash text := NULL::text;
  v_scope_hash text := NULL::text;
  v_is_stale boolean := false;
  v_result_json jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('PROGRESS');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_freshness_result_get: p_operation_id is required';
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_batch_freshness_result_get operation not found: %', p_operation_id;
  END IF;

  v_pay_batch_id := COALESCE(v_pay_batch_id, v_operation.pay_batch_id);

  v_summary := CASE
    WHEN jsonb_typeof(COALESCE(v_operation.progress_json, '{}'::jsonb)->'freshness_summary') = 'object'
      THEN COALESCE(v_operation.progress_json->'freshness_summary', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_total_units := COALESCE(
    CASE WHEN COALESCE(v_summary->>'total_units', '') ~ '^[0-9]+$' THEN (v_summary->>'total_units')::integer ELSE NULL::integer END,
    CASE WHEN COALESCE(v_operation.progress_json->>'freshness_total_units', '') ~ '^[0-9]+$' THEN (v_operation.progress_json->>'freshness_total_units')::integer ELSE NULL::integer END,
    0
  );
  v_fresh_units := COALESCE(CASE WHEN COALESCE(v_summary->>'fresh_units', '') ~ '^[0-9]+$' THEN (v_summary->>'fresh_units')::integer ELSE NULL::integer END, 0);
  v_stale_units := COALESCE(
    CASE WHEN COALESCE(v_summary->>'stale_units', '') ~ '^[0-9]+$' THEN (v_summary->>'stale_units')::integer ELSE NULL::integer END,
    CASE WHEN COALESCE(v_operation.progress_json->>'freshness_stale_units', '') ~ '^[0-9]+$' THEN (v_operation.progress_json->>'freshness_stale_units')::integer ELSE NULL::integer END,
    0
  );
  v_pending_units := COALESCE(
    CASE WHEN COALESCE(v_summary->>'pending_units', '') ~ '^[0-9]+$' THEN (v_summary->>'pending_units')::integer ELSE NULL::integer END,
    CASE WHEN COALESCE(v_operation.progress_json->>'freshness_pending_units', '') ~ '^[0-9]+$' THEN (v_operation.progress_json->>'freshness_pending_units')::integer ELSE NULL::integer END,
    0
  );
  v_error_units := COALESCE(
    CASE WHEN COALESCE(v_summary->>'error_units', '') ~ '^[0-9]+$' THEN (v_summary->>'error_units')::integer ELSE NULL::integer END,
    CASE WHEN COALESCE(v_operation.progress_json->>'freshness_error_units', '') ~ '^[0-9]+$' THEN (v_operation.progress_json->>'freshness_error_units')::integer ELSE NULL::integer END,
    0
  );

  v_scope_hash := COALESCE(
    NULLIF(BTRIM(COALESCE(v_summary->>'scope_hash', '')), ''),
    NULLIF(BTRIM(COALESCE(v_operation.progress_json->>'freshness_scope_hash', '')), '')
  );
  v_result_hash := COALESCE(
    NULLIF(BTRIM(COALESCE(v_summary->>'result_hash', '')), ''),
    NULLIF(BTRIM(COALESCE(v_operation.progress_json->>'freshness_result_hash', '')), '')
  );
  v_status := UPPER(BTRIM(COALESCE(
    NULLIF(BTRIM(COALESCE(v_summary->>'status', '')), ''),
    NULLIF(BTRIM(COALESCE(v_operation.progress_json->>'freshness_status', '')), ''),
    CASE
      WHEN COALESCE(v_pending_units, 0) > 0 THEN 'PENDING'
      WHEN COALESCE(v_error_units, 0) > 0 THEN 'ERROR'
      WHEN COALESCE(v_stale_units, 0) > 0 THEN 'STALE'
      WHEN COALESCE(v_total_units, 0) > 0 THEN 'PASSED'
      ELSE 'PENDING'
    END
  )));

  IF v_status NOT IN ('PENDING', 'ERROR', 'STALE', 'PASSED') THEN
    v_status := 'PENDING';
  END IF;

  v_stale_reasons := CASE
    WHEN jsonb_typeof(v_summary->'stale_reasons') = 'array' THEN COALESCE(v_summary->'stale_reasons', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;
  v_diff_samples := CASE
    WHEN jsonb_typeof(v_summary->'diff_samples') = 'array' THEN COALESCE(v_summary->'diff_samples', '[]'::jsonb)
    WHEN jsonb_typeof(v_summary->'diff') = 'array' THEN COALESCE(v_summary->'diff', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_is_stale := v_status IN ('STALE', 'ERROR') OR COALESCE(v_stale_units, 0) > 0 OR COALESCE(v_error_units, 0) > 0;

  v_result_json := jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', CASE WHEN v_pay_batch_id IS NULL THEN NULL ELSE v_pay_batch_id::text END,
    'phase', 'FRESHNESS',
    'status', v_status,
    'is_stale', v_is_stale,
    'total_units', COALESCE(v_total_units, 0),
    'fresh_units', COALESCE(v_fresh_units, 0),
    'stale_units', COALESCE(v_stale_units, 0),
    'pending_units', COALESCE(v_pending_units, 0),
    'error_units', COALESCE(v_error_units, 0),
    'stale_reasons', COALESCE(v_stale_reasons, '[]'::jsonb),
    'diff', COALESCE(v_diff_samples, '[]'::jsonb),
    'diff_samples', COALESCE(v_diff_samples, '[]'::jsonb),
    'scope_hash', v_scope_hash,
    'result_hash', v_result_hash,
    'checked_at_utc', CASE WHEN v_status <> 'PENDING' THEN v_now::text ELSE NULL END,
    'progress_source', 'banking_pay_operations.progress_json.freshness_summary'
  );

  UPDATE public.banking_pay_operations AS operation_row
  SET progress_json = jsonb_strip_nulls(
        COALESCE(operation_row.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'freshness_summary', COALESCE(v_summary, '{}'::jsonb) || jsonb_build_object(
            'status', v_status,
            'total_units', COALESCE(v_total_units, 0),
            'fresh_units', COALESCE(v_fresh_units, 0),
            'stale_units', COALESCE(v_stale_units, 0),
            'pending_units', COALESCE(v_pending_units, 0),
            'error_units', COALESCE(v_error_units, 0),
            'scope_hash', v_scope_hash,
            'result_hash', v_result_hash,
            'stale_reasons', COALESCE(v_stale_reasons, '[]'::jsonb),
            'diff_samples', COALESCE(v_diff_samples, '[]'::jsonb)
          ),
          'freshness_status', v_status,
          'freshness_total_units', COALESCE(v_total_units, 0),
          'freshness_stale_units', COALESCE(v_stale_units, 0),
          'freshness_pending_units', COALESCE(v_pending_units, 0),
          'freshness_result_hash', v_result_hash,
          'freshness_scope_hash', v_scope_hash
        )
      ),
      result_json = CASE WHEN v_status <> 'PENDING' THEN jsonb_set(COALESCE(operation_row.result_json, '{}'::jsonb), '{freshness}', v_result_json, true) ELSE operation_row.result_json END,
      updated_at_utc = v_now
  WHERE operation_row.id = p_operation_id;

  IF v_pay_batch_id IS NOT NULL THEN
    UPDATE public.pay_batches AS batch_row
    SET freshness_operation_id = p_operation_id,
        freshness_validation_status = v_status,
        freshness_checked_at_utc = CASE WHEN v_status <> 'PENDING' THEN v_now ELSE batch_row.freshness_checked_at_utc END,
        freshness_result_hash = CASE WHEN v_status <> 'PENDING' THEN v_result_hash ELSE batch_row.freshness_result_hash END,
        freshness_scope_hash = COALESCE(v_scope_hash, batch_row.freshness_scope_hash),
        freshness_result_json = v_result_json
    WHERE batch_row.id = v_pay_batch_id;
  END IF;

  RETURN v_result_json;
END;
$function$;



CREATE OR REPLACE FUNCTION public.banking_pay_operation_release_lease(
  p_operation_id uuid,
  p_lease_owner text,
  p_release_state text DEFAULT 'MORE_WORK'::text,
  p_run_after_delay_seconds integer DEFAULT 0,
  p_progress_patch_json jsonb DEFAULT '{}'::jsonb,
  p_result_patch_json jsonb DEFAULT NULL::jsonb,
  p_error_json jsonb DEFAULT NULL::jsonb,
  p_resume_reason text DEFAULT NULL::text,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_release_state text := upper(BTRIM(COALESCE(p_release_state, 'MORE_WORK')));
  v_delay_seconds integer := LEAST(GREATEST(COALESCE(p_run_after_delay_seconds, 0), 0), 3600);
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_operation_type text := NULL::text;
  v_next_status text := 'RUNNING';
  v_next_runner_state text := 'RUNNABLE';
  v_next_run_after_utc timestamptz := now();
  v_next_requires_user_action boolean := false;
  v_next_resume_reason text := NULL::text;
  v_completed_at_utc timestamptz := NULL::timestamptz;
  v_failed_at_utc timestamptz := NULL::timestamptz;
  v_retry_failure boolean := false;
  v_next_attempt_count integer := NULL::integer;
  v_attempt_limit_reached boolean := false;
BEGIN
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_PAY_OPERATION_RELEASE_OPERATION_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_RELEASE_OPERATION_ID_REQUIRED')::text;
  END IF;

  IF NULLIF(BTRIM(COALESCE(p_lease_owner, '')), '') IS NULL THEN
    RAISE EXCEPTION 'BANKING_PAY_OPERATION_RELEASE_LEASE_OWNER_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_RELEASE_LEASE_OWNER_REQUIRED', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF p_progress_patch_json IS NOT NULL AND jsonb_typeof(p_progress_patch_json) <> 'object' THEN
    RAISE EXCEPTION 'BANKING_PAY_OPERATION_RELEASE_PROGRESS_PATCH_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_RELEASE_PROGRESS_PATCH_MUST_BE_OBJECT', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF p_result_patch_json IS NOT NULL AND jsonb_typeof(p_result_patch_json) <> 'object' THEN
    RAISE EXCEPTION 'BANKING_PAY_OPERATION_RELEASE_RESULT_PATCH_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_RELEASE_RESULT_PATCH_MUST_BE_OBJECT', 'operation_id', p_operation_id::text)::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BANKING_PAY_OPERATION_RELEASE_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_RELEASE_OPERATION_NOT_FOUND', 'operation_id', p_operation_id::text)::text;
  END IF;

  v_operation_type := upper(BTRIM(COALESCE(v_operation_row.operation_type, '')));

  IF NULLIF(BTRIM(COALESCE(v_operation_row.lease_owner, '')), '') IS NULL
     OR v_operation_row.lease_owner <> p_lease_owner THEN
    RAISE EXCEPTION 'BANKING_PAY_OPERATION_RELEASE_LEASE_OWNER_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_RELEASE_LEASE_OWNER_MISMATCH', 'operation_id', p_operation_id::text, 'expected_lease_owner', v_operation_row.lease_owner, 'actual_lease_owner', p_lease_owner)::text;
  END IF;

  IF v_operation_row.lease_expires_at_utc IS NULL OR v_operation_row.lease_expires_at_utc <= v_now THEN
    RAISE EXCEPTION 'BANKING_PAY_OPERATION_RELEASE_LEASE_EXPIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_RELEASE_LEASE_EXPIRED', 'operation_id', p_operation_id::text, 'lease_expires_at_utc', CASE WHEN v_operation_row.lease_expires_at_utc IS NULL THEN NULL ELSE v_operation_row.lease_expires_at_utc::text END)::text;
  END IF;

  IF v_release_state IN ('MORE_WORK', 'RUNNABLE', 'RUNNING', 'CONTINUE', 'CONTINUING') THEN
    v_next_status := 'RUNNING';
    v_next_runner_state := 'RUNNABLE';
    v_next_run_after_utc := v_now + make_interval(secs => v_delay_seconds);
    v_next_requires_user_action := false;
    v_next_resume_reason := COALESCE(NULLIF(BTRIM(COALESCE(p_resume_reason, '')), ''), 'MORE_WORK_REMAINS');
  ELSIF v_release_state IN ('WAITING_RETRY', 'RETRYABLE_ERROR', 'RETRYABLE_FAILURE', 'RETRY', 'TRANSIENT_ERROR') THEN
    v_retry_failure := true;
    v_next_attempt_count := COALESCE(v_operation_row.attempt_count, 0) + 1;
    v_attempt_limit_reached := v_next_attempt_count >= COALESCE(v_operation_row.max_attempts, 10);

    IF v_attempt_limit_reached IS TRUE THEN
      v_next_status := 'FAILED';
      v_next_runner_state := 'FAILED';
      v_next_run_after_utc := NULL::timestamptz;
      v_next_requires_user_action := false;
      v_next_resume_reason := COALESCE(NULLIF(BTRIM(COALESCE(p_resume_reason, '')), ''), CASE WHEN v_operation_type = 'DRAFT_CREATE' THEN 'DRAFT_CREATE_ATTEMPT_LIMIT_EXHAUSTED' ELSE 'OPERATION_ATTEMPT_LIMIT_EXHAUSTED' END);
      v_failed_at_utc := v_now;
    ELSE
      v_next_status := 'WAITING_RETRY';
      v_next_runner_state := 'RUNNABLE';
      v_next_run_after_utc := v_now + make_interval(secs => GREATEST(v_delay_seconds, 1));
      v_next_requires_user_action := false;
      v_next_resume_reason := COALESCE(NULLIF(BTRIM(COALESCE(p_resume_reason, '')), ''), 'WAITING_RETRY');
    END IF;
  ELSIF v_release_state IN ('WAITING_AUTHORISATION', 'WAITING_AUTHORIZATION', 'WAIT_AUTHORISATION', 'WAIT_AUTHORIZATION') THEN
    v_next_status := 'WAITING_AUTHORISATION';
    v_next_runner_state := 'WAITING_USER';
    v_next_run_after_utc := NULL::timestamptz;
    v_next_requires_user_action := true;
    v_next_resume_reason := COALESCE(NULLIF(BTRIM(COALESCE(p_resume_reason, '')), ''), 'AWAITING_PAYMENT_AUTHORISATION');
  ELSIF v_release_state IN ('WAITING_PROVIDER', 'WAIT_PROVIDER') THEN
    v_next_status := 'WAITING_PROVIDER';
    v_next_runner_state := 'WAITING_PROVIDER';
    v_next_run_after_utc := v_now + make_interval(secs => GREATEST(v_delay_seconds, 60));
    v_next_requires_user_action := false;
    v_next_resume_reason := COALESCE(NULLIF(BTRIM(COALESCE(p_resume_reason, '')), ''), 'AWAITING_PROVIDER_OUTCOME');
  ELSIF v_release_state IN ('REVIEW_REQUIRED', 'UNSAFE', 'AMBIGUOUS') THEN
    v_next_status := 'REVIEW_REQUIRED';
    v_next_runner_state := 'WAITING_USER_REVIEW';
    v_next_run_after_utc := NULL::timestamptz;
    v_next_requires_user_action := true;
    v_next_resume_reason := COALESCE(NULLIF(BTRIM(COALESCE(p_resume_reason, '')), ''), 'REVIEW_REQUIRED');
  ELSIF v_release_state IN ('COMPLETE', 'COMPLETED', 'DONE') THEN
    v_next_status := 'COMPLETE';
    v_next_runner_state := 'COMPLETE';
    v_next_run_after_utc := NULL::timestamptz;
    v_next_requires_user_action := false;
    v_next_resume_reason := COALESCE(NULLIF(BTRIM(COALESCE(p_resume_reason, '')), ''), 'OPERATION_COMPLETE');
    v_completed_at_utc := v_now;
  ELSIF v_release_state IN ('FAILED', 'ERROR') THEN
    v_next_status := 'FAILED';
    v_next_runner_state := 'FAILED';
    v_next_run_after_utc := NULL::timestamptz;
    v_next_requires_user_action := CASE WHEN v_operation_type = 'DRAFT_CREATE' THEN false ELSE true END;
    v_next_resume_reason := COALESCE(NULLIF(BTRIM(COALESCE(p_resume_reason, '')), ''), CASE WHEN v_operation_type = 'DRAFT_CREATE' THEN 'DRAFT_CREATE_OPERATION_FAILED' ELSE 'OPERATION_FAILED' END);
    v_failed_at_utc := v_now;
  ELSE
    RAISE EXCEPTION 'BANKING_PAY_OPERATION_RELEASE_STATE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_RELEASE_STATE_INVALID', 'operation_id', p_operation_id::text, 'release_state', p_release_state)::text;
  END IF;

  UPDATE public.banking_pay_operations AS operation_update
  SET status = v_next_status,
      runner_state = v_next_runner_state,
      run_after_utc = v_next_run_after_utc,
      requires_user_action = v_next_requires_user_action,
      resume_reason = v_next_resume_reason,
      attempt_count = CASE WHEN v_retry_failure IS TRUE THEN COALESCE(v_next_attempt_count, operation_update.attempt_count) ELSE operation_update.attempt_count END,
      lease_owner = NULL::text,
      lease_expires_at_utc = NULL::timestamptz,
      locked_by = NULL::text,
      lock_expires_at_utc = NULL::timestamptz,
      heartbeat_at_utc = v_now,
      last_advanced_at_utc = v_now,
      progress_json = jsonb_strip_nulls(
        COALESCE(operation_update.progress_json, '{}'::jsonb)
        || COALESCE(p_progress_patch_json, '{}'::jsonb)
        || jsonb_build_object(
          'last_release', jsonb_build_object(
            'released_at_utc', v_now::text,
            'release_state', v_release_state,
            'next_status', v_next_status,
            'runner_state', v_next_runner_state,
            'run_after_utc', CASE WHEN v_next_run_after_utc IS NULL THEN NULL ELSE v_next_run_after_utc::text END,
            'requires_user_action', v_next_requires_user_action,
            'resume_reason', v_next_resume_reason,
            'retry_failure', v_retry_failure,
            'attempt_count', CASE WHEN v_retry_failure IS TRUE THEN v_next_attempt_count ELSE operation_update.attempt_count END,
            'max_attempts', operation_update.max_attempts,
            'attempt_limit_reached', v_attempt_limit_reached,
            'actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END
          )
        )
      ),
      result_json = CASE
        WHEN p_result_patch_json IS NULL THEN operation_update.result_json
        ELSE jsonb_strip_nulls(COALESCE(operation_update.result_json, '{}'::jsonb) || p_result_patch_json)
      END,
      error_json = CASE
        WHEN p_error_json IS NULL AND v_attempt_limit_reached IS NOT TRUE THEN operation_update.error_json
        ELSE jsonb_strip_nulls(
          COALESCE(p_error_json, '{}'::jsonb)
          || CASE
            WHEN v_attempt_limit_reached IS TRUE THEN jsonb_build_object(
              'code', v_next_resume_reason,
              'message', 'Operation retry attempt limit was exhausted.',
              'operation_id', p_operation_id::text,
              'attempt_count', v_next_attempt_count,
              'max_attempts', operation_update.max_attempts
            )
            ELSE '{}'::jsonb
          END
        )
      END,
      completed_at_utc = CASE WHEN v_completed_at_utc IS NULL THEN operation_update.completed_at_utc ELSE COALESCE(operation_update.completed_at_utc, v_completed_at_utc) END,
      failed_at_utc = CASE WHEN v_failed_at_utc IS NULL THEN operation_update.failed_at_utc ELSE COALESCE(operation_update.failed_at_utc, v_failed_at_utc) END,
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'released_lease_owner', p_lease_owner,
    'status', v_next_status,
    'runner_state', v_next_runner_state,
    'run_after_utc', CASE WHEN v_next_run_after_utc IS NULL THEN NULL ELSE v_next_run_after_utc::text END,
    'requires_user_action', v_next_requires_user_action,
    'resume_reason', v_next_resume_reason,
    'released_at_utc', v_now::text,
    'retry_failure', v_retry_failure,
    'attempt_count', CASE WHEN v_retry_failure IS TRUE THEN v_next_attempt_count ELSE v_operation_row.attempt_count END,
    'max_attempts', v_operation_row.max_attempts,
    'attempt_limit_reached', v_attempt_limit_reached
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.banking_pay_operation_provider_attempt_record(
  p_operation_id uuid,
  p_pay_batch_id uuid DEFAULT NULL::uuid,
  p_transfer_scope_id uuid DEFAULT NULL::uuid,
  p_provider_chunk_id uuid DEFAULT NULL::uuid,
  p_idempotency_key text DEFAULT NULL::text,
  p_request_id text DEFAULT NULL::text,
  p_provider_transaction_id text DEFAULT NULL::text,
  p_previous_state text DEFAULT NULL::text,
  p_new_state text DEFAULT NULL::text,
  p_lease_owner text DEFAULT NULL::text,
  p_request_json jsonb DEFAULT NULL::jsonb,
  p_response_json jsonb DEFAULT NULL::jsonb,
  p_error_json jsonb DEFAULT NULL::jsonb,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_effective_pay_batch_id uuid := p_pay_batch_id;
  v_request_hash text := NULL::text;
  v_response_hash text := NULL::text;
  v_error_summary jsonb := NULL::jsonb;
  v_attempt_id uuid := NULL::uuid;
BEGIN
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_PAY_PROVIDER_ATTEMPT_OPERATION_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_PROVIDER_ATTEMPT_OPERATION_ID_REQUIRED')::text;
  END IF;

  IF NULLIF(BTRIM(COALESCE(p_new_state, '')), '') IS NULL THEN
    RAISE EXCEPTION 'BANKING_PAY_PROVIDER_ATTEMPT_NEW_STATE_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_PROVIDER_ATTEMPT_NEW_STATE_REQUIRED', 'operation_id', p_operation_id::text)::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BANKING_PAY_PROVIDER_ATTEMPT_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_PROVIDER_ATTEMPT_OPERATION_NOT_FOUND', 'operation_id', p_operation_id::text)::text;
  END IF;

  v_effective_pay_batch_id := COALESCE(v_effective_pay_batch_id, v_operation_row.pay_batch_id);

  IF p_transfer_scope_id IS NOT NULL THEN
    PERFORM 1
    FROM public.banking_pay_operation_transfer_scope AS transfer_scope_check
    WHERE transfer_scope_check.id = p_transfer_scope_id
      AND transfer_scope_check.operation_id = p_operation_id
      AND (v_effective_pay_batch_id IS NULL OR transfer_scope_check.pay_batch_id = v_effective_pay_batch_id);

    IF NOT FOUND THEN
      RAISE EXCEPTION 'BANKING_PAY_PROVIDER_ATTEMPT_TRANSFER_SCOPE_NOT_FOUND'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_PROVIDER_ATTEMPT_TRANSFER_SCOPE_NOT_FOUND', 'operation_id', p_operation_id::text, 'transfer_scope_id', p_transfer_scope_id::text)::text;
    END IF;
  END IF;

  IF p_provider_chunk_id IS NOT NULL THEN
    PERFORM 1
    FROM public.banking_pay_operation_chunks AS provider_chunk_check
    WHERE provider_chunk_check.id = p_provider_chunk_id
      AND provider_chunk_check.operation_id = p_operation_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'BANKING_PAY_PROVIDER_ATTEMPT_CHUNK_NOT_FOUND'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_PROVIDER_ATTEMPT_CHUNK_NOT_FOUND', 'operation_id', p_operation_id::text, 'provider_chunk_id', p_provider_chunk_id::text)::text;
    END IF;
  END IF;

  IF p_request_json IS NOT NULL AND jsonb_typeof(p_request_json) <> 'object' THEN
    RAISE EXCEPTION 'BANKING_PAY_PROVIDER_ATTEMPT_REQUEST_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_PROVIDER_ATTEMPT_REQUEST_JSON_MUST_BE_OBJECT', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF p_response_json IS NOT NULL AND jsonb_typeof(p_response_json) <> 'object' THEN
    RAISE EXCEPTION 'BANKING_PAY_PROVIDER_ATTEMPT_RESPONSE_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_PROVIDER_ATTEMPT_RESPONSE_JSON_MUST_BE_OBJECT', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF p_error_json IS NOT NULL AND jsonb_typeof(p_error_json) <> 'object' THEN
    RAISE EXCEPTION 'BANKING_PAY_PROVIDER_ATTEMPT_ERROR_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_PROVIDER_ATTEMPT_ERROR_JSON_MUST_BE_OBJECT', 'operation_id', p_operation_id::text)::text;
  END IF;

  v_request_hash := CASE WHEN p_request_json IS NULL THEN NULL ELSE md5(p_request_json::text) END;
  v_response_hash := CASE WHEN p_response_json IS NULL THEN NULL ELSE md5(p_response_json::text) END;
  v_error_summary := CASE
    WHEN p_error_json IS NULL THEN NULL::jsonb
    ELSE jsonb_strip_nulls(jsonb_build_object(
      'code', COALESCE(NULLIF(BTRIM(p_error_json->>'code'), ''), NULLIF(BTRIM(p_error_json->>'error_code'), '')),
      'message', LEFT(COALESCE(NULLIF(BTRIM(p_error_json->>'message'), ''), NULLIF(BTRIM(p_error_json->>'error'), ''), p_error_json::text), 1000),
      'sqlstate', NULLIF(BTRIM(p_error_json->>'sqlstate'), ''),
      'provider_status', NULLIF(BTRIM(p_error_json->>'provider_status'), '')
    ))
  END;

  INSERT INTO public.banking_pay_operation_provider_attempts (
    operation_id,
    pay_batch_id,
    transfer_scope_id,
    provider_chunk_id,
    provider_idempotency_key,
    provider_request_id,
    provider_transaction_id,
    previous_state,
    new_state,
    lease_owner,
    compact_request_hash,
    compact_response_hash,
    compact_error_summary_json,
    created_at_utc
  )
  VALUES (
    p_operation_id,
    v_effective_pay_batch_id,
    p_transfer_scope_id,
    p_provider_chunk_id,
    NULLIF(BTRIM(COALESCE(p_idempotency_key, '')), ''),
    NULLIF(BTRIM(COALESCE(p_request_id, '')), ''),
    NULLIF(BTRIM(COALESCE(p_provider_transaction_id, '')), ''),
    NULLIF(BTRIM(COALESCE(p_previous_state, '')), ''),
    UPPER(BTRIM(COALESCE(p_new_state, ''))),
    NULLIF(BTRIM(COALESCE(p_lease_owner, '')), ''),
    v_request_hash,
    v_response_hash,
    v_error_summary,
    v_now
  )
  RETURNING id INTO v_attempt_id;

  UPDATE public.banking_pay_operations AS operation_update
  SET progress_json = jsonb_strip_nulls(
        COALESCE(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'last_provider_attempt', jsonb_strip_nulls(jsonb_build_object(
            'attempt_id', CASE WHEN v_attempt_id IS NULL THEN NULL ELSE v_attempt_id::text END,
            'recorded_at_utc', v_now::text,
            'transfer_scope_id', CASE WHEN p_transfer_scope_id IS NULL THEN NULL ELSE p_transfer_scope_id::text END,
            'provider_chunk_id', CASE WHEN p_provider_chunk_id IS NULL THEN NULL ELSE p_provider_chunk_id::text END,
            'previous_state', NULLIF(BTRIM(COALESCE(p_previous_state, '')), ''),
            'new_state', UPPER(BTRIM(COALESCE(p_new_state, ''))),
            'provider_transaction_id_present', NULLIF(BTRIM(COALESCE(p_provider_transaction_id, '')), '') IS NOT NULL,
            'provider_request_id_present', NULLIF(BTRIM(COALESCE(p_request_id, '')), '') IS NOT NULL,
            'provider_idempotency_key_present', NULLIF(BTRIM(COALESCE(p_idempotency_key, '')), '') IS NOT NULL,
            'error_present', p_error_json IS NOT NULL
          ))
        )
      ),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN jsonb_build_object(
    'ok', true,
    'attempt_id', CASE WHEN v_attempt_id IS NULL THEN NULL ELSE v_attempt_id::text END,
    'operation_id', p_operation_id::text,
    'pay_batch_id', CASE WHEN v_effective_pay_batch_id IS NULL THEN NULL ELSE v_effective_pay_batch_id::text END,
    'transfer_scope_id', CASE WHEN p_transfer_scope_id IS NULL THEN NULL ELSE p_transfer_scope_id::text END,
    'provider_chunk_id', CASE WHEN p_provider_chunk_id IS NULL THEN NULL ELSE p_provider_chunk_id::text END,
    'previous_state', NULLIF(BTRIM(COALESCE(p_previous_state, '')), ''),
    'new_state', UPPER(BTRIM(COALESCE(p_new_state, ''))),
    'created_at_utc', v_now::text,
    'compact_request_hash', v_request_hash,
    'compact_response_hash', v_response_hash,
    'error_present', p_error_json IS NOT NULL
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_execute_bank_transfer_scope_rollup_chunk(
  p_operation_id uuid,
  p_transfer_scope_id uuid,
  p_cursor jsonb DEFAULT NULL::jsonb,
  p_limit integer DEFAULT 100,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_scope_row public.banking_pay_operation_transfer_scope%ROWTYPE;
  v_last_item_ordinal bigint := 0;
  v_page_count integer := 0;
  v_processed_count integer := 0;
  v_page_error_count integer := 0;
  v_page_prepared_count integer := 0;
  v_page_prepared_amount numeric(14,2) := 0;
  v_prepared_item_count integer := 0;
  v_prepared_amount_total numeric(14,2) := 0;
  v_effective_scope_amount numeric(14,2) := 0;
  v_membership_seed_complete boolean := false;
  v_has_more boolean := false;
  v_next_cursor jsonb := NULL::jsonb;
  v_provider_ready boolean := false;
  v_prepared_scope_hash text := NULL::text;
  v_prepared_result_hash text := NULL::text;
BEGIN
  PERFORM set_config('lock_timeout', '3s', true);
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_OPERATION_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_OPERATION_ID_REQUIRED')::text;
  END IF;

  IF p_transfer_scope_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_SCOPE_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_SCOPE_ID_REQUIRED')::text;
  END IF;

  IF p_cursor IS NOT NULL AND jsonb_typeof(p_cursor) <> 'object' THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_CURSOR_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_CURSOR_MUST_BE_OBJECT')::text;
  END IF;

  IF nullif(btrim(coalesce(p_cursor->>'last_item_ordinal', '')), '') ~ '^[0-9]+$' THEN
    v_last_item_ordinal := (p_cursor->>'last_item_ordinal')::bigint;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_OPERATION_NOT_FOUND', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_OPERATION_TYPE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_OPERATION_TYPE_INVALID', 'operation_id', p_operation_id::text, 'operation_type', v_operation_row.operation_type)::text;
  END IF;

  SELECT scope_row.*
  INTO v_scope_row
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  WHERE scope_row.id = p_transfer_scope_id
    AND scope_row.operation_id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_SCOPE_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_SCOPE_NOT_FOUND', 'operation_id', p_operation_id::text, 'transfer_scope_id', p_transfer_scope_id::text)::text;
  END IF;

  IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> v_scope_row.pay_batch_id THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_OPERATION_BATCH_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_OPERATION_BATCH_MISMATCH', 'operation_id', p_operation_id::text, 'operation_pay_batch_id', v_operation_row.pay_batch_id::text, 'scope_pay_batch_id', v_scope_row.pay_batch_id::text)::text;
  END IF;

  IF upper(btrim(coalesce(v_scope_row.provider_submit_state, 'NOT_READY'))) NOT IN ('', 'NOT_READY', 'READY', 'REVIEW_REQUIRED') THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_PROVIDER_STATE_ALREADY_STARTED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_PROVIDER_STATE_ALREADY_STARTED', 'transfer_scope_id', p_transfer_scope_id::text, 'provider_submit_state', v_scope_row.provider_submit_state)::text;
  END IF;

  v_membership_seed_complete := COALESCE((v_operation_row.progress_json #>> ARRAY['transfer_scope_item_seed_proofs', p_transfer_scope_id::text, 'seed_complete'])::boolean, false);

  DROP TABLE IF EXISTS pg_temp.tmp_transfer_scope_rollup_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_transfer_scope_rollup_page ON COMMIT DROP AS
  SELECT scope_item.pay_batch_item_id,
         scope_item.item_ordinal,
         scope_item.item_amount,
         CASE
           WHEN item_rows.id IS NULL THEN 'MISSING'
           WHEN COALESCE(item_rows.is_voided, false) THEN 'VOIDED'
           WHEN upper(btrim(coalesce(scope_item.item_status, ''))) IN ('VOIDED', 'PAYOUT_INSTRUCTION_MISSING', 'MISSING', 'ERROR') THEN upper(btrim(coalesce(scope_item.item_status, 'ERROR')))
           WHEN COALESCE(scope_item.item_amount, 0) <> 0 AND item_rows.payout_instruction_snapshot_json IS NULL THEN 'PAYOUT_INSTRUCTION_MISSING'
           ELSE 'PREPARED'
         END AS validation_status
  FROM public.banking_pay_operation_transfer_scope_items AS scope_item
  LEFT JOIN public.pay_batch_items AS item_rows
    ON item_rows.id = scope_item.pay_batch_item_id
  WHERE scope_item.operation_id = p_operation_id
    AND scope_item.transfer_scope_id = p_transfer_scope_id
    AND scope_item.item_ordinal > v_last_item_ordinal
    AND upper(btrim(coalesce(scope_item.rollup_status, ''))) = 'PENDING'
  ORDER BY scope_item.item_ordinal, scope_item.pay_batch_item_id
  LIMIT (v_limit + 1);

  SELECT count(*)::integer
  INTO v_page_count
  FROM pg_temp.tmp_transfer_scope_rollup_page AS page_row;

  v_has_more := coalesce(v_page_count, 0) > v_limit;

  WITH page_rows AS (
    SELECT page_row.*
    FROM pg_temp.tmp_transfer_scope_rollup_page AS page_row
    ORDER BY page_row.item_ordinal, page_row.pay_batch_item_id
    LIMIT v_limit
  ), updated AS (
    UPDATE public.banking_pay_operation_transfer_scope_items AS scope_item
    SET item_status = page_rows.validation_status,
        rollup_status = CASE WHEN page_rows.validation_status = 'PREPARED' THEN 'ROLLED_UP' ELSE 'ERROR' END,
        updated_at_utc = v_now
    FROM page_rows
    WHERE scope_item.operation_id = p_operation_id
      AND scope_item.transfer_scope_id = p_transfer_scope_id
      AND scope_item.pay_batch_item_id = page_rows.pay_batch_item_id
    RETURNING scope_item.item_status,
              scope_item.item_amount,
              scope_item.item_ordinal,
              scope_item.pay_batch_item_id
  )
  SELECT count(*)::integer,
         count(*) FILTER (WHERE updated.item_status = 'PREPARED')::integer,
         count(*) FILTER (WHERE updated.item_status <> 'PREPARED')::integer,
         round(coalesce(sum(CASE WHEN updated.item_status = 'PREPARED' THEN coalesce(updated.item_amount, 0) ELSE 0 END), 0), 2)::numeric(14,2),
         md5(coalesce(string_agg(updated.pay_batch_item_id::text || ':' || coalesce(updated.item_amount, 0)::text || ':' || coalesce(updated.item_status, ''), '|' ORDER BY updated.item_ordinal, updated.pay_batch_item_id), 'NO_PAGE_ITEMS'))
  INTO v_processed_count,
       v_page_prepared_count,
       v_page_error_count,
       v_page_prepared_amount,
       v_prepared_scope_hash
  FROM updated;

  v_prepared_item_count := coalesce(v_scope_row.prepared_item_count, 0) + coalesce(v_page_prepared_count, 0);
  v_prepared_amount_total := round(coalesce(v_scope_row.prepared_amount_total, 0) + coalesce(v_page_prepared_amount, 0), 2);
  v_effective_scope_amount := CASE WHEN round(coalesce(v_scope_row.amount, 0), 2) = 0 AND coalesce(v_prepared_amount_total, 0) <> 0 THEN v_prepared_amount_total ELSE round(coalesce(v_scope_row.amount, 0), 2) END;

  v_provider_ready := (
    coalesce(v_membership_seed_complete, false) = true
    AND coalesce(v_has_more, false) = false
    AND coalesce(v_page_error_count, 0) = 0
    AND coalesce(v_scope_row.provider_review_required, false) = false
    AND coalesce(v_prepared_item_count, 0) > 0
    AND round(coalesce(v_prepared_amount_total, 0), 2) = round(coalesce(v_effective_scope_amount, 0), 2)
    AND v_scope_row.pay_bank_transfer_id IS NOT NULL
  );

  v_prepared_result_hash := md5(jsonb_build_object(
    'operation_id', p_operation_id::text,
    'transfer_scope_id', p_transfer_scope_id::text,
    'pay_batch_id', v_scope_row.pay_batch_id::text,
    'prepared_item_count', coalesce(v_prepared_item_count, 0),
    'prepared_amount_total', round(coalesce(v_prepared_amount_total, 0), 2),
    'scope_amount', round(coalesce(v_effective_scope_amount, 0), 2),
    'page_hash', v_prepared_scope_hash,
    'provider_ready', v_provider_ready,
    'has_more', coalesce(v_has_more, false)
  )::text);

  UPDATE public.banking_pay_operation_transfer_scope AS scope_update
  SET prepared_item_count = coalesce(v_prepared_item_count, 0),
      prepared_amount_total = round(coalesce(v_prepared_amount_total, 0), 2),
      amount = CASE WHEN round(coalesce(scope_update.amount, 0), 2) = 0 AND coalesce(v_prepared_amount_total, 0) <> 0 THEN round(coalesce(v_prepared_amount_total, 0), 2) ELSE scope_update.amount END,
      prepared_scope_hash = md5(coalesce(scope_update.prepared_scope_hash, '') || ':' || coalesce(v_prepared_scope_hash, '') || ':' || coalesce(v_processed_count, 0)::text),
      prepared_result_hash = v_prepared_result_hash,
      provider_submit_ready = v_provider_ready,
      provider_submit_state = CASE
        WHEN v_provider_ready THEN 'READY'
        WHEN coalesce(v_page_error_count, 0) > 0 THEN 'REVIEW_REQUIRED'
        ELSE 'NOT_READY'
      END,
      provider_review_required = coalesce(scope_update.provider_review_required, false) OR coalesce(v_page_error_count, 0) > 0,
      provider_unsafe_reason = CASE
        WHEN coalesce(v_page_error_count, 0) > 0 THEN 'TRANSFER_SCOPE_ITEM_ROLLUP_ERROR'
        WHEN coalesce(v_membership_seed_complete, false) IS NOT TRUE THEN 'TRANSFER_SCOPE_ITEM_SEED_INCOMPLETE'
        WHEN coalesce(v_has_more, false) THEN 'TRANSFER_SCOPE_ITEM_ROLLUP_PENDING'
        WHEN scope_update.pay_bank_transfer_id IS NULL THEN 'TRANSFER_PREPARE_PENDING'
        WHEN round(coalesce(v_prepared_amount_total, 0), 2) <> round(coalesce(v_effective_scope_amount, 0), 2) THEN 'TRANSFER_SCOPE_AMOUNT_MISMATCH'
        ELSE NULL::text
      END,
      status = CASE
        WHEN v_provider_ready THEN 'PREPARED'
        WHEN coalesce(v_page_error_count, 0) > 0 THEN 'FAILED'
        WHEN coalesce(v_has_more, false) IS NOT TRUE AND coalesce(v_membership_seed_complete, false) THEN 'ROLLED_UP'
        ELSE scope_update.status
      END,
      updated_at_utc = v_now
  WHERE scope_update.id = p_transfer_scope_id;

  IF v_has_more THEN
    SELECT jsonb_build_object(
      'last_item_ordinal', page_row.item_ordinal,
      'last_pay_batch_item_id', page_row.pay_batch_item_id::text
    )
    INTO v_next_cursor
    FROM pg_temp.tmp_transfer_scope_rollup_page AS page_row
    ORDER BY page_row.item_ordinal, page_row.pay_batch_item_id
    LIMIT 1 OFFSET GREATEST(v_limit - 1, 0);
  ELSE
    v_next_cursor := NULL::jsonb;
  END IF;

  UPDATE public.banking_pay_operations AS operation_update
  SET phase = CASE WHEN coalesce(v_has_more, false) THEN 'ROLLUP_TRANSFER_SCOPE_ITEMS' ELSE 'PREPARE_TRANSFER_CHUNKS' END,
      runner_state = CASE WHEN upper(btrim(coalesce(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN operation_update.runner_state ELSE 'RUNNABLE' END,
      run_after_utc = CASE WHEN upper(btrim(coalesce(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN operation_update.run_after_utc ELSE v_now END,
      progress_json = jsonb_strip_nulls(
        coalesce(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'last_transfer_scope_rollup', jsonb_build_object(
            'transfer_scope_id', p_transfer_scope_id::text,
            'rolled_at_utc', v_now::text,
            'processed_count', coalesce(v_processed_count, 0),
            'membership_seed_complete', coalesce(v_membership_seed_complete, false),
            'provider_submit_ready', v_provider_ready,
            'has_more', coalesce(v_has_more, false),
            'next_cursor', v_next_cursor
          ),
          'transfer_scope_rollup_proofs', CASE
              WHEN jsonb_typeof(operation_update.progress_json->'transfer_scope_rollup_proofs') = 'object'
                THEN coalesce(operation_update.progress_json->'transfer_scope_rollup_proofs', '{}'::jsonb)
              ELSE '{}'::jsonb
            END || jsonb_build_object(
              p_transfer_scope_id::text,
              jsonb_build_object(
                'membership_seed_complete', coalesce(v_membership_seed_complete, false),
                'prepared_item_count', coalesce(v_prepared_item_count, 0),
                'prepared_amount_total', round(coalesce(v_prepared_amount_total, 0), 2),
                'prepared_result_hash', v_prepared_result_hash,
                'provider_submit_ready', v_provider_ready,
                'updated_at_utc', v_now::text
              )
            ),
          'next_required_phase', CASE WHEN coalesce(v_has_more, false) THEN 'TRANSFER_SCOPE_ROLLUP_PAGE' ELSE 'TRANSFER_CHUNK_PREPARE_PAGE' END
        )
      ),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', v_scope_row.pay_batch_id::text,
    'transfer_scope_id', p_transfer_scope_id::text,
    'limit', v_limit,
    'processed_count', coalesce(v_processed_count, 0),
    'page_error_count', coalesce(v_page_error_count, 0),
    'membership_seed_complete', coalesce(v_membership_seed_complete, false),
    'prepared_item_count', coalesce(v_prepared_item_count, 0),
    'prepared_amount_total', round(coalesce(v_prepared_amount_total, 0), 2),
    'scope_amount', round(coalesce(v_effective_scope_amount, 0), 2),
    'prepared_result_hash', v_prepared_result_hash,
    'provider_submit_ready', v_provider_ready,
    'has_more', coalesce(v_has_more, false),
    'next_cursor', v_next_cursor,
    'server_utc', v_now::text
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.banking_pay_operation_lease_heartbeat(
  p_operation_id uuid,
  p_lease_owner text,
  p_extend_seconds integer DEFAULT 60,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_extend_seconds integer := LEAST(GREATEST(COALESCE(p_extend_seconds, 60), 10), 300);
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_new_lease_expires_at_utc timestamptz;
BEGIN
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_PAY_OPERATION_HEARTBEAT_OPERATION_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_HEARTBEAT_OPERATION_ID_REQUIRED')::text;
  END IF;

  IF NULLIF(BTRIM(COALESCE(p_lease_owner, '')), '') IS NULL THEN
    RAISE EXCEPTION 'BANKING_PAY_OPERATION_HEARTBEAT_LEASE_OWNER_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_HEARTBEAT_LEASE_OWNER_REQUIRED', 'operation_id', p_operation_id::text)::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BANKING_PAY_OPERATION_HEARTBEAT_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_HEARTBEAT_OPERATION_NOT_FOUND', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_operation_row.lease_owner, '')), '') IS NULL
     OR v_operation_row.lease_owner <> p_lease_owner THEN
    RAISE EXCEPTION 'BANKING_PAY_OPERATION_HEARTBEAT_LEASE_OWNER_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_HEARTBEAT_LEASE_OWNER_MISMATCH', 'operation_id', p_operation_id::text, 'expected_lease_owner', v_operation_row.lease_owner, 'actual_lease_owner', p_lease_owner)::text;
  END IF;

  IF v_operation_row.lease_expires_at_utc IS NULL OR v_operation_row.lease_expires_at_utc <= v_now THEN
    RAISE EXCEPTION 'BANKING_PAY_OPERATION_HEARTBEAT_LEASE_EXPIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'BANKING_PAY_OPERATION_HEARTBEAT_LEASE_EXPIRED', 'operation_id', p_operation_id::text, 'lease_expires_at_utc', CASE WHEN v_operation_row.lease_expires_at_utc IS NULL THEN NULL ELSE v_operation_row.lease_expires_at_utc::text END)::text;
  END IF;

  v_new_lease_expires_at_utc := v_now + make_interval(secs => v_extend_seconds);

  UPDATE public.banking_pay_operations AS operation_update
  SET heartbeat_at_utc = v_now,
      lease_expires_at_utc = v_new_lease_expires_at_utc,
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'lease_owner', p_lease_owner,
    'heartbeat_at_utc', v_now::text,
    'lease_expires_at_utc', v_new_lease_expires_at_utc::text,
    'status', v_operation_row.status,
    'runner_state', v_operation_row.runner_state
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.pay_execute_bank_transfer_scope_items_seed_chunk(
  p_operation_id uuid,
  p_transfer_scope_id uuid,
  p_cursor jsonb DEFAULT NULL::jsonb,
  p_limit integer DEFAULT 100,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_scope_row public.banking_pay_operation_transfer_scope%ROWTYPE;
  v_batch_row public.pay_batches%ROWTYPE;
  v_last_pay_batch_item_id uuid := NULL::uuid;
  v_last_item_ordinal bigint := 0;
  v_page_count integer := 0;
  v_seeded_count integer := 0;
  v_page_error_count integer := 0;
  v_has_more boolean := false;
  v_seed_complete boolean := false;
  v_next_cursor jsonb := NULL::jsonb;
  v_seed_proof_hash text := NULL::text;
  v_membership_count bigint := 0;
  v_no_source boolean := false;
BEGIN
  PERFORM set_config('lock_timeout', '3s', true);
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_OPERATION_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_OPERATION_ID_REQUIRED')::text;
  END IF;

  IF p_transfer_scope_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_SCOPE_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_SCOPE_ID_REQUIRED')::text;
  END IF;

  IF p_cursor IS NOT NULL AND jsonb_typeof(p_cursor) <> 'object' THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_CURSOR_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_CURSOR_MUST_BE_OBJECT')::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_OPERATION_NOT_FOUND', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_OPERATION_TYPE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_OPERATION_TYPE_INVALID', 'operation_id', p_operation_id::text, 'operation_type', v_operation_row.operation_type)::text;
  END IF;

  SELECT scope_row.*
  INTO v_scope_row
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  WHERE scope_row.id = p_transfer_scope_id
    AND scope_row.operation_id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_SCOPE_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_SCOPE_NOT_FOUND', 'operation_id', p_operation_id::text, 'transfer_scope_id', p_transfer_scope_id::text)::text;
  END IF;

  IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> v_scope_row.pay_batch_id THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_OPERATION_BATCH_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_OPERATION_BATCH_MISMATCH', 'operation_id', p_operation_id::text, 'operation_pay_batch_id', v_operation_row.pay_batch_id::text, 'scope_pay_batch_id', v_scope_row.pay_batch_id::text)::text;
  END IF;

  IF upper(btrim(coalesce(v_scope_row.provider_submit_state, 'NOT_READY'))) NOT IN ('', 'NOT_READY', 'READY', 'REVIEW_REQUIRED') THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_PROVIDER_STATE_ALREADY_STARTED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_PROVIDER_STATE_ALREADY_STARTED', 'transfer_scope_id', p_transfer_scope_id::text, 'provider_submit_state', v_scope_row.provider_submit_state)::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = v_scope_row.pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_BATCH_NOT_FOUND', 'pay_batch_id', v_scope_row.pay_batch_id::text)::text;
  END IF;

  IF nullif(btrim(coalesce(p_cursor->>'last_pay_batch_item_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_last_pay_batch_item_id := (p_cursor->>'last_pay_batch_item_id')::uuid;
  END IF;
  IF nullif(btrim(coalesce(p_cursor->>'last_item_ordinal', '')), '') ~ '^[0-9]+$' THEN
    v_last_item_ordinal := (p_cursor->>'last_item_ordinal')::bigint;
  END IF;

  IF v_last_pay_batch_item_id IS NULL THEN
    SELECT existing_scope_item.pay_batch_item_id,
           existing_scope_item.item_ordinal
    INTO v_last_pay_batch_item_id,
         v_last_item_ordinal
    FROM public.banking_pay_operation_transfer_scope_items AS existing_scope_item
    WHERE existing_scope_item.operation_id = p_operation_id
      AND existing_scope_item.transfer_scope_id = p_transfer_scope_id
    ORDER BY existing_scope_item.item_ordinal DESC, existing_scope_item.pay_batch_item_id DESC
    LIMIT 1;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_transfer_scope_item_seed_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_transfer_scope_item_seed_page ON COMMIT DROP AS
  WITH candidate_item_page AS (
    SELECT batch_item.id AS pay_batch_item_id,
           batch_item.pay_batch_candidate_id,
           batch_candidate.candidate_id,
           batch_candidate.net_bank_amount,
           COALESCE(batch_item.amount_inc_vat, batch_item.amount_ex_vat, 0)::numeric AS source_item_amount,
           batch_item.item_type,
           batch_item.is_voided,
           batch_item.payout_instruction_snapshot_json,
           row_number() OVER (ORDER BY batch_item.id)::bigint AS page_row_no
    FROM public.pay_batch_items AS batch_item
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = batch_item.pay_batch_candidate_id
    WHERE batch_candidate.pay_batch_id = v_scope_row.pay_batch_id
      AND batch_candidate.candidate_id = v_scope_row.candidate_id
      AND coalesce(batch_item.is_voided, false) = false
      AND batch_item.item_type <> 'DEBT_CREATED'
      AND (v_last_pay_batch_item_id IS NULL OR batch_item.id > v_last_pay_batch_item_id)
      AND (
        (v_scope_row.pay_channel = 'PAYE' AND (CASE WHEN upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) = 'LOANS' THEN 'PAYE' ELSE batch_item.pay_channel END) = 'PAYE')
        OR (v_scope_row.pay_channel = 'UMBRELLA' AND (CASE WHEN upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) = 'LOANS' THEN 'PAYE' ELSE batch_item.pay_channel END) = 'UMBRELLA')
      )
      AND (
        CASE
          WHEN CASE WHEN upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) = 'LOANS' THEN 'PAYE' ELSE batch_item.pay_channel END = 'PAYE'
            THEN batch_candidate.candidate_id::text || '|PAYE|' || coalesce(nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'bank_details_hash', '')), ''), '')
          WHEN CASE WHEN upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) = 'LOANS' THEN 'PAYE' ELSE batch_item.pay_channel END = 'UMBRELLA'
            THEN batch_candidate.candidate_id::text || '|UMBRELLA|' || coalesce(CASE WHEN coalesce(batch_item.payout_instruction_snapshot_json->>'week_ending_bucket', '') ~ '^\d{4}-\d{2}-\d{2}$' THEN (batch_item.payout_instruction_snapshot_json->>'week_ending_bucket') ELSE 'NO_WEEK' END, 'NO_WEEK') || '|' || coalesce(batch_item.payout_instruction_snapshot_json->>'payee_entity_id', '') || '|' || coalesce(nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'bank_details_hash', '')), ''), '')
          ELSE batch_candidate.candidate_id::text || '|OTHER|' || coalesce(nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'bank_details_hash', '')), ''), '')
        END
      ) = v_scope_row.transfer_group_key
    ORDER BY batch_item.id
    LIMIT (v_limit + 1)
  )
  SELECT (v_last_item_ordinal + candidate_item_page.page_row_no)::bigint AS item_ordinal,
         candidate_item_page.pay_batch_item_id,
         candidate_item_page.pay_batch_candidate_id,
         candidate_item_page.candidate_id,
         round(
           CASE
             WHEN v_scope_row.pay_channel = 'PAYE' THEN CASE WHEN (v_last_item_ordinal + candidate_item_page.page_row_no) = 1 THEN coalesce(nullif(v_scope_row.amount, 0), candidate_item_page.net_bank_amount, 0) ELSE 0 END
             ELSE coalesce(candidate_item_page.source_item_amount, 0)
           END,
           2
         )::numeric(14,2) AS item_amount,
         CASE
           WHEN COALESCE(candidate_item_page.is_voided, false) THEN 'VOIDED'
           WHEN candidate_item_page.item_type = 'DEBT_CREATED' THEN 'IGNORED_DEBT_CREATED'
           WHEN COALESCE(candidate_item_page.source_item_amount, 0) <> 0
            AND candidate_item_page.payout_instruction_snapshot_json IS NULL THEN 'PAYOUT_INSTRUCTION_MISSING'
           ELSE 'PENDING'
         END AS seed_status
  FROM candidate_item_page
  ORDER BY candidate_item_page.page_row_no;

  SELECT count(*)::integer
  INTO v_page_count
  FROM pg_temp.tmp_transfer_scope_item_seed_page AS page_row;

  v_has_more := coalesce(v_page_count, 0) > v_limit;

  WITH page_rows AS (
    SELECT page_row.*
    FROM pg_temp.tmp_transfer_scope_item_seed_page AS page_row
    ORDER BY page_row.item_ordinal, page_row.pay_batch_item_id
    LIMIT v_limit
  ), upserted AS (
    INSERT INTO public.banking_pay_operation_transfer_scope_items (
      operation_id,
      pay_batch_id,
      transfer_scope_id,
      pay_batch_item_id,
      pay_batch_candidate_id,
      candidate_id,
      item_amount,
      item_status,
      item_ordinal,
      rollup_status,
      created_at_utc,
      updated_at_utc
    )
    SELECT p_operation_id,
           v_scope_row.pay_batch_id,
           p_transfer_scope_id,
           page_rows.pay_batch_item_id,
           page_rows.pay_batch_candidate_id,
           page_rows.candidate_id,
           page_rows.item_amount,
           page_rows.seed_status,
           page_rows.item_ordinal,
           'PENDING',
           v_now,
           v_now
    FROM page_rows
    ON CONFLICT (operation_id, transfer_scope_id, pay_batch_item_id)
    DO UPDATE
    SET pay_batch_id = EXCLUDED.pay_batch_id,
        pay_batch_candidate_id = EXCLUDED.pay_batch_candidate_id,
        candidate_id = EXCLUDED.candidate_id,
        item_amount = EXCLUDED.item_amount,
        item_status = CASE WHEN public.banking_pay_operation_transfer_scope_items.rollup_status IN ('ROLLED_UP', 'PREPARED', 'READY', 'COMPLETE', 'COMPLETED') THEN public.banking_pay_operation_transfer_scope_items.item_status ELSE EXCLUDED.item_status END,
        item_ordinal = EXCLUDED.item_ordinal,
        rollup_status = CASE WHEN public.banking_pay_operation_transfer_scope_items.rollup_status IN ('ROLLED_UP', 'PREPARED', 'READY', 'COMPLETE', 'COMPLETED') THEN public.banking_pay_operation_transfer_scope_items.rollup_status ELSE 'PENDING' END,
        updated_at_utc = v_now
    RETURNING item_status, item_ordinal, pay_batch_item_id
  )
  SELECT count(*)::integer,
         count(*) FILTER (WHERE upper(btrim(coalesce(upserted.item_status, ''))) IN ('VOIDED', 'PAYOUT_INSTRUCTION_MISSING', 'MISSING', 'ERROR'))::integer,
         max(upserted.item_ordinal)
  INTO v_seeded_count,
       v_page_error_count,
       v_membership_count
  FROM upserted;

  v_no_source := coalesce(v_seeded_count, 0) = 0 AND coalesce(v_last_item_ordinal, 0) = 0;
  v_seed_complete := coalesce(v_has_more, false) IS NOT TRUE;

  IF v_has_more THEN
    SELECT jsonb_build_object(
      'last_item_ordinal', page_row.item_ordinal,
      'last_pay_batch_item_id', page_row.pay_batch_item_id::text
    )
    INTO v_next_cursor
    FROM pg_temp.tmp_transfer_scope_item_seed_page AS page_row
    ORDER BY page_row.item_ordinal, page_row.pay_batch_item_id
    LIMIT 1 OFFSET GREATEST(v_limit - 1, 0);
  ELSE
    v_next_cursor := NULL::jsonb;
  END IF;

  v_seed_proof_hash := md5(jsonb_build_object(
    'operation_id', p_operation_id::text,
    'transfer_scope_id', p_transfer_scope_id::text,
    'pay_batch_id', v_scope_row.pay_batch_id::text,
    'seeded_count', coalesce(v_seeded_count, 0),
    'last_item_ordinal', coalesce(v_membership_count, v_last_item_ordinal, 0),
    'seed_complete', coalesce(v_seed_complete, false),
    'has_more', coalesce(v_has_more, false)
  )::text);

  UPDATE public.banking_pay_operation_transfer_scope AS scope_update
  SET provider_submit_ready = false,
      provider_submit_state = CASE WHEN coalesce(v_page_error_count, 0) > 0 OR v_no_source THEN 'REVIEW_REQUIRED' ELSE 'NOT_READY' END,
      provider_review_required = coalesce(v_page_error_count, 0) > 0 OR v_no_source,
      provider_unsafe_reason = CASE
        WHEN v_no_source THEN 'TRANSFER_SCOPE_ITEM_SOURCE_EMPTY'
        WHEN coalesce(v_page_error_count, 0) > 0 THEN 'TRANSFER_SCOPE_ITEM_SEED_ERROR'
        WHEN coalesce(v_seed_complete, false) IS NOT TRUE THEN 'TRANSFER_SCOPE_ITEM_SEED_INCOMPLETE'
        ELSE 'TRANSFER_SCOPE_ITEM_ROLLUP_PENDING'
      END,
      updated_at_utc = v_now
  WHERE scope_update.id = p_transfer_scope_id;

  UPDATE public.banking_pay_operations AS operation_update
  SET phase = CASE WHEN coalesce(v_has_more, false) THEN 'SEED_TRANSFER_SCOPE_ITEMS' ELSE 'ROLLUP_TRANSFER_SCOPE_ITEMS' END,
      runner_state = CASE WHEN upper(btrim(coalesce(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN operation_update.runner_state ELSE 'RUNNABLE' END,
      run_after_utc = CASE WHEN upper(btrim(coalesce(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN operation_update.run_after_utc ELSE v_now END,
      progress_json = jsonb_strip_nulls(
        coalesce(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'last_transfer_scope_item_seed', jsonb_build_object(
            'transfer_scope_id', p_transfer_scope_id::text,
            'seeded_at_utc', v_now::text,
            'seeded_count', coalesce(v_seeded_count, 0),
            'last_item_ordinal', coalesce(v_membership_count, v_last_item_ordinal, 0),
            'seed_complete', coalesce(v_seed_complete, false),
            'seed_proof_hash', v_seed_proof_hash,
            'has_more', coalesce(v_has_more, false),
            'next_cursor', v_next_cursor
          ),
          'transfer_scope_item_seed_proofs', CASE
              WHEN jsonb_typeof(operation_update.progress_json->'transfer_scope_item_seed_proofs') = 'object'
                THEN coalesce(operation_update.progress_json->'transfer_scope_item_seed_proofs', '{}'::jsonb)
              ELSE '{}'::jsonb
            END || jsonb_build_object(
              p_transfer_scope_id::text,
              jsonb_build_object(
                'last_item_ordinal', coalesce(v_membership_count, v_last_item_ordinal, 0),
                'seed_complete', coalesce(v_seed_complete, false),
                'seed_proof_hash', v_seed_proof_hash,
                'updated_at_utc', v_now::text
              )
            ),
          'next_required_phase', CASE WHEN coalesce(v_has_more, false) THEN 'TRANSFER_SCOPE_ITEM_MEMBERSHIP_SEED_PAGE' ELSE 'TRANSFER_SCOPE_ROLLUP_PAGE' END
        )
      ),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', v_scope_row.pay_batch_id::text,
    'transfer_scope_id', p_transfer_scope_id::text,
    'source_mode', 'ROW_BACKED_TRANSFER_GROUP',
    'limit', v_limit,
    'seeded_count', coalesce(v_seeded_count, 0),
    'last_item_ordinal', coalesce(v_membership_count, v_last_item_ordinal, 0),
    'seed_complete', coalesce(v_seed_complete, false),
    'seed_proof_hash', v_seed_proof_hash,
    'page_error_count', coalesce(v_page_error_count, 0),
    'has_more', coalesce(v_has_more, false),
    'next_cursor', v_next_cursor,
    'server_utc', v_now::text
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_workbench_enqueue_stage_continuation(p_session_id uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_job_type text DEFAULT NULL::text, p_cursor_json jsonb DEFAULT NULL::jsonb, p_source_job_id uuid DEFAULT NULL::uuid, p_result_json jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_priority integer DEFAULT NULL::integer, p_limit integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope_row public.banking_pay_workbench_session_scope%ROWTYPE;
  v_source_job_row public.banking_pay_workbench_jobs%ROWTYPE;
  v_job_type text := UPPER(BTRIM(COALESCE(p_job_type, '')));
  v_reason text := COALESCE(NULLIF(BTRIM(COALESCE(p_reason, '')), ''), 'WORKBENCH_STAGE_CONTINUATION');
  v_result_json jsonb := CASE WHEN jsonb_typeof(COALESCE(p_result_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_result_json, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_actor_user_id uuid := p_actor_user_id;
  v_cursor_json jsonb := NULL::jsonb;
  v_cursor_token text := 'none';
  v_session_signature_token text := 'none';
  v_candidate_key text := 'ALL';
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_priority integer := 50;
  v_line_work_action text := NULL::text;
  v_next_recommended_action text := NULL::text;
  v_progress_state text := NULL::text;
  v_scope_status text := NULL::text;
  v_source_job_session_version bigint := NULL::bigint;
  v_payload_core_json jsonb := '{}'::jsonb;
  v_payload_stage_json jsonb := '{}'::jsonb;
  v_payload_cursor_json jsonb := '{}'::jsonb;
  v_payload_source_json jsonb := '{}'::jsonb;
  v_payload_result_summary_json jsonb := '{}'::jsonb;
  v_payload_json jsonb := '{}'::jsonb;
  v_reuse_patch_json jsonb := '{}'::jsonb;
  v_dedupe_key text := NULL::text;
  v_job_id uuid := NULL::uuid;
  v_job_status text := NULL::text;
  v_job_was_inserted boolean := false;
  v_stale_running_seconds integer := 180;
  v_stale_cutoff timestamptz := NULL::timestamptz;
  v_superseded_stale_count integer := 0;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');
  v_stale_cutoff := v_now - make_interval(secs => v_stale_running_seconds);

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SESSION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_CONTINUATION_SESSION_ID_REQUIRED')::text;
  END IF;

  IF v_job_type = '' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_JOB_TYPE_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_CONTINUATION_JOB_TYPE_REQUIRED', 'session_id', p_session_id::text)::text;
  END IF;

  IF v_job_type NOT IN (
    'WORKBENCH_SESSION_SCOPE_SEED',
    'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
    'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
    'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_UNSUPPORTED_JOB_TYPE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CONTINUATION_UNSUPPORTED_JOB_TYPE',
              'session_id', p_session_id::text,
              'job_type', v_job_type
            )::text;
  END IF;

  IF p_cursor_json IS NOT NULL AND jsonb_typeof(p_cursor_json) <> 'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_CURSOR_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CONTINUATION_CURSOR_MUST_BE_OBJECT',
              'session_id', p_session_id::text,
              'job_type', v_job_type,
              'cursor_type', jsonb_typeof(p_cursor_json)
            )::text;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CONTINUATION_SESSION_NOT_FOUND',
              'session_id', p_session_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CONTINUATION_SESSION_NOT_OPEN',
              'session_id', p_session_id::text,
              'status', v_session_row.status,
              'discarded_at_utc', v_session_row.discarded_at_utc
            )::text;
  END IF;

  v_actor_user_id := COALESCE(v_actor_user_id, v_session_row.actor_user_id);
  v_session_signature_token := md5(COALESCE(v_session_row.session_signature, ''));

  IF p_source_job_id IS NOT NULL THEN
    SELECT source_job.*
    INTO v_source_job_row
    FROM public.banking_pay_workbench_jobs AS source_job
    WHERE source_job.id = p_source_job_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_NOT_FOUND',
                'session_id', p_session_id::text,
                'source_job_id', p_source_job_id::text,
                'job_type', v_job_type
              )::text;
    END IF;

    IF v_source_job_row.session_id IS DISTINCT FROM p_session_id THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_SESSION_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_SESSION_MISMATCH',
                'session_id', p_session_id::text,
                'source_job_id', p_source_job_id::text,
                'source_job_session_id', CASE WHEN v_source_job_row.session_id IS NULL THEN NULL ELSE v_source_job_row.session_id::text END,
                'job_type', v_job_type
              )::text;
    END IF;

    IF v_source_job_row.snapshot_run_id IS DISTINCT FROM v_session_row.source_snapshot_run_id THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_SNAPSHOT_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_SNAPSHOT_MISMATCH',
                'session_id', p_session_id::text,
                'source_job_id', p_source_job_id::text,
                'source_job_snapshot_run_id', CASE WHEN v_source_job_row.snapshot_run_id IS NULL THEN NULL ELSE v_source_job_row.snapshot_run_id::text END,
                'session_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
                'job_type', v_job_type
              )::text;
    END IF;

    IF COALESCE(v_source_job_row.payload_json->>'session_version', '') ~ '^[0-9]+$' THEN
      v_source_job_session_version := (v_source_job_row.payload_json->>'session_version')::bigint;

      IF COALESCE(v_source_job_session_version, 0) <> COALESCE(v_session_row.version, 0) THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_SESSION_VERSION_STALE'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_SESSION_VERSION_STALE',
                  'session_id', p_session_id::text,
                  'source_job_id', p_source_job_id::text,
                  'source_job_session_version', v_source_job_session_version,
                  'current_session_version', COALESCE(v_session_row.version, 0),
                  'job_type', v_job_type
                )::text;
      END IF;
    END IF;
  END IF;

  IF v_job_type = 'WORKBENCH_SESSION_SCOPE_SEED' THEN
    IF p_candidate_id IS NOT NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SCOPE_SEED_CANDIDATE_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_SCOPE_SEED_CANDIDATE_NOT_ALLOWED',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text,
                'job_type', v_job_type
              )::text;
    END IF;

    v_line_work_action := 'SCOPE_SEED';
    v_next_recommended_action := 'SEED_SCOPE_CHUNK';
    v_progress_state := 'REFRESHING_CANDIDATES';
    v_priority := COALESCE(p_priority, 40);
  ELSE
    IF p_candidate_id IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_CANDIDATE_ID_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_CANDIDATE_ID_REQUIRED',
                'session_id', p_session_id::text,
                'job_type', v_job_type
              )::text;
    END IF;

    SELECT scope_row.*
    INTO v_scope_row
    FROM public.banking_pay_workbench_session_scope AS scope_row
    WHERE scope_row.session_id = p_session_id
      AND scope_row.candidate_id = p_candidate_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_CANDIDATE_NOT_IN_SCOPE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_CANDIDATE_NOT_IN_SCOPE',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text,
                'job_type', v_job_type
              )::text;
    END IF;

    IF p_source_job_id IS NOT NULL
       AND v_source_job_row.candidate_id IS NOT NULL
       AND v_source_job_row.candidate_id IS DISTINCT FROM p_candidate_id THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_CANDIDATE_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_CANDIDATE_MISMATCH',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text,
                'source_job_id', p_source_job_id::text,
                'source_job_candidate_id', v_source_job_row.candidate_id::text,
                'job_type', v_job_type
              )::text;
    END IF;

    v_candidate_key := p_candidate_id::text;

    IF v_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_SEED' THEN
      v_line_work_action := 'SEED';
      v_next_recommended_action := 'SEED_LINE_WORK_CHUNK';
      v_progress_state := 'REFRESHING_CANDIDATES';
      v_scope_status := CASE
        WHEN UPPER(BTRIM(COALESCE(v_scope_row.status, ''))) = 'PENDING' THEN 'PENDING'
        ELSE 'LINE_WORK_PENDING'
      END;
      v_priority := COALESCE(p_priority, 45);
    ELSIF v_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS' THEN
      v_line_work_action := 'PROCESS';
      v_next_recommended_action := 'PROCESS_LINE_WORK_CHUNK';
      v_progress_state := 'PROCESSING_LINE_WORK';
      v_scope_status := 'LINE_WORK_PENDING';
      v_priority := COALESCE(p_priority, 42);
    ELSE
      v_line_work_action := 'MATERIALISE';
      v_next_recommended_action := 'MATERIALISE_PREVIEW_ROWS_CHUNK';
      v_progress_state := 'MATERIALISING_PREVIEW_ROWS';
      v_scope_status := 'LINE_WORK_READY';
      v_priority := COALESCE(p_priority, 41);
    END IF;
  END IF;

  v_priority := LEAST(GREATEST(COALESCE(v_priority, 50), 1), 999);

  IF p_cursor_json IS NOT NULL AND jsonb_typeof(p_cursor_json) = 'object' THEN
    v_cursor_json := p_cursor_json;
    v_cursor_token := md5(p_cursor_json::text);
  ELSE
    v_cursor_json := NULL::jsonb;
    v_cursor_token := 'none';
  END IF;

  v_dedupe_key := 'WORKBENCH_STAGE_CONTINUATION'
    || ':' || v_job_type
    || ':session:' || p_session_id::text
    || ':version:' || COALESCE(v_session_row.version, 0)::text
    || ':snapshot:' || v_session_row.source_snapshot_run_id::text
    || ':signature:' || v_session_signature_token
    || ':candidate:' || COALESCE(v_candidate_key, 'ALL')
    || ':cursor:' || v_cursor_token;

  v_payload_core_json := jsonb_build_object(
    'session_id', p_session_id::text,
    'session_version', COALESCE(v_session_row.version, 0),
    'snapshot_run_id', v_session_row.source_snapshot_run_id::text,
    'session_signature', v_session_row.session_signature,
    'session_signature_token', v_session_signature_token,
    'actor_user_id', CASE WHEN v_actor_user_id IS NULL THEN NULL ELSE v_actor_user_id::text END,
    'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'job_type', v_job_type,
    'dedupe_key', v_dedupe_key,
    'continuation', true
  );

  v_payload_stage_json := jsonb_build_object(
    'reason', v_reason,
    'continuation_reason', v_reason,
    'line_work_action', v_line_work_action,
    'next_recommended_action', v_next_recommended_action,
    'limit', v_limit,
    'line_limit', v_limit,
    'chunk_size', v_limit,
    'run_mode', 'BOUNDED_CONTINUATION',
    'line_work_required', v_job_type <> 'WORKBENCH_SESSION_SCOPE_SEED',
    'line_work_only', v_job_type <> 'WORKBENCH_SESSION_SCOPE_SEED'
  );

  v_payload_cursor_json := jsonb_build_object(
    'cursor_json', v_cursor_json,
    'cursor', v_cursor_json,
    'cursor_token', v_cursor_token,
    'has_cursor', v_cursor_json IS NOT NULL
  );

  v_payload_source_json := jsonb_build_object(
    'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
    'source_result_has_more', COALESCE(v_result_json->'has_more', 'false'::jsonb),
    'source_result_next_cursor_present', COALESCE((v_result_json ? 'next_cursor') OR (v_result_json ? 'next_cursor_json') OR (v_result_json ? 'nextCursor'), false),
    'created_by_helper', 'pay_workbench_enqueue_stage_continuation',
    'created_at_utc', v_now::text
  );

  v_payload_result_summary_json := jsonb_build_object(
    'source_result_summary', jsonb_strip_nulls(jsonb_build_object(
      'ok', COALESCE(v_result_json->'ok', 'true'::jsonb),
      'seeded_count', v_result_json->'seeded_count',
      'new_scope_count', v_result_json->'new_scope_count',
      'enqueued_count', v_result_json->'enqueued_count',
      'reused_count', v_result_json->'reused_count',
      'processed_count', v_result_json->'processed_count',
      'ready_count_delta', v_result_json->'ready_count_delta',
      'materialised_count', v_result_json->'materialised_count',
      'materialized_count', v_result_json->'materialized_count',
      'new_preview_row_count', v_result_json->'new_preview_row_count',
      'new_selected_row_count', v_result_json->'new_selected_row_count',
      'error_count', v_result_json->'error_count',
      'has_more', v_result_json->'has_more'
    ))
  );

  v_payload_json := v_payload_core_json
    || v_payload_stage_json
    || v_payload_cursor_json
    || v_payload_source_json
    || v_payload_result_summary_json;

  v_reuse_patch_json := jsonb_build_object(
    'last_reused_at_utc', v_now::text,
    'last_reuse_reason', v_reason,
    'last_source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
    'last_actor_user_id', CASE WHEN v_actor_user_id IS NULL THEN NULL ELSE v_actor_user_id::text END
  );

  WITH superseded_stale_jobs AS (
    UPDATE public.banking_pay_workbench_jobs AS superseded_job
    SET status = 'FAILED',
        updated_at_utc = v_now,
        failed_at_utc = v_now,
        last_error_json = jsonb_build_object(
          'code', 'WORKBENCH_JOB_SUPERSEDED_BY_NEWER_SESSION_VERSION',
          'message', 'Superseded stale running workbench preview job while enqueueing newer session-version continuation.',
          'session_id', p_session_id::text,
          'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
          'job_type', v_job_type,
          'current_session_version', COALESCE(v_session_row.version, 0),
          'job_session_version', CASE
            WHEN COALESCE(superseded_job.payload_json->>'session_version', '') ~ '^[0-9]+$'
              THEN (superseded_job.payload_json->>'session_version')::bigint
            ELSE NULL::bigint
          END,
          'stale_running_seconds', v_stale_running_seconds,
          'last_activity_at_utc', COALESCE(superseded_job.updated_at_utc, superseded_job.started_at_utc, superseded_job.run_at_utc, superseded_job.created_at_utc),
          'superseded_at_utc', v_now
        ),
        payload_json = COALESCE(superseded_job.payload_json, '{}'::jsonb) || jsonb_build_object(
          'superseded_by_newer_session_version_at_utc', v_now::text,
          'superseded_by_session_version', COALESCE(v_session_row.version, 0),
          'superseded_by_dedupe_key', v_dedupe_key
        )
    WHERE superseded_job.session_id = p_session_id
      AND superseded_job.candidate_id IS NOT DISTINCT FROM p_candidate_id
      AND superseded_job.snapshot_run_id IS NOT DISTINCT FROM v_session_row.source_snapshot_run_id
      AND UPPER(BTRIM(COALESCE(superseded_job.job_type, ''))) = v_job_type
      AND UPPER(BTRIM(COALESCE(superseded_job.status, ''))) IN ('RUNNING', 'PROCESSING', 'CLAIMED', 'IN_PROGRESS')
      AND superseded_job.completed_at_utc IS NULL
      AND superseded_job.failed_at_utc IS NULL
      AND COALESCE(superseded_job.payload_json->>'cursor_token', 'none') = v_cursor_token
      AND COALESCE(superseded_job.payload_json->>'session_signature_token', 'none') = v_session_signature_token
      AND COALESCE(superseded_job.updated_at_utc, superseded_job.started_at_utc, superseded_job.run_at_utc, superseded_job.created_at_utc) <= v_stale_cutoff
      AND COALESCE(superseded_job.payload_json->>'session_version', '') ~ '^[0-9]+$'
      AND (superseded_job.payload_json->>'session_version')::bigint < COALESCE(v_session_row.version, 0)
    RETURNING superseded_job.id
  )
  SELECT COUNT(*)::integer
  INTO v_superseded_stale_count
  FROM superseded_stale_jobs;

  INSERT INTO public.banking_pay_workbench_jobs (
    job_type,
    status,
    priority,
    run_at_utc,
    attempt_count,
    max_attempts,
    dedupe_key,
    snapshot_run_id,
    session_id,
    candidate_id,
    payload_json,
    created_at_utc,
    updated_at_utc,
    started_at_utc,
    completed_at_utc,
    failed_at_utc,
    last_error_json
  )
  VALUES (
    v_job_type,
    'QUEUED',
    v_priority,
    v_now,
    0,
    8,
    v_dedupe_key,
    v_session_row.source_snapshot_run_id,
    p_session_id,
    p_candidate_id,
    v_payload_json,
    v_now,
    v_now,
    NULL::timestamptz,
    NULL::timestamptz,
    NULL::timestamptz,
    NULL::jsonb
  )
  ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
  DO UPDATE
  SET status = CASE
        WHEN UPPER(BTRIM(COALESCE(public.banking_pay_workbench_jobs.status, ''))) = 'RUNNING'
             AND public.banking_pay_workbench_jobs.completed_at_utc IS NULL
             AND public.banking_pay_workbench_jobs.failed_at_utc IS NULL
             AND COALESCE(public.banking_pay_workbench_jobs.updated_at_utc, public.banking_pay_workbench_jobs.started_at_utc, public.banking_pay_workbench_jobs.run_at_utc, public.banking_pay_workbench_jobs.created_at_utc) <= v_stale_cutoff
             AND COALESCE(public.banking_pay_workbench_jobs.attempt_count, 0) >= GREATEST(COALESCE(public.banking_pay_workbench_jobs.max_attempts, 8), 1)
          THEN 'FAILED'
        WHEN UPPER(BTRIM(COALESCE(public.banking_pay_workbench_jobs.status, ''))) = 'RUNNING'
             AND public.banking_pay_workbench_jobs.completed_at_utc IS NULL
             AND public.banking_pay_workbench_jobs.failed_at_utc IS NULL
             AND COALESCE(public.banking_pay_workbench_jobs.updated_at_utc, public.banking_pay_workbench_jobs.started_at_utc, public.banking_pay_workbench_jobs.run_at_utc, public.banking_pay_workbench_jobs.created_at_utc) <= v_stale_cutoff
          THEN 'QUEUED'
        ELSE public.banking_pay_workbench_jobs.status
      END,
      priority = CASE
        WHEN UPPER(BTRIM(COALESCE(public.banking_pay_workbench_jobs.status, ''))) = 'RUNNING'
             AND COALESCE(public.banking_pay_workbench_jobs.updated_at_utc, public.banking_pay_workbench_jobs.started_at_utc, public.banking_pay_workbench_jobs.run_at_utc, public.banking_pay_workbench_jobs.created_at_utc) > v_stale_cutoff
          THEN public.banking_pay_workbench_jobs.priority
        ELSE LEAST(public.banking_pay_workbench_jobs.priority, EXCLUDED.priority)
      END,
      run_at_utc = CASE
        WHEN UPPER(BTRIM(COALESCE(public.banking_pay_workbench_jobs.status, ''))) = 'RUNNING'
             AND public.banking_pay_workbench_jobs.completed_at_utc IS NULL
             AND public.banking_pay_workbench_jobs.failed_at_utc IS NULL
             AND COALESCE(public.banking_pay_workbench_jobs.updated_at_utc, public.banking_pay_workbench_jobs.started_at_utc, public.banking_pay_workbench_jobs.run_at_utc, public.banking_pay_workbench_jobs.created_at_utc) <= v_stale_cutoff
             AND COALESCE(public.banking_pay_workbench_jobs.attempt_count, 0) >= GREATEST(COALESCE(public.banking_pay_workbench_jobs.max_attempts, 8), 1)
          THEN public.banking_pay_workbench_jobs.run_at_utc
        WHEN UPPER(BTRIM(COALESCE(public.banking_pay_workbench_jobs.status, ''))) = 'RUNNING'
             AND public.banking_pay_workbench_jobs.completed_at_utc IS NULL
             AND public.banking_pay_workbench_jobs.failed_at_utc IS NULL
             AND COALESCE(public.banking_pay_workbench_jobs.updated_at_utc, public.banking_pay_workbench_jobs.started_at_utc, public.banking_pay_workbench_jobs.run_at_utc, public.banking_pay_workbench_jobs.created_at_utc) <= v_stale_cutoff
          THEN v_now
        WHEN public.banking_pay_workbench_jobs.status = 'RUNNING' THEN public.banking_pay_workbench_jobs.run_at_utc
        ELSE LEAST(public.banking_pay_workbench_jobs.run_at_utc, EXCLUDED.run_at_utc)
      END,
      started_at_utc = CASE
        WHEN UPPER(BTRIM(COALESCE(public.banking_pay_workbench_jobs.status, ''))) = 'RUNNING'
             AND public.banking_pay_workbench_jobs.completed_at_utc IS NULL
             AND public.banking_pay_workbench_jobs.failed_at_utc IS NULL
             AND COALESCE(public.banking_pay_workbench_jobs.updated_at_utc, public.banking_pay_workbench_jobs.started_at_utc, public.banking_pay_workbench_jobs.run_at_utc, public.banking_pay_workbench_jobs.created_at_utc) <= v_stale_cutoff
             AND COALESCE(public.banking_pay_workbench_jobs.attempt_count, 0) >= GREATEST(COALESCE(public.banking_pay_workbench_jobs.max_attempts, 8), 1)
          THEN public.banking_pay_workbench_jobs.started_at_utc
        WHEN UPPER(BTRIM(COALESCE(public.banking_pay_workbench_jobs.status, ''))) = 'RUNNING'
             AND public.banking_pay_workbench_jobs.completed_at_utc IS NULL
             AND public.banking_pay_workbench_jobs.failed_at_utc IS NULL
             AND COALESCE(public.banking_pay_workbench_jobs.updated_at_utc, public.banking_pay_workbench_jobs.started_at_utc, public.banking_pay_workbench_jobs.run_at_utc, public.banking_pay_workbench_jobs.created_at_utc) <= v_stale_cutoff
          THEN NULL::timestamptz
        ELSE public.banking_pay_workbench_jobs.started_at_utc
      END,
      completed_at_utc = public.banking_pay_workbench_jobs.completed_at_utc,
      failed_at_utc = CASE
        WHEN UPPER(BTRIM(COALESCE(public.banking_pay_workbench_jobs.status, ''))) = 'RUNNING'
             AND public.banking_pay_workbench_jobs.completed_at_utc IS NULL
             AND public.banking_pay_workbench_jobs.failed_at_utc IS NULL
             AND COALESCE(public.banking_pay_workbench_jobs.updated_at_utc, public.banking_pay_workbench_jobs.started_at_utc, public.banking_pay_workbench_jobs.run_at_utc, public.banking_pay_workbench_jobs.created_at_utc) <= v_stale_cutoff
             AND COALESCE(public.banking_pay_workbench_jobs.attempt_count, 0) >= GREATEST(COALESCE(public.banking_pay_workbench_jobs.max_attempts, 8), 1)
          THEN v_now
        WHEN UPPER(BTRIM(COALESCE(public.banking_pay_workbench_jobs.status, ''))) = 'RUNNING'
             AND public.banking_pay_workbench_jobs.completed_at_utc IS NULL
             AND public.banking_pay_workbench_jobs.failed_at_utc IS NULL
             AND COALESCE(public.banking_pay_workbench_jobs.updated_at_utc, public.banking_pay_workbench_jobs.started_at_utc, public.banking_pay_workbench_jobs.run_at_utc, public.banking_pay_workbench_jobs.created_at_utc) <= v_stale_cutoff
          THEN NULL::timestamptz
        ELSE public.banking_pay_workbench_jobs.failed_at_utc
      END,
      last_error_json = CASE
        WHEN UPPER(BTRIM(COALESCE(public.banking_pay_workbench_jobs.status, ''))) = 'RUNNING'
             AND public.banking_pay_workbench_jobs.completed_at_utc IS NULL
             AND public.banking_pay_workbench_jobs.failed_at_utc IS NULL
             AND COALESCE(public.banking_pay_workbench_jobs.updated_at_utc, public.banking_pay_workbench_jobs.started_at_utc, public.banking_pay_workbench_jobs.run_at_utc, public.banking_pay_workbench_jobs.created_at_utc) <= v_stale_cutoff
          THEN jsonb_build_object(
            'code', CASE
              WHEN COALESCE(public.banking_pay_workbench_jobs.attempt_count, 0) >= GREATEST(COALESCE(public.banking_pay_workbench_jobs.max_attempts, 8), 1)
                THEN 'STALE_RUNNING_WORKBENCH_JOB_MAX_ATTEMPTS'
              ELSE 'STALE_RUNNING_WORKBENCH_JOB_RECOVERED'
            END,
            'message', 'Recovered stale running workbench preview job during continuation enqueue.',
            'job_type', v_job_type,
            'session_id', p_session_id::text,
            'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
            'stale_running_seconds', v_stale_running_seconds,
            'recovered_at_utc', v_now
          )
        ELSE public.banking_pay_workbench_jobs.last_error_json
      END,
      payload_json = COALESCE(public.banking_pay_workbench_jobs.payload_json, '{}'::jsonb)
        || v_reuse_patch_json
        || CASE
          WHEN UPPER(BTRIM(COALESCE(public.banking_pay_workbench_jobs.status, ''))) = 'RUNNING'
               AND public.banking_pay_workbench_jobs.completed_at_utc IS NULL
               AND public.banking_pay_workbench_jobs.failed_at_utc IS NULL
               AND COALESCE(public.banking_pay_workbench_jobs.updated_at_utc, public.banking_pay_workbench_jobs.started_at_utc, public.banking_pay_workbench_jobs.run_at_utc, public.banking_pay_workbench_jobs.created_at_utc) <= v_stale_cutoff
            THEN jsonb_build_object(
              'stale_running_recovered_at_utc', v_now::text,
              'stale_running_recovered_by', 'pay_workbench_enqueue_stage_continuation'
            )
          ELSE '{}'::jsonb
        END,
      updated_at_utc = CASE
        WHEN UPPER(BTRIM(COALESCE(public.banking_pay_workbench_jobs.status, ''))) = 'RUNNING'
             AND COALESCE(public.banking_pay_workbench_jobs.updated_at_utc, public.banking_pay_workbench_jobs.started_at_utc, public.banking_pay_workbench_jobs.run_at_utc, public.banking_pay_workbench_jobs.created_at_utc) > v_stale_cutoff
          THEN public.banking_pay_workbench_jobs.updated_at_utc
        ELSE v_now
      END
  RETURNING public.banking_pay_workbench_jobs.id,
            public.banking_pay_workbench_jobs.status,
            (xmax = 0)
  INTO v_job_id,
       v_job_status,
       v_job_was_inserted;

  IF p_candidate_id IS NOT NULL THEN
    UPDATE public.banking_pay_workbench_session_scope AS scope_update
    SET status = v_scope_status,
        pending_job_id = v_job_id,
        dirty = false,
        error_json = NULL::jsonb,
        updated_at_utc = v_now
    WHERE scope_update.session_id = p_session_id
      AND scope_update.candidate_id = p_candidate_id;
  END IF;

  UPDATE public.banking_pay_workbench_sessions AS session_update
  SET progress_state = v_progress_state,
      progress_json = COALESCE(session_update.progress_json, '{}'::jsonb) || jsonb_build_object(
        'last_continuation_enqueue_at_utc', v_now::text,
        'last_continuation_job_id', v_job_id::text,
        'last_continuation_job_type', v_job_type,
        'last_continuation_candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
        'last_continuation_reused', NOT v_job_was_inserted,
        'next_recommended_action', v_next_recommended_action,
        'phase', v_progress_state
      ),
      progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
      progress_updated_at_utc = v_now,
      updated_at_utc = v_now
  WHERE session_update.id = p_session_id;

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    v_job_id::text,
    CASE WHEN v_job_was_inserted THEN 'QUEUED' ELSE 'REUSED' END,
    NULL::jsonb,
    jsonb_build_object(
      'id', v_job_id::text,
      'job_type', v_job_type,
      'status', v_job_status,
      'session_id', p_session_id::text,
      'session_version', COALESCE(v_session_row.version, 0),
      'snapshot_run_id', v_session_row.source_snapshot_run_id::text,
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'dedupe_key', v_dedupe_key,
      'cursor_token', v_cursor_token,
      'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
      'continuation_reason', v_reason,
      'reused', NOT v_job_was_inserted,
      'superseded_stale_running_count', COALESCE(v_superseded_stale_count, 0)
    ),
    'WORKBENCH_STAGE_CONTINUATION_ENQUEUE',
    v_actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', v_job_id::text,
    'job_type', v_job_type,
    'status', v_job_status,
    'session_id', p_session_id::text,
    'session_version', COALESCE(v_session_row.version, 0),
    'snapshot_run_id', v_session_row.source_snapshot_run_id::text,
    'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'dedupe_key', v_dedupe_key,
    'cursor_token', v_cursor_token,
    'has_cursor', v_cursor_json IS NOT NULL,
    'limit', v_limit,
    'line_limit', v_limit,
    'line_work_action', v_line_work_action,
    'next_recommended_action', v_next_recommended_action,
    'reused', NOT v_job_was_inserted,
    'created', v_job_was_inserted,
    'superseded_stale_running_count', COALESCE(v_superseded_stale_count, 0),
    'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
    'continuation_reason', v_reason
  );
END;
$function$;




CREATE OR REPLACE FUNCTION public._pay_batch_status_display_label(
  p_status text,
  p_pending_count integer DEFAULT NULL::integer,
  p_unknown_count integer DEFAULT NULL::integer
)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE
PARALLEL SAFE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_status text := NULLIF(REPLACE(REPLACE(UPPER(BTRIM(COALESCE(p_status, ''))), '-', '_'), ' ', '_'), '');
  v_pending_count integer := GREATEST(COALESCE(p_pending_count, 0), 0);
  v_unknown_count integer := GREATEST(COALESCE(p_unknown_count, 0), 0);
BEGIN
  IF v_status IS NULL THEN
    RETURN 'Unknown';
  END IF;

  IF v_status = 'FAILED' THEN
    RETURN 'Completed with failed payments';
  END IF;

  IF v_status IN ('SETTLED', 'COMPLETED', 'COMPLETE', 'COMMITTED') THEN
    RETURN 'Completed';
  END IF;

  IF v_status = 'WAITING_BANK_CONFIRM' THEN
    RETURN 'Waiting for bank confirmation';
  END IF;

  IF v_status = 'PARTIAL' THEN
    RETURN 'Partially completed';
  END IF;

  IF v_status IN ('DRAFT', 'DRAFT_CREATED') THEN
    RETURN 'Draft';
  END IF;

  IF v_status = 'READY' THEN
    RETURN 'Ready';
  END IF;

  IF v_status = 'AWAITING_AUTHORISATION' THEN
    RETURN 'Awaiting authorisation';
  END IF;

  IF v_status = 'AUTHORISED_FOR_PAYMENT' THEN
    RETURN 'Authorised for payment';
  END IF;

  IF v_status = 'SCHEDULED' THEN
    RETURN 'Scheduled';
  END IF;

  IF v_status = 'EXECUTING' THEN
    RETURN 'Executing';
  END IF;

  IF v_status = 'BLOCKED_FUNDS' THEN
    RETURN 'Blocked funds';
  END IF;

  IF v_status = 'CANCELLED' THEN
    RETURN 'Cancelled';
  END IF;

  IF v_status = 'UNPAID' THEN
    RETURN 'Unpaid';
  END IF;

  IF v_status = 'PAID' THEN
    RETURN 'Paid';
  END IF;

  IF v_pending_count > 0 OR v_unknown_count > 0 THEN
    RETURN INITCAP(REPLACE(v_status, '_', ' '));
  END IF;

  RETURN INITCAP(REPLACE(v_status, '_', ' '));
END;
$function$;


CREATE OR REPLACE FUNCTION public._pay_bank_transfer_status_display_label(
  p_status text,
  p_rail_state text,
  p_cash_state text DEFAULT NULL::text
)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE
PARALLEL SAFE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_status text := NULLIF(REPLACE(REPLACE(UPPER(BTRIM(COALESCE(p_status, ''))), '-', '_'), ' ', '_'), '');
  v_rail_state text := NULLIF(REPLACE(REPLACE(UPPER(BTRIM(COALESCE(p_rail_state, ''))), '-', '_'), ' ', '_'), '');
  v_cash_state text := NULLIF(REPLACE(REPLACE(UPPER(BTRIM(COALESCE(p_cash_state, ''))), '-', '_'), ' ', '_'), '');
  v_primary_state text := COALESCE(v_status, v_rail_state);
BEGIN
  IF v_cash_state = 'FINAL_PAID' THEN
    RETURN 'Payment completed successfully';
  END IF;

  IF v_cash_state = 'TERMINAL_NO_MONEY' THEN
    IF v_primary_state IN ('CANCELLED', 'CANCELED', 'CANCELLED_BEFORE_RELEASE', 'CANCELED_BEFORE_RELEASE') THEN
      RETURN 'Payment cancelled';
    END IF;

    IF v_primary_state IN ('RETURNED', 'REVERTED', 'REVERSED') THEN
      RETURN 'Payment returned';
    END IF;

    IF v_primary_state IN ('REJECTED', 'DECLINED') THEN
      RETURN 'Payment rejected';
    END IF;

    RETURN 'Payment failed';
  END IF;

  IF v_cash_state = 'PENDING_NON_FINAL' THEN
    RETURN 'Submitted / pending bank confirmation';
  END IF;

  IF v_cash_state = 'UNKNOWN' THEN
    RETURN 'Check required';
  END IF;

  IF v_primary_state IS NULL THEN
    RETURN 'Check required';
  END IF;

  IF v_primary_state IN ('COMPLETED', 'COMPLETE', 'PAID', 'SETTLED', 'SUCCESS', 'SUCCESSFUL', 'SUCCEEDED', 'DONE') THEN
    RETURN 'Payment completed successfully';
  END IF;

  IF v_primary_state IN ('PENDING', 'SUBMITTED', 'SENT', 'PROCESSING', 'QUEUED', 'ACCEPTED', 'CREATED', 'SCHEDULED', 'IN_PROGRESS', 'WAITING', 'WAITING_BANK_CONFIRM', 'SUBMITTED_NOT_COMMITTED') THEN
    RETURN 'Submitted / pending bank confirmation';
  END IF;

  IF v_primary_state IN ('FAILED', 'FAILURE', 'ERROR') THEN
    RETURN 'Payment failed';
  END IF;

  IF v_primary_state IN ('REJECTED', 'DECLINED') THEN
    RETURN 'Payment rejected';
  END IF;

  IF v_primary_state IN ('CANCELLED', 'CANCELED', 'CANCELLED_BEFORE_RELEASE', 'CANCELED_BEFORE_RELEASE') THEN
    RETURN 'Payment cancelled';
  END IF;

  IF v_primary_state IN ('RETURNED', 'REVERTED', 'REVERSED') THEN
    RETURN 'Payment returned';
  END IF;

  IF v_primary_state IN ('BLOCKED_FUNDS', 'INSUFFICIENT_FUNDS', 'FUNDS_REQUIRED') THEN
    RETURN 'Payment blocked - funds required';
  END IF;

  IF v_primary_state IN ('UNMATCHED', 'UNMATCHED_REVIEW_REQUIRED', 'REVIEW_REQUIRED', 'CHECK_REQUIRED', 'UNKNOWN', 'UNCLEAR') THEN
    RETURN 'Check required';
  END IF;

  RETURN 'Check required';
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_workbench_preview_section_from_line_json(p_line_json jsonb DEFAULT '{}'::jsonb)
RETURNS text
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_line_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_line_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_line_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_source_kind text := UPPER(NULLIF(BTRIM(COALESCE(v_line_json->>'source_kind', v_line_json->>'source_type', '')), ''));
  v_raw_section text := LOWER(NULLIF(BTRIM(COALESCE(v_line_json->>'target_section', v_line_json->>'section', '')), ''));
  v_presentation_section text := UPPER(NULLIF(BTRIM(COALESCE(v_line_json->>'presentation_section', '')), ''));
  v_readiness_state text := UPPER(NULLIF(BTRIM(COALESCE(v_line_json->>'readiness_state', '')), ''));
  v_line_type text := UPPER(NULLIF(BTRIM(COALESCE(v_line_json->>'line_type', v_line_json->>'case_type', '')), ''));
  v_blocked_reason_count integer := 0;
  v_draftable boolean := false;
  v_is_ready_for_draft boolean := false;
BEGIN
  IF v_source_kind IN (
    'TIMESHEET_SNAPSHOT',
    'TIMESHEET_SNAPSHOT_EVIDENCE',
    'RAW_TIMESHEET_SNAPSHOT',
    'INTERNAL_ONLY',
    'NO_DELTA',
    'EXCLUDED'
  ) THEN
    RETURN 'internal_only';
  END IF;

  IF v_raw_section IN ('canonical_preview_lines', 'ready_to_pay', 'ready_preview_lines', 'preview_rows') THEN
    RETURN 'canonical_preview_lines';
  END IF;

  IF v_raw_section IN ('cases_resolutions', 'case_resolution_states', 'case_resolutions', 'cases', 'resolutions') THEN
    RETURN 'cases_resolutions';
  END IF;

  IF v_raw_section IN ('blocked_for_pay', 'blocked_preview_lines', 'blocked_items', 'blocked_now') THEN
    RETURN 'blocked_for_pay';
  END IF;

  IF v_raw_section IN ('internal_only', 'hidden', 'excluded', 'no_delta') THEN
    RETURN 'internal_only';
  END IF;

  IF v_presentation_section IN ('READY_TO_PAY', 'READY', 'PAYABLE_NOW') THEN
    RETURN 'canonical_preview_lines';
  END IF;

  IF v_presentation_section IN ('CASES_RESOLUTIONS', 'CASE_RESOLUTION', 'CASE_RESOLUTIONS', 'RESOLUTION_REQUIRED')
     OR v_readiness_state IN ('CASES_RESOLUTIONS', 'CASE_RESOLUTION', 'CASE_RESOLUTIONS', 'RESOLUTION_REQUIRED') THEN
    RETURN 'cases_resolutions';
  END IF;

  IF v_presentation_section IN ('BLOCKED_FOR_PAY', 'BLOCKED', 'DO_NOT_PAY')
     OR v_readiness_state IN ('BLOCKED_FOR_PAY', 'BLOCKED', 'DO_NOT_PAY') THEN
    RETURN 'blocked_for_pay';
  END IF;

  IF jsonb_typeof(v_line_json->'blocked_reason_codes') = 'array' THEN
    v_blocked_reason_count := jsonb_array_length(v_line_json->'blocked_reason_codes');
  END IF;

  IF LOWER(BTRIM(COALESCE(v_line_json->>'case_is_blocked', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
     OR COALESCE(v_blocked_reason_count, 0) > 0 THEN
    RETURN 'blocked_for_pay';
  END IF;

  v_draftable := LOWER(BTRIM(COALESCE(v_line_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_is_ready_for_draft := LOWER(BTRIM(COALESCE(v_line_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF COALESCE(v_draftable, false)
     OR (COALESCE(v_is_ready_for_draft, false) AND v_line_type IS NOT NULL) THEN
    RETURN 'canonical_preview_lines';
  END IF;

  RETURN 'internal_only';
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_workbench_seed_candidate_preview_line_source(p_session_id uuid, p_candidate_id uuid, p_context_json jsonb DEFAULT '{}'::jsonb, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_context_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_context_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_context_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_classifier_context_json jsonb := '{}'::jsonb;
  v_classifier_result jsonb := '{}'::jsonb;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_cursor_line_ordinal bigint := 0;
  v_seeded_count integer := 0;
  v_error_count integer := 0;
  v_new_pending_count integer := 0;
  v_new_error_count integer := 0;
  v_source_row_count integer := 0;
  v_materialisable_count integer := 0;
  v_contract_rejected_count integer := 0;
  v_hidden_recovery_template_count integer := 0;
  v_finance_case_source_count integer := 0;
  v_next_cursor jsonb := NULL::jsonb;
  v_has_more boolean := false;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SEED_PREVIEW_LINE_SOURCE_SESSION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_SEED_PREVIEW_LINE_SOURCE_SESSION_ID_REQUIRED')::text;
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SEED_PREVIEW_LINE_SOURCE_CANDIDATE_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_SEED_PREVIEW_LINE_SOURCE_CANDIDATE_ID_REQUIRED')::text;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SEED_PREVIEW_LINE_SOURCE_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_SEED_PREVIEW_LINE_SOURCE_SESSION_NOT_FOUND',
              'session_id', p_session_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SEED_PREVIEW_LINE_SOURCE_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_SEED_PREVIEW_LINE_SOURCE_SESSION_NOT_OPEN',
              'session_id', p_session_id::text,
              'status', v_session_row.status
            )::text;
  END IF;

  PERFORM 1
  FROM public.banking_pay_workbench_session_scope AS scope_check
  WHERE scope_check.session_id = p_session_id
    AND scope_check.candidate_id = p_candidate_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SEED_PREVIEW_LINE_SOURCE_CANDIDATE_NOT_IN_SCOPE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_SEED_PREVIEW_LINE_SOURCE_CANDIDATE_NOT_IN_SCOPE',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text
            )::text;
  END IF;

  IF p_cursor_json IS NOT NULL AND jsonb_typeof(p_cursor_json) = 'object' THEN
    BEGIN
      v_cursor_line_ordinal := COALESCE(
        NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_line_ordinal', '')), '')::bigint,
        NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_ordinal', '')), '')::bigint,
        NULLIF(BTRIM(COALESCE(p_cursor_json->>'cursor_ordinal', '')), '')::bigint,
        0
      );
    EXCEPTION WHEN OTHERS THEN
      v_cursor_line_ordinal := 0;
    END;
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_context_json->>'pay_date', '')), '') IS NULL THEN
    v_context_json := public.pay_preview_build_context(
      p_pay_date => v_session_row.pay_date,
      p_week_ending_cutoff => v_session_row.week_ending_cutoff,
      p_actor_user_id => v_session_row.actor_user_id,
      p_candidate_id => p_candidate_id,
      p_client_id => NULL::uuid,
      p_preview_decisions_json => COALESCE(v_session_row.filters_json, '{}'::jsonb) || COALESCE(v_context_json, '{}'::jsonb)
    );
  END IF;

  v_classifier_context_json := v_context_json
    - 'workbench_session_id'
    - 'workbenchSessionId'
    - 'pay_workbench_session_id'
    - 'session_id'
    - 'workbench'
    - 'line_work'
    - 'line_materialise_cursor'
    - 'line_work_cursor';

  v_classifier_result := public.pay_preview_candidate_build_canonical_lines(
    p_context_json => v_classifier_context_json,
    p_candidate_id => p_candidate_id
  );

  IF to_regclass('pg_temp.canonical_preview_lines') IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SEED_PREVIEW_LINE_SOURCE_CANONICAL_LINES_MISSING'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_SEED_PREVIEW_LINE_SOURCE_CANONICAL_LINES_MISSING',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text
            )::text;
  END IF;

  IF to_regclass('pg_temp.finance_case_lines') IS NOT NULL THEN
    SELECT COUNT(*)::integer
    INTO v_finance_case_source_count
    FROM pg_temp.finance_case_lines AS finance_source_rows;
  END IF;

  IF to_regclass('pg_temp.hidden_recovery_template_lines') IS NOT NULL THEN
    SELECT COUNT(*)::integer
    INTO v_hidden_recovery_template_count
    FROM pg_temp.hidden_recovery_template_lines AS hidden_source_rows;
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_preview_line_seed_source;
  CREATE TEMPORARY TABLE pg_temp._tmp_pay_wb_preview_line_seed_source ON COMMIT DROP AS
  WITH base_rows_raw AS (
    SELECT
      ROW_NUMBER() OVER (
        ORDER BY
          public.pay_workbench_preview_section_from_line_json(canonical_rows.line_json),
          COALESCE(canonical_rows.line_json->>'preview_row_id', canonical_rows.line_json->>'line_id', canonical_rows.line_json->>'case_key', md5(canonical_rows.line_json::text))
      )::bigint AS base_ordinal,
      canonical_rows.candidate_id,
      canonical_rows.line_json,
      canonical_rows.pay_channel,
      canonical_rows.paye_treatment,
      canonical_rows.amount_ex_vat,
      canonical_rows.is_excluded_from_allocation,
      public.pay_workbench_preview_section_from_line_json(canonical_rows.line_json) AS target_section,
      UPPER(NULLIF(BTRIM(COALESCE(canonical_rows.line_json->>'line_type', canonical_rows.line_json->>'case_type', '')), '')) AS line_type,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(canonical_rows.line_json->>'real_business_timesheet_id', canonical_rows.line_json#>>'{economic_key,timesheet_id}', canonical_rows.line_json->>'timesheet_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(canonical_rows.line_json->>'real_business_timesheet_id', canonical_rows.line_json#>>'{economic_key,timesheet_id}', canonical_rows.line_json->>'timesheet_id', '')), '')::uuid
        ELSE NULL::uuid
      END AS requested_timesheet_id,
      NULLIF(BTRIM(COALESCE(canonical_rows.line_json->>'preview_row_id', canonical_rows.line_json->>'line_id', canonical_rows.line_json->>'case_key', md5(canonical_rows.line_json::text))), '') AS parent_line_key
    FROM pg_temp.canonical_preview_lines AS canonical_rows
    WHERE canonical_rows.candidate_id = p_candidate_id
  ), base_requested_timesheets AS (
    SELECT DISTINCT
      base_rows_raw.requested_timesheet_id
    FROM base_rows_raw
    WHERE base_rows_raw.requested_timesheet_id IS NOT NULL
  ), base_rotation_scope AS (
    SELECT
      rotation_scope_rows.requested_timesheet_id,
      rotation_scope_rows.canonical_timesheet_id,
      rotation_scope_rows.family_is_current,
      rotation_scope_rows.family_version,
      rotation_scope_rows.family_timesheet_id
    FROM public._pay_timesheet_rotation_scope(
      (
        SELECT COALESCE(
          array_agg(base_requested_timesheets.requested_timesheet_id ORDER BY base_requested_timesheets.requested_timesheet_id),
          ARRAY[]::uuid[]
        )
        FROM base_requested_timesheets
      )
    ) AS rotation_scope_rows
  ), base_requested_canonical AS (
    SELECT DISTINCT ON (base_rotation_scope.requested_timesheet_id)
      base_rotation_scope.requested_timesheet_id,
      COALESCE(base_rotation_scope.canonical_timesheet_id, base_rotation_scope.requested_timesheet_id) AS canonical_timesheet_id
    FROM base_rotation_scope
    WHERE base_rotation_scope.requested_timesheet_id IS NOT NULL
    ORDER BY
      base_rotation_scope.requested_timesheet_id,
      base_rotation_scope.family_is_current DESC NULLS LAST,
      base_rotation_scope.family_version DESC NULLS LAST,
      base_rotation_scope.family_timesheet_id
  ), base_rows AS (
    SELECT
      base_rows_raw.base_ordinal,
      base_rows_raw.candidate_id,
      jsonb_strip_nulls(
        base_rows_raw.line_json
        || jsonb_build_object(
          'timesheet_id', CASE WHEN COALESCE(base_requested_canonical.canonical_timesheet_id, base_rows_raw.requested_timesheet_id) IS NULL THEN NULL ELSE COALESCE(base_requested_canonical.canonical_timesheet_id, base_rows_raw.requested_timesheet_id)::text END,
          'real_business_timesheet_id', CASE WHEN COALESCE(base_requested_canonical.canonical_timesheet_id, base_rows_raw.requested_timesheet_id) IS NULL THEN NULL ELSE COALESCE(base_requested_canonical.canonical_timesheet_id, base_rows_raw.requested_timesheet_id)::text END
        )
        || CASE
          WHEN base_rows_raw.requested_timesheet_id IS NOT NULL
           AND COALESCE(base_requested_canonical.canonical_timesheet_id, base_rows_raw.requested_timesheet_id) IS DISTINCT FROM base_rows_raw.requested_timesheet_id
          THEN jsonb_build_object('rotation_requested_timesheet_id', base_rows_raw.requested_timesheet_id::text)
          ELSE '{}'::jsonb
        END
      ) AS line_json,
      base_rows_raw.pay_channel,
      base_rows_raw.paye_treatment,
      base_rows_raw.amount_ex_vat,
      base_rows_raw.is_excluded_from_allocation,
      base_rows_raw.target_section,
      base_rows_raw.line_type,
      COALESCE(base_requested_canonical.canonical_timesheet_id, base_rows_raw.requested_timesheet_id) AS timesheet_id,
      base_rows_raw.parent_line_key
    FROM base_rows_raw
    LEFT JOIN base_requested_canonical
      ON base_requested_canonical.requested_timesheet_id = base_rows_raw.requested_timesheet_id
  ), timesheet_segment_rows AS (
    SELECT
      base_rows.base_ordinal,
      base_rows.candidate_id,
      base_rows.timesheet_id,
      base_rows.target_section,
      base_rows.parent_line_key,
      ('segment:' || segment_rows.segment_ord::text) AS split_suffix,
      segment_rows.segment_ord::bigint AS split_ordinal,
      'SEGMENT_DELTA'::text AS item_type,
      NULL::text AS key_type_hint,
      NULL::text AS key_value_hint,
      segment_rows.segment_json,
      jsonb_strip_nulls(
        (
          base_rows.line_json
          - 'case_components'
          - 'component_key_type'
          - 'component_key_value'
          - 'frozen_component_key_type'
          - 'frozen_component_key_value'
          - 'frozen_component_classification'
          - 'frozen_component_snapshot_json'
          - 'source_basis_json'
          - 'frozen_source_basis_json'
        )
        || jsonb_build_object(
          'source_kind', 'VALID_PREVIEW_LINE',
          'preview_row_id', base_rows.parent_line_key || ':segment:' || segment_rows.segment_ord::text,
          'line_id', base_rows.parent_line_key || ':segment:' || segment_rows.segment_ord::text,
          'line_key', base_rows.parent_line_key || ':segment:' || segment_rows.segment_ord::text,
          'row_key', base_rows.parent_line_key || ':segment:' || segment_rows.segment_ord::text
        )
        || jsonb_build_object(
          'presentation_role', 'CHILD',
          'presentation_parent_line_id', base_rows.parent_line_key,
          'amount_ex_vat', segment_rows.segment_amount_ex_vat,
          'amount_display', segment_rows.segment_amount_ex_vat,
          'section_amount_ex_vat', segment_rows.segment_amount_ex_vat,
          'section_amount_display', segment_rows.segment_amount_ex_vat
        )
        || jsonb_build_object(
          'segment_rows', jsonb_build_array(segment_rows.segment_json),
          'section_segment_rows', jsonb_build_array(segment_rows.segment_json),
          'segment_count', 1,
          'section_segment_count', 1,
          'section_non_segment_amount_ex_vat', 0,
          'segment_id', NULLIF(BTRIM(COALESCE(segment_rows.segment_json->>'segment_id', '')), '')
        )
        || jsonb_build_object(
          'segment_key', NULLIF(BTRIM(COALESCE(segment_rows.segment_json->>'segment_key', '')), ''),
          'segment_stable_key', NULLIF(BTRIM(COALESCE(segment_rows.segment_json->>'segment_stable_key', '')), ''),
          'work_date', NULLIF(BTRIM(COALESCE(segment_rows.segment_json->>'work_date', segment_rows.segment_json->>'date', '')), ''),
          'date', NULLIF(BTRIM(COALESCE(segment_rows.segment_json->>'date', segment_rows.segment_json->>'work_date', '')), ''),
          'source_basis_json', segment_rows.segment_json
        )
        || jsonb_build_object(
          'case_components', segment_case_components.non_fixed_case_components_json
        )
      ) AS seed_line_json
    FROM base_rows
    CROSS JOIN LATERAL (
      SELECT
        segment_element.value AS segment_json,
        segment_element.ordinality::integer AS segment_ord,
        ROUND(COALESCE(
          CASE WHEN COALESCE(segment_element.value->>'pay_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (segment_element.value->>'pay_amount_ex_vat')::numeric ELSE NULL::numeric END,
          CASE WHEN COALESCE(segment_element.value->>'effective_delta_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (segment_element.value->>'effective_delta_ex_vat')::numeric ELSE NULL::numeric END,
          CASE WHEN COALESCE(segment_element.value->>'delta_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (segment_element.value->>'delta_pay_ex_vat')::numeric ELSE NULL::numeric END,
          CASE WHEN COALESCE(segment_element.value->>'raw_delta_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (segment_element.value->>'raw_delta_ex_vat')::numeric ELSE NULL::numeric END,
          0::numeric
        ), 2) AS segment_amount_ex_vat
      FROM jsonb_array_elements(COALESCE(base_rows.line_json->'section_segment_rows', base_rows.line_json->'segment_rows', '[]'::jsonb)) WITH ORDINALITY AS segment_element(value, ordinality)
      WHERE segment_element.value IS NOT NULL
        AND jsonb_typeof(segment_element.value) = 'object'
    ) AS segment_rows
    CROSS JOIN LATERAL (
      SELECT COALESCE(
        jsonb_agg(component_element.value ORDER BY component_element.ordinality),
        '[]'::jsonb
      ) AS non_fixed_case_components_json
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(base_rows.line_json->'case_components') = 'array' THEN base_rows.line_json->'case_components'
          ELSE '[]'::jsonb
        END
      ) WITH ORDINALITY AS component_element(value, ordinality)
      WHERE NOT (
        component_element.value IS NOT NULL
        AND jsonb_typeof(component_element.value) = 'object'
        AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
        AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
        AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
      )
    ) AS segment_case_components
    WHERE base_rows.target_section = 'canonical_preview_lines'
      AND base_rows.line_type = 'TIMESHEET_PAYMENT'
      AND LOWER(BTRIM(COALESCE(base_rows.line_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND ROUND(COALESCE(segment_rows.segment_amount_ex_vat, 0), 2) <> 0
  ), timesheet_non_segment_rows AS (
    SELECT
      base_rows.base_ordinal,
      base_rows.candidate_id,
      base_rows.timesheet_id,
      base_rows.target_section,
      base_rows.parent_line_key,
      'non_segment:total'::text AS split_suffix,
      900000::bigint AS split_ordinal,
      'SEGMENT_DELTA'::text AS item_type,
      'TS_TOTAL'::text AS key_type_hint,
      'TOTAL'::text AS key_value_hint,
      '{}'::jsonb AS segment_json,
      jsonb_strip_nulls(
        (
          base_rows.line_json
          - 'case_components'
          - 'component_key_type'
          - 'component_key_value'
          - 'frozen_component_key_type'
          - 'frozen_component_key_value'
          - 'frozen_component_classification'
          - 'frozen_component_snapshot_json'
          - 'source_basis_json'
          - 'frozen_source_basis_json'
        )
        || jsonb_build_object(
          'source_kind', 'VALID_PREVIEW_LINE',
          'preview_row_id', base_rows.parent_line_key || ':non_segment:total',
          'line_id', base_rows.parent_line_key || ':non_segment:total',
          'line_key', base_rows.parent_line_key || ':non_segment:total',
          'row_key', base_rows.parent_line_key || ':non_segment:total'
        )
        || jsonb_build_object(
          'presentation_role', 'CHILD',
          'presentation_parent_line_id', base_rows.parent_line_key,
          'amount_ex_vat', non_segment_amounts.non_segment_amount_ex_vat,
          'amount_display', non_segment_amounts.non_segment_amount_ex_vat,
          'section_amount_ex_vat', non_segment_amounts.non_segment_amount_ex_vat,
          'section_amount_display', non_segment_amounts.non_segment_amount_ex_vat
        )
        || jsonb_build_object(
          'segment_rows', '[]'::jsonb,
          'section_segment_rows', '[]'::jsonb,
          'segment_count', 0,
          'section_segment_count', 0,
          'section_non_segment_amount_ex_vat', non_segment_amounts.non_segment_amount_ex_vat,
          'source_basis_json', jsonb_build_object('component_key_type', 'TS_TOTAL', 'component_key_value', 'TOTAL')
        )
        || jsonb_build_object(
          'case_components', non_segment_case_components.non_fixed_case_components_json
        )
      ) AS seed_line_json
    FROM base_rows
    CROSS JOIN LATERAL (
      SELECT
        ROUND(COALESCE(
          CASE WHEN COALESCE(base_rows.line_json->>'section_non_segment_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (base_rows.line_json->>'section_non_segment_amount_ex_vat')::numeric ELSE NULL::numeric END,
          CASE WHEN jsonb_array_length(COALESCE(base_rows.line_json->'section_segment_rows', base_rows.line_json->'segment_rows', '[]'::jsonb)) = 0
                 AND COALESCE(base_rows.line_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
               THEN (base_rows.line_json->>'amount_ex_vat')::numeric ELSE NULL::numeric END,
          0::numeric
        ), 2) AS gross_non_segment_amount_ex_vat
    ) AS gross_non_segment_amounts
    CROSS JOIN LATERAL (
      SELECT
        ROUND(COALESCE(SUM(
          CASE
            WHEN COALESCE(base_rows.line_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND (base_rows.line_json->>'amount_ex_vat')::numeric < 0
            THEN -ABS(ROUND(COALESCE(
              CASE WHEN COALESCE(component_element.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'preview_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN COALESCE(component_element.value->>'allocated_source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'allocated_source_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN COALESCE(component_element.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'target_pay_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN COALESCE(component_element.value->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'remaining_source_amount')::numeric ELSE NULL::numeric END,
              0::numeric
            ), 2))
            ELSE ABS(ROUND(COALESCE(
              CASE WHEN COALESCE(component_element.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'preview_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN COALESCE(component_element.value->>'allocated_source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'allocated_source_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN COALESCE(component_element.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'target_pay_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN COALESCE(component_element.value->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'remaining_source_amount')::numeric ELSE NULL::numeric END,
              0::numeric
            ), 2))
          END
        ), 0::numeric), 2) AS explicit_reimbursement_amount_ex_vat
      FROM jsonb_array_elements(COALESCE(base_rows.line_json->'case_components', '[]'::jsonb)) AS component_element(value)
      WHERE base_rows.line_type = 'TIMESHEET_PAYMENT'
        AND component_element.value IS NOT NULL
        AND jsonb_typeof(component_element.value) = 'object'
        AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
        AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
        AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
    ) AS explicit_component_amounts
    CROSS JOIN LATERAL (
      SELECT ROUND(
        COALESCE(gross_non_segment_amounts.gross_non_segment_amount_ex_vat, 0)
        - COALESCE(explicit_component_amounts.explicit_reimbursement_amount_ex_vat, 0),
        2
      ) AS non_segment_amount_ex_vat
    ) AS non_segment_amounts
    CROSS JOIN LATERAL (
      SELECT COALESCE(
        jsonb_agg(component_element.value ORDER BY component_element.ordinality),
        '[]'::jsonb
      ) AS non_fixed_case_components_json
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(base_rows.line_json->'case_components') = 'array' THEN base_rows.line_json->'case_components'
          ELSE '[]'::jsonb
        END
      ) WITH ORDINALITY AS component_element(value, ordinality)
      WHERE NOT (
        component_element.value IS NOT NULL
        AND jsonb_typeof(component_element.value) = 'object'
        AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
        AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
        AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
      )
    ) AS non_segment_case_components
    WHERE base_rows.target_section = 'canonical_preview_lines'
      AND base_rows.line_type = 'TIMESHEET_PAYMENT'
      AND LOWER(BTRIM(COALESCE(base_rows.line_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND ROUND(COALESCE(non_segment_amounts.non_segment_amount_ex_vat, 0), 2) <> 0
  ), finance_component_rows AS (
    SELECT
      base_rows.base_ordinal,
      base_rows.candidate_id,
      component_timesheet.timesheet_id,
      base_rows.target_section,
      base_rows.parent_line_key,
      ('component:' || COALESCE(NULLIF(BTRIM(component_rows.component_json->>'finance_component_id'), ''), component_rows.component_ord::text)) AS split_suffix,
      component_rows.component_ord::bigint AS split_ordinal,
      CASE
        WHEN UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), '')) IN ('TS_DAY', 'TS_TOTAL') THEN 'SEGMENT_DELTA'
        WHEN UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), '')) = 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
        WHEN UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), '')) = 'EXPENSE_CODE'
         AND UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_value', '')), '')) = 'MILEAGE' THEN 'MILEAGE_DELTA'
        WHEN UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE') THEN 'EXPENSE_DELTA'
        ELSE base_rows.line_type
      END AS item_type,
      UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), '')) AS key_type_hint,
      NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_value', '')), '') AS key_value_hint,
      '{}'::jsonb AS segment_json,
      jsonb_strip_nulls(
        (
          base_rows.line_json
          - 'case_components'
          - 'component_key_type'
          - 'component_key_value'
          - 'frozen_component_key_type'
          - 'frozen_component_key_value'
          - 'frozen_component_classification'
          - 'frozen_component_snapshot_json'
          - 'source_basis_json'
          - 'frozen_source_basis_json'
        )
        || jsonb_build_object(
          'source_kind', 'VALID_PREVIEW_LINE',
          'preview_row_id', base_rows.parent_line_key || ':component:' || COALESCE(NULLIF(BTRIM(component_rows.component_json->>'finance_component_id'), ''), component_rows.component_ord::text),
          'line_id', base_rows.parent_line_key || ':component:' || COALESCE(NULLIF(BTRIM(component_rows.component_json->>'finance_component_id'), ''), component_rows.component_ord::text),
          'line_key', base_rows.parent_line_key || ':component:' || COALESCE(NULLIF(BTRIM(component_rows.component_json->>'finance_component_id'), ''), component_rows.component_ord::text),
          'row_key', base_rows.parent_line_key || ':component:' || COALESCE(NULLIF(BTRIM(component_rows.component_json->>'finance_component_id'), ''), component_rows.component_ord::text)
        )
        || jsonb_build_object(
          'presentation_role', 'CHILD',
          'presentation_parent_line_id', base_rows.parent_line_key,
          'finance_component_id', NULLIF(BTRIM(COALESCE(component_rows.component_json->>'finance_component_id', '')), ''),
          'component_key_type', UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), '')),
          'component_key_value', NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_value', '')), '')
        )
        || jsonb_build_object(
          'case_components', jsonb_build_array(component_rows.component_json)
        )
        || jsonb_build_object(
          'amount_ex_vat', component_rows.signed_component_amount_ex_vat,
          'amount_display', component_rows.signed_component_amount_ex_vat,
          'preview_amount_ex_vat', component_rows.signed_component_amount_ex_vat,
          'source_basis_json', COALESCE(component_rows.component_json->'source_basis_json', '{}'::jsonb),
          'frozen_component_snapshot_json', component_rows.component_json
        )
        || jsonb_build_object(
          'frozen_component_key_type', UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), '')),
          'frozen_component_key_value', NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_value', '')), ''),
          'frozen_component_classification', NULLIF(BTRIM(COALESCE(component_rows.component_json->>'classification', '')), ''),
          'frozen_source_basis_json', COALESCE(component_rows.component_json->'source_basis_json', '{}'::jsonb),
          'frozen_source_amount', component_rows.source_amount_ex_vat
        )
        || jsonb_build_object(
          'source_entitlement_amount_ex_vat', component_rows.source_amount_ex_vat,
          'source_reservation_amount_ex_vat', component_rows.source_amount_ex_vat,
          'source_amount_ex_vat', component_rows.source_amount_ex_vat,
          'remaining_source_amount', component_rows.source_amount_ex_vat,
          'target_pay_ex_vat', component_rows.signed_component_amount_ex_vat
        )
        || jsonb_build_object(
          'saved_target_pay_method', NULLIF(BTRIM(COALESCE(component_rows.component_json->>'saved_target_pay_method', '')), ''),
          'saved_resolution_mode', NULLIF(BTRIM(COALESCE(component_rows.component_json->>'saved_resolution_mode', '')), ''),
          'saved_resolution_payload_json', COALESCE(component_rows.component_json->'saved_resolution_payload_json', '{}'::jsonb),
          'saved_resolution_result_json', COALESCE(component_rows.component_json->'saved_resolution_result_json', '{}'::jsonb)
        )
        || jsonb_build_object(
          'resolution_mode', NULLIF(BTRIM(COALESCE(component_rows.component_json->>'saved_resolution_mode', '')), ''),
          'resolution_payload_json', COALESCE(component_rows.component_json->'saved_resolution_payload_json', '{}'::jsonb),
          'resolution_result_json', COALESCE(component_rows.component_json->'saved_resolution_result_json', '{}'::jsonb),
          'frozen_resolution_mode', NULLIF(BTRIM(COALESCE(component_rows.component_json->>'saved_resolution_mode', '')), ''),
          'frozen_resolution_payload_json', COALESCE(component_rows.component_json->'saved_resolution_payload_json', '{}'::jsonb),
          'frozen_resolution_result_json', COALESCE(component_rows.component_json->'saved_resolution_result_json', '{}'::jsonb)
        )
      ) AS seed_line_json
    FROM base_rows
    CROSS JOIN LATERAL (
      SELECT
        component_element.value AS component_json,
        component_element.ordinality::integer AS component_ord,
        ROUND(COALESCE(
          CASE WHEN COALESCE(component_element.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'preview_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'allocated_source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'allocated_source_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'target_pay_ex_vat')::numeric ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'remaining_source_amount')::numeric ELSE NULL::numeric END,
          0::numeric
        ), 2) AS unsigned_component_amount_ex_vat,
        ROUND(COALESCE(
          CASE WHEN COALESCE(component_element.value->>'source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'source_amount')::numeric ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'remaining_source_amount')::numeric ELSE NULL::numeric END,
          0::numeric
        ), 2) AS source_amount_ex_vat,
        CASE
          WHEN COALESCE(base_rows.line_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
           AND (base_rows.line_json->>'amount_ex_vat')::numeric < 0
          THEN -ABS(ROUND(COALESCE(
            CASE WHEN COALESCE(component_element.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'preview_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN COALESCE(component_element.value->>'allocated_source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'allocated_source_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN COALESCE(component_element.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'target_pay_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN COALESCE(component_element.value->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'remaining_source_amount')::numeric ELSE NULL::numeric END,
            0::numeric
          ), 2))
          ELSE ABS(ROUND(COALESCE(
            CASE WHEN COALESCE(component_element.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'preview_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN COALESCE(component_element.value->>'allocated_source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'allocated_source_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN COALESCE(component_element.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'target_pay_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN COALESCE(component_element.value->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'remaining_source_amount')::numeric ELSE NULL::numeric END,
            0::numeric
          ), 2))
        END AS signed_component_amount_ex_vat
      FROM jsonb_array_elements(COALESCE(base_rows.line_json->'case_components', '[]'::jsonb)) WITH ORDINALITY AS component_element(value, ordinality)
      WHERE component_element.value IS NOT NULL
        AND jsonb_typeof(component_element.value) = 'object'
    ) AS component_rows
    CROSS JOIN LATERAL (
      SELECT base_rows.timesheet_id AS timesheet_id
    ) AS component_timesheet
    WHERE base_rows.target_section = 'canonical_preview_lines'
      AND (
        base_rows.line_type <> 'TIMESHEET_PAYMENT'
        OR (
          base_rows.line_type = 'TIMESHEET_PAYMENT'
          AND UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
          AND UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
          AND NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_value', '')), '') IS NOT NULL
        )
      )
      AND LOWER(BTRIM(COALESCE(base_rows.line_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND jsonb_array_length(COALESCE(base_rows.line_json->'case_components', '[]'::jsonb)) > 0
      AND ROUND(COALESCE(component_rows.signed_component_amount_ex_vat, 0), 2) <> 0
  ), parent_display_rows AS (
    SELECT
      base_rows.base_ordinal,
      base_rows.candidate_id,
      base_rows.timesheet_id,
      base_rows.target_section,
      base_rows.parent_line_key,
      'parent'::text AS split_suffix,
      0::bigint AS split_ordinal,
      CASE
        WHEN base_rows.line_type = 'MANUAL_ADJUSTMENT_CARRY_FORWARD' THEN 'MANUAL_CARRY_FORWARD'
        ELSE base_rows.line_type
      END AS item_type,
      CASE
        WHEN base_rows.line_type = 'MANUAL_ADJUSTMENT_CARRY_FORWARD' THEN 'MANUAL_CARRY_FORWARD'
        ELSE UPPER(NULLIF(BTRIM(COALESCE(base_rows.line_json->>'component_key_type', base_rows.line_json->>'frozen_component_key_type', '')), ''))
      END AS key_type_hint,
      CASE
        WHEN base_rows.line_type = 'MANUAL_ADJUSTMENT_CARRY_FORWARD' THEN NULLIF(BTRIM(COALESCE(base_rows.line_json->>'manual_adjustment_carry_forward_id', REPLACE(base_rows.line_json->>'source_ref', 'carry_forward:', ''), base_rows.parent_line_key, '')), '')
        ELSE NULLIF(BTRIM(COALESCE(base_rows.line_json->>'component_key_value', base_rows.line_json->>'frozen_component_key_value', '')), '')
      END AS key_value_hint,
      '{}'::jsonb AS segment_json,
      jsonb_strip_nulls(
        base_rows.line_json
        || jsonb_build_object(
          'source_kind', 'VALID_PREVIEW_LINE',
          'preview_row_id', base_rows.parent_line_key,
          'line_id', base_rows.parent_line_key,
          'line_key', base_rows.parent_line_key,
          'row_key', base_rows.parent_line_key,
          'target_section', base_rows.target_section
        )
        || CASE
          WHEN base_rows.target_section IN ('cases_resolutions', 'blocked_for_pay') THEN jsonb_build_object(
            'draftable', false,
            'is_ready_for_draft', false,
            'is_excluded_from_allocation', true,
            'selection_allowed', false
          )
          ELSE '{}'::jsonb
        END
      ) AS seed_line_json
    FROM base_rows
    WHERE base_rows.target_section IN ('cases_resolutions', 'blocked_for_pay')
       OR (
          base_rows.target_section = 'canonical_preview_lines'
          AND base_rows.line_type = 'MANUAL_ADJUSTMENT_CARRY_FORWARD'
       )
       OR (
          base_rows.target_section = 'canonical_preview_lines'
          AND base_rows.line_type <> 'TIMESHEET_PAYMENT'
          AND base_rows.line_type <> 'MANUAL_ADJUSTMENT_CARRY_FORWARD'
          AND jsonb_array_length(COALESCE(base_rows.line_json->'case_components', '[]'::jsonb)) = 0
       )
  ), unioned_rows AS (
    SELECT * FROM timesheet_segment_rows
    UNION ALL
    SELECT * FROM timesheet_non_segment_rows
    UNION ALL
    SELECT * FROM finance_component_rows
    UNION ALL
    SELECT * FROM parent_display_rows
  ), keyed_rows AS (
    SELECT
      unioned_rows.*,
      public.pay_workbench_preview_line_economic_key(
        p_line_json => unioned_rows.seed_line_json,
        p_timesheet_id => unioned_rows.timesheet_id,
        p_item_type => unioned_rows.item_type,
        p_segment_json => unioned_rows.segment_json,
        p_key_type_hint => unioned_rows.key_type_hint,
        p_key_value_hint => unioned_rows.key_value_hint
      ) AS economic_key_json
    FROM unioned_rows
  ), contracted_rows AS (
    SELECT
      keyed_rows.*,
      public.pay_workbench_preview_line_contract_ok(
        p_line_json => keyed_rows.seed_line_json,
        p_economic_key_json => keyed_rows.economic_key_json,
        p_target_section => keyed_rows.target_section
      ) AS contract_json
    FROM keyed_rows
  ), numbered_rows AS (
    SELECT
      ROW_NUMBER() OVER (
        ORDER BY contracted_rows.base_ordinal, contracted_rows.split_ordinal, contracted_rows.parent_line_key, contracted_rows.split_suffix
      )::bigint AS line_ordinal,
      contracted_rows.*
    FROM contracted_rows
    WHERE LOWER(BTRIM(COALESCE(contracted_rows.contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
  )
  SELECT numbered_rows.*
  FROM numbered_rows;

  SELECT COUNT(*)::integer
  INTO v_source_row_count
  FROM pg_temp.canonical_preview_lines AS source_count_rows
  WHERE source_count_rows.candidate_id = p_candidate_id;

  SELECT COUNT(*)::integer
  INTO v_materialisable_count
  FROM pg_temp._tmp_pay_wb_preview_line_seed_source AS materialisable_rows;

  v_contract_rejected_count := GREATEST(COALESCE(v_source_row_count, 0) - COALESCE(v_materialisable_count, 0), 0);

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_preview_line_seed_page;
  CREATE TEMPORARY TABLE pg_temp._tmp_pay_wb_preview_line_seed_page ON COMMIT DROP AS
  SELECT seed_rows.*
  FROM pg_temp._tmp_pay_wb_preview_line_seed_source AS seed_rows
  WHERE seed_rows.line_ordinal > COALESCE(v_cursor_line_ordinal, 0)
  ORDER BY seed_rows.line_ordinal, seed_rows.parent_line_key, seed_rows.split_suffix
  LIMIT (v_limit + 1);

  IF (SELECT COUNT(*) FROM pg_temp._tmp_pay_wb_preview_line_seed_page AS page_count_rows) > v_limit THEN
    SELECT jsonb_build_object('last_line_ordinal', cursor_row.line_ordinal)
    INTO v_next_cursor
    FROM (
      SELECT page_rows.line_ordinal
      FROM pg_temp._tmp_pay_wb_preview_line_seed_page AS page_rows
      ORDER BY page_rows.line_ordinal, page_rows.parent_line_key, page_rows.split_suffix
      LIMIT v_limit
    ) AS cursor_row
    ORDER BY cursor_row.line_ordinal DESC
    LIMIT 1;
    v_has_more := true;
  ELSE
    v_next_cursor := NULL::jsonb;
    v_has_more := false;
  END IF;

  WITH selected_rows AS (
    SELECT page_rows.*
    FROM pg_temp._tmp_pay_wb_preview_line_seed_page AS page_rows
    ORDER BY page_rows.line_ordinal, page_rows.parent_line_key, page_rows.split_suffix
    LIMIT v_limit
  ), existing_rows AS (
    SELECT
      selected_rows.timesheet_id,
      selected_rows.parent_line_key || ':' || selected_rows.split_suffix AS line_key,
      existing_line.status AS existing_status
    FROM selected_rows
    LEFT JOIN public.banking_pay_workbench_candidate_line_work AS existing_line
      ON existing_line.session_id = p_session_id
     AND existing_line.candidate_id = p_candidate_id
     AND existing_line.timesheet_id IS NOT DISTINCT FROM selected_rows.timesheet_id
     AND existing_line.line_key = selected_rows.parent_line_key || ':' || selected_rows.split_suffix
  ), upserted_line_work AS (
    INSERT INTO public.banking_pay_workbench_candidate_line_work (
      session_id,
      candidate_id,
      timesheet_id,
      line_key,
      line_ordinal,
      status,
      work_payload_json,
      result_row_json,
      error_json,
      created_at_utc,
      updated_at_utc
    )
    SELECT
      p_session_id,
      selected_rows.candidate_id,
      selected_rows.timesheet_id,
      selected_rows.parent_line_key || ':' || selected_rows.split_suffix,
      selected_rows.line_ordinal,
      'PENDING',
      jsonb_strip_nulls(
        jsonb_build_object(
          'source_function', 'pay_workbench_seed_candidate_preview_line_source',
          'source_kind', 'VALID_PREVIEW_LINE',
          'session_id', p_session_id::text,
          'candidate_id', selected_rows.candidate_id::text,
          'line_key', selected_rows.parent_line_key || ':' || selected_rows.split_suffix,
          'line_ordinal', selected_rows.line_ordinal
        )
        || jsonb_build_object(
          'target_section', selected_rows.target_section,
          'section', selected_rows.target_section,
          'line_json', selected_rows.seed_line_json,
          'economic_key', selected_rows.economic_key_json,
          'preview_contract', selected_rows.contract_json,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
        )
      ),
      NULL::jsonb,
      NULL::jsonb,
      v_now,
      v_now
    FROM selected_rows
    ON CONFLICT (session_id, candidate_id, (COALESCE(timesheet_id, '00000000-0000-0000-0000-000000000000'::uuid)), line_key)
    DO UPDATE
    SET line_ordinal = EXCLUDED.line_ordinal,
        work_payload_json = EXCLUDED.work_payload_json,
        status = CASE
          WHEN public.banking_pay_workbench_candidate_line_work.work_payload_json IS DISTINCT FROM EXCLUDED.work_payload_json
            OR UPPER(BTRIM(COALESCE(public.banking_pay_workbench_candidate_line_work.status, ''))) IN ('ERROR', 'FAILED')
          THEN EXCLUDED.status
          ELSE public.banking_pay_workbench_candidate_line_work.status
        END,
        result_row_json = CASE
          WHEN public.banking_pay_workbench_candidate_line_work.work_payload_json IS DISTINCT FROM EXCLUDED.work_payload_json THEN NULL::jsonb
          ELSE public.banking_pay_workbench_candidate_line_work.result_row_json
        END,
        error_json = EXCLUDED.error_json,
        updated_at_utc = v_now
    RETURNING public.banking_pay_workbench_candidate_line_work.timesheet_id,
              public.banking_pay_workbench_candidate_line_work.line_key,
              public.banking_pay_workbench_candidate_line_work.status
  ), counted_changes AS (
    SELECT
      upserted_line_work.status,
      existing_rows.existing_status
    FROM upserted_line_work
    LEFT JOIN existing_rows
      ON existing_rows.timesheet_id IS NOT DISTINCT FROM upserted_line_work.timesheet_id
     AND existing_rows.line_key = upserted_line_work.line_key
  )
  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(counted_changes.status, ''))) = 'ERROR')::integer,
         COUNT(*) FILTER (WHERE counted_changes.existing_status IS NULL AND UPPER(BTRIM(COALESCE(counted_changes.status, ''))) = 'PENDING')::integer,
         COUNT(*) FILTER (WHERE counted_changes.existing_status IS NULL AND UPPER(BTRIM(COALESCE(counted_changes.status, ''))) = 'ERROR')::integer
  INTO v_seeded_count,
       v_error_count,
       v_new_pending_count,
       v_new_error_count
  FROM counted_changes;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'limit', v_limit,
    'cursor_line_ordinal', COALESCE(v_cursor_line_ordinal, 0),
    'source_canonical_preview_line_count', COALESCE(v_source_row_count, 0),
    'materialisable_line_count', COALESCE(v_materialisable_count, 0),
    'valid_materialisable_line_count', COALESCE(v_materialisable_count, 0),
    'contract_rejected_count', COALESCE(v_contract_rejected_count, 0)
  )
  || jsonb_build_object(
    'seeded_count', COALESCE(v_seeded_count, 0),
    'page_count', COALESCE(v_seeded_count, 0),
    'line_work_seeded_count', COALESCE(v_seeded_count, 0),
    'error_count', COALESCE(v_error_count, 0),
    'line_work_error_count', COALESCE(v_error_count, 0),
    'new_pending_count', COALESCE(v_new_pending_count, 0),
    'new_error_count', COALESCE(v_new_error_count, 0)
  )
  || jsonb_build_object(
    'finance_case_source_count', COALESCE(v_finance_case_source_count, 0),
    'hidden_recovery_template_line_count', COALESCE(v_hidden_recovery_template_count, 0),
    'next_cursor', v_next_cursor,
    'has_more', COALESCE(v_has_more, false),
    'classifier_result', COALESCE(v_classifier_result, '{}'::jsonb)
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_workbench_preview_line_economic_key(p_line_json jsonb DEFAULT '{}'::jsonb, p_timesheet_id uuid DEFAULT NULL::uuid, p_item_type text DEFAULT NULL::text, p_segment_json jsonb DEFAULT NULL::jsonb, p_key_type_hint text DEFAULT NULL::text, p_key_value_hint text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_line_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_line_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_line_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_segment_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_segment_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_segment_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_timesheet_id uuid := p_timesheet_id;
  v_timesheet_id_text text := NULL::text;
  v_line_type text := UPPER(NULLIF(BTRIM(COALESCE(v_line_json->>'line_type', v_line_json->>'case_type', '')), ''));
  v_item_type text := UPPER(NULLIF(BTRIM(COALESCE(p_item_type, v_line_json->>'item_type', v_line_json->>'allocation_type', v_line_type, '')), ''));
  v_key_type_hint text := UPPER(NULLIF(BTRIM(COALESCE(
    p_key_type_hint,
    v_segment_json->>'component_key_type',
    v_segment_json->>'key_type',
    v_line_json#>>'{economic_key,key_type}',
    v_line_json->>'component_key_type',
    v_line_json->>'key_type',
    v_line_json->>'frozen_component_key_type',
    v_line_json#>>'{source_basis_json,component_key_type}',
    v_line_json#>>'{source_basis_json,key_type}',
    v_line_json#>>'{frozen_source_basis_json,component_key_type}',
    v_line_json#>>'{frozen_source_basis_json,key_type}',
    ''
  )), ''));
  v_key_value_hint text := NULLIF(BTRIM(COALESCE(
    p_key_value_hint,
    v_segment_json->>'component_key_value',
    v_segment_json->>'key_value',
    v_line_json#>>'{economic_key,key_value}',
    v_line_json->>'component_key_value',
    v_line_json->>'key_value',
    v_line_json->>'frozen_component_key_value',
    v_line_json#>>'{source_basis_json,component_key_value}',
    v_line_json#>>'{source_basis_json,key_value}',
    v_line_json#>>'{frozen_source_basis_json,component_key_value}',
    v_line_json#>>'{frozen_source_basis_json,key_value}',
    ''
  )), '');
  v_work_date_text text := NULLIF(BTRIM(COALESCE(
    v_segment_json->>'work_date',
    v_segment_json->>'date',
    v_line_json->>'work_date',
    v_line_json->>'date',
    v_line_json#>>'{source_basis_json,work_date}',
    v_line_json#>>'{source_basis_json,date}',
    v_line_json#>>'{frozen_source_basis_json,work_date}',
    v_line_json#>>'{frozen_source_basis_json,date}',
    ''
  )), '');
  v_work_date date := NULL::date;
  v_manual_key_value text := NULL::text;
  v_source_json jsonb := '{}'::jsonb;
  v_resolved_timesheet_id uuid := NULL::uuid;
  v_resolved_key_type text := NULL::text;
  v_resolved_key_value text := NULL::text;
  v_resolved_source text := NULL::text;
  v_failure_reason text := NULL::text;
  v_case_component_count integer := 0;
  v_single_case_component_json jsonb := '{}'::jsonb;
  v_single_component_key_type text := NULL::text;
  v_single_component_key_value text := NULL::text;
  v_single_component_classification text := NULL::text;
  v_line_amount_ex_vat numeric := NULL::numeric;
  v_single_component_amount_ex_vat numeric := NULL::numeric;
  v_has_segment_identity boolean := false;
BEGIN
  v_has_segment_identity := NULLIF(BTRIM(COALESCE(
    v_segment_json->>'segment_id',
    v_segment_json->>'segment_key',
    v_segment_json->>'segment_stable_key',
    v_segment_json->>'ref_num',
    v_segment_json->>'work_date',
    v_segment_json->>'date',
    v_line_json->>'segment_id',
    v_line_json->>'segment_key',
    v_line_json->>'segment_stable_key',
    v_line_json->>'ref_num',
    v_line_json#>>'{source_basis_json,segment_id}',
    v_line_json#>>'{source_basis_json,segment_key}',
    v_line_json#>>'{source_basis_json,segment_stable_key}',
    ''
  )), '') IS NOT NULL;

  IF COALESCE(v_line_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_line_amount_ex_vat := ROUND((v_line_json->>'amount_ex_vat')::numeric, 2);
  ELSIF COALESCE(v_line_json->>'preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_line_amount_ex_vat := ROUND((v_line_json->>'preview_amount_ex_vat')::numeric, 2);
  ELSIF COALESCE(v_line_json->>'section_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_line_amount_ex_vat := ROUND((v_line_json->>'section_amount_ex_vat')::numeric, 2);
  END IF;

  IF jsonb_typeof(COALESCE(v_line_json->'case_components', '[]'::jsonb)) = 'array' THEN
    SELECT
      COUNT(*)::integer,
      COALESCE((ARRAY_AGG(case_component.value ORDER BY case_component.ordinality))[1], '{}'::jsonb)
    INTO v_case_component_count, v_single_case_component_json
    FROM jsonb_array_elements(COALESCE(v_line_json->'case_components', '[]'::jsonb)) WITH ORDINALITY AS case_component(value, ordinality)
    WHERE case_component.value IS NOT NULL
      AND jsonb_typeof(case_component.value) = 'object';
  END IF;

  IF COALESCE(v_case_component_count, 0) = 1 THEN
    v_single_component_key_type := UPPER(NULLIF(BTRIM(COALESCE(v_single_case_component_json->>'component_key_type', '')), ''));
    v_single_component_key_value := NULLIF(BTRIM(COALESCE(v_single_case_component_json->>'component_key_value', '')), '');
    v_single_component_classification := UPPER(NULLIF(BTRIM(COALESCE(v_single_case_component_json->>'classification', '')), ''));

    IF COALESCE(v_single_case_component_json->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      v_single_component_amount_ex_vat := ROUND((v_single_case_component_json->>'preview_due_amount_ex_vat')::numeric, 2);
    ELSIF COALESCE(v_single_case_component_json->>'allocated_source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      v_single_component_amount_ex_vat := ROUND((v_single_case_component_json->>'allocated_source_due_amount_ex_vat')::numeric, 2);
    ELSIF COALESCE(v_single_case_component_json->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      v_single_component_amount_ex_vat := ROUND((v_single_case_component_json->>'target_pay_ex_vat')::numeric, 2);
    ELSIF COALESCE(v_single_case_component_json->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      v_single_component_amount_ex_vat := ROUND((v_single_case_component_json->>'remaining_source_amount')::numeric, 2);
    END IF;

    IF v_single_component_classification = 'REIMBURSEMENT_GROSS_FIXED'
       AND v_single_component_key_type IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
       AND v_single_component_key_value IS NOT NULL
       AND (
         v_key_type_hint IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
         OR (
           COALESCE(v_has_segment_identity, false) IS FALSE
           AND v_line_amount_ex_vat IS NOT NULL
           AND v_single_component_amount_ex_vat IS NOT NULL
           AND ROUND(ABS(v_line_amount_ex_vat), 2) = ROUND(ABS(v_single_component_amount_ex_vat), 2)
         )
         OR (
           COALESCE(v_has_segment_identity, false) IS FALSE
           AND v_key_type_hint IS NULL
           AND COALESCE(v_item_type, '') NOT IN ('SEGMENT_DELTA')
         )
       ) THEN
      v_key_type_hint := v_single_component_key_type;
      v_key_value_hint := v_single_component_key_value;
      v_item_type := CASE
        WHEN v_single_component_key_type = 'EXPENSE_CODE'
         AND UPPER(COALESCE(v_single_component_key_value, '')) = 'MILEAGE' THEN 'MILEAGE_DELTA'
        ELSE 'EXPENSE_DELTA'
      END;
    END IF;
  END IF;

  v_timesheet_id_text := CASE
    WHEN v_timesheet_id IS NOT NULL THEN NULL::text
    ELSE NULLIF(BTRIM(COALESCE(
      v_line_json#>>'{economic_key,timesheet_id}',
      v_line_json->>'real_business_timesheet_id',
      v_line_json->>'timesheet_id',
      v_line_json#>>'{source_basis_json,timesheet_id}',
      v_line_json#>>'{frozen_source_basis_json,timesheet_id}',
      ''
    )), '')
  END;

  IF v_timesheet_id IS NULL
     AND v_timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_timesheet_id := v_timesheet_id_text::uuid;
  END IF;

  IF v_item_type IN ('TIMESHEET_PAYMENT', 'TIMESHEET', 'HOURS', 'SEGMENT') THEN
    v_item_type := 'SEGMENT_DELTA';
  ELSIF v_item_type IN ('MANUAL_ADJUSTMENT_CARRY_FORWARD', 'MANUAL_CREDIT_PAYOUT') THEN
    v_item_type := 'MANUAL_CARRY_FORWARD';
  ELSIF v_item_type IN ('LOAN_PAYOUT', 'PAYMENT_ADVANCE_REPAYMENT', 'OVERPAYMENT_RECOVERY', 'MANUAL_DEBT_RECOVERY', 'MANUAL_CREDIT_ADJUSTMENT_PAYMENT') THEN
    v_item_type := COALESCE(
      CASE
        WHEN v_key_type_hint IN ('TS_DAY', 'TS_TOTAL') THEN 'SEGMENT_DELTA'
        WHEN v_key_type_hint = 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
        WHEN v_key_type_hint = 'EXPENSE_CODE' AND UPPER(COALESCE(v_key_value_hint, '')) = 'MILEAGE' THEN 'MILEAGE_DELTA'
        WHEN v_key_type_hint IN ('EXPENSE_CODE', 'ADDITIONAL_CODE') THEN 'EXPENSE_DELTA'
        ELSE NULL::text
      END,
      'ADJUSTMENT_DELTA'
    );
  ELSIF v_item_type IS NULL THEN
    v_item_type := CASE
      WHEN v_key_type_hint IN ('TS_DAY', 'TS_TOTAL') THEN 'SEGMENT_DELTA'
      WHEN v_key_type_hint = 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
      WHEN v_key_type_hint = 'EXPENSE_CODE' AND UPPER(COALESCE(v_key_value_hint, '')) = 'MILEAGE' THEN 'MILEAGE_DELTA'
      WHEN v_key_type_hint IN ('EXPENSE_CODE', 'ADDITIONAL_CODE') THEN 'EXPENSE_DELTA'
      ELSE NULL::text
    END;
  END IF;

  IF v_item_type = 'MANUAL_CARRY_FORWARD' THEN
    v_manual_key_value := NULLIF(BTRIM(COALESCE(
      v_line_json->>'manual_adjustment_carry_forward_id',
      REPLACE(v_line_json->>'source_ref', 'carry_forward:', ''),
      REPLACE(v_line_json->>'preview_row_id', 'carry_forward:', ''),
      v_line_json->>'operation_source_key',
      ''
    )), '');

    IF v_manual_key_value IS NOT NULL THEN
      RETURN jsonb_build_object(
        'ok', true,
        'timesheet_id', CASE WHEN v_timesheet_id IS NULL THEN NULL ELSE v_timesheet_id::text END,
        'key_type', 'MANUAL_CARRY_FORWARD',
        'key_value', v_manual_key_value,
        'key_resolution_source', 'PRE_DRAFT_MANUAL_CARRY_FORWARD_KEY',
        'key_resolution_failure_reason', NULL::text,
        'item_type', 'MANUAL_CARRY_FORWARD',
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      );
    END IF;
  END IF;

  IF v_work_date_text IS NOT NULL AND v_work_date_text ~ '^\d{4}-\d{2}-\d{2}$' THEN
    v_work_date := v_work_date_text::date;
  END IF;

  v_source_json := jsonb_strip_nulls(
    COALESCE(v_line_json, '{}'::jsonb)
    || jsonb_build_object(
      'timesheet_id', CASE WHEN v_timesheet_id IS NULL THEN NULL ELSE v_timesheet_id::text END,
      'item_type', v_item_type,
      'work_date', CASE WHEN v_work_date IS NULL THEN NULL ELSE v_work_date::text END,
      'date', CASE WHEN v_work_date IS NULL THEN NULL ELSE v_work_date::text END
    )
    || jsonb_build_object(
      'segment_id', NULLIF(BTRIM(COALESCE(v_segment_json->>'segment_id', v_line_json->>'segment_id', '')), ''),
      'segment_key', NULLIF(BTRIM(COALESCE(v_segment_json->>'segment_key', v_line_json->>'segment_key', '')), ''),
      'segment_stable_key', NULLIF(BTRIM(COALESCE(v_segment_json->>'segment_stable_key', v_line_json->>'segment_stable_key', '')), ''),
      'ref_num', NULLIF(BTRIM(COALESCE(v_segment_json->>'ref_num', v_line_json->>'ref_num', '')), ''),
      'component_key_type', v_key_type_hint,
      'component_key_value', v_key_value_hint,
      'segment_json', v_segment_json
    )
  );

  SELECT
    resolved_key.timesheet_id,
    resolved_key.key_type,
    resolved_key.key_value,
    resolved_key.key_resolution_source,
    resolved_key.key_resolution_failure_reason
  INTO
    v_resolved_timesheet_id,
    v_resolved_key_type,
    v_resolved_key_value,
    v_resolved_source,
    v_failure_reason
  FROM public._pay_policy_x_resolve_pre_draft_economic_key(
    p_timesheet_id => v_timesheet_id,
    p_live_source_json => v_source_json,
    p_item_type => v_item_type,
    p_key_type_hint => v_key_type_hint,
    p_key_value_hint => v_key_value_hint,
    p_work_date => v_work_date
  ) AS resolved_key;

  RETURN jsonb_build_object(
    'ok', (v_resolved_key_type IS NOT NULL AND v_resolved_key_value IS NOT NULL),
    'timesheet_id', CASE WHEN v_resolved_timesheet_id IS NULL THEN NULL ELSE v_resolved_timesheet_id::text END,
    'key_type', v_resolved_key_type,
    'key_value', v_resolved_key_value,
    'key_resolution_source', v_resolved_source,
    'key_resolution_failure_reason', v_failure_reason,
    'item_type', v_item_type,
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_workbench_preview_line_contract_ok(
  p_line_json jsonb DEFAULT '{}'::jsonb,
  p_economic_key_json jsonb DEFAULT NULL::jsonb,
  p_target_section text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_line_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_line_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_line_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_economic_key_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_economic_key_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_economic_key_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_target_section_input text := NULLIF(BTRIM(COALESCE(p_target_section, '')), '');
  v_target_section text := CASE
    WHEN v_target_section_input IS NULL THEN public.pay_workbench_preview_section_from_line_json(v_line_json)
    ELSE public.pay_workbench_preview_section_from_line_json(v_line_json || jsonb_build_object('target_section', v_target_section_input))
  END;
  v_presentation_section text := UPPER(NULLIF(BTRIM(COALESCE(v_line_json->>'presentation_section', v_line_json->>'readiness_state', '')), ''));
  v_source_kind text := UPPER(NULLIF(BTRIM(COALESCE(v_line_json->>'source_kind', v_line_json->>'source_type', '')), ''));
  v_line_key text := NULLIF(BTRIM(COALESCE(v_line_json->>'line_key', v_line_json->>'row_key', v_line_json->>'preview_row_id', v_line_json->>'line_id', '')), '');
  v_line_type text := UPPER(NULLIF(BTRIM(COALESCE(v_line_json->>'line_type', v_line_json->>'case_type', '')), ''));
  v_key_type text := UPPER(NULLIF(BTRIM(COALESCE(v_economic_key_json->>'key_type', v_line_json#>>'{economic_key,key_type}', v_line_json->>'component_key_type', v_line_json->>'key_type', '')), ''));
  v_key_value text := NULLIF(BTRIM(COALESCE(v_economic_key_json->>'key_value', v_line_json#>>'{economic_key,key_value}', v_line_json->>'component_key_value', v_line_json->>'key_value', '')), '');
  v_amount_text text := NULLIF(BTRIM(COALESCE(v_line_json->>'amount_ex_vat', v_line_json->>'preview_amount_ex_vat', v_line_json->>'section_amount_ex_vat', '')), '');
  v_amount numeric := NULL::numeric;
  v_draftable boolean := false;
  v_is_ready_for_draft boolean := false;
  v_is_excluded boolean := false;
  v_materialisable boolean := false;
  v_selection_allowed boolean := false;
  v_ok boolean := false;
  v_reasons jsonb := '[]'::jsonb;
  v_reason_count integer := 0;
BEGIN
  IF jsonb_typeof(COALESCE(p_line_json, '{}'::jsonb)) <> 'object' THEN
    v_reasons := v_reasons || jsonb_build_array('LINE_JSON_NOT_OBJECT');
  END IF;

  IF v_source_kind IN (
    'TIMESHEET_SNAPSHOT',
    'TIMESHEET_SNAPSHOT_EVIDENCE',
    'RAW_TIMESHEET_SNAPSHOT',
    'INTERNAL_ONLY',
    'NO_DELTA',
    'EXCLUDED'
  ) THEN
    v_reasons := v_reasons || jsonb_build_array('INTERNAL_OR_RAW_SOURCE_KIND');
  END IF;

  IF v_amount_text IS NOT NULL AND v_amount_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_amount := ROUND(v_amount_text::numeric, 2);
  END IF;

  v_draftable := LOWER(BTRIM(COALESCE(v_line_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_is_ready_for_draft := LOWER(BTRIM(COALESCE(v_line_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_is_excluded := LOWER(BTRIM(COALESCE(v_line_json->>'is_excluded_from_allocation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF v_target_section = 'canonical_preview_lines' THEN
    v_materialisable := true;

    IF COALESCE(v_draftable, false) IS NOT TRUE THEN
      v_reasons := v_reasons || jsonb_build_array('READY_ROW_NOT_DRAFTABLE');
    END IF;

    IF COALESCE(v_is_ready_for_draft, false) IS NOT TRUE THEN
      v_reasons := v_reasons || jsonb_build_array('READY_ROW_NOT_READY_FOR_DRAFT');
    END IF;

    IF COALESCE(v_is_excluded, false) THEN
      v_reasons := v_reasons || jsonb_build_array('READY_ROW_EXCLUDED_FROM_ALLOCATION');
    END IF;

    IF v_presentation_section IS DISTINCT FROM 'READY_TO_PAY' THEN
      v_reasons := v_reasons || jsonb_build_array('READY_ROW_PRESENTATION_SECTION_INVALID');
    END IF;

    IF v_amount IS NULL THEN
      v_reasons := v_reasons || jsonb_build_array('READY_ROW_AMOUNT_MISSING');
    ELSIF ROUND(COALESCE(v_amount, 0), 2) = 0 THEN
      v_reasons := v_reasons || jsonb_build_array('READY_ROW_AMOUNT_ZERO');
    END IF;

    IF v_key_type IS NULL OR v_key_value IS NULL THEN
      v_reasons := v_reasons || jsonb_build_array('READY_ROW_ECONOMIC_KEY_MISSING');
    ELSIF v_key_type = 'TS_DAY' AND v_key_value !~ '^\d{4}-\d{2}-\d{2}$' THEN
      v_reasons := v_reasons || jsonb_build_array('READY_ROW_TS_DAY_KEY_NOT_DATE');
    END IF;

    IF v_line_key LIKE 'timesheet_snapshot:%' THEN
      v_reasons := v_reasons || jsonb_build_array('RAW_TIMESHEET_SNAPSHOT_ROW_KEY_REJECTED');
    END IF;

  ELSIF v_target_section IN ('cases_resolutions', 'blocked_for_pay') THEN
    v_materialisable := true;
    v_selection_allowed := false;

    IF v_presentation_section IS NULL THEN
      v_reasons := v_reasons || jsonb_build_array('DISPLAY_ROW_PRESENTATION_SECTION_MISSING');
    END IF;

    IF COALESCE(v_draftable, false) THEN
      v_reasons := v_reasons || jsonb_build_array('DISPLAY_ROW_MUST_NOT_BE_DRAFTABLE');
    END IF;
  ELSE
    v_materialisable := false;
  END IF;

  SELECT jsonb_array_length(v_reasons)
  INTO v_reason_count;

  v_ok := COALESCE(v_materialisable, false) AND COALESCE(v_reason_count, 0) = 0;

  IF v_target_section = 'canonical_preview_lines' AND COALESCE(v_ok, false) THEN
    v_selection_allowed := true;
  END IF;

  RETURN jsonb_build_object(
    'ok', COALESCE(v_ok, false),
    'materialisable', COALESCE(v_materialisable, false),
    'target_section', v_target_section,
    'presentation_section', v_presentation_section,
    'source_kind', v_source_kind,
    'line_type', v_line_type,
    'line_key', v_line_key,
    'draftable', COALESCE(v_draftable, false),
    'is_ready_for_draft', COALESCE(v_is_ready_for_draft, false)
  )
  || jsonb_build_object(
    'is_excluded_from_allocation', COALESCE(v_is_excluded, false),
    'selection_allowed', COALESCE(v_selection_allowed, false),
    'amount_ex_vat', v_amount,
    'key_type', v_key_type,
    'key_value', v_key_value,
    'reason_count', COALESCE(v_reason_count, 0),
    'reasons', COALESCE(v_reasons, '[]'::jsonb),
    'status', CASE WHEN COALESCE(v_ok, false) THEN 'OK' ELSE 'NOT_OK' END
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.banking_pay_operation_find_active_draft_create(
    p_actor_user_id uuid,
    p_workbench_session_id uuid,
    p_include_recent_terminal boolean DEFAULT false,
    p_recent_terminal_minutes integer DEFAULT 60
)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_now timestamptz := now();
    v_recent_terminal_minutes integer := LEAST(GREATEST(COALESCE(p_recent_terminal_minutes, 60), 0), 10080);
    v_recent_terminal_after timestamptz := NULL::timestamptz;
    v_operation public.banking_pay_operations%ROWTYPE;
    v_progress jsonb := '{}'::jsonb;
    v_result jsonb := '{}'::jsonb;
    v_error jsonb := '{}'::jsonb;
    v_public_payload jsonb := '{}'::jsonb;
    v_terminal boolean := false;
    v_active boolean := false;
    v_heartbeat_age_seconds integer := NULL::integer;
    v_batch_ids jsonb := '[]'::jsonb;
    v_primary_pay_batch_id text := NULL::text;
    v_backend_runner_owned boolean := false;
    v_frontend_completion_required boolean := false;
    v_session_id_text text := NULL::text;
BEGIN
    PERFORM public.banking_pay_hot_path_budget_apply('PROGRESS');

    IF p_actor_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'ok', false,
            'code', 'ACTOR_USER_ID_REQUIRED',
            'message', 'actor_user_id is required'
        );
    END IF;

    IF p_workbench_session_id IS NULL THEN
        RETURN jsonb_build_object(
            'ok', false,
            'code', 'WORKBENCH_SESSION_ID_REQUIRED',
            'message', 'workbench_session_id is required'
        );
    END IF;

    v_session_id_text := p_workbench_session_id::text;

    IF COALESCE(p_include_recent_terminal, false) IS TRUE AND v_recent_terminal_minutes > 0 THEN
        v_recent_terminal_after := v_now - make_interval(mins => v_recent_terminal_minutes);
    END IF;

    SELECT operation_row.*
    INTO v_operation
    FROM public.banking_pay_operations AS operation_row
    WHERE upper(BTRIM(COALESCE(operation_row.operation_type, ''))) = 'DRAFT_CREATE'
      AND operation_row.actor_user_id = p_actor_user_id
      AND (
          operation_row.workbench_session_id = p_workbench_session_id
          OR COALESCE(operation_row.input_json->>'workbench_session_id', '') = v_session_id_text
          OR COALESCE(operation_row.input_json->>'workbenchSessionId', '') = v_session_id_text
          OR COALESCE(operation_row.input_json->>'session_id', '') = v_session_id_text
          OR COALESCE(operation_row.input_json->>'source_session_id', '') = v_session_id_text
          OR COALESCE(operation_row.input_json->>'source_workbench_session_id', '') = v_session_id_text
          OR COALESCE(operation_row.progress_json->>'workbench_session_id', '') = v_session_id_text
          OR COALESCE(operation_row.progress_json->>'workbenchSessionId', '') = v_session_id_text
          OR COALESCE(operation_row.progress_json->>'session_id', '') = v_session_id_text
          OR COALESCE(operation_row.progress_json->>'source_session_id', '') = v_session_id_text
          OR COALESCE(operation_row.progress_json->>'source_workbench_session_id', '') = v_session_id_text
          OR COALESCE(operation_row.result_json->>'workbench_session_id', '') = v_session_id_text
          OR COALESCE(operation_row.result_json->>'workbenchSessionId', '') = v_session_id_text
          OR COALESCE(operation_row.result_json->>'session_id', '') = v_session_id_text
          OR COALESCE(operation_row.result_json->>'source_session_id', '') = v_session_id_text
          OR COALESCE(operation_row.result_json->>'source_workbench_session_id', '') = v_session_id_text
      )
      AND (
          upper(BTRIM(COALESCE(operation_row.status, ''))) IN ('RUNNING', 'CONTINUING', 'WAITING_RETRY')
          OR (
              v_recent_terminal_after IS NOT NULL
              AND upper(BTRIM(COALESCE(operation_row.status, ''))) IN ('COMPLETE', 'COMPLETED', 'FAILED', 'CANCELLED', 'CANCELED', 'ERROR', 'REVIEW_REQUIRED')
              AND COALESCE(operation_row.completed_at_utc, operation_row.failed_at_utc, operation_row.updated_at_utc, operation_row.created_at_utc) >= v_recent_terminal_after
          )
      )
    ORDER BY
      CASE
        WHEN upper(BTRIM(COALESCE(operation_row.status, ''))) IN ('RUNNING', 'CONTINUING', 'WAITING_RETRY') THEN 0
        ELSE 1
      END ASC,
      CASE upper(BTRIM(COALESCE(operation_row.status, '')))
        WHEN 'RUNNING' THEN 0
        WHEN 'CONTINUING' THEN 1
        WHEN 'WAITING_RETRY' THEN 2
        ELSE 8
      END ASC,
      operation_row.updated_at_utc DESC NULLS LAST,
      operation_row.created_at_utc DESC NULLS LAST,
      operation_row.id DESC
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'ok', true,
            'found', false,
            'operation', NULL::jsonb,
            'operation_id', NULL::text,
            'workbench_session_id', v_session_id_text,
            'operation_type', 'DRAFT_CREATE'
        );
    END IF;

    v_progress := COALESCE(v_operation.progress_json, '{}'::jsonb);
    v_result := COALESCE(v_operation.result_json, '{}'::jsonb);
    v_error := COALESCE(v_operation.error_json, '{}'::jsonb);
    v_terminal := upper(BTRIM(COALESCE(v_operation.status, ''))) IN ('COMPLETE', 'COMPLETED', 'FAILED', 'CANCELLED', 'CANCELED', 'ERROR', 'REVIEW_REQUIRED');
    v_active := upper(BTRIM(COALESCE(v_operation.status, ''))) IN ('RUNNING', 'CONTINUING', 'WAITING_RETRY') AND v_terminal IS NOT TRUE;
    v_heartbeat_age_seconds := CASE
        WHEN v_operation.heartbeat_at_utc IS NULL THEN NULL::integer
        ELSE GREATEST(0, EXTRACT(EPOCH FROM (v_now - v_operation.heartbeat_at_utc))::integer)
    END;

    v_backend_runner_owned := upper(BTRIM(COALESCE(
        v_operation.input_json->>'backend_runner_owned',
        v_operation.input_json->>'backendRunnerOwned',
        v_operation.config_json->>'backend_runner_owned',
        v_operation.config_json->>'backendRunnerOwned',
        v_progress->>'backend_runner_owned',
        v_progress->>'backendRunnerOwned',
        'false'
    ))) IN ('TRUE', 'T', '1', 'YES', 'Y', 'ON');

    v_frontend_completion_required := upper(BTRIM(COALESCE(
        v_operation.input_json->>'frontend_completion_required',
        v_operation.input_json->>'frontendCompletionRequired',
        v_operation.config_json->>'frontend_completion_required',
        v_operation.config_json->>'frontendCompletionRequired',
        v_progress->>'frontend_completion_required',
        v_progress->>'frontendCompletionRequired',
        'false'
    ))) IN ('TRUE', 'T', '1', 'YES', 'Y', 'ON');

    SELECT COALESCE(jsonb_agg(batch_id_dedup.batch_id_text ORDER BY batch_id_dedup.batch_id_text), '[]'::jsonb)
    INTO v_batch_ids
    FROM (
        SELECT DISTINCT NULLIF(BTRIM(batch_id_source.batch_id_text), '') AS batch_id_text
        FROM (
            SELECT CASE WHEN v_operation.pay_batch_id IS NULL THEN NULL::text ELSE v_operation.pay_batch_id::text END AS batch_id_text
            UNION ALL SELECT v_progress->>'pay_batch_id'
            UNION ALL SELECT v_progress->>'payBatchId'
            UNION ALL SELECT v_progress->>'primary_pay_batch_id'
            UNION ALL SELECT v_progress->>'primaryPayBatchId'
            UNION ALL SELECT v_result->>'pay_batch_id'
            UNION ALL SELECT v_result->>'payBatchId'
            UNION ALL SELECT v_result->>'primary_pay_batch_id'
            UNION ALL SELECT v_result->>'primaryPayBatchId'
            UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_progress->'pay_batch_ids') = 'array' THEN v_progress->'pay_batch_ids' ELSE '[]'::jsonb END)
            UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_progress->'payBatchIds') = 'array' THEN v_progress->'payBatchIds' ELSE '[]'::jsonb END)
            UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_progress->'created_pay_batch_ids') = 'array' THEN v_progress->'created_pay_batch_ids' ELSE '[]'::jsonb END)
            UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_progress->'createdPayBatchIds') = 'array' THEN v_progress->'createdPayBatchIds' ELSE '[]'::jsonb END)
            UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result->'pay_batch_ids') = 'array' THEN v_result->'pay_batch_ids' ELSE '[]'::jsonb END)
            UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result->'payBatchIds') = 'array' THEN v_result->'payBatchIds' ELSE '[]'::jsonb END)
            UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result->'created_pay_batch_ids') = 'array' THEN v_result->'created_pay_batch_ids' ELSE '[]'::jsonb END)
            UNION ALL SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result->'createdPayBatchIds') = 'array' THEN v_result->'createdPayBatchIds' ELSE '[]'::jsonb END)
        ) AS batch_id_source
    ) AS batch_id_dedup
    WHERE batch_id_dedup.batch_id_text IS NOT NULL;

    v_primary_pay_batch_id := COALESCE(
        CASE WHEN v_operation.pay_batch_id IS NULL THEN NULL::text ELSE v_operation.pay_batch_id::text END,
        NULLIF(BTRIM(v_progress->>'primary_pay_batch_id'), ''),
        NULLIF(BTRIM(v_progress->>'primaryPayBatchId'), ''),
        NULLIF(BTRIM(v_progress->>'pay_batch_id'), ''),
        NULLIF(BTRIM(v_progress->>'payBatchId'), ''),
        NULLIF(BTRIM(v_result->>'primary_pay_batch_id'), ''),
        NULLIF(BTRIM(v_result->>'primaryPayBatchId'), ''),
        NULLIF(BTRIM(v_result->>'pay_batch_id'), ''),
        NULLIF(BTRIM(v_result->>'payBatchId'), '')
    );

    v_public_payload := COALESCE(public.banking_pay_operation_get(v_operation.id, p_actor_user_id, 'PROGRESS_LIGHT'), '{}'::jsonb);

    RETURN jsonb_strip_nulls(
        v_public_payload
        || jsonb_build_object(
            'ok', true,
            'found', true,
            'active_draft_create_operation', v_active,
            'recent_terminal_draft_create_operation', (v_terminal IS TRUE AND v_active IS NOT TRUE),
            'operation_id', v_operation.id::text,
            'id', v_operation.id::text,
            'operation_type', v_operation.operation_type,
            'status', v_operation.status,
            'phase', v_operation.phase,
            'runner_state', v_operation.runner_state,
            'actor_user_id', v_operation.actor_user_id::text,
            'workbench_session_id', COALESCE(CASE WHEN v_operation.workbench_session_id IS NULL THEN NULL::text ELSE v_operation.workbench_session_id::text END, v_session_id_text),
            'pay_batch_id', v_primary_pay_batch_id,
            'primary_pay_batch_id', v_primary_pay_batch_id,
            'root_operation_id', CASE WHEN v_operation.root_operation_id IS NULL THEN NULL ELSE v_operation.root_operation_id::text END,
            'idempotency_key', v_operation.idempotency_key,
            'backend_runner_owned', v_backend_runner_owned,
            'frontend_completion_required', v_frontend_completion_required,
            'terminal', v_terminal,
            'server_running', (v_operation.lease_owner IS NOT NULL AND v_operation.lease_expires_at_utc IS NOT NULL AND v_operation.lease_expires_at_utc > v_now),
            'heartbeat_age_seconds', v_heartbeat_age_seconds,
            'pay_batch_ids', v_batch_ids,
            'created_pay_batch_ids', v_batch_ids
        )
        || jsonb_build_object(
            'result_summary', jsonb_strip_nulls(jsonb_build_object(
                'pay_batch_id', v_primary_pay_batch_id,
                'primary_pay_batch_id', v_primary_pay_batch_id,
                'pay_batch_ids', v_batch_ids,
                'created_pay_batch_ids', v_batch_ids,
                'created_batch_count', CASE WHEN COALESCE(v_result->>'created_batch_count', '') ~ '^[0-9]+$' THEN (v_result->>'created_batch_count')::integer ELSE jsonb_array_length(v_batch_ids) END,
                'workbench_session_id', COALESCE(CASE WHEN v_operation.workbench_session_id IS NULL THEN NULL::text ELSE v_operation.workbench_session_id::text END, v_session_id_text),
                'source_session_discarded', v_result->>'source_session_discarded',
                'last_message', COALESCE(v_result->>'last_message', v_progress->>'last_message')
            )),
            'small_error_summary', CASE
                WHEN v_operation.error_json IS NULL THEN NULL::jsonb
                WHEN jsonb_typeof(v_error) = 'object' THEN jsonb_strip_nulls(jsonb_build_object(
                    'code', COALESCE(NULLIF(BTRIM(v_error->>'code'), ''), NULLIF(BTRIM(v_error->>'error_code'), '')),
                    'message', LEFT(COALESCE(NULLIF(BTRIM(v_error->>'message'), ''), NULLIF(BTRIM(v_error->>'error'), ''), v_error::text), 1000)
                ))
                ELSE jsonb_build_object('message', LEFT(v_error::text, 1000))
            END
        )
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.pay_batch_abort_failed_draft_create_partial(p_operation_id uuid, p_pay_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_failure_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_batch_row public.pay_batches%ROWTYPE;
  v_batch_row_after public.pay_batches%ROWTYPE;
  v_operation_status text := NULL::text;
  v_operation_phase text := NULL::text;
  v_batch_status_before text := NULL::text;
  v_batch_status_after text := NULL::text;
  v_execution_commit_state_before text := NULL::text;
  v_failure_json jsonb := '{}'::jsonb;
  v_failure_code text := 'DRAFT_CREATE_OPERATION_FAILED';
  v_failure_phase text := 'UNKNOWN';
  v_reason text := NULL::text;
  v_effective_actor_user_id uuid := NULL::uuid;
  v_expected_snapshot_run_id_text text := NULL::text;
  v_batch_snapshot_run_id_text text := NULL::text;
  v_expected_session_version_text text := NULL::text;
  v_batch_session_version_text text := NULL::text;
  v_session_version_direct_link_exception_used boolean := false;
  v_operation_direct_batch_link boolean := false;
  v_candidate_scope_link_count integer := 0;
  v_allocation_link_count integer := 0;
  v_item_link_count integer := 0;
  v_latest_draft_create_operation_id uuid := NULL::uuid;
  v_transfer_row_count integer := 0;
  v_transfer_scope_count integer := 0;
  v_provider_attempt_count integer := 0;
  v_bank_transfer_event_count integer := 0;
  v_auth_request_count integer := 0;
  v_auth_action_count integer := 0;
  v_remittance_scope_count integer := 0;
  v_settlement_scope_count integer := 0;
  v_correction_request_count integer := 0;
  v_committed_reservation_count integer := 0;
  v_submission_artifact_count integer := 0;
  v_batch_submission_flag_count integer := 0;
  v_candidate_count integer := 0;
  v_item_count integer := 0;
  v_active_item_count integer := 0;
  v_reservation_count integer := 0;
  v_reservations_released integer := 0;
  v_items_voided integer := 0;
  v_candidate_scopes_failed integer := 0;
  v_allocation_rows_updated integer := 0;
  v_allocation_rows_failed integer := 0;
  v_batch_status_cancelled_allowed boolean := true;
  v_candidate_scope_failed_status_allowed boolean := true;
  v_allocation_failed_status_allowed boolean := false;
  v_reservation_released_status_allowed boolean := false;
  v_called_from_failure_finalisation boolean := false;
  v_cleanup_counts_json jsonb := '{}'::jsonb;
  v_signal_scope_json jsonb := '{}'::jsonb;
  v_signal_result_json jsonb := '{}'::jsonb;
  v_cleanup_result_json jsonb := '{}'::jsonb;
  v_operation_progress_patch_json jsonb := '{}'::jsonb;
  v_operation_error_patch_json jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_REQUIRED'
            )::text;
  END IF;

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_BATCH_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_BATCH_REQUIRED',
              'operation_id', p_operation_id::text
            )::text;
  END IF;

  v_failure_json := CASE
    WHEN p_failure_json IS NOT NULL AND jsonb_typeof(p_failure_json) = 'object' THEN COALESCE(p_failure_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_NOT_FOUND',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_BATCH_NOT_FOUND',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  v_operation_status := UPPER(BTRIM(COALESCE(v_operation_row.status, '')));
  v_operation_phase := UPPER(BTRIM(COALESCE(v_operation_row.phase, '')));
  v_batch_status_before := UPPER(BTRIM(COALESCE(v_batch_row.status, '')));
  v_execution_commit_state_before := UPPER(BTRIM(COALESCE(v_batch_row.execution_commit_state, '')));
  v_effective_actor_user_id := COALESCE(p_actor_user_id, v_operation_row.actor_user_id, v_batch_row.created_by_user_id);

  v_failure_code := UPPER(NULLIF(BTRIM(COALESCE(
    v_failure_json->>'code',
    v_failure_json->>'error_code',
    v_failure_json->>'errorCode',
    'DRAFT_CREATE_OPERATION_FAILED'
  )), ''));
  IF v_failure_code IS NULL THEN
    v_failure_code := 'DRAFT_CREATE_OPERATION_FAILED';
  END IF;

  v_failure_phase := UPPER(NULLIF(BTRIM(COALESCE(
    v_failure_json->>'phase',
    v_failure_json->>'operation_phase',
    v_failure_json->>'operationPhase',
    v_operation_phase,
    'UNKNOWN'
  )), ''));
  IF v_failure_phase IS NULL THEN
    v_failure_phase := 'UNKNOWN';
  END IF;

  v_reason := LEFT(COALESCE(
    NULLIF(BTRIM(p_reason), ''),
    'Draft creation failed during ' || v_failure_phase || ': ' || v_failure_code
  ), 500);

  v_called_from_failure_finalisation := (
    v_operation_status IN ('QUEUED', 'RUNNING', 'PROCESSING', 'CLAIMED')
    AND v_operation_phase NOT IN ('COMPLETE', 'COMPLETED', 'SUCCESS', 'SUCCEEDED', 'DONE')
    AND (
      NULLIF(BTRIM(COALESCE(v_failure_json->>'code', '')), '') IS NOT NULL
      OR NULLIF(BTRIM(COALESCE(v_failure_json->>'error_code', '')), '') IS NOT NULL
      OR NULLIF(BTRIM(COALESCE(v_failure_json->>'errorCode', '')), '') IS NOT NULL
      OR NULLIF(BTRIM(COALESCE(v_failure_json->>'error', '')), '') IS NOT NULL
      OR NULLIF(BTRIM(COALESCE(v_failure_json->>'message', '')), '') IS NOT NULL
      OR LOWER(BTRIM(COALESCE(v_failure_json->>'called_from_failure_finalisation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    )
  );

  IF UPPER(BTRIM(COALESCE(v_operation_row.operation_type, ''))) <> 'DRAFT_CREATE' THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_TYPE_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_TYPE_INVALID',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'operation_type', v_operation_row.operation_type
            )::text;
  END IF;

  IF v_operation_status NOT IN ('FAILED', 'ERROR', 'REVIEW_REQUIRED', 'NEEDS_REVIEW', 'REVIEW')
     AND v_called_from_failure_finalisation IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_NOT_FAILED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_NOT_FAILED',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'operation_status', v_operation_row.status,
              'operation_phase', v_operation_row.phase,
              'failure_json_present', v_failure_json <> '{}'::jsonb
            )::text;
  END IF;

  IF v_batch_status_before NOT IN ('DRAFT', 'DRAFT_CREATED', 'CANCELLED', 'CANCELED') THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_BATCH_STATUS_UNSAFE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_BATCH_STATUS_UNSAFE',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'batch_status', v_batch_row.status
            )::text;
  END IF;

  IF NULLIF(v_execution_commit_state_before, '') IS NOT NULL
     AND v_execution_commit_state_before <> 'NOT_SUBMITTED' THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_BATCH_COMMIT_STATE_UNSAFE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_BATCH_COMMIT_STATE_UNSAFE',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'execution_commit_state', v_batch_row.execution_commit_state
            )::text;
  END IF;

  IF v_operation_row.workbench_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_SESSION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_SESSION_REQUIRED',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  IF v_batch_row.source_workbench_session_id IS DISTINCT FROM v_operation_row.workbench_session_id THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SESSION_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SESSION_MISMATCH',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'operation_workbench_session_id', v_operation_row.workbench_session_id::text,
              'batch_source_workbench_session_id', CASE WHEN v_batch_row.source_workbench_session_id IS NULL THEN NULL ELSE v_batch_row.source_workbench_session_id::text END
            )::text;
  END IF;

  v_expected_snapshot_run_id_text := NULLIF(BTRIM(COALESCE(
    v_operation_row.input_json->>'source_snapshot_run_id',
    v_operation_row.input_json->>'sourceSnapshotRunId',
    v_operation_row.input_json->>'snapshot_run_id',
    v_operation_row.input_json->>'snapshotRunId',
    ''
  )), '');
  v_batch_snapshot_run_id_text := CASE WHEN v_batch_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_batch_row.source_snapshot_run_id::text END;

  IF v_expected_snapshot_run_id_text IS NOT NULL
     AND v_batch_snapshot_run_id_text IS DISTINCT FROM v_expected_snapshot_run_id_text THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SNAPSHOT_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SNAPSHOT_MISMATCH',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'expected_source_snapshot_run_id', v_expected_snapshot_run_id_text,
              'batch_source_snapshot_run_id', v_batch_snapshot_run_id_text
            )::text;
  END IF;

  v_expected_session_version_text := NULLIF(BTRIM(COALESCE(
    v_operation_row.input_json->>'source_session_version',
    v_operation_row.input_json->>'sourceSessionVersion',
    v_operation_row.input_json->>'selection_session_version',
    v_operation_row.input_json->>'selectionSessionVersion',
    ''
  )), '');
  v_batch_session_version_text := CASE WHEN v_batch_row.source_session_version IS NULL THEN NULL ELSE v_batch_row.source_session_version::text END;

  v_operation_direct_batch_link := (
    v_operation_row.pay_batch_id IS NOT NULL
    AND v_operation_row.pay_batch_id = p_pay_batch_id
  );

  SELECT COUNT(*)::integer
  INTO v_candidate_scope_link_count
  FROM public.banking_pay_operation_candidate_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_allocation_link_count
  FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
  WHERE allocation_row.operation_id = p_operation_id
    AND allocation_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_item_link_count
  FROM public.pay_batch_items AS item_row
  JOIN public.pay_batch_candidates AS candidate_row
    ON candidate_row.id = item_row.pay_batch_candidate_id
  WHERE candidate_row.pay_batch_id = p_pay_batch_id
    AND item_row.operation_source_key IS NOT NULL
    AND item_row.operation_source_key LIKE p_operation_id::text || ':%';

  v_session_version_direct_link_exception_used := (
    v_expected_session_version_text IS NOT NULL
    AND v_batch_session_version_text IS DISTINCT FROM v_expected_session_version_text
    AND (
      COALESCE(v_operation_direct_batch_link, false) IS TRUE
      OR COALESCE(v_candidate_scope_link_count, 0) > 0
      OR COALESCE(v_allocation_link_count, 0) > 0
      OR COALESCE(v_item_link_count, 0) > 0
    )
  );

  IF v_expected_session_version_text IS NOT NULL
     AND v_batch_session_version_text IS DISTINCT FROM v_expected_session_version_text
     AND COALESCE(v_session_version_direct_link_exception_used, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SESSION_VERSION_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SESSION_VERSION_MISMATCH',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'expected_source_session_version', v_expected_session_version_text,
              'batch_source_session_version', v_batch_session_version_text,
              'operation_direct_batch_link', COALESCE(v_operation_direct_batch_link, false),
              'candidate_scope_link_count', COALESCE(v_candidate_scope_link_count, 0),
              'allocation_link_count', COALESCE(v_allocation_link_count, 0),
              'item_link_count', COALESCE(v_item_link_count, 0)
            )::text;
  END IF;

  SELECT latest_operation.id
  INTO v_latest_draft_create_operation_id
  FROM public.banking_pay_operations AS latest_operation
  WHERE UPPER(BTRIM(COALESCE(latest_operation.operation_type, ''))) = 'DRAFT_CREATE'
    AND (
      latest_operation.pay_batch_id = p_pay_batch_id
      OR EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_candidate_scope AS latest_scope_row
        WHERE latest_scope_row.operation_id = latest_operation.id
          AND latest_scope_row.pay_batch_id = p_pay_batch_id
      )
      OR EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_candidate_allocation_rows AS latest_allocation_row
        WHERE latest_allocation_row.operation_id = latest_operation.id
          AND latest_allocation_row.pay_batch_id = p_pay_batch_id
      )
    )
  ORDER BY latest_operation.updated_at_utc DESC NULLS LAST,
           latest_operation.created_at_utc DESC NULLS LAST,
           latest_operation.id DESC
  LIMIT 1;

  IF v_operation_direct_batch_link IS NOT TRUE
     AND COALESCE(v_candidate_scope_link_count, 0) = 0
     AND COALESCE(v_allocation_link_count, 0) = 0
     AND COALESCE(v_item_link_count, 0) = 0
     AND v_latest_draft_create_operation_id IS DISTINCT FROM p_operation_id THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_BATCH_LINK_MISSING'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_OPERATION_BATCH_LINK_MISSING',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'operation_pay_batch_id', CASE WHEN v_operation_row.pay_batch_id IS NULL THEN NULL ELSE v_operation_row.pay_batch_id::text END,
              'candidate_scope_link_count', COALESCE(v_candidate_scope_link_count, 0),
              'allocation_link_count', COALESCE(v_allocation_link_count, 0),
              'item_link_count', COALESCE(v_item_link_count, 0),
              'latest_draft_create_operation_id', CASE WHEN v_latest_draft_create_operation_id IS NULL THEN NULL ELSE v_latest_draft_create_operation_id::text END
            )::text;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_transfer_row_count
  FROM public.pay_bank_transfers AS transfer_row
  WHERE transfer_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_transfer_scope_count
  FROM public.banking_pay_operation_transfer_scope AS transfer_scope_row
  WHERE transfer_scope_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_provider_attempt_count
  FROM public.banking_pay_operation_provider_attempts AS provider_attempt_row
  WHERE provider_attempt_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_bank_transfer_event_count
  FROM public.pay_bank_transfer_events AS transfer_event_row
  WHERE transfer_event_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_auth_request_count
  FROM public.pay_batch_auth_requests AS auth_request_row
  WHERE auth_request_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_auth_action_count
  FROM public.pay_batch_auth_actions AS auth_action_row
  JOIN public.pay_batch_auth_requests AS auth_action_request_row
    ON auth_action_request_row.id = auth_action_row.auth_request_id
  WHERE auth_action_request_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_remittance_scope_count
  FROM public.banking_pay_operation_remittance_scope AS remittance_scope_row
  WHERE remittance_scope_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_settlement_scope_count
  FROM public.banking_pay_operation_settlement_scope AS settlement_scope_row
  WHERE settlement_scope_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_correction_request_count
  FROM public.pay_payment_correction_requests AS correction_request_row
  WHERE correction_request_row.pay_batch_id = p_pay_batch_id
    AND UPPER(BTRIM(COALESCE(correction_request_row.status, ''))) NOT IN ('CANCELLED', 'CANCELED', 'FAILED', 'FAILED_FINAL');

  SELECT COUNT(*)::integer
  INTO v_committed_reservation_count
  FROM public.pay_advance_reservations AS reservation_row
  WHERE reservation_row.pay_batch_id = p_pay_batch_id
    AND (
      reservation_row.committed_at_utc IS NOT NULL
      OR reservation_row.settled_at_utc IS NOT NULL
      OR UPPER(BTRIM(COALESCE(reservation_row.status, ''))) IN ('COMMITTED', 'SETTLED', 'PAID')
    );

  v_submission_artifact_count := COALESCE(v_transfer_row_count, 0)
    + COALESCE(v_transfer_scope_count, 0)
    + COALESCE(v_provider_attempt_count, 0)
    + COALESCE(v_bank_transfer_event_count, 0)
    + COALESCE(v_auth_request_count, 0)
    + COALESCE(v_auth_action_count, 0)
    + COALESCE(v_remittance_scope_count, 0)
    + COALESCE(v_settlement_scope_count, 0)
    + COALESCE(v_correction_request_count, 0)
    + COALESCE(v_committed_reservation_count, 0);

  v_batch_submission_flag_count := 0;
  IF NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL THEN
    v_batch_submission_flag_count := v_batch_submission_flag_count + 1;
  END IF;
  IF v_batch_row.execution_committed_at_utc IS NOT NULL THEN
    v_batch_submission_flag_count := v_batch_submission_flag_count + 1;
  END IF;
  IF v_batch_row.monzo_confirmed_at_utc IS NOT NULL THEN
    v_batch_submission_flag_count := v_batch_submission_flag_count + 1;
  END IF;
  IF COALESCE(jsonb_typeof(v_batch_row.bank_csv_export_json), 'null') = 'object'
     AND v_batch_row.bank_csv_export_json <> '{}'::jsonb THEN
    v_batch_submission_flag_count := v_batch_submission_flag_count + 1;
  END IF;
  IF COALESCE(jsonb_typeof(v_batch_row.execution_intent_json), 'null') = 'object'
     AND v_batch_row.execution_intent_json <> '{}'::jsonb THEN
    v_batch_submission_flag_count := v_batch_submission_flag_count + 1;
  END IF;
  IF COALESCE(jsonb_typeof(v_batch_row.settlement_confirmation_json), 'null') = 'object'
     AND v_batch_row.settlement_confirmation_json <> '{}'::jsonb THEN
    v_batch_submission_flag_count := v_batch_submission_flag_count + 1;
  END IF;

  IF COALESCE(v_submission_artifact_count, 0) > 0 OR COALESCE(v_batch_submission_flag_count, 0) > 0 THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SUBMISSION_EVIDENCE_PRESENT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SUBMISSION_EVIDENCE_PRESENT',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'transfer_row_count', COALESCE(v_transfer_row_count, 0),
              'transfer_scope_count', COALESCE(v_transfer_scope_count, 0),
              'provider_attempt_count', COALESCE(v_provider_attempt_count, 0),
              'bank_transfer_event_count', COALESCE(v_bank_transfer_event_count, 0),
              'auth_request_count', COALESCE(v_auth_request_count, 0),
              'auth_action_count', COALESCE(v_auth_action_count, 0),
              'remittance_scope_count', COALESCE(v_remittance_scope_count, 0),
              'settlement_scope_count', COALESCE(v_settlement_scope_count, 0),
              'correction_request_count', COALESCE(v_correction_request_count, 0),
              'committed_reservation_count', COALESCE(v_committed_reservation_count, 0),
              'batch_submission_flag_count', COALESCE(v_batch_submission_flag_count, 0)
            )::text;
  END IF;

  SELECT CASE
           WHEN COUNT(*) = 0 THEN true
           ELSE COALESCE(BOOL_OR(pg_catalog.pg_get_constraintdef(constraint_row.oid) ILIKE '%CANCELLED%'), false)
         END
  INTO v_batch_status_cancelled_allowed
  FROM pg_catalog.pg_constraint AS constraint_row
  JOIN pg_catalog.pg_class AS relation_row
    ON relation_row.oid = constraint_row.conrelid
  JOIN pg_catalog.pg_namespace AS namespace_row
    ON namespace_row.oid = relation_row.relnamespace
  WHERE namespace_row.nspname = 'public'
    AND relation_row.relname = 'pay_batches'
    AND constraint_row.contype = 'c'
    AND constraint_row.conname = 'pay_batches_status_chk_v2';

  IF v_batch_status_cancelled_allowed IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_CANCELLED_STATUS_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_CANCELLED_STATUS_NOT_ALLOWED',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  SELECT CASE
           WHEN COUNT(*) = 0 THEN true
           ELSE COALESCE(BOOL_OR(pg_catalog.pg_get_constraintdef(constraint_row.oid) ILIKE '%FAILED%'), false)
         END
  INTO v_candidate_scope_failed_status_allowed
  FROM pg_catalog.pg_constraint AS constraint_row
  JOIN pg_catalog.pg_class AS relation_row
    ON relation_row.oid = constraint_row.conrelid
  JOIN pg_catalog.pg_namespace AS namespace_row
    ON namespace_row.oid = relation_row.relnamespace
  WHERE namespace_row.nspname = 'public'
    AND relation_row.relname = 'banking_pay_operation_candidate_scope'
    AND constraint_row.contype = 'c'
    AND constraint_row.conname = 'banking_pay_operation_candidate_scope_status_chk';

  IF v_candidate_scope_failed_status_allowed IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SCOPE_FAILED_STATUS_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_ABORT_FAILED_DRAFT_CREATE_PARTIAL_SCOPE_FAILED_STATUS_NOT_ALLOWED',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  SELECT CASE
           WHEN COUNT(*) = 0 THEN false
           ELSE COALESCE(BOOL_OR(pg_catalog.pg_get_constraintdef(constraint_row.oid) ILIKE '%FAILED%'), false)
         END
  INTO v_allocation_failed_status_allowed
  FROM pg_catalog.pg_constraint AS constraint_row
  JOIN pg_catalog.pg_class AS relation_row
    ON relation_row.oid = constraint_row.conrelid
  JOIN pg_catalog.pg_namespace AS namespace_row
    ON namespace_row.oid = relation_row.relnamespace
  WHERE namespace_row.nspname = 'public'
    AND relation_row.relname = 'banking_pay_operation_candidate_allocation_rows'
    AND constraint_row.contype = 'c'
    AND constraint_row.conname = 'banking_pay_operation_candidate_allocation_status_chk';

  SELECT CASE
           WHEN COUNT(*) = 0 THEN false
           ELSE COALESCE(BOOL_OR(pg_catalog.pg_get_constraintdef(constraint_row.oid) ILIKE '%RELEASED%'), false)
         END
  INTO v_reservation_released_status_allowed
  FROM pg_catalog.pg_constraint AS constraint_row
  JOIN pg_catalog.pg_class AS relation_row
    ON relation_row.oid = constraint_row.conrelid
  JOIN pg_catalog.pg_namespace AS namespace_row
    ON namespace_row.oid = relation_row.relnamespace
  WHERE namespace_row.nspname = 'public'
    AND relation_row.relname = 'pay_advance_reservations'
    AND constraint_row.contype = 'c'
    AND constraint_row.conname = 'pay_advance_reservations_status_chk';

  SELECT COUNT(*)::integer
  INTO v_candidate_count
  FROM public.pay_batch_candidates AS candidate_count_row
  WHERE candidate_count_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE COALESCE(item_count_row.is_voided, false) = false)::integer
  INTO v_item_count,
       v_active_item_count
  FROM public.pay_batch_items AS item_count_row
  JOIN public.pay_batch_candidates AS candidate_count_row
    ON candidate_count_row.id = item_count_row.pay_batch_candidate_id
  WHERE candidate_count_row.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_reservation_count
  FROM public.pay_advance_reservations AS reservation_count_row
  WHERE reservation_count_row.pay_batch_id = p_pay_batch_id;

  WITH released_reservations AS (
    UPDATE public.pay_advance_reservations AS reservation_update
    SET status = CASE
          WHEN v_reservation_released_status_allowed IS TRUE
               AND UPPER(BTRIM(COALESCE(reservation_update.status, ''))) = 'RESERVED' THEN 'RELEASED'
          ELSE reservation_update.status
        END,
        released_at_utc = COALESCE(reservation_update.released_at_utc, v_now),
        released_reason = COALESCE(
          NULLIF(BTRIM(reservation_update.released_reason), ''),
          LEFT('Failed draft creation cleanup: ' || v_reason, 500)
        ),
        updated_by_user_id = COALESCE(v_effective_actor_user_id, reservation_update.updated_by_user_id)
    WHERE reservation_update.pay_batch_id = p_pay_batch_id
      AND reservation_update.committed_at_utc IS NULL
      AND reservation_update.settled_at_utc IS NULL
      AND reservation_update.released_at_utc IS NULL
    RETURNING reservation_update.id
  )
  SELECT COUNT(*)::integer
  INTO v_reservations_released
  FROM released_reservations AS released_reservation_row;

  WITH voided_items AS (
    UPDATE public.pay_batch_items AS item_update
    SET is_voided = true,
        updated_at = v_now
    FROM public.pay_batch_candidates AS candidate_for_item
    WHERE candidate_for_item.id = item_update.pay_batch_candidate_id
      AND candidate_for_item.pay_batch_id = p_pay_batch_id
      AND COALESCE(item_update.is_voided, false) = false
    RETURNING item_update.id
  )
  SELECT COUNT(*)::integer
  INTO v_items_voided
  FROM voided_items AS voided_item_row;

  WITH failed_scopes AS (
    UPDATE public.banking_pay_operation_candidate_scope AS scope_update
    SET status = 'FAILED',
        pay_batch_id = COALESCE(scope_update.pay_batch_id, p_pay_batch_id),
        effective_summary_fragment_json = jsonb_strip_nulls(
          COALESCE(scope_update.effective_summary_fragment_json, '{}'::jsonb)
          || jsonb_build_object(
            'draft_creation_failed', true,
            'draft_creation_failed_partial', true,
            'draft_creation_failed_operation_id', p_operation_id::text,
            'draft_creation_failed_pay_batch_id', p_pay_batch_id::text,
            'draft_creation_failed_phase', v_failure_phase,
            'draft_creation_failed_code', v_failure_code,
            'draft_creation_failed_at_utc', v_now::text
          )
        ),
        candidate_totals_json = jsonb_strip_nulls(
          COALESCE(scope_update.candidate_totals_json, '{}'::jsonb)
          || jsonb_build_object(
            'draft_creation_failed', true,
            'draft_creation_failed_partial', true,
            'batch_action_blocked', true,
            'normal_draft_actions_blocked', true,
            'failed_partial_cleanup_mode', 'FAILED_DRAFT_CREATE_PARTIAL_ABORT'
          )
        ),
        updated_at_utc = v_now
    WHERE scope_update.operation_id = p_operation_id
      AND (
        scope_update.pay_batch_id = p_pay_batch_id
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_candidate_allocation_rows AS scope_allocation_row
          WHERE scope_allocation_row.operation_id = p_operation_id
            AND scope_allocation_row.candidate_scope_id = scope_update.id
            AND scope_allocation_row.pay_batch_id = p_pay_batch_id
        )
      )
    RETURNING scope_update.id
  )
  SELECT COUNT(*)::integer
  INTO v_candidate_scopes_failed
  FROM failed_scopes AS failed_scope_row;

  WITH updated_allocations AS (
    UPDATE public.banking_pay_operation_candidate_allocation_rows AS allocation_update
    SET status = CASE
          WHEN v_allocation_failed_status_allowed IS TRUE THEN 'FAILED'
          ELSE allocation_update.status
        END,
        allocation_basis_json = jsonb_strip_nulls(
          COALESCE(allocation_update.allocation_basis_json, '{}'::jsonb)
          || jsonb_build_object(
            'draft_creation_failed', true,
            'draft_creation_failed_partial', true,
            'draft_creation_failed_operation_id', p_operation_id::text,
            'draft_creation_failed_pay_batch_id', p_pay_batch_id::text,
            'draft_creation_failed_phase', v_failure_phase,
            'draft_creation_failed_code', v_failure_code,
            'failed_partial_cleanup_mode', 'FAILED_DRAFT_CREATE_PARTIAL_ABORT',
            'allocation_status_failed_written', v_allocation_failed_status_allowed IS TRUE,
            'draft_creation_failed_at_utc', v_now::text
          )
        ),
        updated_at_utc = v_now
    WHERE allocation_update.operation_id = p_operation_id
      AND (
        allocation_update.pay_batch_id = p_pay_batch_id
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_candidate_scope AS allocation_scope_row
          WHERE allocation_scope_row.id = allocation_update.candidate_scope_id
            AND allocation_scope_row.operation_id = p_operation_id
            AND allocation_scope_row.pay_batch_id = p_pay_batch_id
        )
      )
    RETURNING allocation_update.id,
              allocation_update.status
  )
  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(updated_allocation_row.status, ''))) = 'FAILED')::integer
  INTO v_allocation_rows_updated,
       v_allocation_rows_failed
  FROM updated_allocations AS updated_allocation_row;

  UPDATE public.pay_batches AS batch_update
  SET status = 'CANCELLED',
      cancelled_at_utc = COALESCE(batch_update.cancelled_at_utc, v_now),
      cancelled_by_user_id = CASE
        WHEN batch_update.cancelled_by_user_id IS NOT NULL THEN batch_update.cancelled_by_user_id
        ELSE v_effective_actor_user_id
      END,
      cancel_reason = COALESCE(NULLIF(BTRIM(batch_update.cancel_reason), ''), v_reason),
      schedule_kind = NULL,
      scheduled_at_utc = NULL,
      scheduled_by_user_id = NULL,
      funding_account_ref = NULL,
      funds_warning_hours_json = NULL,
      execution_commit_state = CASE
        WHEN NULLIF(BTRIM(COALESCE(batch_update.execution_commit_state, '')), '') IS NULL THEN 'NOT_SUBMITTED'
        ELSE batch_update.execution_commit_state
      END
  WHERE batch_update.id = p_pay_batch_id
  RETURNING batch_update.*
  INTO v_batch_row_after;

  v_batch_status_after := UPPER(BTRIM(COALESCE(v_batch_row_after.status, '')));

  v_cleanup_counts_json := jsonb_build_object(
    'candidate_count', COALESCE(v_candidate_count, 0),
    'item_count', COALESCE(v_item_count, 0),
    'active_item_count_before', COALESCE(v_active_item_count, 0),
    'item_rows_voided', COALESCE(v_items_voided, 0),
    'reservation_count', COALESCE(v_reservation_count, 0),
    'reservations_released', COALESCE(v_reservations_released, 0),
    'candidate_scopes_failed', COALESCE(v_candidate_scopes_failed, 0),
    'allocation_rows_updated', COALESCE(v_allocation_rows_updated, 0),
    'allocation_rows_failed', COALESCE(v_allocation_rows_failed, 0)
  );

  v_cleanup_result_json := jsonb_strip_nulls(
    jsonb_build_object(
      'ok', true,
      'cleanup_mode', 'FAILED_DRAFT_CREATE_PARTIAL_ABORT',
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'status_before', v_batch_status_before,
      'status_after', v_batch_status_after,
      'execution_commit_state_before', NULLIF(v_execution_commit_state_before, ''),
      'execution_commit_state_after', v_batch_row_after.execution_commit_state
    )
    || jsonb_build_object(
      'item_count', COALESCE(v_item_count, 0),
      'candidate_count', COALESCE(v_candidate_count, 0),
      'reservations_released', COALESCE(v_reservations_released, 0),
      'item_rows_voided', COALESCE(v_items_voided, 0),
      'candidate_scopes_failed', COALESCE(v_candidate_scopes_failed, 0),
      'allocation_rows_updated', COALESCE(v_allocation_rows_updated, 0),
      'allocation_rows_failed', COALESCE(v_allocation_rows_failed, 0)
    )
    || jsonb_build_object(
      'draft_creation_failed', true,
      'draft_creation_failed_partial', true,
      'batch_action_blocked', true,
      'normal_draft_actions_blocked', true,
      'failure_code', v_failure_code,
      'failure_phase', v_failure_phase,
      'reason', v_reason,
      'policy_x_checked', true
    )
    || jsonb_build_object(
      'source_workbench_session_id', v_operation_row.workbench_session_id::text,
      'source_snapshot_run_id', v_batch_snapshot_run_id_text,
      'source_session_version', v_batch_session_version_text,
      'expected_source_session_version', v_expected_session_version_text,
      'session_version_direct_link_exception_used', COALESCE(v_session_version_direct_link_exception_used, false),
      'operation_direct_batch_link', COALESCE(v_operation_direct_batch_link, false),
      'candidate_scope_link_count', COALESCE(v_candidate_scope_link_count, 0),
      'allocation_link_count', COALESCE(v_allocation_link_count, 0),
      'item_link_count', COALESCE(v_item_link_count, 0),
      'allocation_status_failed_allowed', v_allocation_failed_status_allowed,
      'reservation_status_released_allowed', v_reservation_released_status_allowed,
      'cleaned_at_utc', v_now::text,
      'counts', v_cleanup_counts_json
    )
  );

  v_operation_progress_patch_json := jsonb_strip_nulls(
    jsonb_build_object(
      'draft_creation_failed_partial', true,
      'failed_partial_cleanup_status', 'ABORTED',
      'failed_partial_cleanup_mode', 'FAILED_DRAFT_CREATE_PARTIAL_ABORT',
      'failed_partial_cleanup_pay_batch_id', p_pay_batch_id::text,
      'failed_partial_cleanup_at_utc', v_now::text,
      'batch_action_blocked', true,
      'normal_draft_actions_blocked', true,
      'created_pay_batch_ids', jsonb_build_array(p_pay_batch_id::text)
    )
    || jsonb_build_object(
      'failed_partial_cleanup_result', v_cleanup_result_json,
      'failed_partial_cleanup_summary_refreshed', true
    )
  );

  v_operation_error_patch_json := jsonb_strip_nulls(
    jsonb_build_object(
      'draft_creation_failed_partial', true,
      'failed_partial_cleanup_status', 'ABORTED',
      'failed_partial_cleanup_mode', 'FAILED_DRAFT_CREATE_PARTIAL_ABORT',
      'failed_partial_cleanup_pay_batch_id', p_pay_batch_id::text,
      'batch_action_blocked', true,
      'normal_draft_actions_blocked', true,
      'cleanup_failure_code', v_failure_code,
      'cleanup_failure_phase', v_failure_phase
    )
  );

  UPDATE public.banking_pay_operations AS operation_update
  SET progress_json = jsonb_strip_nulls(
        COALESCE(operation_update.progress_json, '{}'::jsonb)
        || v_operation_progress_patch_json
      ),
      error_json = jsonb_strip_nulls(
        COALESCE(operation_update.error_json, '{}'::jsonb)
        || v_operation_error_patch_json
      ),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  PERFORM public.pay_batch_display_summary_refresh(p_pay_batch_id);

  v_signal_scope_json := jsonb_strip_nulls(
    jsonb_build_object(
      'operation_id', p_operation_id::text,
      'operation_type', 'DRAFT_CREATE',
      'pay_batch_id', p_pay_batch_id::text,
      'cleanup_mode', 'FAILED_DRAFT_CREATE_PARTIAL_ABORT',
      'draft_creation_failed', true,
      'draft_creation_failed_partial', true,
      'batch_action_blocked', true,
      'normal_draft_actions_blocked', true
    )
    || jsonb_build_object(
      'failure_phase', v_failure_phase,
      'failure_code', v_failure_code,
      'status_before', v_batch_status_before,
      'status_after', v_batch_status_after,
      'execution_commit_state_before', NULLIF(v_execution_commit_state_before, ''),
      'execution_commit_state_after', v_batch_row_after.execution_commit_state,
      'counts', v_cleanup_counts_json,
      'cleaned_at_utc', v_now::text
    )
  );

  SELECT public.banking_pay_batch_signal_touch(
    p_pay_batch_id := p_pay_batch_id,
    p_change_reason := 'DRAFT_CREATE_FAILED_PARTIAL_ABORTED',
    p_change_source := 'pay_batch_abort_failed_draft_create_partial',
    p_change_scope_json := v_signal_scope_json,
    p_touch_payment_status := true,
    p_touch_correction_progress := true,
    p_touch_alerts := true,
    p_touch_overview := true
  )
  INTO v_signal_result_json;

  UPDATE public.banking_pay_operations AS operation_update
  SET progress_json = jsonb_strip_nulls(
        COALESCE(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'failed_partial_cleanup_signal_version', v_signal_result_json->>'version'
        )
      ),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN v_cleanup_result_json
    || jsonb_build_object(
      'signal', COALESCE(v_signal_result_json, '{}'::jsonb),
      'display_summary_refreshed', true
    );
END;
$function$;



CREATE OR REPLACE FUNCTION public._pay_timesheet_rotation_scope(p_timesheet_ids uuid[])
 RETURNS TABLE(requested_timesheet_id uuid, booking_id text, canonical_timesheet_id uuid, family_timesheet_id uuid, family_is_current boolean, family_version integer, requested_is_canonical boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
WITH input_timesheets AS (
  SELECT DISTINCT
    input_timesheet_values.timesheet_id_value AS requested_timesheet_id
  FROM unnest(COALESCE(p_timesheet_ids, ARRAY[]::uuid[])) AS input_timesheet_values(timesheet_id_value)
  WHERE input_timesheet_values.timesheet_id_value IS NOT NULL
),
requested_timesheets AS (
  SELECT
    input_timesheets.requested_timesheet_id AS requested_timesheet_id,
    public.timesheets.timesheet_id AS matched_timesheet_id,
    public.timesheets.booking_id AS matched_booking_id
  FROM input_timesheets
  LEFT JOIN public.timesheets
    ON public.timesheets.timesheet_id = input_timesheets.requested_timesheet_id
),
requested_bookings AS (
  SELECT DISTINCT
    requested_timesheets.matched_booking_id AS booking_id
  FROM requested_timesheets
  WHERE requested_timesheets.matched_timesheet_id IS NOT NULL
    AND requested_timesheets.matched_booking_id IS NOT NULL
    AND BTRIM(requested_timesheets.matched_booking_id) <> ''
),
canonical_timesheets AS (
  SELECT DISTINCT ON (current_timesheets.booking_id)
    current_timesheets.booking_id AS booking_id,
    current_timesheets.timesheet_id AS canonical_timesheet_id
  FROM public.timesheets AS current_timesheets
  JOIN requested_bookings
    ON requested_bookings.booking_id = current_timesheets.booking_id
  WHERE current_timesheets.is_current = true
  ORDER BY
    current_timesheets.booking_id,
    current_timesheets.version DESC,
    current_timesheets.updated_at DESC,
    current_timesheets.created_at DESC,
    current_timesheets.timesheet_id
),
family_timesheets AS (
  SELECT DISTINCT
    family_rows.booking_id AS booking_id,
    family_rows.timesheet_id AS family_timesheet_id,
    family_rows.is_current AS family_is_current,
    family_rows.version AS family_version
  FROM public.timesheets AS family_rows
  JOIN requested_bookings
    ON requested_bookings.booking_id = family_rows.booking_id
),
resolved_scope_rows AS (
  SELECT
    requested_timesheets.requested_timesheet_id AS requested_timesheet_id,
    requested_timesheets.matched_booking_id AS booking_id,
    canonical_timesheets.canonical_timesheet_id AS canonical_timesheet_id,
    family_timesheets.family_timesheet_id AS family_timesheet_id,
    family_timesheets.family_is_current AS family_is_current,
    family_timesheets.family_version AS family_version,
    COALESCE(requested_timesheets.requested_timesheet_id = canonical_timesheets.canonical_timesheet_id, false) AS requested_is_canonical
  FROM requested_timesheets
  JOIN family_timesheets
    ON family_timesheets.booking_id = requested_timesheets.matched_booking_id
  LEFT JOIN canonical_timesheets
    ON canonical_timesheets.booking_id = requested_timesheets.matched_booking_id
  WHERE requested_timesheets.matched_timesheet_id IS NOT NULL
),
defensive_unresolved_rows AS (
  SELECT
    requested_timesheets.requested_timesheet_id AS requested_timesheet_id,
    NULL::text AS booking_id,
    requested_timesheets.requested_timesheet_id AS canonical_timesheet_id,
    requested_timesheets.requested_timesheet_id AS family_timesheet_id,
    NULL::boolean AS family_is_current,
    NULL::integer AS family_version,
    false AS requested_is_canonical
  FROM requested_timesheets
  WHERE requested_timesheets.matched_timesheet_id IS NULL
),
rotation_scope_output AS (
  SELECT
    resolved_scope_rows.requested_timesheet_id AS requested_timesheet_id,
    resolved_scope_rows.booking_id AS booking_id,
    resolved_scope_rows.canonical_timesheet_id AS canonical_timesheet_id,
    resolved_scope_rows.family_timesheet_id AS family_timesheet_id,
    resolved_scope_rows.family_is_current AS family_is_current,
    resolved_scope_rows.family_version AS family_version,
    resolved_scope_rows.requested_is_canonical AS requested_is_canonical
  FROM resolved_scope_rows

  UNION ALL

  SELECT
    defensive_unresolved_rows.requested_timesheet_id AS requested_timesheet_id,
    defensive_unresolved_rows.booking_id AS booking_id,
    defensive_unresolved_rows.canonical_timesheet_id AS canonical_timesheet_id,
    defensive_unresolved_rows.family_timesheet_id AS family_timesheet_id,
    defensive_unresolved_rows.family_is_current AS family_is_current,
    defensive_unresolved_rows.family_version AS family_version,
    defensive_unresolved_rows.requested_is_canonical AS requested_is_canonical
  FROM defensive_unresolved_rows
)
SELECT
  rotation_scope_output.requested_timesheet_id,
  rotation_scope_output.booking_id,
  rotation_scope_output.canonical_timesheet_id,
  rotation_scope_output.family_timesheet_id,
  rotation_scope_output.family_is_current,
  rotation_scope_output.family_version,
  rotation_scope_output.requested_is_canonical
FROM rotation_scope_output
ORDER BY
  rotation_scope_output.requested_timesheet_id,
  rotation_scope_output.booking_id NULLS LAST,
  rotation_scope_output.family_is_current DESC NULLS LAST,
  rotation_scope_output.family_version DESC NULLS LAST,
  rotation_scope_output.family_timesheet_id;
$function$;
